window.QBANK={"14":[{"y":2016,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2016_22-41-1","t":"출생의 신고는 출생 후 1개월 이내에 하여야 한다.","ox":"O","m":"①","c":"A","tp":"출생신고"},{"y":2016,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2016_22-41-2","t":"신고기간은 신고사건 발생일부터 기산한다.","ox":"O","m":"②","c":"A","tp":"출생신고"},{"y":2016,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2016_22-41-3","t":"부가 혼인 전의 출생자를 혼인 후에 혼인 중의 출생자로 출생신고를 할 때에는 혼인 외의 출생자를 혼인 중의 출생자로 출생신고한 것이므로 이를 수리할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2016_22-41-4","t":"중혼은 취소원인이나 그 취소의 효력은 이전으로 소급하지 아니하므로, 중혼으로 취소할 수 있는 혼인당사자 사이에서의 출생한 자녀는 혼인 중의 자로 출생신고를 하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2016_22-41-5","t":"혼인 중 출생자의 출생의 신고는 부 또는 모가 하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"출생신고"},{"y":2016,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2016_22-45-1","t":"한국인 모와 외국인 부 사이에 출생한 혼인 외의 자는 한국의 국적을 취득(국적법 제2조 제1항 제1호)한 자녀이므로 혼인 외의 자에 대한 출생신고의무자인 생모의 출생신고에 의하여 그 자녀의 가족관계등록부를 작성한다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2016_22-45-2","t":"외국인 부는 인지의 준거법이 될 수 있는 사람의 출생 당시 모의 본국법(한국법), 자녀의 출생 당시 부의 본국법, 현재 자녀의 상거소지법, 인지 당시 인지자(부)의 본국법 중 하나를 해당 인지행위의 준거법으로 선택하여 그 나라의 방식으로 인지를 할 것이나(국제사법 제17조 제1항, 제41조, 제44조), 인지행위지법의 방식에 의하여 인지를 할 수도 있다.","ox":"O","m":"②","c":"A","tp":"한국인 모와 외국인 부 사이에 출생한 혼인 외의 자"},{"y":2016,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2016_22-45-3","t":"외국인 부가 인지행위지법 또는 인지의 준거법인 외국법이 정한 방식에 따라 인지절차를 마친 때에는 그 나라의 권한 있는 기관이 발행한 인지에 관한 증서와 번역문을 시(구)ㆍ읍ㆍ면에 제출하여야 한다.","ox":"O","m":"③","c":"A","tp":"한국인 모와 외국인 부 사이에 출생한 혼인 외의 자"},{"y":2016,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2016_22-45-4","t":"혼인 외의 자의 생모와 외국인 부가 후에 혼인을 하더라도 그것만으로는 외국인 부와 혼인 외의 자 사이에 친자관계가 발생하는 것은 아니다.","ox":"O","m":"④","c":"A","tp":"한국인 모와 외국인 부 사이에 출생한 혼인 외의 자"},{"y":2016,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2016_22-45-5","t":"외국인인 부는 가족관계의 등록 등에 관한 법률 제57조에 따른 친생자녀로서 출생신고를 할 수 없다.","ox":"X","m":"⑤","c":"A","tp":"한국인 모와 외국인 부 사이에 출생한 혼인 외의 자"},{"y":2016,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2016_22-46-1","t":"부가 혼인 외의 자녀에 대하여 친생자출생의 신고를 한 때에는 그 신고는 인지의 효력이 있다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2016_22-46-2","t":"모의 성명ㆍ등록기준지 및 주민등록번호를 알 수 없는 경우에는 부의 등록기준지 또는 주소지를 관할하는 가정법원의 확인을 받아 가족관계의 등록 등에 관한 법률 제57조 제1항에 따른 신고를 할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2016_22-46-3","t":"가정법원은 가족관계의 등록 등에 관한 법률 제57조 제2항에 따른 확인을 위하여 필요한 사항을 직권으로 조사할 수 있고, 지방자치단체, 국가경찰관서 및 행정기관이나 그 밖의 단체 또는 개인에게 필요한 사항을 보고하게 하거나 자료의 제출을 요구할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2016_22-46-4","t":"가족관계의 등록 등에 관한 법률 제57조 제2항에 따른 가정법원 확인의 처리절차에 관하여는 비송사건절차법을 준용한다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2016_22-46-5","t":"출생자가 제3자로부터 민법 제844조의 친생자 추정을 받고 있음이 밝혀진 경우에는 신고의무자가 3개월 이내에 출생의 신고를 하고 등록부의 정정을 신청하여야 한다(이 경우 시ㆍ읍ㆍ면의 장이 확인하여야 한다).","ox":"X","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2016_22-47-1","t":"한국인과 외국인 사이의 혼인이 외국에서 거행되는 경우 그 혼인거행지의 법이 정하는 방식에 따른 혼인절차를 마친 경우에는 별도로 우리나라의 법에 따른 혼인신고를 하지 않더라도 혼인의 성립에 영향이 없다.","ox":"O","m":"①","c":"A","tp":"국제혼인"},{"y":2016,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2016_22-47-2","t":"국제사법상 혼인의 방식은 혼인거행지법 또는 당사자 일방의 본국법에 의하므로 대한민국에서 한국인과 외국인 사이에 외국인 당사자의 본국법이 정한 방식으로 성립한 혼인은 우리나라의 법률상 유효한 혼인으로서의 효력이 있다.","ox":"X","m":"②","c":"A","tp":"국제혼인"},{"y":2016,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2016_22-47-3","t":"외국에서 외국인 남자와 한국인 여자가 그 외국법이 정한 방식으로 혼인한 경우 혼인을 한 외국방식에 의하여 혼인이 성립되었음을 증명하는 서면을 접수한 한국인 여자의 등록기준지 시(구)ㆍ읍ㆍ면의 장은 한국인 여자의 가족관계등록부 일반등록사항란에 혼인사유를 기록하고 바로 국적상실을 원인으로 가족관계등록부를 폐쇄하여야 한다.","ox":"X","m":"③","c":"A","tp":"국제혼인"},{"y":2016,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2016_22-47-4","t":"한국인이 외국에서 그 나라 방식에 의하여 혼인을 하는 경우 한국인의 해당 신분행위 성립요건구비증명서는 등록기준지 시(구)ㆍ읍ㆍ면의 장 또는 거주지 관할 재외공관의 장이 발급하며, 등록기준지 관할 지방법원장은 발급할 수 없다.","ox":"X","m":"④","c":"A","tp":"국제혼인"},{"y":2016,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2016_22-47-5","t":"한국에 머물고 있는 중국 남자와 프랑스 여자가 중국 풍습에 따른 혼례식을 마치고 주한 중화인민공화국 대사관에 그 혼인신고를 하면 거행지법인 우리나라 법에 의한 혼인이 유효하게 성립한 것으로 볼 수 있다.","ox":"X","m":"⑤","c":"A","tp":"국제혼인"},{"y":2016,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2016_22-50","t":"가족관계등록신고의 심사와 수리 또는 불수리에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"가족관계등록신고의 심사와 수리 또는 불수리에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["미성년자의 부모가 이혼하기로 협의하면서 친권자 지정에 관한 협의를 한 경우에도 이혼신고가 수리되기 전에는 친권자 지정신고를 수리할 수 없다.","불수리한 신고서류는 불수리신고서류편철장에 편철하되, 신고인의 청구에 따라 신고서 및 첨부서류를 되돌려 줄 수 있다.","가족관계등록신고에 대한 심사는 신고인이 제출하는 법정의 첨부서류만에 의하여 법정의 요건을 구비하고 있는지, 절차에 부합하는지의 여부를 형식적으로만 심사하는 것이고 그 신고사항의 실체적 진실과의 부합여부를 탐지하여 심사하여야 하는 것은 아니다.","신고서류를 접수한 때에는 원칙적으로 지체 없이 심사하여 접수한 당일에 수리여부를 결정하여야 한다.","혼인신고서에 첨부한 처의 등록사항별 증명서에 본의 기록이 없어도 신고서에 본을 기재한 때에는 이를 수리하여야 한다. 2016년 6월 18일 시행 제22회 법무사 제1차 시험"],"a":2}},{"y":2017,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2017_23-42-1","t":"신고서는 한글과 아라비아숫자로 기재하여야 한다. 다만, 사건본인의 성명은 한자로 표기할 수 없는 경우를 제외하고는 한자를 병기하여야 하고, 사건본인의 본은 한자로 표기할 수 없는 경우를 제외하고는 한자로 기재하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2017_23-42-2","t":"출생자의 이름에 사용된 한자 중 가족관계의 등록 등에 관한 법률 및 동 규칙이 정하는 인명용 한자의 범위에 속하지 않는 한자가 포함된 경우에는 해당신고는 수리할 수 없다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2017_23-42-3","t":"시ㆍ읍ㆍ면ㆍ동의 장 또는 재외공관의 장은 신고서류를 접수하는 경우에 출석한 신고인 또는 제출인의 신분증명서에 의하여 반드시 그 신분을 확인하여야 하고, 신고인 또는 제출인이 가족관계의 등록 등에 관한 법률 제23조 제2항에 따라 불출석 신고사건 본인의 신분증명서를 제시한 때에는 그 신분을 확인한 후 신고서류의 뒤에 그 사본을 첨부하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2017_23-42-4","t":"신고인, 증인, 동의자 등은 신고서에 서명하거나 기명날인할 수 있고, 서명 또는 기명날인을 할 수 없을 때에는 무인을 할 수 있다. 이 경우 담당공무원은 본인의 무인임을 증명한다는 문구를 기재하고 기명날인하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2017_23-42-5","t":"등록창설허가의 재판을 얻은 사람이 등록창설의 신고를 하지 아니한 때에는 배우자 또는 직계혈족이 할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2017_23-47-1","t":"동장이 접수하여 수리한 신고서를 동이 속하는 시(구)의 장에게 송부할 때에는 ‘가족관계등록사무의 문서 양식에 관한 예규’ 별지 제33호 서식의 발송인을 찍는다.","ox":"O","m":"①","c":"A","tp":"가족관계의 등록 등"},{"y":2017,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2017_23-47-2","t":"발송명의는 ‘○○시장 또는 ○○구청장 대행자 ○○동장’으로 표시하고 동장 직인을 찍어 송부한다.","ox":"O","m":"②","c":"A","tp":"가족관계의 등록 등"},{"y":2017,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2017_23-47-3","t":"신고서가 부적법하여 가족관계의 등록 등에 관한 법률 제43조에 따라 통지하는 경우에는 ‘가족관계등록사무의 문서 양식에 관한 예규’ 별지 제21호 서식에 의하되, ‘○○시장 또는 ○○구청장 대행자 ○○동장’ 이름으로 하고, 불수리한 신고서는 불수리신고서류편철장에 편철하여 보존한다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2017_23-47-4","t":"동장으로부터 신고서를 송부 받은 소속 시(구)의 장은 그 신고서를 다시 접수하되, 접수장의 접수연월일란에는 신고서를 송부 받은 날을 기록하고 수리사항란에는 동으로부터 송부 받은 일자를 소속 시(구)에서 수리한 일자로 기록한다.","ox":"X","m":"④","c":"A","tp":"가족관계의 등록 등"},{"y":2017,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2017_23-47-5","t":"동장으로부터 신고서를 송부 받은 소속 시(구)의 장은 신고일은 해당 동에서 출생ㆍ사망신고서를 접수한 날을, 송부일은 소속 시(구)에서 다시 접수한 날을 가족관계등록부에 각 기록하되, 송부자는 동장이 송부한 것으로 한다.","ox":"O","m":"⑤","c":"A","tp":"가족관계의 등록 등"},{"y":2017,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2017_23-48-1","t":"혼인의 실질적 성립요건은 각 당사자에 관하여 그 본국법에 의하나 근친혼과 같은 혼인장애사유는 각 당사자에게 누적적으로 적용된다.","ox":"O","m":"①","c":"A","tp":"국제신분행위"},{"y":2017,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2017_23-48-2","t":"혼인 중의 친자관계의 성립은 자의 출생 당시 부부중 일방의 본국법에 의한다.","ox":"O","m":"②","c":"A","tp":"국제신분행위"},{"y":2017,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2017_23-48-3","t":"친권자를 정하는 문제는 부모와 자의 본국법이 모두 동일한 경우에는 그 법에 의하고, 그 외의 경우에는 자의 본국법에 의한다.","ox":"X","m":"③","c":"A","tp":"국제신분행위"},{"y":2017,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2017_23-48-4","t":"이혼의 허용여부 및 효력은 혼인의 일반적 효력의 준거법에 따르되, 부부중 일방이 대한민국에 상거소가 있는 대한민국 국민인 경우에는 이혼은 대한민국 법에 의한다.","ox":"O","m":"④","c":"A","tp":"국제신분행위"},{"y":2017,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2017_23-48-5","t":"입양 및 파양은 입양 당시 양친의 본국법에 의한다.","ox":"O","m":"⑤","c":"A","tp":"국제신분행위"},{"y":2017,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2017_23-49-1","t":"미성년후견 개시의 신고는 미성년후견인이 그 취임일부터 1개월 이내에 하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2017_23-49-2","t":"민법 제781조 제4항에 따라 부모를 알 수 없는 자는 가정법원의 성과 본 창설 허가서의 등본을 받은 날부터 1개월 이내에 그 사실을 신고하여야 한다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2017_23-49-3","t":"민법 제908조의2에 따라 친양자를 입양하고자 하는 사람은 친양자 입양재판의 확정일부터 1개월 이내에 재판서의 등본 및 확정증명서를 첨부하여 그 사실을 신고하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2017_23-49-4","t":"실종선고의 신고는 그 선고를 청구한 사람이 재판확정일부터 1개월 이내에 재판서의 등본 및 확정증명서를 첨부하여 그 사실을 신고하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2017_23-49-5","t":"개명하고자 하는 사람은 주소지를 관할하는 가정법원의 허가를 받고 그 허가서의 등본을 받은 날부터 1개월 이내에 신고를 하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2018_24-42-1","t":"이혼하는 부부에게 포태 중인 자가 있는 경우 시(구)·읍·면의 장은 친권자지정신고를 협의이혼신고 시 함께 수리하여야 한다.","ox":"X","m":"①","c":"A","tp":"협의이혼 의사확인 절차"},{"y":2018,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2018_24-42-2","t":"협의이혼의사를 철회한 후 그 철회의사를 철회하는 경우 이혼신고를 수리할 수 있다.","ox":"X","m":"②","c":"A","tp":"협의이혼 의사확인 절차"},{"y":2018,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2018_24-42-3","t":"가정법원의 확인서가 첨부된 협의이혼신고서는 부부 중 한쪽이 제출할 수 있다.","ox":"O","m":"③","c":"A","tp":"협의이혼 의사확인 절차"},{"y":2018,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2018_24-42-4","t":"협의이혼 의사확인의 신청은 당사자인 부(夫) 또는 처(妻)나 대리인이 할 수 있다.","ox":"X","m":"④","c":"A","tp":"협의이혼 의사확인 절차"},{"y":2018,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2018_24-42-5","t":"협의상 이혼을 하고자 하는 사람은 등록기준지 또는 주소지를 관할하는 가정법원의 확인을 받아 신고하여야 한다. 다만, 국내에 거주하지 아니하는 경우에 그 확인은 재외국민 가족관계등록사무소의 관할로 한다.","ox":"X","m":"⑤","c":"A","tp":"협의이혼 의사확인 절차"},{"y":2018,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2018_24-43","t":"신고기간에 관한 다음 설명 중 가장 옳은 것은?","c":"A","mc":{"s":"신고기간에 관한 다음 설명 중 가장 옳은 것은?","d":"","o":["시(구)․읍․면의 장은 신고기간이 경과한 후의 신고라도 수리하여야 하므로, 가정법원의 협의이혼의사 확인서 등본을 교부 또는 송달받은 날로부터 3개월 이후에 하는 협의이혼신고도 수리하여야 한다.","신고인의 생존 중에 우송한 신고서가 신고인이 사망한 후 시(구)․읍․면의 장에게 도달한 경우에는 수리하여서는 아니된다.","재판의 확정일부터 기간을 기산하여야 할 경우에 재판이 송달 또는 교부 전에 확정된 때에는 그 송달 또는 교부된 날부터 기산한다.","재외국민이 그 나라의 방식에 따라 신고사건에 관한 증서를 작성한 경우에는 6개월 이내에 그 지역을 관할하는 재외공관의 장에게 그 증서의 등본을 제출하여야 한다.","사망신고는 신고의무자가 사망 사실을 알았는지를 불문하고 사건본인이 사망한 날로부터 1개월 이내에 하여야 한다. 23-22"],"a":3}},{"y":2018,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2018_24-44-1","t":"종전 일반입양이 된 상태에서 친양자 입양이 이루어지고 친양자 입양이 파양된 경우에 친양자 입양 전의 양부모와 친양자 입양의 양부모가 동일인인 경우에는 친생부모와의 친족관계만을 부활기록하고 일반입양관계는 부활기록하지 아니한다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2018_24-44-2","t":"사망을 원인으로 가족관계등록부가 폐쇄된 사람의 자녀가 친양자 입양되었을 경우에는, 그 폐쇄등록부에 친양자 입양으로 자녀가 말소된 사유를 기록하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2018_24-44-3","t":"甲남이 乙녀를 친양자 입양하였으나 甲남과 乙녀 간 친양자 파양 없이 丙남이 乙녀에 대하여 새로이 친양자 입양을 허가하는 재판을 받아 확정된 후 해당 친양자 입양신고를 하여 그 신고가 수리된 경우, 친양자 乙녀의 가족관계증명서상 부로 새로운 양부 丙남만 기재되어야 하고 종전 양부 甲남은 말소되어야 한다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2018_24-44-4","t":"일반입양된 양자가 친양자로 입양이 되는 경우에 친양자의 가족관계등록부는 재작성하여야 하고, 재작성시 일반입양에 관한 기록을 이기하여야 한다.","ox":"X","m":"④","c":"A","tp":"친양자 입양"},{"y":2018,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2018_24-44-5","t":"친양자 입양신고가 있는 경우 친양자 입양을 한 양부모의 가족관계증명서에는 친양자가 자녀로, 친양자입양관계증명서에는 친양자로 현출되도록 하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2018_24-46","t":"다음에 열거한 신고 중 가족관계의 등록 등에 관한 법률(이하 ‘법’이라 한다) 제23조의2에 따라 전산정보처리조직을 이용하여 전자문서를 이용한 신고로 할 수 있는 것은 모두 몇 건인가?","c":"A","mc":{"s":"다음에 열거한 신고 중 가족관계의 등록 등에 관한 법률(이하 ‘법’이라 한다) 제23조의2에 따라 전산정보처리조직을 이용하여 전자문서를 이용한 신고로 할 수 있는 것은 모두 몇 건인가?","d":"ㄱ.법 제101조에 따른 가족관계등록 창설 신고\nㄴ.법 제99조에 따른 개명 신고\nㄷ.법 제44조 제4항 본문 및 제46조 제1항, 제2항에 따른 부 또는 모의 출생신고\nㄹ.법 제96조에 따른 국적취득자의 성과 본의 창설 신고","o":["없음","1건","2건","3건","전부"],"a":5}},{"y":2018,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2018_24-47-1","t":"신고의무자 또는 신고적격자가 아닌 사람이 신고한 경우 그 사망신고를 수리할 수 없으나 사망신고서에 사망진단서 등 사망의 사실을 증명하는 서면이 첨부되어 있는 때에는 문서건명부에 접수하고 시(구)·읍·면의 장이 감독법원의 허가를 받아 직권으로 기록한다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2018_24-47-2","t":"재외공관으로부터 사망자에 대한 사망신고 및 진단서가 송부된 경우 그 사망신고 및 진단서에 유명(幼名)을 기재하여 등록부와 일치되지 않은 때에도 사건본인임을 인식할 수 있는 때에는 수리하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2018_24-47-3","t":"사망신고는 사망사실을 증명할 만한 서면으로 인우인 2명 이상의 증명서를 첨부하여 할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2018_24-47-4","t":"출생신고가 되지 아니한 사람에 대하여 재외공관에서 사망신고를 수리하여 재외국민 가족관계등록사무소 소속 가족관계등록관에게 송부한 때에는 이를 특종신고서류편철장에 편철한 다음 출생신고의무자에게 출생신고를 하도록 최고하여 그에 따른 출생신고가 있는 때에는 사망자의 가족관계등록부를 작성한 후 출생 및 사망사유를 모두 기록하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2018_24-47-5","t":"가족관계등록부에 기록된 외국인인 가족이 외국에서 사망한 경우 이해관계인은 등록부의 등록기준지 시(구)·읍·면의 장에게 사망사실을 증명하는 서면을 제출하여 직권기록을 신청하여야 한다.","ox":"X","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2018_24-48","t":"혼인에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"혼인에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["혼인당사자의 성과 그 부모의 성이 다른 신고는 등록부에 착오 있음이 명확할지라도 당사자가 스스로 정정하지 아니하는 한, 그 혼인신고서를 수리하고 등록부에 기록해야 한다.","혼인신고는 원칙적으로 양 당사자가 생존한 경우에 할 수 있으므로 사실혼관계에 있던 자가 사망한 후에 사실상혼인관계존재확인의 판결이 확정된 경우에는 그 판결에 기한 혼인신고는 할 수 없다.","가호적 취적당시 법률상 부부 아닌 자가 법률상 부부인양 취적신고를 하여 그 가호적이 신고가 되고 1963. 1. 1.부터 그 가호적을 종전 호적법에 따른 호적으로 보게 된 경우 혼인으로서 효력은 발생할 수 없으며, 이와 같은 경우 2008. 1. 1.부터 새로운 등록부가 작성된 경우에도 혼인의 효력은 발생할 수 없다.","베트남 혼인․가족법에 의한 혼인적령은 남자는 20세, 여자는 18세이지만, 신고일 현재 베트남 남성이 20세, 베트남 여성이 18세에 이르지 아니한 경우에도 혼인신고서에 첨부할 서류(베트남인의 부모 등이 작성한 혼인동의서나 승낙서 포함)를 첨부한 혼인신고서가 제출되었다면 가족관계등록공무원은 그 혼인신고 수리를 거부할 수 없다.","중국 혼인법에 의한 혼인적령은 남자는 만22세, 여자는 만20세임에도 불구하고 한국에서 한국인과 혼인하는 중국인이 만18세에 이른 때는 시(구)․읍․면의 장은 혼인적령 미달을 이유로 혼인신고 수리를 거부할 수 없다. 23-23"],"a":4}},{"y":2018,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2018_24-49-1","t":"부모가 혼인신고 시 모의 성과 본을 따르기로 하는 협의는 그 협의 이후 협의당사자 사이에서 태어나는 모든 자녀에 대하여 효력이 있으나 협의당사자가 이혼 후 동일한 당사자끼리 재혼하여 다시 혼인신고를 하는 경우에는 효력이 없다.","ox":"X","m":"①","c":"A","tp":"자녀의 성과 본"},{"y":2018,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2018_24-49-2","t":"부모가 혼인신고 시 모의 성과 본을 따르기로 하는 협의서는 혼인신고 시에 제출할 수 있으나 특별한 사정이 있으면 출생신고 시 변경할 수 있다.","ox":"X","m":"②","c":"A","tp":"자녀의 성과 본"},{"y":2018,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2018_24-49-3","t":"혼인의 당사자가 혼인신고 시 그들 사이의 여러 자녀의 성과 본에 대하여 각 자녀마다 따를 성과 본을 달리 협의하여 협의서를 제출하는 경우 수리하여야 한다.","ox":"X","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2018_24-49-4","t":"부를 알 수 없는 자녀란 모가 부라고 인정할 사람을 알 수 없는 자녀를 말하므로 혼인외의 자 중 부의 성과 본을 알 수 있다 하더라도 부의 성과 본을 따라 가족관계등록을 할 수 있는 것은 아니다.","ox":"X","m":"④","c":"A","tp":"자녀의 성과 본"},{"y":2018,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2018_24-49-5","t":"부모가 혼인신고 시 모의 성과 본을 따르기로 하는 협의서가 제출된 경우에 그 협의서는 혼인신고서와 별도로 접수하여 가족관계등록문서건명부에 기록하고 동시에 특종신고서류 등 접수장에 기록하되, 혼인신고서에 가철하여 보존한다.","ox":"O","m":"⑤","c":"A","tp":"자녀의 성과 본"},{"y":2019,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2019_25-41-1","t":"가족관계등록부에 기록을 마친 신고서류는 1개월마다 다음 달 10일까지 접수순서에 따라 편철한 후 각 장마다 장수를 기재하여 그 목록과 함께 사건을 처리한 시ㆍ읍ㆍ면사무소를 감독하는 법원에 송부하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2019_25-41-2","t":"가족관계의 등록 등에 관한 법률 제42조 제4항의 이해관계인은 법원에 보관되어 있는 신고서류의 열람을 청구할 수 있고, 이때의 열람은 관계공무원이 보는 앞에서 하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2019_25-41-3","t":"시ㆍ읍ㆍ면에 있는 신고서류의 열람 수수료는 무료로 한다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2019_25-41-4","t":"시ㆍ읍ㆍ면의 장이 신고서류 등을 수리한 때에는 그 신고사건에 무효사유가 없으면, 즉시 가족관계등록부에 기록을 하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2019_25-41-5","t":"신고서류에 의하여 이루어진 가족관계등록부의 기록에 오기나 누락된 부분이 있음이 해당 신고서류에 비추어 명백한 때에는 시ㆍ읍ㆍ면의 장이 가족관계의 등록 등에 관한 법률 제18조 제2항 단서에 따라 감독법원의 허가 없이 직권으로 정정 또는 기록할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2019_25-44-1","t":"외국에 거주하고 있는 한국인은 한국에 거주하고 있는 사람과 동일하게 보고적 신고사항에 대하여 가족관계의 등록 등에 관한 법률에 따른 신고의무를 진다.","ox":"O","m":"①","c":"A","tp":"외국에 거주하고 있는 한국인의 가족관계등록신고 절차"},{"y":2019,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2019_25-44-2","t":"신고의무가 있는 보고적 신고사항에는 고유의 보고적 신고와 전래의 보고적 신고가 모두 포함된다.","ox":"O","m":"②","c":"A","tp":"외국에 거주하고 있는 한국인의 가족관계등록신고 절차"},{"y":2019,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2019_25-44-3","t":"외국에 거주하고 있는 한국인이 외국 법원의 확정판결을 받아 전래의 보고적 신고를 하는 경우, 거주지 나라 방식에 의해 신고한 사실을 증명하는 서면으로 가족관계등록신고서에 첨부하여야 할 확정판결과 집행판결을 갈음할 수 있다.","ox":"X","m":"③","c":"A","tp":"외국에 거주하고 있는 한국인의 가족관계등록신고 절차"},{"y":2019,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2019_25-44-4","t":"증서의 등본 제출방식에 의하여 가족관계등록부에 기록을 할 수 있는 경우는 외국에 거주하고 있는 한국인이 그 거주지 나라 방식에 의하여 실체적인 창설적 신분행위를 하여 신분행위가 성립된 경우에만 가능하다.","ox":"O","m":"④","c":"A","tp":"외국에 거주하고 있는 한국인의 가족관계등록신고 절차"},{"y":2019,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2019_25-44-5","t":"외국에 거주하고 있는 한국인은 그 지역을 관할하는 재외공관의 장 또는 재외공관에서 근무하는 가족관계등록관에게 신고를 할 수 있으나, 다른 지역을 관할하는 재외공관의 장 또는 재외공관에서 근무하는 가족관계등록관에게 신고를 할 수는 없다.","ox":"O","m":"⑤","c":"A","tp":"외국에 거주하고 있는 한국인의 가족관계등록신고 절차"},{"y":2019,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2019_25-45-1","t":"외국인 부와 한국인 모 사이에 출생한 혼인외의 자녀는 그 외국인 부가 인지하기 전에는 외국인 부의 성을 아는 경우라도 외국인 부의 성을 따라 가족관계등록부에 기록을 할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2019_25-45-2","t":"외국에 거주하는 한국인이 외국 관공서 등으로부터 교부받은 증서의 등본을 출생증명서에 갈음하여 출생신고서에 첨부하는 경우 그 사본을 첨부하고 원본의 환부를 청구할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2019_25-45-3","t":"외국인 부와 한국인 모 사이에 출생한 혼인외의 자녀에 대하여 모가 출생신고한 후 한국인 모와 외국인 부가 혼인을 하더라도 그것만으로는 외국인 부와 혼인외의 자녀 사이에 친자관계가 발생하는 것은 아니다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2019_25-45-4","t":"외국인 부와 한국인 모 사이에 출생한 혼인중의 자녀가 외국인 부의 성을 따라 외국식 이름으로 기록된 후에 한국인 모의 성과 한국식 이름으로 변경하려면 성·본 변경절차와 개명절차를 거쳐야 한다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2019_25-45-5","t":"외국인 부와 한국인 모 사이에 출생한 혼인중의 자녀는 한국인 모의 성과 본을 따를 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2019_25-46","t":"다음 중 그 신고를 게을리한 때에 가족관계의 등록 등에 관한 법률 제122조에 따라 과태료가 부과될 수 있는 것은?","c":"A","mc":{"s":"다음 중 그 신고를 게을리한 때에 가족관계의 등록 등에 관한 법률 제122조에 따라 과태료가 부과될 수 있는 것은?","d":"","o":["검사 또는 지방자치단체의 장이 출생의 신고를 하는 경우","부가 혼인 외의 자녀에 대하여 친생자출생의 신고를 하는 경우","인지의 재판이 확정된 후 그 소의 상대방이 인지의 재판이 확정된 취지를 신고하는 경우","미성년자를 입양하려는 사람이 민법 제867조에 따라 가정법원의 허가를 받아 입양의 신고를 하는 경우","국적상실자의 배우자가 국적상실의 신고를 하는 경우"],"a":5}},{"y":2020,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2020_26-42-1","t":"협의이혼의사확인 절차에서 작성되는 양육비부담조서가 그 자체로 집행권원이 되는 것은 아니므로, 이혼 후 자녀의 양육비에 관하여 강제집행을 하기 위해서는 별도의 재판이 필요하다.","ox":"X","m":"①","c":"A","tp":"협의이혼의사확인 절차 등"},{"y":2020,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2020_26-42-2","t":"양육비부담조서는 협의이혼신고일부터 미성년인 자녀가 각 성년에 이르는 날까지의 기간에 해당하는 양육비에 한하여 작성하므로, 양육비부담조서의 집행문은 그 양육비부담조서가 작성된 협의이혼의사확인 사건의 확인서에 따라 이혼신고를 하였음이 소명된 경우 내어준다.","ox":"X","m":"②","c":"A","tp":"협의이혼의사확인 절차 등"},{"y":2020,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2020_26-42-3","t":"가정법원은 양육비를 정기적으로 지급할 의무가 있는 사람이 정당한 사유 없이 2회 이상 양육비를 지급하지 아니한 경우에 정기금 양육비 채권에 관한 집행권원을 가진 채권자의 신청에 따라 양육비채무자에 대하여 정기적 급여채무를 부담하는 소득세원천징수의무자에게 양육비채무자의 급여에서 정기적으로 양육비를 공제하여 양육비채권자에게 직접 지급하도록 명할 수 있다.","ox":"O","m":"③","c":"A","tp":"협의이혼의사확인 절차 등"},{"y":2020,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2020_26-42-4","t":"재외공관의 장이 당사자 쌍방으로부터 협의이혼의사확인 신청을 받은 경우 쌍방을 출석시켜 그 진술을 듣고 이혼의사확인서를 작성한 후 이혼의사확인서등본을 교부한다.","ox":"X","m":"④","c":"A","tp":"협의이혼의사확인 절차 등"},{"y":2020,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2020_26-42-5","t":"협의이혼신고서는 협의상 이혼을 하려는 부부가 등록기준지, 주소지 또는 현재지의 시ㆍ읍ㆍ면에 함께 출석하여 가정법원의 확인서가 첨부된 협의이혼신고서를 제출하여야 한다.","ox":"X","m":"⑤","c":"A","tp":"협의이혼의사확인 절차 등"},{"y":2020,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2020_26-44-1","t":"민법 제871조 제2항에 따라 부모의 동의를 갈음하는 심판이 있는 경우에는 가정법원의 심판서를 첨부하여야 한다.","ox":"O","m":"①","c":"A","tp":"입양신고 및 가족관계증명서"},{"y":2020,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2020_26-44-2","t":"양자가 13세 미만인 경우에는 민법 제869조 제2항에 따라 입양을 승낙한 법정대리인이 신고하여야 한다. 다만, 양자 본인이 신고를 하여도 된다.","ox":"X","m":"②","c":"A","tp":"입양신고 및 가족관계증명서"},{"y":2020,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2020_26-44-3","t":"양부모의 가족관계증명서에는 친생자와 양자 모두 자녀로 기재된다.","ox":"O","m":"③","c":"A","tp":"입양신고 및 가족관계증명서"},{"y":2020,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2020_26-44-4","t":"외국인이 양부 또는 양모로 기재된 입양신고도 수리될 수 있다.","ox":"O","m":"④","c":"A","tp":"입양신고 및 가족관계증명서"},{"y":2020,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2020_26-44-5","t":"단독입양한 양부가 친생모와 혼인관계에 있는 때라면, 양자의 가족관계증명서에는 양부와 친생모가 부모로 기재된다.","ox":"O","m":"⑤","c":"A","tp":"입양신고 및 가족관계증명서"},{"y":2020,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2020_26-46-1","t":"부가 혼인 전의 출생자를 혼인 후에 혼인 중의 출생자로 출생신고를 할 때에는 혼인 외의 출생자로 출생신고한 것이므로 이를 수리할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2020_26-46-2","t":"성명란의 한자란에 한글과 한자(인명용 한자의 제한 범위 내의 것)를 혼합하여 표기한 출생신고 등은 수리할 수 없다.","ox":"X","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2020_26-46-3","t":"중혼은 취소원인이나 그 취소의 효력은 이전으로 소급하지 아니하므로, 중혼으로 취소할 수 있는 혼인당사자 사이에서의 출생한 자녀는 혼인 중의 자로 출생신고를 하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2020_26-46-4","t":"부 또는 모의 출생신고는 전산정보처리조직을 이용하여 전자문서로 할 수 없다.","ox":"X","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2020_26-46-5","t":"한국인 생부와 일본인 모 사이의 혼인 외의 자가 일본에서 출생한 경우, 한국인 생부가 가족관계의 등록 등에 관한 법률 제57조의 친생자 출생신고를 할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2020_26-47-1","t":"가족관계등록공무원은 가족관계등록부에 기록을 함에 있어서 그 신고가 형식상 요건을 갖추고 있는 경우에는 그에 따른 기록절차를 밟고, 신고사항이 허위임을 공적으로 확인할 수 있거나 허위인 것이 명백한 경우에는 그 기록을 거부할 수 있다.","ox":"O","m":"①","c":"A","tp":"가족관계등록신고"},{"y":2020,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2020_26-47-2","t":"혼인신고는 원칙적으로 양 당사자가 생존한 경우에 한하여 할 수 있으므로 사실혼관계에 있던 자가 사망한 후에 사실상혼인관계존재확인의 판결이 확정된 경우에는 그 판결에 기한 혼인신고는 할 수 없다.","ox":"O","m":"②","c":"A","tp":"가족관계등록신고"},{"y":2020,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2020_26-47-3","t":"인지의 재판이 확정된 경우 소제기자가 사망한 때에는 그 사람의 배우자 또는 4촌이내의 친족이 인지신고를 할 수 있으나 신고의무자는 아니다.","ox":"O","m":"③","c":"A","tp":"가족관계등록신고"},{"y":2020,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2020_26-47-4","t":"부(父) 미정의 출생신고가 있는 경우에는 일단 가족관계등록부에 출생신고를 기록한 후에 부(父)를 정하는 판결의 확정 후, 추후보완신고에 의하여 부(父)를 기록하여야 한다.","ox":"X","m":"④","c":"A","tp":"가족관계등록신고"},{"y":2020,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2020_26-47-5","t":"국적취득자의 성과 본의 창설 신고, 개명신고, 가족관계등록 창설 신고 및 가족관계의 등록 등에 관한 법률 제104조 및 제105조에 따른 등록부정정 신청, 동법 제44조 제4항 및 제46조 제1항, 제2항에 따른 부 또는 모의 출생신고는 전자신고로 할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"가족관계등록신고"},{"y":2020,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2020_26-48","t":"다음 신고 중 유언집행자가 신고하여야 하는 경우는?","c":"A","mc":{"s":"다음 신고 중 유언집행자가 신고하여야 하는 경우는?","d":"","o":["입양신고","개명신고","미성년후견 종료신고","인지신고","친권자 지정 신고"],"a":4}},{"y":2021,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2021_27-45-1","t":"혼인신고인이 생존 중에 혼인신고서를 우송하였으나 그 혼인신고인 일방이 사망한 후에 혼인신고서가 도착한 경우라도 시(구)·읍·면의 장은 이를 수리하여야 한다.","ox":"O","m":"①","c":"A","tp":"혼인신고 및 혼인신고수리불가신고"},{"y":2021,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2021_27-45-2","t":"혼인신고서와 혼인신고수리불가신고서의 접수일이 같고, 그 선·후의 판명을 할 수 없을 때에는 혼인신고서가 먼저 접수된 것으로 처리한다.","ox":"X","m":"②","c":"A","tp":"혼인신고 및 혼인신고수리불가신고"},{"y":2021,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2021_27-45-3","t":"한국에서 한국인 남자와 외국인 여자 사이에 혼인한 경우 혼인신고를 수리한 시(구)·읍·면의 장은 남편의 가족관계등록부 일반등록사항란에 혼인사유만을 기록하였다가 나중에 귀화통보가 있을 때에 처의 가족관계등록부를 작성한다.","ox":"O","m":"③","c":"A","tp":"혼인신고 및 혼인신고수리불가신고"},{"y":2021,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2021_27-45-4","t":"미성년자가 혼인하는 경우에는 부모의 동의를 받아야 하며, 부모 중 한쪽의 동의권을 행사할 수 없는 때에는 다른 한쪽의 동의를 받아야 한다. 부모가 모두 동의권을 행사할 수 없는 때에는 미성년후견인의 동의를 얻어야 한다.","ox":"O","m":"④","c":"A","tp":"혼인신고 및 혼인신고수리불가신고"},{"y":2021,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2021_27-45-5","t":"혼인신고수리불가신고서의 제출횟수는 제한이 없으며 6개월의 범위 내에서 취급기간을 정하여야 한다. 또한, 취급 상대방은 특정된 1인이어야 하며 불특정 다수를 상대로 한 수리불가신고서는 제출할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"혼인신고 및 혼인신고수리불가신고"},{"y":2021,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2021_27-47-1","t":"국적상실의 신고는 본인 또는 4촌 이내의 친족이 그 사실을 안 날부터 1개월 이내에 하여야 하며, 그 신고를 게을리한 때에 가족관계의 등록 등에 관한 법률 제122조에 따라 과태료가 부과될 수 있다.","ox":"X","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2021_27-47-2","t":"甲이 乙의 자로 출생신고되었다가 甲·乙간의 친생자관계부존재확인판결이 확정되어 甲의 가족관계등록부가 폐쇄됨으로 인하여 甲에 대한 출생신고의무자가 다시 출생신고를 하는 경우, 과태료 부과의 기산점인 출생신고기간은 친생자관계부존재확인의 판결이 확정된 때로부터 기산하여야 한다.","ox":"X","m":"②","c":"A","tp":"가족관계의 등록 등"},{"y":2021,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2021_27-47-3","t":"과태료 처분에 불복하는 사람은 60일 이내에 과태료 처분한 시(구)·읍·면의 장에게 이의를 제기할 수 있다.","ox":"X","m":"③","c":"A","tp":"가족관계의 등록 등"},{"y":2021,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2021_27-47-4","t":"시(구)·읍·면의 장으로부터 과태료 처분을 받은 사람이 이의를 제기한 때에는 당해 시(구)·읍·면의 장은 지체 없이 과태료 처분을 받은 사람의 주소 또는 거소를 관할하는 가정법원에 그 사실을 통보하여야 한다.","ox":"O","m":"④","c":"A","tp":"가족관계의 등록 등"},{"y":2021,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2021_27-47-5","t":"재외국민 가족관계등록사무소의 가족관계등록관이 과태료 부과 대상이 있음을 안 때에는 신고의무자인 재외국민이 있는 지역을 관할하는 재외공관의 장에게 그 사실을 통지하고, 통지를 받은 재외공관의 장이 과태료를 부과·징수한다.","ox":"X","m":"⑤","c":"A","tp":"가족관계의 등록 등"},{"y":2021,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2021_27-48-1","t":"부(父)의 추정이 경합하여 부 미정의 출생신고가 접수된 때에는 이를 특종신고서류편철장에 편철하여 두었다가, 부를 정하는 판결의 확정 후, 추후보완신고에 의하여 부 또는 모의 성과 본을 따라 가족관계등록부를 작성하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2021_27-48-2","t":"출생신고를 한 부 또는 모와 친생자관계부존재확인판결이 확정되어 가족관계등록부가 폐쇄된 사건본인에 대하여, 이후 그 판결 확정 전 국적상실을 이유로 한 국적상실신고 또는 국적상실통보가 있다고 하더라도 사건본인의 폐쇄된 가족관계등록부에 국적상실과 관련된 어떠한 기록도 할 수 없으며, 그 신고서류 또는 통보서류는 특종신고서류편철장에 편철하여 보존해야 한다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2021_27-48-3","t":"한국인과 외국인 사이의 가족관계등록신고 중 혼인, 입양, 인지신고는 한국인의 가족관계등록부에 기록한 후 신고서류의 원본을 감독법원에 송부하고, 그 등본을 별도로 특종신고서류편철장에 편철하여 보존하지 아니한다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2021_27-48-4","t":"인지된 태아의 사산신고가 제출되는 경우 그 신고서는 특종신고서류편철장에 편철하여 보존하고, 특종신고서류 등 접수장에도 접수에 관한 기록을 하여야 한다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2021_27-48-5","t":"외국인 부모가 대한민국에서 자녀를 출산한 경우 외국인 부모는 그 외국인 자녀에 대하여 출생증명서를 첨부하여 출생신고를 할 수 있으며, 그 출생신고서류는 특종신고서류편철장에 편철하여 보존한다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2021_27-49-1","t":"친권은 부모가 혼인 중인 때에는 부모가 공동으로 이를 행사하고, 부모의 일방이 친권을 행사할 수 없을 때에는 당사자의 청구에 의하여 가정법원이 이를 정한다.","ox":"X","m":"①","c":"A","tp":"친권 및 친권자 지정·변경 등"},{"y":2021,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2021_27-49-2","t":"친권자는 그 자를 보호 또는 교양하기 위하여 법원의 허가를 얻어 감화 또는 교정기관에 위탁할 수 있다.","ox":"X","m":"②","c":"A","tp":"친권 및 친권자 지정·변경 등"},{"y":2021,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2021_27-49-3","t":"미성년자를 인지한 때 하는 친권자 지정신고의 경우에는 인지신고 또는 인지의 효력이 있는 출생신고가 수리되기 전에는 친권자 지정신고를 수리할 수 없다.","ox":"O","m":"③","c":"A","tp":"친권 및 친권자 지정·변경 등"},{"y":2021,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2021_27-49-4","t":"협의이혼을 하는 부부에게 포태 중인 자가 있는 경우에는 시(구)·읍·면의 장은 그 자에 대한 친권자지정 신고를 협의이혼신고시 함께 수리하여야 한다.","ox":"X","m":"④","c":"A","tp":"친권 및 친권자 지정·변경 등"},{"y":2021,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2021_27-49-5","t":"이혼 후 미성년인 자녀에 대한 양육권이 부모 중 어느 일방에, 친권이 다른 일방에 귀속되는 것으로 정하는 것은 미성년자인 자녀의 복리에 현저하게 부정적인 영향을 미치므로 허용되지 않는다.","ox":"X","m":"⑤","c":"A","tp":"친권 및 친권자 지정·변경 등"},{"y":2021,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2021_27-50","t":"국적의 취득 및 상실, 국적취득자의 성과 본의 창설신고 등에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"국적의 취득 및 상실, 국적취득자의 성과 본의 창설신고 등에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["한국인 남자와 외국인 여자 사이의 출생자가 혼인 외의 자인 경우 부의 출생신고만으로는 가족관계등록부를 작성할 수 없다.","외국의 성을 쓰는 국적취득자가 그 성을 쓰지 아니하고 새로이 성ㆍ본을 정하고자 하는 경우에는 그 등록기준지ㆍ주소지 또는 등록기준지로 하고자 하는 곳을 관할하는 가정법원의 허가를 받아야 한다.","외국인의 자로서 대한민국의 민법상 미성년인 사람은 부 또는 모가 귀화허가를 신청하여 대한민국 국적을 취득하게 되면, 신청 없이도 함께 대한민국 국적을 취득하게 된다.","법무부장관은 국적법에 따라 대한민국의 국적을 취득한 사람이 있는 경우 지체 없이 국적을 취득한 사람이 정한 등록기준지의 시(구)ㆍ읍ㆍ면의 장에게 대법원규칙으로 정하는 사항을 통보하여야 하며, 통보를 받은 시(구)ㆍ읍ㆍ면의 장은 국적을 취득한 사람의 등록부를 작성한다.","대한민국의 국민이었던 외국인은 법무부장관의 국적회복허가를 받아 대한민국 국적을 취득할 수 있다. 2021년 6월 19일 시행 제27회 법무사 제1차 시험"],"a":3}},{"y":2022,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2022_28-42-1","t":"대한민국 국민인 부 또는 모가 외국인을 인지한 경우에는 인지자 또는 피인지자의 국적취득신고에 따라 피인지자의 가족관계등록부를 작성한다.","ox":"X","m":"①","c":"A","tp":"국적의 취득과 상실"},{"y":2022,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2022_28-42-2","t":"국적상실의 신고는 배우자 또는 4촌 이내의 친족이 그 국적을 상실한 날부터 1개월 이내에 하여야 한다.","ox":"X","m":"②","c":"A","tp":"국적의 취득과 상실"},{"y":2022,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2022_28-42-3","t":"대한민국의 국민으로서 자진하여 외국 국적을 취득한 자는 그 외국 국적을 취득한 때에 대한민국 국적을 상실하므로, 국적상실자 본인은 국적상실의 신고를 할 수 없다.","ox":"X","m":"③","c":"A","tp":"국적의 취득과 상실"},{"y":2022,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2022_28-42-4","t":"한쪽 배우자에 대하여 국적취득과 그 상실의 신고가 있는 때에는 다른 배우자의 가족관계등록부에도 그 취지를 기록하여야 한다.","ox":"O","m":"④","c":"A","tp":"국적의 취득과 상실"},{"y":2022,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2022_28-42-5","t":"국적상실로 가족관계등록부가 폐쇄된 경우에 폐쇄 전에 효력이 발생한 법률관계 또는 사실에 관하여 폐쇄 후에 신고적격자가 신고를 하면, 해당 가족관계등록부의 등록기준지의 시(구)·읍·면의 장이 감독법원의 허가를 받아 부활 없이 폐쇄등록부에 직권기록한다.","ox":"X","m":"⑤","c":"A","tp":"국적의 취득과 상실"},{"y":2022,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2022_28-44","t":"다음 중 특종신고서류 등 접수장에 접수에 관한 기록을 해야 하는 신고나 경우가 아닌 것은?","c":"A","mc":{"s":"다음 중 특종신고서류 등 접수장에 접수에 관한 기록을 해야 하는 신고나 경우가 아닌 것은?","d":"","o":["태아인지신고","이혼의사 철회신고","부 미정의 출생신고","혼인신고를 하는 때에 자녀의 성과 본을 모의 성과 본으로 따르기로 한 협의서를 제출하는 경우","혼인신고수리불가신고"],"a":3}},{"y":2022,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2022_28-47-1","t":"출생자에 대한 부와 모의 가족관계증명서에 드러나는 사람과 동일한 이름을 기재한 출생신고도 수리하여야 한다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2022_28-47-2","t":"모가 특정됨에도 불구하고 부가 혼인 외의 자녀에 대하여 친생자 출생신고를 할 때 모의 소재불명 또는 모가 정당한 사유 없이 출생신고에 필요한 서류 제출에 협조하지 아니하는 등의 장애가 있는 경우에는 부의 등록기준지 또는 주소지를 관할하는 가정법원의 확인을 받아 신고할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2022_28-47-3","t":"부 또는 모가 기아를 찾아 출생신고와 더불어 시(구)·읍·면의 장에게 종전 기아의 등록부를 폐쇄하기 위해서는 반드시 법원의 허가를 받아 등록부의 정정을 신청해야 한다.","ox":"X","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2022_28-47-4","t":"중혼으로 취소할 수 있는 혼인당사자 사이에서의 출생한 자녀는 혼인 외의 자로 출생신고해야 한다.","ox":"X","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2022_28-47-5","t":"외국에서 출생한 우리나라 국민으로서 가족관계등록부상 특정등록사항란의 출생연월일이 한국시각으로 환산된 일자로 기록된 자가 현지 출생연월일로 정정하고자 하는 때에는 간이직권정정을 통해 정정할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"출생신고"},{"y":2022,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2022_28-50","t":"다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"다음 설명 중 가장 옳지 않은 것은?","d":"","o":["혼인신고가 위법하여 무효인 경우에도 그 무효의 혼인 중의 출생자를 부가 출생신고하여 그 등록부를 작성한 이상 그 사람에 대한 인지의 효력이 있다.","외국인 부와 한국인 모 사이에서 출생한 혼인 외의 자, 즉 한국인 자녀에 대해서 모가 출생신고한 후 혼인외 자의 생모와 외국인 부가 혼인을 하더라도 그것만으로는 외국인 부와 혼인 외의 자 사이에 친자관계가 발생하는 것은 아니다.","한국인 생부와 일본인 모 사이의 혼인 외의 자가 일본에서 출생한 경우에는 한국인의 생부는 인지신고 또는 친생자 출생신고(가족관계의 등록 등에 관한 법률 제57조)를 할 수 있다.","혼인중의 여자가 다른 남자와의 사이에서 출생한 자녀는 친자관계에 관한 재판을 거치지 않고 다른 남자의 자녀로 출생신고를 할 수 없다.","모의 혼인 외의 자로 등록부가 작성된 자가 가족관계등록이 되어 있지 않은 채 사망한 부를 상대(검사를 피고로 한다)로 인지재판을 청구하여 그 판결이 확정된 경우에는 피인지자의 등록부 일반등록사항란에 인지사유를 기록하고 부란에 부의 성명을 기록하여야 한다. 2022년 8월 27일 시행 제28회 법무사 제1차 시험"],"a":3}},{"y":2023,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2023_29-42-1","t":"부모가 혼인신고 시 민법 제781조 제1항 단서에 따라 자가 모의 성과 본을 따르기로 협의한 경우에 자녀는 모의 성과 본을 따르며, 혼인신고 시 협의하지 아니하였던 부부가 이혼 후 동일한 당사자끼리 다시 혼인하는 경우에도 민법 제781조 제1항 단서에 따른 협의를 할 수 있다.","ox":"O","m":"①","c":"A","tp":"자녀의 성과 본"},{"y":2023,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2023_29-42-2","t":"혼인 외의 자가 인지된 경우에는 부의 성과 본을 따른다. 다만, 인지신고 시 부모의 협의에 의하여 종전의 성과 본을 계속 사용하기로 하는 협의서를 제출한 경우에는 종전의 성과 본을 그대로 사용할 수 있으며, 이 경우 자녀의 가족관계등록부에는 종전 성과 본을 유지한다는 취지를 기록하여야 한다.","ox":"O","m":"②","c":"A","tp":"자녀의 성과 본"},{"y":2023,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2023_29-42-3","t":"부가 인지하지 아니한 혼인 외의 출생자라도 부의 성과 본을 알 수 있는 경우에는 부의 성과 본을 따를 수 있으며, 부의 성명을 그 자녀의 일반등록사항란 및 특정등록사항란의 부란에 기록한다.","ox":"X","m":"③","c":"A","tp":"자녀의 성과 본"},{"y":2023,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2023_29-42-4","t":"혼인중 출생자의 부가 외국인이고 모가 대한민국 국민인 경우 민법 제781조 제2항에 따라 그 자녀는 모의 성과 본을 따를 수 있으며, 혼인외 출생자의 부가 외국인이고 모가 대한민국 국민인 경우 그 자녀는 모의 성과 본을 따른다.","ox":"O","m":"④","c":"A","tp":"자녀의 성과 본"},{"y":2023,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2023_29-42-5","t":"외국인인 부가 한국인인 혼인 외의 자를 인지하는 경우에 혼인 외의 자가 부의 성을 따를 때 외국인 부의 성이 외국어로서 한자인 경우, 그 자녀의 성 표기에 대하여는 그 한자에 대한 한국식 발음의 한글 및 한자를 병기하는 방법으로도 이를 표기할 수 있다. 다만, 그 한자는 그에 대응하는 한국통용의 한자가 소명되어야 하며 외국인 부가 그의 나라에서 발행한 공문서에 의하여 이를 소명하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"자녀의 성과 본"},{"y":2023,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2023_29-43-1","t":"외국의 성을 쓰는 국적취득자가 그 성을 쓰지 않고 새로이 성과 본을 정하고자 하는 경우에는 그 등록기준지ㆍ주소지 또는 등록기준지로 하고자 하는 곳을 관할하는 가정법원의 허가를 받고 그 등본을 받은 날부터 1개월 이내에 그 성과 본을 신고하여야 한다.","ox":"O","m":"①","c":"A","tp":"가족관계의 등록 등"},{"y":2023,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2023_29-43-2","t":"국적취득자의 성과 본의 창설신고서에는 종전의 성, 창설한 성ㆍ본, 허가의 연월일을 기재하여야 한다.","ox":"O","m":"②","c":"A","tp":"가족관계의 등록 등"},{"y":2023,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2023_29-43-3","t":"가족관계등록 창설신고와 달리, 국적취득자의 성과 본의 창설신고는 가족관계의 등록 등에 관한 법률 제23조의2에 따라 전산정보처리조직을 이용하여 전자문서로 할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2023_29-43-4","t":"시(구)·읍·면의 장은 한 쪽 배우자에 대한 성과 본의 창설신고가 수리되면, 다른 배우자의 가족관계등록부 일반등록사항란에 그 취지를 직권으로 기록하여야 한다.","ox":"O","m":"④","c":"A","tp":"가족관계의 등록 등"},{"y":2023,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2023_29-43-5","t":"시(구)ㆍ읍ㆍ면의 장은 국적취득자의 성과 본의 창설신고에 따라 부 또는 모의 성과 본이 변경된 경우, 그 부 또는 모의 성을 따르는 자녀의 성과 본을 직권으로 변경기록하고 그 사유를 자녀의 가족관계등록부 일반등록사항란에 기록하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"가족관계의 등록 등"},{"y":2023,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2023_29-44-1","t":"외국에 거주하고 있는 한국인은 한국에 거주하고 있는 사람과 동일하게 보고적 신고사항에 대하여 가족관계의 등록 등에 관한 법률에 따른 가족관계등록신고의 의무를 지며, 보고적 신고대상인 신분변동사실에 대하여 거주지 나라의 법에 따라 그 나라 관공서 등에 신고를 한 경우에도 위 신고의무가 면제되는 것은 아니다.","ox":"O","m":"①","c":"A","tp":"국제가족관계등록사무의 처리"},{"y":2023,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2023_29-44-2","t":"증서의 등본 제출방식에 의하여 가족관계등록부에 기록을 할 수 있는 경우는 외국에 거주하고 있는 한국인이 그 거주지 나라 방식에 의하여 실체적인 창설적 신분행위(혼인, 입양, 인지, 이혼과 파양 등)를 하여 신분행위가 성립된 경우에만 가능하다.","ox":"O","m":"②","c":"A","tp":"국제가족관계등록사무의 처리"},{"y":2023,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2023_29-44-3","t":"외국에 거주하고 있는 한국인이 출생, 사망 등과 같은 보고적 신고를 하는 경우에는, 가족관계등록신고서에 첨부하여야 할 출생증명서나 사망증명서 등을 갈음하여 그 거주지 나라의 방식에 의해 신고한 사실을 증명하는 서면을 첨부할 수 있다.","ox":"O","m":"③","c":"A","tp":"국제가족관계등록사무의 처리"},{"y":2023,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2023_29-44-4","t":"대한민국 국적을 회복한 사람에 대하여 국적회복통보를 하는 경우에, 국적회복자가 종전에 우리나라에서 사용하던 성명(한자를 포함한다)을 국적회복통보서에 기재한 때에는 이를 수리하여야 한다. 이 경우 국적회복자가 종전에 우리나라에서 사용하던 성명을 등록사항별 증명서에 의하여 소명하여야 하며, 이때에도 인명용 한자의 제한을 받는다.","ox":"X","m":"④","c":"A","tp":"국제가족관계등록사무의 처리"},{"y":2023,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2023_29-44-5","t":"외국인의 인명은 신고인이 가족관계등록신고서에 한글로 표기한 해당 외국의 원지음대로 가족관계등록부에 기록하여야 하며 이 경우 한자는 함께 기록할 수 없다. 다만, 중국에서 발행한 공문서에 의하여 조선족임을 소명한 중국 국적자에 대하여 가족관계등록신고를 하는 경우에, 신고인이 해당 중국국적자의 인명에 대하여 그에 대응하는 한국통용의 한자를 소명한 때에는 그 한국통용의 한자에 대한 한국식 발음의 한글을 그 원지음을 갈음하여 위 신고서에 표기할 수 있으나, 이 경우에도 한자는 함께 기록할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"국제가족관계등록사무의 처리"},{"y":2023,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2023_29-47","t":"다음 중 가족관계등록신고와 그 신고의무자에 대한 연결이 잘못된 것은 모두 몇 개인가?","c":"A","mc":{"s":"다음 중 가족관계등록신고와 그 신고의무자에 대한 연결이 잘못된 것은 모두 몇 개인가?","d":"가.사망신고 – 친족\n나.(강제)인지신고 – 인지청구의 소를 제기한 사람의 상대방\n다.혼인 중 출생자 출생신고 – 부 또는 모\n라.혼인 외 출생자 출생신고 – 모\n마.(재판상)이혼신고 – 이혼소송을 제기하거나 조정을 신청한 자","o":["1개","2개","3개","4개","5개"],"a":2}},{"y":2023,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2023_29-48","t":"다음 중 추후보완신고의 대상으로 볼 수 없는 것은?","c":"A","mc":{"s":"다음 중 추후보완신고의 대상으로 볼 수 없는 것은?","d":"","o":["부 미정의 출생신고를 한 후 부를 정하는 판결이 확정되어 출생신고를 하는 경우","신고에 필요한 부모 기타의 사실상 동의가 있었으나 이를 증명하는 서면의 첨부 또는 신고서의 기재만 유탈한데 지나지 않는 경우","신고서에 가족관계등록부의 기록사항인 ‘성과 본’이 누락된 경우","외국인 부의 성을 따라 외국식 이름으로 기록된 가족관계등록부를 후에 한국인 모의 성과 한국식 이름으로 변경하고자 하는 경우","인명용 한자 추가에 따라 이름에 한자를 기재하고자 하는 경우"],"a":4}},{"y":2023,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2023_29-49-1","t":"부가 혼인 외의 자녀에 대하여 친생자출생의 신고를 한 때에는 그 신고는 인지의 효력이 있다. 다만, 모가 특정됨에도 불구하고 부가 본문에 따른 신고를 함에 있어 모의 소재불명 또는 모가 정당한 사유 없이 출생신고에 필요한 서류 제출에 협조하지 아니하는 등의 장애가 있는 경우에는 부의 등록기준지 또는 주소지를 관할하는 가정법원의 확인을 받아 신고를 할 수 있다.","ox":"O","m":"①","c":"A","tp":"인지(신고)"},{"y":2023,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2023_29-49-2","t":"인지의 재판이 확정된 경우에 소를 제기한 사람은 재판의 확정일부터 1개월 이내에 재판서의 등본 및 확정증명서를 첨부하여 그 취지를 신고하여야 하고, 그 소의 상대방도 위 서류를 첨부하여 인지의 재판이 확정된 취지를 신고할 수 있다.","ox":"O","m":"②","c":"A","tp":"인지(신고)"},{"y":2023,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2023_29-49-3","t":"혼인외 출생자와 그 부의 법률상의 친자관계는 부의 인지에 의하여서만 발생하는 것이므로 부가 사망한 경우에는 그 사망을 안 날로부터 2년 이내에 검사를 상대로 인지청구의 소를 제기하여야 하고, 생모가 혼인외 출생자를 상대로 혼인외 출생자와 사망한 부 사이의 친생자관계존재확인을 구하는 소는 허용될 수 없다.","ox":"O","m":"③","c":"A","tp":"인지(신고)"},{"y":2023,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2023_29-49-4","t":"부가 혼인 외의 자녀에 대하여 친생자출생의 신고를 할 때, 모의 성명ㆍ등록기준지 및 주민등록번호의 전부 또는 일부를 알 수 없어 모를 특정할 수 없는 경우 또는 모가 공적 서류ㆍ증명서ㆍ장부 등에 의하여 특정될 수 없는 경우에는 부의 등록기준지 또는 주소지를 관할하는 가정법원의 확인을 받아 위 신고를 할 수 있다.","ox":"O","m":"④","c":"A","tp":"인지(신고)"},{"y":2023,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2023_29-49-5","t":"부가 혼인외의 자에 대하여 친생자 출생신고를 한 때에는 그 신고는 인지의 효력이 있으므로, 이와 같은 신고로 인한 친자관계의 외관을 배제하는 때에는 인지에 대한 이의의 소 또는 인지무효의 소를 제기하여야 한다.","ox":"X","m":"⑤","c":"A","tp":"인지(신고)"},{"y":2024,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2024_30-41-1","t":"혼인은 가족관계의 등록 등에 관한 법률에 정한 바에 의하여 신고함으로써 그 효력이 생기며, 그 신고는 당사자 쌍방과 성년자인 증인 2인의 연서한 서면으로 하여야 한다.","ox":"O","m":"①","c":"A","tp":"증인이 필요한 가족관계등록신고"},{"y":2024,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2024_30-41-2","t":"협의상 이혼은 가정법원의 확인을 받아 가족관계의 등록 등에 관한 법률의 정한 바에 의하여 신고함으로써 그 효력이 생기며, 그 신고는 당사자 쌍방과 성년자인 증인 2인의 연서한 서면으로 하여야 하나, 그 신고서에 가정법원의 이혼의사확인서등본을 첨부한 경우에는 증인 2인의 연서가 있는 것으로 본다.","ox":"O","m":"②","c":"A","tp":"증인이 필요한 가족관계등록신고"},{"y":2024,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2024_30-41-3","t":"입양은 가족관계의 등록 등에 관한 법률에서 정한 바에 따라 신고함으로써 그 효력이 생기며, 그 신고는 당사자 쌍방과 성년자인 증인 2인의 연서한 서면으로 하여야 한다.","ox":"X","m":"③","c":"A","tp":"증인이 필요한 가족관계등록신고"},{"y":2024,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2024_30-41-4","t":"증인을 필요로 하는 사건의 신고에 있어서는 증인은 신고서에 주민등록번호 및 주소를 기재하고 서명하거나 기명날인하여야 한다. 다만, 증인은 신고서에 서명 또는 기명날인을 할 수 없을 때에는 무인할 수 있고, 이 경우 담당공무원은 본인의 무인임을 증명한다는 문구를 기재하고 기명날인하여야 한다.","ox":"O","m":"④","c":"A","tp":"증인이 필요한 가족관계등록신고"},{"y":2024,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2024_30-41-5","t":"혼인신고는 성년자인 증인 2인의 연서가 있어야 수리할 수 있는바, 이에 위반하였다 하더라도 민법상 혼인무효 또는 취소사유에 해당하지 아니하므로 혼인은 유효하게 성립된 것이나, 수리 당시에 발견하였다면 민법 제813조에 따라 수리를 거부하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"증인이 필요한 가족관계등록신고"},{"y":2024,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2024_30-43","t":"다음 신고 중 가족관계의 등록 등에 관한 법률상 유언녹음을 기재한 서면 첨부가 가능한 경우는?","c":"A","mc":{"s":"다음 신고 중 가족관계의 등록 등에 관한 법률상 유언녹음을 기재한 서면 첨부가 가능한 경우는?","d":"","o":["친권자 지정 신고","인지신고","친양자의 입양신고","사망신고","입양신고"],"a":2}},{"y":2024,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2024_30-45","t":"다음 중 사망신고서에 진단서나 검안서를 첨부할 수 없는 부득이한 사유가 있는 때에 첨부할 수 있는 사망의 사실을 증명할 만한 서면에 해당하는 것을 모두 고른 것은?","c":"A","mc":{"s":"다음 중 사망신고서에 진단서나 검안서를 첨부할 수 없는 부득이한 사유가 있는 때에 첨부할 수 있는 사망의 사실을 증명할 만한 서면에 해당하는 것을 모두 고른 것은?","d":"ㄱ.관공서의 사망증명서 또는 매장인허증\nㄴ.진실화해위원회의 진실규명결정문\nㄷ.정부기록보관소에 보존 중인 재무부 작성의 피수용자사망자연명부\nㄹ.외국 관공서 등에서 발행한 그 나라 방식에 의해 사망신고 한 사실을 증명하는 서면\nㅁ.군인이 전투 그 밖의 사변으로 사망한 경우에 부대장 등이 사망 사실을 확인하여 그 명의로 작성한 전사확인서\nㅂ.동(리)장 및 통장 또는 인우인 2명 이상의 증명서\nㅅ.6․25사변으로 인한 사망을 목격한 사람 또는 사망을 확인한 사람 2명 이상의 증명서","o":["ㄱ, ㄴ, ㄹ, ㅁ, ㅅ","ㄱ, ㄷ, ㄹ, ㅁ, ㅂ","ㄱ, ㄴ, ㄷ, ㄹ, ㅁ, ㅂ","ㄱ, ㄴ, ㄷ, ㄹ, ㅂ, ㅅ","ㄱ, ㄴ, ㄷ, ㄹ, ㅁ, ㅂ, ㅅ"],"a":5}},{"y":2024,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2024_30-47","t":"다음은 가족관계의 등록 등에 관한 법률조항의 내용이다. 다음괄호 안에 들어갈 내용이 알맞게 열거된 것은?","c":"A","mc":{"s":"다음은 가족관계의 등록 등에 관한 법률조항의 내용이다. 다음괄호 안에 들어갈 내용이 알맞게 열거된 것은?","d":"ㄱ.의료기관의 장은 출생일부터 ( A ) 이내에 출생정보를 국민건강보험법 제62조에 따른 건강보험심사평가원에 제출하여야 한다.\nㄴ.시ㆍ읍ㆍ면의 장은 제44조 제1항에 따른 신고기간이 지나도록 제44조의3 제3항에 따라 통보받은 출생자에 대한 출생신고가 되지 아니한 경우에는 즉시 제46조 제1항 및 제2항에 따른 신고의무자에게 ( B ) 이내에 출생신고를 할 것을 최고하여야 한다.\nㄷ.시ㆍ읍ㆍ면의 장이 제38조 또는 제108조에 따라 기간을 정하여 신고 또는 신청의 최고를 한 경우에 정당한 사유 없이 그 기간 내에 신고 또는 신청을 하지 아니한 사람에게는 ( C )의 과태료를 부과한다.\nA\nB\nC","o":["10일 5일 5만 원 이하","10일 5일 10만 원 이하","10일 7일 5만 원 이하","14일 5일 5만 원 이하","14일 7일 10만 원 이하"],"a":5}},{"y":2024,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2024_30-49-1","t":"친생부인의 소를 제기한 때에는 그 재판의 확정일부터 1개월 이내에 출생신고를 하여야 한다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2024_30-49-2","t":"출생신고 전에 자녀가 사망한 때에는 출생신고 없이 사망신고를 하여야 한다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2024_30-49-3","t":"부 또는 모가 기아를 찾은 때에는 3개월 이내에 출생의 신고를 하고 등록부의 정정을 신청하여야 한다.","ox":"X","m":"③","c":"A","tp":"출생신고"},{"y":2024,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2024_30-49-4","t":"시·읍·면의 장이 출생신고서류를 수리한 때에는 그 신고사건에 무효사유가 있더라도 즉시 등록부에 기록을 하여야 한다.","ox":"X","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2024_30-49-5","t":"출생신고의 수리 증명서를 청구할 때에는 수수료를 납부하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2025_31-41-1","t":"가족관계의 등록 등에 관한 법률에 따른 신고는 신고사건 본인의 등록기준지 또는 신고인의 주소지나 현재지에서 할 수 있으므로, 당사자가 등록기준지를 새롭게 변경하고자 하는 경우 현재지 시·읍·면의 장에게 변경신고를 할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2025_31-41-2","t":"가족관계등록창설허가의 재판을 얻은 사람이 등록창설의 신고를 하지 아니한 때에는 배우자 또는 직계혈족이 할 수 있으며, 가족관계등록창설허가를 받았으나 그 신고 전에 사망한 사람에 대한 가족관계등록창설신고는 배우자 또는 직계혈족이 이를 하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2025_31-41-3","t":"이혼이 무효이거나 취소된 경우에 그 이혼당사자 사이에서 출생한 미성년의 자녀에 대하여 친권자가 지정·신고 되어 있다면 그에 관한 가족관계등록부의 기록도 따로 정정허가를 받을 필요 없이 이혼무효 또는 이혼취소의 판결(심판)에 의하여 말소할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2025_31-41-4","t":"가족관계등록부상 한자 성의 한글표기 정정의 효력은 사건본인에게만 미친다. 다만, 직계비속이 있음에도 사건본인만이 한자 성의 한글표기 정정 신청을 하여 가족관계등록부상 한자 성의 한글표기가 정정된 경우에는 가족관계의 등록 등에 관한 규칙 제55조 제3항, 제60조 제2항 제4호를 준용하여 시(구)·읍·면의 장은 그 직계비속의 가족관계등록부상 한자 성의 한글표기도 직권으로 정정한다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2025_31-41-5","t":"가족관계등록부를 정정할 때는 그 사항이 기재된 제적부를 정정하되, 가족관계등록부가 현재의 공부이므로 제적부의 정정은 필요최소한으로 하며, 가족관계등록부 정정허가결정만으로 제적부를 정정할 수는 없다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2025_31-42-1","t":"미성년후견인이 경질된 경우, 전임자는 경질일부터 1개월 이내에 그 취지를 신고하여야 한다.","ox":"X","m":"①","c":"A","tp":"미성년후견인 및 미성년후견감독인"},{"y":2025,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2025_31-42-2","t":"미성년자가 성년이 되어 미성년후견감독이 종료된 경우, 미성년후견감독인이 1개월 이내에 그 종료신고를 하여야 한다.","ox":"X","m":"②","c":"A","tp":"미성년후견인 및 미성년후견감독인"},{"y":2025,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2025_31-42-3","t":"미성년후견에 관한 사항은 미성년자 및 미성년후견인의 가족관계등록부 일반등록사항란에 각 기록한다.","ox":"X","m":"③","c":"A","tp":"미성년후견인 및 미성년후견감독인"},{"y":2025,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2025_31-42-4","t":"신고하여야 할 사람이 미성년후견인인 경우에는 미성년자가 신고를 하여도 된다.","ox":"X","m":"④","c":"A","tp":"미성년후견인 및 미성년후견감독인"},{"y":2025,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2025_31-42-5","t":"미성년후견인이 개명한 경우에는 미성년자의 가족관계등록부 일반등록사항란에 기록되어 있는 미성년후견인의 성명을 정정할 필요가 없다.","ox":"O","m":"⑤","c":"A","tp":"미성년후견인 및 미성년후견감독인"},{"y":2025,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2025_31-44-1","t":"확인기일, 보정명령, 불확인결과는 전화, 팩시밀리 등 간이한 방법으로 통지할 수 있다.","ox":"O","m":"①","c":"A","tp":"협의이혼의사확인신청 및 이혼신고 등"},{"y":2025,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2025_31-44-2","t":"협의이혼의사확인서등본을 분실한 경우 당사자 쌍방은 언제든지 관할 가정법원에 다시 협의이혼의사확인신청을 할 수 있다.","ox":"O","m":"②","c":"A","tp":"협의이혼의사확인신청 및 이혼신고 등"},{"y":2025,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2025_31-44-3","t":"양육비부담조서의 집행문은 그 양육비부담조서가 작성된 협의이혼의사확인사건의 확인서에 따라 이혼신고를 하였음을 소명한 때에만 내어준다.","ox":"O","m":"③","c":"A","tp":"협의이혼의사확인신청 및 이혼신고 등"},{"y":2025,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2025_31-44-4","t":"부부 양쪽이 재외국민인 경우에는 두 사람이 함께 그 현재지를 관할하는 재외공관의 장에게 협의이혼의사확인신청을 할 수 있다.","ox":"X","m":"④","c":"A","tp":"협의이혼의사확인신청 및 이혼신고 등"},{"y":2025,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2025_31-44-5","t":"협의이혼의사확인을 받은 재외국민이 협의이혼의사를 철회하고자 하는 경우에는 이혼신고가 접수되기 전에 등록기준지 시·읍·면의 장 또는 가족관계등록관에게 협의이혼의사확인서등본을 첨부한 협의이혼의사철회서를 제출하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"협의이혼의사확인신청 및 이혼신고 등"},{"y":2025,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2025_31-45","t":"다음은 가족관계의 등록 등에 관한 법률 제39조이다. 다음 괄호 안에 들어갈 내용으로 옳은 것은?","c":"A","mc":{"s":"다음은 가족관계의 등록 등에 관한 법률 제39조이다. 다음 괄호 안에 들어갈 내용으로 옳은 것은?","d":"제39조(신고의 추후 보완) 시․읍․면의 장은 신고를 수리한 경우에 흠이 있어 등록부에 기록을 할 수 없을 때에는 (      ) 하여금 보완하게 하여야 한다. 이 경우 제38조를 준용한다.","o":["신고인으로","신고사건의 본인으로","신고의무자로","신고인 또는 신고의무자로","신고인 또는 신고사건의 본인으로"],"a":4}},{"y":2025,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2025_31-46","t":"다음은 가족관계의 등록 등에 관한 법률 중 일부 조문들을 열거한 것이다. 다음 괄호 안에 들어갈 내용이 ‘그 사실을 안 날’인 경우를 모두 고른 것은?","c":"A","mc":{"s":"다음은 가족관계의 등록 등에 관한 법률 중 일부 조문들을 열거한 것이다. 다음 괄호 안에 들어갈 내용이 ‘그 사실을 안 날’인 경우를 모두 고른 것은?","d":"ㄱ.국적상실의 신고는 배우자 또는 4촌 이내의 친족이 (     )부터 1개월 이내에 하여야 한다.\nㄴ.인지된 태아가 사체로 분만된 경우에 출생의 신고의무자는 (     )부터 1개월 이내에 그 사실을 신고하여야 한다. 다만, 유언집행자가 제59조의 신고를 하였을 경우에는 유언집행자가 그 신고를 하여야 한다.\nㄷ.등록되어 있는지가 분명하지 아니한 사람 또는 등록되어 있지 아니하거나 등록할 수 없는 사람에 관한 신고가 수리된 후 그 사람에 관하여 등록되어 있음이 판명된 때 또는 등록할 수 있게 된 때에는 신고인 또는 신고사건의 본인은 (     )부터 1개월 이내에 수리된 신고사건을 표시하여 처음 그 신고를 수리한 시․읍․면의 장에게 그 사실을 신고하여야 한다.\nㄹ.유언에 의한 인지의 경우에는 유언집행자는 (     )부터 1개월 이내에 인지에 관한 유언서등본 또는 유언녹음을 기재한 서면을 첨부하여 제55조 또는 제56조에 따라 신고를 하여야 한다.","o":["ㄱ, ㄹ","ㄴ, ㄷ","ㄷ, ㄹ","ㄱ, ㄴ, ㄷ","ㄱ, ㄴ, ㄹ"],"a":4}},{"y":2025,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2025_31-47-1","t":"동사무소에는 가족관계등록신고서류편철장을 비치하여야 하고, 그 보존기간은 3년으로 한다.","ox":"O","m":"①","c":"A","tp":"동장 및 동사무소"},{"y":2025,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2025_31-47-2","t":"동장은 신고를 게을리 한 사람을 안 때에는 상당한 기간을 정하여 신고의무자에 대하여 그 기간 내에 신고할 것을 최고하여야 한다.","ox":"X","m":"②","c":"A","tp":"동장 및 동사무소"},{"y":2025,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2025_31-47-3","t":"증서의 등본은 신분행위 당사자 1명이 동장에게 우편의 방법을 이용하거나 직접 제출할 수 있다.","ox":"X","m":"③","c":"A","tp":"동장 및 동사무소"},{"y":2025,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2025_31-47-4","t":"사망장소의 동장은 사망신고를 할 수 없다.","ox":"X","m":"④","c":"A","tp":"동장 및 동사무소"},{"y":2025,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2025_31-47-5","t":"동장은 수리한 신고서류의 부본을 접수순서에 따라 편철한 후 각 장마다 장수를 기재하고 3개월마다 목록을 붙여 보존한다.","ox":"X","m":"⑤","c":"A","tp":"동장 및 동사무소"},{"y":2025,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2025_31-48","t":"다음은 가족관계의 등록 등에 관한 법률 제90조이다. 다음 괄호 안에 들어갈 내용으로 옳은 것은?","c":"A","mc":{"s":"다음은 가족관계의 등록 등에 관한 법률 제90조이다. 다음 괄호 안에 들어갈 내용으로 옳은 것은?","d":"제90조(등록불명자 등의 사망) ① 사망자에 대하여 등록이 되어 있는지 여부가 분명하지 아니하거나 사망자를 인식할 수 없는 때에는 경찰공무원은 검시조서를 작성․첨부하여 지체 없이 사망지의 시․읍․면의 장에게 사망의 통보를 하여야 한다.\n② 사망자가 등록이 되어 있음이 판명되었거나 사망자의 신원을 알 수 있게 된 때에는 경찰공무원은 지체 없이 사망지의 시․읍․면의 장에게 그 취지를 통보하여야 한다.\n③ 제1항의 통보가 있은 후에 제85조에서 정한 사람이 사망자의 신원을 안 때에는 그 날부터 (    ) 이내에 사망의 신고를 하여야 한다.","o":["1개월","20일","10일","7일","5일"],"a":3}},{"y":2025,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2025_31-50","t":"다음 중 가족관계의 등록 등에 관한 법률에 따라 소의 상대방도 신고할 수 있는 경우는 모두 몇 개인가?","c":"A","mc":{"s":"다음 중 가족관계의 등록 등에 관한 법률에 따라 소의 상대방도 신고할 수 있는 경우는 모두 몇 개인가?","d":"ㄱ.친양자 파양의 재판이 확정된 경우\nㄴ.사실상 혼인관계 존재확인의 재판이 확정된 경우\nㄷ.혼인취소의 재판이 확정된 경우\nㄹ.입양취소의 재판이 확정된 경우\nㅁ.미성년후견인의 선임재판이 확정된 경우","o":["1개","2개","3개","4개","5개"],"a":3}},{"y":2026,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2026_32-42","t":"다음 중 시(구)⋅읍⋅면의 장이 수리할 수 있는 경우에 해당하는 신고는 모두 몇 개인가?","c":"A","mc":{"s":"다음 중 시(구)⋅읍⋅면의 장이 수리할 수 있는 경우에 해당하는 신고는 모두 몇 개인가?","d":"ㄱ.성명란의 한자란에 한글과 한자(인명용 한자의 제한 범위 내의 것)를 혼합하여 표기한 출생신고\nㄴ.한국인 부와 외국인 모 사이에 출생한 혼인 중의 자에 대하여 모의 나라의 신분등록부상 이름(이름자가 5자를 초과하는 문자이며, 성은 포함되지 않음)을 기재한 출생신고\nㄷ.사망의 연월일을 ‘미상’으로 기재한 사망신고\nㄹ.사망장소를 도로명주소의 ‘도로명’까지만 기재한 사망신고","o":["없음","1개","2개","3개","4개"],"a":4}},{"y":2026,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2026_32-45-1","t":"추후보완의 최고는 해당 가족관계등록부의 등록기준지와 무관하게 전국 시(구)⋅읍⋅면의 장이 할 수 있다.","ox":"X","m":"①","c":"A","tp":"추후보완(신고)"},{"y":2026,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2026_32-45-2","t":"등록기준지의 시⋅읍⋅면의 장은 법무부장관의 국적관련 통보로 가족관계등록부를 작성할 수 없는 경우 법무부장관에게 재통보를 요청하고, 국적관련 통보 대상자의 추후보완신고를 받아 가족관계등록부를 작성할 수 있다.","ox":"O","m":"②","c":"A","tp":"추후보완(신고)"},{"y":2026,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2026_32-45-3","t":"부가 출생신고한 자녀가 가족관계등록부상 모와 친생자관계부존재 확인판결이 확정된 경우 친생모를 기록하려면 친자관계를 확인하는 판결(판결 주문이 아닌 이유에 설시한 판결은 해당하지 아니한다)에 의한 정정절차를 거치거나, 사건본인의 출생신고인(신고인이 추후보완신고할 수 없을 때에는 다른 출생신고의무자)이 친생모와의 친생자관계 및 출생 당시 친생모가 유부녀가 아님을 소명하여 출생의 추후보완신고를 하여야 한다.","ox":"O","m":"③","c":"A","tp":"추후보완(신고)"},{"y":2026,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2026_32-45-4","t":"출생신고 시 출생자의 이름을 한글로만 신고한 경우 추후에 한자 이름을 함께 기록하게 하려면 추후보완신고로는 할 수 없다.","ox":"O","m":"④","c":"A","tp":"추후보완(신고)"},{"y":2026,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2026_32-45-5","t":"접수장의 사건명은 신고의 종류에 따르되, 신고의 추후보완의 경우에는 원래의 신고의 접수번호도 부기한다.","ox":"O","m":"⑤","c":"A","tp":"추후보완(신고)"},{"y":2026,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2026_32-46-1","t":"부모의 이혼을 인용함과 동시에 친권자를 지정한 판결이 확정된 때에는 이혼신고가 수리되기 전에 친권자 지정 신고를 할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2026_32-46-2","t":"친권자가 미성년자의 친부와 혼인한 때에는 민법 제909조 제4항에 따라 친권자를 정하여 1개월 이내에 그 사실을 신고하여야 한다.","ox":"X","m":"②","c":"A","tp":"친권자 지정 신고"},{"y":2026,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2026_32-46-3","t":"친권자 지정에 관하여는 신고와 가정법원의 기록 촉탁이 경합될 수 있다.","ox":"O","m":"③","c":"A","tp":"친권자 지정 신고"},{"y":2026,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2026_32-46-4","t":"포태 중인 자의 친권자 지정 신고기간은 협의이혼신고가 수리된 때부터 기산한다.","ox":"X","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2026_32-46-5","t":"부모의 혼인이 취소된 때에도 협의에 의한 친권자 지정 신고를 할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2026_32-48","t":"다음 중 사망진단서 또는 검안서를 첨부하여야 하는 경우는?","c":"A","mc":{"s":"다음 중 사망진단서 또는 검안서를 첨부하여야 하는 경우는?","d":"","o":["재소 중 사망한 사람의 사체를 찾아갈 사람이 없어 교도소장이 교도소 소재지의 시⋅읍⋅면의 장에게 사망의 통보를 하는 경우","장사 등에 관한 법률 제12조에 따라 시장 등이 무연고 사망자 등을 처리한 후 사망지⋅매장지 또는 화장지의 시⋅읍⋅면의 장에게 통보하는 경우","항해 중에 사망한 사람에 대하여 선장이 사망에 관한 항해일지 등본을 선박이 처음 도착한 항구를 관할하는 시⋅읍⋅면의 장 또는 재외국민 가족관계등록사무소의 가족관계등록관에게 발송한 경우","실종선고를 청구한 사람이 재판이 확정되어 실종선고의 신고를 하는 경우","수해, 화재나 그 밖의 재난으로 인하여 사망한 사람을 조사한 관공서에서 사망지의 시⋅읍⋅면의 장에게 통보한 경우"],"a":1}},{"y":2026,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2026_32-50","t":"다음 중 가족관계의 등록 등에 관한 법률 제23조의2에 따른 전자문서를 이용한 신고의 처리 주체가 아닌 것을 모두 고른 것은?","c":"A","mc":{"s":"다음 중 가족관계의 등록 등에 관한 법률 제23조의2에 따른 전자문서를 이용한 신고의 처리 주체가 아닌 것을 모두 고른 것은?","d":"ㄱ.재외국민 가족관계등록사무소의 가족관계등록관\nㄴ.신고인의 현재지 시⋅읍⋅면의 장\nㄷ.외국인의 거주지 시⋅읍⋅면의 장\nㄹ.신고사건 본인의 주민등록지 시⋅읍⋅면의 장\nㅁ.신고인의 주소지 시⋅읍⋅면의 장","o":["ㄱ, ㄷ","ㄱ, ㅁ","ㄴ, ㄷ","ㄴ, ㄹ","ㄷ, ㄹ"],"a":4}}],"13":[{"y":2016,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2016_22-42","t":"가족관계등록부에 기록할 사항 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"가족관계등록부에 기록할 사항 중 가장 옳지 않은 것은?","d":"","o":["등록기준지","성명ㆍ본ㆍ성별ㆍ출생연월일 및 주민등록번호","출생ㆍ혼인ㆍ사망 등 가족관계의 발생 및 변동에 관한 사항","가족으로 기록할 자가 대한민국 국민이 아닌 사람(외국인)인 경우에는 성명ㆍ성별ㆍ출생연월일ㆍ국적ㆍ주민등록번호 및 등록기준지","그 밖에 가족관계에 관한 사항으로서 대법원규칙으로 정하는 사항"],"a":4}},{"y":2016,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2016_22-43-1","t":"가족관계의 발생 및 변동사항에 관한 등록과 그 증명에 관한 사무는 대법원이 관장한다.","ox":"O","m":"①","c":"A","tp":"가족관계등록사무"},{"y":2016,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2016_22-43-2","t":"대법원장은 등록사무의 처리에 관한 권한을 시ㆍ읍ㆍ면의 장(도농복합형태의 시에 있어서 동지역에 대하여는 시장, 읍ㆍ면지역에 대하여는 읍ㆍ면장으로 한다)에게 위임한다.","ox":"O","m":"②","c":"A","tp":"가족관계등록사무"},{"y":2016,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2016_22-43-3","t":"특별시 및 광역시와 구를 둔 시에 있어서는 시, 시장 또는 시의 사무소라 함은 각각 구, 구청장 또는 구의 사무소를 말한다. 다만 광역시에 있어서 군지역에 대하여는 읍ㆍ면, 읍ㆍ면의 장 또는 읍ㆍ면의 사무소를 말한다.","ox":"O","m":"③","c":"A","tp":"가족관계등록사무"},{"y":2016,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2016_22-43-4","t":"대법원장은 등록사무의 감독에 관한 권한을 시ㆍ읍ㆍ면의 사무소 소재지를 관할하는 가정법원장에게 위임한다. 다만 가정법원지원장은 가정법원장의 명을 받아 그 관할 구역 내의 등록사무를 감독한다.","ox":"O","m":"④","c":"A","tp":"가족관계등록사무"},{"y":2016,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2016_22-43-5","t":"가족관계의 발생 및 변동사항의 등록에 관한 신고는 반드시 등록기준지에서 신고하여야 하며, 가족관계등록사무는 신고인의 등록기준지의 시ㆍ읍ㆍ면의 장이 처리하여야 한다.","ox":"X","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2016_22-44-1","t":"외국에 거주하고 있는 한국인은 그 지역을 관할하는 재외공관의 장 또는 재외공관에서 근무하는 가족관계등록관에게 가족관계등록신고를 할 수 있으나(재외공관에서 근무하는 가족관계등록관에 대한 신고는 사망신고에 한한다), 다른 지역을 관할하는 재외공관의 장 또는 재외공관에서 근무하는 가족관계등록관에게 가족관계등록신고를 할 수는 없다.","ox":"X","m":"①","c":"A","tp":"재외국민과 관련한 가족관계등록사무"},{"y":2016,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2016_22-44-2","t":"재외국민 가족관계등록사무소에 접수되는 등록사건은 각 가족관계등록관이 독립하여 처리한다.","ox":"O","m":"②","c":"A","tp":"재외국민과 관련한 가족관계등록사무"},{"y":2016,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2016_22-44-3","t":"재외공관의 장이 수리하여 재외국민 가족관계등록사무소로 송부하는 사건 중 신고(신청)인의 전자적 송부에 대한 신청이 있는 사건은 전자적으로 송부한다.","ox":"O","m":"③","c":"A","tp":"재외국민과 관련한 가족관계등록사무"},{"y":2016,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2016_22-44-4","t":"재외국민 가족관계등록사무소의 가족관계등록관은 공인전자우편 방식을 이용한 재외공관의 등록사항별 증명서 교부 등에 관한 사무처리지침에 따라 증명서 발급 사무를 처리한다.","ox":"O","m":"④","c":"A","tp":"재외국민과 관련한 가족관계등록사무"},{"y":2016,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2016_22-44-5","t":"재외국민 가족관계등록사무소 소속 가족관계등록관은 처리 기준이 불분명한 사건 등 그 처리가 어려운 사건에 대해서는 같은 사건을 전담하는 가족관계등록관 간의 협의를 제안할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"재외국민과 관련한 가족관계등록사무"},{"y":2017,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2017_23-43","t":"다음 중 가족관계의 등록 등에 관한 법률 제117조에 의하여 3년 이하의 징역 또는 1천만 원 이하의 벌금에 처해질 수 있는 사람은 몇 명인가?","c":"A","mc":{"s":"다음 중 가족관계의 등록 등에 관한 법률 제117조에 의하여 3년 이하의 징역 또는 1천만 원 이하의 벌금에 처해질 수 있는 사람은 몇 명인가?","d":"ㄱ.제공받은 등록전산정보자료를 본래의 목적 외의 용도로 이용하거나 활용한 사람\nㄴ.거짓이나 부정한 방법으로 다른 사람의 등록사항별 증명서를 발급받은 사람\nㄷ.그 이유를 설명하지 아니하고 등록사항별 증명서의 상세증명서 제출을 요구한 사람\nㄹ.제출받은 등록사항별 증명서를 사용목적 외의 용도로 사용한 사람","o":["없음","1명","2명","3명","전부"],"a":3}},{"y":2017,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2017_23-45-1","t":"등록사항별 증명서 발급 뿐만 아니라 제적 등ㆍ초본의 발급도 인터넷으로 할 수 있다.","ox":"O","m":"①","c":"A","tp":"인터넷에 의한 등록사항별 증명서 발급 등"},{"y":2017,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2017_23-45-2","t":"인터넷에 의한 등록사항별 증명서의 발급은 본인 또는 배우자, 직계혈족만이 신청할 수 있고, 형제자매는 신청할 수 없다.","ox":"X","m":"②","c":"A","tp":"인터넷에 의한 등록사항별 증명서 발급 등"},{"y":2017,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2017_23-45-3","t":"친양자입양관계에 관한 등록사항별 증명서의 발급은 친양자가 성년이 되어 신청하는 경우에 한한다.","ox":"O","m":"③","c":"A","tp":"인터넷에 의한 등록사항별 증명서 발급 등"},{"y":2017,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2017_23-45-4","t":"인터넷에 의하여 발급한 경우 신청인이 아포스티유 신청을 위하여 외교부에 증명서 발급 정보의 전송을 원하는 때에는 전자가족관계등록시스템을 통하여 전송할 수 있다.","ox":"O","m":"④","c":"A","tp":"인터넷에 의한 등록사항별 증명서 발급 등"},{"y":2017,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2017_23-45-5","t":"타인으로부터 등록사항별 증명서를 교부받은 자는 인터넷을 통하여 그 발급내역(신청 구분, 종류, 발급일시 등)을 확인할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"인터넷에 의한 등록사항별 증명서 발급 등"},{"y":2017,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2017_23-46-1","t":"재외국민은 가족관계의 등록 등에 관한 법률이 정하는 바에 따라 그 지역을 관할하는 대한민국 재외공관의 장에게 신고를 할 수 있다.","ox":"O","m":"①","c":"A","tp":"재외국민의 가족관계등록"},{"y":2017,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2017_23-46-2","t":"대한민국 재외공관의 장은 가족관계의 등록 등에 관한 법률 제34조 및 제35조에 따라 재외국민의 신고서류를 수리한 경우에는 외교부장관을 경유하여 반드시 재외국민 가족관계등록사무소의 가족관계등록관에게 송부하여야 한다.","ox":"O","m":"②","c":"A","tp":"재외국민의 가족관계등록"},{"y":2017,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2017_23-46-3","t":"재외국민 가족관계등록사무소의 가족관계등록관이 과태료 부과 대상이 있음을 안 때에는 신고의무자가 재외국민인 경우 그 지역을 관할하는 재외공관의 장에게 그 사실을 통지한다.","ox":"X","m":"③","c":"A","tp":"재외국민의 가족관계등록"},{"y":2017,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2017_23-46-4","t":"부부 중 한쪽이 재외국민인 경우에 재외국민인 당사자는 그 거주지를 관할하는 재외공관의 장에게 협의이혼의사확인신청을 할 수 있다.","ox":"O","m":"④","c":"A","tp":"재외국민의 가족관계등록"},{"y":2017,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2017_23-46-5","t":"재외공관에서 수리한 신고서류는 그 부본을 접수순서에 따라 편철한 후 2년간 보존한다.","ox":"O","m":"⑤","c":"A","tp":"재외국민의 가족관계등록"},{"y":2017,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2017_23-50-1","t":"가족관계증명서의 일반증명서에는 자녀 중 생존한 현재의 혼인 중의 자녀에 관한 사항만이 기재된다.","ox":"O","m":"①","c":"A","tp":"가족관계등록부의 기록사항"},{"y":2017,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2017_23-50-2","t":"혼인관계증명서의 일반증명서에는 전혼에 관한 사항은 기재되지 아니하고 현재의 혼인에 관한 사항이 기재된다.","ox":"O","m":"②","c":"A","tp":"가족관계등록부의 기록사항"},{"y":2017,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2017_23-50-3","t":"기본증명서의 상세증명서에는 국적상실, 국적취득 및 회복 등에 관한 사항이 기재된다.","ox":"O","m":"③","c":"A","tp":"가족관계등록부의 기록사항"},{"y":2017,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2017_23-50-4","t":"혼인관계증명서의 상세증명서에는 혼인 및 이혼에 관한 사항이 기재된다.","ox":"O","m":"④","c":"A","tp":"가족관계등록부의 기록사항"},{"y":2017,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2017_23-50-5","t":"특정증명서는 가족관계의 등록 등에 관한 법률 부칙에 따라 아직 시행되고 있지 아니하다.","ox":"X","m":"⑤","c":"A","tp":"가족관계등록부의 기록사항"},{"y":2018,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2018_24-50","t":"등록기준지에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"등록기준지에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["등록기준지는 비송사건의 관할법원 결정 기준, 검색 기능, 종전 호적과의 연결 등을 위하여 도입한 기능적 개념이다.","2008. 1. 1. 이후 출생하는 사람의 등록기준지는 부 또는 모가 자유로이 정할 수 있다.","위 ②항의 경우 부 또는 모의 특별한 의사표시가 없는 때에는 자녀가 따르는 성과 본을 가진 부 또는 모의 등록기준지를 자녀의 등록기준지로 한다.","등록기준지는 자유롭게 변경할 수 있지만, 하나의 가족관계증명서에 나타나는 가족들 사이의 등록기준지는 같아야 한다.","등록기준지 변경신고는 새롭게 변경하고자 하는 등록기준지의 시(구)․읍․면의 장에게 하여야 한다. 2018년 6월 23일 시행 제24회 법무사 제1차 시험"],"a":4}},{"y":2019,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2019_25-43","t":"다음에 열거한 가족관계등록부 폐쇄사유 중 가족관계의 등록 등에 관한 규칙에서 정한 사유만으로 묶인 것은?","c":"A","mc":{"s":"다음에 열거한 가족관계등록부 폐쇄사유 중 가족관계의 등록 등에 관한 규칙에서 정한 사유만으로 묶인 것은?","d":"A.이중으로 작성된 경우\nB.실종선고를 받은 경우\nC.착오 또는 부적법하게 작성된 경우\nD.사망한 경우\nE.부재선고를 받은 경우\nF.정정된 가족관계등록부가 이해관계인에게 현저히 부당하다고 인정되어 재작성하는 경우","o":["A, B, C","D, E, F","C, E, F","B, D, F","A, C, F 22-22"],"a":5}},{"y":2019,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2019_25-48-1","t":"재외국민 가족관계등록사무소에는 가족관계등록관인 소장을 둔다.","ox":"O","m":"①","c":"A","tp":"재외국민 가족관계등록사무소 및 가족관계등록관"},{"y":2019,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2019_25-48-2","t":"재외국민은 가족관계등록관에게 등록기준지 변경신고를 할 수 있다.","ox":"X","m":"②","c":"A","tp":"재외국민 가족관계등록사무소 및 가족관계등록관"},{"y":2019,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2019_25-48-3","t":"재외국민에 관한 등록사무의 처리 및 지원을 위하여 법원행정처에 재외국민 가족관계등록사무소를 둔다.","ox":"O","m":"③","c":"A","tp":"재외국민 가족관계등록사무소 및 가족관계등록관"},{"y":2019,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2019_25-48-4","t":"대법원장은 재외국민에 관한 등록사무를 가족관계등록관으로 하여금 처리하게 할 수 있다.","ox":"O","m":"④","c":"A","tp":"재외국민 가족관계등록사무소 및 가족관계등록관"},{"y":2019,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2019_25-48-5","t":"가족관계등록관이 과태료 부과 대상이 있음을 안 때에는 신고의무자의 등록기준지 시·읍·면의 장에게 그 사실을 통지하고, 통지를 받은 시·읍·면의 장이 과태료를 부과·징수한다.","ox":"O","m":"⑤","c":"A","tp":"재외국민 가족관계등록사무소 및 가족관계등록관"},{"y":2019,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2019_25-49-1","t":"출생신고인이 부 또는 모인 경우에는 그 성명의 기록을 생략하여서는 안 된다.","ox":"X","m":"①","c":"A","tp":"가족관계등록부의 기록"},{"y":2019,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2019_25-49-2","t":"부가 인지하지 아니한 혼인외의 출생자라도 부의 성과 본을 알 수 있는 경우에는 부의 성과 본을 따라 기록될 수 있다.","ox":"O","m":"②","c":"A","tp":"가족관계등록부의 기록"},{"y":2019,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2019_25-49-3","t":"한쪽 배우자에 대하여 실종선고의 신고가 있는 때에는 다른 배우자의 가족관계등록부에도 그 취지를 기록하여야 한다.","ox":"O","m":"③","c":"A","tp":"가족관계등록부의 기록"},{"y":2019,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2019_25-49-4","t":"미성년후견에 관한 사항은 미성년자의 가족관계등록부의 일반등록사항란에 기록한다.","ox":"O","m":"④","c":"A","tp":"가족관계등록부의 기록"},{"y":2019,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2019_25-49-5","t":"동일한 사건에 수개의 신고가 수리된 경우에는 먼저 수리된 신고에 따라 가족관계등록부에 기록하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"가족관계등록부의 기록"},{"y":2019,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2019_25-50","t":"다음 중 교부(발급) 또는 열람을 청구(신청)할 수 있는 사람의 범위가 가장 좁은 것은?","c":"A","mc":{"s":"다음 중 교부(발급) 또는 열람을 청구(신청)할 수 있는 사람의 범위가 가장 좁은 것은?","d":"","o":["무인증명서발급기에 의한 가족관계증명서 발급","인터넷에 의한 가족관계증명서 발급","인터넷에 의한 가족관계등록부의 기록사항 열람","시․읍․면의 장에 의한 가족관계증명서 교부","공인전자우편 방식을 이용한 가족관계증명서 교부 2019년 6월 22일 시행 제25회 법무사 제1차 시험"],"a":1}},{"y":2020,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2020_26-49","t":"다음에 열거한 기록사항 중 가족관계의 등록 등에 관한 규칙 제21조의3에 따라 영문으로 작성된 등록사항별 증명서에 기록될 수 있는 사항은 모두 몇 개인가?","c":"A","mc":{"s":"다음에 열거한 기록사항 중 가족관계의 등록 등에 관한 규칙 제21조의3에 따라 영문으로 작성된 등록사항별 증명서에 기록될 수 있는 사항은 모두 몇 개인가?","d":"ㄱ.배우자의 성명․성별․출생연월일 및 주민등록번호\nㄴ.본인의 출생에 관한 사항\nㄷ.자녀의 성명․성별․출생연월일 및 주민등록번호\nㄹ.본인의 현재의 혼인에 관한 사항","o":["없음","1개","2개","3개","전부"],"a":4}},{"y":2020,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2020_26-50","t":"다음 중 가족관계등록관이 처리할 수 있는 업무끼리 나열된 것은?","c":"A","mc":{"s":"다음 중 가족관계등록관이 처리할 수 있는 업무끼리 나열된 것은?","d":"","o":["직권에 의한 가족관계등록부의 정정 - 무연고자 등의 사망 통보 수리","과태료 부과ㆍ징수 - 무연고자 등의 사망 통보 수리","직권에 의한 가족관계등록부의 정정 - 신고 불수리의 통지","과태료 부과ㆍ징수 - 국적취득의 통보 수리","과태료 부과ㆍ징수 - 신고서류의 조사 및 시정지시 2020년 6월 20일 시행 제26회 법무사 제1차 시험"],"a":3}},{"y":2021,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2021_27-42-1","t":"특정증명서는 가족관계증명서, 기본증명서, 혼인관계증명서 및 친양자입양관계증명서에 대하여 발급한다.","ox":"X","m":"①","c":"A","tp":"등록사항별 증명서"},{"y":2021,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2021_27-42-2","t":"가족관계증명서에 대한 특정증명서는 부모, 배우자 및 자녀 중 신청인이 선택한 사람의 성명, 성별, 출생연월일 및 주민등록번호를 기재하며, 신청인은 사람을 복수로 선택할 수 있다.","ox":"O","m":"②","c":"A","tp":"등록사항별 증명서"},{"y":2021,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2021_27-42-3","t":"혼인관계증명서에 대한 특정증명서는 일반등록사항란의 기록 중에서 신청인이 선택한 과거의 배우자 한 사람과의 혼인에 관한 사항을 현출하고, 현재의 혼인에 관한 사항은 현출하지 아니한다. 한편 같은 배우자와 두 번 이상 혼인한 기록이 있는 때에는 신청인이 선택한 하나의 혼인에 관한 사항을 현출한다.","ox":"O","m":"③","c":"A","tp":"등록사항별 증명서"},{"y":2021,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2021_27-42-4","t":"가족관계증명서에 대한 일반증명서는 특정등록사항란 중 혼인 외의 자녀, 전혼 중의 자녀, 사망한 자녀를 제외하고 작성한다.","ox":"O","m":"④","c":"A","tp":"등록사항별 증명서"},{"y":2021,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2021_27-42-5","t":"영문으로 작성되는 등록사항별 증명서의 경우 본인의 등록부가 폐쇄되거나 본인이 여권을 발급받은 사실이 없는 경우 그 발급이 제한될 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2021_27-44-1","t":"외국인인 배우자의 특정등록사항은 국민인 상대방 배우자의 가족관계증명서 및 혼인관계증명서에 기록하며, 외국인인 자녀의 특정등록사항은 국민이 인지, 입양, 친양자입양한 자녀인 경우에만 기록한다.","ox":"O","m":"①","c":"A","tp":"외국인 기록대상자"},{"y":2021,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2021_27-44-2","t":"귀화에 의하여 대한민국 국적을 취득한 사람에 대하여 귀화통보를 하는 경우, 그 인명은 해당 외국의 원지음을 귀화통보서에 한글과 한자로 표기하여야 하고, 가족관계등록부에는 귀화통보서에 표기한 원지음대로 한글과 한자로 기록하여야 한다.","ox":"X","m":"②","c":"A","tp":"외국인 기록대상자"},{"y":2021,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2021_27-44-3","t":"가족관계등록신고서에 기재된 국호와 지명에 대한 해당 외국 원지음의 한글표기가 외래어 표기법에 맞지 아니하는 경우, 시(구)ㆍ읍ㆍ면의 장은 외래어 표기법에 맞는 표기를 부전지에 적어 그 가족관계등록신고서에 붙이고, 가족관계등록부에는 외래어 표기법에 맞추어 기록하여야 한다.","ox":"O","m":"③","c":"A","tp":"외국인 기록대상자"},{"y":2021,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2021_27-44-4","t":"한국인 부가 외국인인 자녀를 인지하는 경우 종전 성(姓) 계속 사용에 관한 부모의 협의가 없는 한, 인지의 효력으로 외국인 자녀의 성은 한국인 부의 성본으로 변경된다.","ox":"O","m":"④","c":"A","tp":"외국인 기록대상자"},{"y":2021,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2021_27-44-5","t":"국제가족관계등록사건에서 외국증서와 가족관계등록부에 각 기재된 당사자의 성명이 불일치하는 경우, 신고인은 원칙적으로 우리나라 또는 외국 관공서가 발행한 동일성을 증명하는 서면을 신고서류와 함께 제출하여야 한다. 다만, 신고서류만으로 동일인임이 명백하거나 사소한 착오나 유루가 있는 것에 불과한 때에는 동일성을 증명하는 서면 없이 신고서류를 수리할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"외국인 기록대상자"},{"y":2022,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2022_28-41-1","t":"가족관계등록부의 주민등록번호의 기록은 주민등록법 제7조의2 및 제15조에 따른 주민등록번호 부여 통보에 의하여야 한다.","ox":"O","m":"①","c":"A","tp":"가족관계등록부상 주민등록번호의 기록, 정정 및 공시제한 등"},{"y":2022,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2022_28-41-2","t":"가족관계등록부상 주민등록번호의 기록이 누락되었을 경우 본인 또는 동거하는 친족이 주민등록표 등·초본을 첨부하여 그 기록을 신청하는 때에는 가족관계등록공무원은 감독법원의 허가 없이 직권으로 이를 기록한다. 다만, 본인이 신청하는 경우에는 주민등록표 등·초본의 첨부 없이 주민등록증을 제시받아 가족관계등록공무원이 그 내용을 확인한 후 주민등록증을 복사하여 신청서에 첨부하고 기록의 절차를 취하여야 한다.","ox":"O","m":"②","c":"A","tp":"가족관계등록부상 주민등록번호의 기록, 정정 및 공시제한 등"},{"y":2022,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2022_28-41-3","t":"주민등록법에 따른 신고사항과 가족관계의 등록 등에 관한 법률에 따른 신고사항이 같으면 가족관계의 등록 등에 관한 법률에 따른 신고로써 주민등록법에 따른 신고를 갈음하는데, 주민등록신고사항 중 출생, 사망 또는 실종, 등록기준지의 변경, 성명·생년월일 또는 성별의 변경이 이에 해당한다.","ox":"O","m":"③","c":"A","tp":"가족관계등록부상 주민등록번호의 기록, 정정 및 공시제한 등"},{"y":2022,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2022_28-41-4","t":"주민등록 신고대상자의 가족관계등록 신고지와 주민등록지가 다를 경우에 가족관계등록 신고지의 시(구)·읍·면의 장이 가족관계등록신고를 받아 가족관계등록부의 기록사항을 변경하면 지체 없이 그 신고사항을 주민등록지의 시장·군수 또는 구청장에게 통보하여야 한다.","ox":"O","m":"④","c":"A","tp":"가족관계등록부상 주민등록번호의 기록, 정정 및 공시제한 등"},{"y":2022,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2022_28-41-5","t":"주민등록법 제7조의4에 따라 주민등록번호를 변경한 사람 또는 변경하고자 하는 사람은 변경되었거나 변경될 주민등록번호의 공시가 제한될 대상자를 지정하여 공시제한을 신청할 수 있고, 신청인은 공시제한 신청서를 신청사건 본인의 등록기준지 또는 신청인의 주소지나 현재지의 시(구)·읍·면의 사무소에 출석하여 제출하여야 하고, 신청인의 주소지나 현재지의 동사무소에는 제출할 수 없다.","ox":"X","m":"⑤","c":"A","tp":"가족관계등록부상 주민등록번호의 기록, 정정 및 공시제한 등"},{"y":2022,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2022_28-43-1","t":"등록사건 처리에 관하여 시(구)·읍·면의 장을 대리하는 사람은 등록에 관한 증명서 발급사무를 제외하고 자기 또는 자기와 4촌 이내의 친족에 관한 등록사건에 관하여는 그 직무를 행할 수 없다.","ox":"O","m":"①","c":"A","tp":"가족관계등록사무의 처리"},{"y":2022,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2022_28-43-2","t":"등록사건 처리에 관하여 시(구)·읍·면의 장을 대리하는 사람이 자기 또는 자기와 4촌 이내의 친족에 관한 등록사건에 대하여 직무를 행한 경우라도 기록사항에 잘못이 없으면 가족관계등록부의 정정을 할 필요가 없다.","ox":"O","m":"②","c":"A","tp":"가족관계등록사무의 처리"},{"y":2022,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2022_28-43-3","t":"시(구)·읍·면의 장이 신고를 수리하지 아니한 때에는 그 사유를 지체 없이 신고인에게 서면으로 통지하여야 하나, 대법원규칙으로 정하는 가족관계등록에 관한 신고는 전산정보처리조직을 이용하여 전자문서로 할 수 있고 그에 따른 신고의 불수리 통지는 전산정보처리조직을 이용하여 전자문서로 할 수 있다.","ox":"O","m":"③","c":"A","tp":"가족관계등록사무의 처리"},{"y":2022,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2022_28-43-4","t":"시(구)·읍·면을 달리하여 동일한 사건에 수개의 신고가 수리된 경우에, 뒤에 수리된 신고에 따라 가족관계등록부에 기록한 때에는 먼저 수리한 시(구)·읍·면의 장이 먼저 수리된 신고에 맞추어 가족관계등록부의 기록을 정정하여야 한다.","ox":"X","m":"④","c":"A","tp":"가족관계등록사무의 처리"},{"y":2022,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2022_28-43-5","t":"시(구)에 있어서 출생·사망의 신고는 그 신고의 장소가 신고사건 본인의 주민등록지 또는 주민등록을 할 지역과 같은 경우에는 신고사건 본인의 주민등록지 또는 주민등록을 할 지역을 관할하는 동을 거쳐 할 수 있고, 이 경우 동장은 소속 시장 또는 구청장을 대행하여 신고서를 수리한다.","ox":"O","m":"⑤","c":"A","tp":"가족관계등록사무의 처리"},{"y":2022,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2022_28-45-1","t":"본인 또는 배우자, 직계혈족(이하 ‘본인등’이라 함)은 수수료를 납부하고 등록사항별 증명서의 교부를 청구할 수 있다.","ox":"O","m":"①","c":"A","tp":"등록사항별 증명서 발급 등"},{"y":2022,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2022_28-45-2","t":"본인이 등록사항별 증명서 발급(영문증명서는 제외한다)을 신청하는 경우에는 신청서를 작성하지 아니할 수 있다.","ox":"O","m":"②","c":"A","tp":"등록사항별 증명서 발급 등"},{"y":2022,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2022_28-45-3","t":"본인등의 대리인이 증명서 발급을 청구하는 경우에는 신청서에 본인등이 서명 또는 날인한 위임장과 신분증명서 사본을 제출하여야 하며, 여기서 위임장은 원본이어야 하므로 변호사가 등록사항별 증명서의 교부청구의 위임취지가 명확하게 기재된 소송위임장의 사본을 제출하더라도 증명서를 교부할 수 없다.","ox":"X","m":"③","c":"A","tp":"등록사항별 증명서 발급 등"},{"y":2022,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2022_28-45-4","t":"등록사항별 증명서의 교부를 청구하는 경우에는 대상자의 성명과 등록기준지를 정확하게 기재하여야 한다. 다만, 본인등과 그 대리인의 경우에는 대상자의 성명과 주민등록번호로도 교부를 청구할 수 있다.","ox":"O","m":"④","c":"A","tp":"등록사항별 증명서 발급 등"},{"y":2022,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2022_28-45-5","t":"국가 또는 지방자치단체, 공공기관이 전자정부법에 따라 전자문서를 이용하여 근거법령과 사유를 기재한 공문을 송부한 경우에는 신청서 작성과 신분증 제출을 생략할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"등록사항별 증명서 발급 등"},{"y":2022,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2022_28-48-1","t":"친양자입양관계증명서는 친양자가 성년이 되어 신청하는 경우에 교부를 청구할 수 있다.","ox":"O","m":"①","c":"A","tp":"친양자입양관계증명서 교부청구의 특례"},{"y":2022,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2022_28-48-2","t":"혼인당사자가 민법 제809조(근친혼 등의 금지)에 관한 친족관계를 파악하고자 하는 경우에 친양자입양관계증명서의 교부를 청구할 수 있다.","ox":"O","m":"②","c":"A","tp":"친양자입양관계증명서 교부청구의 특례"},{"y":2022,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2022_28-48-3","t":"법원의 사실조회촉탁이 있거나 수사기관이 수사상 필요에 따라 문서로 신청하는 경우에 친양자입양관계증명서의 교부를 청구할 수 있다.","ox":"O","m":"③","c":"A","tp":"친양자입양관계증명서 교부청구의 특례"},{"y":2022,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2022_28-48-4","t":"친양자입양관계증명서 교부청구에 대한 제한은 교부청구 대상 가족관계등록부의 본인이 친양자로 입양된 경우에 한하여 적용된다.","ox":"X","m":"④","c":"A","tp":"친양자입양관계증명서 교부청구의 특례"},{"y":2022,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2022_28-48-5","t":"채권·채무 등 재산권의 상속과 관련하여 상속인의 범위를 확인하기 위해서 사망한 사람의 친양자입양관계증명서가 필요한 경우 소명자료를 첨부하면 교부청구가 가능하다.","ox":"O","m":"⑤","c":"A","tp":"친양자입양관계증명서 교부청구의 특례"},{"y":2023,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2023_29-41-1","t":"등록기준지 변경신고는 가족관계의 등록 등에 관한 법률 제23조의2에 따라 전산정보처리조직을 이용하여 전자문서로 할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2023_29-41-2","t":"가족관계등록부의 등록기준지란에 도로명주소가 기록되어 있는 경우, 신고서의 등록기준지가 지번방식의 주소로 기재된 때에도 가족관계등록정보시스템의 검색화면을 통하여 해당 도로명주소에 대한 지번방식의 주소임이 인정되면, 그 신고를 수리한다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2023_29-41-3","t":"가족관계등록부의 등록기준지란에 지번방식의 주소가 기록되어 있는 경우, 신고서의 등록기준지가 도로명주소로 기재된 때에도 가족관계등록정보시스템의 검색화면을 통하여 해당 지번방식의 주소에 대한 도로명주소임이 인정되면, 그 신고를 수리한다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2023_29-41-4","t":"등록기준지를 새로 지정하거나 변경하는 신고의 경우 도로명주소로 기재된 신고를 수리한다. 다만, 해당 등록기준지에 대한 도로명주소가 없는 때에는 지번방식의 주소로 등록기준지를 지정하거나 변경하는 신고도 이를 수리한다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2023_29-41-5","t":"행정구역, 토지의 명칭, 지번, 도로명 또는 건물번호의 부여·변경이 있는 경우, 시(구)·읍·면의 장은 가족관계등록부의 등록기준지란과 일반등록사항란에 기록된 해당 행정구역, 토지의 명칭, 지번, 도로명 또는 건물번호를 경정하여야 하고, 등록기준지란의 경정사유는 일반등록사항란에 기록한다.","ox":"X","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2023_29-45-1","t":"본인이 사망하거나 실종선고ㆍ부재선고를 받은 때, 국적을 이탈하거나 상실한 때, 가족관계등록부가 이중으로 작성된 경우, 가족관계등록부가 착오 또는 부적법하게 작성된 경우, 정정된 가족관계등록부가 이해관계인에게 현저히 부당하다고 인정되어 재작성하는 경우에는 가족관계등록부를 폐쇄한다.","ox":"O","m":"①","c":"A","tp":"가족관계등록부의 폐쇄"},{"y":2023,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2023_29-45-2","t":"동일한 사람이 성명이나 출생연월일의 일부 또는 전부를 달리하여 2개 이상의 가족관계등록부가 있음이 명백히 밝혀진 경우에는 시(구)ㆍ읍ㆍ면의 장은 가족관계의 등록 등에 관한 법률 제18조에 따른 감독법원의 허가를 받아 직권으로 그 등록부를 폐쇄할 수 있다.","ox":"O","m":"②","c":"A","tp":"가족관계등록부의 폐쇄"},{"y":2023,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2023_29-45-3","t":"가족관계등록부가 이중으로 작성되어 폐쇄하는 경우에는 착오로 작성된 가족관계등록부를 폐쇄하여야 하고, 폐쇄할 가족관계등록부를 당사자가 임의로 선택할 수 없다.","ox":"O","m":"③","c":"A","tp":"가족관계등록부의 폐쇄"},{"y":2023,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2023_29-45-4","t":"적법한 출생신고에 의하여 가족관계등록부가 작성된 사람이 가족관계등록창설을 하여 이중으로 가족관계등록부가 작성된 경우, 가족관계등록창설에 의하여 작성된 가족관계등록부에 그 기록사항이 적법하게 기록된 경우에는 등록부정정에 의하여 가족관계등록창설에 의하여 작성된 가족관계등록부를 폐쇄함과 동시에 적법한 가족관계등록부에 그 기록사항을 이기하는 정정절차를 거쳐 정리할 수 있다.","ox":"O","m":"④","c":"A","tp":"가족관계등록부의 폐쇄"},{"y":2023,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2023_29-45-5","t":"시(구)·읍·면의 장이 가족관계등록부를 폐쇄하는 때에는 가족관계등록부사항란 및 특정등록사항란에 그 취지와 사유를 기록하고, 등록사항별 증명서를 발급하는 경우에는 증명서의 우측상단에 “폐쇄”라고 표시한다.","ox":"X","m":"⑤","c":"A","tp":"가족관계등록부의 폐쇄"},{"y":2023,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2023_29-46-1","t":"기본증명서와 마찬가지로 다른 증명서에도 등록기준지의 지정, 변경 또는 정정에 관한 사항이나 등록부의 작성, 폐쇄에 관한 사항을 기재하기 위하여 가족관계등록부 사항란을 두었다.","ox":"X","m":"①","c":"A","tp":"가족관계등록사항별 증명서의 종류와 기록사항"},{"y":2023,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2023_29-46-2","t":"입양의 경우 양자인 본인의 가족관계증명서에는 부모란에 친생부모와 양부모를 모두 기록한다. 다만, 단독입양한 양부가 친생모와 혼인관계에 있는 때에는 양부와 친생모를, 단독입양한 양모가 친생부와 혼인관계에 있는 때에는 양모와 친생부를 각각 부모로 기록한다.","ox":"X","m":"②","c":"A","tp":"가족관계등록사항별 증명서의 종류와 기록사항"},{"y":2023,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2023_29-46-3","t":"영문증명서에는 본인, 부모, 배우자 및 자녀의 성명·성별·출생연월일 및 주민등록번호가 기재된다.","ox":"X","m":"③","c":"A","tp":"가족관계등록사항별 증명서의 종류와 기록사항"},{"y":2023,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2023_29-46-4","t":"가족관계등록부에 가족으로 기록될 자가 외국인인 경우에는 성명·성별·출생연월일·국적 및 외국인등록번호가 기재된다.","ox":"O","m":"④","c":"A","tp":"가족관계등록사항별 증명서의 종류와 기록사항"},{"y":2023,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2023_29-46-5","t":"혼인관계증명서의 특정증명서에는 신청인이 선택한 현재 및 과거의 혼인사항이 기재된다.","ox":"X","m":"⑤","c":"A","tp":"가족관계등록사항별 증명서의 종류와 기록사항"},{"y":2024,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2024_30-42-1","t":"인터넷에 의한 등록사항별 증명서의 발급은 본인 또는 배우자, 부모, 자녀가 신청할 수 있다. 다만, 친양자입양관계증명서의 발급은 친양자가 성년이 되어 신청하는 경우에 한한다.","ox":"O","m":"①","c":"A","tp":"등록사항별 증명서의 발급 등"},{"y":2024,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2024_30-42-2","t":"가정폭력범죄의 처벌 등에 관한 특례법 제2조 제5호에 따른 가정폭력피해자 또는 그 대리인은 그 피해자의 배우자 또는 직계혈족을 교부제한대상자로 지정하여 시(구)ㆍ읍ㆍ면의 장에게 그 피해자 본인의 등록사항별 증명서의 교부를 제한하도록 신청할 수 있다. 이 경우 교부제한대상자는 가정폭력피해자의 배우자, 부모 또는 자녀에 해당하더라도 인터넷에 의한 가정폭력피해자 본인의 등록사항별 증명서를 발급받을 수 없다.","ox":"O","m":"②","c":"A","tp":"등록사항별 증명서의 발급 등"},{"y":2024,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2024_30-42-3","t":"인터넷에 의한 등록사항별 증명서의 발급 수수료는 무료로 한다.","ox":"O","m":"③","c":"A","tp":"등록사항별 증명서의 발급 등"},{"y":2024,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2024_30-42-4","t":"무인증명서발급기에 의한 등록사항별 증명서의 발급은 본인 또는 배우자, 부모, 자녀가 신청할 수 있다.","ox":"X","m":"④","c":"A","tp":"등록사항별 증명서의 발급 등"},{"y":2024,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2024_30-42-5","t":"우편으로 등록사항별 증명서의 송부를 청구하는 경우에는, 신청서에 정해진 사항을 기재하고 법률상 정당한 청구권자의 신분증명서 사본을 첨부하여야 하며, 본인이 신청하는 경우에도 신청대상자의 성명과 등록기준지를 기재하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"등록사항별 증명서의 발급 등"},{"y":2024,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2024_30-48","t":"다음 중 가족관계등록부에 기록될 수 없는 것끼리 고른 것은?","c":"A","mc":{"s":"다음 중 가족관계등록부에 기록될 수 없는 것끼리 고른 것은?","d":"ㄱ.등록사건을 처리한 시․읍․면의 명칭\nㄴ.통보자의 성명\nㄷ.가족관계등록에 관한 촉탁을 한 법원\nㄹ.신고인이 사건본인과 다른 때에는 신고인의 자격\nㅁ.협의이혼의사의 확인일","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄹ","ㄷ, ㅁ","ㄴ, ㅁ"],"a":5}},{"y":2025,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2025_31-43","t":"다음 중 가족관계의 등록 등에 관한 법률 제16조에 따른 등록부의 기록절차가 아닌 것끼리 고른 것은?","c":"A","mc":{"s":"다음 중 가족관계의 등록 등에 관한 법률 제16조에 따른 등록부의 기록절차가 아닌 것끼리 고른 것은?","d":"ㄱ.통보\nㄴ.재판서\nㄷ.촉탁\nㄹ.항해일지의 등본\nㅁ.보고","o":["ㄱ, ㄴ","ㄴ, ㄹ","ㄴ, ㅁ","ㄷ, ㄹ","ㄷ, ㅁ"],"a":5}},{"y":2026,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2026_32-41-1","t":"인터넷에 의한 등록사항별 증명서의 발급은 법원행정처 전산정보중앙관리소 전산운영책임관 명의로 한다.","ox":"O","m":"①","c":"A","tp":"등록사항별 증명서의 발급 명의"},{"y":2026,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2026_32-41-2","t":"동사무소에서 교부하는 등록사항별 증명서는 소속 시장(구청장) 명의로 한다.","ox":"O","m":"②","c":"A","tp":"등록사항별 증명서의 발급 명의"},{"y":2026,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2026_32-41-3","t":"무인증명서발급기에 의한 등록사항별 증명서의 발급은 관할 시(구)⋅읍⋅면의 장 명의로 한다.","ox":"O","m":"③","c":"A","tp":"등록사항별 증명서의 발급 명의"},{"y":2026,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2026_32-41-4","t":"가족관계등록관이 파견된 재외공관에서 교부하는 등록사항별 증명서는 교부 재외공관에 파견된 가족관계등록관 명의로 한다.","ox":"O","m":"④","c":"A","tp":"등록사항별 증명서의 발급 명의"},{"y":2026,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2026_32-41-5","t":"법원행정처와 외교부의 시스템 연계 방식을 이용한 재외공관에서 교부하는 등록사항별 증명서는 법원행정처 전산정보중앙관리소 전산운영책임관 명의로 한다.","ox":"X","m":"⑤","c":"A","tp":"등록사항별 증명서의 발급 명의"},{"y":2026,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2026_32-43-1","t":"가족관계등록사무는 대법원이 관장하며, 대법원장은 가족관계등록사무의 감독에 관한 권한을 시(구)ㆍ읍ㆍ면의 사무소 소재지를 관할하는 가정법원장에게 위임한다.","ox":"O","m":"①","c":"A","tp":"신고서류 및 법원의 감독"},{"y":2026,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2026_32-43-2","t":"시(구)ㆍ읍ㆍ면의 장은 가족관계등록부에 기록을 마친 신고서류를 1개월마다 다음 달 10일까지 접수순서에 따라 편철한 후 각 장마다 장수를 기재하여 그 목록과 함께 사건을 처리한 시(구)ㆍ읍ㆍ면의 사무소를 감독하는 법원에 송부하여야 한다.","ox":"O","m":"②","c":"A","tp":"신고서류 및 법원의 감독"},{"y":2026,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2026_32-43-3","t":"감독법원은 시(구)ㆍ읍ㆍ면의 장으로부터 신고서류 등을 송부받은 때에는 지체 없이 가족관계등록부의 기록사항과 대조하고 조사하여야 하며, 조사결과 그 신고서류 등에 위법ㆍ부당한 사실이 발견된 경우에는 시(구)ㆍ읍ㆍ면의 장에 대하여 시정지시 등 필요한 처분을 명할 수 있다.","ox":"O","m":"③","c":"A","tp":"신고서류 및 법원의 감독"},{"y":2026,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2026_32-43-4","t":"감독법원은 시(구)ㆍ읍ㆍ면의 장으로부터 송부받은 신고서류를 30년간 보존하고, 보존기간은 송부받은 날부터 기산하며, 이해관계인은 감독법원에 보관되어 있는 신고서류의 열람을 청구할 수 있다.","ox":"X","m":"④","c":"A","tp":"신고서류 및 법원의 감독"},{"y":2026,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2026_32-43-5","t":"감독법원은 신고서류의 보존기간이 경과한 때에는 법원기록물 관리규칙 제27조의 절차를 거친 후 각 소속기관의 장의 인가를 받아 보존기간이 종료되는 연도의 다음 연도 3월말까지 폐기하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"신고서류 및 법원의 감독"},{"y":2026,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2026_32-47-1","t":"대법원장으로부터 등록사무의 처리에 관한 권한을 위임받은 시⋅읍⋅면⋅동의 장은 등록사항별 증명서의 교부사무를 처리할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2026_32-47-2","t":"시⋅읍⋅면의 사무소나 출장소를 이전한 때에는 7일 이내에 감독법원에 보고하여야 한다.","ox":"X","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2026_32-47-3","t":"동장이 취임하거나 퇴임 등의 사유로 그 직을 면한 때에는 즉시 감독법원에 보고하여야 한다.","ox":"X","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2026_32-47-4","t":"대법원장은 외국에 거주하거나 체류하는 대한민국 국민에 관한 등록사무를 가족관계등록관에게 위임하여 처리하게 할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2026_32-47-5","t":"행정구역, 토지의 명칭, 지번, 도로명 또는 건물번호가 변경된 때에는 그 시행일 15일 전까지 감독법원에 보고하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2026_32-49","t":"다음 중 가족관계의 등록 등에 관한 규칙에서 정한 식별부호 사용신청이 가능한 대상자를 모두 고른 것은?","c":"A","mc":{"s":"다음 중 가족관계의 등록 등에 관한 규칙에서 정한 식별부호 사용신청이 가능한 대상자를 모두 고른 것은?","d":"ㄱ.읍⋅면의 장\nㄴ.재외공관의 장\nㄷ.등록사무담임자\nㄹ.동장\nㅁ.전산운영책임관","o":["ㄱ, ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄱ, ㄷ, ㄹ","ㄴ, ㄹ, ㅁ","ㄷ, ㅁ"],"a":3}}],"15":[{"y":2016,"e":"법무사 1차","qn":48,"lv":3,"i":"법무사2016_22-48","t":"다음 중 시(구)ㆍ읍ㆍ면의 장이 직권으로 등록부에 기록하여야 할 사항이 아닌 것은?","c":"A","mc":{"s":"다음 중 시(구)ㆍ읍ㆍ면의 장이 직권으로 등록부에 기록하여야 할 사항이 아닌 것은?","d":"","o":["한쪽 배우자에 대하여 개명신고가 있는 때에 다른 배우자의 등록부 일반등록사항란에 그 취지의 기록","부모의 혼인이 취소된 때에 자녀의 등록부 일반등록사항란에 그 사유의 기록","부 또는 모의 성과 본이 정정되거나 변경된 경우 그 부 또는 모의 성을 따르는 자녀의 성과 본을 정정 또는 변경기록하고 그 사유를 등록부 일반등록사항란에 기록","인지의 효력이 있는 출생신고가 있는 때에 인지한 부의 등록부 특정등록사항란에 그 출생자의 성명 등의 기록","한쪽 배우자에 대하여 실종선고취소신고가 있는 때에 다른 배우자의 등록부 일반등록사항란에 그 취지의 기록"],"a":2}},{"y":2016,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2016_22-49-1","t":"가족관계의 등록 등에 관한 법률 제104조에 따른 등록기록 정정의 허부에 관한 결정에 대한 항고는 통상항고로서 그 불복기간의 정함이 없고 불복의 실익이 있는 한 언제든지 이를 제기할 수 있다.","ox":"O","m":"①","c":"A","tp":"가족관계등록비송"},{"y":2016,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2016_22-49-2","t":"본이란 원래 소속 시조발상의 지명을 표시하여 혈족계통을 나타내는 제도이므로 자신의 종전 이름으로 본을 삼겠다는 정정신청은 본 제도의 취지에 어긋나는 것이다.","ox":"O","m":"②","c":"A","tp":"가족관계등록비송"},{"y":2016,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2016_22-49-3","t":"외국인 부의 성을 따라 외국식 이름으로 기록된 가족관계등록부를 후에 한국인 모의 성과 한국식 이름으로 변경하기 위해서는, 창성절차와 개명절차를 거쳐야 하고, 추후보완신고 또는 등록부의 정정절차를 통해서는 이를 할 수 없다.","ox":"X","m":"③","c":"A","tp":"가족관계등록비송"},{"y":2016,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2016_22-49-4","t":"가족관계등록창설 허가신청은 가족관계등록이 되어 있지 아니한 사람(이하 ‘무등록자’라 한다) 자신이 신청하는 것이고, 무등록자가 이미 사망하였다면 가족관계등록창설이 허용되지 아니한다.","ox":"O","m":"④","c":"A","tp":"가족관계등록비송"},{"y":2016,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2016_22-49-5","t":"미성년자라도 의사능력이 있는 경우에는 단독으로 개명허가신청을 할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"가족관계등록비송"},{"y":2017,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2017_23-41-1","t":"등록부의 기록이 법률상 무효인 것이거나 그 기록에 착오 또는 누락이 있음을 안 때에는 시ㆍ읍ㆍ면의 장은 지체 없이 신고인 또는 신고사건의 본인에게 그 사실을 통지하여야 한다. 다만, 그 착오 또는 누락이 시ㆍ읍ㆍ면의 장의 잘못으로 인한 것인 때에는 그러하지 아니하다.","ox":"O","m":"①","c":"A","tp":"가족관계등록 정정"},{"y":2017,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2017_23-41-2","t":"신고로 인하여 효력이 발생하는 행위에 관하여 등록부에 기록하였으나 그 행위가 무효임이 명백한 때에는 신고인 또는 신고사건의 본인은 신고인의 등록기준지를 관할하는 가정법원의 허가를 받아 등록부의 정정을 신청할 수 있다.","ox":"X","m":"②","c":"A","tp":"가족관계등록 정정"},{"y":2017,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2017_23-41-3","t":"가족관계의 등록 등에 관한 법률 제104조 및 제105조에 따라 허가의 재판이 있었을 때에는 재판서의 등본을 받은 날부터 1개월 이내에 그 등본을 첨부하여 등록부의 정정을 신청하여야 한다.","ox":"O","m":"③","c":"A","tp":"가족관계등록 정정"},{"y":2017,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2017_23-41-4","t":"등록부의 정정 사항이 친족법상 또는 상속법상 중대한 영향을 미치는 사항인 경우에는 가족관계의 등록 등에 관한 법률 제107조에 따라 확정판결에 의하여 정정하여야 하는 것이 원칙이다.","ox":"O","m":"④","c":"A","tp":"가족관계등록 정정"},{"y":2017,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2017_23-41-5","t":"확정판결로 인하여 등록부를 정정하여야 할 때에는 소를 제기한 사람은 판결확정일부터 1개월 이내에 판결의 등본 및 그 확정증명서를 첨부하여 등록부의 정정을 신청하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"가족관계등록 정정"},{"y":2017,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2017_23-44","t":"시ㆍ읍ㆍ면의 장의 처분에 대한 불복절차에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"시ㆍ읍ㆍ면의 장의 처분에 대한 불복절차에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["등록사건에 관한 시ㆍ읍ㆍ면의 장의 위법 또는 부당한 처분에 대하여 이해관계인은 관할 가정법원에 불복의 신청을 할 수 있다.","불복 신청서는 관할 가정법원에 직접 제출하면 되고, 처분을 한 시ㆍ읍ㆍ면의 장을 경유할 필요는 없다.","불복 신청을 받은 가정법원은 신청에 관한 서류를 시ㆍ읍ㆍ면의 장에게 송부하며 그 의견을 구할 수 있다.","위 ③항의 경우 시ㆍ읍ㆍ면의 장은 불복 신청이 이유 있다고 인정되는 때에는 의견을 붙여 지체 없이 그 서류를 법원에 반환하여야 한다.","가정법원은 신청이 이유 없는 때에는 각하하고, 이유 있는 때에는 시ㆍ읍ㆍ면의 장에게 상당한 처분을 명하여야 한다."],"a":4}},{"y":2018,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2018_24-41-1","t":"「독립유공자예우에 관한 법률에 의한 가족관계등록 사무처리규칙」에 따라 가족관계등록을 창설할 때 독립유공자의 가족관계등록부 특정등록사항란에 배우자 및 자녀를 기록하지 아니한다.","ox":"O","m":"①","c":"A","tp":"가족관계등록비송"},{"y":2018,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2018_24-41-2","t":"친생자관계부존재확인판결에 의하여 폐쇄된 등록부상의 성명과 새로운 출생신고에 의하여 작성되는 등록부에 기록된 성명이 서로 다른 경우 개명절차를 거쳐야 한다.","ox":"X","m":"②","c":"A","tp":"가족관계등록비송"},{"y":2018,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2018_24-41-3","t":"자의 복리를 위한 자의 성·본변경허가 사건은 가족관계등록 비송사건에 해당한다.","ox":"X","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2018_24-41-4","t":"부모를 알 수 없는 자로서 기아인 경우에는 성·본 창설허가와 가족관계등록창설허가를 받아 가족관계등록부를 작성한다.","ox":"X","m":"④","c":"A","tp":"가족관계등록비송"},{"y":2018,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2018_24-41-5","t":"가족관계등록창설허가신청은 사건본인의 주소지를 관할하는 가정법원의 허가를 받아야 한다.","ox":"X","m":"⑤","c":"A","tp":"가족관계등록비송"},{"y":2018,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2018_24-45-1","t":"출생신고인이 출생신고서에 기재한 이름과 실제 가족관계등록부에 기록된 이름이 서로 다른 경우에는 개명이 아닌 등록부 정정 절차에 의하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2018_24-45-2","t":"개명하고자 하는 사람은 등록기준지가 아닌 주소지 관할 법원에 개명허가 신청을 하는 것이 원칙이다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2018_24-45-3","t":"의사능력이 있는 미성년자는 단독으로 개명허가 신청을 할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2018_24-45-4","t":"개명허가를 받은 사람이 직접 개명신고를 할 경우 신고인란에는 개명허가 전의 이름을 기재하여야 한다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2018_24-45-5","t":"배우자 일방에 대한 개명신고가 있는 때에는 다른 배우자의 등록부에도 그 취지를 직권으로 기록하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":42,"lv":3,"i":"법무사2019_25-42","t":"가족관계등록부를 재작성할 수 있는 경우에 대한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"가족관계등록부를 재작성할 수 있는 경우에 대한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["甲․乙 부부가 이혼한 것으로 신고된 것을 잘못하여 丙․丁 부부가 이혼한 것으로 기록하였다가 후에 이를 정정회복한 가족관계등록부에 대한 재작성 신청이 있는 경우","甲남이 乙녀와 혼인한 것으로 신고된 것을 잘못하여 다른 사람인 丙녀와 혼인한 것으로 기록하였다가 후에 이를 정정회복한 가족관계등록부에 대한 재작성 신청이 있는 경우","甲에 대한 사망신고를 잘못하여 다른 생존자인 乙에 대하여 사망기록을 하였다가 후에 이를 정정회복한 가족관계등록부에 대한 재작성 신청이 있는 경우","당사자 사이에 혼인의사의 합의가 없음을 원인으로 하는 혼인무효판결에 의한 등록부정정신청으로 해당 가족관계등록부가 정정된 후 혼인무효판결과 확정증명원만을 첨부하여 재작성 신청이 있는 경우","가족관계의 등록 등에 관한 규칙 제20조에 의한 멸실고시의 사유가 발생한 경우"],"a":4}},{"y":2019,"e":"법무사 1차","qn":47,"lv":3,"i":"법무사2019_25-47","t":"다음 중 소를 제기한 사람이 가족관계의 등록 등에 관한 법률 제107조에 따라 가족관계등록부의 정정을 신청하여야 하는 경우가 아닌 것은?","c":"A","mc":{"s":"다음 중 소를 제기한 사람이 가족관계의 등록 등에 관한 법률 제107조에 따라 가족관계등록부의 정정을 신청하여야 하는 경우가 아닌 것은?","d":"","o":["이혼무효의 재판이 확정된 경우","이혼취소의 재판이 확정된 경우","혼인무효의 재판이 확정된 경우","혼인취소의 재판이 확정된 경우","입양무효의 재판이 확정된 경우"],"a":4}},{"y":2020,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2020_26-41-1","t":"성전환자의 성별정정허가신청이 있으면 법원은 반드시 신청인을 비공개로 심문하여야 하나 상당하다고 인정하는 자에게 방청을 허가할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2020_26-41-2","t":"법원은 신청인이 대한민국 국적자로서 19세 이상의 행위능력자인지, 현재 혼인중인지, 신청인에게 미성년인 자녀가 있는지 여부를 조사할 수 있다.","ox":"O","m":"②","c":"A","tp":"성전환자의 성별정정허가신청"},{"y":2020,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2020_26-41-3","t":"신청인이 성별정정허가신청을 하기 위하여는 부모의 동의서를 첨부하여야 한다.","ox":"X","m":"③","c":"A","tp":"성전환자의 성별정정허가신청"},{"y":2020,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2020_26-41-4","t":"신청인이 성별정정허가신청과 함께 개명허가신청을 한 경우, 개명허가신청사건에 관해서는 원칙적으로 개명허가신청사건 사무처리지침에 따르되, 지침에 따른 사실조회는 실시하지 아니할 수 있다.","ox":"O","m":"④","c":"A","tp":"성전환자의 성별정정허가신청"},{"y":2020,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2020_26-41-5","t":"성전환증을 이유로 성별정정허가결정을 받은 신청인의 등록부정정신청을 접수한 시(구)ㆍ읍ㆍ면의 장은 신청인의 성별란을 정정하고, 일반등록사항란에 정정사유를 기록한다.","ox":"O","m":"⑤","c":"A","tp":"성전환자의 성별정정허가신청"},{"y":2020,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2020_26-43","t":"다음 중 가족관계등록 비송사건에 해당하는 것은?","c":"A","mc":{"s":"다음 중 가족관계등록 비송사건에 해당하는 것은?","d":"","o":["부모를 알 수 없는 자의 성․본 창설허가 사건","자의 복리를 위한 자녀의 성․본 변경허가 사건","협의상 이혼에 따른 자녀의 양육에 관한 처분과 그 변경, 면접교섭권의 처분 또는 제한ㆍ배제ㆍ변경 사건","외국의 성을 쓰는 국적취득자의 성․본 창설허가 사건","혼인관계가 종료된 날부터 300일 이내에 출생한 자녀에 대한 인지의 허가 사건"],"a":4}},{"y":2020,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2020_26-45-1","t":"등록부의 기록에 착오 또는 누락이 시(구)·읍·면의 장의 잘못으로 인한 것인 때에는 지체없이 신고인 또는 신고사건의 본인에게 그 사실을 통지하여야 한다.","ox":"X","m":"①","c":"A","tp":"직권 정정·기록 등"},{"y":2020,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2020_26-45-2","t":"시(구)·읍·면의 장이 출생신고를 게을리 한 사람을 안 때에는 신고의무자에게 가족관계의 등록 등에 관한 법률 제38조에 따른 최고를 하여야 한다. 신고의무자가 그 최고기간 내에 신고를 하지 않거나 최고 할 수 없는 경우에는 시(구)·읍·면의 장은 감독법원의 허가를 받아 직권으로 출생기록을 하여야 한다.","ox":"O","m":"②","c":"A","tp":"직권 정정·기록 등"},{"y":2020,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2020_26-45-3","t":"가족관계등록부의 성명란에 한글과 한자를 함께 기록하는 방법으로는 “김철수(金哲秀)”, “김철수(金哲수)”, “김철수(金철秀)”, “김철수(金철수)”와 같이 할 수 있다.","ox":"O","m":"③","c":"A","tp":"직권 정정·기록 등"},{"y":2020,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2020_26-45-4","t":"특정등록사항란의 성명란이 아닌 곳에 성명을 기록할 경우에는 모두 한글로 기록한다. 그러나 개명 또는 등록부정정의 경우에는 일반등록사항란에 한글과 한자를 함께 기록하여 그 사유를 기록한다.","ox":"O","m":"④","c":"A","tp":"직권 정정·기록 등"},{"y":2020,"e":"법무사 1차","qn":45,"lv":3,"i":"법무사2020_26-45-5","t":"한쪽 배우자에 대하여 개명신고가 있는 때에는 다른 배우자의 등록부에도 그 취지를 기록하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"직권 정정·기록 등"},{"y":2021,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2021_27-43-1","t":"외국인과의 신분행위(예: 외국인에게 입양된 경우 등) 등으로 그 외국인과 일정한 신분관계가 형성이 되어 그 외국의 법에 따라 개명을 한 경우라 하더라도, 가족관계의 등록 등에 관한 법률 제99조에 따라 한국법원에서 개명허가결정을 받은 경우가 아닌 한 그 외국에서 개명한 이름을 개명신고에 의해서 한국 가족관계등록부에 기록할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2021_27-43-2","t":"개명허가신청인의 개인적인 입장을 고려하여 개명을 허가할 만한 상당한 이유가 있고, 달리 개명신청권의 남용으로 볼 사정이 없는 한, 미성년자 시절 한 차례 개명허가결정을 받은 사실만으로는 개명신청권의 남용이라고 보기 어렵다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2021_27-43-3","t":"개명하고자 하는 사람은 주소지를 관할하는 가정법원의 허가를 받아야 하고, 주소지가 없는 사람은 등록기준지를 관할하는 가정법원에 개명허가신청을 할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2021_27-43-4","t":"재외국민이 개명허가신청서를 재외공관에 제출할 때에는 신청서에 정해진 인지를 붙이거나 그 액면상당의 현지화를 재외공관장에게 납부하여도 된다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":43,"lv":3,"i":"법무사2021_27-43-5","t":"개명신청을 허가한 재판이 효력을 발생한 때에는 가정법원의 법원사무관등은 지체 없이 사건본인의 주소지의 시(구)ㆍ읍ㆍ면의 장에게 그 뜻을 통지하여야 하고, 통지를 받은 시(구)ㆍ읍ㆍ면의 장은 법정기간 내 신고의무자의 신고가 없으면 지체없이 가족관계의 등록 등에 관한 법률 제38조 제1항 및 제2항에 따라 신고의무자에게 신고할 것을 최고하여야 한다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2021_27-46-1","t":"국적취득자의 성본창설허가, 개명허가, 가족관계등록창설허가 및 등록기록정정허가는 비송사건절차법을 준용하므로 심문은 비공개가 원칙이고 직권에 의한 탐지와 증거조사가 인정된다.","ox":"O","m":"①","c":"A","tp":"가족관계등록비송사건"},{"y":2021,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2021_27-46-2","t":"가족관계등록공무원이 가족관계등록부의 정정허가결정에 의한 가족관계등록부의 정정신청을 수리하여 가족관계등록부에 기록을 한 후에는 그 허가결정을 한 법원은 비송사건절차법 제19조 제1항에 따라 재판의 취소 또는 변경을 할 수는 없다.","ox":"O","m":"②","c":"A","tp":"가족관계등록비송사건"},{"y":2021,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2021_27-46-3","t":"비송사건절차법이 민사소송법 개별 규정을 준용하고 있고, 가족관계등록비송사건에는 비송사건절차법이 준용되므로 가족관계등록비송사건을 대상으로 하는 소송구조 신청은 적법하다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2021_27-46-4","t":"일반 민사비송사건이나 가사비송사건에 있어서는 공익의 대표자인 검사에게 청구인적격이 부여되는 경우가 있으나 가족관계등록비송사건에 관하여는 이러한 규정이 없다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2021_27-46-5","t":"가족관계등록비송사건의 신청서나 재판서에는 당사자에 준하여 사건본인을 기재할 필요가 있으므로 허가신청서에는 사건본인의 성명ㆍ출생연월일ㆍ등록기준지 및 주소를 기재하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2022_28-46","t":"다음에 열거한 비송사건 중에서 가족관계등록비송사건을 모두 고른 것은?","c":"A","mc":{"s":"다음에 열거한 비송사건 중에서 가족관계등록비송사건을 모두 고른 것은?","d":"가.자의 복리를 위한 자의 성과 본의 변경 허가 사건\n나.등록이 되어 있지 아니한 사람에 대한 가족관계등록창설허가 사건\n다.개명허가 사건\n라.부모를 알 수 없는 사람에 대한 성과 본의 창설 허가 사건\n마.외국의 성을 쓰는 국적취득자의 성과 본의 창설 허가 사건\n바.미성년자의 입양에 대한 허가 사건\n사.위법한 가족관계 등록기록의 정정 허가 사건\n아.출생증명서 또는 서면을 첨부할 수 없는 경우의 가정법원의 확인 사건","o":["나, 다, 라, 마","가, 다, 라, 바","나, 다, 라, 마, 사","나, 다, 마, 사, 아","나, 다, 라, 마, 사, 아"],"a":4}},{"y":2022,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2022_28-49-1","t":"폐쇄된 가족관계등록부를 정정할 때에는 부활 없이 정정하나, 그 가족관계등록부가 위법한 것이어서 폐쇄된 경우에는 기록을 정정할 수 없다.","ox":"O","m":"①","c":"A","tp":"가족관계등록부 기록 및 제적부 기재의 정정 등"},{"y":2022,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2022_28-49-2","t":"가족관계등록부를 정정할 때는 그 사항이 기재된 제적부를 정정하되, 가족관계등록부의 정정허가결정만으로 제적부를 정정할 수는 없다.","ox":"O","m":"②","c":"A","tp":"가족관계등록부 기록 및 제적부 기재의 정정 등"},{"y":2022,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2022_28-49-3","t":"제적부의 정정은 본적지 관할 가족관계등록관서에서 한다.","ox":"O","m":"③","c":"A","tp":"가족관계등록부 기록 및 제적부 기재의 정정 등"},{"y":2022,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2022_28-49-4","t":"가족관계등록부에 기록된 외국인인 가족에 관한 기록사항 중 출생연월일, 외국인등록번호, 국적 또는 성별이 기록되지 않은 경우 이해관계인은 해당 가족관계등록부의 등록기준지의 시(구)·읍·면의 장에게 직권기록을 신청하여야 하고, 등록기준지의 시(구)·읍·면의 장은 간이직권절차에 의하여 기록한다.","ox":"X","m":"④","c":"A","tp":"가족관계등록부 기록 및 제적부 기재의 정정 등"},{"y":2022,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2022_28-49-5","t":"가족관계등록부에 기록된 외국인인 가족이 외국에서 사망한 경우 이해관계인은 해당 가족관계등록부의 등록기준지와 무관하게 전국 시(구)·읍·면의 장에게 사망사실을 증명하는 서면을 제출하여 직권기록을 신청할 수 있고, 시(구)·읍·면의 장은 간이직권절차에 의하여 기록한다.","ox":"O","m":"⑤","c":"A","tp":"가족관계등록부 기록 및 제적부 기재의 정정 등"},{"y":2023,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2023_29-50","t":"다음 중 이해관계인이 신청 또는 청구할 수 있는 것을 모두 고른 것은?","c":"A","mc":{"s":"다음 중 이해관계인이 신청 또는 청구할 수 있는 것을 모두 고른 것은?","d":"가.신고의 수리 또는 불수리의 증명서\n나.법원에 보관되어 있는 신고서류에 대한 열람\n다.가족관계등록부의 기록이 법률상 허가될 수 없는 것 또는 그 기재에 착오나 누락이 있다고 인정한 때에 사건 본인의 등록기준지를 관할하는 가정법원의 허가를 받아 가족관계등록부의 정정을 신청하는 절차\n라.가족관계등록사건에 관하여 시(구)․읍․면의 장의 위법 또는 부당한 처분이 있는 경우 관할 가정법원에 불복을 신청하는 절차","o":["가, 나, 다, 라","나, 다","나, 라","나, 다, 라","다, 라 2023년 9월 2일 시행 제29회 법무사 제1차 시험"],"a":4}},{"y":2024,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2024_30-44","t":"다음 중 시(구)⋅읍⋅면의 장이 감독법원의 허가 없이 가족관계등록부의 기록을 직권으로 정정 또는 기록할 수 있는 경우에 해당하는 것을 모두 고른 것은?","c":"A","mc":{"s":"다음 중 시(구)⋅읍⋅면의 장이 감독법원의 허가 없이 가족관계등록부의 기록을 직권으로 정정 또는 기록할 수 있는 경우에 해당하는 것을 모두 고른 것은?","d":"ㄱ.한쪽 배우자의 가족관계등록부에 혼인의 기록이 있으나 다른 배우자의 가족관계등록부에는 혼인의 기록이 누락된 때\nㄴ.신고서류에 의하여 이루어진 가족관계등록부의 기록에 오기나 누락된 부분이 있음이 해당 신고서류에 비추어 명백한 때\nㄷ. 도로명 또는 건물번호에 관한 가족관계등록부의 기록이 잘못 기재되었거나 빠뜨리게 된 것이 명백한 때\nㄹ. 외국의 국호와 지명에 관한 가족관계등록부의 기록이 외래어 표기법에 맞지 않는 때\nㅁ.귀화 또는 국적회복한 외국인의 인명이 우리나라 방식의 성명 배열이 아닌 해당 외국 방식에 의하여 가족관계등록부에 기록된 때","o":["ㄱ, ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄹ, ㅁ","ㄱ, ㄴ, ㄷ, ㄹ, ㅁ"],"a":5}},{"y":2024,"e":"법무사 1차","qn":46,"lv":3,"i":"법무사2024_30-46","t":"다음 중 주소지 관할 가정법원이 처리하는 경우가 있는 것끼리 연결된 것은(여기서 등록부의 정정허가는 가족관계의 등록 등에 관한 법률 제104조에 의함)?","c":"A","mc":{"s":"다음 중 주소지 관할 가정법원이 처리하는 경우가 있는 것끼리 연결된 것은(여기서 등록부의 정정허가는 가족관계의 등록 등에 관한 법률 제104조에 의함)?","d":"","o":["가족관계 등록 창설 허가 - 등록부의 정정 허가","개명 허가 - 귀화 허가","국적취득자의 성과 본 창설 허가 - 등록부의 정정 허가","협의상 이혼의 확인 - 개명 허가","개명 허가 - 등록부의 정정 허가"],"a":4}},{"y":2024,"e":"법무사 1차","qn":50,"lv":3,"i":"법무사2024_30-50","t":"가족관계의 등록 등에 관한 법률 또는 규칙상 불복절차 및 과태료에 관한 다음 설명 중 가장 옳은 것은?","c":"A","mc":{"s":"가족관계의 등록 등에 관한 법률 또는 규칙상 불복절차 및 과태료에 관한 다음 설명 중 가장 옳은 것은?","d":"","o":["불복신청의 비용에 관하여는 민사소송법의 규정을 준용한다.","가정법원은 신청이 이유 없는 때에는 기각하고 이유 있는 때에는 시․읍․면의 장에게 상당한 처분을 명하여야 한다.","위 ②항의 처분을 명하는 재판은 명령으로써 하고, 시․읍․면의 장 및 신청인에게 송달하여야 한다.","과태료를 부과하는 경우에는 위반사실과 과태료금액을 명시한 과태료납부통지서를 과태료처분 대상자에게 송부하여야 한다. 그러나 신고서 제출과 동시에 자진하여 과태료를 납부하는 경우에는 그러하지 아니하다.","과태료의 부과는 신고를 수리한 가족관계등록관이 한다. 2024년 8월 31일 시행 제30회 법무사 제1차 시험"],"a":4}},{"y":2025,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2025_31-49-1","t":"제적부를 정정할 때는 제적부를 부활한 후 정정한다.","ox":"X","m":"①","c":"A","tp":"가족관계등록부 또는 제적부의 정정"},{"y":2025,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2025_31-49-2","t":"혼인 등 신고로 인하여 효력이 발생하는 행위는 가족관계등록부에 기록한 후에 실체상의 흠결이 있음을 발견하여도 가족관계의 등록 등에 관한 법률 제18조 제2항에 따라 이를 정정할 수 없다.","ox":"O","m":"②","c":"A","tp":"가족관계등록부 또는 제적부의 정정"},{"y":2025,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2025_31-49-3","t":"판결에 의해서만 할 수 있는 가족관계등록부의 정정을 가정법원의 허가를 받아 가족관계등록부를 정정한 경우에도 그 허가를 받은 이상 적법한 정정의 효력이 발생한다.","ox":"X","m":"③","c":"A","tp":"가족관계등록부 또는 제적부의 정정"},{"y":2025,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2025_31-49-4","t":"가족관계등록부의 정정은 재판의 주문 및 이유에 나타난 사항에 한하여 허용된다.","ox":"X","m":"④","c":"A","tp":"가족관계등록부 또는 제적부의 정정"},{"y":2025,"e":"법무사 1차","qn":49,"lv":3,"i":"법무사2025_31-49-5","t":"일반등록사항란의 기록을 정정하는 경우에는 정정할 부분에 하나의 선을 긋고, 해당 사항란에 정정내용과 그 사유를 기록한다.","ox":"X","m":"⑤","c":"A","tp":"가족관계등록부 또는 제적부의 정정"},{"y":2026,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2026_32-44-1","t":"가족관계등록부사항란이나 일반등록사항란의 사건 자체를 말소하는 경우에는 그 기록사항 전체에 하나의 선을 긋고, 말소내용과 사유를 각 해당 사항란에 기록한다.","ox":"O","m":"①","c":"A","tp":"제적부 또는 가족관계등록부의 정정"},{"y":2026,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2026_32-44-2","t":"생가에 자의 제적이 존재하는 경우에는 친생자관계부존재 확인판결에 의해 위법한 가족관계등록부를 말소하여 이중등록부를 정리한 후 이에 따라 이중제적을 정리한다.","ox":"X","m":"②","c":"A","tp":"제적부 또는 가족관계등록부의 정정"},{"y":2026,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2026_32-44-3","t":"위법한 제적부를 기초로 작성된 가족관계등록부가 이중등록부인 경우에는 폐쇄하고 그 기록사항을 존치등록부로 이기하되, 이중등록부가 아닌 경우에는 폐쇄하지 않고 최초 등록기준지를 존치제적부의 본적으로 정정한다.","ox":"O","m":"③","c":"A","tp":"제적부 또는 가족관계등록부의 정정"},{"y":2026,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2026_32-44-4","t":"출생신고하지 않은 모와 양친자관계존재 확인판결이 확정된 경우 양친자관계가 존재하는 모와 자녀의 가족관계등록부를 친생자관계에서 양친자관계로 정정하고, 양자의 가족관계등록부상 출생신고일자를 입양신고일자로 기록한다.","ox":"O","m":"④","c":"A","tp":"제적부 또는 가족관계등록부의 정정"},{"y":2026,"e":"법무사 1차","qn":44,"lv":3,"i":"법무사2026_32-44-5","t":"허위의 출생신고로 기록한 친생자관계를 양친자관계로 정정하기 위하여는 양친자관계존재 확인판결이 있어야 하며, 파양판결 등으로 가족관계등록부를 정정할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"제적부 또는 가족관계등록부의 정정"}],"11":[{"y":2021,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2021_27-41-1","t":"부부의 일방이 장기간에 걸쳐 해외에 나가 있거나 사실상의 이혼으로 부부가 별거하고 있는 경우 등 부부의 동거가 없어 모가 법률상 남편의 자를 포태할 수 없는 외관상 명백한 사정이 있는 경우에는 친생자 추정이 미치지 않고 부자관계(父子關係) 다툼은 친생자관계부존재확인의 소에 의하여 가능하다.","ox":"O","m":"①","c":"A","tp":"친생자관계 존부 확인의 소"},{"y":2021,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2021_27-41-2","t":"혼인 외 출생자와 사망한 부 사이에 친생자관계존재확인판결이 확정되면 그들 사이에 친생자관계가 형성되므로, 혼인 외 출생자가 자신과 사망한 부의 사이에 친생자관계존재확인판결의 등본과 그 확정증명원을 첨부하여 자신의 가족관계등록부상 부란에 사망한 부의 성명을 기재하여 달라는 취지의 등록부정정신청을 하는 경우 시(구)·읍·면의 장은 이를 수리하여야 한다.","ox":"X","m":"②","c":"A","tp":"친생자관계 존부 확인의 소"},{"y":2021,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2021_27-41-3","t":"민법 제844조의 친생추정을 번복하기 위하여는 친생부인의 소를 제기하여 그 확정판결을 받아야 하고, 이러한 친생부인의 소가 아닌 민법 제865조 소정의 친생자관계부존재확인의 소에 의하여 그 친생자관계의 부존재확인을 구하는 것은 부적법하다.","ox":"O","m":"③","c":"A","tp":"친생자관계 존부 확인의 소"},{"y":2021,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2021_27-41-4","t":"부가 출생신고한 자녀가 가족관계등록부상 모와 친생자관계부존재확인판결이 확정된 경우 소를 제기한 자 또는 상대방이 판결등본과 확정증명서를 첨부하여 가족관계등록부 정정신청을 하면 자녀의 가족관계등록부에 모의 특정등록사항을 말소한다.","ox":"O","m":"④","c":"A","tp":"친생자관계 존부 확인의 소"},{"y":2021,"e":"법무사 1차","qn":41,"lv":3,"i":"법무사2021_27-41-5","t":"허위의 친생자출생신고를 한 것이 입양신고로서의 기능을 발휘하여 입양의 효력이 발생하였다면 파양에 의하여 양친자관계를 해소할 필요가 있는 등의 특별한 사정이 없는 한, 친생자관계부존재확인의 소는 확인의 이익이 없는 것으로서 부적법하다.","ox":"O","m":"⑤","c":"A","tp":"친생자관계 존부 확인의 소"},{"y":2016,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2016_22-36-1","t":"재산분할 제도의 취지에 비추어 허용될 수 없는 경우가 아니라면, 이미 발생한 공무원 퇴직연금수급권도 부동산 등과 마찬가지로 재산분할의 대상에 포함될 수 있고, 구체적으로는 연금수급권자인 배우자가 매월 수령할 퇴직연금액 중 일정 비율에 해당하는 금액을 상대방 배우자에게 정기적으로 지급하는 방식의 재산분할도 가능하다.","ox":"O","m":"①","c":"A","tp":"이혼"},{"y":2016,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2016_22-36-2","t":"이혼의 당사자가 자의 양육에 관한 사항을 협의에 의하여 정하였더라도 필요한 경우 가정법원은 당사자의 청구에 의하여 언제든지 그 사항을 변경할 수 있는 것이며, 이는 당사자 사이의 협의가 재판상 화해에 의한 경우에도 마찬가지이다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2016_22-36-3","t":"부부가 이혼하는 경우 일방이 혼인 중 제3자에게 부담한 채무는 일상가사에 관한 것 이외에는 원칙적으로 그 개인의 채무로서 청산의 대상이 되지 않으나 그것이 공동재산의 형성ㆍ유지에 수반하여 부담한 채무인 때에는 청산의 대상이 되며, 그 채무로 인하여 취득한 특정 적극재산이 남아 있지 않더라도 그 채무부담행위가 부부 공동의 이익을 위한 것으로 인정될 때에는 혼인 중의 공동재산의 형성ㆍ유지에 수반하는 것으로 보아 청산의 대상이 된다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2016_22-36-4","t":"아직 이혼하지 않은 당사자가 장차 협의상 이혼할 것을 약정하면서 이를 전제로 하여 재산분할에 관한 협의를 한 경우에는, 그 협의 후 당사자가 약정한대로 협의상 이혼이 이루어지지 않고 혼인관계가 존속하게 되거나 당사자 일방이 제기한 이혼청구의 소에 의하여 재판상이혼(화해 또는 조정에 의한 이혼을 포함한다.)이 이루어진 경우에도, 위 재산분할협의의 효력이 발생한다.","ox":"X","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2016_22-36-5","t":"재산분할청구권은 이혼한 날로부터 2년 내에 행사하여야 하고 그 기간이 경과하면 소멸되어 이를 청구할 수 없는바, 이때의 2년이라는 기간은 일반 소멸시효기간이 아니라 제척기간으로서 그 기간이 도과하였는지 여부는 당사자의 주장에 관계없이 법원이 당연히 조사하여 고려할 사항이다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2017_23-35-1","t":"법정대리인인 친권자는 자의 재산에 관한 법률행위에 대하여 그 자를 대리한다. 그러나 그 자의 행위를 목적으로 하는 채무를 부담할 경우에는 본인의 동의를 얻어야 한다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2017_23-35-2","t":"단독 친권자로 정하여진 부모의 일방이 사망한 경우 생존하는 부 또는 모, 미성년자, 미성년자의 친족은 그 사실을 안 날부터 1개월, 사망한 날부터 6개월 내에 가정법원에 생존하는 부 또는 모를 친권자로 지정할 것을 청구할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2017_23-35-3","t":"부모가 공동으로 친권을 행사하는 경우 부모의 일방이 공동명의로 자를 대리하거나 자의 법률행위에 동의한 때에는 다른 일방의 의사에 반하는 한 그 효력이 없다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2017_23-35-4","t":"친권자는 그 자를 보호 또는 교양하기 위하여 필요한 징계를 할 수 있고 법원의 허가를 얻어 감화 또는 교정기관에 위탁할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2017_23-35-5","t":"친권의 상실, 일시 정지, 일부 제한 또는 대리권과 재산관리권의 상실이 선고된 경우에도 부모의 자녀에 대한 그 밖의 권리와 의무는 변경되지 아니한다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2018_24-10-1","t":"부모가 성년의 자녀에 대하여 직계혈족으로서 민법 제974조 제1호, 제975조에 따라 부담하는 부양의무는 부양의무자가 자기의 사회적 지위에 상응하는 생활을 하면서 생활에 여유가 있음을 전제로 하여 부양을 받을 자가 자력 또는 근로에 의하여 생활을 유지할 수 없는 경우에 한하여 그의 생활을 지원하는 것을 내용으로 하는 제2차 부양의무이다.","ox":"O","m":"①","c":"A","tp":"양육 및 부양의무"},{"y":2018,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2018_24-10-2","t":"부부간의 부양의무 중 과거의 부양료에 관하여는 특별한 사정이 없는 한 부양을 받을 사람이 부양의무자에게 부양의무의 이행을 청구하였음에도 불구하고 부양의무자가 부양의무를 이행하지 아니함으로써 이행지체에 빠진 후의 것에 관하여만 부양료의 지급을 청구할 수 있을 뿐이다.","ox":"O","m":"②","c":"A","tp":"양육 및 부양의무"},{"y":2018,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2018_24-10-3","t":"부부의 일방이 정당한 이유 없이 동거를 거부함으로써 자신의 협력의무를 스스로 저버리고 있다면, 상대방의 동거청구가 권리의 남용에 해당하는 등의 특별한 사정이 없는 한, 상대방에게 부양료의 지급을 청구할 수 없다.","ox":"O","m":"③","c":"A","tp":"양육 및 부양의무"},{"y":2018,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2018_24-10-4","t":"부양료청구권의 침해를 이유로 채권자취소권을 행사하는 경우의 제척기간은 부양료청구권이 구체적인 권리로서 성립한 시기가 아니라 민법 제406조 제2항이 정한 ‘취소원인을 안 날’ 또는 ‘법률행위가 있은 날’로부터 진행한다.","ox":"O","m":"④","c":"A","tp":"양육 및 부양의무"},{"y":2018,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2018_24-10-5","t":"증여자가 증여를 해제할 수 있는 민법 제556조 제1항 제2호의 ‘부양의무’에는 민법 제974조에 규정되어 있는 직계혈족 및 그 배우자 또는 생계를 같이 하는 친족간의 부양의무뿐만 아니라 친족간이 아닌 당사자 사이의 약정에 의한 부양의무도 포함되어, 그 경우에도 민법 제558조(전3조의 규정에 의한 계약의 해제는 이미 이행한 부분에 대하여는 영향을 미치지 아니한다)가 적용된다.","ox":"X","m":"⑤","c":"A","tp":"양육 및 부양의무"},{"y":2019,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2019_25-16-1","t":"일반입양에서는 성년자·미성년자 모두 양자가 될 수 있으나, 친양자 입양에서는 미성년자만이 양자가 될 수 있다.","ox":"O","m":"①","c":"A","tp":"민법상 일반입양과 친양자입양"},{"y":2019,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2019_25-16-2","t":"일반입양에서는 성년자이면 양친이 될 수 있으나, 친양자입양에서는 3년 이상 혼인 중인 부부로서 공동으로 입양하는 것이 원칙이다.","ox":"O","m":"②","c":"A","tp":"민법상 일반입양과 친양자입양"},{"y":2019,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2019_25-16-3","t":"일반입양에서 양자의 입양 전의 친족관계는 입양 후에도 존속하나, 친양자입양에서 친양자의 입양 전의 친족관계는 가정법원에 의해 입양이 확정되면 친양자의 출생시로 소급하여 종료한다.","ox":"X","m":"③","c":"A","tp":"민법상 일반입양과 친양자입양"},{"y":2019,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2019_25-16-4","t":"일반입양의 경우 협의상 파양이 인정될 수 있으나, 친양자입양의 경우 협의상 파양은 할 수 없고 일정한 경우 재판상 파양만이 인정된다.","ox":"O","m":"④","c":"A","tp":"민법상 일반입양과 친양자입양"},{"y":2019,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2019_25-16-5","t":"친양자입양이 취소된 때에는 친양자관계는 소멸하고 입양 전의 친족관계는 부활하는데, 그 취소의 효력이 소급하지 않는다.","ox":"O","m":"⑤","c":"A","tp":"민법상 일반입양과 친양자입양"},{"y":2019,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2019_25-22","t":"이혼에 따른 자녀 양육 및 면접교섭권에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"이혼에 따른 자녀 양육 및 면접교섭권에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["부모 중 한쪽만이 자녀를 양육하게 된 경우 과거의 양육비에 대하여도 상대방이 분담함이 상당하다고 인정되는 경우에는 그 비용의 상환을 청구할 수 있고, 이 경우 반드시 이행청구 이후의 양육비와 동일한 기준에서 정할 필요는 없다.","자녀를 직접 양육하지 아니하는 부모 일방의 직계존속은 그 부모 일방이 사망하였거나 질병, 외국 거주, 그 밖에 불가피한 사정으로 자녀를 면접교섭할 수 없는 경우 가정법원에 자녀와의 면접교섭을 청구할 수 있다.","甲과 乙은 이혼하면서 자녀 丙의 친권자와 양육자를 乙로 지정하는 내용의 조정이 성립되었다. 그 후 甲이 임의로 丙을 양육하게 되었다면 甲은 乙에 대하여 위와 같은 임의적 양육에 관하여 양육비를 청구할 수 없다.","가정법원은 자의 복리를 위하여 필요한 때에 당사자의 청구 또는 직권에 의하여 면접교섭을 제한․변경할 수 있지만, 면접교섭을 배제하기 위해서는 반드시 당사자의 청구가 있어야 한다.","가정법원의 심판에 의하여 구체적인 청구권의 내용과 범위가 확정된 후의 양육비채권 중 이미 이행기가 도달한 후의 양육비채권은 권리자의 의사에 따라 포기, 양도 또는 상계의 자동채권으로 하는 것도 가능하다. 22-17"],"a":4}},{"y":2020,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2020_26-05-1","t":"이혼에 따른 위자료청구권은 일신전속적 권리이므로 청구권자가 위자료의 지급을 구하는 소송을 제기함으로써 청구권을 행사할 의사가 외부적·객관적으로 명백하게 되었다고 하더라도 타인에게 양도하거나 상속 할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2020_26-05-2","t":"부부의 혼인관계가 돌이킬 수 없을 정도로 파탄되었다고 인정된다면 그 파탄의 원인에 대한 원고의 책임이 피고의 책임보다 더 무겁다고 인정되지 않는 한 이혼청구는 인용되어야 한다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2020_26-05-3","t":"공무원이 착오로 협의이혼의사 철회신고서가 제출된 사실을 간과한 나머지 그 후에 제출된 협의이혼신고서를 수리하였다고 하더라도 협의상 이혼의 효력이 생길 수 없다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2020_26-05-4","t":"가정법원의 심판에 의하여 구체적인 청구권의 내용과 범위가 확정된 후의 양육비채권 중 이미 이행기에 도달한 후의 양육비채권은 완전한 재산권으로서 친족법상의 신분으로부터 독립하여 처분이 가능하다.","ox":"O","m":"④","c":"A","tp":"이혼"},{"y":2020,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2020_26-05-5","t":"상대방에게도 이혼의사가 있다고 인정되지만 단지 오기나 보복적인 감정 등의 이유에서 표면적으로만 이혼을 거부하고 있을 뿐 실제로는 혼인생활을 계속할 의사가 없다는 사실이 객관적으로 명백히 드러나는 경우에는 유책배우자라도 이혼을 청구할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2020_26-12-1","t":"양친이 되는 자는 성년이어야 하며, 기혼 또는 미혼을 불문한다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2020_26-12-2","t":"미성년자를 입양하려는 사람은 가정법원의 허가를 받아야 하며, 피성년후견인이 입양을 하거나 양자가 되는 경우에도 가정법원의 허가가 필요하다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2020_26-12-3","t":"배우자가 있는 사람은 그 배우자의 동의를 받아야만 양자가 될 수 있다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2020_26-12-4","t":"피성년후견인은 성년후견인의 동의를 얻더라도 입양을 할 수 없다.","ox":"X","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2020_26-12-5","t":"친양자 입양이 취소되거나 파양된 때에는 친양자관계는 소멸하고 입양 전의 친족관계는 부활하는데, 이 경우 친양자 입양의 취소의 효력은 소급하지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2020_26-36-1","t":"이혼소송 계속 중 배우자의 일방이 사망한 때에는 이혼소송은 종료된다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2020_26-36-2","t":"부모 중 어느 한 쪽만이 자녀를 양육하게 된 경우에 양육하는 일방은 상대방에 대하여 현재 및 장래에 있어서의 양육비 중 적정 금액의 분담을 청구할 수 있음은 물론이고, 부모의 자녀양육의무는 특별한 사정이 없는 한 자녀의 출생과 동시에 발생하는 것이므로 과거의 양육비에 대하여도 상대방이 분담함이 상당하다고 인정되는 경우에는 그 비용의 상환을 청구할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2020_26-36-3","t":"소극재산의 총액이 적극재산의 총액을 초과하여 재산분할을 한 결과가 결국 채무의 분담을 정하는 것이 되는 경우에도 법원은 채무의 성질, 채권자와의 관계, 물적 담보의 존부 등 일체의 사정을 참작하여 이를 분담하게 하는 것이 적합하다고 인정되면 구체적인 분담의 방법 등을 정하여 재산분할청구를 받아들일 수 있다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2020_26-36-4","t":"당사자가 이혼소송과 병합하여 재산분할청구를 한 경우에는 법원이 이혼과 동시에 재산분할로서 금전의 지급을 명하는 판결이 확정되기 전이라도 재산분할청구권을 양도할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2020_26-36-5","t":"이혼에 따른 재산분할청구권에 의하여 재산을 취득하는 것이 상당한 정도를 벗어나서 사해행위로서 채권자취소권의 대상이 되는 경우 취소되는 범위는 그 상당한 부분을 초과하는 부분에 한정된다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2021_27-17","t":"다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"다음 설명 중 가장 옳지 않은 것은?","d":"","o":["협의상 이혼을 하려는 자는 가정법원이 제공하는 이혼에 관한 안내를 받아야 하고, 가정법원은 필요한 경우 당사자에게 상담에 관하여 전문적인 지식과 경험을 갖춘 전문상담인의 상담을 받을 것을 권고할 수 있다.","가정법원에 이혼의사의 확인을 신청한 당사자는 위 ①항의 안내를 받은 날부터 다음 각 호의 기간이 지난 후에 이혼의사의 확인을 받을 수 있다. 1.양육하여야 할 자(포태 중인 자를 포함한다)가 있는 경우에는 3개월 2.제1호에 해당하지 아니하는 경우에는 1개월","가정법원은 폭력으로 인하여 당사자 일방에게 참을 수 없는 고통이 예상되는 등 이혼을 하여야 할 급박한 사정이 있는 경우에 위 ②항의 기간을 단축할 수 있으나, 면제할 수는 없다.","당사자는 그 자의 양육에 관한 사항을 협의에 의하여 정하여야 하는데, 양육자의 결정, 양육비용의 부담, 면접교섭권의 행사 여부 및 그 방법에 관한 사항을 포함하여야 한다.","가정법원은 당사자가 협의한 양육비부담에 관한 내용을 확인하는 양육비부담조서를 작성하여야 한다. 이 경우 양육비부담조서의 효력에 대하여는 가사소송법 제41조를 준용한다."],"a":3}},{"y":2021,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2021_27-24-1","t":"성년후견제도의 도입 취지 및 목적, 성년후견인의 임무와 범위, 가정법원의 감독권한 등을 종합하면 성년후견인의 변경사유인 ‘피성년후견인의 복리를 위하여 후견인을 변경할 필요가 있다고 인정되는 경우’는 가정법원이 성년후견인의 임무수행을 전체적으로 살펴보았을 때 선량한 관리자로서의 주의의무를 게을리하여 후견인으로서 그 임무를 수행하는 데 적당하지 않은 사유가 있는 경우로서 그 부적당한 점으로 피후견인의 복리에 영향이 있는 경우라고 봄이 상당하다. 또한 성년후견인의 임무에는 피성년후견인의 재산관리 임무뿐 아니라 신상보호 임무가 포함되어 있고, 신상보호 임무 역시 재산관리 임무 못지않게 피성년후견인의 복리를 위하여 중요한 의미를 가지기 때문에, 특별한 사정이 없는 한 성년후견인 변경사유를 판단함에 있어서는 재산관리와 신상보호의 양 업무의 측면을 모두 고려하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2021_27-24-2","t":"민법 제959조의20 제1항은 “후견계약이 등기되어 있는 경우에는 가정법원은 본인의 이익을 위하여 특별히 필요할 때에만 임의후견인 또는 임의후견감독인의 청구에 의하여 성년후견, 한정후견 또는 특정후견의 심판을 할 수 있다. 이 경우 후견계약은 본인이 성년후견 또는 한정후견 개시의 심판을 받은 때 종료된다.”라고 규정하고, 같은 조 제2항은 “본인이 피성년후견인, 피한정후견인 또는 피특정후견인인 경우에 가정법원은 임의후견감독인을 선임함에 있어서 종전의 성년후견, 한정후견 또는 특정후견의 종료 심판을 하여야 한다. 다만 성년후견 또는 한정후견 조치의 계속이 본인의 이익을 위하여 특별히 필요하다고 인정하면 가정법원은 임의후견감독인을 선임하지 아니한다.”라고 규정하고 있다. 민법 제959조의20 제1항은 본인에 대해 한정후견개시심판 청구가 제기된 후 심판이 확정되기 전에 후견계약이 등기된 경우에는 적용되지 않는다고 보아야 한다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2021_27-24-3","t":"민법 제865조 제1항은 “제845조, 제846조, 제848조, 제850조, 제851조, 제862조, 제863조의 규정에 의하여 소를 제기할 수 있는 자는 다른 사유를 원인으로 하여 친생자관계존부확인의 소를 제기할 수 있다.”라고 정하고 있으나, 친생자관계존부확인의 소를 제기할 수 있는 자는 민법 제865조 제1항에서 정한 제소권자로 한정된다고 볼 수 없다고 봄이 타당하다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2021_27-24-4","t":"친족의 범위에 관하여 규정한 민법 제777조에서 정한 친족에 해당하기만 하면 당연히 친생자관계존부확인의 소를 제기할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2021_27-24-5","t":"제사주재자는 우선적으로 망인의 공동상속인들 사이의 협의에 의해 정하되, 협의가 이루어지지 않는 경우에는 제사주재자의 지위를 유지할 수 없는 특별한 사정이 있지 않은 한 망인의 장남이 제사주재자가 되고, 망인의 장남이 이미 사망한 경우에는 장남의 아들, 즉 장손자가 있다고 하더라도 망인의 차남이 제사주재자가 된다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2021_27-35-1","t":"친생부인의 소는 남편 또는 아내가 다른 일방 또는 자(子)를 상대로 하여 그 사유가 있은 날로부터 2년 내에 제기하여야 한다.","ox":"X","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2021_27-35-2","t":"남편이나 아내가 피성년후견인인 경우에는 남편이나 아내가 성년후견감독인의 동의를 받아 친생부인의 소를 제기할 수 있다. 성년후견감독인이 없거나 동의할 수 없을 때에는 가정법원에 그 동의를 갈음하는 허가를 청구할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2021_27-35-3","t":"친생부인의 소의 원고적격이 있는 처(妻)는 자(子)의 생모뿐만 아니라 부(父)와 재혼한 처(妻)도 포함한다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2021_27-35-4","t":"부(夫)가 자(子)의 출생 전에 사망하거나 부(夫) 또는 처(妻)가 민법 제847조 제1항의 기간내에 사망한 때에는 부(夫) 또는 처(妻)의 직계존속이나 직계비속에 한하여 그 사망을 안 날부터 2년 내에 친생부인의 소를 제기할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2021_27-35-5","t":"친생부인의 조정이 성립되면 친생부인의 효력이 발생한다.","ox":"X","m":"⑤","c":"A","tp":"친생부인의 소"},{"y":2022,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2022_28-28-1","t":"甲과 乙은 가정법원이 제공하는 이혼에 관한 안내를 받아야 하고, 가정법원은 필요한 경우 당사자에게 상담에 관하여 전문적인 지식과 경험을 갖춘 전문상담인의 상담을 받을 것을 권고할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2022_28-28-2","t":"이혼 후 미성년인 자에 대한 친권을 가지는 사람 및 양육자를 정함에 있어서는 모든 요소를 종합적으로 고려하여 미성년인 자의 성장과 복지에 가장 도움이 되고 적합한 방향으로 판단하여야 하므로, 丙에 대한 친권과 양육권이 항상 같은 사람에게 돌아가도록 하여야 한다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2022_28-28-3","t":"甲과 乙 중 丙을 직접 양육하지 않는 일방과 丙은 상호 면접교섭할 수 있는 권리를 가진다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2022_28-28-4","t":"가정법원은 丙의 복리를 위하여 필요하다고 인정하는 경우에는 甲ㆍ乙ㆍ丙 및 검사의 청구 또는 직권으로 丙의 양육에 관한 사항을 변경하거나 다른 적당한 처분을 할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2022_28-28-5","t":"가정법원은 甲과 乙이 협의한 양육비부담에 관한 내용을 확인하는 양육비부담조서를 작성하여야 한다. 이 경우 양육비부담조서는 양육비 이행에 관한 집행권원이 된다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2022_28-31-1","t":"친생자 출생신고 당시 입양의 실질적 요건을 갖추지 못하여 입양신고로서의 효력이 생기지 않았더라도 그 후에 입양의 실질적 요건을 갖추게 된 경우에는 무효인 친생자 출생신고는 소급적으로 입양신고로서의 효력을 갖게 된다고 할 것이나, 당사자 간에 무효인 신고행위에 상응하는 신분관계가 실질적으로 형성되어 있지 아니한 경우에는 무효인 신분행위에 대한 추인의 의사표시만으로 그 무효행위의 효력을 인정할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2022_28-31-2","t":"조부모가 자녀의 입양허가를 청구하는 경우에 입양의 요건을 갖추고 입양이 자녀의 복리에 부합한다면 이를 허가할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2022_28-31-3","t":"입양으로 인한 친족관계는 입양의 취소 또는 파양으로 인하여 종료하므로, 양부모가 이혼하였을 경우에는 양부자관계는 존속하지만 양모자관계는 소멸한다.","ox":"X","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2022_28-31-4","t":"친생자 출생신고가 입양의 효력을 갖는 경우, 양친 부부 중 일방이 사망한 후 생존하는 다른 일방이 사망한 일방과 양자 사이의 양친자관계의 해소를 위하여 재판상 파양에 갈음하는 친생자관계부존재확인청구를 할 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2022_28-31-5","t":"입양신고가 형식적으로만 입양한 것처럼 가장하기로 하여 이루어진 것일 뿐 당사자 사이에 실제로 양친자로서의 신분적 생활관계를 형성한다는 의사의 합치가 없었던 것이라면 이는 당사자 간에 입양의 합의가 없는 때에 해당하여 무효이다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2022_28-36-1","t":"협의이혼하는 경우 부모의 협의로 친권자를 정하되, 협의를 할 수 없거나 협의가 이루어지지 않는 때에는 가정법원은 직권 또는 당사자의 청구에 따라 친권자를 지정하여야 한다. 다만 부모의 협의가 있는 경우에 가정법원은 그에 따라 친권자를 지정하여야 한다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2022_28-36-2","t":"부모 중 어느 한 쪽만이 자녀를 양육하게 된 경우에, 양육하는 일방은 상대방에 대하여 현재 및 장래에 있어서의 양육비 중 적정 금액의 분담을 청구할 수 있음은 물론이고, 부모의 자녀양육의무는 특별한 사정이 없는 한 자녀의 출생과 동시에 발생하는 것이므로 과거의 양육비에 대하여도 상대방이 분담함이 상당하다고 인정되는 경우에는 그 비용의 상환을 청구할 수 있으나, 반드시 이행청구 이후의 양육비와 동일한 기준에서 정할 필요는 없고 여러 사정을 고려하여 적절하다고 인정되는 분담의 범위를 정할 수 있다.","ox":"O","m":"②","c":"A","tp":"이혼"},{"y":2022,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2022_28-36-3","t":"재판상 이혼사유에 관한 민법 제840조는 동조가 규정하고 있는 각 호사유마다 각 별개의 독립된 이혼사유를 구성하는 것이고, 이혼청구를 구하면서 위 각 호 소정의 수개의 사유를 주장하는 경우 법원은 그 중 어느 하나를 받아들여 청구를 인용할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2022_28-36-4","t":"상대방 배우자도 혼인을 계속할 의사가 없어 일방의 의사에 따른 이혼 내지 축출이혼의 염려가 없는 경우는 물론, 나아가 이혼을 청구하는 배우자의 유책성을 상쇄할 정도로 상대방 배우자 및 자녀에 대한 보호와 배려가 이루어진 경우, 세월의 경과에 따라 혼인파탄 당시 현저하였던 유책배우자의 유책성과 상대방 배우자가 받은 정신적 고통이 점차 약화되어 쌍방의 책임의 경중을 엄밀히 따지는 것이 더 이상 무의미할 정도가 된 경우 등과 같이 혼인생활의 파탄에 대한 유책성이 이혼청구를 배척해야 할 정도로 남아 있지 아니한 특별한 사정이 있는 경우에는 예외적으로 유책배우자의 이혼청구를 허용할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2022_28-36-5","t":"협의이혼에 있어서 이혼의사는 법률상 부부관계를 해소하려는 의사를 말하므로 일시적으로나마 법률상 부부관계를 해소하려는 당사자간의 합의하에 협의이혼신고가 된 이상 협의이혼에 다른 목적이 있더라도 양자간에 이혼의사가 없다고는 말할 수 없고 따라서 이와 같은 협의이혼은 무효로 되지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2023_29-02-1","t":"민법은 입양의 요건으로 동의와 허가 등에 관하여 규정하고 있을 뿐이고 존속을 제외하고는 혈족의 입양을 금지하고 있지 않으므로, 조부모가 손자녀를 입양하여 부모·자녀 관계를 맺는 것도 가능하다.","ox":"O","m":"①","c":"A","tp":"친자관계 등"},{"y":2023,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2023_29-02-2","t":"인지의 소의 확정판결에 의하여 일단 부와 자 사이에 친자관계가 창설된 이상, 확정판결에 반하여 친생자관계부존재확인의 소로써 당사자 사이에 친자관계가 존재하지 않는다고 다툴 수는 없다.","ox":"O","m":"②","c":"A","tp":"친자관계 등"},{"y":2023,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2023_29-02-3","t":"아내가 혼인 중 남편이 아닌 제3자의 정자를 제공받아 인공수정으로 자녀를 출산한 경우에도 친생추정 규정을 적용하여 인공수정으로 출생한 자녀는 남편의 자녀로 추정된다.","ox":"O","m":"③","c":"A","tp":"친자관계 등"},{"y":2023,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2023_29-02-4","t":"인지청구권은 본인의 일신전속적인 신분관계상의 권리로서 포기할 수 없고, 포기하였더라도 그 효력이 발생할 수 없으며, 이와 같이 인지청구권의 포기가 허용되지 않는 이상 거기에 실효의 법리가 적용될 여지도 없다.","ox":"O","m":"④","c":"A","tp":"친자관계 등"},{"y":2023,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2023_29-02-5","t":"성전환자가 미성년자인 자녀가 있는 경우에는, 가족관계등록부에 기재된 성별을 정정하여 미성년자인 자녀의 법적 지위와 그에 대한 사회적 인식에 곤란을 초래하는 것까지 허용할 수는 없으므로, 미성년자인 자녀를 둔 성전환자의 성별정정은 허용되지 않는다.","ox":"X","m":"⑤","c":"A","tp":"친자관계 등"},{"y":2023,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2023_29-06-1","t":"일반적으로 약혼은 특별한 형식을 거칠 필요 없이 장차 혼인을 체결하려는 당사자 사이에 합의가 있으면 성립한다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2023_29-06-2","t":"약혼을 하는 당사자 일방은 자신의 학력, 경력 및 직업과 같은 혼인의사를 결정하는 데 있어 중대한 영향을 미치는 사항에 관하여 이를 상대방에게 사실대로 고지할 신의성실의 원칙상의 의무가 있다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2023_29-06-3","t":"약혼예물이 수수된 경우 특별한 사정이 없는 한 일단 부부관계가 성립하고 그 혼인이 상당 기간 지속된 이상 후일 부부 일방의 귀책사유로 혼인이 해소되어도 약혼예물의 반환을 구할 수는 없다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2023_29-06-4","t":"약혼의 해제에 관하여 과실이 있는 유책자는 상대방에게 자신이 제공한 약혼예물의 반환을 구할 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2023_29-06-5","t":"사실혼관계가 단기간에 해소된 경우, 혼인생활에 사용하기 위하여 부부 일방이 자신의 비용으로 구입한 가재도구 등을 상대방이 점유하고 있다면 그 상대방에 대하여 그 구입비용 상당액의 손해배상을 청구할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2024_30-13","t":"다음 설명 중 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"다음 설명 중 옳은 것을 모두 고른 것은?","d":"ㄱ.인지청구권은 본인의 일신전속적인 신분관계상의 권리로서 포기할 수도 없으며 포기하였더라도 그 효력이 발생할 수 없는 것이고, 이와 같이 인지청구권의 포기가 허용되지 않는 이상 거기에 실효의 법리가 적용될 여지도 없다.\nㄴ.혼인 외의 출생자가 부의 사망 후에 인지의 소에 의하여 친생자로 인지받은 경우 피인지자보다 후순위 상속인인 피상속인의 직계존속 또는 형제자매 등은 피인지자의 출현과 함께 자신이 취득한 상속권을 잃게 되므로, 이들은 민법 제860조 단서의 규정에 따라 인지의 소급효 제한에 의하여 보호받게 되는 제3자에 포함된다.\nㄷ.민법 제865조의 규정에 의하여 이해관계 있는 제3자가 친생자관계 부존재확인을 청구하는 경우 친자 쌍방이 다 생존하고 있는 경우는 친자 쌍방을 피고로 삼아야 하고, 친자 중 어느 한편이 사망하였을 때에는 생존자만을 피고로 삼아야 하며, 친자가 모두 사망하였을 경우에는 검사를 상대로 소를 제기할 수 있다. 친생자관계존부확인소송은 소송물이 일신전속적인 것이기는 하나, 제3자가 친자 쌍방을 상대로 제기한 친생자관계부존재확인소송이 계속되던 중 친자 중 어느 한편이 사망하였을 때에는 생존한 사람만 피고가 됨과 동시에 공익적 지위를 갖는 검사가 망인의 소송절차를 수계할 수 있다.\nㄹ.전 등기명의인이 미성년자이고 당해 부동산을 친권자에게 증여하는 행위가 이해상반행위라 하더라도 일단 친권자에게 이전등기가 경료된 이상, 특별한 사정이 없는 한 그 이전등기에 관하여 필요한 절차를 적법하게 거친 것으로 추정된다.\nㅁ.친권자가 수인의 미성년자의 법정대리인으로서 상속재산분할협의를 한 것이라면 이는 민법 제921조에 위반된 것으로서 이러한 대리행위에 의하여 성립된 상속재산분할협의는 피대리자 전원에 의한 추인이 없는 한 무효이다.","o":["ㄱ, ㄹ, ㅁ","ㄱ, ㄷ, ㅁ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㄹ","ㄴ, ㄹ, ㅁ"],"a":1}},{"y":2024,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2024_30-22-1","t":"법률상 혼인관계가 일방 당사자의 사망으로 인하여 종료된 경우에도 생존 배우자에게 재산분할청구권이 인정되지 아니하고 단지 상속에 관한 법률 규정에 따라서 망인의 재산에 대한 상속권만이 인정된다는 점 등에 비추어 보면, 사실혼관계가 일방 당사자의 사망으로 인하여 종료된 경우에는 그 상대방에게 재산분할청구권이 인정된다고 할 수 없다.","ox":"O","m":"①","c":"A","tp":"이혼 내지 사실혼관계의 해소에 따른 재산분할청구"},{"y":2024,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2024_30-22-2","t":"이혼으로 인한 재산분할청구권은 협의 또는 심판에 의하여 그 구체적 내용이 형성되기까지는 그 범위 및 내용이 불명확·불확정하더라도 협의나 심판절차가 개시된 이상 재산분할청구권의 존재 자체는 분명하다고 할 것이므로 이를 보전하기 위하여 채권자대위권을 행사할 수 있다.","ox":"X","m":"②","c":"A","tp":"이혼 내지 사실혼관계의 해소에 따른 재산분할청구"},{"y":2024,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2024_30-22-3","t":"협의이혼을 예정하고 미리 재산분할 협의를 한 경우 협의이혼에 따른 재산분할에 있어 분할의 대상이 되는 재산과 액수는 협의이혼이 성립한 날(이혼신고일)을 기준으로 정하여야 한다. 따라서 재산분할 협의를 한 후 협의이혼 성립일까지의 기간 동안 재산분할 대상인 채무의 일부가 변제된 경우 그 변제된 금액은 원칙적으로 채무액에서 공제되어야 한다.","ox":"O","m":"③","c":"A","tp":"이혼 내지 사실혼관계의 해소에 따른 재산분할청구"},{"y":2024,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2024_30-22-4","t":"이혼 당사자 각자가 보유한 적극재산에서 소극재산을 공제하는 등으로 재산상태를 따져 본 결과 재산분할 청구의 상대방이 그에게 귀속되어야 할 몫보다 더 많은 적극재산을 보유하고 있거나 소극재산의 부담이 더 적은 경우에는 적극재산을 분배하거나 소극재산을 분담하도록 하는 재산분할은 어느 것이나 가능하다고 보아야 하고, 후자의 경우라고 하여 당연히 재산분할 청구가 배척되어야 한다고 할 것은 아니다.","ox":"O","m":"④","c":"A","tp":"이혼 내지 사실혼관계의 해소에 따른 재산분할청구"},{"y":2024,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2024_30-22-5","t":"이혼하지 않은 당사자가 장차 협의상 이혼할 것을 합의하는 과정에서 이를 전제로 재산분할청구권을 포기하는 서면을 작성한 경우, 부부 쌍방의 협력으로 형성된 공동재산 전부를 청산·분배하려는 의도로 재산분할의 대상이 되는 재산액, 이에 대한 쌍방의 기여도와 재산분할 방법 등에 관하여 협의한 결과 부부 일방이 재산분할청구권을 포기하기에 이르렀다는 등의 사정이 없는 한 성질상 허용되지 아니하는 ‘재산분할청구권의 사전포기’에 불과할 뿐이므로 쉽사리 ‘재산분할에 관한 협의’로서의 ‘포기약정’이라고 보아서는 아니 된다.","ox":"O","m":"⑤","c":"A","tp":"이혼 내지 사실혼관계의 해소에 따른 재산분할청구"},{"y":2024,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2024_30-38-1","t":"양육자는 인지판결의 확정 전에 발생한 과거의 양육비에 대하여도 상대방이 부담함이 상당한 범위 내에서 그 비용의 상환을 청구할 수 있다고 보아야 한다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2024_30-38-2","t":"가정법원이 민법 제924조의2에 따라 부모의 친권 중 양육권만을 제한하여 미성년후견인으로 하여금 자녀에 대한 양육권을 행사하도록 결정한 경우에 민법 제837조를 유추적용하여 미성년후견인은 비양육친을 상대로 가사소송법 제2조 제1항 제2호 (나)목 3)에 따른 양육비심판을 청구할 수 있다고 봄이 타당하다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2024_30-38-3","t":"양육자로 지정된 양육친이 비양육친을 상대로 제기한 양육비 청구 사건에서 제1심 가정법원이 자녀가 성년에 이르기 전날을 종기로 삼아 장래양육비의 분담을 정한 경우, 항고심법원이 양육에 관한 사항을 심리한 결과 일정 시점 이후에는 양육자로 지정된 자가 자녀를 양육하지 않고 있는 사실이 확인된다고 하더라도 이를 반영하여 장래양육비의 지급을 명하는 기간을 다시 정할 수는 없다.","ox":"X","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2024_30-38-4","t":"종전에 정해진 양육비의 분담이 과다하게 되었다고 주장하며 감액을 청구하는 경우 법원은 자녀들의 성장에도 불구하고 양육비의 감액이 필요할 정도로 청구인의 소득과 재산이 실질적으로 감소하였는지를 심리·판단하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2024_30-38-5","t":"대한민국 국민과 혼인을 한 후 입국하여 체류자격을 취득하고 거주하다가 한국어를 습득하기 충분하지 않은 기간에 이혼에 이르게 된 외국인이 당사자인 경우, 미성년 자녀의 양육에 있어 한국어 소통능력이 부족한 외국인보다는 대한민국 국민인 상대방에게 양육되는 것이 더 적합할 것이라는 추상적이고 막연한 판단으로 해당 외국인 배우자가 미성년 자녀의 양육자로 지정되기에 부적합하다고 평가하는 것은 옳지 않다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2025_31-24-1","t":"아직 이혼하지 않은 당사자가 장차 협의상 이혼할 것을 합의하는 과정에서 이를 전제로 재산분할청구권을 포기하는 서면을 작성한 경우, 특별한 사정이 없는 한 ‘재산분할에 관한 협의’로서의 ‘포기약정’에 해당한다.","ox":"X","m":"①","c":"A","tp":"이혼 당사자의 재산분할청구"},{"y":2025,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2025_31-24-2","t":"재산분할재판에서 분할대상인지 여부가 전혀 심리된바 없는 재산이 재판확정 후 추가로 발견된 경우에는 이에 대하여 추가로 재산분할청구를 할 수 있지만, 그러한 추가 재산분할청구 역시 이혼한 날부터 2년 이내라는 제척기간을 준수하여야 한다.","ox":"O","m":"②","c":"A","tp":"이혼 당사자의 재산분할청구"},{"y":2025,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2025_31-24-3","t":"협의이혼에 따른 재산분할에서 분할의 대상이 되는 재산과 액수는 협의이혼이 성립한 날(이혼신고일)을 기준으로 정하여야 하지만, 협의이혼을 예정하고 미리 재산분할 협의를 한 경우에는 해당 재산분할 협의 시점을 기준으로 정하여야 한다.","ox":"X","m":"③","c":"A","tp":"이혼 당사자의 재산분할청구"},{"y":2025,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2025_31-24-4","t":"공무원 퇴직연금은 수급권자의 사망으로 그 지급이 종료되는데 수급권자의 여명을 확정할 수 없으므로 그 자체를 재산분할의 대상으로 할 수 없고, 다만 이를 분할액수와 방법을 정함에 있어서 참작되는 ‘기타의 사정’으로 삼는 것으로 족하다.","ox":"X","m":"④","c":"A","tp":"이혼 당사자의 재산분할청구"},{"y":2025,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2025_31-24-5","t":"재산분할재판에서 법원이 적극재산과 소극재산을 구별하거나, 분할대상 재산들을 개별적으로 구분하여 분할비율을 달리 정하는 것도 원칙적으로 허용된다.","ox":"X","m":"⑤","c":"A","tp":"이혼 당사자의 재산분할청구"},{"y":2025,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2025_31-34","t":"친양자 입양에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"친양자 입양에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","d":"ㄱ.친양자가 될 사람이 15세 이상인 경우에는 법정대리인의 동의를 받아 입양을 승낙하고, 15세 미만인 경우에는 법정대리인이 그를 갈음하여 입양을 승낙하여야 한다.\nㄴ.친양자를 입양하려는 사람은 2년 이상 혼인 중인 부부로서 공동으로 입양하여야 하고, 다만 1년 이상 혼인 중인 부부의 한쪽이 그 배우자의 친생자를 친양자로 하는 경우에는 그러하지 않다.\nㄷ.친생부모가 자신에게 책임이 있는 사유로 3년 이상 자녀에 대한 부양의무를 이행하지 아니하고 면접교섭을 하지 아니한 경우에는 동의권자 또는 승낙권자의 동의나 승낙이 없더라도 가정법원은 친양자 입양청구를 인용할 수 있다.\nㄹ.친양자 입양이 취소된 때에는 친양자 관계는 입양한 때로 소급하여 소멸하고 입양 전의 친족관계는 부활한다.\nㅁ.친양자 입양에는 친양자가 될 사람의 친생부모의 동의가 필요하지만, 친생부모의 소재를 알 수 없는 경우에는 그의 동의 없이도 친양자 입양이 가능하다.","o":["ㄱ, ㄷ","ㄱ, ㅁ","ㄴ, ㄹ","ㄷ, ㄹ","ㄷ, ㅁ"],"a":5}},{"y":2025,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2025_31-35-1","t":"사실혼이란 당사자 사이에 주관적으로 혼인의 의사가 있고, 객관적으로도 사회관념상 가족질서적인 면에서 부부공동생활을 인정할 만한 혼인생활의 실체가 있는 경우라야 하고, 법률상 혼인을 한 부부가 별거하고 있는 상태에서 그 다른 한쪽이 제3자와 혼인의 의사로 실질적인 부부생활을 하고 있다고 하더라도, 특별한 사정이 없는 한, 이를 사실혼으로 인정하여 법률혼에 준하는 보호를 할 수는 없는 것이다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2025_31-35-2","t":"중혼적 사실혼관계에 해당한다면, 법률혼인 전 혼인이 사실상 이혼상태에 있다는 등의 특별한 사정이 있더라도, 법률혼에 준하는 보호를 할 필요는 없다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2025_31-35-3","t":"약혼예물의 수수는 약혼의 성립을 증명하고 혼인이 성립한 경우 당사자 내지 양가의 정리를 두텁게 할 목적으로 수수되는 것으로 혼인의 불성립을 해제조건으로 하는 증여와 유사한 성질을 가진다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2025_31-35-4","t":"현행 부부재산제도는 부부별산제를 기본으로 하고 있어 부부 각자의 채무는 각자가 부담하는 것이 원칙이므로 부부가 이혼하는 경우 일방이 혼인 중 제3자에게 부담한 채무는 일상가사에 관한 것 이외에는 원칙적으로 그 개인의 채무로서 청산의 대상이 되지 않으나 그것이 공동재산의 형성·유지에 수반하여 부담한 채무인 때에는 청산의 대상이 된다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2025_31-35-5","t":"재산분할에 관한 협의는 혼인 중 당사자 쌍방의 협력으로 이룩한 재산의 분할에 관하여 이미 이혼을 마친 당사자 또는 아직 이혼하지 않은 당사자 사이에 행하여지는 협의를 가리키는 것이다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2026_32-04-1","t":"이혼한 부부 사이에서 어느 일방이 자녀를 양육하게 된 경우, 특별한 사정이 있는 경우를 제외하고 양육하는 일방은 상대방에 대하여 현재 및 장래 양육비 중 적정 금액의 분담을 청구할 수 있음은 물론이고, 부모의 자녀양육의무는 특별한 사정이 없는 한 자녀의 출생과 동시에 발생하므로 과거 양육비에 대하여도 상대방이 분담함이 상당하다고 인정되는 경우에는 그 비용의 상환을 청구할 수 있다.","ox":"O","m":"①","c":"A","tp":"부양"},{"y":2026,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2026_32-04-2","t":"이혼한 부부 사이에서 어느 일방이 과거에 미성년 자녀를 양육하면서 생긴 비용의 상환을 상대방에게 청구하는 경우, 자녀의 복리를 위해 실현되어야 하는 과거 양육비에 관한 권리의 성질상 그 권리의 소멸시효는 자녀가 미성년이어서 양육의무가 계속되는 동안에는 진행하지 않고 자녀가 성년이 되어 양육의무가 종료된 때부터 진행한다.","ox":"O","m":"②","c":"A","tp":"부양"},{"y":2026,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2026_32-04-3","t":"성년의 자녀는 요부양상태, 즉 객관적으로 보아 생활비 수요가 자기의 자력 또는 근로에 의하여 충당할 수 없는 곤궁한 상태인 경우에 한하여, 부모를 상대로 그 부모가 부양할 수 있을 한도 내에서 생활부조로서 생활필요비에 해당하는 부양료를 청구할 수 있을 뿐이다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2026_32-04-4","t":"부부 간의 상호부양의무는 제1차 부양의무이고, 부모가 성년의 자녀에 대하여 직계혈족으로서 부담하는 부양의무는 제2차 부양의무이다. 제1차 부양의무자와 제2차 부양의무자가 동시에 존재하는 경우에 제1차 부양의무자는 특별한 사정이 없는 한 제2차 부양의무자에 우선하여 부양의무를 부담하지만, 제2차 부양의무자가 부양받을 자를 먼저 부양하였더라도 그 소요된 비용을 제1차 부양의무자에 대하여 상환청구를 할 수는 없다.","ox":"X","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2026_32-04-5","t":"민법 제826조 제1항에 규정된 부부 간의 상호부양의무는 부부의 일방에게 부양을 받을 필요가 생겼을 때 당연히 발생되는 것이기는 하지만, 과거의 부양료에 관하여는 특별한 사정이 없는 한, 부양을 받을 자가 부양의무자에게 부양의무의 이행을 청구하였음에도 불구하고 부양의무자가 부양의무를 이행하지 아니함으로써 이행지체에 빠진 이후의 것에 대하여만 부양료의 지급을 청구할 수 있을 뿐, 부양의무자가 부양의무의 이행을 청구받기 이전의 부양료의 지급은 청구할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2026_32-21-1","t":"이혼을 원인으로 하는 위자료청구권의 액수를 산정할 때에는 개별적 유책행위의 발생으로부터 최종적 이혼에 이르기까지의 모든 사정을 참작하여야 하고, 개별적 유책행위에 대하여 별도의 손해배상청구가 가능하다고 하여 달라지지 않는다.","ox":"O","m":"①","c":"A","tp":"이혼 등 소송"},{"y":2026,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2026_32-21-2","t":"제3자가 부부의 일방과 부정행위를 함으로써 배우자에게 정신적 고통을 가한 경우, 그 제3자가 부담하는 불법행위책임은 부정행위를 한 배우자의 책임과 공동불법행위책임으로서 부진정연대채무관계에 있다.","ox":"O","m":"②","c":"A","tp":"이혼 등 소송"},{"y":2026,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2026_32-21-3","t":"이혼을 원인으로 하는 위자료청구권은 혼인이 해소된 때부터 3년이 지나면 민법 제766조 제1항에서 정한 단기소멸시효가 완성된다.","ox":"O","m":"③","c":"A","tp":"이혼 등 소송"},{"y":2026,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2026_32-21-4","t":"민법 제839조의2 제3항에서 정한 재산분할청구권의 2년의 제척기간은 재판 외에서 권리를 행사하는 것으로도 충분한 기간이지, 반드시 그 기간 내에 재산분할심판 청구를 하여야 하는 출소기간으로 볼 것은 아니다.","ox":"X","m":"④","c":"A","tp":"이혼 등 소송"},{"y":2026,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2026_32-21-5","t":"부부의 일방이 다른 일방의 재산분할청구권 행사를 해할 것을 알면서 재산권을 목적으로 한 법률행위를 한 경우, 다른 일방은 민법 제406조 제1항을 준용하여 그 취소 및 원상회복을 가정법원에 청구할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"이혼 등 소송"},{"y":2026,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2026_32-23-1","t":"이혼위자료청구권은 원칙적으로 일신전속적 권리로서 양도나 상속 등 승계가 되지 아니하나 이는 행사상 일신전속권이고 귀속상 일신전속권은 아니라 할 것인바, 그 청구권자가 위자료의 지급을 구하는 소송을 제기함으로써 청구권을 행사할 의사가 외부적·객관적으로 명백하게 된 이상 양도나 상속 등 승계가 가능하다.","ox":"O","m":"①","c":"A","tp":"일신전속의 권리"},{"y":2026,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2026_32-23-2","t":"공유물분할청구권은 공유자의 일반재산을 구성하는 재산권의 일종이고 그 행사가 오로지 공유자의 자유로운 의사에 맡겨져 있어 공유자 본인만 행사할 수 있는 권리라고 볼 수는 없으므로 공유물분할청구권도 채권자대위권의 목적이 될 수 있다.","ox":"O","m":"②","c":"A","tp":"일신전속의 권리"},{"y":2026,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2026_32-23-3","t":"재판상의 이혼청구권은 부부의 일신전속의 권리로 이혼소송 계속 중 배우자의 일방이 사망한 때에는 상속인이 그 절차를 수계할 수 없으므로 이혼소송은 종료된다. 그러나 이혼소송에 부대한 재산분할청구는 재산법적 행위로 행사상의 일신전속성을 가진다고 할 수 없으므로 상속인이 이를 수계할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2026_32-23-4","t":"혼인 중 형성한 재산관계를 이혼에 즈음하여 청산하는 것을 본질로 하는 재산분할 제도의 취지와 공평의 관념에 비추어 보면, 이혼을 한 당사자 일방이 사망하는 경우 그의 재산분할의무는 상속인들에게 승계된다고 보아야 하고, 특별한 사정이 없는 한 이혼을 한 당사자 일방은 사망한 전 배우자의 상속인들을 상대로 이혼으로 인한 재산분할을 청구할 수 있다.","ox":"O","m":"④","c":"A","tp":"일신전속의 권리"},{"y":2026,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2026_32-23-5","t":"후견인이 피후견인을 대리하여 부동산 또는 중요한 재산에 관한 권리의 득실변경을 목적으로 하는 행위를 하면서 후견감독인의 동의를 얻지 아니한 경우, 민법 제950조 제3항의 규정에 의하여 피후견인 또는 후견감독인이 그 후견인의 행위를 취소할 수 있는 권리는 행사상의 일신전속권이므로 채권자대위권의 목적이 될 수 없다.","ox":"O","m":"⑤","c":"A","tp":"일신전속의 권리"},{"y":2026,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2026_32-33-1","t":"친권자가 자녀에 대한 재산관리 권한으로 자녀 대신 수령한 돈은, 권한 소멸 시 정당지출분을 공제한 나머지를 반환할 의무가 있고, 정당지출에 대한 증명책임은 친권자에게 있다.","ox":"O","m":"①","c":"A","tp":"민법상 자"},{"y":2026,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2026_32-33-2","t":"민법 제921조의 이해상반행위란 행위의 객관적 성질상 친권자와 자 사이에 이해대립 우려가 있는 행위를 가리키고, 친권자의 의도나 그 행위의 결과 실제 이해대립이 생겼는지의 여부는 묻지 않는다.","ox":"O","m":"②","c":"A","tp":"민법상 자"},{"y":2026,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2026_32-33-3","t":"부모 중 어느 한쪽만이 자녀를 양육하게 된 경우, 특별한 사정이 있는 경우를 제외하고는 과거 양육비에 대하여 상대방이 분담하는 것이 상당한 비용의 상환을 청구할 수 있다.","ox":"O","m":"③","c":"A","tp":"민법상 자"},{"y":2026,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2026_32-33-4","t":"양육비 감액 청구 사건에서 법원은 자녀의 복리에 미치는 영향보다는 청구인의 소득⋅재산 감소 여부에 중점을 두고 심리하여야 한다.","ox":"X","m":"④","c":"A","tp":"민법상 자"},{"y":2026,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2026_32-33-5","t":"자의 출생 후에 친생자임을 승인한 자는 다시 친생부인의 소를 제기하지 못한다.","ox":"O","m":"⑤","c":"A","tp":"민법상 자"}],"1":[{"y":2016,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2016_22-01-1","t":"매매계약서에 계약사항에 대한 이의가 생겼을 때에는 매도인의 해석에 따른다는 조항은 법원의 법률행위해석권을 구속하는 조항이라고 볼 수 없다.","ox":"O","m":"①","c":"A","tp":"법률행위의 해석과 이중매매"},{"y":2016,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2016_22-01-2","t":"甲이 허무인 乙명의의 자동차운전면허증과 인장을 위조한 후 이를 이용하여 증권회사인 丙 주식회사에 乙명의로 증권위탁계좌를 개설하였다면, 甲과 丙 회사 사이에는 행위자인 甲을 계약당사자로 한 계좌 개설계약이 체결되었다고 보아야 한다.","ox":"X","m":"②","c":"A","tp":"법률행위의 해석과 이중매매"},{"y":2016,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2016_22-01-3","t":"甲이 A부동산을 乙에게 매도하고, 아직 미등기 상태에서 계약금 및 중도금만 수령한 뒤 다시 丙에게 매도하고 丙에게 소유권이전등기를 마쳐준 경우, 丙이 甲의 이중매매에 적극 가담하였다면, 乙은 甲을 대위하여 丙을 상대로 소유권이전등기의 말소를 청구할 수 있다.","ox":"O","m":"③","c":"A","tp":"법률행위의 해석과 이중매매"},{"y":2016,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2016_22-01-4","t":"부동산의 이중매매가 반사회적행위로서 무효가 된다는 법리는 이중으로 임대차계약을 체결한 경우에도 적용될 수 있다.","ox":"O","m":"④","c":"A","tp":"법률행위의 해석과 이중매매"},{"y":2016,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2016_22-01-5","t":"부동산의 이중매매가 반사회적 법률행위에 해당하는 경우에는 이중매매계약은 절대적으로 무효이므로, 당해 부동산을 제2매수인으로부터 다시 취득한 제3자는 설사 제2매수인이 당해 부동산의 소유권을 유효하게 취득한 것으로 믿었더라도 이중매매계약이 유효하다고 주장할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"법률행위의 해석과 이중매매"},{"y":2016,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2016_22-02-1","t":"매수인이 매도인의 기망에 의하여 타인의 물건을 매도인의 것으로 잘못 알고 매수한다는 의사표시를 하고 만일 타인의 물건인줄 알았더라면 매수하지 아니하였을 사정이 있는 경우에는 매수인은 사기에 의한 것임을 이유로 매수의 의사표시를 취소할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2016_22-02-2","t":"상대방있는 의사표시에 관하여 제3자가 사기나 강박을 행한 경우에는 상대방이 그 사실을 알았거나 알 수 있었을 경우에 한하여 그 의사표시를 취소할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2016_22-02-3","t":"어떤 법률행위가 사기에 의한 것으로서 취소되는 경우에 그 법률행위가 동시에 불법행위를 구성하는 때에는 취소의 효과로 생기는 부당이득반환청구권과 불법행위로 인한 손해배상청구권은 경합하여 병존하는 것이므로, 채권자는 어느 것이라도 선택하여 행사할 수 있지만 중첩적으로는 행사할 수 없다.","ox":"O","m":"③","c":"A","tp":"의사표시"},{"y":2016,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2016_22-02-4","t":"법률행위의 내용의 중요 부분에 착오가 있는 때에는 의사표시를 취소할 수 있는바, 착오가 법률행위 내용의 중요 부분에 있다고 하기 위하여는 표의자에 의하여 추구된 목적을 고려하여 합리적으로 판단하여 볼 때 표시와 의사의 불일치가 객관적으로 현저하여야 하고, 만일 그 착오로 인하여 표의자가 무슨 경제적인 불이익을 입은 것이 아니라고 한다면 이를 법률행위 내용의 중요 부분의 착오라고 할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2016_22-02-5","t":"상대방이 있는 의사표시는 상대방에게 도달한 때에 그 효력이 생기므로, 의사표시자가 그 통지를 발송한 후 사망하는 경우 그 의사표시는 효력이 발생하지 않는다.","ox":"X","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2016_22-03-1","t":"甲은 乙로부터 고려청자로 알고 도자기를 매수하였는데, 그 도자기가 진품이 아닌 것으로 밝혀진 경우, 개인소장자인 매수인 甲이 그 출처의 조회나 전문적 감정인의 감정 없이 매수한 점만으로는 중과실이 인정되지 않으므로 착오를 이유로 계약을 취소할 수 있다.","ox":"O","m":"①","c":"A","tp":"착오에 의한 의사표시"},{"y":2016,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2016_22-03-2","t":"甲신용보증기관이 보증대상 기업인 乙의 실제 경영주 A가 신용불량자라는 사실을 모르고 신용불량자가 아닌 신청명의인 B를 경영주로 오인하여 이를 전제로 기업의 신용도 등을 조사한 후 보증계약을 체결한 경우, 법률행위의 중요부분에 착오가 있는 경우에 해당한다.","ox":"O","m":"②","c":"A","tp":"착오에 의한 의사표시"},{"y":2016,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2016_22-03-3","t":"상린관계에 있는 토지 소유자 甲과 乙이 토지 경계에 관한 다툼을 하던 중, 乙의 경계선을 침범하였다는 강력한 주장에 의하여 甲이 착오로 그간의 경계 침범에 대한 보상금 지급을 약정한 경우, 위 경계선의 착오는 동기의 착오이나 그 착오가 乙로부터 연유한 것으로서 甲의 위 금원 지급의 의사표시는 그 내용의 중요부분에 착오가 있는 것이 되어 취소할 수 있다.","ox":"O","m":"③","c":"A","tp":"착오에 의한 의사표시"},{"y":2016,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2016_22-03-4","t":"甲이 채무자란이 백지로 된 근저당권설정계약서를 제시받고 그 채무자가 乙인 것으로 알고 근저당권설정자로 서명날인을 하였는데 그 후 채무자가 丙으로 되어 근저당권설정등기가 경료된 경우, 甲은 그 소유의 부동산에 관하여 근저당권설정계약상의 채무자를 丙이 아닌 乙로 오인한 나머지 근저당설정의 의사표시를 한 것이고, 이와 같은 착오는 법률행위 내용의 중요부분에 관한 착오에 해당한다.","ox":"O","m":"④","c":"A","tp":"착오에 의한 의사표시"},{"y":2016,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2016_22-03-5","t":"금융기관 甲은 신용보증기금 乙의 신용보증서를 담보로 금융채권자금을 대출해 주었는데, 甲은 대출자금이 모두 상환되지 않았음에도 착오로 乙에게 신용보증담보설정의 해지를 통지한 경우, 그 해지의 의사표시는 민법 제109조 제1항 단서 소정의 중대한 과실에 해당하지 아니한다.","ox":"X","m":"⑤","c":"A","tp":"착오에 의한 의사표시"},{"y":2016,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2016_22-07-1","t":"표현대리행위가 성립하는 경우에 그 본인은 표현대리행위에 의하여 전적인 책임을 져야 하고, 상대방에게 과실이 있다고 하더라도 과실상계의 법리를 유추적용하여 본인의 책임을 경감할 수 없다.","ox":"O","m":"①","c":"A","tp":"표현대리 또는 무권대리"},{"y":2016,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2016_22-07-2","t":"민법 제125조가 규정하는 대리권 수여의 표시에 의한 표현대리는 본인과 대리행위를 한 자 사이의 기본적인 법률관계의 성질이나 그 효력의 유무와는 관계없이 어떤 자가 본인을 대리하여 제3자와 법률행위를 함에 있어 본인이 그 자에게 대리권을 수여하였다는 표시를 제3자에게 한 경우에 성립하는 것이다.","ox":"O","m":"②","c":"A","tp":"표현대리 또는 무권대리"},{"y":2016,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2016_22-07-3","t":"다른 자의 대리인으로서 계약을 맺은 자가 그 대리권을 증명하지 못하고 또 본인의 추인을 받지 못한 경우에는 그는 상대방의 선택에 따라 계약을 이행할 책임 또는 손해를 배상할 책임이 있으나, 대리인으로서 계약을 맺은 자에게 대리권이 없다는 사실을 상대방이 알았거나 알 수 있었을 때 또는 대리인으로서 계약을 맺은 사람이 제한능력자일 때에는 그러하지 아니하다.","ox":"O","m":"③","c":"A","tp":"표현대리 또는 무권대리"},{"y":2016,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2016_22-07-4","t":"민법 제135조 제1항에 따른 무권대리인의 상대방에 대한 책임은 무권대리행위가 제3자의 기망이나 문서위조 등 위법행위로 야기된 경우에 그 책임은 부정된다.","ox":"X","m":"④","c":"A","tp":"표현대리 또는 무권대리"},{"y":2016,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2016_22-07-5","t":"종중으로부터 임야의 매각과 관련한 권한을 부여받은 甲이 임야의 일부를 실질적으로 자기가 매수하여 그 처분권한이 있다고 하면서 乙로부터 금원을 차용하고 그 담보를 위하여 위 임야에 대하여 양도담보계약을 체결하였으며 乙도 그와 같이 알고 있었던 이상, 이는 종중을 위한 대리행위가 아니어서 그 효력이 종중에게 미치지 아니하고, 민법 제126조의 표현대리의 법리가 적용될 수도 없다.","ox":"O","m":"⑤","c":"A","tp":"표현대리 또는 무권대리"},{"y":2016,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2016_22-10-1","t":"상대방과 통정한 허위의 의사표시는 무효이고 누구든지 그 무효를 주장할 수 있는 것이 원칙이나, 허위표시의 당사자 및 포괄승계인 이외의 자로서 허위표시에 의하여 외형상 형성된 법률관계를 토대로 실질적으로 새로운 법률상 이해관계를 맺은 선의의 제3자에 대하여는 허위표시의 당사자뿐만 아니라 그 누구도 허위표시의 무효를 대항하지 못한다 할 것이고, 따라서 위와 같은 선의의 제3자에 대한 관계에 있어서는 허위표시도 그 표시된 대로 효력이 있다.","ox":"O","m":"①","c":"A","tp":"통정허위표시"},{"y":2016,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2016_22-10-2","t":"임대차보증금반환채권이 양도된 후 그 양수인의 채권자가 임대차보증금반환채권에 대하여 채권압류 및 추심명령을 받았는데 그 임대차보증금반환채권 양도계약이 허위표시로서 무효인 경우, 그 채권자는 그로 인해 외형상 형성된 법률관계를 기초로 실질적으로 새로운 법률상 이해관계를 맺은 제3자에 해당하지 않는다.","ox":"X","m":"②","c":"A","tp":"통정허위표시"},{"y":2016,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2016_22-10-3","t":"통정허위표시의 무효는 선의의 제3자에게 대항하지 못하는데, 여기의 제3자는 선의이면 족하고 무과실은 요건이 아니다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2016_22-10-4","t":"파산채무자가 상대방과 통정한 허위의 의사표시를 통하여 가장채권을 보유하고 있다가 파산이 선고된 경우 그 가장채권도 일단 파산재단에 속하게 되고, 파산선고에 따라 파산채무자와는 독립한 지위에서 파산채권자 전체의 공동의 이익을 위하여 직무를 행하게 된 파산관재인은 그 허위표시에 따라 외형상 형성된 법률관계를 토대로 실질적으로 새로운 법률상 이해관계를 가지게 된 민법 제108조 제2항의 제3자에 해당한다.","ox":"O","m":"④","c":"A","tp":"통정허위표시"},{"y":2016,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2016_22-10-5","t":"채무자의 법률행위가 통정허위표시인 경우에도 채권자취소권의 대상으로 된다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2016_22-12-1","t":"소멸시효 완성의 이익 포기의 의사표시는 채무자에게 불리한 행위로서 시효이익을 받을 당사자인 채무자에 의하여 행하여져야 하고, 그 대리인에 의하여 행하여질 수 없다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2016_22-12-2","t":"대리인이 본인을 위한 것임을 표시하지 아니한 때에는 그 의사표시는 자기를 위한 것으로 본다. 그러나 상대방이 대리인으로서 한 것임을 알 수 있었을 때에는 본인에게 대하여 효력이 생긴다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2016_22-12-3","t":"대리인에 의하여 법률행위가 이루어진 경우 그 법률행위가 민법 제104조의 불공정한 법률행위에 해당하는지 여부를 판단함에 있어서 경솔과 무경험은 대리인을 기준으로 하여 판단하고, 궁박은 본인의 입장에서 판단하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2016_22-12-4","t":"대리권이 법률행위에 의하여 부여된 경우에는 대리인은 본인의 승낙이 있거나 부득이한 사유있는 때가 아니면 복대리인을 선임하지 못한다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2016_22-12-5","t":"매매계약의 체결과 이행에 관하여 포괄적으로 대리권을 수여받은 대리인은 특별한 다른 사정이 없는 한 상대방에 대하여 약정된 매매대금 지급기일을 연기하여 줄 권한도 가진다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2016_22-14-1","t":"민법 제35조 제1항은 ‘법인은 이사 기타 대표자가 그 직무에 관하여 타인에게 가한 손해를 배상할 책임이 있다.’라고 규정하고 있는바, 여기서 ‘법인의 대표자’에는 그 명칭이나 직위 여하, 또는 대표자로 등기되었는지 여부를 불문하고 당해 법인을 실질적으로 운영하면서 법인을 사실상 대표하여 법인의 사무를 집행하는 사람을 포함한다고 해석함이 타당하다.","ox":"O","m":"①","c":"A","tp":"법인의 불법행위능력"},{"y":2016,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2016_22-14-2","t":"법인의 목적범위 외의 행위로 인하여 타인에게 손해를 가한 때에는 그 사항의 의결에 찬성하거나 그 의결을 집행한 사원, 이사 및 기타 대표자가 연대하여 배상하여야 한다.","ox":"O","m":"②","c":"A","tp":"법인의 불법행위능력"},{"y":2016,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2016_22-14-3","t":"비법인사단의 대표자의 행위가 대표자 개인의 사리를 도모하기 위한 것이었거나 또는 법령의 규정에 위배된 것이었다고 하더라도 외관상, 객관적으로 직무에 관한 행위라고 인정할 수 있다면 민법 제35조 제1항의 직무에 관한 행위에 해당한다고 할 것이나, 그 대표자의 행위가 직무에 관한 행위에 해당하지 아니함을 피해자 자신이 알았거나 또는 과실(중과실, 경과실을 불문한다)로 인하여 알지 못한 경우에는 비법인사단에게 손해배상 책임을 물을 수 없다.","ox":"X","m":"③","c":"A","tp":"법인의 불법행위능력"},{"y":2016,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2016_22-14-4","t":"재개발조합의 대표기관의 직무상 불법행위로 조합에게 과다한 채무를 부담하게 함으로써 재개발조합이 손해를 입고 결과적으로 조합원의 경제적 이익이 침해되는 손해와 같은 간접적인 손해는 민법 제35조에서 말하는 손해의 개념에 포함되지 않으므로 이에 대하여는 위 법 조항에 의하여 손해배상을 청구할 수 없다.","ox":"O","m":"④","c":"A","tp":"법인의 불법행위능력"},{"y":2016,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2016_22-14-5","t":"민법 제35조에서 말하는 ‘이사 기타 대표자’는 법인의 대표기관을 의미하는 것이고, 대표권이 없는 이사는 법인의 기관이기는 하지만 대표기관은 아니기 때문에 그들의 행위로 인하여 법인의 불법행위가 성립하지 않는다.","ox":"O","m":"⑤","c":"A","tp":"법인의 불법행위능력"},{"y":2016,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2016_22-37-1","t":"법인은 그 주된 사무소의 소재지에서 설립등기를 함으로써 성립하고, 법률의 규정에 좇아 정관으로 정한 목적의 범위 내에서 권리와 의무의 주체가 된다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2016_22-37-2","t":"유언으로 재단법인을 설립하는 경우에도 제3자에 대한 관계에서는 출연재산이 부동산인 경우는 그 법인에의 귀속에는 법인의 설립 외에 등기를 필요로 하는 것이므로, 재단법인이 그와 같은 등기를 마치지 않았다면 유언자의 상속인의 한 사람으로부터 부동산의 지분을 취득하여 이전등기를 마친 선의의 제3자에 대하여 대항할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2016_22-37-3","t":"민법 제47조 제1항에 의하여 생전처분으로 재단법인을 설립하는 때에 준용되는 민법 제555조는 ‘증여의 의사가 서면으로 표시되지 아니한 경우에는 각 당사자는 이를 해제할 수 있다.’고 함으로써 서면에 의한 증여(출연)의 해제를 제한하고 있으나, 그 해제는 민법 총칙상의 취소와는 요건과 효과가 다르므로 서면에 의한 출연이더라도 민법 총칙규정에 따라 출연자가 착오에 기한 의사표시라는 이유로 출연의 의사표시를 취소할 수 있고, 상대방 없는 단독행위인 재단법인에 대한 출연행위라고 하여 달리 볼 것은 아니다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2016_22-37-4","t":"이사의 대표권에 대한 제한은 이를 정관에 기재하지 않으면 그 효력이 없다.","ox":"O","m":"④","c":"A","tp":"법인"},{"y":2016,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2016_22-37-5","t":"출연재산은 출연자와 법인과의 관계에 있어서 그 출연행위에 터잡아 법인이 성립되면 그로써 출연재산은 민법 제48조에 의하여 법인성립 시에 법인에게 귀속되어 법인의 재산이 되는 것이 원칙이나, 출연재산이 부동산인 경우 그 출연재산이 법인에 귀속되기 위해서는 제3자에 대한 관계에 있어서뿐만 아니라, 출연자와 법인과의 관계에 있어서도 위 요건(법인의 성립) 외에 등기를 필요로 한다.","ox":"X","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2017_23-01-1","t":"신의성실의 원칙에 반하는 것은 강행규정에 위배되는 것으로서 당사자의 주장이 없더라도 법원이 직권으로 판단할 수 있다.","ox":"O","m":"①","c":"A","tp":"신의칙과 그 파생원칙"},{"y":2017,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2017_23-01-2","t":"임대차계약에 있어서 차임불증액의 특약이 있더라도 그 약정 후 그 특약을 그대로 유지시키는 것이 신의칙에 반한다고 인정될 정도의 사정변경이 있다고 보여지는 경우에는 형평의 원칙상 임대인에게 차임증액청구를 인정하여야 한다.","ox":"O","m":"②","c":"A","tp":"신의칙과 그 파생원칙"},{"y":2017,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2017_23-01-3","t":"공무원의 불법행위로 손해를 입은 피해자의 국가배상청구권의 소멸시효 기간이 지났으나 국가가 소멸시효 완성을 주장하는 것이 신의성실의 원칙에 반하는 권리남용으로 허용될 수 없어 배상책임을 이행한 경우에는, 소멸시효 완성 주장이 권리남용에 해당하게 된 원인행위와 관련하여 공무원이 원인이 되는 행위를 적극적으로 주도하였다는 등의 특별한 사정이 없는 한, 국가가 공무원에게 구상권을 행사하는 것은 신의칙상 허용되지 않는다.","ox":"O","m":"③","c":"A","tp":"신의칙과 그 파생원칙"},{"y":2017,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2017_23-01-4","t":"계약의 해제로 인한 원상회복청구권에 대하여 해제자가 해제의 원인이 된 채무불이행에 관하여 ‘원인’의 일부를 제공하였다면 신의칙 또는 공평의 원칙에 기하여 일반적으로 손해배상에 있어서의 과실상계에 준하여 권리의 내용이 제한될 수 있다.","ox":"X","m":"④","c":"A","tp":"신의칙과 그 파생원칙"},{"y":2017,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2017_23-01-5","t":"위임계약에서 보수액에 관하여 약정한 경우에 수임인은 원칙적으로 약정보수액을 전부 청구할 수 있는 것이 원칙이지만 위임의 경위, 위임업무 처리의 경과와 난이도, 투입한 노력의 정도, 위임인이 업무 처리로 인하여 얻게 되는 구체적 이익, 기타 변론에 나타난 제반 사정을 고려할 때 약정보수액이 부당하게 과다하여 신의성실의 원칙이나 형평의 원칙에 반한다고 볼 만한 특별한 사정이 있는 때에는 예외적으로 상당하다고 인정되는 범위 내의 보수액만을 청구할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"신의칙과 그 파생원칙"},{"y":2017,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2017_23-02-1","t":"법정대리인은 원칙적으로 미성년자가 법정대리인의 동의 없이 한 법률행위를 취소할 수 있다.","ox":"O","m":"①","c":"A","tp":"자연인의 능력"},{"y":2017,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2017_23-02-2","t":"가정법원은 질병, 장애, 노령, 그 밖의 사유로 인한 정신적 제약으로 사무를 처리할 능력이 지속적으로 결여된 사람에 대하여 본인, 배우자, 4촌 이내의 친족, 미성년후견인, 미성년후견감독인, 한정후견인, 한정후견감독인, 특정후견인, 특정후견감독인, 검사 또는 지방자치단체의 장의 청구에 의하여 성년후견개시의 심판을 한다.","ox":"O","m":"②","c":"A","tp":"자연인의 능력"},{"y":2017,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2017_23-02-3","t":"가정법원은 한정후견인의 청구에 의하여도 피한정후견인이 한정후견인의 동의를 받아야만 할 수 있는 행위의 범위를 변경할 수 있다.","ox":"O","m":"③","c":"A","tp":"자연인의 능력"},{"y":2017,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2017_23-02-4","t":"특정후견은 본인의 의사에 반하여 할 수 없다.","ox":"O","m":"④","c":"A","tp":"자연인의 능력"},{"y":2017,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2017_23-02-5","t":"가정법원이 피한정후견인 또는 피특정후견인에 대하여 성년후견개시의 심판을 한 때에는 종전의 한정후견 또는 특정후견은 별도의 심판 없이 종료한다.","ox":"X","m":"⑤","c":"A","tp":"자연인의 능력"},{"y":2017,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2017_23-03-1","t":"재단법인의 설립을 위하여 서면으로 재산을 출연한 경우에도 출연자는 착오를 이유로 출연의 의사표시를 취소할 수 있다.","ox":"O","m":"①","c":"A","tp":"민법상 법인"},{"y":2017,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2017_23-03-2","t":"유언으로 부동산을 출연하여 재단법인을 설립하는 경우, 재단법인이 그 부동산에 관한 소유권이전등기를 마치지 아니하였다면 유언자의 상속인으로부터 부동산을 취득하여 이전등기를 마친 선의의 제3자에게 대항할 수 없다.","ox":"O","m":"②","c":"A","tp":"민법상 법인"},{"y":2017,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2017_23-03-3","t":"갑회사가 을회사의 채권자에 대하여 을회사와는 별개의 법인격을 가지는 회사라는 주장을 하는 것이 신의성실의 원칙에 반하거나 법인격을 남용하는 것으로 인정되는 경우에도 을회사에 대한 판결의 기판력 및 집행력의 범위를 갑회사에까지 확장하는 것은 허용되지 아니한다.","ox":"O","m":"③","c":"A","tp":"민법상 법인"},{"y":2017,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2017_23-03-4","t":"법인의 정관에 법인 대표권의 제한에 관한 규정이 있으나 그와 같은 취지가 등기되어 있지 않다면 법인은 그와 같은 정관의 규정에 대하여 선의냐 악의냐에 관계없이 제3자에 대하여 대항할 수 없다.","ox":"O","m":"④","c":"A","tp":"민법상 법인"},{"y":2017,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2017_23-03-5","t":"법인 대표자의 행위가 직무에 관한 행위에 해당하지 아니함을 피해자 자신이 알았거나 과실로 인하여 알지 못한 경우에는 법인에게 손해배상책임을 물을 수 없다.","ox":"X","m":"⑤","c":"A","tp":"민법상 법인"},{"y":2017,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2017_23-08-1","t":"소집절차에 하자가 있어 그 효력을 인정할 수 없는 종중총회의 결의는 나중에 적법하게 소집된 종중총회에서 추인이 이루어지더라도 유효로 볼 수 없다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2017_23-08-2","t":"종중총회를 개최함에 있어서 종중원들에 대한 소집통지의 방법은 반드시 직접 서면으로 하여야만 하는 것은 아니고 구두 또는 전화로 하여도 되고 다른 종중원이나 세대주를 통하여 하여도 무방하다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2017_23-08-3","t":"공동선조의 후손 중 남성만으로 그 구성원을 한정하여 종중 유사단체를 설립하더라도 특별한 사정이 없는 한 양성평등 원칙을 정한 헌법 제11조 및 민법 제103조를 위반하여 무효라고 볼 수 없다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2017_23-08-4","t":"비법인사단이 총유물에 관한 매매계약을 체결하는 행위는 총유물의 처분행위에 해당하나 그 매매계약에 의하여 부담하고 있는 채무에 대한 소멸시효 중단사유로서의 승인은 총유물의 관리ㆍ처분행위로 볼 수 없다.","ox":"O","m":"④","c":"A","tp":"종중"},{"y":2017,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2017_23-08-5","t":"종중의 토지에 관하여 지급된 수용보상금은 종중원의 총유로서 종중의 정관이나 규약에 달리 정함이 없는 한 종중총회의 결의에 의해 처분할 수 있고, 이러한 결의는 비영리사단으로서의 종중의 성격에 위배되는 것도 아니다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2017_23-09-1","t":"부동산입찰절차에서 동일한 물건에 관하여 1인이 이해관계를 달리하는 2인 이상의 대리인이 된 경우, 그 대리인이 한 입찰행위는 원칙적으로 무효이다.","ox":"O","m":"①","c":"A","tp":"법률행위의 대리"},{"y":2017,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2017_23-09-2","t":"무권대리행위의 추인은 무권대리인, 무권대리행위의 직접 상대방 및 그 무권대리행위로 인한 권리 또는 법률관계의 승계인에 대하여도 할 수 있다.","ox":"O","m":"②","c":"A","tp":"법률행위의 대리"},{"y":2017,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2017_23-09-3","t":"부부간의 일상가사대리권은 그 동거생활을 유지하기 위하여 각각 필요한 범위 내의 법률행위에 국한되어야 할 것이고, 아내가 남편 소유의 부동산을 매각하는 것과 같은 처분행위는 일상가사의 대리권에는 속하지 아니한다.","ox":"O","m":"③","c":"A","tp":"법률행위의 대리"},{"y":2017,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2017_23-09-4","t":"민법 제135조 제1항에 따른 무권대리인의 책임은 무과실책임으로서 대리권의 흠결에 관하여 대리인에게 과실 등의 귀책사유가 있어야만 인정되는 것이 아니고, 무권대리행위가 제3자의 기망이나 문서위조 등 위법행위로 야기되었다고 하더라도 책임이 부정되지 않는다.","ox":"O","m":"④","c":"A","tp":"법률행위의 대리"},{"y":2017,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2017_23-09-5","t":"甲이 그 소유 부동산을 乙에게 매도하였는데, 丙의 대리인 丁이 그 사실을 알면서도 甲의 배임행위에 적극 가담하여 이중으로 매수한 경우, 丙이 자신이 선의임을 증명하지 않는 한 甲과 丙의 매매계약은 원칙적으로 사회질서에 반하여 무효이다.","ox":"X","m":"⑤","c":"A","tp":"법률행위의 대리"},{"y":2018,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2018_24-03-1","t":"가정법원은 질병, 장애, 노령, 그 밖의 사유로 인한 정신적 제약으로 사무를 처리할 능력이 지속적으로 결여된 사람에 대하여 일정한 자의 청구에 의하여 성년후견개시의 심판을 한다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2018_24-03-2","t":"성년후견개시심판이 있는 경우라도 반드시 성년후견인을 두어야 하는 것은 아니며, 피성년후견인의 신상과 재산에 관한 모든 사정을 고려하여 성년후견인을 두지 않을 수 있다. 또한 성년후견인은 미성년후견과 마찬가지로 여러 명을 둘 수 있고, 법인도 성년후견인이 될 수 있다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2018_24-03-3","t":"가정법원은 질병, 장애, 노령, 그 밖의 사유로 인한 정신적 제약으로 사무를 처리할 능력이 부족한 사람에 대하여 일정한 자의 청구에 의하여 한정후견개시의 심판을 한다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2018_24-03-4","t":"미성년자에 대하여 친권자가 없거나 친권자가 법률행위의 대리권 및 재산관리권을 행사할 수 없는 때에는 그 후견인을 두어야 한다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2018_24-03-5","t":"미성년후견인이 미성년자와의 사이에 이해가 상반되는 행위를 함에는 미성년후견인은 가정법원에 특별대리인의 선임을 청구하여야 한다. 다만, 후견감독인이 있는 경우에는 그러하지 아니하다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2018_24-09-1","t":"부동산의 소유자로부터 매매계약을 체결할 대리권을 수여받은 대리인은 특별한 사정이 없는 한 그 매매계약에서 약정한 바에 따라 중도금이나 잔금을 수령할 권한도 있다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2018_24-09-2","t":"어떠한 계약의 체결에 관한 대리권을 수여받은 대리인은 자신이 대리하여 체결하였던 계약의 해제 등 일체의 처분권과 상대방의 의사를 수령할 권한도 있다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2018_24-09-3","t":"대리권을 수여하는 수권행위는 묵시적인 의사표시에 의하여 할 수도 있으며, 어떤 사람이 대리인의 외양을 가지고 행위하는 것을 본인이 알면서도 이의를 하지 아니하고 방임하는 등 사실상의 용태에 의하여 대리권의 수여가 추단될 수도 있다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2018_24-09-4","t":"사술을 써서 대리행위의 표시를 하지 아니하고 단지 본인의 성명을 모용하여 자기가 마치 본인인 것처럼 기망하여 본인 명의로 직접 법률행위를 한 경우에는 특별한 사정이 없는 한 민법 제126조의 표현대리는 성립될 수 없다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2018_24-09-5","t":"무권대리행위의 추인은 묵시적인 방법으로도 할 수 있으며, 본인이 무권대리행위로 처하게 된 법적 지위를 충분히 이해하고 진의에 기하여 무권대리행위의 결과가 자기에게 귀속된다는 것을 승인한 것으로 볼 만한 사정이 있다면 무권대리행위를 묵시적으로 추인한 것으로 볼 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2018_24-14-1","t":"甲이 乙의 임차보증금반환채권을 담보하기 위하여 통정허위표시로 乙에게 전세권설정등기를 마친 후 丙이 이러한 사정을 알면서도 乙에 대한 채권을 담보하기 위하여 위 전세권에 대하여 전세권근저당권설정등기를 마쳤는데, 그 후 丁이 丙의 전세권근저당권부 채권을 가압류하였다가 이를 본압류로 이전하는 압류명령을 받은 경우, 丁이 통정허위표시에 관하여 선의라면 비록 丙이 악의라 하더라도 허위표시자는 그에 대하여 전세권이 통정허위표시에 의한 것이라는 이유로 대항할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2018_24-14-2","t":"통정허위표시에 해당하여 무효인 계약에 기해 발생한 채권을 가압류한 자도 민법 제108조 제2항의 ‘제3자’에 해당한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2018_24-14-3","t":"상법 제644조에 의하면, 보험계약 당시에 보험사고가 발생할 수 없는 것인 때에는 보험계약의 당사자 쌍방과 피보험자가 이를 알지 못한 경우가 아닌 한 그 보험계약은 무효이다. 따라서 보증보험계약의 주계약이 통정허위표시로서 무효인 때에는 보험사고가 발생할 수 없는 경우에 해당하므로 그 보증보험계약은 무효이나, 보증보험계약의 보험자는 주계약이 통정허위표시인 사정을 알지 못한 제3자에 대해서는 보증보험계약의 무효를 주장할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2018_24-14-4","t":"민법 제108조 제2항에 규정된 ‘제3자’는 특별한 사정이 없는 한 선의로 추정된다.","ox":"O","m":"④","c":"A","tp":"통정허위표시"},{"y":2018,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2018_24-14-5","t":"어음 발행행위에도 통정허위표시에 관한 민법 제108조가 적용될 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2018_24-24-1","t":"민법 제27조 제2항은 “전지에 임한 자, 침몰한 선박 중에 있던 자, 추락한 항공기 중에 있던 자 기타 사망의 원인이 될 위난을 당한 자”의 실종선고에 관해 규정하고 있다. 잠수장비를 착용하고 바다에 들어가서 해산물을 채취하다가 행방불명되었다고 하더라도 특별한 사정이 없는 한 이를 “사망의 원인이 될 위난”이라고 할 수 없다.","ox":"O","m":"①","c":"A","tp":"부재와 실종"},{"y":2018,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2018_24-24-2","t":"실종선고가 취소되지 않는 한 반증을 들어 실종선고의 효과를 다툴 수는 없다.","ox":"O","m":"②","c":"A","tp":"부재와 실종"},{"y":2018,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2018_24-24-3","t":"실종선고로 인하여 실종기간 만료시를 기준으로 하여 상속이 개시된 이상 설사 이후 실종선고가 취소되어야 할 사유가 생겼다고 하더라도 실제로 실종선고가 취소되지 아니하는 한, 임의로 실종기간이 만료하여 사망한 때로 간주되는 시점과는 달리 사망시점을 정하여 이미 개시된 상속을 부정하고 이와 다른 상속관계를 인정할 수는 없다.","ox":"O","m":"③","c":"A","tp":"부재와 실종"},{"y":2018,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2018_24-24-4","t":"실종선고 확정 전에는 실종기간이 만료된 실종자를 상대로 하여 제기된 소도 적법하고, 실종자를 당사자로 하여 선고된 판결도 유효하다. 그러나 실종자를 당사자로 한 판결이 확정된 후에 실종선고가 확정되어 그 사망간주의 시점이 소제기 전으로 소급하는 경우에는 위 확정판결은 사망한 사람을 상대로 한 판결로서 무효가 된다.","ox":"X","m":"④","c":"A","tp":"부재와 실종"},{"y":2018,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2018_24-24-5","t":"사망한 것으로 간주된 자가 그 이전에 생사불명의 부재자로서 그 재산관리에 관하여 법원으로부터 재산관리인이 선임되어 있었다면 재산관리인은 그 부재자의 사망을 확인했다고 하더라도 선임결정이 취소되지 아니하는 한 계속하여 권한을 행사할 수 있다. 그러므로 재산관리인에 대한 선임결정이 취소되기 전에 재산관리인의 처분행위에 기하여 마쳐진 등기는 법원의 처분허가 등 모든 절차를 거쳐 적법하게 마쳐진 것으로 추정된다.","ox":"O","m":"⑤","c":"A","tp":"부재와 실종"},{"y":2018,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2018_24-31","t":"대리에 관한 다음 설명 중 가장 옳은 것은?","c":"A","mc":{"s":"대리에 관한 다음 설명 중 가장 옳은 것은?","d":"","o":["무권대리행위 추인은 명시적인 방법만이 아니라 묵시적인 방법으로도 할 수 있고, 무권대리행위의 직접의 상대방은 물론 무권대리행위로 인한 권리 또는 법률관계의 승계인에 대하여도 할 수 있지만, 무권대리인에 대하여 한 무권대리행위 추인은 아무런 효력이 없다.","무권리자가 타인의 권리를 처분한 경우에는 특별한 사정이 없는 한 권리가 이전되지 않고, 무권리자의 처분이 계약으로 이루어진 경우에 권리자가 이를 추인하더라도 그 계약의 효과가 계약을 체결했을 때에 소급하여 권리자에게 귀속되는 것은 아니다.","비법인사단인 교회의 대표자는 총유물인 교회 재산 처분에 관하여 교인총회 결의를 거치지 아니하고는 이를 대표하여 행할 권한이 없다. 하지만 그 상대방이 교인총회 결의를 거쳤다고 믿었고 그와 같이 믿은 데에 정당한 사유가 있는 때에는 민법 제126조의 표현대리 규정에 따라 본인인 교회에 처분행위의 효력이 미친다.","민법 제126조의 권한을 넘는 표현대리 규정은 법정대리에도 적용되므로, 한정치산자의 후견인이 친족회의 동의를 얻지 않고 피후견인의 부동산을 처분하는 행위를 한 경우에도 상대방이 친족회의 동의가 있다고 믿은 데에 정당한 사유가 있는 때에는 본인인 한정치산자에게 그 효력이 미친다.","표현대리가 성립하는 경우라도, 과실상계의 법리를 유추적용하여 본인의 책임을 경감할 수 있다. 23-19"],"a":4}},{"y":2018,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2018_24-39","t":"법인 아닌 사단에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"법인 아닌 사단에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["종중 또는 문중과 같이 특별한 조직행위 없이도 자연적으로 성립하는 예외적인 사단이 아닌 한, 법인 아닌 사단이 성립하려면 사단으로서의 실체를 갖추는 조직행위가 있어야 한다.","민법상의 조합과 법인격은 없으나 사단성이 인정되는 비법인사단을 구별함에 있어서는 일반적으로 그 단체성의 강약을 기준으로 판단하여야 한다.","법인 아닌 사단인 종중의 대표자 또는 그 구성원의 일부는 종중의 재산에 대한 보존행위로서 소송을 하는 경우에 종중 총회의 결의를 거칠 필요 없이 단독으로 할 수 있다.","종중재산을 분배함에 있어 단순히 남녀 성별의 구분에 따라 그 분배 비율, 방법, 내용에 차이를 두는 것은 개인의 존엄과 양성의 평등을 기초로 한 가족생활을 보장하고, 남녀평등을 실현할 것을 요구하는 우리의 전체 법질서에 부합하지 아니한 것으로 정당성과 합리성이 없어 무효라고 할 것이다.","비법인사단이 타인 간의 금전채무를 보증하는 행위는 총유물 그 자체의 관리․처분이 따르지 아니하는 단순한 채무부담행위에 불과하여 이를 총유물의 관리․처분행위라고 볼 수는 없다. 23-21"],"a":3}},{"y":2019,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2019_25-03-1","t":"부재자의 생사가 5년간 분명하지 아니한 때에는 법원은 이해관계인이나 검사의 청구에 의하여 실종선고를 하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2019_25-03-2","t":"부재자의 자매로서 제2순위 상속인에 불과한 자는 부재자에 대한 실종선고의 여부에 따라 상속지분에 차이가 생긴다고 하더라도 부재자에 대하여 실종선고를 청구할 이해관계인이 될 수 없다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2019_25-03-3","t":"잠수장비를 착용한 채 바다에 입수하였다가 부상하지 아니한 채 행방불명되었다 하더라도, 이는 민법 제27조 제2항의 ‘사망의 원인이 될 위난’이라고 할 수 없다.","ox":"O","m":"③","c":"A","tp":"실종선고"},{"y":2019,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2019_25-03-4","t":"실종선고로 인하여 실종기간 만료시를 기준으로 하여 상속이 개시된 이상 설사 이후 실종선고가 취소되어야 할 사유가 생겼다고 하더라도 실제로 실종선고가 취소되지 아니하는 한, 임의로 실종기간이 만료하여 사망한 때로 간주되는 시점과는 달리 사망 시점을 정하여 이미 개시된 상속을 부정하고 다른 상속관계를 인정할 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2019_25-03-5","t":"부재자의 재산관리인이 부재자의 대리인으로서 소를 제기하여 그 소송 계속 중에 부재자에 대한 실종선고가 확정되어 그 소제기 이전에 부재자가 사망한 것으로 간주되는 경우에는 위 소제기 자체가 소급하여 당사자능력이 없는 사망한 자가 제기한 것으로 된다.","ox":"X","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2019_25-08","t":"종중에 관한 다음 설명 중 가장 옳은 것은?","c":"A","mc":{"s":"종중에 관한 다음 설명 중 가장 옳은 것은?","d":"","o":["종중의 대표자 또는 그 구성원의 일부는 종중의 재산에 대한 보존행위로서 소송을 하는 경우에 종중 총회의 결의를 거칠 필요 없이 단독으로 할 수 있다.","공동선조의 후손 중 특정지역 거주자나 지파 소속 종중원만으로 조직체를 구성하여 활동하고 있다면, 이는 본래의 의미의 종중으로 볼 수 없고, 종중 유사의 권리능력 없는 사단도 될 수 없다.","종중재산을 분배함에 있어 단순히 남녀 성별의 구별에 따라 그 분배 비율, 방법, 내용에 차이를 두는 것은 정당성과 합리성이 없어 무효이다.","소집절차에 하자가 있어 그 효력을 인정할 수 없는 종중총회의 결의는 나중에 적법하게 소집된 종중총회에서 추인이 이루어지더라도 유효로 볼 수 없다.","종중원들이 종중 재산의 관리 또는 처분 등을 위하여 종중의 규약에 따른 적법한 소집권자 또는 일반 관례에 따른 종중총회의 소집권자인 종중의 연고항존자에게 필요한 종중의 임시총회 소집을 요구하였음에도 그 소집권자가 정당한 이유 없이 이에 응하지 아니하는 경우에는 반드시 민법 제70조를 준용하여 감사가 총회를 소집하거나 종원이 법원의 허가를 얻어 총회를 소집하여야 한다. 22-13"],"a":3}},{"y":2019,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2019_25-11-1","t":"가정법원은 성년후견개시 심판을 하면서 피성년후견인의 행위 중 취소할 수 없는 법률행위의 범위를 정할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2019_25-11-2","t":"한정후견인의 동의가 필요한 행위에 대하여 피한정후견인의 이익이 침해될 염려가 있음에도 한정후견인이 동의를 하지 아니하는 때에는 가정법원은 피한정후견인의 청구에 의하여 한정후견인의 동의를 갈음하는 허가를 할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2019_25-11-3","t":"후견계약은 공정증서로 체결하여야 하는 요식행위이며, 후견계약이 체결되어 등기된 때에는 가정법원은 본인의 이익을 위한 경우라도 성년후견 또는 한정후견의 심판을 할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2019_25-11-4","t":"성년후견인의 감독을 위하여 가정법원은 필요하다고 인정하는 경우 직권으로 성년후견감독인을 선임할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2019_25-11-5","t":"남편이나 아내가 피성년후견인인 경우에는 그의 성년후견인이 성년후견감독인의 동의를 받아 친생부인의 소를 제기할 수 있고, 성년후견감독인이 없거나 동의할 수 없을 때에는 가정법원에 그 동의를 갈음하는 허가를 청구할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2019_25-14","t":"다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"다음 설명 중 가장 옳지 않은 것은?","d":"","o":["무능력자의 책임을 제한하는 민법 제141조 단서는 부당이득에 있어 수익자의 반환범위를 정한 민법 제748조의 특칙으로서 무능력자의 보호를 위해 그 선의ㆍ악의를 불문하고 반환범위를 현존 이익에 한정시키려는 데 그 취지가 있으므로, 의사능력의 흠결을 이유로 법률행위가 무효가 되는 경우에도 유추적용되어야 한다.","미성년자가 신용카드발행인과 사이에 신용카드 이용계약을 체결하여 신용카드거래를 하다가 신용카드 이용계약을 취소하는 경우 미성년자는 그 행위로 인하여 받은 이익이 현존하는 한도에서 상환할 책임이 있는바, 신용카드 이용계약이 취소됨에도 불구하고 신용카드회원과 해당 가맹점 사이에 체결된 개별적인 매매계약은 특별한 사정이 없는 한 신용카드 이용계약취소와 무관하게 유효하게 존속한다 할 것이고, 신용카드발행인의 가맹점에 대한 신용카드이용대금의 지급으로써 신용카드회원은 자신의 가맹점에 대한 매매대금 지급채무를 법률상 원인 없이 면제받는 이익을 얻었으며, 이러한 이익은 금전상의 이득으로서 특별한 사정이 없는 한 현존하는 것으로 추정된다.","적모와 미성년자인 수인의 자 사이에 상속재산분할협의를 하게 되는 경우에는 미성년자가 각자마다 특별대리인을 선임하여 그 각 특별대리인이 각 미성년자를 대리하여 상속재산분할의 협의를 하여야 하고, 만약 특별대리인 1인이 수인의 미성년자를 대리하여 상속재산분할협의를 하였다면 이는 민법 제921조에 위반된 것으로서 이러한 대리행위에 의하여 성립된 상속재산분할협의는 원칙적으로 무효이고, 이는 개별적으로 사후 추인을 한 피대리자 1인에 대해서도 마찬가지이다.","미성년자는 다양한 인격발현의 잠재력을 지니고 있으므로, 그러한 잠재력을 최대한 끌어낼 수 있도록 일정한 요건 하에 복수의 미성년후견인이 허용되고 있다.","증여는 증여자와 수증자 간의 계약으로서 수증자의 승낙을 요건으로 하는 것이므로 태아에 대한 증여에 있어서도 태아의 수증행위가 필요한 것인바, 민법상 개별적으로 태아의 권리능력이 인정되는 경우에도 그 권리능력은 태아인 동안에는 없고 살아서 출생하면 문제된 사건의 시기까지 소급하여 그 때에 출생한 것과 같이 법률상 간주될 뿐이므로, 태아인 동안에는 법정대리인이 있을 수 없고, 따라서 법정대리인에 의한 수증행위도 불가능하다. 22-15"],"a":4}},{"y":2019,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2019_25-15-1","t":"비법인사단인 주택조합의 대표자가 조합총회의 결의를 거쳐야 하는 조합원 총유에 속하는 재산에 관하여 조합원 총회의 결의를 거치지 아니하고 처분한 경우 처분행위는 원칙적으로 무효이나, 다만 이 경우에도 민법 제126조(권한을 넘은 표현대리)가 준용될 수 있으므로 처분행위의 상대방인 제3자가 대표자에게 그 권한이 있다고 믿을 만한 정당한 이유가 있었음을 입증한 경우에는 주택조합에 대하여 그 처분행위가 유효라고 대항할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2019_25-15-2","t":"비법인사단이 타인 간의 금전채무를 보증하는 행위는 총유물 그 자체의 관리ㆍ처분이 따르지 아니하는 단순한 채무부담행위에 불과하므로 이를 총유물의 관리ㆍ처분행위라고 볼 수는 없다. 따라서 비법인사단인 재건축조합의 조합장이 채무보증계약을 체결하면서 조합규약에서 정한 조합 임원회의의 결의를 거치지 아니하였다거나 조합원총회의 결의를 거치지 않았다 하더라도 바로 그 보증계약이 무효라고 할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2019_25-15-3","t":"법인의 정관에 법인 대표권의 제한에 관한 규정이 있으나 그와 같은 취지가 등기되어 있지 않다면 법인은 그와 같은 정관의 규정에 대하여 선의냐 악의냐에 관계없이 제3자에 대하여 대항할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2019_25-15-4","t":"대표이사가 대표권의 범위 내에서 한 행위는 설사 회사의 영리목적과 관계없이 자기 또는 제3자의 이익을 도모할 목적으로 그 권한을 남용한 것이라 할지라도 일단 회사의 행위로서 유효하고, 다만 그 행위의 상대방이 대표이사의 진의를 알았거나 알 수 있었을 때에는 회사에 대하여 무효가 되는 것이며, 이는 민법상 법인의 대표자가 대표권한을 남용한 경우에도 마찬가지이다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2019_25-15-5","t":"민법상 법인과 그 기관인 이사와의 관계는 위임자와 수임자의 법률관계와 같아서 이사가 사임하면 일단 위임관계는 종료됨이 원칙이나 후임 이사의 선임시까지 이사가 존재하지 않는다면 법인으로서는 정상적인 활동을 중단하여야 할 상황에 놓이게 되므로, 사임한 이사라도 임무를 수행함이 부적당하다고 인정할 만한 특별한 사정이 없는 한 후임 이사가 선임될 때까지 이사의 직무를 계속 수행할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2019_25-28-1","t":"착오를 이유로 의사표시를 취소하는 자는 법률행위의 내용에 착오가 있었다는 사실과 함께 착오가 의사표시에 결정적인 영향을 미쳤다는 점, 즉 만일 그 착오가 없었더라면 의사표시를 하지 않았을 것이라는 점을 증명하여야 한다.","ox":"O","m":"①","c":"A","tp":"착오로 인한 의사표시"},{"y":2019,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2019_25-28-2","t":"매매계약 당시 장차 도시계획이 변경되어 공동주택, 호텔 등의 신축에 대한 인ㆍ허가를 받을 수 있을 것으로 생각하였으나 그 후 생각대로 되지 않은 경우, 이는 법률행위 당시를 기준으로 장래의 미필적 사실의 발생에 대한 기대나 예상이 빗나간 것에 불과할 뿐 착오라고 할 수 없다.","ox":"O","m":"②","c":"A","tp":"착오로 인한 의사표시"},{"y":2019,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2019_25-28-3","t":"매도인이 매수인의 중도금 지급채무 불이행을 이유로 매매계약을 적법하게 해제하였다면, 매수인으로서는 착오를 이유로 한 취소권을 행사하여 매매계약 전체를 무효로 돌릴 수 없다.","ox":"X","m":"③","c":"A","tp":"착오로 인한 의사표시"},{"y":2019,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2019_25-28-4","t":"고려청자로 알고 매수한 도자기가 진품이 아닌 것으로 밝혀진 경우, 개인 소장자인 매수인이 그 출처의 조회나 전문적 감정인의 감정 없이 매수한 점만으로는 중과실이 인정되지 않으므로 착오를 이유로 매매계약을 취소할 수 있다.","ox":"O","m":"④","c":"A","tp":"착오로 인한 의사표시"},{"y":2019,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2019_25-28-5","t":"주채무자의 차용금반환채무를 보증할 의사로 공정증서에 연대보증인으로 서명날인하였으나 그 공정증서가 주채무자의 기존의 구상금채무 등에 관한 준소비대차계약의 공정증서였다 하더라도, 연대보증인의 위와 같은 착오는 연대보증계약의 중요 부분의 착오가 아니다.","ox":"O","m":"⑤","c":"A","tp":"착오로 인한 의사표시"},{"y":2019,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2019_25-32-1","t":"타인의 대리인으로 계약을 한 자가 그 대리권을 증명하지 못하고 또 본인의 추인을 얻지 못한 때에 상대방이 가지는 무권대리인에 대한 계약이행 또는 손해배상청구권의 소멸시효는, 무권대리인이 대리권을 증명하지 못하거나 본인의 추인을 얻지 못함을 그 상대방이 안 때부터 진행한다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2019_25-32-2","t":"甲이 대리권 없이 乙소유 X부동산을 丙에게 매도하여 소유권이전등기를 마쳐준 이후, 甲이 乙로부터 X부동산을 상속받아 그 소유자가 되어 자신의 매매행위가 무권대리행위여서 무효였다는 이유로 丙 앞으로 마쳐진 소유권이전등기의 말소를 구하더라도, 이를 두고 신의칙에 반한다고 할 수 없다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2019_25-32-3","t":"甲이 乙명의의 주식에 관하여 처분권한 없이 A은행과 담보설정계약을 체결한 이후 甲의 사망으로 인하여 乙이 甲을 상속한 경우, 乙이 위 담보설정계약에 따른 의무의 이행을 거절하더라도, 특별한 사정이 없는 한 신의칙에 반한다고 할 수 없다.","ox":"O","m":"③","c":"A","tp":"무권대리"},{"y":2019,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2019_25-32-4","t":"민법 제132조는 무권대리행위 추인의 상대방으로 무권대리행위의 상대방만을 규정하고 있으므로, 무권대리행위의 추인은 반드시 무권대리행위의 직접의 상대방에게 하여야 하고, 무권대리인에게 한 경우에는 그 상대방에게 대항하지 못한다.","ox":"X","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2019_25-32-5","t":"甲이 대리권 없이 乙소유 X부동산에 관하여 丙과 근저당권설정계약을 체결하였고, 乙로부터 추인을 얻지도 못하였다고 하더라도, 甲이 자신의 대리권 흠결에 대하여 아무런 귀책사유가 없다면 甲은 丙에 대하여 민법 제135조 제1항이 정한 무권대리인의 책임을 지지 않는다.","ox":"X","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2020_26-04-1","t":"총유물인 종중 토지 매각대금의 분배는 정관 기타 규약에 달리 정함이 없는 한 종중총회의 분배결의가 없으면 종원이 종중에 대하여 직접 분배청구를 할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2020_26-04-2","t":"종중총회를 개최함에 있어 종중원들에 대한 소집통지의 방법은 반드시 직접 서면으로 하여야만 하는 것은 아니고 구두 또는 전화로 하여도 되고 다른 종중원이나 세대주를 통하여 하여도 무방하다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2020_26-04-3","t":"종중 유사의 권리능력 없는 사단은 반드시 총회를 열어 성문화된 규약을 만들고 정식의 조직체계를 갖추어야만 비로소 단체로서 성립한다.","ox":"X","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2020_26-04-4","t":"고유의 의미의 종중의 경우에 종중이 종중원의 자격을 박탈한다든지 종중원이 종중을 탈퇴할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2020_26-04-5","t":"공동선조의 후손들 중 특정 지역 거주자나 특정 범위 내의 자들만으로 구성된 종중은 있을 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2020_26-10-1","t":"과반수의 이사가 민법 제58조 제2항에 근거하여 이사회를 소집하는 경우 법원의 허가를 받을 필요 없이 이사회를 소집할 수 있다.","ox":"O","m":"①","c":"A","tp":"민법상 법인"},{"y":2020,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2020_26-10-2","t":"법원의 직무집행정지 가처분결정에 의해 회사를 대표할 권한이 정지된 대표이사가 그 정지기간 중에 체결한 계약은 절대적으로 무효이고, 그 후 가처분신청의 취하에 의하여 보전집행이 취소되었다 하더라도 집행의 효력은 장래를 향하여 소멸할 뿐이다.","ox":"O","m":"②","c":"A","tp":"민법상 법인"},{"y":2020,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2020_26-10-3","t":"민법상 재단법인의 기본재산에 관한 저당권 설정행위는 기본재산의 처분행위에 속하므로, 이에 관하여는 주무관청의 허가를 얻어야 한다.","ox":"X","m":"③","c":"A","tp":"민법상 법인"},{"y":2020,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2020_26-10-4","t":"이사가 수인인 민법상 법인의 정관에 대표권 있는 이사만 이사회를 소집할 수 있고 다른 이사가 요건을 갖추어 이사회 소집을 요구하면 대표권 있는 이사가 이에 응하도록 규정하고 있는데도 대표권 있는 이사가 다른 이사의 정당한 이사회 소집을 거절한 경우 이사는 정관의 이사회 소집권한에 관한 규정 또는 민법에 기초하여 법인의 사무를 집행할 권한에 의하여 이사회를 소집할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2020_26-10-5","t":"사단법인의 사원의 지위는 양도 또는 상속할 수 없다고 규정한 민법 제56조는 강행규정은 아니라고 할 것이므로, 정관에 의하여 이를 인정하고 있을 때에는 양도·상속이 허용된다.","ox":"O","m":"⑤","c":"A","tp":"민법상 법인"},{"y":2020,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2020_26-14-1","t":"동기의 착오가 법률행위의 내용의 중요부분의 착오에 해당함을 이유로 표의자가 법률행위를 취소하려면 그 동기를 당해 의사표시의 내용으로 삼을 것을 상대방에게 표시하고 의사표시의 해석상 법률행위의 내용으로 되어 있다고 인정되면 충분하고 당사자들 사이에 별도로 그 동기를 의사표시의 내용으로 삼기로 하는 합의까지 이루어질 필요는 없지만, 그 법률행위의 내용의 착오는 보통 일반인이 표의자의 입장에 섰더라면 그와 같은 의사표시를 하지 아니하였으리라고 여겨질 정도로 그 착오가 중요한 부분에 관한 것이어야 한다.","ox":"O","m":"①","c":"A","tp":"착오에 의한 의사표시"},{"y":2020,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2020_26-14-2","t":"민법 제109조 제1항 단서는 의사표시의 착오가 표의자의 중대한 과실로 인한 때에는 그 의사표시를 취소하지 못한다고 규정하고 있으므로 상대방이 표의자의 착오를 알고 이를 이용한 경우에도 착오가 표의자의 중대한 과실로 인한 것이라면 표의자는 의사표시를 취소할 수 없다.","ox":"X","m":"②","c":"A","tp":"착오에 의한 의사표시"},{"y":2020,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2020_26-14-3","t":"원고 소송대리인으로부터 소송대리인 사임신고서 제출을 지시받은 사무원은 원고 소송대리인의 표시기관에 해당되어 그의 착오는 원고 소송대리인의 착오라고 보아야 하므로, 사무원의 착오로 원고 소송대리인의 의사에 반하여 소를 취하하였다고 하여도 이를 무효라고 볼 수는 없다.","ox":"O","m":"③","c":"A","tp":"착오에 의한 의사표시"},{"y":2020,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2020_26-14-4","t":"부동산 매매에 있어서 시가에 관한 착오는 부동산을 매매하려는 의사를 결정함에 있어 동기의 착오에 불과할 뿐 법률행위의 중요부분에 관한 착오라고 할 수 없다.","ox":"O","m":"④","c":"A","tp":"착오에 의한 의사표시"},{"y":2020,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2020_26-14-5","t":"민법상 화해계약에 있어서 당사자는 착오를 이유로 취소하지 못하고 다만 화해 당사자의 자격 또는 화해의 목적인 분쟁 이외의 사항에 착오가 있는 때에 한하여 취소할 수 있는바, 여기서 화해의 목적인 분쟁 이외의 사항이라 함은 분쟁의 대상이 아니라 분쟁의 전제 또는 기초가 된 사항으로서, 쌍방 당사자가 예정한 것이어서 상호 양보의 내용으로 되지 않고 다툼이 없는 사실로 양해된 사항을 말한다.","ox":"O","m":"⑤","c":"A","tp":"착오에 의한 의사표시"},{"y":2020,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2020_26-25-1","t":"임차권의 양도에 있어서 양도인은 그 임차권의 존속기간, 임대기간 종료 후의 재계약 여부, 임대인의 동의 여부와 이에 관계되는 모든 사정을 양수인에게 알려주어야 할 신의칙상의 의무가 있다.","ox":"O","m":"①","c":"A","tp":"신의칙과 그 파생원칙"},{"y":2020,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2020_26-25-2","t":"회사의 임원이나 직원의 지위에 있었기 때문에 부득이 회사와 제3자 사이의 계속적 거래에서 발생하는 회사의 채무를 연대보증한 사람이 그 후 회사에서 퇴직하여 임직원의 지위에서 떠난 때에는 연대보증인은 특별한 사정이 없는 한 연대보증계약을 일방적으로 해지할 수 있다.","ox":"O","m":"②","c":"A","tp":"신의칙과 그 파생원칙"},{"y":2020,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2020_26-25-3","t":"계속적 계약에서 계약의 체결 시와 이행 시 사이에 간극이 크고, 경제적 상황의 변화로 당사자에게 불이익이 발생했다는 사실만 인정되면 사정변경을 이유로 계약을 해지할 수 있다.","ox":"X","m":"③","c":"A","tp":"신의칙과 그 파생원칙"},{"y":2020,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2020_26-25-4","t":"공매절차에서 점유자의 유치권 신고 사실을 알고 부동산을 매수한 자가 그 점유를 침탈하여 유치권을 소멸시키고 나아가 고의적인 점유이전으로 유치권자의 확정판결에 기한 점유회복조차 곤란하게 하였음에도 유치권자가 현재까지 점유회복을 하지 못한 사실을 내세워 유치권자를 상대로 적극적으로 유치권부존재확인을 구하는 것은 명백히 정의 관념에 반하여 사회생활상 도저히 용인될 수 없는 것으로 권리남용에 해당하여 허용되지 않는다.","ox":"O","m":"④","c":"A","tp":"신의칙과 그 파생원칙"},{"y":2020,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2020_26-25-5","t":"실권 또는 실효의 법리는 법의 일반원리인 신의성실의 원칙에 바탕을 둔 파생원칙인 것이므로 공법관계 가운데 관리관계는 물론이고 권력관계에도 적용되어야 함을 배제할 수는 없다.","ox":"O","m":"⑤","c":"A","tp":"신의칙과 그 파생원칙"},{"y":2021,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2021_27-06-1","t":"법인은 법률의 규정에 좇아 정관으로 정한 목적 범위 내에서 권리와 의무의 주체가 되는데, ‘목적 범위 내’의 행위라 함은 정관에 명시된 목적 자체에 국한되는 것이 아니라, 그 목적을 수행하기 위한 직접 또는 간접으로 필요한 행위를 모두 포함한다. 목적 수행에 필요한지 여부도 행위의 객관적 성질에 따라 추상적으로 판단해야 하므로, 행위자의 주관적·구체적 의사에 따라 판단하면 아니 되고, 문제된 행위가 정관상 목적에 현실적으로 필요한 것인지 여부에 따라 판단하여야 한다.","ox":"X","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2021_27-06-2","t":"법인은 이사 기타 대표자가 그 직무에 관하여 타인에게 가한 손해를 배상할 책임이 있는데, 법인의 목적 범위 외의 행위로 인하여 타인에게 손해를 가한 때에는 그 사항의 의결에 찬성하거나 그 의결을 집행한 사원, 이사 및 기타 대표자가 연대하여 배상하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2021_27-06-3","t":"민법 제35조 제1항에 의한 법인의 불법행위가 성립하는 경우, 사용자책임을 규정한 민법 제756조 제1항이 적용되지 않는다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2021_27-06-4","t":"민법 제35조 제1항의 ‘대표자’에는 그 명칭이나 직위 여하를 불문하고 당해 법인을 실질적으로 운영하면서 사실상 법인을 대표하여 법인의 사무를 집행하는 사람을 포함한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2021_27-06-5","t":"법인의 대표자의 행위가 직무에 관한 행위에 해당하지 아니함을 피해자 자신이 알았거나 또는 중대한 과실로 인하여 알지 못한 경우에는 법인에게 손해배상책임을 물을 수 없다고 할 것이고, 여기서 중대한 과실이라 함은 거래의 상대방이 조금만 주의를 기울였더라면 대표자의 행위가 그 직무권한 내에서 적법하게 행하여진 것이 아니라는 사정을 알 수 있었음에도 만연히 이를 직무권한 내의 행위라고 믿음으로써 일반인에게 요구되는 주의의무에 현저히 위반하는 것으로 거의 고의에 가까운 정도의 주의를 결여하고, 공평의 관점에서 상대방을 구태여 보호할 필요가 없다고 봄이 상당하다고 인정되는 상태를 말한다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2021_27-08-1","t":"채권양도의 통지와 같은 준법률행위의 도달은 의사표시와 마찬가지로 사회관념상 채무자가 통지의 내용을 알 수 있는 객관적 상태에 놓여졌을 때를 지칭하고, 그 통지를 채무자가 현실적으로 수령하였거나 그 통지의 내용을 알았을 것까지는 필요하지 않다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2021_27-08-2","t":"대리인이 본인을 위한 것임을 표시하지 아니한 때에는 그 의사표시는 본인에 대하여 효력이 생기지 않고, 원칙적으로 대리인 자기를 위한 것으로 보지도 않는다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2021_27-08-3","t":"의사표시의 상대방이 의사표시를 받은 때에 제한능력자인 경우에는 의사표시자는 그 의사표시로써 대항할 수 없다. 다만, 그 상대방의 법정대리인이 의사표시가 도달한 사실을 안 후에는 그러하지 아니하다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2021_27-08-4","t":"의사표시자가 그 통지를 발송한 후 사망하거나 제한능력자가 되어도 의사표시의 효력에 영향을 미치지 아니한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2021_27-08-5","t":"표의자가 과실없이 상대방을 알지 못하거나 상대방의 소재를 알지 못하는 경우에는 의사표시는 민사소송법 공시송달의 규정에 의하여 송달할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2021_27-12-1","t":"실제로는 전세권설정계약이 없으면서도 임대차계약에 기한 임차보증금반환채권을 담보할 목적 또는 금융기관으로부터 자금을 융통할 목적으로 임차인과 임대인 사이의 합의에 따라 임차인 명의로 전세권설정등기를 경료한 후 그 전세권에 대하여 근저당권이 설정된 경우, 가사 위 전세권설정계약만 놓고 보아 그것이 통정허위표시에 해당하여 무효라 하더라도 이로써 위 전세권설정계약에 의하여 형성된 법률관계를 토대로 별개의 법률원인에 의하여 새로운 법률상 이해관계를 갖게 된 근저당권자에 대하여는 그와 같은 사정을 알고 있었던 경우에만 그 무효를 주장할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2021_27-12-2","t":"대출절차상의 편의를 위하여 명의만을 대여한 것으로 인정되어 채무자로 볼 수 없는 경우라 하더라도, 실질적 주채무자에 대한 보증의 의사가 있는 것으로 볼 수 있다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2021_27-12-3","t":"통정한 허위표시에 의하여 외형상 형성된 법률관계로 생긴 채권을 가압류한 경우, 그 가압류권자는 허위표시에 기초하여 새로운 법률상 이해관계를 가지게 되므로 민법 제108조 제2항의 제3자에 해당한다고 봄이 상당하고, 또한 민법 제108조 제2항의 제3자는 선의이면 족하고 무과실은 요건이 아니다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2021_27-12-4","t":"불법원인급여를 규정한 민법 제746조 소정의 \"불법의 원인\"이라 함은 재산을 급여한 원인이 선량한 풍속 기타 사회질서에 위반하는 경우를 가리키는 것으로서, 강제집행을 면할 목적으로 부동산의 소유자명의를 신탁하는 것이 위와 같은 불법원인급여에 해당한다고 볼 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2021_27-12-5","t":"민법 제108조 제1항에서 상대방과 통정한 허위의 의사표시를 무효로 규정하고, 제2항에서 그 의사표시의 무효는 선의의 제3자에게 대항하지 못한다고 규정하고 있는데, 여기에서 제3자는 특별한 사정이 없는 한 선의로 추정할 것이므로, 제3자가 악의라는 사실에 관한 주장·입증책임은 그 허위표시의 무효를 주장하는 자에게 있다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2021_27-14-1","t":"미성년자가 토지매매행위를 부인하고 있는 이상, 미성년자가 그 법정대리인의 동의를 얻었다는 점에 관한 입증책임은 미성년자에게 없고 이를 주장하는 상대방에게 있다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2021_27-14-2","t":"책임능력 있는 미성년자의 불법행위로 인하여 손해가 발생한 경우에 그 발생된 손해가 당해 미성년자의 감독의무자의 의무위반과 상당인과관계가 있을 경우에는 감독의무자는 일반불법행위자로서 손해배상의무가 있다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2021_27-14-3","t":"미성년자의 법률행위에 법정대리인의 동의를 요하도록 하는 것은 강행규정인데, 위 규정에 반하여 이루어진 신용구매계약을 미성년자 스스로 취소하는 것을 신의칙 위반을 이유로 배척한다면, 이는 오히려 위 규정에 의해 배제하려는 결과를 실현시키는 셈이 되어 미성년자 제도의 입법 취지를 몰각시킬 우려가 있으므로, 법정대리인의 동의 없이 신용구매계약을 체결한 미성년자가 사후에 법정대리인의 동의 없음을 사유로 들어 이를 취소하는 것이 신의칙에 위배된 것이라고 할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2021_27-14-4","t":"미성년자의 친권자인 모가 자기 오빠의 제3자에 대한 채무의 담보로 미성년자 소유의 부동산에 근저당권을 설정하는 행위는, 채무자를 위한 것으로서 미성년자에게는 불이익만을 주는 것이어서 민법 제921조 제1항에 규정된 \"법정대리인인 친권자와 그 자 사이에 이해상반되는 행위\"에 해당한다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2021_27-14-5","t":"미성년자가 법률행위를 함에 있어서 요구되는 법정대리인의 동의는 언제나 명시적이어야 하는 것은 아니고 묵시적으로도 가능한 것이며, 미성년자의 행위가 위와 같이 법정대리인의 묵시적 동의가 인정되거나 처분허락이 있는 재산의 처분 등에 해당하는 경우라면, 미성년자로서는 더 이상 행위무능력을 이유로 그 법률행위를 취소할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2021_27-32-1","t":"미성년자의 법정대리인인 친권자의 법률행위에 있어서 법정대리인인 친권자의 대리행위가 객관적으로 볼 때 미성년자 본인에게는 경제적인 손실만을 초래하는 반면, 친권자나 제3자에게는 경제적인 이익을 가져오는 행위이고, 그 행위의 상대방이 이러한 사실을 알았거나 알 수 있었을 때에는, 민법 제107조 제1항 단서의 규정을 유추 적용하여 그 행위의 효과는 자(子)에게는 미치지 않는다고 해석함이 상당하다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2021_27-32-2","t":"외형상 형성된 법률관계를 기초로 하여 새로운 법률상 이해관계를 맺은 선의의 제3자에 대하여는 민법 제107조 제2 항의 규정을 유추적용하여 누구도 그와 같은 사정을 들어 대항할 수 없으며, 제3자가 악의라는 사실에 관한 주장·증명책임은 그 무효를 주장하는 자에게 있다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2021_27-32-3","t":"대리권이 법률행위에 의하여 부여된 경우에는 대리인은 본인의 승낙이 있거나 부득이한 사유있는 때가 아니어도 필요에 따라 복대리인을 선임할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2021_27-32-4","t":"의사표시의 효력이 의사의 흠결, 사기, 강박 또는 어느 사정을 알았거나 과실로 알지 못한 것으로 인하여 영향을 받을 경우에 그 사실의 유무는 대리인을 표준하여 결정한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2021_27-32-5","t":"일반적으로 매매계약에서 매도인으로 나온 사람이 소유권자로부터 매매에 관한 권한을 위임받은 내용의 위임장을 제시하고 매매계약을 체결하였다면 특단의 사정이 없는 한 그는 소유권자를 대리하여 매매행위를 한 것으로 보아야 할 것이고, 매매계약서의 매도인란에 대리관계의 표시가 없이 그 자신의 이름을 기재하였다고 하여도 이것만으로 그 자신이 매도인으로서 타인물의 매매를 한 것이라고 볼 수는 없는 것이다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2021_27-37-1","t":"계약체결의 요건을 규정하고 있는 강행법규에 위반한 계약은 무효이므로 그 경우에 계약상대방이 선의·무과실이더라도 민법 제107조의 비진의표시의 법리 또는 표현대리 법리가 적용될 여지는 없다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2021_27-37-2","t":"법률상 또는 사실상의 장애로 자기 명의로 대출받을 수 없는 자를 위하여 대출금채무자로서의 명의를 빌려준 자에게 그와 같은 채무부담의 의사가 없는 것이라고는 할 수 없을 것이어서 그러한 의사표시를 비진의표시에 해당한다고 볼 수 없다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2021_27-37-3","t":"비진의의사표시에 있어서의 진의란 특정한 내용의 의사표시를 하고자 하는 표의자의 생각을 말하는 것이지 표의자가 진정으로 마음속에서 바라는 사항을 뜻하는 것은 아니라고 할 것이므로, 비록 재산을 강제로 뺏긴다는 것이 표의자의 본심으로 잠재되어 있었다 하여도 표의자가 강박에 의하여서나마 증여를 하기로 하고 그에 따른 증여의 의사표시를 한 이상 증여의 내심의 효과의사가 결여된 것이라고 할 수는 없다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2021_27-37-4","t":"어떠한 의사표시가 비진의의사표시로서 무효라고 주장하는 경우에 그 입증책임은 그 주장자에게 있다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2021_27-37-5","t":"진의 아닌 의사표시인지의 여부는 효과의사에 대응하는 내심의 의사가 있는지 여부에 따라 결정되는 것인 바, 근로자가 사용자의 지시에 좇아 일괄하여 사직서를 작성 제출할 당시 그 사직서에 기하여 의원면직처리될지 모른다는 점을 인식하였다면 내심에 사직의 의사가 있는 것으로 보아야 한다.","ox":"X","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2022_28-16-1","t":"착오로 인한 취소 제도와 매도인의 하자담보책임 제도는 취지가 서로 다르고, 요건과 효과도 구별되므로, 매매계약 내용의 중요 부분에 착오가 있는 경우 매수인은 매도인의 하자담보책임이 성립하는지와 상관없이 착오를 이유로 매매계약을 취소할 수 있다.","ox":"O","m":"①","c":"A","tp":"의사표시"},{"y":2022,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2022_28-16-2","t":"소취하합의의 의사표시는 법률행위의 내용의 중요 부분에 착오가 있더라도 민법 제109조에 따라 취소할 수는 없다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2022_28-16-3","t":"장래에 발생할 막연한 사정을 예측하거나 기대하고 법률행위를 한 경우 그러한 예측이나 기대와 다른 사정이 발생하였다고 하더라도 그로 인한 위험은 원칙적으로 법률행위를 한 사람이 스스로 감수하여야 하고 상대방에게 전가해서는 안 되므로 착오를 이유로 취소를 구할 수 없다.","ox":"O","m":"③","c":"A","tp":"의사표시"},{"y":2022,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2022_28-16-4","t":"하나의 법률행위의 일부분에만 취소사유가 있다고 하더라도 그 법률행위가 가분적이거나 그 목적물의 일부가 특정될 수 있다면, 그 나머지 부분이라도 이를 유지하려는 당사자의 가정적 의사가 인정되는 경우 그 일부만의 취소도 가능하다고 할 것이고, 그 일부의 취소는 법률행위의 일부에 관하여 효력이 생긴다.","ox":"O","m":"④","c":"A","tp":"의사표시"},{"y":2022,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2022_28-16-5","t":"학교법인이 사립학교법상의 제한규정 때문에 그 학교의 교직원들인 소외인들의 명의를 빌려서 피고로부터 금원을 차용한 경우에 피고 역시 그러한 사정을 알고 있었다고 하더라도 위 소외인들의 의사는 위 금전의 대차에 관하여 그들이 주채무자로서 채무를 부담하겠다는 뜻이라고 해석함이 상당하므로 이를 진의 아닌 의사표시라고 볼 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2022_28-26-1","t":"매매계약의 체결과 이행에 관하여 포괄적으로 대리권을 수여받은 대리인은 특별한 다른 사정이 없는 한 상대방에 대하여 약정된 매매대금지급기일을 연기하여 줄 권한도 가진다고 보아야 할 것이다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2022_28-26-2","t":"대리권 없는 자가 타인의 대리인으로 계약을 한 경우에 상대방은 상당한 기간을 정하여 본인에게 그 추인 여부의 확답을 최고할 수 있고, 본인이 그 기간 내에 확답을 발하지 않은 때에는 추인을 거절한 것으로 본다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2022_28-26-3","t":"민법 제134조에서 정한 상대방의 철회권은, 무권대리행위가 본인의 추인에 따라 효력이 좌우되어 상대방이 불안정한 지위에 놓이게 됨을 고려하여 대리권이 없었음을 알지 못한 상대방을 보호하기 위하여 상대방에게 부여된 권리로서, 상대방이 유효한 철회를 하면 무권대리행위는 확정적으로 무효가 되어 그 후에는 본인이 무권대리행위를 추인할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2022_28-26-4","t":"대리인이 대리권 소멸 후 복대리인을 선임하여 복대리인으로 하여금 상대방과 사이에 대리행위를 하도록 한 경우에도, 상대방이 대리권 소멸 사실을 알지 못하여 복대리인에게 적법한 대리권이 있는 것으로 믿었고 그와 같이 믿은 데 과실이 없다면 민법 제129조에 의한 표현대리가 성립할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2022_28-26-5","t":"증권회사의 직원이 아니면서도 사실상 투자상담사의 역할을 하는 자가 고객의 유치, 투자상담 및 권유, 위탁매매약정실적의 제고 등의 업무를 위임받아 증권회사를 대리하여 예탁금을 수령하거나 위탁매매계약을 체결한 경우 권한초과의 표현대리가 성립한다.","ox":"X","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2022_28-40-1","t":"비법인사단의 경우에는 대표자의 대표권 제한에 관하여 등기할 방법이 없어 민법 제60조의 규정을 준용할 수 없고, 비법인사단의 대표자가 정관에서 사원총회의 결의를 거쳐야 하도록 규정한 대외적 거래행위에 관하여 이를 거치지 아니한 경우라도, 이와 같은 사원총회 결의사항은 비법인사단의 내부적 의사결정에 불과하다 할 것이므로, 그 거래 상대방이 그와 같은 대표권 제한 사실을 알았거나 알 수 있었을 경우가 아니라면 그 거래행위는 유효하다고 봄이 상당하고, 이 경우 거래의 상대방이 대표권 제한 사실을 알았거나 알 수 있었음은 이를 주장하는 비법인사단측이 주장 및 증명하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2022_28-40-2","t":"임시이사의 선임에 관한 민법 제63조는 법인의 조직과 활동에 관한 것으로서 법인격을 전제로 하는 조항은 아니라 할 것이고, 법인 아닌 사단이나 재단의 경우에도 이사가 없거나 결원이 생길 수 있으며, 통상의 절차에 따른 새로운 이사의 선임이 극히 곤란하고 종전 이사의 긴급처리권도 인정되지 아니하는 경우에는 사단이나 재단 또는 타인에게 손해가 생길 염려가 있을 수 있으므로, 민법 제63조는 법인 아닌 사단이나 재단에도 유추 적용할 수 있다.","ox":"O","m":"②","c":"A","tp":"비법인사단"},{"y":2022,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2022_28-40-3","t":"종중은 공동선조의 분묘수호와 제사 및 후손 상호간의 친목을 목적으로 하여 형성되는 자연발생적인 종족단체로서 그 선조의 사망과 동시에 그 자손에 의하여 관습상 당연히 성립하는 것이므로 공동선조의 후손들 중 특정 지역 거주자나 특정 범위 내의 자들만으로 구성된 종중이란 있을 수 없고, 종중이 공동선조의 제사봉행을 주목적으로 하는 것과 구관습상의 양자제도의 목적에 비추어 타가에 출계한 자는 친가의 생부를 공동선조로 하여 자연발생적으로 형성되는 종중의 구성원이 될 수 없다.","ox":"O","m":"③","c":"A","tp":"비법인사단"},{"y":2022,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2022_28-40-4","t":"종중총회는 특별한 사정이 없는 한 족보에 의하여 소집통지 대상이 되는 종중원의 범위를 확정한 후 국내에 거주하고 소재가 분명하여 통지가 가능한 모든 종중원에게 개별적으로 소집통지를 함으로써 각자가 회의와 토의 및 의결에 참가할 수 있는 기회를 주어야 하고, 일부 종중원에게 소집통지를 결여한 채 개최된 종중총회의 결의는 효력이 없으나, 그 소집통지의 방법은 반드시 직접 서면으로 하여야만 하는 것은 아니고 구두 또는 전화로 하여도 되고 다른 종중원이나 세대주를 통하여 하여도 무방하며, 경우에 따라서는 소집권자가 지파 또는 거주지별 대표자에게 총회소집을 알리는 것만으로도 적법하게 통지할 수 있다.","ox":"X","m":"④","c":"A","tp":"비법인사단"},{"y":2022,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2022_28-40-5","t":"교회의 교인들은 교회 재산을 총유의 형태로 소유하면서 사용·수익할 것인데, 일부 교인들이 교회를 탈퇴하여 그 교회 교인으로서의 지위를 상실하게 되면 탈퇴가 개별적인 것이든 집단적인 것이든 이와 더불어 종전 교회의 총유 재산의 관리처분에 관한 의결에 참가할 수 있는 지위나 그 재산에 대한 사용·수익권을 상실하고, 종전 교회는 잔존 교인들을 구성원으로 하여 실체의 동일성을 유지하면서 존속하며 종전 교회의 재산은 그 교회에 소속된 잔존 교인들의 총유로 귀속됨이 원칙이다. 그리고 교단에 소속되어 있던 지교회의 교인들의 일부가 소속 교단을 탈퇴하기로 결의한 다음 종전 교회를 나가 별도의 교회를 설립하여 별도의 대표자를 선정하고 나아가 다른 교단에 가입한 경우, 그 교회는 종전 교회에서 집단적으로 이탈한 교인들에 의하여 새로이 법인 아닌 사단의 요건을 갖추어 설립된 신설 교회라 할 것이어서, 그 교회 소속 교인들은 더 이상 종전 교회의 재산에 대한 권리를 보유할 수 없게 된다.","ox":"O","m":"⑤","c":"A","tp":"비법인사단"},{"y":2023,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2023_29-07-1","t":"법인격 없는 사단이나 재단으로서 권리의무의 주체가 되는 독립한 사찰은 독자적으로 존속할 수도 있지만 종교적 이념이나 교리 또는 종교적 이해관계를 같이하는 사람과 단체로 구성된 상위 종단에 소속되어 존속하기도 하는데, 사찰의 종단소속관계는 사법상 계약의 영역으로서 사찰이 특정 종단에 소속하려면 이에 관한 사찰과 특정 종단 사이의 합의가 전제되어야 한다.","ox":"O","m":"①","c":"A","tp":"사찰(寺刹)"},{"y":2023,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2023_29-07-2","t":"개인사찰로 관리·운영되어 오던 사찰이 종단 소속 사찰로 등록되어 종단으로부터 주지 임명을 받은 후 관할 관청에 종단 소속으로 사찰등록 및 주지등록을 하고 사찰 부지에 관하여 사찰 명의로 소유권이전등기를 경료한 경우, 특별한 사정이 없는 한 그 사찰은 종단 소속 불교단체 내지는 법인 아닌 사단 또는 재단으로서의 실체를 갖춘 독립된 사찰로 보아야 한다.","ox":"O","m":"②","c":"A","tp":"사찰(寺刹)"},{"y":2023,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2023_29-07-3","t":"개인사찰에 있어서 창건주에 의하여 건립되었던 사찰건물이 그와 무관하게 멸실된 후 동일 용도의 사찰건물을 새로 건립하거나 산신각 등 추가적인 사찰건물이 필요하게 되어 이를 건립한 경우, 창건주가 직접 그 건물들을 건립하지 아니하고 창건주에 의하여 임명된 주지가 주도하여 신도들의 시주를 주된 재원으로 하여 이를 건립하였다면, 특별한 사정이 없는 한 위와 같이 추가로 건립된 사찰건물들은 창건주가 아닌 주지와 신도들의 소유로 귀속된다.","ox":"X","m":"③","c":"A","tp":"사찰(寺刹)"},{"y":2023,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2023_29-07-4","t":"사찰이 특정 종단과 종단소속에 관한 합의를 하게 되면 그때부터는 그 종단의 소속 사찰이 되어 종단의 종헌이나 종법을 사찰의 자치법규로 삼아 따라야 하고 사찰의 주지임면권도 종단에 귀속되는 등 사찰 자체의 지위나 권한에 중대한 변화를 가져오게 되므로 어느 사찰이 특정 종단에 가입하거나 소속 종단을 변경하기 위해서는 사찰 자체의 자율적인 의사결정이 기본적인 전제가 되어야 한다.","ox":"O","m":"④","c":"A","tp":"사찰(寺刹)"},{"y":2023,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2023_29-07-5","t":"사찰이 소속 종단의 종헌에 따르지 아니하고 그 신도와 승려가 결합하여 그 소속 종단을 탈종하였다 하더라도 이는 그 신도와 승려 개인이 소속 종단에서 탈퇴하게 되는 데에 그치는 것일 뿐 그로써 이미 독립한 권리·의무의 귀속 주체로 성립한 사찰 자체의 종단 소속이 변경되게 되는 것은 아니고, 사찰이 일단 성립한 이상 사찰 그 자체의 분열도 인정되지 않는다.","ox":"O","m":"⑤","c":"A","tp":"사찰(寺刹)"},{"y":2023,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2023_29-14-1","t":"한정후견의 개시를 청구한 사건에서 의사의 감정 결과 등에 비추어 성년후견 개시의 요건을 충족하고 본인도 성년후견의 개시를 희망한다면 법원이 성년후견을 개시할 수 있고, 성년후견 개시를 청구하고 있더라도 필요하다면 한정후견을 개시할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2023_29-14-2","t":"피성년후견인 또는 피한정후견인은 의사능력이 있는 한 성년후견인 또는 한정후견인의 동의 없이도 유언을 할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2023_29-14-3","t":"후견심판 사건에서 사전처분으로 후견심판이 확정될 때까지 임시후견인이 선임된 경우, 아직 성년후견이 개시되기 전이라면 의사가 유언서에 심신 회복 상태를 부기하고 서명날인하도록 요구한 민법 제1063조 제2항은 적용되지 않는다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2023_29-14-4","t":"후견계약이 등기된 경우 본인의 이익을 위한 특별한 필요성이 인정되어 민법 제9조 제1항 등에서 정한 법정후견 청구권자, 임의후견인이나 임의후견감독인의 청구에 따라 법정후견 심판을 한 경우 후견계약은 임의후견감독인의 선임과 관계없이 본인이 성년후견 또는 한정후견 개시의 심판을 받은 때 종료한다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2023_29-14-5","t":"후견계약이 등기되어 있는 경우에는 본인의 이익을 위하여 특별히 필요할 때에만 한정후견 등의 심판을 할 수 있도록 규정한 민법 제959조의20 제1항은 본인에 대해 한정후견개시심판 청구가 제기된 후 심판이 확정되기 전에 후견계약이 등기된 경우에는 적용되지 않는다.","ox":"X","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2023_29-16-1","t":"매매계약의 체결과 이행에 관하여 포괄적으로 대리권을 수여받은 대리인이라도 특별한 다른 사정이 없는 한 상대방에 대하여 약정된 매매대금지급기일을 연기하여 줄 권한은 없다.","ox":"X","m":"①","c":"A","tp":"임의대리권"},{"y":2023,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2023_29-16-2","t":"수권행위의 통상의 내용으로서의 임의대리권은 그 권한에 부수하여 필요한 한도에서 상대방의 의사표시를 수령하는 이른바 수령대리권을 포함한다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2023_29-16-3","t":"부동산의 소유자로부터 매매계약을 체결할 대리권을 수여받은 대리인은 특별한 사정이 없는 한 그 매매계약에서 약정한 바에 따라 중도금이나 잔금을 수령할 권한이 있다.","ox":"O","m":"③","c":"A","tp":"임의대리권"},{"y":2023,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2023_29-16-4","t":"예금계약의 체결을 위임받은 자가 가지는 대리권에 당연히 그 예금을 담보로 하여 대출을 받거나 이를 처분할 수 있는 대리권이 포함되어 있는 것은 아니다.","ox":"O","m":"④","c":"A","tp":"임의대리권"},{"y":2023,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2023_29-16-5","t":"소송상 화해나 청구의 포기에 관한 특별수권이 되어 있다면 특별한 사정이 없는 한 그러한 소송행위에 대한 수권만이 아니라 그러한 소송행위의 전제가 되는 당해 소송물인 권리의 처분이나 포기에 대한 권한도 수여되어 있다고 봄이 상당하다.","ox":"O","m":"⑤","c":"A","tp":"임의대리권"},{"y":2023,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2023_29-23-1","t":"교회가 법인 아닌 사단으로서 존재하는 이상 그 법률관계를 둘러싼 분쟁을 소송적인 방법으로 해결함에 있어서는 법인 아닌 사단에 관한 민법의 일반 이론에 따라 교회의 실체를 파악하고 교회의 재산 귀속에 대하여 판단하여야 하고, 그 교인들은 교회 재산을 총유의 형태로 소유하면서 사용·수익하게 된다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2023_29-23-2","t":"비법인사단인 교회의 대표자는 총유물인 교회 재산의 처분에 관하여 교인총회의 결의를 거치지 아니하고는 이를 대표하여 행할 권한이 없으나, 교회의 대표자가 권한 없이 행한 교회 재산의 처분행위에 대하여도 민법 제126조의 표현대리에 관한 규정이 준용될 수 있다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2023_29-23-3","t":"비법인사단이 타인 간의 금전채무를 보증하는 행위는 총유물 그 자체의 관리·처분이 따르지 아니하는 단순한 채무부담행위에 불과하여 이를 총유물의 관리·처분행위라고 볼 수는 없다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2023_29-23-4","t":"교회가 그 실체를 갖추어 법인 아닌 사단으로서 성립한 경우에 교회의 대표자가 교회를 위하여 취득한 권리의무는 교회에 귀속된다고 할 것이나, 교회가 아직 실체를 갖추지 못하여 법인 아닌 사단으로서 성립되기 이전에 설립의 주체인 개인이 취득한 권리의무는 그것이 앞으로 성립될 교회를 위한 것이라 하더라도 바로 법인 아닌 사단인 교회에 귀속될 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2023_29-23-5","t":"일부 교인들이 교회를 탈퇴하여 그 교회 교인으로서의 지위를 상실하게 되면 탈퇴가 개별적인 것이든 집단적인 것이든 이와 더불어 종전 교회의 총유 재산의 관리처분에 관한 의결에 참가할 수 있는 지위나 그 재산에 대한 사용·수익권을 상실하고, 종전 교회는 잔존 교인들을 구성원으로 하여 실체의 동일성을 유지하면서 존속하며 종전 교회의 재산은 그 교회에 소속된 잔존 교인들의 총유로 귀속됨이 원칙이다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2023_29-31-1","t":"동기의 착오가 법률행위의 내용의 중요 부분의 착오에 해당함을 이유로 표의자가 법률행위를 취소하려면 그 동기를 당해 의사표시의 내용으로 삼을 것을 상대방에게 표시하고 의사표시의 해석상 법률행위의 내용으로 되어 있다고 인정되면 충분하고 당사자들 사이에 별도로 그 동기를 의사표시의 내용으로 삼기로 하는 합의까지 이루어질 필요는 없다.","ox":"O","m":"①","c":"A","tp":"착오로 인한 의사표시"},{"y":2023,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2023_29-31-2","t":"법률행위 내용의 중요 부분에 착오가 있는 때에는 그 의사표시를 취소할 수 있으나 그 착오가 표의자의 중대한 과실로 인한 때에는 취소하지 못한다. 여기서 ‘중대한 과실’이라 함은 표의자의 직업, 행위의 종류, 목적 등에 비추어 보통 요구되는 주의를 현저히 결여하는 것을 의미한다.","ox":"O","m":"②","c":"A","tp":"착오로 인한 의사표시"},{"y":2023,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2023_29-31-3","t":"상대방이 표의자의 착오를 알고 이를 이용한 경우에는 착오가 표의자의 중대한 과실로 인한 것이라고 하더라도 표의자는 의사표시를 취소할 수 있다.","ox":"O","m":"③","c":"A","tp":"착오로 인한 의사표시"},{"y":2023,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2023_29-31-4","t":"주채무자의 차용금반환채무를 보증할 의사로 공정증서에 연대보증인으로 서명·날인하였으나 그 공정증서가 주채무자의 기존의 구상금채무 등에 관한 준소비대차계약의 공정증서이었던 경우, 위와 같은 착오는 연대보증계약의 중요 부분의 착오에 해당한다.","ox":"X","m":"④","c":"A","tp":"착오로 인한 의사표시"},{"y":2023,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2023_29-31-5","t":"민사소송법상의 소송행위에는 특별한 규정이나 특별한 사정이 없는 한 민법상의 법률행위에 관한 규정이 적용될 수 없는 것이므로, 착오로 항소이유서를 제출하였다고 하여 의사표시의 하자를 이유로 그와 같은 소송행위의 취소를 주장할 수는 없다.","ox":"O","m":"⑤","c":"A","tp":"착오로 인한 의사표시"},{"y":2024,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2024_30-12","t":"대리에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"대리에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","d":"ㄱ.대리권 남용 행위에 따라 외형상 형성된 법률관계를 기초로 하여 새로운 법률상 이해관계를 맺은 선의의 제3자에 대해서는 민법 제107조 제2항을 유추적용하여 누구도 그러한 사정을 들어 대항할 수 없는데, 제3자가 악의라는 사실에 관한 증명책임은 그 무효를 주장하는 자에게 있다.\nㄴ.대부중개업자가 전주를 위하여 금전소비대차계약과 그 담보를 위한 담보권설정계약을 체결할 대리권을 수여받은 것으로 인정되는 경우에는 특별한 사정이 없는 한 금전소비대차계약과 그 담보를 위한 담보권설정계약이 체결된 후에 이를 해제할 권한까지 당연히 가지고 있다고 볼 수 있다.\nㄷ.특정한 법률행위를 위임한 경우에 대리인이 본인의 지시에 좇아 그 행위를 한 때에는 본인은 자기가 안 사정 또는 과실로 인하여 알지 못한 사정에 관하여 대리인의 부지를 주장하지 못한다.\nㄹ.부부의 일방이 의식불명의 상태에 있어 사회통념상 대리관계를 인정할 필요가 있다는 사정이 인정된다면 그 배우자로서는 당연히 채무의 부담행위를 포함한 모든 법률행위에 관하여 대리권을 갖는다고 보아야 한다.\nㅁ.대리권 소멸 후의 표현대리에 관한 민법 제129조는 법정대리인의 대리권이 소멸된 경우에도 적용된다고 할 것이다.","o":["ㄱ, ㄴ, ㅁ","ㄱ, ㄷ, ㄹ","ㄱ, ㄷ, ㅁ","ㄴ, ㄷ, ㅁ","ㄴ, ㄹ, ㅁ"],"a":3}},{"y":2024,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2024_30-19-1","t":"하나의 법률관계를 둘러싸고 각기 다른 내용을 정한 여러 개의 계약서가 순차로 작성되어 있는 경우 당사자가 그러한 계약서에 따른 법률관계나 우열관계를 명확하게 정하고 있다면 그와 같은 내용대로 효력이 발생하지만, 여러 개의 계약서에 따른 법률관계 등이 명확히 정해져 있지 않다면 각각의 계약서에 정해져 있는 내용 중 서로 양립할 수 없는 부분에 관해서는 원칙적으로 나중에 작성된 계약서에서 정한 대로 계약 내용이 변경되었다고 해석하는 것이 합리적이다.","ox":"O","m":"①","c":"A","tp":"법률행위의 해석"},{"y":2024,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2024_30-19-2","t":"계약의 합의해지는 계속적 채권채무관계에서 당사자가 이미 체결한 계약의 효력을 장래에 향하여 소멸시킬 것을 내용으로 하는 새로운 계약으로서, 이를 인정하기 위해서는 계약이 성립하는 경우와 마찬가지로 기존 계약의 효력을 장래에 향하여 소멸시키기로 하는 내용의 청약과 승낙이라는 서로 대립하는 의사표시가 합치될 것을 요건으로 한다. 이와 같은 합의가 성립하기 위해서는 쌍방 당사자의 표시행위에 나타난 의사의 내용이 객관적으로 일치하여야 하지만 계약당사자 일방이 계약해지에 관한 조건을 제시한 경우 그 조건에 관한 합의까지 이루어질 필요는 없다.","ox":"X","m":"②","c":"A","tp":"법률행위의 해석"},{"y":2024,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2024_30-19-3","t":"계약을 체결하는 행위자가 타인의 이름으로 법률행위를 한 경우에 행위자 또는 명의인 가운데 누구를 계약의 당사자로 볼 것인가에 관하여는, 우선 행위자와 상대방의 의사가 일치한 경우에는 그 일치한 의사대로 행위자 또는 명의인을 계약의 당사자로 확정해야 하고, 행위자와 상대방의 의사가 일치하지 않는 경우에는 그 계약의 성질·내용·목적·체결 경위 등 그 계약 체결 전후의 구체적인 제반 사정을 토대로 상대방이 합리적인 사람이라면 행위자와 명의자 중 누구를 계약 당사자로 이해할 것인가에 의하여 당사자를 결정하여야 한다.","ox":"O","m":"③","c":"A","tp":"법률행위의 해석"},{"y":2024,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2024_30-19-4","t":"성립이 진정한 것으로 인정되는 처분문서(매매계약서)는 그 내용을 부정할만한 분명하고 수긍할 수 있는 이유가 없는 한 그 내용되는 법률행위의 존재를 인정하여야 한다.","ox":"O","m":"④","c":"A","tp":"법률행위의 해석"},{"y":2024,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2024_30-19-5","t":"계약이 성립하기 위하여는 당사자 사이에 의사의 합치가 있을 것이 요구되는데, 이러한 의사의 합치는 당해 계약의 내용을 이루는 모든 사항에 관하여 있어야 하는 것은 아니고 그 본질적 사항이나 중요사항에 관하여 구체적으로 의사의 합치가 있거나 적어도 장래 구체적으로 특정할 수 있는 기준과 방법 등에 관한 합의가 있으면 된다. 따라서 당사자 사이에 체결된 계약과 이에 따라 장래 체결할 본계약을 구별하고자 하는 의사가 명확하거나 일정한 형식을 갖춘 본계약 체결이 별도로 요구되는 경우 등의 특별한 사정이 없다면, 매매계약이 성립하였다고 보기에 충분한 합의가 있었음에도 법원이 매매계약 성립을 부정하고 별도의 본계약이 체결되어야 하는 매매예약에 불과하다고 단정할 것은 아니다.","ox":"O","m":"⑤","c":"A","tp":"법률행위의 해석"},{"y":2024,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2024_30-28-1","t":"계속적 보증계약에서 보증인은 변제기에 있는 주채무 전액에 대하여 책임을 지는 것이 원칙이고, 다만 보증 당시 주채무의 액수를 보증인이 예상하였거나 예상할 수 있었을 경우에는 그 예상 범위로 보증책임을 제한할 수 있으나, 그 예상 범위를 상회하는 주채무 과다 발생의 원인이 채권자가 주채무자의 자산 상태가 현저히 악화된 사실을 잘 알거나 중대한 과실로 알지 못한 탓으로 이를 알지 못하는 보증인에게 아무런 통보나 의사 타진도 없이 고의로 거래 규모를 확대함에 연유하는 등 신의칙에 반하는 사정이 있는 경우에 한하여 보증인의 책임을 합리적인 범위 내로 제한할 수 있다.","ox":"O","m":"①","c":"A","tp":"신의칙과 권리남용"},{"y":2024,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2024_30-28-2","t":"위임계약에서 보수액에 관하여 약정한 경우에 수임인은 원칙적으로 약정보수액을 전부 청구할 수 있는 것이 원칙이지만, 위임의 경위, 위임업무 처리의 경과와 난이도, 투입한 노력의 정도, 위임인이 업무 처리로 인하여 얻게 되는 구체적 이익, 기타 변론에 나타난 제반 사정을 고려할 때 약정보수액이 부당하게 과다하여 신의성실의 원칙이나 형평의 원칙에 반한다고 볼 만한 특별한 사정이 있는 때에는 예외적으로 상당하다고 인정되는 범위 내의 보수액만을 청구할 수 있다.","ox":"O","m":"②","c":"A","tp":"신의칙과 권리남용"},{"y":2024,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2024_30-28-3","t":"계약 성립의 기초가 된 사정이 현저히 변경되고 당사자가 계약의 성립 당시 이를 예견할 수 없었으며, 그로 인하여 계약을 그대로 유지하는 것이 당사자의 이해에 중대한 불균형을 초래하거나 계약을 체결한 목적을 달성할 수 없는 경우에는 계약준수 원칙의 예외로서 사정변경을 이유로 계약을 해제하거나 해지할 수 있다. 여기에서 말하는 사정이란 당사자들에게 계약 성립의 기초가 된 사정뿐만 아니라, 어느 일방당사자가 변경에 따른 불이익이나 위험을 떠안기로 한 사정도 모두 포함될 수 있다.","ox":"X","m":"③","c":"A","tp":"신의칙과 권리남용"},{"y":2024,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2024_30-28-4","t":"점유자가 취득시효완성 후에 그 사실을 모르고 당해 토지에 관하여 어떠한 권리도 주장하지 않기로 하였다 하더라도 이에 반하여 시효주장을 하는 것은 특별한 사정이 없는 한 신의칙상 허용되지 않는다.","ox":"O","m":"④","c":"A","tp":"신의칙과 권리남용"},{"y":2024,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2024_30-28-5","t":"상속인 중의 1인이 피상속인의 생존시에 피상속인에 대하여 상속을 포기하기로 약정하였다고 하더라도, 상속개시 후 민법이 정하는 절차와 방식에 따라 상속포기를 하지 아니한 이상, 상속개시 후에 자신의 상속권을 주장하는 것은 정당한 권리행사로서 권리남용에 해당하거나 또는 신의칙에 반하는 권리의 행사라고 할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"신의칙과 권리남용"},{"y":2024,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2024_30-29-1","t":"종중이란 공동선조의 분묘수호와 제사 및 종원 상호 간의 친목 등을 목적으로 하여 구성되는 자연발생적인 종족집단이므로, 종중의 이러한 목적과 본질에 비추어 볼 때 공동선조와 성과 본을 같이 하는 후손은 성별의 구별 없이 성년이 되면 당연히 그 구성원이 된다. 민법 제781조 제6항에 따라 자녀의 복리를 위하여 자녀의 성과 본을 변경할 필요가 있어 자녀의 성과 본이 모의 성과 본으로 변경되었을 경우 성년인 그 자녀는 모가 속한 종중의 공동선조와 성과 본을 같이 하는 후손으로서 당연히 종중의 구성원이 된다.","ox":"O","m":"①","c":"A","tp":"권리의 주체나 객체"},{"y":2024,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2024_30-29-2","t":"사단법인의 사원총회의 결의는 민법 또는 정관에 다른 규정이 없으면 사원 과반수의 출석과 출석사원 결의권의 과반수로써 하는데, 이 때 각 사원의 결의권 행사에 관한 의사의 진정성을 담보하기 위하여 결의권을 서면으로 행사하는 것은 금지되나, 대리인을 통해 결의권을 행사하는 것은 허용된다.","ox":"X","m":"②","c":"A","tp":"권리의 주체나 객체"},{"y":2024,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2024_30-29-3","t":"의사능력이란 자기 행위의 의미나 결과를 정상적인 인식력과 예기력을 바탕으로 합리적으로 판단할 수 있는 정신적 능력이나 지능을 말한다. 의사능력 유무는 구체적인 법률행위와 관련하여 개별적으로 판단해야 하고, 특히 어떤 법률행위가 일상적인 의미만을 이해해서는 알기 어려운 특별한 법률적 의미나 효과가 부여되어 있는 경우 의사능력이 인정되기 위해서는 그 행위의 일상적인 의미뿐만 아니라 법률적인 의미나 효과에 대해서도 이해할 수 있어야 한다.","ox":"O","m":"③","c":"A","tp":"권리의 주체나 객체"},{"y":2024,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2024_30-29-4","t":"법인의 불법행위능력을 규정한 민법 제35조에서 말하는 ‘이사 기타 대표자’는 법인의 대표기관을 의미하는 것이고 대표권이 없는 이사는 법인의 기관이기는 하지만 대표기관은 아니기 때문에 그들의 행위로 인하여 법인의 불법행위가 성립하지 않는다.","ox":"O","m":"④","c":"A","tp":"권리의 주체나 객체"},{"y":2024,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2024_30-29-5","t":"구분건물의 전유부분에 대한 소유권보존등기만 경료되고 대지지분에 대한 등기가 경료되기 전에 전유부분만에 대해 내려진 가압류결정의 효력은, 대지사용권의 분리처분이 가능하도록 규약으로 정하였다는 등의 특별한 사정이 없는 한 종물 내지 종된 권리인 그 대지권에까지 미친다.","ox":"O","m":"⑤","c":"A","tp":"권리의 주체나 객체"},{"y":2025,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2025_31-03-1","t":"토지 및 그 지상 건물 모두가 각 공유에 속한 상태에서 토지 및 건물공유자 중 1인이 그중 건물 지분만을 다른 사람에게 증여하여 토지와 건물의 소유자가 달라진 경우, 토지 전부에 관하여 건물의 소유를 위한 관습법상 법정지상권이 성립된 것으로 볼 수 없다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2025_31-03-2","t":"사실인 관습은 법령으로서의 효력이 없는 단순한 관행으로서 법률행위의 당사자의 의사를 보충함에 그치는 것이다.","ox":"O","m":"②","c":"A","tp":"관습법"},{"y":2025,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2025_31-03-3","t":"사회를 지배하는 기본적 이념이나 사회질서의 변화로 인하여 관습법을 적용하여야 할 시점에 있어서의 전체 법질서에 부합하지 않게 되었다면 그러한 관습법은 법적 규범으로서의 효력이 부정될 수밖에 없다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2025_31-03-4","t":"외국적 요소가 있는 법률관계에 적용될 외국법규의 내용을 확정하고 그 의미를 해석할 때 외국 관습법까지 고려할 수는 없다.","ox":"X","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2025_31-03-5","t":"일반적으로 볼 때 법령과 같은 효력을 갖는 관습법은 당사자의 주장·증명을 기다림이 없이 법원이 직권으로 이를 확정하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2025_31-15-1","t":"법인은 이사 기타 대표자가 그 직무에 관하여 타인에게 가한 손해를 배상할 책임이 있다. 이사 기타 대표자는 이로 인하여 자기의 손해배상책임을 면하지 못한다.","ox":"O","m":"①","c":"A","tp":"법인의 불법행위"},{"y":2025,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2025_31-15-2","t":"법인의 목적범위 외의 행위로 인하여 타인에게 손해를 가한 때에는 그 사항의 의결에 찬성하거나 그 의결을 집행한 사원, 이사 및 기타 대표자가 연대하여 배상하여야 한다.","ox":"O","m":"②","c":"A","tp":"법인의 불법행위"},{"y":2025,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2025_31-15-3","t":"대표권이 없는 이사도 법인의 기관에 해당하므로, 그들의 행위로 인하여 법인의 불법행위가 성립한다.","ox":"X","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2025_31-15-4","t":"학교법인의 설립자로서 이사 겸 학교장인 자가 자기 개인의 사업자금으로 사용할 목적으로 학교법인의 명의로 금원을 차용하면서 그 차용을 위하여 학교법인의 이사회결의까지 있었다면 그 차용금의 사용목적이 무엇이던간에 위 학교장의 차용행위는 학교법인의 사무집행 행위라 하지 않을 수 없다.","ox":"O","m":"④","c":"A","tp":"법인의 불법행위"},{"y":2025,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2025_31-15-5","t":"이사회의 의결은 원칙적으로 법인의 내부행위에 불과하므로 특별한 사정이 없는 한 그 사항의 의결에 찬성하였다는 이유만으로 제3자의 채권을 침해한다거나 대표자의 행위에 가공 또는 방조한 자로서 제3자에 대하여 불법행위책임을 부담한다고 할 수는 없다.","ox":"O","m":"⑤","c":"A","tp":"법인의 불법행위"},{"y":2025,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2025_31-20-1","t":"과거에 가졌던 대리권이 소멸되어 민법 제129조(대리권소멸후의 표현대리)에 의하여 표현대리로 인정되는 경우에 그 표현대리의 권한을 넘는 대리행위가 있을 때에는 민법 제126조(권한을 넘은 표현대리)에 의한 표현대리가 성립할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2025_31-20-2","t":"민법 제126조의 표현대리에서 자칭 대리인에게 대리권이 있다고 믿을 만한 정당한 이유가 있는지 여부는 대리행위인 매매계약 당시를 기준으로 결정하여야 하고 매매계약 성립 이후의 사정은 고려할 것이 아니다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2025_31-20-3","t":"교회의 대표자가 권한 없이 행한 교회 재산의 처분행위에 대하여는 민법 제126조의 표현대리에 관한 규정이 준용되지 아니한다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2025_31-20-4","t":"복대리인 선임권이 없는 대리인에 의하여 선임된 복대리인의 권한은 민법 제126조의 기본대리권이 될 수 없다.","ox":"X","m":"④","c":"A","tp":"표현대리"},{"y":2025,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2025_31-20-5","t":"대리권의 소멸은 선의의 제3자에게 대항하지 못한다. 그러나 제3자가 과실로 인하여 그 사실을 알지 못한 때에는 그러하지 아니하다.","ox":"O","m":"⑤","c":"A","tp":"표현대리"},{"y":2025,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2025_31-31-1","t":"법인이거나 비법인 사단인 어느 단체가 상급단체에 가입되어 있는 경우, 가입단체의 조직과 운영에 관하여는 특별한 사정이 없는 한 상급단체가 제정한 규칙에 따라 규율된다.","ox":"X","m":"①","c":"A","tp":"법인 및 법인 아닌 사단"},{"y":2025,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2025_31-31-2","t":"법인 아닌 사단의 대표자가 당해 법인 아닌 사단이 채무를 부담하게 되는 보증계약을 체결하는 경우에도 이로 인해 총유물에 대한 관리·처분이 따르지 않는 이상 사원총회의 결의를 거치지 않았다는 이유로 그 계약이 무효가 되지는 않는다.","ox":"O","m":"②","c":"A","tp":"법인 및 법인 아닌 사단"},{"y":2025,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2025_31-31-3","t":"법인이 피해자인 경우 법인의 업무에 관하여 포괄적 대리권을 가진 대리인이 가해자인 피용자의 행위가 사용자의 사무집행행위에 해당하지 않음을 안 때에는 피해자인 법인이 이를 알았다고 보아야 하고, 이러한 법리는 그 대리인이 본인인 법인에 대한 관계에서 이른바 배임적 대리행위를 하는 경우에도 마찬가지이다.","ox":"O","m":"③","c":"A","tp":"법인 및 법인 아닌 사단"},{"y":2025,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2025_31-31-4","t":"설립중의 회사의 개념과 법적 성격에 비추어, 법인 아닌 사단인 교회가 성립하기 전의 단계에서 설립중의 회사의 법리를 유추적용할 수는 없다.","ox":"O","m":"④","c":"A","tp":"법인 및 법인 아닌 사단"},{"y":2025,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2025_31-31-5","t":"재단법인에 관한 민법 규정이 준용되는 의료법인의 대표자가 그 법인의 재산을 처분함에 있어서 이사회의 결의를 거치도록 정관에 규정되어 있다면 그와 같은 규정은 법인 대표권의 제한에 관한 규정으로서 이러한 제한은 등기하지 아니하면 제3자에게 대항할 수 없는 것이고, 이 경우 제3자가 선의인지 악의인지는 묻지 아니한다.","ox":"O","m":"⑤","c":"A","tp":"법인 및 법인 아닌 사단"},{"y":2025,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2025_31-36-1","t":"종중의 대표자는 종중의 규약이나 관례가 있으면 그에 따라 선임하고 그것이 없다면 종장 또는 문장이 그 종원 중 성년 이상의 사람을 소집하여 선출하며, 평소에 종중에 종장이나 문장이 선임되어 있지 아니하고 선임에 관한 규약이나 관례가 없으면 현존하는 연고항존자가 종장이나 문장이 되어 국내에 거주하고 소재가 분명한 종원에게 통지하여 종중총회를 소집하고 그 회의에서 종중 대표자를 선임하는 것이 일반 관습이다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2025_31-36-2","t":"종중은 공동선조의 분묘수호와 제사 및 종원 상호 간의 친목 등을 목적으로 하여 구성되는 자연발생적인 종족집단으로 그 공동선조와 성과 본을 같이하는 후손은 그 의사와 관계없이 성년이 되면 당연히 그 구성원이 된다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2025_31-36-3","t":"종중 규약의 내용이 선량한 풍속 기타 사회질서에 반하는 경우 또는 종원이 가지는 고유하고 기본적인 권리의 본질적인 내용을 침해하는 등 종중의 본질이나 설립 목적에 크게 위배되는 경우 그 종중 규약은 무효로 보아야 한다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2025_31-36-4","t":"종중이 종중원의 자격을 박탈하거나 종중원이 종중을 탈퇴할 수 없는 것이지만, 공동선조의 후손들은 종중을 양분하는 것과 같은 종중분열을 할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2025_31-36-5","t":"종중이 자연발생적으로 성립한 후에 정관 등 종중규약을 작성하면서 일부 종원의 자격을 임의로 제한하거나 확장하더라도 그러한 규약은 종중의 본질에 반하여 무효이고, 그로 인하여 이미 성립한 종중의 실재 자체가 부인되는 것은 아니다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2026_32-05","t":"계약의 해석에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"계약의 해석에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","d":"ㄱ.처분문서는 그 성립의 진정함이 인정되고 문언의 객관적 의미가 명확하다면, 법원은 그 기재 내용을 부인할 만한 분명하고도 수긍할 수 있는 반증이 없는 한, 그 처분문서에 기재되어 있는 문언대로 의사표시의 존재와 내용을 인정하여야 한다.\nㄴ.법률행위의 해석에 있어 당사자가 표시한 문언에 의하여 객관적 의미가 명확하게 드러나지 않는 경우, 법원은 문언의 사전적 의미를 중심으로 해석하여야 하고, 그 법률행위가 이루어진 동기나 경위 등 다른 사정을 고려하여서는 아니 된다.\nㄷ.실제 계약을 체결한 행위자가 자신의 이름은 특정하여 기재하되 불특정인을 추가하는 방식으로 계약서상 당사자를 표시한 경우(즉, 실제 계약체결자의 이름에 ‘외\n○인’을 부가하는 형태), 계약서 자체에서 당사자로 특정할 수 있거나 상대방의 입장에서도 특정할 수 있는 특별한 사정이 인정될 수 있는 당사자만 계약당사자 지위를 인정할 수 있다.\nㄹ.공제와 상계 중 무엇에 관한 약정인지는 약정의 문언과 체계, 약정의 경위와 목적, 채권들의 상호관계, 제3자의 이해관계 등을 종합적으로 고려하여 합리적으로 해석하여야 한다.\nㅁ.처분문서인 계약서에 작성된 문언의 객관적 의미가 명확한 경우 특별한 사정이 없는 한 문언대로의 의사표시의 존재와 내용을 인정하여야 하고, 이를 달리 해석함으로써 당사자 사이의 법률관계에 중대한 영향을 초래하는 경우에는 문언의 내용을 더욱 엄격하게 해석하여야 한다.","o":["ㄴ, ㄹ","ㄱ, ㅁ","ㄱ, ㄷ, ㄹ, ㅁ","ㄱ, ㄹ","ㄴ, ㄹ, ㅁ"],"a":3}},{"y":2026,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2026_32-07-1","t":"상대방 있는 의사표시는 그 통지가 상대방에게 도달한 때부터 그 효력이 생기는데, 여기서 도달이란 사회통념상 상대방이 통지의 내용을 알 수 있는 객관적 상태에 놓여 있는 경우를 말하고, 상대방이 통지를 현실적으로 수령하였거나 통지의 내용을 알았을 것까지 필요로 하지 않는다.","ox":"O","m":"①","c":"A","tp":"의사표시의 도달과 효력발생시기"},{"y":2026,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2026_32-07-2","t":"승낙의 의사표시 발송 후에 승낙한 자가 사망하였다면 그 의사표시는 더 이상 효력이 없고 승낙기간 내에 상대방에게 도달하였다 하더라도 계약은 무효이다.","ox":"X","m":"②","c":"A","tp":"의사표시의 도달과 효력발생시기"},{"y":2026,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2026_32-07-3","t":"의사표시자는 미성년자에게 한 의사표시로써 대항할 수 없지만 미성년자의 법정대리인이 의사표시의 도달 사실을 안 후에는 그 의사표시로써 대항할 수 있다.","ox":"O","m":"③","c":"A","tp":"의사표시의 도달과 효력발생시기"},{"y":2026,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2026_32-07-4","t":"표의자가 과실없이 상대방을 알지 못하거나 상대방의 소재를 알지 못하는 경우에는 의사표시는 민사소송법 공시송달의 규정에 의하여 송달할 수 있다.","ox":"O","m":"④","c":"A","tp":"의사표시의 도달과 효력발생시기"},{"y":2026,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2026_32-07-5","t":"우편법 소정의 규정에 따라 우편물이 배달되었다고 하여 언제나 상대방 있는 의사표시의 통지가 상대방에게 도달하였다고 볼 수는 없다.","ox":"O","m":"⑤","c":"A","tp":"의사표시의 도달과 효력발생시기"},{"y":2026,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2026_32-13-1","t":"이사가 수인인 경우 정관에 다른 규정이 없으면 법인의 사무집행은 이사의 과반수로써 결정한다.","ox":"O","m":"①","c":"A","tp":"법인의 이사"},{"y":2026,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2026_32-13-2","t":"이사는 법인의 사무에 관하여 각자 법인을 대표함이 원칙이지만, 정관 등으로 그 대표권에 관하여 달리 정할 수 있으므로, 정관에서 법인을 대표하는 이사인 이사장과 대표권이 없는 일반 이사를 명백히 분리함으로써 법인의 대표권이 이사장에게만 전속되도록 정하고 이사장을 법인의 회원으로 이루어진 총회에서 투표로 직접 선출하도록 정한 경우, 일반 이사들에게는 처음부터 법인의 대표권이 전혀 주어져 있지 않기 때문에 이사장이 궐위된 경우에도 일반 이사가 법인을 대표할 권한을 가진다고 할 수 없다.","ox":"O","m":"②","c":"A","tp":"법인의 이사"},{"y":2026,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2026_32-13-3","t":"법인과 이사의 법률관계는 신뢰를 기초로 한 위임 유사의 관계로 볼 수 있는데, 민법 제689조 제1항에서 위임계약은 각 당사자가 언제든지 해지할 수 있다고 규정하고 있으므로, 법인은 원칙적으로 이사의 임기 만료 전에도 이사를 해임할 수 있다.","ox":"O","m":"③","c":"A","tp":"법인의 이사"},{"y":2026,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2026_32-13-4","t":"법인이 자치법규인 정관으로 이사의 해임사유 및 절차 등에 관하여 별도 규정을 둘 수 있고, 이러한 규정은 법인과 이사의 관계를 명확히 하는 것 외에 이사의 신분을 보장하는 의미도 아울러 가지고 있으므로 이를 단순히 주의적 규정으로 볼 수는 없는바, 법인의 정관에 이사의 해임사유에 관한 규정이 있는 경우 이사의 중대한 의무위반 또는 정상적인 사무집행 불능 등의 특별한 사정이 없는 이상 법인은 정관에서 정하지 아니한 사유로 이사를 해임할 수 없다.","ox":"O","m":"④","c":"A","tp":"법인의 이사"},{"y":2026,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2026_32-13-5","t":"법인과 이사의 법률관계는 신뢰를 기초로 한 위임 유사의 관계에 있으므로, 법인이 정관에서 이사의 해임사유와 절차를 정하였고 그 해임사유가 실제로 발생하였더라도 정관에서 정한 해임사유가 발생하였다는 요건 외에 이로 인하여 법인과 이사 사이의 신뢰관계가 더 이상 유지되기 어려울 정도에 이르러야 한다는 요건이 추가로 충족되어야 법인이 이사를 해임할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"법인의 이사"},{"y":2026,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2026_32-15-1","t":"민법 제109조 제1항은 법률행위 내용의 중요 부분에 착오가 있는 때에는 그 의사표시를 취소할 수 있다고 규정하면서, 같은 항 단서에서 그 착오가 표의자의 중대한 과실로 인한 때에는 취소하지 못한다고 규정하고 있는데, 위 단서 규정은 표의자의 상대방의 이익을 보호하기 위한 것이므로, 상대방이 표의자의 착오를 알고 이를 이용한 경우에는 그 착오가 표의자의 중대한 과실로 인한 것이라고 하더라도 표의자는 그 의사표시를 취소할 수 있다.","ox":"O","m":"①","c":"A","tp":"착오에 의한 의사표시"},{"y":2026,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2026_32-15-2","t":"계약당사자 쌍방이 계약의 전제나 기초가 되는 사항에 관하여 같은 내용으로 착오가 있고 이로 인하여 그에 관한 구체적 약정을 하지 아니하였다면, 당사자가 그러한 착오가 없을 때에 약정하였을 것으로 보이는 내용으로 당사자의 의사를 보충하여 계약을 해석할 수 있는데, 여기서 보충되는 당사자의 의사는 당사자의 실제 의사 또는 주관적 의사가 아니라 계약의 목적, 거래관행, 적용법규, 신의칙 등에 비추어 객관적으로 추인되는 정당한 이익조정 의사를 말한다.","ox":"O","m":"②","c":"A","tp":"착오에 의한 의사표시"},{"y":2026,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2026_32-15-3","t":"의사표시자가 행위를 할 당시 장래에 있을 어떤 사항의 발생을 예측한 데 지나지 않는 경우는 의사표시자의 심리상태에 인식과 대조사실의 불일치가 있다고 할 수 없어 민법 제109조에 따라 의사표시에 착오가 있다고 할 수 없지만, 어떠한 인식이 장래에 있을 어떤 사항에 대한 단순한 예측이나 기대에 머무르는 것이 아니라 그 예측이나 기대의 근거가 되는 현재 사정에 대한 인식을 포함하고 있고 그 인식이 실제로 있는 사실과 일치하지 않는다면 이를 착오로 다룰 수 있다.","ox":"O","m":"③","c":"A","tp":"착오에 의한 의사표시"},{"y":2026,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2026_32-15-4","t":"착오로 인한 의사표시 취소에 관한 민법 제109조 제1항은 표의자 보호를 위한 규정이므로, 당사자 합의로 그 적용을 배제할 수 없다.","ox":"X","m":"④","c":"A","tp":"착오에 의한 의사표시"},{"y":2026,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2026_32-15-5","t":"착오로 인한 취소 제도와 매도인의 하자담보책임 제도는 그 취지가 서로 다르고, 그 요건과 효과도 구별되므로, 매매계약 내용의 중요 부분에 착오가 있는 경우 매수인은 매도인의 하자담보책임이 성립하는지와 상관없이 착오를 이유로 그 매매계약을 취소할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"착오에 의한 의사표시"},{"y":2026,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2026_32-40-1","t":"통상 어떠한 계약의 체결에 관한 대리권을 수여받은 대리인은 필요한 한도에서 상대방의 의사표시를 수령하는 대리권도 있는 것으로 보아야 하므로 매매계약 체결의 대리권을 수여받은 대리인은 그 계약 체결 완료 이후 상대방의 계약해제의 의사를 수령할 권한까지 가지고 있다고 할 것이다.","ox":"X","m":"①","c":"A","tp":"대리권의 범위"},{"y":2026,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2026_32-40-2","t":"채권의 양수인이 양도인으로부터 채권양도통지 권한을 위임받아 대리인으로서 그 통지를 함에 있어서 그 통지가 본인인 채권의 양도인을 위한 것임을 표시하지 아니한 경우라도 채권양도통지를 둘러싼 여러 사정에 비추어 양수인이 대리인으로서 통지한 것임을 상대방이 알았거나 알 수 있었을 때에는 유효하게 되나, 이는 채권의 양수인이 양도인으로부터 채권양도통지 권한을 위임받아 그에 대한 대리권을 가지고 있음을 전제로 하는 것이다.","ox":"O","m":"②","c":"A","tp":"대리권의 범위"},{"y":2026,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2026_32-40-3","t":"인감도장 및 인감증명서는 대리권을 인정할 수 있는 하나의 자료에 지나지 아니하고 이에 의하여 당연히 피고에게 원고를 대리하여 양도담보부 금전소비대차계약을 체결하거나 위 계약에 대한 공정증서 작성을 촉탁할 대리권이 인정되는 것은 아니다.","ox":"O","m":"③","c":"A","tp":"대리권의 범위"},{"y":2026,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2026_32-40-4","t":"계약의 체결에 관한 대리권을 수여받은 대리인이 수권된 법률행위를 하게 되면 그것으로 대리권의 원인된 법률관계는 원칙적으로 목적을 달성하여 종료하는 것이고, 법률행위에 의하여 수여된 대리권은 그 원인된 법률관계의 종료에 의하여 소멸한다.","ox":"O","m":"④","c":"A","tp":"대리권의 범위"},{"y":2026,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2026_32-40-5","t":"대리권을 수여하는 수권행위는 불요식의 행위로서 명시적인 의사표시에 의함이 없이 묵시적인 의사표시에 의하여 할 수도 있으며, 어떤 사람이 대리인의 외양을 가지고 행위하는 것을 본인이 알면서도 이의를 하지 아니하고 방임하는 등 사실상의 용태에 의하여 대리권의 수여가 추단되는 경우도 있다.","ox":"O","m":"⑤","c":"A","tp":"대리권의 범위"}],"9":[{"y":2016,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2016_22-04-1","t":"여행에 하자가 있는 경우에는 여행자는 원칙적으로 여행용역을 제공하는 여행주최자에게 하자의 시정 또는 대금의 감액을 청구할 수 있다.","ox":"O","m":"①","c":"A","tp":"여행계약"},{"y":2016,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2016_22-04-2","t":"여행자는 여행을 시작하기 전에는 언제든지 계약을 해제할 수 있다. 다만 여행자는 상대방에게 발생한 손해를 배상하여야 한다.","ox":"O","m":"②","c":"A","tp":"여행계약"},{"y":2016,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2016_22-04-3","t":"부득이한 사유가 있는 경우에는 각 당사자는 계약을 해지할 수 있는데, 그 해지 사유가 누구의 사정에도 속하지 아니하는 경우 위 해지로 인하여 발생하는 추가비용은 여행주최자가 부담한다.","ox":"X","m":"③","c":"A","tp":"여행계약"},{"y":2016,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2016_22-04-4","t":"여행자는 약정한 시기에 대금을 지급하여야 하며, 그 시기의 약정이 없으면 관습에 따르고, 관습이 없으면 여행의 종료 후 지체 없이 지급하여야 한다.","ox":"O","m":"④","c":"A","tp":"여행계약"},{"y":2016,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2016_22-04-5","t":"여행자는 여행에 중대한 하자가 있는 경우에 그 시정이 이루어지지 아니하거나 계약의 내용에 따른 이행을 기대할 수 없는 경우에는 계약을 해지할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"여행계약"},{"y":2016,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2016_22-23-1","t":"여러 사람이 공동임대인으로서 임차인과 하나의 임대차계약을 체결한 경우, 공동임대인 전원의 해지의 의사표시에 따라 임대차계약 전부를 해지하여야 한다.","ox":"O","m":"①","c":"A","tp":"해제 또는 해지"},{"y":2016,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2016_22-23-2","t":"매매계약이 합의해제됨으로써 매수인에게 이전되었던 소유권은 당연히 매도인에게 복귀하는 것이므로 합의해제에 따른 매도인의 원상회복 청구권은 소유권에 기한 물권적 청구권이라 할 것이고, 따라서 이는 소멸시효의 대상이 아니라고 할 것이다.","ox":"O","m":"②","c":"A","tp":"해제 또는 해지"},{"y":2016,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2016_22-23-3","t":"채무불이행을 이유로 계약을 해제하려면, 당해 채무가 계약의 목적 달성에 있어 필요불가결하고 이를 이행하지 아니하면 계약의 목적이 달성되지 아니하여 채권자가 그 계약을 체결하지 아니하였을 것이라고 여겨질 정도의 주된 채무이어야 한다.","ox":"O","m":"③","c":"A","tp":"해제 또는 해지"},{"y":2016,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2016_22-23-4","t":"국토이용관리법상 토지거래허가구역 내에 있는 토지에 관하여 소유권 등 권리를 이전 또는 설정하는 내용의 거래계약은 관할 시장ㆍ군수 등의 허가를 받기까지는 유동적 무효의 상태에 있다고 볼 것이므로, 그러한 거래계약의 당사자로서는 허가받기 전의 상태에서 상대방의 거래계약상 채무불이행을 이유로 거래계약을 해제할 수 없다.","ox":"O","m":"④","c":"A","tp":"해제 또는 해지"},{"y":2016,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2016_22-23-5","t":"매도인이 미리 이행하지 아니할 의사를 명백히 표시한 경우라도 매수인은 소유권이전등기의무 이행기일에 잔대금의 이행제공을 하여야 매매계약을 해제할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"해제 또는 해지"},{"y":2016,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2016_22-25-1","t":"민법상의 위임계약은 그것이 유상계약이든 무상계약이든 당사자 쌍방의 특별한 대인적 신뢰관계를 기초로 하는 위임계약의 본질상 각 당사자는 언제든지 이를 해지할 수 있고 그로 말미암아 상대방이 손해를 입는 일이 있어도 그것을 배상할 의무를 부담하지 않는 것이 원칙이다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2016_22-25-2","t":"상대방이 불리한 시기에 해지한 때에는 그 해지가 부득이한 사유에 의한 것이 아닌 한 그로 인한 손해를 배상하여야 하고, 그 배상의 범위는 위임이 해지되었다는 사실로부터 생기는 손해이다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2016_22-25-3","t":"위임계약의 일방 당사자가 타방 당사자의 채무불이행을 이유로 위임계약을 해지한다는 의사표시를 하였으나 실제로는 채무불이행을 이유로 한 계약 해지의 요건을 갖추지 못한 경우라도, 특별한 사정이 없는 한 위 의사표시에는 임의해지로서의 효력이 인정된다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2016_22-25-4","t":"수임인이 위임받은 사무를 처리하던 중 사무처리를 완료하지 못한 상태에서 위임계약을 해지함으로써 위임인이 그 사무처리의 완료에 따른 성과를 이전받거나 이익을 얻지 못하게 되었다 하더라도, 별도로 특약을 하는 등 특별한 사정이 없는 한 수임인이 사무처리를 완료하기 전에 위임계약을 해지한 것만으로 위임인에게 불리한 시기에 해지한 것이라고 볼 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2016_22-25-5","t":"민법 제684조 제1항은 ‘수임인은 위임사무의 처리로 인하여 받은 금전 기타의 물건 및 그 수취한 과실을 위임인에게 인도하여야 한다.’라고 규정하고 있는바, 위 조항에서 말하는 ‘위임사무의 처리로 인하여 받은 금전 기타 물건’에는 수임인이 위임사무의 처리와 관련하여 취득한 금전 기타 물건으로서 이를 수임인에게 그대로 보유하게 하는 것이 위임의 신임관계를 해한다고 사회통념상 생각할 수 있는 것도 포함된다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2016_22-30-1","t":"건물의 소유를 목적으로 한 토지임대차계약의 기간이 만료됨에 따라 지상건물 소유자가 임대인에 대하여 행사하는 매수청구권은 매수청구의 대상이 되는 건물에 근저당권이 설정되어 있는 경우에도 인정된다.","ox":"O","m":"①","c":"A","tp":"민법상 임대차"},{"y":2016,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2016_22-30-2","t":"임차인의 비용상환청구권, 지상물매수청구권에 관한 민법의 규정은 강행규정이다.","ox":"X","m":"②","c":"A","tp":"민법상 임대차"},{"y":2016,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2016_22-30-3","t":"건물의 소유를 목적으로 하는 토지임차인이 그 지상건물을 등기하기 전에 제3자가 그 토지에 관하여 물권취득의 등기를 한 때에는 임차인이 그 지상건물을 등기하더라도 그 제3자에 대하여 임대차의 효력이 생기지 아니한다.","ox":"O","m":"③","c":"A","tp":"민법상 임대차"},{"y":2016,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2016_22-30-4","t":"甲이 대지와 건물의 소유자였던 乙로부터 대지와 건물을 임차하였는데 그 후 甲이 그 건물을 강제경매절차에서 경락받아 그 대지에 관한 위 임차권은 등기하지 아니한 채 그 건물에 관하여 甲 명의의 소유권이전등기를 경료하였다면, 甲은 대지에 관하여 소유권이전등기를 경료받은 제3자에 대하여 그 대지에 관한 임차권으로 대항할 수 없다.","ox":"O","m":"④","c":"A","tp":"민법상 임대차"},{"y":2016,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2016_22-30-5","t":"건물에 대한 저당권이 실행되어 경락인이 건물의 소유권을 취득한 때에는 특별한 다른 사정이 없는 한 그에 수반하여 그 건물의 소유를 목적으로 한 토지의 임차권도 그 건물의 소유권과 함께 경락인에게 이전된다.","ox":"O","m":"⑤","c":"A","tp":"민법상 임대차"},{"y":2016,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2016_22-39-1","t":"공사도급계약상 도급인의 지체상금채권과 수급인의 공사대금채권은 특별한 사정이 없는 한 동시이행의 관계에 있다고 할 수 없다.","ox":"O","m":"①","c":"A","tp":"민법상 도급 및 조합"},{"y":2016,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2016_22-39-2","t":"건물신축 도급계약에서 수급인이 공사를 완성하였다고 하더라도, 신축된 건물에 하자가 있고 그 하자 및 손해에 상응하는 금액이 공사잔대금액 이상이어서, 도급인이 수급인에 대한 하자보수청구권 내지 하자보수에 갈음한 손해배상채권 등에 기하여 수급인의 공사잔대금 채권 전부에 대하여 동시이행의 항변을 한 때에는, 공사잔대금 채권의 변제기가 도래하지 아니한 경우와 마찬가지로 수급인은 도급인에 대하여 하자보수의무나 하자보수에 갈음한 손해배상의무 등에 관한 이행의 제공을 하지 아니한 이상 공사잔대금 채권에 기한 유치권을 행사할 수 없다.","ox":"O","m":"②","c":"A","tp":"민법상 도급 및 조합"},{"y":2016,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2016_22-39-3","t":"수급인의 담보책임에 기한 하자보수에 갈음하는 손해배상청구권에 대하여는 민법 제670조 또는 제671조의 제척기간이 적용되고, 이는 법률관계의 조속한 안정을 도모하고자 하는 데에 그 취지가 있다. 그런데 이러한 도급인의 손해배상청구권에 대하여는 그 권리의 내용ㆍ성질 및 취지에 비추어 민법 제162조 제1항의 채권 소멸시효의 규정 또는 그 도급계약이 상행위에 해당하는 경우에는 상법 제64조의 상사시효의 규정이 적용된다고 할 것이고, 민법 제670조 또는 제671조의 제척기간 규정으로 인하여 위 각 소멸시효 규정의 적용이 배제된다고 볼 수 없다.","ox":"O","m":"③","c":"A","tp":"민법상 도급 및 조합"},{"y":2016,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2016_22-39-4","t":"민법상 조합의 채권은 조합원 전원에게 합유적으로 귀속하는 것이어서 특별한 사정이 없는 한 조합원 중 1인에 대한 채권으로써 그 조합원 개인을 집행채무자로 하여 조합의 채권에 대하여 강제집행을 할 수 없고, 조합 업무를 집행할 권한을 수여받은 업무집행 조합원은 조합재산에 관하여 조합원으로부터 임의적 소송신탁을 받아 자기 이름으로 소송을 수행할 수 없다.","ox":"X","m":"④","c":"A","tp":"민법상 도급 및 조합"},{"y":2016,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2016_22-39-5","t":"민법상 조합인 공동수급체가 경쟁입찰에 참가하였다가 다른 경쟁업체가 낙찰자로 선정된 경우, 그 공동수급체의 구성원 중 1인이 그 낙찰자 선정이 무효임을 주장하며 무효확인의 소를 제기하는 것은 그 공동수급체가 경쟁입찰과 관련하여 갖는 법적 지위 내지 법률상 보호받는 이익이 침해될 우려가 있어 그 현상을 유지하기 위하여 하는 소송행위이므로 이는 합유재산의 보존행위에 해당한다.","ox":"O","m":"⑤","c":"A","tp":"민법상 도급 및 조합"},{"y":2016,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2016_22-40-1","t":"소비대차는 당사자 일방이 금전 기타 대체물의 소유권을 상대방에게 이전할 것을 약정하고 상대방은 그와 같은 종류, 품질 및 수량으로 반환할 것을 약정함으로써 그 효력이 생기는바, 일단 소비대차의 효력이 발생한 이후에는 대주가 목적물을 차주에게 인도하기 전에 당사자 일방이 파산선고를 받았다는 이유만으로 그 소비대차가 효력을 잃지는 않는다.","ox":"X","m":"①","c":"A","tp":"소비대차 및 준소비대차"},{"y":2016,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2016_22-40-2","t":"민법상 소비대차는 이른바 낙성계약이므로, 차주가 현실로 금전 등을 수수하거나 현실의 수수가 있은 것과 같은 경제적 이익을 취득하여야만 소비대차가 성립하는 것은 아니다.","ox":"O","m":"②","c":"A","tp":"소비대차 및 준소비대차"},{"y":2016,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2016_22-40-3","t":"당사자 쌍방이 소비대차에 의하지 아니하고 금전 기타의 대체물을 지급할 의무가 있는 경우에 당사자가 그 목적물을 소비대차의 목적으로 할 것을 약정한 때에는 소비대차의 효력이 생긴다.","ox":"O","m":"③","c":"A","tp":"소비대차 및 준소비대차"},{"y":2016,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2016_22-40-4","t":"금전 소비대차계약과 함께 이자의 약정을 하는 경우, 그 이자 약정이 대주가 그의 우월한 지위를 이용하여 부당한 이득을 얻고 차주에게는 과도한 반대급부 또는 기타의 부당한 부담을 지우는 것이어서 선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위로서 무효라고 보기 위해서는, 양쪽 당사자 사이의 경제력의 차이로 인하여 그 이율이 당시의 경제적ㆍ사회적 여건에 비추어 사회통념상 허용되는 한도를 초과하여 현저하게 고율로 정하여졌다는 사정이 인정되어야 한다.","ox":"O","m":"④","c":"A","tp":"소비대차 및 준소비대차"},{"y":2016,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2016_22-40-5","t":"이자있는 소비대차는 차주가 목적물의 인도를 받은 때로부터 이자를 계산하여야 하며 차주가 그 책임 있는 사유로 수령을 지체할 때에는 대주가 이행을 제공한 때로부터 이자를 계산하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"소비대차 및 준소비대차"},{"y":2017,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2017_23-14-1","t":"근저당권 실행을 위한 경매가 무효로 되어 채권자(근저당권자)가 채무자를 대위하여 매수인에 대한 소유권이전등기말소청구권을 행사하는 경우, 채권자(근저당권자)가 매수인에 대하여 부담하는 배당금반환채무와 매수인이 채무자에 대하여 부담하는 소유권이전등기말소의무는 서로 동시이행관계에 있다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2017_23-14-2","t":"매도인의 매매계약상의 소유권이전등기의무가 이행불능이 되어 이를 이유로 매매계약을 해제함에 있어서는 상대방의 잔대금지급의무가 매도인의 소유권이전등기의무와 동시이행관계에 있다고 하더라도 그 이행의 제공을 필요로 하는 것이 아니다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2017_23-14-3","t":"지입계약의 종료에 따라 지입회사가 지입차주에 대하여 부담하는 소유권이전등록절차이행의무와 지입계약이 유지됨으로 인하여 지입회사에게 부과된 세금이나 지입차주의 차량운행과 관련하여 발생한 과태료 등을 정산하여 지급하여야 할 지입차주의 지입회사에 대한 의무는 쌍무계약에 있어서 고유의 대가관계에 있는 것은 아니라고 하더라도 형평의 원칙에 비추어 서로 동시이행관계에 있다고 봄이 상당하다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2017_23-14-4","t":"공사도급계약상 도급인의 지체상금채권과 수급인의 공사대금채권은 특별한 사정이 없는 한 동시이행의 관계에 있다고 할 수 없다.","ox":"O","m":"④","c":"A","tp":"동시이행관계"},{"y":2017,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2017_23-14-5","t":"주택임대차보호법 제3조의3 규정에 의한 임차권등기는 이미 임대차계약이 종료하였음에도 임대인이 그 보증금을 반환하지 않는 상태에서 경료되게 되므로, 이미 사실상 이행지체에 빠진 임대인의 임대차보증금의 반환의무와 그에 대응하는 임차인의 권리를 보전하기 위하여 새로이 경료하는 임차권등기에 대한 임차인의 말소의무를 동시이행관계에 있는 것으로 해석할 것은 아니다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2017_23-16-1","t":"근로자가 사직원의 제출방법에 의하여 근로계약관계의 합의해지를 청약하고 이에 대하여 사용자가 승낙함으로써 당해 근로관계를 종료시키게 되는 경우 근로자는 사직원의 제출에 따른 사용자의 승낙의사가 형성되어 확정적으로 근로계약 종료의 효과가 발생하기 전에는 사직의 의사표시를 자유로이 철회할 수 있다.","ox":"O","m":"①","c":"A","tp":"계약의 성립"},{"y":2017,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2017_23-16-2","t":"매매계약 당사자 중 매도인이 매수인에게 매매계약의 합의해제를 청약하였다고 할지라도, 매수인이 그 청약에 대하여 조건을 붙이거나 변경을 가하여 승낙한 때에는 민법 제534조의 규정에 비추어 그 청약의 거절과 동시에 새로 청약한 것으로 보게 되는 것이고, 그로 인하여 종전의 매도인의 청약은 실효된다.","ox":"O","m":"②","c":"A","tp":"계약의 성립"},{"y":2017,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2017_23-16-3","t":"예금계약은 예금자가 예금의 의사를 표시하면서 금융기관에 돈을 제공하고 금융기관이 그 의사에 따라 그 돈을 받아 확인을 하면 그로써 성립하며, 금융기관의 직원이 그 받은 돈을 금융기관에 입금하지 아니하고 이를 횡령하였다고 하더라도 예금계약의 성립에는 지장이 없다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2017_23-16-4","t":"승낙의 기간을 정한 계약의 청약은 청약자가 그 기간 내에 승낙의 통지를 받지 못한 때에는 그 효력을 잃으나, 승낙의 기간을 정하지 아니한 계약의 청약은 청약자가 상당한 기간 내에 승낙의 통지를 받지 못하더라도 그 효력을 잃지 않는다.","ox":"X","m":"④","c":"A","tp":"계약의 성립"},{"y":2017,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2017_23-16-5","t":"격지자간의 계약은 승낙의 통지를 발송한 때에 성립하고, 당사자간에 동일한 내용의 청약이 상호교차된 경우에는 양청약이 상대방에게 도달한 때에 계약이 성립한다.","ox":"O","m":"⑤","c":"A","tp":"계약의 성립"},{"y":2017,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2017_23-18-1","t":"매매당사자 사이에 수수된 계약금에 대하여 매수인이 위약하였을 때에는 이를 무효로 하고 매도인이 위약하였을 때에는 그 배액을 상환할 뜻의 약정이 있는 경우에는 특별한 사정이 없는 한 그 계약금은 민법 제398조 제1항 소정의 손해배상액의 예정의 성질을 가질 뿐 아니라 민법 제565조 소정의 해약금의 성질도 가진 것으로 볼 것이다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2017_23-18-2","t":"매매당사자 간에 계약금을 수수하고 계약해제권을 유보한 경우에 매도인이 계약금의 배액을 상환하고 계약을 해제하려면 계약해제 의사표시 이외에 계약금 배액의 이행의 제공이 있으면 족하고 상대방이 이를 수령하지 아니한다 하여 이를 공탁하여야 유효한 것은 아니다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2017_23-18-3","t":"매수인이 약정한 계약금의 일부만을 지급한 경우 계약금을 전부 지급하기 전까지는 매도인은 지급받은 계약금의 배액을 상환하고 매매계약을 해제할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2017_23-18-4","t":"민법 제565조 제1항은 ‘매매의 당사자 일방이 계약당시에 금전 기타 물건을 계약금, 보증금 등의 명목으로 상대방에게 교부한 때에는 당사자간에 다른 약정이 없는 한 당사자의 일방이 이행에 착수할 때까지 교부자는 이를 포기하고 수령자는 그 배액을 상환하여 매매계약을 해제할 수 있다’고 규정하고 있다. 그러나 계약금계약은 금전 기타 유가물의 교부를 요건으로 하므로 단지 계약금을 지급하기로 약정만 한 단계에서는 아직 계약금으로서의 효력, 즉 위 민법 규정에 의해 계약해제를 할 수 있는 권리는 발생하지 않는다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2017_23-18-5","t":"민법 제565조 제1항 ‘매매의 당사자 일방이 계약당시에 금전 기타 물건을 계약금, 보증금 등의 명목으로 상대방에게 교부한 때에는 당사자 간에 다른 약정이 없는 한 당사자의 일방이 이행에 착수할 때까지 교부자는 이를 포기하고 수령자는 그 배액을 상환하여 매매계약을 해제할 수 있다’에서 말하는 당사자의 일방이라는 것은 매매 쌍방 중 어느 일방을 지칭하는 것이고, 상대방이라 국한하여 해석할 것이 아니다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2017_23-20-1","t":"민법 제548조 제2항은 계약해제로 인한 원상회복의무의 이행으로서 반환하는 금전에는 그 받은 날로부터 이자를 가산하여야 한다고 규정하고 있는바, 위 이자의 반환은 반환의무의 이행지체로 인한 손해배상의 성질을 가지는 것이지, 일반적인 부당이득반환의 성질을 갖는 것이 아니다.","ox":"X","m":"①","c":"A","tp":"계약의 해제"},{"y":2017,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2017_23-20-2","t":"매수인이 중도금 지급채무를 불이행하여 매도인이 그 이행을 최고한 경우, 그 최고가 약정한 금액보다 현저하게 과다하고 청구한 금액을 제공하지 않으면 그것을 수령하지 않을 것이라는 매도인의 의사가 분명하다면 위와 같은 최고에 터잡은 매도인의 계약해제는 효력이 없다.","ox":"O","m":"②","c":"A","tp":"계약의 해제"},{"y":2017,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2017_23-20-3","t":"부수적 채무의 불이행을 원인으로 계약을 해제할 수 있는 것은 그 불이행으로 인하여 채권자가 계약의 목적을 달성할 수 없는 경우 또는 특별한 약정이 있는 경우에 한정된다.","ox":"O","m":"③","c":"A","tp":"계약의 해제"},{"y":2017,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2017_23-20-4","t":"부동산 매매계약에 있어서 매수인이 잔대금 지급기일까지 그 대금을 지급하지 못하면 그 계약이 자동적으로 해제된다는 취지의 약정이 있더라도 특별한 사정이 없는 한 매도인이 이행의 제공을 하여 매수인으로 하여금 이행지체에 빠지게 하였을 때에 비로소 자동적으로 매매계약이 해제된다고 보아야 한다.","ox":"O","m":"④","c":"A","tp":"계약의 해제"},{"y":2017,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2017_23-20-5","t":"계약해제시 원칙적으로 손해배상의 범위는 이행이익의 배상이지만, 그에 갈음하여 신뢰이익의 배상을 청구할 수도 있다. 이 경우에 신뢰이익의 배상은 통상손해와 특별손해로 구별되며, 과잉배상금지 원칙에 비추어 이행이익의 범위를 초과할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"계약의 해제"},{"y":2017,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2017_23-21-1","t":"매매의 목적이 된 재산권 전부가 타인에게 속하고 매도인이 이를 취득하여 매수인에게 이전할 수 없는 경우, 선의의 매수인은 매도인의 귀책사유를 불문하고 손해배상을 청구할 수 있다.","ox":"O","m":"①","c":"A","tp":"매도인의 담보책임"},{"y":2017,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2017_23-21-2","t":"건물 및 그 대지가 목적물인 매매계약이 이행된 후 건물의 일부가 경계를 침범하여 이웃 토지 위에 건립되어 있는 사실이 밝혀져 매수인이 그 건물의 일부를 철거해야 했다면, 민법 제572조가 유추적용되어 매수인은 권리의 일부가 타인에 속한 경우에 관한 담보책임을 매도인에게 물을 수 있다.","ox":"O","m":"②","c":"A","tp":"매도인의 담보책임"},{"y":2017,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2017_23-21-3","t":"건축을 목적으로 매매된 토지에 대하여 건축허가를 받을 수 없어 건축이 불가능한 경우 이는 매매목적물의 하자가 아닌 권리의 하자로 보아야 하고, 이러한 하자의 존부는 매매목적물인 토지에 대한 소유권이전 시점을 기준으로 판단하여야 한다.","ox":"X","m":"③","c":"A","tp":"매도인의 담보책임"},{"y":2017,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2017_23-21-4","t":"목적물이 일정한 면적(수량)을 가지고 있다는 데 주안을 두고 대금도 면적을 기준으로 하여 정하여지는 아파트분양계약은 이른바 수량을 지정한 매매에 해당한다.","ox":"O","m":"④","c":"A","tp":"매도인의 담보책임"},{"y":2017,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2017_23-21-5","t":"가등기의 목적이 된 부동산을 매수한 사람이 그 뒤 가등기에 기한 본등기가 경료됨으로서 그 부동산의 소유권을 상실하게 된 때에는 저당권 또는 전세권의 행사로 인하여 매수인이 소유권을 상실한 경우에 관한 민법 제576조의 규정이 준용된다.","ox":"O","m":"⑤","c":"A","tp":"매도인의 담보책임"},{"y":2017,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2017_23-22-1","t":"부동산 매수인의 의뢰로 부동산 거래관계에 관여하고 그에 따른 등기신청서류의 작성과 등기신청을 대리한 법무사는 그 등기신청과 관련된 한도 내에서는 등기부를 열람하여 등기의 목적과 관련된 권리관계를 확인하고, 이를 의뢰인에게 설명ㆍ조언할 의무가 있고, 형식적으로 소유권이전등기신청에 관한 서류를 작성하여 제출한 것만으로는 수임인으로서의 의무를 다하였다고 할 수 없다.","ox":"O","m":"①","c":"A","tp":"민법상 위임"},{"y":2017,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2017_23-22-2","t":"무상위임의 경우 수임인은 위임의 본지에 따라 자신의 재산과 동일한 주의로 위임사무를 처리하여야 한다.","ox":"X","m":"②","c":"A","tp":"민법상 위임"},{"y":2017,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2017_23-22-3","t":"등기권리자와 등기의무자 쌍방으로부터 등기절차의 위임을 받고 그 절차에 필요한 서류를 교부받은 법무사는 절차가 끝나기 전에 등기의무자로부터 등기신청을 보류해 달라는 요청이 있었다 해도 등기권리자에 대한 관계에 있어서는 그 사람의 동의가 있는 등 특별한 사정이 없는 한 그 요청을 거부하거나 최소한 그 사실을 위임인인 등기권리자에게 알려주어야 할 위임계약상의 의무가 있다.","ox":"O","m":"③","c":"A","tp":"민법상 위임"},{"y":2017,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2017_23-22-4","t":"위임계약의 각 당사자는 언제든지 위임계약을 해지할 수 있으므로, 일방 당사자가 타방 당사자의 채무불이행을 이유로 위임계약을 해지한다는 의사표시를 하였으나 실제로는 채무불이행을 이유로 한 계약 해지의 요건을 갖추지 못한 경우라도 특별한 사정이 없는 한 그 의사표시는 임의해지로서의 효력이 인정된다.","ox":"O","m":"④","c":"A","tp":"민법상 위임"},{"y":2017,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2017_23-22-5","t":"수임인이 위임사무의 처리에 관하여 필요비를 지출한 때에는 위임인에 대하여 지출한 날 이후의 이자를 청구할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"민법상 위임"},{"y":2017,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2017_23-23-1","t":"증여계약이 성립한 당시에는 서면이 작성되지 않았더라도 그후 계약이 존속하는 동안 서면을 작성한 때에는 처음부터 서면에 의한 증여로서 효력이 있다.","ox":"X","m":"①","c":"A","tp":"민법상 증여"},{"y":2017,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2017_23-23-2","t":"정기의 급여를 목적으로 한 증여는 증여자 또는 수증자의 사망으로 인하여 그 효력을 잃는다.","ox":"O","m":"②","c":"A","tp":"민법상 증여"},{"y":2017,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2017_23-23-3","t":"망은행위로 인한 증여계약의 해제 사유로서 민법 제556조 제1항 제2호(증여자에 대하여 부양의무 있는 경우에 이를 이행하지 아니하는 때)에 규정하고 있는 ‘부양의무’라 함은 민법 제974조 직계혈족 및 그 배우자 또는 생계를 같이 하는 친족간의 부양의무 뿐만 아니라 친족간이 아닌 당사자 사이의 약정에 의한 부양의무도 포함된다.","ox":"X","m":"③","c":"A","tp":"민법상 증여"},{"y":2017,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2017_23-23-4","t":"사인증여에 관하여는 유증에 관한 규정이 준용되므로, 포괄적 사인증여를 받은 자는 포괄적 유증을 받은 자와 마찬가지로 상속인과 동일한 권리의무가 있다.","ox":"X","m":"④","c":"A","tp":"민법상 증여"},{"y":2017,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2017_23-23-5","t":"서면에 의하지 않은 증여의 경우에 각 당사자는 이를 해제할 수 있으나 이미 이행된 경우에는 그러하지 않은 바, 서면에 의하지 않은 부동산 증여의 경우 아직 소유권이전등기를 마치지 않았으나 그 부동산을 인도하였다면 증여자는 계약을 해제할 수 없다.","ox":"X","m":"⑤","c":"A","tp":"민법상 증여"},{"y":2017,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2017_23-25-1","t":"건물의 소유를 목적으로 한 토지임대차에 있어서 임차인의 건물매수청구권은 매수청구의 대상이 되는 건물에 근저당권이 설정되어 있는 경우에도 인정되고, 그 매수가격을 정할 때 근저당권의 채권최고액이나 피담보채무액은 공제되어야 한다.","ox":"X","m":"①","c":"A","tp":"토지임대차 종료에 따른 임차인의 지상물매수청구권"},{"y":2017,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2017_23-25-2","t":"지상물매수청구권이 행사되면 임대인과 임차인 사이에서는 임차지상의 건물에 대하여 매수청구권 행사 당시의 건물시가를 대금으로 하는 매매계약이 체결된 것과 같은 효과가 발생하는 것이지, 임대인이 기존 건물의 철거비용을 포함하여 임차인이 임차지상의 건물을 신축하기 위하여 지출한 모든 비용을 보상할 의무를 부담하게 되는 것은 아니다.","ox":"O","m":"②","c":"A","tp":"토지임대차 종료에 따른 임차인의 지상물매수청구권"},{"y":2017,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2017_23-25-3","t":"건물의 소유를 목적으로 한 토지임대차에 있어서 임차인이 그 지상건물에 대하여 매수청구권을 행사한 후에도 건물의 점유ㆍ사용을 통하여 그 부지를 계속하여 점유ㆍ사용하는 경우 부당이득으로서 부지의 임료 상당액을 반환하여야 한다.","ox":"O","m":"③","c":"A","tp":"토지임대차 종료에 따른 임차인의 지상물매수청구권"},{"y":2017,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2017_23-25-4","t":"건물의 소유를 목적으로 하는 토지 임차인의 건물매수청구권 행사의 상대방은 원칙적으로 임차권 소멸 당시의 토지소유자인 임대인이고, 임대인이 임차권 소멸 당시에 이미 토지소유권을 상실한 경우에는 그에게 지상건물의 매수청구권을 행사할 수는 없으며, 이는 임대인이 임대차계약의 종료 전에 토지를 임의로 처분하였다 하여 달라지는 것은 아니다.","ox":"O","m":"④","c":"A","tp":"토지임대차 종료에 따른 임차인의 지상물매수청구권"},{"y":2017,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2017_23-25-5","t":"토지임대차 종료시 임대인의 건물철거와 그 대지인도 청구에는 건물매수대금 지급과 동시에 건물인도를 구하는 청구가 포함되어 있다고 볼 수 없다.","ox":"O","m":"⑤","c":"A","tp":"토지임대차 종료에 따른 임차인의 지상물매수청구권"},{"y":2017,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2017_23-26-1","t":"도급인의 수급인에 대한 하자의 보수, 손해배상의 청구 및 계약의 해제는 목적물의 인도를 받은 날로부터 1년 내에 하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2017_23-26-2","t":"공사도급계약에 따라 주고받는 선급금은 일반적으로 구체적인 기성고와 관련하여 지급되는 것이 아니라 전체 공사와 관련하여 지급되는 공사대금의 일부이다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2017_23-26-3","t":"도급인이 선급금을 지급한 후 도급계약이 해제되거나 해지된 경우에는 특별한 사정이 없는 한 별도의 상계 의사표시 없이 그때까지 기성고에 해당하는 공사대금 중 미지급액은 당연히 선급금으로 충당되고 공사대금이 남아 있으면 도급인은 그 금액에 한하여 지급의무가 있다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2017_23-26-4","t":"수급인이 완공기한 내에 공사를 완성하지 못한 채 완공기한을 넘겨 도급계약이 해제된 경우에 있어서 그 지체상금 발생의 시기는 완공기한 다음날이고, 종기는 수급인이 공사를 중단하거나 기타 해제사유가 있어 도급인이 실제로 해제ㆍ해지한 때이다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2017_23-26-5","t":"수급인이 일을 완성하기 전에는 도급인은 손해를 배상하고 계약을 해제할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2018_24-08-1","t":"계약당사자가 부담하는 각 채무가 쌍무계약에 있어 고유의 대가관계가 있는 채무가 아니라고 하더라도 구체적인 계약관계에서 각 당사자가 부담하는 채무에 관한 약정 내용에 따라 그것이 대가적 의미가 있어 이행상의 견련관계를 인정하여야 할 사정이 있는 경우에는 동시이행의 항변권을 인정할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2018_24-08-2","t":"주택임대차보호법 제3조의3 규정에 의한 임차권등기는 이미 임대차계약이 종료하였음에도 임대인이 그 보증금을 반환하지 않는 상태에서 경료되게 되므로, 이미 사실상 이행지체에 빠진 임대인의 임대차보증금의 반환의무와 그에 대응하는 임차인의 권리를 보전하기 위하여 새로이 경료하는 임차권등기에 대한 임차인의 말소의무를 동시이행관계에 있는 것으로 해석할 것은 아니다.","ox":"O","m":"②","c":"A","tp":"동시이행의 항변권"},{"y":2018,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2018_24-08-3","t":"쌍무계약의 당사자 일방이 먼저 한번 현실의 제공을 하고 상대방을 수령지체에 빠지게 하였다 하더라도 그 이행의 제공이 계속되지 않는 경우는 과거에 이행의 제공이 있었다는 사실만으로 상대방이 가지는 동시이행의 항변권이 소멸하는 것은 아니다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2018_24-08-4","t":"쌍무계약에서 쌍방의 채무가 동시이행관계에 있는 경우 일방의 채무의 이행기가 도래하더라도 상대방 채무의 이행제공이 있을 때까지는 그 채무를 이행하지 않아도 이행지체의 책임을 지지 않는 것이며, 이와 같은 효과는 이행지체의 책임이 없다고 주장하는 자가 동시이행의 항변권을 행사하여야만 발생하는 것이다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2018_24-08-5","t":"임대차계약이 해지된 후에 임대인이 잔존 임차보증금반환청구권을 전부받은 자에게 그 채무를 현실적으로 이행하였거나 그 채무이행을 제공하지 않은 이상, 임차인의 목적물에 대한 점유는 동시이행의 항변권에 기한 것이어서 불법점유라고 볼 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2018_24-13-1","t":"계약이 합의해제된 경우에는 그 해제시에 당사자 일방이 상대방에게 손해배상을 하기로 특약하거나 손해배상청구를 유보하는 의사표시를 하는 등 다른 사정이 없는 한 채무불이행으로 인한 손해배상을 청구할 수 없다.","ox":"O","m":"①","c":"A","tp":"계약의 해제"},{"y":2018,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2018_24-13-2","t":"이행지체를 이유로 계약을 해제함에 있어서 그 전제요건인 이행의 최고는 반드시 미리 일정기간을 명시하여 최고하여야 하는 것은 아니며 최고한 때로부터 상당한 기간이 경과하면 해제권이 발생한다.","ox":"O","m":"②","c":"A","tp":"계약의 해제"},{"y":2018,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2018_24-13-3","t":"계약상 채무자가 계약을 이행하지 아니할 의사를 명백히 표시한 경우라도 채권자는 신의성실의 원칙상 이행기 전에 이행의 최고 없이 채무자의 이행거절을 이유로 계약을 해제할 수는 없다.","ox":"X","m":"③","c":"A","tp":"계약의 해제"},{"y":2018,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2018_24-13-4","t":"매매계약에 있어서 매수인이 중도금을 약정한 일자에 지급하지 아니하면 그 계약을 무효로 한다는 특약이 있는 경우, 매수인이 약정한 대로 중도금을 지급하지 아니하면 그 불이행 자체로서 계약은 그 일자에 자동적으로 해제된 것으로 본다.","ox":"O","m":"④","c":"A","tp":"계약의 해제"},{"y":2018,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2018_24-13-5","t":"매수인이 잔대금 지급기일까지 그 대금을 지급하지 못하면 그 계약이 자동적으로 해제된다는 취지의 약정이 있더라도, 매도인이 잔대금 지급기일에 소유권이전등기의무에 관한 이행의 제공을 하여, 매수인으로 하여금 이행지체에 빠지게 하였을 때 비로소 자동적으로 계약이 해제된다고 보아야 한다.","ox":"O","m":"⑤","c":"A","tp":"계약의 해제"},{"y":2018,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2018_24-16-1","t":"증여자는 원칙적으로 증여의 목적인 물건 또는 권리의 하자나 흠결에 대하여 책임을 지지 않는다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2018_24-16-2","t":"민법 제614조는 “차주가 사망하거나 파산선고를 받은 때에는 대주는 계약을 해지할 수 있다.”라고 규정하고 있다. 그러나 일반적으로 건물 소유를 목적으로 하는 토지 사용대차의 경우, 당해 토지를 사용수익할 필요는 그 지상 건물을 사용수익할 필요가 있는 한 그대로 존속하고 이는 특별한 사정이 없는 한 차주 본인이 사망하더라도 당연히 상실되는 것이 아니어서, 그로 인하여 곧바로 계약의 목적을 달성하게 되는 것은 아니라고 봄이 통상의 의사해석에도 합치된다. 이러한 경우에는 민법 제614조 규정에도 불구하고 대주가 차주의 사망사실만을 이유로 사용대차계약을 해지할 수는 없다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2018_24-16-3","t":"부동산교환계약에 있어 목적 부동산에 설정된 담보권의 피담보채무를 인수하기로 하는 약정이 행하여진 경우, 그 일방(A)이 상대방(B)의 채무인수의무 불이행으로 말미암아 그 채무를 대신 변제하였다면, 그로 인한 B의 손해배상채무와 A의 소유권이전등기의무는 동시이행관계에 있다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2018_24-16-4","t":"기존 채권·채무의 당사자가 목적물을 소비대차 목적으로 할 것을 약정한 경우, 약정을 경개로 볼 것인가 준소비대차로 볼 것인가는 일차적으로 당사자의 의사에 따라 결정된다. 만약 당사자의 의사가 명백하지 않을 때에는 의사해석 문제이나, 특별한 사정이 없는 한 준소비대차로 보아야 한다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2018_24-16-5","t":"상대부담 있는 증여에 대하여는 민법 제561조에 의하여 쌍무계약에 관한 규정이 준용되어 부담의무 있는 상대방이 자신의 의무를 이행하지 아니할 때에는 증여자는 그 계약을 해제할 수 있으나, 이 경우에도 민법 제558조가 적용되므로 이미 이행된 부분에 대하여는 영향을 미치지 않는다.","ox":"X","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2018_24-22-1","t":"쌍무계약에서 계약 체결 후에 당사자 쌍방의 귀책사유 없이 채무의 이행이 불가능하게 된 경우, 당사자 일방이 이미 이행한 급부는 법률상 원인 없는 급부가 되어 상대방에게 부당이득의 법리에 따라 반환청구할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2018_24-22-2","t":"쌍무계약의 당사자 일방의 채무가 채권자의 수령지체 중에 당사자 쌍방의 책임 없는 사유로 이행할 수 없게 된 때에는, 채무자는 상대방의 이행을 청구할 수 있다. 다만, 채무자가 자기의 채무를 면함으로써 이익을 얻은 때에는 이를 채권자에게 상환하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2018_24-22-3","t":"민법 제400조에 정한 채권자지체가 성립하기 위해서는 민법 제460조 소정의 채무자의 변제 제공이 있어야 하지만, 채권자가 변제를 받지 아니할 의사가 확고한 경우(이른바 채권자의 영구적 불수령)에는 구두의 제공조차 필요 없다. 따라서 쌍무계약에서 당사자 일방이 이른바 영구적 불수령 의사를 표시한 이상, 상대방이 현실 제공이나 구두 제공을 하지 않더라도 민법 제538조 제1항 제2문에 정한 '채권자의 수령지체 중에 당사자 쌍방의 책임 없는 사유로 이행할 수 없게 된 때'에 해당할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2018_24-22-4","t":"매매계약이 무효로 되는 때에는 매도인이 악의의 수익자인 경우 특별한 사정이 없는 한 매도인은 반환할 매매대금에 대하여 민법이 정한 연 5%의 법정이율에 의한 이자를 붙여 반환하여야 한다. 그리고 이는 매도인의 매매대금 반환의무와 매수인의 소유권이전등기 말소등기절차 이행의무가 동시이행 관계에 있는 경우에도 마찬가지이다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2018_24-22-5","t":"제3자를 위한 계약관계에서 낙약자와 요약자 사이의 법률관계(이른바 기본관계)를 이루는 계약이 무효이거나 해제된 경우, 특별한 사정이 없는 한 낙약자가 이미 제3자에게 급부한 것이 있더라도 낙약자는 계약해제 등에 기한 원상회복 또는 부당이득을 원인으로 제3자를 상대로 그 반환을 구할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2018_24-25-1","t":"업무집행 조합원의 배임행위로 조합이 손해를 입은 경우 그로 인하여 손해를 입은 주체는 조합이다. 그러므로 그로 인하여 조합의 목적을 달성할 수 없게 되었다고 하더라도 조합원으로서는 조합관계를 벗어난 개인 지위에서 그 손해의 배상을 구할 수 없는 것이 원칙이다.","ox":"O","m":"①","c":"A","tp":"민법상 조합"},{"y":2018,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2018_24-25-2","t":"2인 조합에서 조합원 1인이 탈퇴하면 조합관계가 종료되고, 특별한 사정이 없는 한 조합원들은 청산 절차를 거쳐 잔여재산을 분배받는다.","ox":"X","m":"②","c":"A","tp":"민법상 조합"},{"y":2018,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2018_24-25-3","t":"조합이 해산하였으나 조합 잔무로서 처리할 일이 없고 잔여재산 분배만이 남아 있을 때에는, 특별한 사정이 없는 한 청산절차를 밟을 필요가 없다.","ox":"O","m":"③","c":"A","tp":"민법상 조합"},{"y":2018,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2018_24-25-4","t":"조합계약으로 업무집행자를 정하지 아니한 경우에는 조합원의 3분의 2 이상의 찬성으로써 이를 선임하고, 업무집행자인 조합원은 정당한 사유 없이 사임하지 못하며, 다른 조합원의 일치가 아니면 해임하지 못한다.","ox":"O","m":"④","c":"A","tp":"민법상 조합"},{"y":2018,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2018_24-25-5","t":"2인 조합에서 조합원 A가 약정에 따른 출자금을 출자한 후, 당사자 간의 불화대립으로 곧바로 동업관계가 결렬되어 그 후 A가 동업관계에서 전적으로 배제된 채 나머지 조합원에 의하여 당초의 업무가 처리되어 온 경우, A는 부득이한 사유가 있음을 이유로 조합 해산청구를 할 수 있고, 탈퇴로 인한 계산으로서 자기가 출자한 금원의 반환을 구할 수도 있다.","ox":"O","m":"⑤","c":"A","tp":"민법상 조합"},{"y":2019,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2019_25-04","t":"다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"다음 설명 중 가장 옳지 않은 것은?","d":"","o":["도급인은 완성된 목적물의 하자로 인하여 계약의 목적을 달성할 수 없는 때에는 계약을 해제할 수 있다. 그러나 건물 기타 토지의 공작물에 대하여는 그러하지 아니하다.","도급인과 수급인 사이에는 일반적으로 지휘․감독의 관계가 없으므로, 도급인은 수급인이나 그의 피용자의 불법행위에 대하여 사용자로서의 배상책임이 없지만, 노무도급의 경우에는 비록 도급인이라도 사용자로서의 배상책임이 있다.","지체상금에 관한 약정은 수급인이 그와 같은 일의 완성을 지체한 데 대한 손해배상액의 예정이므로, 법원은 제반 사정을 참작하여 약정에 따라 산정된 지체상금액이 일반 사회인이 납득할 수 있는 범위를 넘어 부당하게 과다하다고 인정하는 때에는 이를 적당히 감액할 수 있다.","위약금이 위약벌로 해석되기 위해서는 특별한 사정이 주장ㆍ입증되어야 하는데, 당사자 사이의 도급계약서에 계약보증금과는 별도로 지체상금에 관한 규정이 마련되어 있는 경우, 계약보증금은 위약벌로서의 성격을 갖는다고 보는 것이 당사자의 의사에 부합한다.","건축도급계약에서 미완성부분이 있는 경우 공사가 상당한 정도로 진척되어 그 원상회복이 중대한 사회적, 경제적 손실을 초래하고 완성된 부분이 도급인에게 이익이 되는 경우, 수급인의 채무불이행을 이유로 도급인이 그 도급계약을 해제한 때에는 그 미완성 부분에 대해서만 도급계약이 실효된다고 보아야 한다. 따라서 이 경우의 수급인은 해제한 때의 상태 그대로 건물을 도급인에게 인도하고 도급인은 그 건물의 완성도 등을 참작하여 상당한 보수를 지급하여야 한다. 22-12"],"a":4}},{"y":2019,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2019_25-07-1","t":"甲은 임의경매절차에서 최고가매수신고인의 지위에 있던 乙과 주택임대차계약을 체결한 후 주택을 인도받아 전입신고를 마치고 임대차계약서에 확정일자를 받았는데, 다음 날 乙은 매각대금을 완납하고 丙 주식회사에 근저당권설정등기를 마쳐주었다. 이 경우 甲은 주택임대차보호법 제3조의2 제2항에서 정한 우선변제권을 취득하였다고 볼 수 없다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2019_25-07-2","t":"아파트 수분양자가 분양자로부터 열쇠를 교부받아 임차인을 입주케 하고 임차인이 주택임대차보호법상의 대항력을 갖춘 경우, 다른 사정으로 분양계약이 해제되어 임대인인 수분양자가 주택의 소유권을 취득하지 못하였다고 하더라도 임차인은 아파트 소유자인 분양자에 대하여 임차권으로 대항할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2019_25-07-3","t":"甲이 丙 회사 소유 임대아파트의 임차인 乙로부터 아파트를 임차하여 전입신고를 마치고 거주하던 중, 乙이 丙 회사로부터 위 아파트를 분양받아 자기 명의로 소유권이전등기를 경료하고 근저당권을 설정하였는데, 그 후 위 근저당권이 실행되어 그 경매절차에서 丁이 위 아파트를 매수하여 그 매각대금을 완납하였다. 이 경우 甲은 乙 명의의 소유권이전등기가 경료되는 즉시 임차권의 대항력을 취득하였으므로, 위 임차권으로써 丁에게 대항할 수 있다.","ox":"O","m":"③","c":"A","tp":"주택임대차"},{"y":2019,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2019_25-07-4","t":"주택임대차보호법상 대항력을 갖춘 임차인의 임대차보증금반환채권이 가압류된 상태에서 임대주택이 양도되면 양수인은 채권가압류의 제3채무자의 지위도 승계하고, 가압류권자 또한 임대주택의 양도인이 아니라 양수인에 대하여만 위 가압류의 효력을 주장할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2019_25-07-5","t":"甲은 미등기 다세대주택의 소액임차인으로서 대항요건과 확정일자를 갖추었는데, 그 후 위 미등기 다세대주택의 대지에 대하여 그 명의로 근저당권설정등기를 마친 乙이 위 근저당권을 실행하여 임의경매절차가 진행되었다. 이 경우 甲은 위 대지의 환가대금에 대하여 저당권자에 우선하여 변제받을 수 없다.","ox":"X","m":"⑤","c":"A","tp":"주택임대차"},{"y":2019,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2019_25-10-1","t":"요약자와 낙약자 사이의 매매계약이 무효인 경우, 매수인인 낙약자는 수익자에게 지급한 매매대금을 부당이득이라는 이유로 수익자를 상대로 그 반환을 청구할 수 있다.","ox":"X","m":"①","c":"A","tp":"제3자를 위한 계약"},{"y":2019,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2019_25-10-2","t":"요약자와 수익자 사이의 법률관계가 무효임을 이유로 요약자는 낙약자에게 부담하는 채무의 이행을 거부할 수 있다.","ox":"X","m":"②","c":"A","tp":"제3자를 위한 계약"},{"y":2019,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2019_25-10-3","t":"채무자와 인수인의 계약으로 체결되는 병존적 채무인수는 채권자로 하여금 인수인에 대하여 새로운 권리를 취득하게 하는 것으로, 그 성격은 제3자를 위한 계약이 아니라 이행인수로 보아야 한다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2019_25-10-4","t":"수익자가 수익의 의사표시를 한 이후에 요약자가 낙약자의 채무불이행을 이유로 계약을 해제한 경우, 수익의 의사표시를 한 수익자는 낙약자에게 자기가 입은 손해의 배상을 청구할 수 있다.","ox":"O","m":"④","c":"A","tp":"제3자를 위한 계약"},{"y":2019,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2019_25-10-5","t":"제3자를 위한 계약이 성립하기 위하여는 그 계약의 당사자가 아닌 제3자로 하여금 직접 권리를 취득하게 하는 조항이 있어야 하므로, 계약의 당사자가 제3자에 대하여 가진 채권에 관하여 그 채무를 면제하는 계약은 제3자를 위한 계약으로 유효하다고 볼 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2019_25-18","t":"각종 계약에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"각종 계약에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["기존채무에 대하여 채권가압류가 마쳐진 후 채무자와 제3채무자 사이에 준소비대차 약정이 체결된 경우, 가압류의 처분제한의 효력에 따라 채무자와 제3채무자는 준소비대차의 성립을 가압류채권자에게 주장할 수 없고, 다만 채무자와 제3채무자 사이에서는 준소비대차가 유효하다.","수인의 채권자가 그 채권을 담보하기 위하여 수인의 채권자 전원을 공동매수인으로 하여 채무자 소유의 부동산에 관하여 매매예약을 체결하고 이에 따라 가등기를 마친 경우, 그 가등기에 기한 본등기절차의 이행을 구하는 소는 반드시 그 수인의 채권자 전원이 제기하여야 한다.","화해계약이 사기로 인하여 이루어진 경우에는 화해의 목적인 분쟁에 관한 사항에 착오가 있더라도 민법 제110조에 따라 이를 취소할 수 있다.","위임계약의 수임인이 위임인에게 가지는 대변제청구권을 보전하기 위하여 채무자인 위임인의 채권을 대위행사하는 경우에는 채무자의 무자력을 요하지 않는다.","민법상 조합계약은 2인 이상이 상호 출자하여 공동으로 사업을 경영할 것을 약정하는 계약이므로, 특정한 사업을 공동경영하는 약정에 한하여 이를 조합계약이라 할 수 있고, 공동의 목적 달성이라는 정도만으로는 조합의 성립요건을 갖추었다고 할 수 없다. 22-16"],"a":2}},{"y":2019,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2019_25-30","t":"매도인의 담보책임에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"매도인의 담보책임에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["매매계약당시 그 토지의 소유권이 매도인에 속하지 아니함을 알고 있던 매수인은 매도인에 대하여 그 이행불능을 원인으로 손해배상을 청구할 수 없고, 다만 그 이행불능이 매도인의 귀책사유로 인하여 이루어진 것인 때에 한하여 그 손해배상을 청구할 수 있다.","타인의 권리매매에 있어 매도인의 목적물을 매수인에게 이전할 수 없게 된 것이 오직 매수인의 귀책사유에 기인한 경우에는 매도인은 하자담보책임을 지지 않는다.","목적물이 일정한 면적을 가지고 있다는 데 주안을 두고 대금도 면적을 기준으로 하여 정하여지는 ‘아파트 분양계약’은 수량을 지정한 매매이며, 공유대지면적을 지정한 아파트 분양계약에서 공유대지면적을 부족하게 이전해 준 경우에는 민법 제574조에 의한 대금감액청구권이 인정된다.","가압류 목적이 된 부동산을 매수한 사람이 그 후 가압류에 기한 강제집행으로 부동산 소유권을 상실하게 된 경우, 매도인의 담보책임에 관한 민법 제570조가 준용되어 악의의 매수인은 매매계약을 해제할 수 있으나, 담보책임으로서 손해배상을 구할 수는 없다.","매수인이 강제경매절차를 통하여 대금을 납부하고 부동산을 매수하였으나 위 강제집행권원이 된 약속어음공정증서가 위조된 것이어서 무효라는 이유로 결국 경매부동산에 대한 소유권을 취득하지 못하게 된 경우라도, 매수인은 경매대금을 배당받은 경매채권자에게 민법 제578조 제2항에 의한 경매에서의 담보책임을 물을 수는 없다. 22-19"],"a":4}},{"y":2020,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2020_26-13-1","t":"계약을 합의해제한 경우에도 민법상 해제의 효과에 따른 제3자 보호규정이 적용된다.","ox":"O","m":"①","c":"A","tp":"계약의 해제 및 해지"},{"y":2020,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2020_26-13-2","t":"계약을 합의해지한 경우에 별도의 약정이 없는 한 합의해지로 인하여 반환해야 할 금전에 법정이자를 가산해야 하는 것은 아니다.","ox":"O","m":"②","c":"A","tp":"계약의 해제 및 해지"},{"y":2020,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2020_26-13-3","t":"부동산매매계약에서 매수인이 잔금 지급기일까지 잔금을 지급하지 못하면 계약이 자동적으로 해제된다는 약정을 한 경우 잔금 지급기일이 도과하였는데 매수인이 잔금을 지급하지 않았다면 계약은 자동적으로 해제된다.","ox":"X","m":"③","c":"A","tp":"계약의 해제 및 해지"},{"y":2020,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2020_26-13-4","t":"甲이 乙에게 매매를 원인으로 주택의 소유권이전등기를 마쳐주었으나, 매매계약이 적법하게 해제되고 乙 명의의 소유권이전등기가 말소된 경우에도 위 매매계약이 해제되기 전에 乙로부터 주택을 임차하여 주택임대차보호법 소정의 대항요건을 갖춘 丙의 권리를 해하지 못하므로 丙은 자신의 임차권으로 甲에게 대항할 수 있다.","ox":"O","m":"④","c":"A","tp":"계약의 해제 및 해지"},{"y":2020,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2020_26-13-5","t":"甲이 乙에 대한 매매대금채권을 丙에게 양도한 후 매매계약이 해제되었다면 丙이 선의라도 乙에 대하여 양도받은 매매대금을 청구할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"계약의 해제 및 해지"},{"y":2020,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2020_26-27-1","t":"매매계약 체결 당시 계약금을 약정하였지만 아직 계약금의 교부는 없었다면 계약의 당사자는 민법 제565조 해약금 규정을 근거로 주계약을 해제할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2020_26-27-2","t":"매매계약 체결시 수수된 계약금에 대하여 매수인이 위약하였을 때에는 계약금을 매도인이 취득하고, 매도인이 위약하였을 때에는 매수인에게 계약금의 배액을 변상한다는 특약을 한 경우 계약금은 더 이상 해약금으로서 기능할 수 없으므로 매도인이 이행에 착수하기 전이라 하더라도 매수인은 계약금을 포기하고 임의로 계약을 해제할 수 없다.","ox":"X","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2020_26-27-3","t":"매매계약을 체결함에 있어서 계약금이 수수된 경우 계약금은 해약금의 성질을 가지고 있어서 이를 위약금으로 하기로 하는 특약이 없는 이상 계약이 당사자 일방의 귀책사유로 인하여 해제되었다 하더라도 상대방은 계약불이행으로 입은 실제 손해만을 배상받을 수 있을 뿐 계약금이 위약금으로서 상대방에게 당연히 귀속되는 것은 아니다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2020_26-27-4","t":"매도인이 해약금에 기한 해제의 의사표시를 하면서 일정한 기한까지 해약금을 수령하라고 최고하고 그 기한을 넘기면 공탁하겠다고 통지한 후, 중도금 납부기일이 도래하기 전에 매수인이 중도금을 지급하였더라도 매도인의 계약해제권 행사에 영향을 미칠 수 없다.","ox":"O","m":"④","c":"A","tp":"계약금"},{"y":2020,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2020_26-27-5","t":"매매계약 체결시 수수된 계약금에 대하여 매수인이 위약하였을 때에는 계약금을 매도인이 취득하고, 매도인이 위약하였을 때에는 매수인에게 계약금의 배액을 변상한다는 특약을 한 경우 이 약정이 손해배상액의 예정인지 위약벌의 성격인지 불분명할 때에는 손해배상액의 예정으로 추정된다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2021_27-01-1","t":"어느 일방이 교섭단계에서 계약이 확실하게 체결되리라는 정당한 기대 내지 신뢰를 부여하여 상대방이 그 신뢰에 따라 행동하였음에도 상당한 이유 없이 계약의 체결을 거부하여 손해를 입혔다면 이는 신의성실의 원칙에 비추어 볼 때 계약자유원칙의 한계를 넘는 위법한 행위로서 불법행위를 구성한다.","ox":"O","m":"①","c":"A","tp":"계약교섭의 부당파기"},{"y":2021,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2021_27-01-2","t":"계약교섭의 부당한 중도파기가 불법행위를 구성하는 경우 그러한 불법행위로 인한 손해는 일방이 신의에 반하여 상당한 이유 없이 계약교섭을 파기함으로써 계약체결을 신뢰한 상대방이 입게 된 상당인과관계 있는 손해로서 계약이 유효하게 체결된다고 믿었던 것에 의하여 입었던 손해 즉 신뢰손해에 한정된다.","ox":"O","m":"②","c":"A","tp":"계약교섭의 부당파기"},{"y":2021,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2021_27-01-3","t":"아직 계약체결에 관한 확고한 신뢰가 부여되기 이전 상태에서 계약교섭의 당사자가 계약체결이 좌절되더라도 어쩔 수 없다고 생각하고 지출한 비용, 예컨대 경쟁입찰에 참가하기 위하여 지출한 제안서, 견적서 작성비용 등도 원칙적으로 민법상 손해배상의 범위에 포함된다.","ox":"X","m":"③","c":"A","tp":"계약교섭의 부당파기"},{"y":2021,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2021_27-01-4","t":"침해행위와 피해법익의 유형에 따라서 계약교섭의 파기로 인한 불법행위가 인격적 법익을 침해함으로써 상대방에게 정신적 고통을 초래하였다고 인정되는 경우라면 그러한 정신적 고통에 대한 손해에 대하여는 별도로 배상을 구할 수 있다.","ox":"O","m":"④","c":"A","tp":"계약교섭의 부당파기"},{"y":2021,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2021_27-01-5","t":"계약교섭 단계에서 당사자 중 일방이 이행에 착수하는 것은 이례적이라고 할 것이므로 설령 이행에 착수하였다고 하더라도 이는 자기의 위험 판단과 책임에 의한 것이라고 평가할 수 있지만 만일 이행의 착수가 상대방의 적극적인 요구에 따른 것이고, 그 이행에 들인 비용의 지급에 관하여 이미 계약교섭이 진행되고 있었다는 등의 특별한 사정이 있는 경우에는 당사자 중 일방이 계약의 성립을 기대하고 이행을 위하여 지출한 비용 상당의 손해가 상당인과관계 있는 손해에 해당한다.","ox":"O","m":"⑤","c":"A","tp":"계약교섭의 부당파기"},{"y":2021,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2021_27-03-1","t":"예금계약은 예금자가 예금의 의사를 표시하면서 금융기관에 돈을 제공하고 금융기관이 그 의사에 따라 돈을 받아 확인하면 그로써 성립하며, 금융기관의 직원이 그 돈을 금융기관에 입금하지 아니하고 이를 횡령하였다고 하더라도 예금계약의 성립 여부에 아무런 영향이 없다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2021_27-03-2","t":"‘계좌이체가 되는 경우에는 예금원장에 입금의 기록이 된 때에 예금이 된다’고 예금거래기본약관에 정하여져 있더라도 송금의뢰인과 수취인 사이에 계좌이체의 원인인 법률관계가 존재하지 아니함에도 착오로 수취인의 예금계좌에 이체를 하였다면 수취인이 수취은행에 대하여 이체된 금액 상당의 예금채권을 취득하는 것은 아니다.","ox":"X","m":"②","c":"A","tp":"예금계약"},{"y":2021,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2021_27-03-3","t":"송금의뢰인과 수취인 사이에 계좌이체의 원인인 법률관계가 존재하지 아니함에도 착오로 수취인의 예금계좌에 이체를 한 위와 같은 경우에는 수취인이 법률상 원인없이 예금채권을 취득하는 이익을 얻은 것이므로 송금의뢰인은 수취인에 대하여 부당이득반환청구권을 가지게 된다.","ox":"O","m":"③","c":"A","tp":"예금계약"},{"y":2021,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2021_27-03-4","t":"甲이 배우자인 乙을 대리하여 금융기관과 乙의 실명확인 절차를 거쳐 乙 명의의 예금계약을 체결한 경우에 명의자인 乙이 아닌 실제로 자금을 출연한 甲을 예금계약의 당사자라고 보기 위해서는, 甲과 금융기관과의 사이에 예금명의자인 乙의 예금반환청구권을 배제하고 출연자인 甲과 예금계약을 체결하여 甲에게 예금반환청구권을 귀속시키겠다는 명확한 의사의 합치가 있는 극히 예외적인 경우여야 한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2021_27-03-5","t":"은행에 공동명의로 예금을 하고 은행에 대하여 그 권리를 함께 행사하기로 한 경우에 만일 동업자금을 공동명의로 예금한 경우라면 채권의 준합유관계에 있지만, 공동명의 예금채권자들 각자가 분담하여 출연한 돈을 동업 이외의 특정 목적을 위하여 공동명의로 예치해 둠으로써 그 목적이 달성되기 전에는 공동명의 예금채권자가 단독으로 예금을 인출할 수 없도록 방지·감시하고자 하는 등의 목적으로 공동명의로 예금을 개설한 경우라면 하나의 예금채권이 분량적으로 분할되어 각 공동명의 예금채권자들에게 귀속된다.","ox":"O","m":"⑤","c":"A","tp":"예금계약"},{"y":2021,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2021_27-15-1","t":"수임인은 위임인의 승낙이나 부득이한 사유없이 제3자로 하여금 자기에 갈음하여 위임사무를 처리하게 하지 못한다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2021_27-15-2","t":"위임계약의 각 당사자는 민법 제689조 제1항에 의하여 특별한 이유 없이도 언제든지 위임계약을 해지할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2021_27-15-3","t":"위임계약의 일방 당사자가 타방 당사자의 채무불이행을 이유로 위임계약을 해지한다는 의사표시를 하였으나 실제로는 채무불이행을 이유로 한 계약 해지의 요건을 갖추지 못한 경우에는, 특별한 사정이 없는 한 위 의사표시에는 민법 제689조 제1항에 기한 임의해지로서의 효력도 인정되지 아니한다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2021_27-15-4","t":"수임인이 위임받은 사무를 처리하던 중 사무처리를 완료하지 못한 상태에서 위임계약을 해지함으로써 위임인이 그 사무처리의 완료에 따른 성과를 이전받거나 이익을 얻지 못하게 되었다 하더라도, 별도로 특약을 하는 등 특별한 사정이 없는 한 위임계약에서는 시기 여하를 불문하고 사무처리 완료 이전에 계약이 해지되면 당연히 위임인이 그 사무처리의 완료에 따른 성과를 이전받거나 이익을 얻지 못하는 것으로 계약 당시에 예정되어 있으므로, 수임인이 사무처리를 완료하기 전에 위임계약을 해지한 것만으로 위임인에게 불리한 시기에 해지한 것이라고 볼 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2021_27-15-5","t":"민법상의 위임계약은 유상계약이든 무상계약이든 당사자 쌍방의 특별한 대인적 신뢰관계를 기초로 하는 위임계약의 본질상 각 당사자는 언제든지 해지할 수 있고 그로 말미암아 상대방이 손해를 입는 일이 있어도 그것을 배상할 의무를 부담하지 않는 것이 원칙이며, 다만 상대방이 불리한 시기에 해지한 때에는 해지가 부득이한 사유에 의한 것이 아닌 한 그로 인한 손해를 배상하여야 하나, 배상의 범위는 위임이 해지되었다는 사실로부터 생기는 손해가 아니라 적당한 시기에 해지되었더라면 입지 아니하였을 손해에 한한다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2021_27-26-1","t":"등기된 임차권에는 용익권적 권능 외에 임차보증금반환채권에 대한 담보권적 권능이 있고, 임대차기간이 종료되면 용익권적 권능은 임차권등기의 말소등기 없이도 곧바로 소멸하나 담보권적 권능은 곧바로 소멸하지 않는다고 할 것이어서, 임차권자는 임대차기간이 종료한 후에도 임차보증금을 반환받기까지는 임대인이나 그 승계인에 대하여 임차권등기의 말소를 거부할 수 있다고 할 것이고, 따라서 임차권등기가 원인 없이 말소된 때에는 그 방해를 배제하기 위한 청구를 할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2021_27-26-2","t":"임대차계약에 있어서 목적물을 사용·수익하게 할 임대인의 의무와 임차인의 차임지급의무는 상호 대응관계에 있으므로 임대인이 목적물을 사용·수익하게 할 의무를 불이행하여 임차인이 목적물을 전혀 사용할 수 없을 경우에는 임차인은 차임 전부의 지급을 거절할 수 있으나, 목적물의 사용·수익이 부분적으로 지장이 있는 상태인 경우에는 그 지장의 한도 내에서 차임의 지급을 거절할 수 있을 뿐 그 전부의 지급을 거절할 수는 없다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2021_27-26-3","t":"임대차계약이 중도에 해지되어 종료하면 임차인은 목적물을 원상으로 회복하여 반환하여야 하는 것이나, 임대인의 귀책사유로 임대차계약이 해지되었다면 임차인은 원상회복의무를 부담하지 않는다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2021_27-26-4","t":"임대차계약의 종료에 의하여 발생된 임차인의 임차목적물 반환의무와 임대인의 연체차임 등을 공제한 나머지 임대차보증금의 반환의무는 동시이행관계에 있으므로, 임대인이 나머지 임대차보증금의 반환의무를 이행하거나 적법한 이행제공을 하여 임차인의 동시이행항변권을 상실시키지 아니한 이상, 임차인이 임차목적물반환의무를 이행하지 아니하고 임차목적물을 계속 점유하고 있다고 하더라도, 임차인은 임대인에 대하여 임차목적물반환의무의 이행지체로 인한 손해배상책임을 지지 아니한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2021_27-26-5","t":"임대차는 당사자 일방이 상대방에게 목적물을 사용·수익하게 할 것을 약정하고 상대방이 이에 대하여 차임을 지급할 것을 약정함으로써 성립하는 것으로서 임대인이 그 목적물에 대한 소유권 기타 이를 임대할 권한이 있을 것을 성립요건으로 하고 있지 아니하므로, 임대차계약이 성립된 후 그 존속기간 중에 임대인이 임대차 목적물에 대한 소유권을 상실한 사실 그 자체만으로 바로 임대차에 직접적인 영향을 미친다고 볼 수는 없지만, 임대인이 임대차 목적물의 소유권을 제3자에게 양도하고 그 소유권을 취득한 제3자가 임차인에게 그 임대차 목적물의 인도를 요구하여 이를 인도하였다면 임대인이 임차인에게 임대차 목적물을 사용·수익케 할 의무는 이행불능이 되었다고 할 것이고, 이러한 이행불능이 일시적이라고 볼 만한 특별한 사정이 없다면 임대차는 당사자의 해지 의사표시를 기다릴 필요 없이 당연히 종료되었다고 볼 것이지, 임대인의 채무가 손해배상 채무로 변환된 상태로 채권·채무관계가 존속한다고 볼 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2021_27-39-1","t":"매수인이 매도인과 사이의 매매계약에 의한 잔대금지급기일에 잔대금을 지급하지 못한 것은 물론 그 지급의 연기를 수차 요청하였다면 그 채무를 이행하지 아니할 의사를 명백히 한 것으로 볼 수 있다.","ox":"X","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2021_27-39-2","t":"채무불이행에 의한 계약해제에 있어 미리 이행하지 아니할 의사를 표시한 경우로서 이른바 ‘이행거절’로 인한 계약해제의 경우에는 상대방의 최고 및 동시이행관계에 있는 자기 채무의 이행제공을 요하지 아니하여 이행지체시의 계약해제와 비교할 때 계약해제의 요건이 완화되어 있는 바, 명시적으로 이행거절의사를 표명하는 경우 외에 계약 당시나 계약 후의 여러 사정을 종합하여 묵시적 이행거절의사를 인정하기 위하여는 그 거절의사가 정황상 분명하게 인정되어야 한다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2021_27-39-3","t":"계약의 합의해제는 명시적으로뿐만 아니라 당사자 쌍방의 묵시적인 합의에 의하여도 할 수 있으나, 묵시적인 합의해제를 한 것으로 인정되려면 계약이 체결되어 그 일부가 이행된 상태에서 당사자 쌍방이 장기간에 걸쳐 나머지 의무를 이행하지 아니함으로써 이를 방치한 것만으로는 부족하고, 당사자 쌍방에게 계약을 실현할 의사가 없거나 계약을 포기할 의사가 있다고 볼 수 있을 정도에 이르러야 한다. 이 경우에 당사자 쌍방이 계약을 실현할 의사가 없거나 포기할 의사가 있었는지 여부는 계약이 체결된 후의 여러 가지 사정을 종합적으로 고려하여 판단하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2021_27-39-4","t":"계약의 합의해제 또는 해제계약은 해제권의 유무를 불문하고 계약당사자 쌍방이 합의에 의하여 기존의 계약의 효력을 소멸시켜 당초부터 계약이 체결되지 않았던 것과 같은 상태로 복귀시킬 것을 내용으로 하는 새로운 계약으로서, 계약이 합의해제되기 위하여는 계약의 성립과 마찬가지로 계약의 청약과 승낙이라는 서로 대립하는 의사표시가 합치될 것을 요건으로 하는 바, 이와 같은 합의가 성립하기 위하여는 쌍방당사자의 표시행위에 나타난 의사의 내용이 객관적으로 일치하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2021_27-39-5","t":"쌍무계약에서 서로 대가관계에 있는 당사자 쌍방의 의무는 원칙적으로 동시이행의 관계에 있고, 나아가 하나의 계약으로 둘 이상의 민법상의 전형계약을 포괄하는 내용의 계약을 체결한 경우에 당사자 일방의 여러 의무가 포괄하여 상대방의 여러 의무와 대가관계에 있다고 인정되면, 이러한 당사자 일방의 여러 의무와 상대방의 여러 의무는 동시이행의 관계에 있다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2022_28-06-1","t":"계약이 의사의 불합치로 성립하지 아니한 경우 그로 인하여 손해를 입은 당사자는 상대방이 계약이 성립되지 아니할 수 있다는 것을 알았거나 알 수 있었음을 이유로 민법 제535조를 유추적용하여 계약체결상의 과실로 인한 손해배상청구를 할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2022_28-06-2","t":"당사자간에 동일한 내용의 청약이 상호교차된 경우에는 양청약이 상대방에게 도달한 때에 계약이 성립하고, 승낙자가 청약에 대하여 조건을 붙이거나 변경을 가하여 승낙한 때에는 그 청약의 거절과 동시에 새로 청약한 것으로 본다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2022_28-06-3","t":"명예퇴직의 신청은 근로계약에 대한 합의해지의 청약에 불과하여 이에 대한 사용자의 승낙이 있어 근로계약이 합의해지되기 전에는 근로자가 임의로 그 청약의 의사표시를 철회할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2022_28-06-4","t":"무효인 약관조항에 의거하여 계약이 체결되었다면 그 후 상대방이 계약의 이행을 지체하는 과정에서 약관작성자로부터 채무의 이행을 독촉받고 종전 약관에 따른 계약내용의 이행 및 약정내용을 재차 확인하는 취지의 각서를 작성하여 교부하였다 하여 무효인 약관의 조항이 유효한 것으로 된다고 할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2022_28-06-5","t":"약관상 매매계약 해제시 매도인을 위한 손해배상액의 예정조항은 있는 반면 매수인을 위한 손해배상액의 예정조항은 없는 경우, 매도인 일방만을 위한 손해배상액의 예정조항을 두었다는 사정만으로는 약관의 규제에 관한 법률에 위배되어 무효라 할 수는 없다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2022_28-09-1","t":"주택의 소유자는 아니지만 주택에 관하여 적법하게 임대차계약을 체결할 수 있는 권한을 가진 명의신탁자와 임대차계약이 체결된 경우, 임차인은 등기기록상 주택의 소유자인 명의수탁자에 대한 관계에서도 적법한 임대차임을 주장할 수 있다.","ox":"O","m":"①","c":"A","tp":"주택임대차"},{"y":2022,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2022_28-09-2","t":"주택임대차보호법에 의하면 임대인이 임대차가 끝나기 6개월 전부터 2개월 전까지의 기간에 임차인에게 갱신거절의 통지를 하지 않거나 계약조건을 변경하지 않으면 갱신하지 않겠다는 뜻의 통지를 하지 않은 경우에는, 그 기간이 끝난 때에 전(前) 임대차와 동일한 조건으로 다시 임차한 것으로 본다. 이때 임차인은 임대인에 대하여 언제든지 계약해지를 통지할 수 있고, 임대인이 그 통지를 받은 날로부터 2개월이 지나면 효력이 발생한다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2022_28-09-3","t":"임대인은 임차인이 임대차기간이 끝나기 6개월 전부터 2개월 전까지의 기간 이내에 계약갱신을 요구하면 정당한 사유 없이 거절하지 못하는데, 임차인은 이 계약갱신요구권을 1회에 한하여 행사할 수 있다.","ox":"O","m":"③","c":"A","tp":"주택임대차"},{"y":2022,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2022_28-09-4","t":"임대인이 목적 주택에서의 실거주를 이유로 임차인의 계약갱신요구를 거절하였음에도 그 계약갱신요구가 거절되지 아니하였더라면 갱신되었을 기간이 만료되기 전에 정당한 사유 없이 제3자에게 목적 주택을 임대한 경우 임대인은 갱신거절로 인하여 임차인이 입은 손해를 배상하여야 한다.","ox":"O","m":"④","c":"A","tp":"주택임대차"},{"y":2022,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2022_28-09-5","t":"주택임대차보호법 제3조 제1항에 의한 대항력 취득의 요건인 주민등록은 임차인 본인뿐 아니라 배우자나 자녀 등 가족의 주민등록도 포함되고, 이는 재외국민이 임차인인 경우에도 마찬가지로 적용되므로, 재외국민이 임대차계약을 체결하고 동거가족인 외국인 또는 외국국적동포가 외국인등록이나 국내거소신고 등을 한 경우에도 대항력을 취득한다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2022_28-11-1","t":"계약이 합의에 따라 해제되거나 해지된 경우에는 상대방에게 손해배상을 하기로 특약하거나 손해배상청구를 유보하는 의사표시를 하는 등 다른 사정이 없는 한 채무불이행으로 인한 손해배상을 청구할 수 없다.","ox":"O","m":"①","c":"A","tp":"계약의 해제"},{"y":2022,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2022_28-11-2","t":"계약의 해제는 제3자의 권리를 해하지 못하는데, 여기에서 제3자란 일반적으로 계약이 해제되는 경우 그 해제된 계약으로부터 생긴 법률효과를 기초로 하여 해제 전에 새로운 이해관계를 가지게 된 자로서, 계약상 채권을 양수한 자와 등기·인도 등으로 완전한 권리를 취득한 자를 말한다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2022_28-11-3","t":"매도인의 매매계약상의 소유권이전등기의무가 이행불능이 되어 이를 이유로 매매계약을 해제함에 있어서는 상대방의 잔대금지급의무가 매도인의 소유권이전등기의무와 동시이행관계에 있다고 하더라도 그 이행의 제공을 필요로 하는 것이 아니다.","ox":"O","m":"③","c":"A","tp":"계약의 해제"},{"y":2022,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2022_28-11-4","t":"일방 당사자의 계약위반을 이유로 한 상대방의 계약해제 의사표시에 의하여 계약이 해제되었음에도 상대방이 계약이 존속함을 전제로 계약상 의무의 이행을 구하는 경우 계약을 위반한 당사자도 당해 계약이 상대방의 해제로 소멸되었음을 들어 그 이행을 거절할 수 있다.","ox":"O","m":"④","c":"A","tp":"계약의 해제"},{"y":2022,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2022_28-11-5","t":"매수인이 계약의 이행에 착수하기 전에는 매도인이 계약금의 배액을 상환하고 계약을 해제할 수 있으나, 이 때 계약 해제 통고로서 바로 해제 효과가 발생하는 것이 아니라 매도인이 수령한 계약금의 배액을 매수인에게 상환하거나 적어도 그 이행제공을 하지 않으면 계약을 해제할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"계약의 해제"},{"y":2022,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2022_28-14-1","t":"동시이행의 관계에 있는 쌍방의 채무 중 어느 한 채무가 이행불능이 됨으로 인하여 발생한 손해배상채무도 여전히 다른 채무와 동시이행의 관계에 있다.","ox":"O","m":"①","c":"A","tp":"동시이행의 항변권"},{"y":2022,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2022_28-14-2","t":"매매계약에서 대가적 의미가 있는 매도인의 소유권이전의무와 매수인의 대금지급의무는 다른 약정이 없는 한 동시이행의 관계에 있다. 설령 어느 의무가 선이행의무라고 하더라도 이행기가 지난 때에는 이행기가 지난 후에도 여전히 선이행하기로 약정하는 등의 특별한 사정이 없는 한 그 의무를 포함하여 매도인과 매수인 쌍방의 의무는 동시이행관계에 놓이게 된다.","ox":"O","m":"②","c":"A","tp":"동시이행의 항변권"},{"y":2022,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2022_28-14-3","t":"매수인이 매도인을 상대로 매매목적 부동산 중 일부에 대해서만 소유권이전등기의무의 이행을 구하고 있는 경우에는, 매도인은 특별한 사정이 없는 한 그 매매잔대금 일부에 대하여 동시이행의 항변권을 행사할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2022_28-14-4","t":"일반적으로 동시이행의 관계가 인정되는 경우에 그러한 항변권을 행사하는 자의 상대방이 그 동시이행의 의무를 이행하기 위하여 과다한 비용이 소요되거나 또는 그 의무의 이행이 실제적으로 어려운 반면 그 의무의 이행으로 인하여 항변권자가 얻는 이득은 별달리 크지 아니하여 동시이행의 항변권의 행사가 주로 자기 채무의 이행만을 회피하기 위한 수단이라고 보여지는 경우에는 그 항변권의 행사는 권리남용으로서 배척되어야 할 것이다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2022_28-14-5","t":"동시이행의 항변권은 당사자가 행사하지 않는 이상 법원으로서는 이를 고려할 필요가 없지만, 이행지체책임은 동시이행의 항변권을 행사하지 않아도 발생하지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2022_28-17-1","t":"임대차계약에 있어 임대차보증금은 임대차계약 종료 후 목적물을 임대인에게 인도할 때까지 발생하는, 임대차에 따른 임차인의 모든 채무를 담보하는 것으로서, 그 피담보채무 상당액은 임대차관계의 종료 후 목적물이 반환될 때에, 특별한 사정이 없는 한, 별도의 의사표시 없이 보증금에서 당연히 공제된다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2022_28-17-2","t":"건물 소유를 목적으로 하는 토지임대차계약을 체결한 임차인이 그 지상건물을 등기하기 전에 제3자가 그 토지에 관하여 물권취득의 등기를 한 때에는 임차인이 그 지상건물을 등기하더라도 그 제3자에 대하여 임대차의 효력이 생기지 않는다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2022_28-17-3","t":"임대차계약 종료 후에도 임차인이 동시이행의 항변권을 행사하여 임차목적물을 계속 점유하여 온 것이라면 임차인의 그 건물에 대한 점유는 불법점유라고 할 수 없으므로, 임차인이 임차목적물을 계속 점유하였다고 하여 바로 불법점유로 인한 손해배상책임이 발생하는 것은 아니다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2022_28-17-4","t":"임차인이 임대차계약종료 이후에도 동시이행의 항변권을 행사하는 방법으로 목적물의 반환을 거부하기 위하여 임차건물부분을 계속 점유하기는 하였으나 이를 본래의 임대차계약상의 목적에 따라 사용·수익하지 아니하여 실질적인 이득을 얻은 바 없는 경우에는 그로 인하여 임대인에게 손해가 발생하였다 하더라도 임차인의 부당이득반환의무는 성립되지 않는다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2022_28-17-5","t":"임차인이 임대인의 동의를 얻어 임차물을 전대한 경우 임차인과 전차인 사이에는 별개의 새로운 전대차계약이 성립하며, 임대인과 전차인 사이에는 직접적인 법률관계가 형성되지 않으므로 전차인은 임대인에 대하여 직접 의무를 부담하지 않는다.","ox":"X","m":"⑤","c":"A","tp":"임대차계약"},{"y":2022,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2022_28-18-1","t":"이행기의 약정이 있는 경우라 하더라도 당사자가 채무의 이행기 전에는 착수하지 아니하기로 하는 특약을 하는 등 특별한 사정이 없는 한 이행기 전에 이행에 착수할 수 있다.","ox":"O","m":"①","c":"A","tp":"매매"},{"y":2022,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2022_28-18-2","t":"유상계약을 체결함에 있어서 계약금 등 금원이 수수되었다고 하더라도 이를 위약금으로 하기로 하는 특약이 있는 경우에 한하여 민법 제398조 제4항에 의하여 손해배상액의 예정으로서의 성질을 가진 것으로 볼 수 있을 뿐이고, 그와 같은 특약이 없는 경우에는 그 계약금 등을 손해배상액의 예정으로 볼 수 없다.","ox":"O","m":"②","c":"A","tp":"매매"},{"y":2022,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2022_28-18-3","t":"매수인은 민법 제565조 제1항에 따라 본인 또는 매도인이 이행에 착수할 때까지는 계약금을 포기하고 계약을 해제할 수 있는바, 매도인이 매수인에 대하여 매매계약의 이행을 최고하고 매매잔대금의 지급을 구하는 소송을 제기하였다면 이행에 착수하였다고 볼 수 있다.","ox":"X","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2022_28-18-4","t":"매매계약 있은 후에도 인도하지 아니한 목적물로부터 생긴 과실은 매도인에게 속한다. 매수인은 목적물의 인도를 받은 날로부터 대금의 이자를 지급하여야 한다. 그러나 대금의 지급에 대하여 기한이 있는 때에는 그러하지 아니하다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2022_28-18-5","t":"매매의 목적물을 종류로 지정한 경우에도 그 후 특정된 목적물에 하자가 있는 때에는 매수인은 계약의 해제 또는 손해배상의 청구를 하지 아니하고 하자없는 물건을 청구할 수도 있다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2022_28-23-1","t":"타인의 권리를 매매의 목적으로 한 경우에 있어서 그 권리를 취득하여 매수인에게 이전하여야 할 매도인의 의무가 매도인의 귀책사유로 인하여 이행불능이 되었다면 매수인이 매도인의 담보책임에 관한 민법 제570조 단서의 규정에 의해 손해배상을 청구할 수 없더라도 채무불이행 일반의 규정에 좇아서 계약을 해제하고 손해배상을 청구할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2022_28-23-2","t":"매매의 목적물이 지상권, 지역권, 전세권, 질권 또는 유치권의 목적이 된 경우에 매수인이 이를 알지 못한 때에는 이로 인하여 계약의 목적을 달성할 수 없는 경우에 한하여 매수인은 계약을 해제할 수 있고, 그렇지 않은 경우에는 손해배상만을 청구할 수 있는데, 그와 같은 권리는 매수인이 그 사실을 안 날로부터 1년 또는 매매계약이 있었던 날로부터 3년 내에 행사하여야 한다.","ox":"X","m":"②","c":"A","tp":"매도인의 담보책임"},{"y":2022,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2022_28-23-3","t":"성토작업을 기화로 다량의 폐기물을 은밀히 매립한 토지의 매도인이 정상적인 토지임을 전제로 협의취득절차를 통하여 공공사업시행자에게 이를 매도함으로써 매수인에게 토지의 폐기물처리비용 상당의 손해를 입게 한 경우, 채무불이행책임과 하자담보책임이 경합적으로 인정된다.","ox":"O","m":"③","c":"A","tp":"매도인의 담보책임"},{"y":2022,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2022_28-23-4","t":"매매의 목적이 된 권리의 일부가 타인에게 속함으로 인하여 매도인이 그 권리를 취득하여 매수인에게 이전할 수 없게 된 때에는 선의의 매수인은 매도인에게 담보책임을 물어 이로 인한 손해배상을 청구할 수 있는바, 이 경우에 매도인이 매수인에 대하여 배상하여야 할 손해액은 원칙적으로 매도인이 매매의 목적이 된 권리의 일부를 취득하여 매수인에게 이전할 수 없게 된 때의 이행불능이 된 권리의 시가, 즉 이행이익 상당액이다.","ox":"O","m":"④","c":"A","tp":"매도인의 담보책임"},{"y":2022,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2022_28-23-5","t":"매매의 목적이 된 권리의 전부가 타인에게 속하는 경우 매도인이 그 권리를 취득하여 매수인에게 이전할 수 없는 때에는 매수인은 매도인의 귀책사유를 불문하고 계약을 해제할 수 있고, 선의의 매수인은 해제와 동시에 손해배상도 청구할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"매도인의 담보책임"},{"y":2022,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2022_28-25","t":"도급에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"도급에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","d":"가.도급계약에서 수급인이 자기의 노력과 재료를 들여 건물을 완성하더라도 도급인과 수급인 사이에 도급인 명의로 건축허가를 받아 소유권보존등기를 하기로 하는 등 완성된 건물의 소유권을 도급인에게 귀속시키기로 합의한 것으로 보여질 경우에는 그 건물의 소유권은 도급인에게 원시적으로 귀속된다.\n나.민법 제673조에 따라 수급인이 일을 완성하기 전에는 도급인은 손해를 배상하고 계약을 해제할 수 있고 특별한 사정이 없는 한 도급인은 이러한 해제로 인한 손해배상에 대하여 과실상계나 손해배상예정액 감액을 주장할 수 있다.\n다.도급계약에서 목적물의 주요구조부분이 약정된 대로 시공되어 사회통념상 일반적으로 요구되는 성능을 갖추었고 당초 예정된 최후의 공정까지 마쳤다면 일이 완성되었다고 보아야 하고, 목적물이 완성되었다면 목적물의 하자는 하자담보책임에 관한 민법 규정에 따라 처리하도록 하는 것이 당사자의 의사와 법률의 취지에 부합하는 해석이다.\n라.완성된 목적물 또는 완성전의 성취된 부분에 하자가 있는 때에는 도급인은 수급인에 대하여 상당한 기간을 정하여 그 하자의 보수를 청구할 수 있고, 하자보수에 갈음하여 또는 보수와 함께 손해배상을 청구할 수 있다.\n마.수급인이 도급인에 대하여 가지는 공사대금채권은 상사채권이므로 특별한 사정이 없는 한 5년의 소멸시효가 적용된다.","o":["가, 나, 라","가, 다, 마","나, 라, 마","가, 다, 라","나, 다, 마"],"a":4}},{"y":2022,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2022_28-32-1","t":"민법상의 조합계약은 2인 이상이 상호 출자하여 공동으로 사업을 경영할 것을 약정하는 계약으로서 특정한 사업을 공동 경영하는 약정에 한하여 이를 조합계약이라고 할 수 있고, 공동의 목적달성이라는 정도만으로는 조합의 성립요건을 갖추었다고 할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2022_28-32-2","t":"동업계약과 같은 조합계약에 있어서는 조합의 해산청구를 하거나 조합으로부터 탈퇴를 하거나 또는 다른 조합원을 제명할 수 있을 뿐이지 일반계약에 있어서처럼 조합계약을 해제하고 상대방에게 그로 인한 원상회복의 의무를 부담지울 수는 없다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2022_28-32-3","t":"조합계약으로 조합원 중 일부 또는 제3자를 업무집행자로 정하지 않은 경우에는 모든 조합원이 원칙적으로 업무집행권을 가진다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2022_28-32-4","t":"2인으로 구성된 조합에서 한 사람이 탈퇴하면 조합관계는 종료되고 특별한 사정이 없는 한 조합 역시 해산 및 청산이 된다.","ox":"X","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2022_28-32-5","t":"조합에서 조합원이 탈퇴하는 경우, 탈퇴자와 잔존자 사이의 탈퇴로 인한 계산은 특별한 사정이 없는 한 민법 제719조 제1항, 제2항에 따라 ‘탈퇴 당시의 조합재산상태’를 기준으로 평가한 조합재산 중 탈퇴자의 지분에 해당하는 금액을 금전으로 반환하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2023_29-05-1","t":"상가건물 임대차보호법이 적용되는 상가건물에 해당하는지는 공부상 표시가 아닌 건물의 현황·용도 등에 비추어 영업용으로 사용하느냐에 따라 실질적으로 판단하여야 하고, 단순히 상품의 보관·제조·가공 등 사실행위만이 이루어지는 공장·창고 등은 영업용으로 사용하는 경우라고 할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2023_29-05-2","t":"건물 내구연한 등에 따른 철거·재건축의 필요성이 객관적으로 인정되지 않거나 그 계획·단계가 구체화되지 않았음에도 임대인이 신규 임차인이 되려는 사람에게 짧은 임대 가능기간만 확정적으로 제시·고수하는 경우 또는 임대인이 신규 임차인이 되려는 사람에게 고지한 내용과 모순되는 정황이 드러나는 등의 특별한 사정이 없는 한, 임대인이 신규 임차인이 되려는 사람과 임대차계약 체결을 위한 협의 과정에서 철거·재건축 계획 및 그 시점을 고지하였다는 사정만으로는 상가건물 임대차보호법 제10조의4 제1항 제4호에서 정한 ‘권리금 회수 방해행위’에 해당한다고 볼 수 없다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2023_29-05-3","t":"차임지급채무는 그 지급에 확정된 기일이 있는 경우에는 그 지급기일 다음 날부터 지체책임이 발생하고 보증금에서 공제되었을 때 비로소 그 채무 및 그에 따른 지체책임이 소멸되는 것이므로, 연체차임에 대한 지연손해금의 발생종기는 다른 특별한 사정이 없는 한 목적물이 반환되는 때가 아니라 임대차계약의 해지시라고 할 것이다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2023_29-05-4","t":"임차인이 임대인의 동의를 받지 않고 제3자에게 임차권을 양도하거나 전대하는 등의 방법으로 임차물을 사용·수익하게 하더라도, 임대인이 이를 이유로 임대차계약을 해지하거나 그 밖의 다른 사유로 임대차계약이 적법하게 종료되지 않는 한 임대인은 임차인에 대하여 여전히 차임청구권을 가지므로, 임대차계약이 존속하는 한도 내에서는 제3자에게 불법점유를 이유로 한 차임상당 손해배상청구나 부당이득반환청구를 할 수 없다 할 것이다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2023_29-05-5","t":"상가건물의 임대차에 이해관계가 있는 자는 관할 세무서장에게 해당 상가건물의 확정일자 부여일, 차임 및 보증금 등 정보의 제공을 요청할 수 있고, 이 경우 요청을 받은 관할 세무서장은 정당한 사유 없이 이를 거부할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2023_29-15-1","t":"민법 제684조 제2항은 “수임인이 위임인을 위하여 자기의 명의로 취득한 권리는 위임인에게 이전하여야 한다.”라고 규정하고 있는데, 이때 그 이전 시기는 당사자 간에 특약이 있거나 위임의 본뜻에 반하는 경우 등과 같은 특별한 사정이 없는 한 위임계약이 종료된 때이다. 따라서 위임사무로 수임인 명의로 취득한 권리에 관한 위임인의 이전청구권의 소멸시효는 위임계약이 종료된 때부터 진행한다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2023_29-15-2","t":"위임계약에서 보수액에 관하여 약정한 경우에 수임인은 원칙적으로 약정보수액을 전부 청구할 수 있는 것이 원칙이지만, 위임업무 처리의 경과와 난이도, 투입한 노력의 정도 등 제반 사정을 고려할 때 약정보수액이 부당하게 과다하여 신의성실의 원칙이나 형평의 원칙에 반한다고 볼 만한 특별한 사정이 있는 때에는 예외적으로 상당하다고 인정되는 범위 내의 보수액만을 청구할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2023_29-15-3","t":"소송위임계약으로 성공보수를 약정하였을 경우 심급대리의 원칙에 따라 수임한 소송사무가 종료하는 시기인 해당 심급의 판결을 송달받은 때로부터 그 소멸시효기간이 진행되나, 당사자 사이에 보수금의 지급시기에 관한 특약이 있다면 그에 따라 보수채권을 행사할 수 있는 때로부터 소멸시효가 진행한다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2023_29-15-4","t":"위임계약의 각 당사자는 민법 제689조 제1항에 따라 특별한 이유 없이도 언제든지 위임계약을 해지할 수 있다. 그러나 위임계약의 일방 당사자가 타방 당사자의 채무불이행을 이유로 위임계약을 해지한다는 의사표시를 하였으나 실제로는 채무불이행을 이유로 한 계약 해지의 요건을 갖추지 못한 경우에는, 특별한 사정이 없는 한 그와 같은 의사표시에 민법 제689조 제1항에 따른 임의해지로서의 효력을 인정할 수는 없다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2023_29-15-5","t":"민법상 위임계약의 당사자는 언제든지 계약을 해지할 수 있고 그로 말미암아 상대방이 손해를 입는 일이 있어도 그것을 배상할 의무를 부담하지 않는 것이 원칙이다. 다만 상대방이 불리한 시기에 해지한 때에는 해지가 부득이한 사유에 의한 것이 아닌 한 그로 인한 손해를 배상하여야 하나, 배상의 범위는 위임이 해지되었다는 사실로부터 생기는 손해가 아니라 적당한 시기에 해지되었더라면 입지 아니하였을 손해에 한한다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2023_29-17-1","t":"자동차관리법령의 문언·내용과 체계 등에 비추어 보면, 자동차 양수인이 양도인으로부터 자동차를 인도받고서도 등록명의의 이전을 하지 않는 경우 양도인은 자동차관리법 제12조 제4항에 따라 양수인을 상대로 소유권이전등록의 인수절차 이행을 구할 수 있다.","ox":"O","m":"①","c":"A","tp":"매매"},{"y":2023,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2023_29-17-2","t":"상가집합건물의 구분점포에 대한 매매는 특별한 사정이 없다면 원칙적으로 실제 이용현황과 관계없이 집합건축물대장 등 공부에 따라 구조, 위치, 면적이 확정된 구분점포를 매매의 대상으로 삼았다고 보아야 할 것이다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2023_29-17-3","t":"선시공·후분양의 방식으로 분양되는 아파트 등의 경우에는 완공된 아파트 등 그 자체가 분양계약의 목적물로 된다고 봄이 상당하고, 완공된 아파트 등의 현황과 달리 분양광고 등에만 표현되어 있는 아파트 등의 외형·재질 등에 관한 사항은 특별한 사정이 없는 한 이를 분양계약의 내용으로 하기로 하는 묵시적 합의가 있었다고 보기는 어렵다.","ox":"O","m":"③","c":"A","tp":"매매"},{"y":2023,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2023_29-17-4","t":"부동산매도인이 매매대금을 다 지급받지 아니한 상태에서 매수인에게 소유권이전등기를 경료하여 목적물의 소유권을 매수인에게 이전한 경우에는, 매도인의 목적물인도의무에 관하여 위와 같은 동시이행의 항변권과 물권적 권리인 유치권이 인정된다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2023_29-17-5","t":"계약 체결 후에 채무의 이행이 불가능하게 된 경우에는 채권자가 이행을 청구하지 못하고 채무불이행을 이유로 손해배상을 청구하거나 계약을 해제할 수 있다. 그러나 계약 당시에 이미 채무의 이행이 불가능했다면 특별한 사정이 없는 한 채권자가 이행을 구하는 것은 허용되지 않고, 민법 제535조에서 정한 계약체결상의 과실책임을 추궁하는 등으로 권리를 구제받을 수밖에 없다.","ox":"O","m":"⑤","c":"A","tp":"매매"},{"y":2023,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2023_29-21-1","t":"완성된 목적물에 하자가 있어 도급인이 하자의 보수에 갈음하여 손해배상을 청구한 경우에 도급인의 손해배상 채권과 동시이행관계에 있는 수급인의 공사대금 채권은 공사잔대금 채권 중 위 손해배상 채권액과 동액의 채권에 한한다.","ox":"O","m":"①","c":"A","tp":"동시이행항변"},{"y":2023,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2023_29-21-2","t":"제3채무자의 압류채무자에 대한 자동채권이 수동채권인 피압류채권과 동시이행의 관계에 있다 하더라도, 압류명령이 제3채무자에게 송달되어 압류의 효력이 생긴 후에 자동채권이 발생하였다면 그 자동채권은 민법 제498조의 ‘지급을 금지하는 명령을 받은 제3채무자가 그 후에 취득한 채권’에 해당하므로, 제3채무자는 동시이행의 항변권을 주장할 수 없다.","ox":"X","m":"②","c":"A","tp":"동시이행항변"},{"y":2023,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2023_29-21-3","t":"계속적 거래관계에 있어서 재화나 용역을 먼저 공급한 후 일정기간마다 거래대금을 정산하여 일정기일 후에 지급받기로 약정한 경우에, 공급자가 선이행의 자기 채무를 이행하였으나 이미 정산이 완료되어 이행기가 지난 전기의 대금을 지급받지 못한 경우에는, 공급자는 이미 이행기가 지난 전기의 대금을 지급받을 때까지 선이행의무가 있는 다음 기간의 자기 채무의 이행을 거절할 수 있다고 해석할 것이다.","ox":"O","m":"③","c":"A","tp":"동시이행항변"},{"y":2023,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2023_29-21-4","t":"부동산 매매계약에 있어 매수인이 부가가치세를 부담하기로 약정한 경우, 부가가치세를 매매대금과 별도로 지급하기로 했다는 등의 특별한 사정이 없는 한 부가가치세를 포함한 매매대금 전부와 부동산의 소유권이전등기의무가 동시이행의 관계에 있다고 봄이 상당하다.","ox":"O","m":"④","c":"A","tp":"동시이행항변"},{"y":2023,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2023_29-21-5","t":"근저당권설정등기가 되어 있는 부동산을 매매하는 경우, 매수인이 근저당권의 피담보채무를 인수하여 그 채무금 상당을 매매잔대금에서 공제하기로 하는 특약을 하는 등 특별한 사정이 없는 한, 매도인의 근저당권말소 및 소유권이전등기의무와 매수인의 잔대금지급의무는 동시이행의 관계에 있는 것이다.","ox":"O","m":"⑤","c":"A","tp":"동시이행항변"},{"y":2023,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2023_29-25-1","t":"채권자와 채무자 모두가 기한의 이익을 갖는 이자부 금전소비대차계약 등에 있어서, 채무자가 변제기로 인한 기한의 이익을 포기하고 변제기 전에 변제하는 경우 변제기까지의 약정이자 등 채권자의 손해를 배상하여야 하고, 이러한 약정이자 등 손해액을 함께 제공하지 않으면 채무의 내용에 따른 변제제공이라고 볼 수 없으므로, 채권자는 수령을 거절할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2023_29-25-2","t":"공동상속인들 사이에 협의가 이루어지지 않는 경우에는 제사주재자의 지위를 인정할 수 없는 특별한 사정이 있지 않는 한 피상속인의 직계비속 중 남녀, 적서를 불문하고 최근친의 연장자가 제사주재자로 우선한다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2023_29-25-3","t":"유언증서가 성립한 후에 멸실되거나 분실되었다는 사유만으로 유언이 실효되는 것은 아니고 이해관계인은 유언증서의 내용을 증명하여 유언의 유효를 주장할 수 있다. 이는 녹음에 의한 유언이 성립한 후에 녹음테이프나 녹음파일 등이 멸실 또는 분실된 경우에도 마찬가지이다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2023_29-25-4","t":"지상권의 존속기간 만료 후 지체 없이 지상권갱신청구권을 행사하지 아니하여 지상권갱신청구권이 소멸한 경우에는, 지상권자의 적법한 갱신청구권의 행사와 지상권설정자의 갱신 거절을 요건으로 하는 지상물매수청구권은 발생하지 않는다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2023_29-25-5","t":"임대차계약에서 임대차기간을 영구로 설정한 것은 채권인 임차권의 성질로 보아 허용되지 않고, 사용·수익 권능을 영구적으로 포기함으로써 처분 권능만이 남는 새로운 유형의 소유권을 창출하는 것이어서 무효이다.","ox":"X","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2023_29-27-1","t":"국가로부터 국유 토지의 관리를 위탁받은 甲 주식회사와 사용수익계약을 체결하여 그 토지 위에 건물을 건축한 乙 주식회사가 계약기간 만료 후 甲 회사를 상대로 지상물매수청구권을 행사한 경우에, 甲 회사는 국유 토지의 관리를 위탁받아 乙 회사와 사용수익계약을 체결한 자일뿐 토지 소유자가 아니므로 지상물매수청구권의 상대방이 될 수 없다고 보아야 한다.","ox":"O","m":"①","c":"A","tp":"지상물매수청구권 및 부속물매수청구권"},{"y":2023,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2023_29-27-2","t":"건물 기타 공작물의 임차인이 적법하게 전대한 경우에 전차인이 그 사용의 편익을 위하여 임대인의 동의를 얻어 임차인으로부터 매수한 부속물이 있는 때에는 전대차의 종료시에 임대인에 대하여 그 부속물의 매수를 청구할 수 있다.","ox":"O","m":"②","c":"A","tp":"지상물매수청구권 및 부속물매수청구권"},{"y":2023,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2023_29-27-3","t":"임야 상태의 토지를 임차하여 대지로 조성한 후 건물을 건축하여 음식점을 경영할 목적으로 임대차계약을 체결한 경우, 비록 임대차계약서에서는 필요비 및 유익비의 상환청구권은 그 비용의 용도를 묻지 않고 이를 전부 포기하는 것으로 기재되었다고 하더라도 대지조성비는 그 상환청구권 포기의 대상으로 삼지 아니한 취지로 약정한 것이라고 해석하는 것이 합리적이다.","ox":"O","m":"③","c":"A","tp":"지상물매수청구권 및 부속물매수청구권"},{"y":2023,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2023_29-27-4","t":"건물의 소유를 목적으로 한 토지의 임대차에 있어서 임차인의 차임연체로 임대차계약이 해지되었을 때에는 임차인에게 그 지상건물에 관한 매수청구권이 발생하지 아니한다.","ox":"O","m":"④","c":"A","tp":"지상물매수청구권 및 부속물매수청구권"},{"y":2023,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2023_29-27-5","t":"기간의 정함이 없는 건물의 소유를 목적으로 하는 토지 임대차에 있어서 임대인에 의한 해지통고에 의하여 그 임차권이 소멸한 경우에도 토지 임차인이 지상물매수청구권을 행사하기 위해서는 계약갱신 청구가 선행되어야 한다.","ox":"X","m":"⑤","c":"A","tp":"지상물매수청구권 및 부속물매수청구권"},{"y":2023,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2023_29-32-1","t":"어떤 계약이 제3자를 위한 계약에 해당하는지 여부는 당사자의 의사가 그 계약에 의하여 제3자에게 직접 권리를 취득하게 하려는 것인지에 관한 의사 해석의 문제로서, 이는 계약 체결의 목적, 계약에 있어서의 당사자의 행위의 성질, 계약으로 인하여 당사자 사이 또는 당사자와 제3자 사이에 생기는 이해득실, 거래 관행, 제3자를 위한 계약 제도가 갖는 사회적 기능 등 제반 사정을 종합하여 계약 당사자의 합리적 의사를 해석함으로써 판별할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2023_29-32-2","t":"제3자를 위한 계약이 성립하기 위하여는 일반적으로 그 계약의 당사자가 아닌 제3자로 하여금 직접 권리를 취득하게 하는 조항이 있어야 할 것이지만, 계약의 당사자가 제3자에 대하여 가진 채권에 관하여 그 채무를 면제하는 계약도 제3자를 위한 계약에 준하는 것으로서 유효하다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2023_29-32-3","t":"낙약자는 요약자와 수익자 사이의 법률관계에 기한 항변으로 수익자에게 대항하지 못하고, 요약자도 요약자와 제3자(수익자) 사이의 법률관계의 부존재나 효력의 상실을 이유로 자신이 낙약자 사이의 법률관계에 기하여 낙약자에게 부담하는 채무의 이행을 거부할 수 없다.","ox":"O","m":"③","c":"A","tp":"제3자를 위한 계약"},{"y":2023,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2023_29-32-4","t":"채무자와 인수인의 계약으로 체결되는 병존적 채무인수는 채권자로 하여금 인수인에 대하여 새로운 권리를 취득하게 하는 것으로 제3자를 위한 계약에 해당한다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2023_29-32-5","t":"제3자를 위한 계약에 있어서 수익의 의사표시를 한 수익자는 낙약자에게 직접 그 이행을 청구할 수 있으나, 요약자가 낙약자와의 계약을 해제한 경우에는 수익자는 낙약자에게 자기가 입은 손해의 배상을 청구할 수는 없다.","ox":"X","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2023_29-34","t":"다음 설명 중 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"다음 설명 중 옳지 않은 것을 모두 고른 것은?","d":"ㄱ.준소비대차는 소비대차에 의하지 아니하고 금전 기타의 대체물을 지급할 의무가 있는 경우에 당사자가 그 목적물을 소비대차의 목적물로 할 것을 약정함으로써 당사자 사이에 소비대차의 효력이 생기는 것을 말하는 것이므로, 준소비대차계약의 당사자는 반드시 기초가 되는 기존 채무의 당사자일 필요는 없다.\nㄴ.임대차종료로 인한 임차인의 원상회복의무에는 임차인이 사용하고 있던 부동산의 점유를 임대인에게 이전하는 것은 물론 임대인이 임대 당시의 부동산 용도에 맞게 다시 사용할 수 있도록 협력할 의무도 포함한다고 할 것이므로, 임대인 또는 그 승낙을 받은 제3자가 임차건물 부분에서 다시 영업허가를 받는 데에 방해되지 않도록 임차인은 임차건물 부분에서의 영업허가에 관하여 폐업신고절차를 이행할 의무가 있다.\nㄷ.임차인이 임차물을 전대하여 그 임대차 기간 및 전대차 기간이 모두 만료된 경우에는 그 전대차가 임대인의 동의를 얻은 여부와 상관없이 임대인으로서는 전차인에 대하여 소유권에 기한 반환청구권에 터잡아 목적물을 자신에게 직접 반환해 줄 것을 요구할 수 있고, 전차인으로서도 목적물을 임대인에게 직접 명도함으로써 임차인(전대인)에 대한 목적물 명도의무를 면한다.\nㄹ.제작물공급계약의 당사자들이 보수의 지급시기에 관하여 “수급인이 공급한 목적물을 도급인이 검사하여 합격하면, 도급인은 수급인에게 그 보수를 지급한다”는 내용으로 한 약정은 법률행위의 효력 발생을 장래의 불확실한 사실의 성부에 의존하게 하는 법률행위의 부관인 조건이며 그 중에서도 순수수의조건에 해당한다.\nㅁ.공사도급계약에서 선급금을 지급한 후 계약이 해제 또는 해지되는 등의 사유로 수급인이 도중에 선급금을 반환하여야 할 사유가 발생하였다면, 특별한 사정이 없는 한 별도의 상계 의사표시 없이도 그때까지의 기성고에 해당하는 공사대금 중 미지급액은 선급금으로 충당되고 도급인은 나머지 공사대금이 있는 경우 그 금액에 한하여 지급할 의무를 부담하게 된다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄱ, ㄹ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㅁ"],"a":3}},{"y":2024,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2024_30-01-1","t":"건물매수청구권의 대상이 되는 건물은 그것이 토지의 임대 목적에 반하여 축조되고 임대인이 예상할 수 없을 정도의 고가의 것이라는 등의 특별한 사정이 없는 한, 비록 행정관청의 허가를 받은 적법한 건물이 아니더라도 임차인의 건물매수청구권의 대상이 될 수 있다.","ox":"O","m":"①","c":"A","tp":"임차인의 매수청구권"},{"y":2024,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2024_30-01-2","t":"건물매수청구권 행사로 인하여 토지 소유자가 임차인에게 지급하여야 할 건물의 시가를 산정함에 있어서 그 건물에서 임차인이 영업을 하면서 얻고 있었던 수익까지 고려하여야 할 것은 아니다.","ox":"O","m":"②","c":"A","tp":"임차인의 매수청구권"},{"y":2024,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2024_30-01-3","t":"건물임차인의 채무불이행으로 인하여 임대차가 해지된 경우 건물임차인은 민법 제646조에 의한 부속물매수청구권이 없으나, 민법 제643조에 의한 건물매수청구권은 국민경제적 관점에서 건물의 잔존가치를 보호하고 토지소유자의 배타적 소유권 행사로 인하여 희생당하기 쉬운 임차인을 보호하기 위한 제도이므로, 토지임차인의 채무불이행을 이유로 임대차계약이 해지되는 경우라면 토지임차인으로서는 토지임대인에 대하여 지상건물의 매수를 청구할 수 있다.","ox":"X","m":"③","c":"A","tp":"임차인의 매수청구권"},{"y":2024,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2024_30-01-4","t":"일시사용을 위한 임대차인 것이 명백한 경우에는 부속물매수청구권의 규정이 적용되지 않는다.","ox":"O","m":"④","c":"A","tp":"임차인의 매수청구권"},{"y":2024,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2024_30-01-5","t":"건물자체의 수선 내지 증·개축부분이 건물자체의 구성부분을 이루고 독립된 물건이라고 보이지 않는 경우 임차인의 부속물 매수청구권의 대상이 될 수 없다.","ox":"O","m":"⑤","c":"A","tp":"임차인의 매수청구권"},{"y":2024,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2024_30-02-1","t":"완성된 목적물 또는 완성 전의 성취된 부분에 하자가 있는 때에는 도급인은 수급인에 대하여 상당한 기간을 정하여 그 하자의 보수를 청구할 수 있다. 그러나 하자가 중요하지 아니한 경우에 그 보수에 과다한 비용을 요할 때에는 그러하지 아니하다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2024_30-02-2","t":"신축건물의 수급인으로부터 공사대금채권을 양수받은 자의 저당권설정청구에 의하여 신축건물의 도급인이 그 건물에 저당권을 설정하는 행위는 다른 특별한 사정이 없는 한 사해행위에 해당하지 아니한다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2024_30-02-3","t":"제작물공급계약은 그 제작의 측면에서는 도급의 성질이 있고 공급의 측면에서는 매매의 성질이 있어 대체로 매매와 도급의 성질을 함께 가지고 있으므로, 그 적용 법률은 계약에 의하여 제작 공급하여야 할 물건이 대체물인 경우에는 매매에 관한 규정이 적용되지만, 부대체물인 경우에는 도급의 성질을 띠게 된다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2024_30-02-4","t":"수급인의 담보책임에 관한 민법 제667조는 법이 특별히 인정한 무과실책임으로서 민법 제396조의 과실상계 규정이 준용될 수는 없다 하더라도 담보책임이 민법의 지도이념인 공평의 원칙에 입각한 것인 이상 하자발생 및 그 확대에 가공한 도급인의 잘못을 참작하여 손해배상의 범위를 정함이 상당하다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2024_30-02-5","t":"민법 제666조에 따른 수급인의 목적부동산에 대한 저당권설정청구권은 10년간 행사하지 않으면 소멸시효가 완성된다.","ox":"X","m":"⑤","c":"A","tp":"도급"},{"y":2024,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2024_30-05-1","t":"동업계약과 같은 조합계약에 있어서는 조합의 해산청구를 하거나 조합으로부터 탈퇴를 하거나 또는 다른 조합원을 제명할 수 있을 뿐이지 일반계약에 있어서처럼 조합계약을 해제하고 상대방에게 그로 인한 원상회복의 의무를 부담지울 수는 없는 것이다.","ox":"O","m":"①","c":"A","tp":"민법상 조합"},{"y":2024,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2024_30-05-2","t":"일부 조합원이 동업계약에 따라 동업자금을 출자하였는데 업무집행 조합원이 본연의 임무에 위배되거나 혹은 권한을 넘어선 행위를 자행함으로써 끝내 동업체의 동업 목적을 달성할 수 없게끔 만들고, 조합원이 출자한 동업자금을 모두 허비한 경우에 그로 인하여 손해를 입은 주체는 동업자금을 상실하여 버린 조합, 즉 조합원들로 구성된 동업체라 할 것이고, 이로 인하여 결과적으로 동업자금을 출자한 조합원에게 손해가 발생하였다 하더라도 이는 조합과 무관하게 개인으로서 입은 손해가 아니므로, 결국 피해자인 조합원으로서는 조합관계를 벗어난 개인의 지위에서 그 손해의 배상을 구할 수는 없다.","ox":"O","m":"②","c":"A","tp":"민법상 조합"},{"y":2024,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2024_30-05-3","t":"민법 제706조에서는 조합원 3분의 2 이상의 찬성으로 조합의 업무집행자를 선임하고 조합원 과반수의 찬성으로 조합의 업무집행방법을 결정하도록 규정하고 있는바, 여기서 말하는 조합원은 조합원의 인원수가 아닌 조합원의 출자가액이나 지분을 뜻한다.","ox":"X","m":"③","c":"A","tp":"민법상 조합"},{"y":2024,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2024_30-05-4","t":"조합원은 다른 조합원 전원의 동의가 있으면 그 지분을 처분할 수 있으나 조합의 목적과 단체성에 비추어 조합원으로서의 자격과 분리하여 그 지분권만을 처분할 수는 없다고 할 것이므로, 조합원이 지분을 양도하면 그로써 조합원의 지위를 상실하게 되며 이와 같은 조합원 지위의 변동은 조합지분의 양도양수에 관한 약정으로써 바로 효력이 생긴다.","ox":"O","m":"④","c":"A","tp":"민법상 조합"},{"y":2024,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2024_30-05-5","t":"조합계약에 ‘동업지분은 제3자에게 양도할 수 있다’는 약정을 두고 있는 것과 같이 조합계약에서 개괄적으로 조합원 지분의 양도를 인정하고 있는 경우 조합원은 다른 조합원 전원의 동의가 없더라도 자신의 지분 전부를 일체로써 제3자에게 양도할 수 있으나, 그 지분의 일부를 제3자에게 양도하는 경우까지 당연히 허용되는 것은 아니다.","ox":"O","m":"⑤","c":"A","tp":"민법상 조합"},{"y":2024,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2024_30-06-1","t":"상대부담있는 증여에 대하여는 증여자는 그 전체 부분에 대해 매도인과 같은 담보의 책임이 있다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2024_30-06-2","t":"증여의 의사가 서면으로 표시되지 아니한 경우에는 각 당사자는 이를 해제할 수 있으나, 이미 이행한 부분에 대하여는 영향을 미치지 아니한다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2024_30-06-3","t":"증여계약이 서면에 의하지 아니하였음을 이유로 한 해제에 대하여는 10년의 제척기간이 적용되지 아니한다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2024_30-06-4","t":"정기의 급여를 목적으로 한 증여는 증여자 또는 수증자의 사망으로 인하여 그 효력을 잃는다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2024_30-06-5","t":"민법 제104조가 규정하는 현저히 공정을 잃은 법률행위라 함은 자기의 급부에 비하여 현저하게 균형을 잃은 반대급부를 하게 하여 부당한 재산적 이익을 얻는 행위를 의미하는 것이므로, 증여계약과 같이 아무런 대가관계 없이 당사자 일방이 상대방에게 일방적인 급부를 하는 법률행위는 그 공정성 여부를 논의할 수 있는 성질의 법률행위가 아니다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2024_30-17-1","t":"매매계약의 일방 당사자가 사망하였고 그에게 여러 명의 상속인이 있는 경우에 그 상속인들이 위 계약을 해제하려면, 상대방과 사이에 다른 내용의 특약이 있다는 등의 특별한 사정이 없는 한 상속인들 전원이 해제의 의사표시를 하여야 한다.","ox":"O","m":"①","c":"A","tp":"계약의 해제"},{"y":2024,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2024_30-17-2","t":"매매계약이 해제된 후에도 매도인이 별다른 이의 없이 일부 변제를 수령한 경우 특별한 사정이 없는 한 당사자 사이에 해제된 계약을 부활시키는 약정이 있었다고 해석함이 상당하고, 이러한 경우 매도인으로서는 새로운 이행의 최고 없이 바로 해제권을 행사할 수 없다.","ox":"O","m":"②","c":"A","tp":"계약의 해제"},{"y":2024,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2024_30-17-3","t":"민법 제548조 제1항 단서에서 규정하는 해제의 효과에도 보호받는 제3자는 일반적으로 그 해제된 계약으로부터 생긴 법률효과를 기초로 하여 해제 전에 새로운 이해관계를 가졌을 뿐 아니라 등기·인도 등으로 완전한 권리를 취득한 자를 의미하므로, 계약이 해제되기 이전에 계약상의 채권을 양수하여 이를 피보전권리로 하여 처분금지가처분결정을 받은 경우 그 채권자는 민법 제548조 제1항 단서 소정의 해제의 소급효가 미치지 아니하는 ‘제3자’에 해당한다.","ox":"X","m":"③","c":"A","tp":"계약의 해제"},{"y":2024,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2024_30-17-4","t":"계약 해제의 효과로서 원상회복의무를 규정하는 민법 제548조 제1항 본문은 부당이득에 관한 특별규정의 성격을 가지는 것으로서, 그 이익 반환의 범위는 이익의 현존 여부나 청구인의 선의·악의를 불문하고 특단의 사유가 없는 한 받은 이익의 전부이다.","ox":"O","m":"④","c":"A","tp":"계약의 해제"},{"y":2024,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2024_30-17-5","t":"계약의 해제로 인한 원상회복청구권에 대하여 해제자가 해제의 원인이 된 채무불이행에 관하여 ‘원인’의 일부를 제공하였다는 등의 사유를 내세워 신의칙 또는 공평의 원칙에 기하여 일반적으로 손해배상에 있어서의 과실상계에 준하여 권리의 내용이 제한될 수 있다고 하는 것은 허용되지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2024_30-23-1","t":"민법 제564조가 정하고 있는 매매예약에서 예약자의 상대방이 매매예약 완결의 의사표시를 하여 매매의 효력을 생기게 하는 권리, 즉 매매예약의 완결권은 일종의 형성권으로서 당사자 사이에 행사기간을 약정한 때에는 그 기간 내에, 약정이 없는 때에는 예약이 성립한 때부터 10년 내에 이를 행사하여야 하고, 그 기간이 지난 때에는 예약완결권은 제척기간의 경과로 소멸한다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2024_30-23-2","t":"상대방인 매도인이 매매계약의 이행에는 전혀 착수한 바가 없는 경우에는 매수인이 중도금을 지급하여 이미 이행에 착수하였더라도 상대방인 매도인으로서는 필요한 비용을 지출하는 등 예측하지 못한 손해를 입게될 우려가 없다고 할 것이므로, 매수인은 민법 제565조에 의하여 계약금을 포기하고 매매계약을 해제할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2024_30-23-3","t":"매매예약이 성립한 이후 상대방의 매매예약 완결의 의사표시 전에 목적물이 멸실 기타의 사유로 이전할 수 없게 되어 예약 완결권의 행사가 이행불능이 된 경우에는 예약 완결권을 행사할 수 없고, 이행불능 이후에 상대방이 매매예약 완결의 의사표시를 하여도 매매의 효력이 생기지 아니한다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2024_30-23-4","t":"매매계약에서 계약금의 일부만 지급된 경우 수령자가 매매계약을 해제할 수 있다고 하더라도 해약금의 기준이 되는 금원은 ‘실제 교부받은 계약금’이 아니라 ‘약정 계약금’이라고 봄이 타당하므로, 매도인이 계약금의 일부로서 지급받은 금원의 배액을 상환하는 것으로는 매매계약을 해제할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2024_30-23-5","t":"민법 제565조가 해제권 행사의 시기를 당사자의 일방이 이행에 착수할 때까지로 제한한 것은 당사자의 일방이 이미 이행에 착수한 때에는 그 당사자는 그에 필요한 비용을 지출하였을 것이고, 또 그 당사자는 계약이 이행될 것으로 기대하고 있는데 만일 이러한 단계에서 상대방으로부터 계약이 해제된다면 예측하지 못한 손해를 입게 될 우려가 있으므로 이를 방지하고자 함에 있고, 이행기의 약정이 있는 경우라 하더라도 당사자가 채무의 이행기 전에는 착수하지 아니하기로 하는 특약을 하는 등 특별한 사정이 없는 한 이행기 전에 이행에 착수할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"매매"},{"y":2024,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2024_30-26-1","t":"예금계약은 예금자가 예금의 의사를 표시하면서 금융기관에 돈을 제공하고 금융기관이 그 의사에 따라서 그 돈을 받아 확인을 하면 그로써 성립하며, 금융기관의 직원이 그 받은 돈을 금융기관에 입금하지 아니하고 이를 횡령하였다고 하더라도 예금계약의 성립에는 아무런 영향이 없다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2024_30-26-2","t":"예금거래기본약관에 따라 송금의뢰인이 수취인의 예금계좌에 자금이체를 하여 예금원장에 입금의 기록이 된 때에는 특별한 사정이 없는 한 송금의뢰인과 수취인 사이에 자금이체의 원인인 법률관계가 존재하는지에 관계없이 수취인과 수취은행 사이에는 입금액 상당의 예금계약이 성립하고, 수취인은 수취은행에 대하여 입금액 상당의 예금채권을 취득한다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2024_30-26-3","t":"출금계좌의 예금주가 수취인 앞으로의 계좌이체에 대하여 지급지시를 하거나 수취인의 추심이체에 관하여 출금 동의 등을 한 바가 없는데도, 은행이 그와 같은 지급지시나 출금 동의가 있는 것으로 착오를 일으켜 출금계좌에서 예금을 인출한 다음 이를 수취인의 예금계좌에 입금하여 그 기록이 완료된 때에도 수취인과 수취은행 사이에는 입금액 상당의 예금계약이 성립하고, 수취인은 수취은행에 대하여 입금액 상당의 예금채권을 취득한다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2024_30-26-4","t":"송금의뢰인이 착오송금임을 이유로 거래은행을 통하여 혹은 수취은행에 직접 송금액의 반환을 요청하고 수취인도 송금의뢰인의 착오송금에 의하여 수취인의 계좌에 금원이 입금된 사실을 인정하고 수취은행에 그 반환을 승낙하고 있는 경우, 수취은행이 수취인에 대한 대출채권 등을 자동채권으로 하여 수취인의 계좌에 착오로 입금된 금원 상당의 예금채권과 상계하는 것은 원칙적으로 가능하다.","ox":"X","m":"④","c":"A","tp":"예금계약"},{"y":2024,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2024_30-26-5","t":"만기가 정해진 예금계약에 따른 금융기관의 예금 반환채무는 만기가 도래하더라도 임치인이 미리 만기 후 예금 수령방법을 지정한 경우와 같은 특별한 사정이 없는 한 임치인의 적법한 지급 청구가 있어야 비로소 이행할 수 있으므로, 예금계약의 만기가 도래한 것만으로 금융기관인 수치인이 임치인에 대하여 예금 반환 지연으로 인한 지체책임을 부담한다고 볼 수는 없다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2024_30-27-1","t":"기존의 원인채권과 어음채권이 병존하는 경우에 채권자가 원인채권을 행사함에 있어서 채무자는 원칙적으로 어음과 상환으로 지급하겠다고 하는 항변으로 채권자에게 대항할 수 있다. 따라서 어음상 권리가 시효완성으로 소멸하여 채무자에게 이중지급의 위험이 없고 채무자가 다른 어음상 채무자에 대하여 권리를 행사할 수도 없는 경우이더라도 채권자의 원인채권 행사에 대하여 채무자에게 어음상환의 동시이행항변을 인정할 필요가 있다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2024_30-27-2","t":"토지 임차인의 매수청구권 행사로 지상 건물에 대하여 시가에 의한 매매 유사의 법률관계가 성립된 경우에는 임차인의 건물명도 및 그 소유권이전등기의무와 토지 임대인의 건물대금지급의무는 서로 대가관계에 있는 채무가 되므로, 임차인이 임대인에게 매수청구권이 행사된 건물들에 대한 명도와 소유권이전등기를 마쳐주지 아니하였다면 임대인에게 그 매매대금에 대한 지연손해금을 구할 수 없다.","ox":"O","m":"②","c":"A","tp":"동시이행항변"},{"y":2024,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2024_30-27-3","t":"매수인이 매매의 목적이 된 부동산을 명도받기 전에 잔대금을 먼저 지급하기로 약정한 매매의 경우에, 매수인이 잔대금지급채무를 이행하지 아니하였다고 하더라도 매매계약이 해제되지 아니한 상태에서 부동산의 명도기일이 지날 때까지 부동산이 명도되지 아니하였다면, 그때부터는 매수인의 잔대금지급채무와 매도인의 부동산명도의무는 동시이행의 관계에 있게 된다.","ox":"O","m":"③","c":"A","tp":"동시이행항변"},{"y":2024,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2024_30-27-4","t":"동시이행의 항변권은 상대방의 채무이행이 있기까지 자신의 채무이행을 거절할 수 있는 권리이므로, 매수인이 매도인을 상대로 매매목적 부동산 중 일부에 대해서만 소유권이전등기의무의 이행을 구하고 있는 경우에도 매도인은 특별한 사정이 없는 한 그 매매잔대금 전부에 대하여 동시이행의 항변권을 행사할 수 있다고 할 것이다.","ox":"O","m":"④","c":"A","tp":"동시이행항변"},{"y":2024,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2024_30-27-5","t":"항변권이 부착되어 있는 채권을 자동채권으로 하여 타의 채무와의 상계를 허용한다면 상계가 일방의 의사표시에 의하여 상대방의 항변권행사의 기회를 상실케 하는 결과가 되므로 이와 같은 상계는 그 성질상 허용할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"동시이행항변"},{"y":2024,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2024_30-32-1","t":"준소비대차계약이 성립하려면 당사자 사이에 금전 기타의 대체물의 급부를 목적으로 하는 기존 채무가 존재하여야 하고, 기존 채무가 존재하지 않거나 또는 존재하고 있더라도 그것이 무효가 된 때에는 준소비대차계약은 효력이 없으며, 준소비대차계약의 채무자가 기존 채무의 부존재를 주장하는 이상 채권자로서는 기존 채무의 존재를 증명할 책임이 있다.","ox":"O","m":"①","c":"A","tp":"소비대차, 준소비대차"},{"y":2024,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2024_30-32-2","t":"민법상 소비대차는 이른바 낙성계약이므로, 차주가 현실로 금전 등을 수수하거나 현실의 수수가 있은 것과 같은 경제적 이익을 취득하여야만 소비대차가 성립하는 것은 아니고, 반대로 당사자 일방이 상대방에게 현실로 금전 기타 대체물의 소유권을 이전하였다고 하더라도 상대방이 같은 종류, 품질 및 수량으로 반환할 것을 약정한 경우가 아니라면 이들 사이의 법률행위를 소비대차라 할 수 없다.","ox":"O","m":"②","c":"A","tp":"소비대차, 준소비대차"},{"y":2024,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2024_30-32-3","t":"반환시기에 관하여 약정이 없는 소비대차에 있어서 반환의 최고는 소장의 송달로도 할 수 있다.","ox":"O","m":"③","c":"A","tp":"소비대차, 준소비대차"},{"y":2024,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2024_30-32-4","t":"당사자 사이에 부동산에 관한 대물반환의 예약 내지는 양도담보의 약정을 맺은 경우, 채무자는 채권자에게 그 피담보채무를 변제함으로써 약정에 따른 소유권이전등기절차 이행의무 자체를 소멸시킬 수 있고, 나아가 채권자 앞으로 소유권이전등기가 경료된 후에는 채권자로부터 청산금 채권을 변제받을 때까지 채권자 앞으로 경료된 소유권이전등기의 말소를 청구할 수는 있으나, 한편 채무자는 채권자에게 소유권이전등기절차 이행의무를 부담하므로 채무자의 그 부동산에 관한 근저당권설정등기 말소청구가 허용될 수는 없다.","ox":"X","m":"④","c":"A","tp":"소비대차, 준소비대차"},{"y":2024,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2024_30-32-5","t":"금전소비대차계약이 성립된 이후에 차주의 신용불안이나 재산상태의 현저한 변경이 생겨 장차 대주의 대여금반환청구권 행사가 위태롭게 되는 등 사정변경이 생기고 이로 인하여 당초의 계약내용에 따른 대여의무를 이행케 하는 것이 공평과 신의칙에 반하게 되는 경우에 대주는 대여의무의 이행을 거절할 수 있다고 보아야 한다.","ox":"O","m":"⑤","c":"A","tp":"소비대차, 준소비대차"},{"y":2024,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2024_30-35","t":"임대차에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"임대차에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["임대차기간을 2019. 3. 10.부터 2021. 3. 9.까지로 정한 주택임대차보호법 적용 사안에서, 임차인의 갱신요구 통지가 2021. 1. 5. 임대인에게 도달하였고, 그 후 임차인의 갱신된 임대차계약에 대한 해지 취지가 기재된 통지서가 2021. 1. 29. 임대인에게 도달하였다면, 그로부터 3개월이 지난 2021. 4. 29. 갱신된 임대차계약의 해지 효력이 발생하였다고 보아야 한다.","주택임대차보호법 제3조의3에서 정한 임차권등기명령에 따른 임차권등기에는 민법 제168조 제2호에서 정하는 소멸시효 중단사유인 압류 또는 가압류, 가처분에 준하는 효력이 있다고 볼 수 없다.","주택임대차보호법 제6조의3 제1항 제8호에서 정한 “임대인(임대인의 직계존속․직계비속을 포함한다)이 목적 주택에 실제 거주하려는 경우”에 해당한다는 점에 대한 증명책임은 임대인에게 있고, ‘실제 거주하려는 의사’의 존재는 임대인이 단순히 그러한 의사를 표명하였다는 사정이 있다고 하여 곧바로 인정될 수는 없다.","주택임대차보호법 제3조 제3항에서 말하는 ‘직원’은, 해당 법인이 주식회사라면 그 법인에서 근무하는 사람 중 법인등기사항증명서에 대표이사 또는 사내이사로 등기된 사람을 제외한 사람을 의미한다고 보아야 한다. 다만 위와 같은 범위의 임원을 제외한 직원이 법인이 임차한 해당 주택을 인도받아 주민등록을 마치고 그곳에서 거주하고 있다고 하더라도 업무관련성, 임대료의 액수, 지리적 근접성 등 제반 사정을 고려하여 위 조항에서 정한 대항력을 갖추었는지 여부를 판단하여야 한다.","임대인의 필요비상환의무는 특별한 사정이 없는 한 임차인의 차임지급의무와 서로 대응하는 관계에 있으므로, 임차인은 지출한 필요비 금액의 한도에서 차임의 지급을 거절할 수 있다."],"a":4}},{"y":2024,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2024_30-36-1","t":"여행자는 여행을 시작하기 전에는 언제든지 계약을 해제할 수 있다. 다만, 여행자는 상대방에게 발생한 손해를 배상하여야 한다.","ox":"O","m":"①","c":"A","tp":"여행계약"},{"y":2024,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2024_30-36-2","t":"여행자가 해외 여행계약에 따라 여행하는 도중 여행업자의 고의 또는 과실로 상해를 입은 경우 계약상 여행업자의 여행자에 대한 국내로의 귀환운송의무가 예정되어 있고, 현지에서 당초 예정한 여행기간 내에 치료를 완료하기 어렵거나, 계속적·전문적 치료가 요구되어 사회통념상 여행자가 국내로 귀환할 필요성이 있었다고 인정된다면, 이로 인하여 발생하는 귀환운송비 등 추가적인 비용은 여행업자의 고의 또는 과실로 인하여 발생한 통상손해의 범위에 포함된다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2024_30-36-3","t":"민법 제674조의6(여행주최자의 담보책임)과 민법 제674조의7(여행주최자의 담보책임과 여행자의 해지권)에 따른 권리는 여행 기간 중에도 행사할 수 있으며, 계약에서 정한 여행 종료일부터 1년 내에 행사하여야 한다.","ox":"X","m":"③","c":"A","tp":"여행계약"},{"y":2024,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2024_30-36-4","t":"기획여행업자는 통상 여행 일반은 물론 목적지의 자연적·사회적 조건에 관하여 전문적 지식을 가진 자로서 우월적 지위에서 행선지나 여행시설 이용 등에 관한 계약 내용을 일방적으로 결정하는 반면, 여행자는 안전성을 신뢰하고 기획여행업자가 제시하는 조건에 따라 여행계약을 체결하는 것이 일반적이므로, 기획여행업자는 여행자에게 여행계약 내용의 실시 도중에 여행자가 부딪칠지 모르는 위험을 고지함으로써 여행자 스스로 위험을 수용할지에 관하여 선택할 기회를 주는 등 합리적 조치를 취할 신의칙상 안전배려의무를 부담한다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2024_30-36-5","t":"부득이한 사유가 있는 경우에는 각 당사자는 여행계약을 해지할 수 있고, 그 해지로 인하여 발생하는 추가 비용은 그 해지 사유가 어느 당사자의 사정에 속하는 경우에는 그 당사자가 부담하고, 누구의 사정에도 속하지 아니하는 경우에는 각 당사자가 절반씩 부담한다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2025_31-16-1","t":"구분건물의 소유권 취득을 목적으로 하는 매매계약에서 매도인의 소유권이전의무가 원시적 불능이어서 계약이 무효라고 하기 위해서는 매매 목적물이 ‘매매계약 당시’ 구분건물로서 구조상, 이용상 독립성을 구비하지 못했다는 정도에 이르면 되고, ‘그 후로도’ 매매 목적물이 당사자 사이에 약정된 내용에 따른 구조상, 이용상 독립성을 갖추는 것이 사회통념상 불가능하다고 평가될 정도에 이를 것까지 요구되지는 않는다.","ox":"X","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2025_31-16-2","t":"계약의 내용이 된 채무를 이행하는 것이 계약 당시부터 이미 사실상·법률상 불가능한 상태였다면 그 계약은 원시적으로 불능이어서 무효이다. 채무의 이행이 불가능하다는 것은 절대적·물리적으로 불가능한 경우만이 아니라 사회생활상 경험칙이나 거래상의 관념에 비추어 볼 때 채권자가 채무자의 이행 실현을 기대할 수 없는 경우도 포함한다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2025_31-16-3","t":"토지의 일부를 특정하여 매수하고 토지를 분할하여 그 특정부분에 대한 소유권이전등기를 넘겨받기로 약정하였으나 그 매수인이 불법증축한 부분으로 인하여 인근지번과의 인동거리가 건축법규상 제한거리에 미달하기 때문에 분할이전등기를 못한 경우 그러한 공법상 제한은 불법증축한 부분만 철거한다면 얼마든지 해제될 수 있는 것이어서 분할약정에 따른 상대방의 분할등기이전의무는 원시적 불능에 속하는 것이라고 할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2025_31-16-4","t":"당사자 일방의 채무가 원시적 이행불능이면 계약은 무효이므로 상대방은 계약체결에 있어서의 과실을 이유로 하는 신뢰이익 손해배상을 구할 수 있을지언정 이행에 대신하는 전보배상을 구할 수는 없다. 한편, 후발적 이행불능의 경우 이행에 대신하는 전보배상은 이행불능이 된 시기의 손해액이다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2025_31-16-5","t":"목적이 불능한 계약을 체결할 때에 그 불능을 알았거나 알 수 있었을 자는 상대방이 그 계약의 유효를 믿었음으로 인하여 받은 손해를 배상하여야 한다. 그러나 그 배상액은 계약이 유효함으로 인하여 생길 이익액을 넘지 못한다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2025_31-17-1","t":"계약이 합의에 따라 해제되거나 해지된 경우에는 상대방에게 손해배상을 하기로 특약하거나 손해배상청구를 유보하는 의사표시를 하는 등 다른 사정이 없는 한 채무불이행으로 인한 손해배상을 청구할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2025_31-17-2","t":"계약의 합의해제는 묵시적으로 이루어질 수도 있으나, 계약이 묵시적으로 합의해제되었다고 하려면 계약의 성립 후에 당사자 쌍방의 계약실현의사의 결여 또는 포기로 인하여 당사자 쌍방의 계약을 실현하지 아니할 의사가 일치되어야 한다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2025_31-17-3","t":"해제권자의 고의나 과실로 인하여 계약의 목적물이 현저히 훼손되거나 이를 반환할 수 없게 된 때 또는 가공이나 개조로 인하여 다른 종류의 물건으로 변경된 때에는 해제권은 소멸한다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2025_31-17-4","t":"채무자가 이행해야 할 본래 채무가 이행불능이라는 이유로 계약을 해제하려고 할 때, 그 이행불능의 대상이 되는 채무자의 본래 채무가 유효하게 존속할 필요는 없다.","ox":"X","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2025_31-17-5","t":"민법 제548조 제2항은 계약해제로 인한 원상회복의무의 이행으로서 반환하는 금전에는 그 받은 날로부터 이자를 가산하여야 한다고 하고 있는바, 위 이자의 반환은 원상회복의무의 범위에 속하는 것으로 일종의 부당이득반환의 성질을 가지는 것이지 반환의무의 이행지체로 인한 손해배상은 아니라고 할 것이다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2025_31-19-1","t":"송금 등 금전지급행위가 증여에 해당하기 위해서는 객관적으로 채무자와 수익자 사이에 금전을 무상으로 수익자에게 종국적으로 귀속시키는 데에 의사의 합치가 있어야 한다. 다른 사람의 예금계좌에 금전을 이체하는 등으로 송금하는 경우 다양한 원인이 있을 수 있는데, 과세 당국 등의 추적을 피하기 위하여 일정한 인적 관계에 있는 사람이 그 소유의 금전을 자신의 예금계좌로 송금한다는 사실을 알면서 그에게 자신의 예금계좌로 송금할 것을 승낙 또는 양해하였다거나 그러한 목적으로 자신의 예금계좌를 사실상 지배하도록 용인하였다는 것만으로는 특별한 사정이 없는 한 송금인과 계좌명의인 사이에 송금액을 계좌명의인에게 무상으로 증여한다는 의사의 합치가 있었다고 쉽사리 추단할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2025_31-19-2","t":"민법 제555조는 “증여의 의사가 서면으로 표시되지 아니한 경우에는 각 당사자는 이를 해제할 수 있다.”고 함으로써 서면에 의한 증여의 해제를 제한하고 있는바, 법적 안정성을 추구하고자 하는 위 규정의 취지상 서면에 의한 증여가 이루어졌다면 증여자가 착오에 기한 의사표시라는 이유로 민법 총칙규정에 따라 증여의 의사표시를 취소할 수도 없다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2025_31-19-3","t":"상대부담 있는 증여에 대하여는 민법 제561조에 의하여 쌍무계약에 관한 규정이 준용되어 부담의무 있는 상대방이 자신의 의무를 이행하지 아니할 때에는 비록 증여계약이 이미 이행되어 있다 하더라도 증여자는 계약을 해제할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2025_31-19-4","t":"민법 제562조는 사인증여에 관하여는 유증에 관한 규정을 준용하도록 규정하고 있지만, 유증의 방식에 관한 민법 제1065조 내지 제1072조는 그것이 단독행위임을 전제로 하는 것이어서 계약인 사인증여에는 적용되지 아니한다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2025_31-19-5","t":"민법 제562조가 사인증여에 관하여 유증에 관한 규정을 준용하도록 규정하고 있다고 하여, 이를 근거로 포괄적 유증을 받은 자는 상속인과 동일한 권리의무가 있다고 규정하고 있는 민법 제1078조가 포괄적 사인증여에도 준용된다고 해석할 수는 없다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2025_31-22-1","t":"임차인이 불이행한 원상회복의무가 사소한 부분이고 그로 인한 손해배상액 역시 근소한 금액인 경우에까지 임대인이 그를 이유로, 임차인이 그 원상회복의무를 이행할 때까지 혹은 임대인이 현실로 목적물의 명도를 받을 때까지 원상회복의무 불이행으로 인한 손해배상액 부분을 넘어서서 거액의 잔존 임대차보증금 전액에 대하여 그 반환을 거부할 수 있다고 하는 것은 오히려 공평의 관념에 반하는 것이 되어 부당하고, 그와 같은 임대인의 동시이행의 항변은 신의칙에 반하는 것이 되어 허용할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2025_31-22-2","t":"가압류등기 등이 있는 부동산의 매매계약에 있어 매도인의 소유권이전등기 의무와 아울러 가압류등기의 말소의무도 매수인의 대금지급의무와 동시이행 관계에 있다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2025_31-22-3","t":"양 채무가 동일한 법률요건으로부터 생겨서 공평의 관점에서 보아 견련적으로 이행시킴이 마땅한 경우에는 동시이행관계가 인정되므로, 채무담보를 위하여 경료된 근저당권설정등기의 말소와 채무의 변제는 동시이행의 관계에 있다.","ox":"X","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2025_31-22-4","t":"매도인의 매매계약상의 소유권이전등기의무가 이행불능이 되어 이를 이유로 매매계약을 해제함에 있어서는 상대방의 잔대금지급의무가 매도인의 소유권이전등기의무와 동시이행관계에 있다고 하더라도 그 이행의 제공을 필요로 하는 것이 아니다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2025_31-22-5","t":"임대인과 임차인이 임대차계약을 체결하면서 임대차보증금을 전세금으로 하는 전세권설정등기를 경료한 경우 임대차보증금은 전세금의 성질을 겸하게 되므로, 당사자 사이에 다른 약정이 없는 한 임대차보증금 반환의무는 민법 제317조에 따라 전세권설정등기의 말소의무와도 동시이행관계에 있다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2025_31-38-1","t":"임대차계약에 있어서 임대인은 목적물을 계약 존속 중 그 사용·수익에 필요한 상태를 유지하게 할 의무를 부담하는 것이므로, 목적물에 파손 또는 장해가 생긴 경우 그것이 임차인이 별 비용을 들이지 아니하고도 손쉽게 고칠 수 있을 정도의 사소한 것이어서 임차인의 사용·수익을 방해할 정도의 것이 아니라면 임대인은 수선의무를 부담하지 않지만, 그것을 수선하지 아니하면 임차인이 계약에 의하여 정해진 목적에 따라 사용·수익할 수 없는 상태로 될 정도의 것이라면 임대인은 그 수선의무를 부담한다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2025_31-38-2","t":"임대차는 당사자 일방이 상대방에게 목적물을 사용·수익하게 할 것을 약정하고 상대방이 이에 대하여 차임을 지급할 것을 약정함으로써 성립하는 것으로, 임대인이 임대차 목적물에 대한 소유권 기타 이를 임대할 권한이 없다고 하더라도 임대차계약은 유효하게 성립한다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2025_31-38-3","t":"주택임대차보호법이 적용되는 임대차가 되기 위해서는 임차인과 주택의 소유자인 임대인 사이에 임대차계약이 체결된 경우로 한정되는 것도 아니고, 그 주택에 관하여 적법하게 임대차계약을 체결할 수 있는 권한을 가진 임대인이 임대차계약을 체결할 것이 요구되지도 않는다.","ox":"X","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2025_31-38-4","t":"임차인의 임차목적물 반환의무는 임대차계약의 종료에 의하여 발생하나, 임대인의 권리금 회수 방해로 인한 손해배상의무는 상가건물 임대차보호법에서 정한 권리금 회수기회 보호의무 위반을 원인으로 하고 있으므로 양 채무는 동일한 법률요건이 아닌 별개의 원인에 기하여 발생한 것일 뿐 아니라 공평의 관점에서 보더라도 그 사이에 이행상 견련관계를 인정하기 어렵다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2025_31-38-5","t":"건물의 소유를 목적으로 한 토지임대차계약의 기간이 만료함에 따라 지상건물 소유자가 임대인에 대하여 행사하는 민법 제643조 소정의 매수청구권은 매수청구의 대상이 되는 건물에 근저당권이 설정되어 있는 경우에도 인정된다. 이 경우에 그 건물의 매수가격은 건물 자체의 가격 외에 건물의 위치, 주변 토지의 여러 사정 등을 종합적으로 고려하여 매수청구권 행사 당시 건물이 현존하는 대로의 상태에서 평가된 시가 상당액을 의미하고, 여기에서 근저당권의 채권최고액이나 피담보채무액을 공제한 금액을 매수가격으로 정할 것은 아니다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2026_32-09-1","t":"제3자를 위한 계약관계에서 낙약자와 요약자 사이의 법률관계(기본관계)를 이루는 계약이 무효이거나 해제된 경우 그 계약관계의 청산은 계약의 당사자인 낙약자와 요약자 사이에 이루어져야 하므로, 특별한 사정이 없는 한 낙약자가 이미 제3자에게 급부한 것이 있더라도 낙약자는 계약해제 등에 기한 원상회복 또는 부당이득을 원인으로 제3자를 상대로 그 반환을 구할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2026_32-09-2","t":"제3자가 수익의 의사표시를 함으로써 제3자에게 권리가 확정적으로 귀속된 경우에는, 요약자와 낙약자의 합의에 의하여 제3자의 권리를 변경⋅소멸시킬 수 있음을 미리 유보하였거나, 제3자의 동의가 있는 경우가 아니면 계약의 당사자인 요약자와 낙약자는 제3자의 권리를 변경⋅소멸시키지 못하고, 만일 계약의 당사자가 제3자의 권리를 임의로 변경⋅소멸시키는 행위를 한 경우 이는 제3자에 대하여 효력이 없다.","ox":"O","m":"②","c":"A","tp":"제3자를 위한 계약"},{"y":2026,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2026_32-09-3","t":"낙약자와 요약자 사이의 법률관계에 기초하여 수익자가 요약자와 원인관계(대가관계)를 맺음으로써 해제 전에 새로운 이해관계를 갖고 그에 따라 등기, 인도 등을 마쳐 권리를 취득하였다면, 수익자는 민법 제548조 제1항 단서에서 말하는 계약해제의 소급효가 제한되는 제3자에 해당한다.","ox":"O","m":"③","c":"A","tp":"제3자를 위한 계약"},{"y":2026,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2026_32-09-4","t":"제3자를 위한 계약에서 제3자는 채무자에 대하여 계약의 이익을 받을 의사를 표시한 때에 채무자에게 직접 이행을 청구할 수 있는 권리를 취득하므로, 이와 별도로 요약자가 낙약자에 대하여 제3자에게 급부를 이행할 것을 요구할 수 있는 권리를 가진다고 볼 것은 아니다.","ox":"X","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2026_32-09-5","t":"제3자를 위한 계약이 성립하기 위하여는 일반적으로 그 계약의 당사자가 아닌 제3자로 하여금 직접 권리를 취득하게 하는 조항이 있어야 할 것이지만, 계약의 당사자가 제3자에 대하여 가진 채권에 관하여 그 채무를 면제하는 계약도 제3자를 위한 계약에 준하는 것으로서 유효하다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2026_32-24-1","t":"민법상 조합에서 조합원 지분의 양도는 원칙적으로 다른 조합원 전원의 동의가 있어야 하지만, 다른 조합원의 동의 없이 각자 지분을 자유로이 양도할 수 있도록 조합원 상호 간에 약정하거나 사후적으로 지분 양도를 인정하는 합의를 하는 것은 유효하다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2026_32-24-2","t":"민법상 조합에서 조합의 채권자가 조합원에 대해 조합재산에 의한 공동책임을 묻는 것이 아니라 각 조합원의 개인적 책임에 기해 당해 채권을 행사하는 경우에는 조합원 각자를 상대로 이행의 소를 제기할 수 있고 그 보전행위인 가압류를 할 수 있으므로, 조합원 중 1인만을 가압류채무자로 한 가압류명령으로써 조합재산에 가압류집행을 할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2026_32-24-3","t":"조합의 채권은 조합원 전원에게 합유적으로 귀속하는 것이어서, 특별한 사정이 없는 한 조합원 중 1인이 임의로 조합의 채무자에 대하여 출자지분의 비율에 따른 급부를 청구할 수 없는 것이다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2026_32-24-4","t":"2인으로 구성된 조합에서 한 사람이 탈퇴하면 조합관계는 종료되나 특별한 사정이 없는 한 조합은 해산이나 청산이 되지 않고, 다만 조합원의 합유에 속한 조합재산은 남은 조합원의 단독소유에 속하여 탈퇴 조합원과 남은 조합원 사이에는 탈퇴로 인한 계산을 해야 한다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2026_32-24-5","t":"동업계약과 같은 조합계약에서는 조합의 해산청구를 하거나 조합으로부터 탈퇴를 하거나 또는 다른 조합원을 제명할 수 있을 뿐이지 일반계약에서처럼 조합계약을 해제 또는 해지하고 상대방에게 그로 인한 원상회복의 의무를 부담지울 수는 없다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2026_32-29-1","t":"당사자 사이에 계약을 종료시킬 의사가 일치되었더라도 계약 종료에 따른 법률관계가 당사자들에게 중요한 관심사인 경우 그러한 법률관계에 관하여 아무런 약정 없이 계약을 종료시키는 합의만 하는 것은 경험칙에 비추어 이례적이므로 이 경우 쉽사리 합의해지가 성립하였다고 보아서는 안 된다.","ox":"O","m":"①","c":"A","tp":"계약의 해제 또는 해지"},{"y":2026,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2026_32-29-2","t":"계약의 합의해지는 계속적 채권채무관계에서 당사자가 이미 체결한 계약의 효력을 장래에 향하여 소멸시킬 것을 내용으로 하는 새로운 계약으로서, 이를 인정하기 위해서는 계약이 성립하는 경우와 마찬가지로 기존 계약의 효력을 장래에 향하여 소멸시키기로 하는 내용의 청약과 승낙이라는 서로 대립하는 의사표시가 객관적으로 합치되어야 하므로 계약의 합의해지는 묵시적으로 이루어질 수는 없다.","ox":"X","m":"②","c":"A","tp":"계약의 해제 또는 해지"},{"y":2026,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2026_32-29-3","t":"계약 성립의 기초가 된 사정이 현저히 변경되고 당사자가 계약의 성립 당시 이를 예견할 수 없었으며, 그로 인하여 계약을 그대로 유지하는 것이 당사자의 이해에 중대한 불균형을 초래하거나 계약을 체결한 목적을 달성할 수 없는 경우에는 계약준수 원칙의 예외로서 사정변경을 이유로 계약을 해제하거나 해지할 수 있다.","ox":"O","m":"③","c":"A","tp":"계약의 해제 또는 해지"},{"y":2026,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2026_32-29-4","t":"민법 제548조 제1항 단서에서 정한 계약해제의 소급효가 제한되는 제3자는 일반적으로 그 해제된 계약으로부터 생긴 법률효과를 기초로 하여 해제 전에 새로운 이해관계를 가졌을 뿐만 아니라 등기, 인도 등으로 권리를 취득한 사람을 말한다.","ox":"O","m":"④","c":"A","tp":"계약의 해제 또는 해지"},{"y":2026,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2026_32-29-5","t":"계약이 합의에 따라 해제되거나 해지된 경우에는 특별한 사정이 없는 한 채무불이행으로 인한 손해배상을 청구할 수 없으나, 상대방에게 손해배상을 하기로 특약하거나 손해배상 청구를 유보하는 의사표시가 있으면 그러한 특약이나 의사에 따라 손해배상을 하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"계약의 해제 또는 해지"},{"y":2026,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2026_32-38-1","t":"종류매매에서 매수인이 가지는 완전물급부청구권을 제한 없이 인정하는 경우에는 오히려 매도인에게 지나친 불이익이나 부당한 손해를 주어 등가관계를 파괴하는 결과를 낳을 수 있으므로, 매매목적물의 하자가 경미하여 수선 등의 방법으로도 계약의 목적을 달성하는 데 별다른 지장이 없는 반면 매도인에게 하자 없는 물건의 급부의무를 지우면 다른 구제방법에 비하여 지나치게 큰 불이익이 매도인에게 발생되는 경우와 같이 하자담보의무의 이행이 오히려 공평의 원칙에 반하는 경우에는 완전물급부청구권의 행사를 제한할 수 있다.","ox":"O","m":"①","c":"A","tp":"매도인의 담보책임"},{"y":2026,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2026_32-38-2","t":"매도인이 타인의 권리를 매수인에게 이전하기 전에 어느 사유로 인하여 이행불능이 된 경우에는 매도인은 이전의무를 이행할 수 없는 것에 따른 하자담보책임을 져야 하는 것이나, 그 이행할 수 없는 사유가 오직 매수인의 책임으로 인한 것이라면 매수인은 이행불능된 사실만을 앞세워 매도인에게 하자담보책임을 물을 수는 없다.","ox":"O","m":"②","c":"A","tp":"매도인의 담보책임"},{"y":2026,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2026_32-38-3","t":"매수인이 강제경매절차를 통하여 부동산의 매각대금을 완납하고 그 앞으로 소유권이전등기까지 마쳤으나 그 후 강제경매절차의 기초가 된 채무자 명의의 소유권이전등기가 원인무효의 등기이어서 경매절차가 무효로 되어 경매 부동산에 대한 소유권을 취득하지 못하게 된 경우, 매수인은 민법 제578조 제1항, 제2항에 따라 경매의 채무자나 채권자에게 담보책임을 물을 수 있다.","ox":"X","m":"③","c":"A","tp":"매도인의 담보책임"},{"y":2026,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2026_32-38-4","t":"민법 제574조에서 규정하는 ‘수량을 지정한 매매’라 함은 당사자가 매매의 목적인 특정물이 일정한 수량을 가지고 있다는 데 주안을 두고 대금도 그 수량을 기준으로 하여 정한 경우를 말하는 것이므로, 토지의 매매에 있어 목적물을 등기부상의 면적에 따라 특정한 경우라도 당사자가 그 지정된 구획을 전체로서 평가하였고 면적에 의한 계산이 하나의 표준에 지나지 아니하여 그것이 당사자들 사이에 대상토지를 특정하고 그 대금을 결정하기 위한 방편이었다고 보일 때에는 이를 가리켜 수량을 지정한 매매라 할 수 없다.","ox":"O","m":"④","c":"A","tp":"매도인의 담보책임"},{"y":2026,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2026_32-38-5","t":"임의경매절차가 진행되어 그 매각허가결정이 확정되었는데 그 매각대금 지급기일이 지정되기 전에 그 매각목적물에 대한 소유자 내지 채무자 또는 그 매수인의 책임으로 돌릴 수 없는 사유로 말미암아 그 매각목적물의 일부가 멸실되었고, 그 매수인이 나머지 부분이라도 매수할 의사가 있어서 경매법원에 대하여 그 매각대금의 감액신청을 하여 왔을 때에는 경매법원으로서는 민법상의 쌍무계약에 있어서의 위험부담 내지 하자담보책임의 이론을 적용하여 그 감액결정을 허용하는 것이 상당하다.","ox":"O","m":"⑤","c":"A","tp":"매도인의 담보책임"}],"6":[{"y":2016,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2016_22-05-1","t":"근저당권자는 근저당권의 목적이 된 토지의 공용징수 등으로 인하여 토지의 소유자가 받을 금전이나 그 밖의 물건에 대하여 물상대위권을 행사할 수 있으므로, 토지의 소유자가 금전 등을 수령한 경우에도 물상대위권을 행사할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2016_22-05-2","t":"구 공용용지의 취득 및 손실보상에 관한 특례법에 따라 저당권이 설정된 토지의 취득에 관하여 토지소유자와 사업시행자 사이에 협의가 성립된 경우에 동 토지의 저당권자는 토지소유자가 수령할 보상금에 대하여 물상대위를 할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2016_22-05-3","t":"토지를 목적으로 저당권을 설정한 후 그 설정자가 그 토지에 건물을 축조한 때에는 저당권자는 토지와 함께 그 건물에 대하여도 경매를 청구할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2016_22-05-4","t":"토지에 관하여 저당권이 설정될 당시 그 지상에 토지소유자에 의한 건물의 건축이 개시되기 이전이었다면, 건물이 없는 토지에 관하여 저당권이 설정될 당시 근저당권자가 토지소유자에 의한 건물의 건축에 동의하였다고 하더라도 법정지상권이 성립되지 않는다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2016_22-05-5","t":"후순위근저당권자가 선순위근저당권의 피담보채무가 확정된 이후에 그 확정된 피담보채무를 변제하였더라도 제3취득자의 변제에 관한 민법 제364조의 규정에 따라 선순위근저당권의 소멸을 청구할 수 있는 사유로는 삼을 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2016_22-33-1","t":"집합물에 대한 양도담보권설정계약이 이루어진 경우 양도담보권자가 담보권설정계약당시 존재하는 집합물을 점유개정의 방법으로 그 점유를 취득하면 그 후 양도담보설정자가 그 집합물을 이루는 개개의 물건을 반입하였다 하더라도 그때마다 별도의 양도담보권설정계약을 맺거나 점유개정의 표시를 하여야 하는 것은 아니라 할 것이다.","ox":"O","m":"①","c":"A","tp":"비전형담보"},{"y":2016,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2016_22-33-2","t":"미등기건물에 대한 양도담보계약상의 채권자의 지위를 승계하여 건물을 관리하고 있는 자는 건물의 소유자가 아님은 물론 건물에 대하여 법률상 또는 사실상 처분권을 가지고 있는 자라고 할 수도 없다.","ox":"O","m":"②","c":"A","tp":"비전형담보"},{"y":2016,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2016_22-33-3","t":"가등기담보 등에 관한 법률(이하 ‘가등기담보법’이라 한다)은 차용물의 반환에 관하여 다른 재산권을 이전할 것을 예약한 경우에 적용되므로 금전소비대차나 준소비대차에 기한 차용금반환채무 이외의 채무를 담보하기 위하여 경료된 가등기나 양도담보에는 원칙적으로 위 법이 적용되지 아니한다.","ox":"O","m":"③","c":"A","tp":"비전형담보"},{"y":2016,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2016_22-33-4","t":"가등기담보법은 재산권 이전의 예약에 의한 가등기담보에 있어서 그 재산의 예약 당시의 가액이 차용액 및 이에 붙인 이자의 합산액을 초과하는 경우에 그 적용이 있는 것이므로, 재산권 이전의 예약 당시 그 재산에 대하여 선순위 근저당권이 설정되어 있다고 해서 그 재산의 가액에서 그 피담보채무액을 공제한 나머지 가액이 차용액 및 이에 붙인 이자의 합산액을 초과하는 경우에만 그 적용이 있다고 볼 것은 아니다.","ox":"X","m":"④","c":"A","tp":"비전형담보"},{"y":2016,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2016_22-33-5","t":"가등기담보법이 시행되기 전에 채권자가 채권담보의 목적으로 부동산에 가등기를 경료하였다가 그 후 변제기까지 변제를 받지 못하게 되어 위 가등기에 기한 소유권이전의 본등기를 경료한 경우에는 당사자들 사이에 채무자가 변제기에 피담보채무를 변제하지 아니하면 채권채무관계는 소멸하고 부동산의 소유권이 확정적으로 채권자에게 귀속된다는 명시의 특약이 없는 한, 그 본등기도 채권담보의 목적으로 경료된 것으로서 정산절차를 예정하고 있는 이른바 ‘약한 의미의 양도담보’가 된 것으로 보아야 한다.","ox":"O","m":"⑤","c":"A","tp":"비전형담보"},{"y":2017,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2017_23-12-1","t":"근저당권자가 피담보채무의 불이행을 이유로 경매신청을 한 경우에는 경매신청시에 근저당권의 피담보채무액이 확정되나 경매개시결정이 있은 후에 경매신청을 취하하면 피담보채권의 확정 효력이 소멸한다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2017_23-12-2","t":"근저당권의 목적이 된 부동산의 제3취득자는 채무자 또는 제3자의 변제 등으로 피담보채무의 일부가 소멸하였으나 그 잔존채무가 채권 최고액을 초과하는 경우, 자신이 담보부동산에 의하여 부담하는 책임이 그 변제 등으로 인하여 감축되었음을 항변할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2017_23-12-3","t":"피담보채무가 확정되기 전에 채무자가 변경되면 변경 후는 물론 변경 전의 채무자에 대한 채권도 근저당권으로 담보된다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2017_23-12-4","t":"근저당권자의 경매신청 등의 사유로 인하여 근저당권의 피담보채권이 확정되었을 경우, 확정 이후에 새로운 거래관계에서 발생한 원본채권과 확정 전에 발생한 원본채권에 관하여 확정 후에 발생하는 이자나 지연손해금 채권은 그 근저당권에 의하여 담보되지 않는다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2017_23-12-5","t":"근저당권자가 스스로 담보권 실행을 위한 경매를 신청하면서 경매신청서에 피담보채권 중 일부만을 청구금액으로 기재한 경우, 다른 특별한 사정이 없는 한 당해 경매절차에서 배당받을 금액은 그 기재된 채권액을 한도로 확정되는 것이며, 피담보채권이 경매신청서에 기재된 청구금액으로 확정되는 것은 아니다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2017_23-15-1","t":"금전채권의 질권자가 자기채권의 범위 내에서 직접청구권을 행사하는 경우 질권자는 질권설정자의 대리인과 같은 지위에서 입질채권을 추심하여 자기채권의 변제에 충당하고 그 한도에서 질권설정자에 의한 변제가 있었던 것으로 본다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2017_23-15-2","t":"금전채권의 질권자가 직접청구권을 행사하여 변제가 이루어진 경우 입질채권의 발생원인인 계약관계에 무효 등의 흠이 있어 입질채권이 부존재한다고 하더라도 제3채무자는 특별한 사정이 없는 한 상대방 계약당사자인 질권설정자에 대하여 부당이득반환을 구할 수 있을 뿐이고 질권자를 상대로 직접 부당이득반환을 구할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2017_23-15-3","t":"질권자가 제3채무자로부터 자기채권을 초과하여 금전을 지급받은 경우, 제3채무자는 특별한 사정이 없는 한 질권자를 상대로 초과 지급 부분에 관하여 부당이득반환을 구할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2017_23-15-4","t":"질권의 목적인 채권의 양도행위는 질권자의 이익을 해하는 변경에 해당되지 않으므로 질권자의 동의를 요하지 아니한다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2017_23-15-5","t":"근질권이 설정된 금전채권에 대하여 제3자의 압류로 강제집행절차가 개시된 경우 근질권의 피담보채권은 근질권자가 위와 같은 강제집행이 개시된 사실을 알게 된 때에 확정된다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2017_23-17-1","t":"민법 제321조는 ‘유치권자는 채권 전부의 변제를 받을 때까지 유치물 전부에 대하여 그 권리를 행사할 수 있다’고 규정하고 있으므로 유치물은 그 각 부분으로써 피담보채권의 전부를 담보하며, 이와 같은 유치권의 불가분성은 그 목적물이 분할 가능하거나 수개의 물건인 경우에도 적용된다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2017_23-17-2","t":"유치권자는 정당한 이유있는 때에는 미리 채무자에게 통지함이 없이 감정인의 평가에 의하여 유치물로 직접 변제에 충당할 것을 법원에 청구할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2017_23-17-3","t":"유치권은 점유의 상실로 인하여 소멸한다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2017_23-17-4","t":"유치권을 행사하더라도 채권의 소멸시효의 진행을 막을 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2017_23-17-5","t":"유치권자는 채무자의 승낙없이 유치물의 사용, 대여 또는 담보제공을 하지 못하나, 유치물의 보존에 필요한 사용은 할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2018_24-04","t":"근저당권의 피담보채무 확정에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"근저당권의 피담보채무 확정에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["근저당권의 존속기간이나 기본적 거래계약에서 결산기의 정함이 없는 경우에는, 근저당권에 의하여 담보되는 채권이 전부 소멸하고 채무자가 채권자로부터 새로이 금원을 차용하는 등 거래를 계속할 의사가 없는 경우에 한하여 근저당권설정자는 계약을 해제하고 근저당권설정등기의 말소를 구할 수 있다.","근저당권자의 경매신청 등의 사유로 인하여 근저당권의 피담보채권이 확정되었을 경우, 확정 이후에 새로운 거래관계에서 발생한 원본채권은 그 근저당권에 의하여 담보되지 아니하지만, 확정 전에 발생한 원본채권에 관하여 확정 후에 발생하는 이자나 지연손해금 채권은 채권최고액의 범위 내에서 근저당권에 의하여 여전히 담보되는 것이다.","물상보증인이 근저당권의 채무자의 계약상의 지위를 인수한 것이 아니라 다만 그 채무만을 면책적으로 인수하고 이를 원인으로 하여 근저당권 변경의 부기등기가 경료된 경우, 특별한 사정이 없는 한 그 변경등기는 당초 채무자가 근저당권자에 대하여 부담하고 있던 것으로서 물상보증인이 인수한 채무만을 그 대상으로 하는 것이지, 그 후 채무를 인수한 물상보증인이 다른 원인으로 근저당권자에 대하여 부담하게 된 새로운 채무까지 담보하는 것으로 볼 수는 없다.","후순위 근저당권자가 경매를 신청한 경우 선순위 근저당권의 피담보채권은 그 근저당권이 소멸하는 시기, 즉 경락인이 경락대금을 완납한 때에 확정된다.","근저당권자가 피담보채무의 불이행을 이유로 경매신청을 한 경우에는 경매신청시에 근저당 채무액이 확정되고, 그와 같이 경매신청을 하여 경매개시결정이 있은 후에 경매신청이 취하되었다고 하더라도 채무확정의 효과가 번복되는 것은 아니다. 23-12"],"a":1}},{"y":2018,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2018_24-12-1","t":"채권질권의 효력이 질권의 목적이 된 채권의 지연손해금 등과 같은 부대채권에까지 미치는 것은 아니다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2018_24-12-2","t":"금전채권의 질권자가 민법 제353조 제1항, 제2항에 의하여 자기채권의 범위 내에서 직접청구권을 행사하는 경우 제3채무자의 질권자에 대한 금전지급으로써 제3채무자의 질권설정자에 대한 급부가 이루어질 뿐만 아니라 질권설정자의 질권자에 대한 급부도 이루어진다고 보아야 한다. 그런데 위와 같은 경우에 입질채권의 발생원인인 계약관계에 무효 등의 흠이 있어 입질채권이 부존재한다면, 제3채무자는 특별한 사정이 없는 한 질권자 또는 질권설정자를 상대로 부당이득반환을 구할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2018_24-12-3","t":"제3채무자가 질권설정을 승낙한 후 그 질권설정계약이 합의해지된 경우 질권설정자가 그 해지를 이유로 제3채무자에게 원래의 채권으로 대항하려면 질권자가 제3채무자에게 해지 사실을 통지하여야 한다. 만일 질권자가 제3채무자에게 질권설정계약 해지 사실을 통지하였다면, 설사 아직 해지가 되지 아니하였다고 하더라도 선의인 제3채무자는 질권설정자에게 대항할 수 있는 사유로 질권자에게 대항할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2018_24-12-4","t":"민법 제347조는 채권을 질권의 목적으로 하는 경우에 채권증서가 있는 때에는 질권의 설정은 그 증서를 질권자에게 교부함으로써 효력이 생긴다고 규정하고 있다. 임대차계약서와 같이 계약 당사자 쌍방의 권리의무관계의 내용을 기재한 서면은 여기에서 말하는 ‘채권증서’에 해당한다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2018_24-12-5","t":"민법 제352조는 질권설정자는 질권자의 동의없이 질권의 목적된 권리를 소멸하게 하거나 질권자의 이익을 해하는 변경을 할 수 없다고 규정하고 있다. 질권설정자와 제3채무자가 질권의 목적된 권리를 소멸하게 하는 행위를 한 경우 질권자뿐 아니라 제3자도 그 무효를 주장할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2018_24-21-1","t":"채무자 소유의 부동산에 경매개시결정의 기입등기가 경료되어 압류의 효력이 발생한 이후에 채권자가 채무자로부터 위 부동산의 점유를 이전받고 이에 관한 공사 등을 시행함으로써 채무자에 대한 공사대금채권 및 이를 피담보채권으로 한 유치권을 취득한 경우, 부동산을 점유한 채권자로서는 위 유치권을 내세워 그 부동산에 관한 경매절차의 매수인에게 대항할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2018_24-21-2","t":"부동산 매도인이 매수인에게 소유권이전등기를 마쳐주었으나 매매대금을 지급받지 못하고 있는 경우, 매도인이 그 부동산을 점유하고 있다면 미지급된 매매대금채권을 피담보채권으로 하여 매수인이나 그에게서 부동산 소유권을 취득한 제3자를 상대로 유치권을 주장할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2018_24-21-3","t":"도급인이 수급인에 대한 하자보수청구권 내지 하자보수에 갈음한 손해배상채권 등에 기하여 수급인의 공사잔대금 채권 전부에 대하여 동시이행의 항변을 한 때에는, 수급인은 도급인에 대하여 하자보수의무나 하자보수에 갈음한 손해배상의무 등에 관한 이행의 제공을 하지 아니한 이상 공사잔대금 채권에 기한 유치권을 행사할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2018_24-21-4","t":"채무자 소유의 건물에 관하여 증·개축 등 공사를 도급받은 수급인이 경매개시결정의 기입등기가 마쳐지기 전에 채무자에게서 건물의 점유를 이전받았다 하더라도 경매개시결정의 기입등기가 마쳐져 압류의 효력이 발생한 후에 공사를 완공하여 공사대금채권을 취득한 경우에는, 수급인은 유치권을 내세워 경매절차의 매수인에게 대항할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2018_24-21-5","t":"건물의 신축공사를 도급받은 수급인이 사회통념상 독립한 건물이라고 볼 수 없는 정착물을 토지에 설치한 상태에서 공사가 중단된 경우에 위 정착물은 토지의 부합물에 불과하여 이러한 정착물에 대하여 유치권을 행사할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2019_25-09-1","t":"저당권자는 저당권의 목적이 된 물건의 멸실, 훼손 또는 공용징수로 인하여 저당목적물의 소유자가 받을 저당목적물에 갈음하는 금전 기타 물건에 대하여 물상대위권을 행사할 수 있으나, 다만 그 지급 또는 인도 전에 이를 압류하여야 하고, 만일 저당권자가 위 금전 또는 물건의 인도청구권을 압류하기 전에 저당물의 소유자가 그 인도청구권에 기하여 금전 등을 수령한 경우에는 저당목적물이 종국적으로 소멸하게 되므로, 저당권자는 저당목적물 소유자를 상대로 물상대위권은 물론 부당이득반환청구권도 행사할 수 없게 된다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2019_25-09-2","t":"건물의 증축부분이 기존건물에 부합하여 기존건물과 분리하여서는 별개의 독립물로서의 효용을 갖지 못하는 이상 기존건물에 대한 근저당권은 민법 제358조에 의하여 부합된 증축부분에도 효력이 미치는 것이므로 기존건물에 대한 경매절차에서 경매목적물로 평가되지 아니하였다 할지라도 매수인은 부합된 증축부분의 소유권을 취득한다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2019_25-09-3","t":"근저당권의 피담보채무는 존속기간이나 결산기의 정함이 없더라도 근저당권설정자가 근저당권자를 상대로 언제든지 해지의 의사표시를 함으로써 피담보채무를 확정시킬 수 있고, 이러한 해지에 관한 권한은 근저당부동산의 소유권을 취득한 제3자도 원용할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2019_25-09-4","t":"근저당 거래관계가 계속되는 관계로 근저당권의 피담보채권이 확정되지 아니하는 동안에는 그 채권의 일부가 대위변제되었다 하더라도 그 근저당권이 대위변제자에게 이전될 수 없다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2019_25-09-5","t":"공동저당권이 설정되어 있는 수개의 부동산 중 일부는 채무자 소유이고 일부는 물상보증인의 소유인 경우 위 각 부동산의 경매대가를 동시에 배당하는 때에는, 채무자 소유의 부동산의 경매대가에서 공동저당권자에게 우선적으로 배당을 하고, 부족분이 있는 경우에 한하여 물상보증인 소유 부동산의 경매대가에서 추가로 배당을 하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2019_25-39","t":"저당권에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"저당권에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["공동근저당권자가 근저당권을 실행하여 개시된 경매를 통하여 공동담보의 목적 부동산 중 일부에 대한 환가대금으로부터 다른 권리자에 우선하여 피담보채권의 일부에 대하여 배당받은 경우, 그와 같이 우선변제받은 금액에 관하여 공동담보의 나머지 목적 부동산에 대한 경매에서 다시 공동근저당권자로서 우선변제권을 행사할 수 있다.","제3자를 근저당권 명의인으로 하는 근저당권을 설정하는 경우, 그 점에 대하여 채권자․채무자․제3자 사이에 합의가 있고, 채권양도, 제3자를 위한 계약 등 채권이 그 제3자에게 실질적으로 귀속되었다고 볼 수 있는 특별한 사정이 있다면, 제3자 명의의 근저당권설정등기도 유효하다.","부동산을 매수한 자가 소유권이전등기를 마치지 아니한 상태에서 매도인인 소유자의 승낙 아래 매수 부동산을 타에 담보로 제공하면서 당사자 사이의 합의로 편의상 매수인 대신 등기부상 소유자인 매도인을 채무자로 하여 마친 근저당권설정등기는 실제 채무자인 매수인의 근저당권자에 대한 채무를 담보하는 것으로서 유효하다.","변제할 정당한 이익이 있는 자가 채무자를 위하여 확정된 근저당권의 피담보채무의 일부를 대위변제한 경우, 대위변제자는 일부대위변제를 원인으로 한 근저당권 일부이전의 부기등기의 경료 여부와 관계없이 변제한 가액의 범위 내에서 종래 근저당권 채권자가 가지고 있던 채권 및 담보에 관한 권리를 법률상 당연히 취득하나, 이때에도 근저당권 채권자는 대위변제자에 대하여 우선변제권을 가진다.","근저당권설정등기가 원인 없이 말소된 이후 근저당목적물인 부동산에 관하여 다른 근저당권자의 신청에 따라 경매절차가 진행되어 매각허가결정이 확정되고 매수인이 매각대금을 완납하였다면, 원인 없이 말소된 근저당권도 소멸한다. 22-21"],"a":1}},{"y":2019,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2019_25-40-1","t":"유치권의 성립요건이자 존속요건인 유치권자의 점유는 직접점유이든 간접점유이든 관계가 없으므로, 직접점유자가 채무자인 경우에도 유치권의 요건으로서의 점유에 해당한다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2019_25-40-2","t":"임대인과 임차인 사이에 건물명도시 권리금을 반환하기로 하는 약정이 있었다 하더라도 그와 같은 권리금반환청구권은 건물에 관한 채권이라 할 수 없으므로, 그와 같은 채권을 가지고 건물에 대한 유치권을 행사할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2019_25-40-3","t":"채무자 소유의 건물 등 부동산에 강제경매개시결정의 기입등기가 경료되어 압류의 효력이 발생한 이후에 채무자가 위 부동산에 관한 공사대금 채권자에게 그 점유를 이전함으로써 그로 하여금 유치권을 취득하게 한 경우, 점유자로서는 위 유치권을 내세워 그 부동산에 관한 경매절차의 매수인에게 대항할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2019_25-40-4","t":"유치권자가 유치물의 보존에 필요한 사용을 한 경우에도 특별한 사정이 없는 한 차임에 상당한 이득을 소유자에게 반환할 의무가 있다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2019_25-40-5","t":"유치권이 성립한 부동산의 매수인은 피담보채권의 소멸시효가 완성되면 시효로 인하여 채무가 소멸되는 결과 직접적인 이익을 받는 자에 해당하므로 소멸시효의 완성을 원용할 수 있는 지위에 있다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2020_26-20-1","t":"채권자가 채무자를 직접점유자로 하여 목적물을 간접점유하는 경우 유치권이 성립하지 아니한다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2020_26-20-2","t":"건물의 임차인이 임대차관계 종료시에는 건물을 원상으로 복구하여 임대인에게 명도하기로 약정하였다고 하더라도 임차인은 임대차보증금을 반환받을 때까지 건물에 관하여 비용상환청구권이 있음을 전제로 하는 유치권을 주장할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2020_26-20-3","t":"토지소유자가 건물의 존재에 따른 불법점유를 이유로 건물점유자에게 건물의 철거를 구하는 경우 건물점유자가 건물의 원시취득자에게 그 건물에 관한 유치권이 있다고 하더라도 토지소유자에게 대항할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2020_26-20-4","t":"목적물에 관하여 채권이 발생하였으나 채권자가 목적물에 관한 점유를 취득하기 전에 그에 관하여 저당권 등 담보물권이 설정되고 이후에 채권자가 목적물에 관한 점유를 취득한 경우 채권자는 다른 사정이 없는 한 그와 같이 취득한 민사유치권을 저당권자 등에게 주장할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2020_26-20-5","t":"수급인의 재료와 노력으로 건축되었고 독립한 건물에 해당되는 기성부분은 수급인의 소유라 할 것이므로 수급인은 공사대금을 지급받을 때까지 이에 대하여 유치권을 가질 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2020_26-26-1","t":"채권을 질권의 목적으로 하는 경우에 채권증서가 있는 때에는 질권의 설정은 그 증서를 질권자에게 교부함으로써 그 효력이 생긴다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2020_26-26-2","t":"저당권으로 담보한 채권을 질권의 목적으로 한 때에는 그 저당권등기에 질권의 부기등기를 하여야 그 효력이 저당권에 미친다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2020_26-26-3","t":"채권담보의 목적으로 채무자 소유의 부동산을 담보로 제공하여 근저당권을 설정하는 경우 채권자 아닌 제3자의 명의로 근저당권설정등기를 하는데 대하여 채권자와 채무자 및 제3자 사이에 합의가 있더라도 이는 부종성의 관점에서 허용될 수 없으므로 언제나 무효이다.","ox":"X","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2020_26-26-4","t":"저당지상의 건물에 대한 일괄경매청구권은 저당권설정자가 건물을 축조한 경우 뿐만 아니라 저당권설정자로부터 저당토지에 대한 용익권을 설정받은 자가 그 토지에 건물을 축조한 경우라도 그 후 저당권설정자가 그 건물의 소유권을 취득한 경우에는 저당권자는 토지와 함께 그 건물에 대하여 경매를 청구할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2020_26-26-5","t":"물상보증인이 담보권의 실행으로 타인의 채무를 담보하기 위하여 제공한 부동산의 소유권을 잃은 경우 물상보증인이 채무자에게 구상할 수 있는 범위는 특별한 사정이 없는 한 담보권의 실행으로 부동산의 소유권을 잃게 된 때, 즉 매수인이 매각대금을 다 낸 때의 부동산 시가를 기준으로 하여야 하고, 매각대금을 기준으로 할 것이 아니다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2021_27-07-1","t":"민법 제361조는 “저당권은 그 담보한 채권과 분리하여 타인에게 양도하거나 다른 채권의 담보로 하지 못한다.”라고 정하고 있을 뿐 피담보채권을 저당권과 분리해서 양도하거나 다른 채권의 담보로 하지 못한다고 정하고 있지 않다. 채권담보라고 하는 저당권 제도의 목적에 비추어 특별한 사정이 없는 한 피담보채권의 처분에는 저당권의 처분도 당연히 포함된다고 볼 것이지만, 피담보채권의 처분이 있으면 언제나 저당권도 함께 처분된다고는 할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2021_27-07-2","t":"민법 제352조가 질권설정자는 질권자의 동의 없이 질권의 목적된 권리를 소멸하게 하거나 질권자의 이익을 해하는 변경을 할 수 없다고 규정한 것은 질권자가 질권의 목적인 채권의 교환가치에 대하여 가지는 배타적 지배권능을 보호하기 위한 것이므로, 질권설정자와 제3채무자가 질권의 목적된 권리를 소멸하게 하는 행위를 하였다고 하더라도 이는 질권자에 대한 관계에 있어 무효일 뿐이어서 특별한 사정이 없는 한 질권자 아닌 제3자가 그 무효의 주장을 할 수는 없다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2021_27-07-3","t":"금전채권의 질권자가 민법 제353조 제1항, 제2항에 의하여 자기채권의 범위 내에서 직접청구권을 행사하는 경우 질권자는 질권설정자의 대리인과 같은 지위에서 입질채권을 추심하여 자기채권의 변제에 충당하고 그 한도에서 질권설정자에 의한 변제가 있었던 것으로 보므로, 위 범위 내에서는 제3채무자의 질권자에 대한 금전지급으로써 제3채무자의 질권설정자에 대한 급부가 이루어질 뿐만 아니라 질권설정자의 질권자에 대한 급부도 이루어진다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2021_27-07-4","t":"제3채무자가 질권자의 동의 없이 질권설정자와 상계합의를 함으로써 질권의 목적인 채무를 소멸하게 한 경우에는 질권자에게 대항할 수 없고, 질권자는 여전히 제3채무자에 대하여 직접 채무의 변제를 청구할 수 있다고 보아야 한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2021_27-07-5","t":"질권자가 피담보채권을 초과하여 질권의 목적이 된 금전채권을 추심하였다고 하더라도 그 중 피담보채권을 초과하는 부분이 법률상 원인이 없는 것으로서 질권설정자에 대한 관계에서 부당이득이 된다고 할 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2021_27-21-1","t":"당사자 사이에 하나의 기본계약에서 발생하는 동일한 채권을 담보하기 위하여 여러 개의 부동산에 근저당권을 설정하면서 각각의 근저당권 채권최고액을 합한 금액을 우선변제받기 위하여 공동근저당권의 형식이 아닌 개별 근저당권의 형식을 취한 경우, 이러한 근저당권은 민법 제368조가 적용되는 공동근저당권이 아니라 피담보채권을 누적적으로 담보하는 근저당권에 해당한다. 이와 같은 누적적 근저당권은 공동근저당권과 달리 담보의 범위가 중첩되지 않으므로, 누적적 근저당권을 설정받은 채권자는 여러 개의 근저당권을 동시에 실행할 수도 있고, 여러 개의 근저당권 중 어느 것이라도 먼저 실행하여 그 채권최고액의 범위에서 피담보채권의 전부나 일부를 우선변제받은 다음 피담보채권이 소멸할 때까지 나머지 근저당권을 실행하여 그 근저당권의 채권최고액 범위에서 반복하여 우선변제를 받을 수 있다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2021_27-21-2","t":"부동산의 소유자 겸 채무자가 채권자인 저당권자에게 당해 저당권설정등기에 의하여 담보되는 채무를 모두 변제함으로써 저당권이 소멸된 경우 그 저당권설정등기 또한 효력을 상실하여 말소되어야 하고, 부동산의 소유자가 새로운 제3의 채권자로부터 금원을 차용함에 있어 그 제3자와 사이에 새로운 차용금 채무를 담보하기 위하여 잔존하는 종전 채권자 명의의 저당권설정등기를 이용하여 이에 터잡아 새로운 제3의 채권자에게 저당권 이전의 부기등기를 경료하기로 하는 내용의 저당권등기 유용의 합의를 하고 실제로 그 부기등기를 경료하였다고 하더라도, 새로운 제3의 채권자는 부동산의 소유자에 대하여 그 등기 유용의 합의를 주장하여 저당권설정등기의 말소청구에 대항할 수 없다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2021_27-21-3","t":"근저당권자는 근저당권의 목적이 된 토지의 공용징수 등으로 토지의 소유자가 받을 금전이나 그 밖의 물건에 대하여 물상대위권을 행사할 수 있으나, 다만 그 지급이나 인도 전에 압류하여야 하고(민법 제370조, 제342조), 근저당권자가 금전이나 물건의 인도청구권을 압류하기 전에 토지의 소유자가 인도청구권에 기하여 금전 등을 수령한 경우 근저당권자는 더 이상 물상대위권을 행사할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2021_27-21-4","t":"민법 제365조가 토지를 목적으로 한 저당권을 설정한 후 그 저당권설정자가 그 토지에 건물을 축조한 때에는 저당권자가 토지와 건물을 일괄하여 경매를 청구할 수 있도록 규정한 취지는, 저당권은 담보물의 교환가치의 취득을 목적으로 할 뿐 담보물의 이용을 제한하지 아니하여 저당권설정자로서는 저당권설정 후에도 그 지상에 건물을 신축할 수 있는데, 후에 그 저당권의 실행으로 토지가 제3자에게 경락될 경우에 건물을 철거하여야 한다면 사회경제적으로 현저한 불이익이 생기게 되어 이를 방지할 필요가 있으므로 이러한 이해관계를 조절하고, 저당권자에게도 저당토지상의 건물의 존재로 인하여 생기게 되는 경매의 어려움을 해소하여 저당권의 실행을 쉽게 할 수 있도록 한 데에 있다는 점에 비추어 볼 때, 저당지상의 건물에 대한 일괄경매청구권은 저당권설정자가 건물을 축조한 경우뿐만 아니라 저당권설정자로부터 저당토지에 대한 용익권을 설정받은 자가 그 토지에 건물을 축조한 경우라도 그 후 저당권설정자가 그 건물의 소유권을 취득한 경우에는 저당권자는 토지와 함께 그 건물에 대하여 경매를 청구할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2021_27-21-5","t":"저당권자는 저당권 설정 이후 환가에 이르기까지 저당물의 교환가치에 대한 지배권능을 보유하고 있으므로 저당목적물의 소유자 또는 제3자가 저당목적물을 물리적으로 멸실·훼손하는 경우는 물론 그 밖의 행위로 저당부동산의 교환가치가 하락할 우려가 있는 등 저당권자의 우선변제청구권의 행사가 방해되는 결과가 발생한다면 저당권자는 저당권에 기한 방해배제청구권을 행사하여 방해행위의 제거를 청구할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2021_27-29","t":"다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"다음 설명 중 가장 옳지 않은 것은?","d":"","o":["근저당권자에게 담보목적물에 관하여 각 유치권의 부존재 확인을 구할 법률상 이익이 있다고 보는 것은 경매절차에서 유치권이 주장됨으로써 낮은 가격에 입찰이 이루어져 근저당권자의 배당액이 줄어들 위험이 있다는 데에 근거가 있고, 이는 소유자가 그 소유의 부동산에 관한 경매절차에서 유치권의 부존재 확인을 구하는 경우에도 마찬가지이다. 위와 같이 경매절차에서 유치권이 주장되었으나 소유부동산 또는 담보목적물이 매각되어 그 소유권이 이전되어 소유권을 상실하거나 근저당권이 소멸하였다면, 소유자와 근저당권자는 유치권의 부존재 확인을 구할 법률상 이익이 없다.","甲 주식회사가 건물신축 공사대금 일부를 지급받지 못하자 건물을 점유하면서 유치권을 행사해 왔는데, 그 후 乙이 경매절차에서 건물 중 일부 상가를 매수하여 소유권이전등기를 마친 다음 甲 회사의 점유를 침탈하여 丙에게 임대한 사안에서, 乙의 점유침탈로 甲 회사가 점유를 상실한 이상 유치권은 소멸하고, 甲 회사가 점유회수의 소를 제기하여 승소판결을 받아 점유를 회복하면 점유를 상실하지 않았던 것으로 되어 유치권이 되살아난다.","유치권은 법정담보물권이기는 하나 채권자의 이익보호를 위한 채권담보의 수단에 불과하므로 이를 포기하는 특약은 유효하고, 유치권을 사전에 포기한 경우 다른 법정요건이 모두 충족되더라도 유치권이 발생하지 않는 것과 마찬가지로 유치권을 사후에 포기한 경우 곧바로 유치권은 소멸한다. 다만, 유치권 포기로 인한 유치권의 소멸은 유치권 포기 의사표시의 상대방 이외의 사람은 주장할 수 없다.","민법 제320조 제1항에서 ‘그 물건에 관하여 생긴 채권’은 유치권 제도 본래의 취지인 공평의 원칙에 특별히 반하지 않는 한 채권이 목적물 자체로부터 발생한 경우는 물론이고 채권이 목적물의 반환청구권과 동일한 법률관계나 사실관계로부터 발생한 경우도 포함하고, 한편 민법 제321조는 “유치권자는 채권 전부의 변제를 받을 때까지 유치물 전부에 대하여 그 권리를 행사할 수 있다”고 규정하고 있으므로, 유치물은 그 각 부분으로써 피담보채권의 전부를 담보하며, 이와 같은 유치권의 불가분성은 그 목적물이 분할 가능하거나 수개의 물건인 경우에도 적용된다.","채무자가 채무초과의 상태에 이미 빠졌거나 그러한 상태가 임박함으로써 채권자가 원래라면 자기 채권의 충분한 만족을 얻을 가능성이 현저히 낮아진 상태에서 이미 채무자 소유의 목적물에 저당권 기타 담보물권이 설정되어 있어서 유치권의 성립에 의하여 저당권자 등이 그 채권 만족상의 불이익을 입을 것을 잘 알면서 자기 채권의 우선적 만족을 위하여 위와 같이 취약한 재정적 지위에 있는 채무자와의 사이에 의도적으로 유치권의 성립요건을 충족하는 내용의 거래를 일으키고 그에 기하여 목적물을 점유하게 됨으로써 유치권이 성립하였다면, 유치권자가 그 유치권을 저당권자 등에 대하여 주장하는 것은 다른 특별한 사정이 없는 한 신의칙에 반하는 권리행사 또는 권리남용으로서 허용되지 아니한다. 그리고 저당권자 등은 경매절차 기타 채권실행절차에서 위와 같은 유치권을 배제하기 위하여 그 부존재의 확인 등을 소로써 청구할 수 있다고 할 것이다."],"a":3}},{"y":2022,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2022_28-12-1","t":"가등기담보권 설정 후에 후순위권리자나 제3취득자 등 이해관계 있는 제3자가 생긴 상태에서 새로운 약정으로 기존 가등기담보권에 피담보채권을 추가하거나 피담보채권의 내용을 변경, 확장하는 경우에는 이해관계 있는 제3자의 이익을 침해하게 되므로, 이러한 경우에는 피담보채권으로 추가, 확장한 부분은 이해관계 있는 제3자에 대한 관계에서는 우선변제권 있는 피담보채권에 포함되지 않는다고 보아야 한다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2022_28-12-2","t":"가등기담보부동산에 대한 예약 당시의 시가가 그 피담보채무액에 미치지 못하는 경우에 있어서는 가등기담보 등에 관한 법률이 정하는 청산금평가액의 통지 및 청산금지급 등의 절차를 이행할 여지가 없다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2022_28-12-3","t":"공동명의로 담보가등기를 마친 수인의 채권자가 각자의 지분별로 별개의 독립적인 매매예약완결권을 가지는 경우, 채권자 중 1인은 단독으로 자신의 지분에 관하여 가등기담보 등에 관한 법률이 정한 청산절차를 이행한 후 소유권이전의 본등기절차 이행청구를 할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2022_28-12-4","t":"가등기담보 등에 관한 법률이 정한 청산절차를 거치지 않고 이루어진 담보가등기에 기한 본등기는 무효이고, 그 본등기는 약한 의미의 양도담보로서의 효력이 있다고 할 수 없다. 나아가 이 경우 나중에 가등기권자가 가등기담보 등에 관한 법률이 정한 청산절차를 마치더라도 무효인 본등기가 실체적 법률관계에 부합하는 유효한 등기로 된다고 할 수도 없다.","ox":"X","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2022_28-12-5","t":"목적부동산의 가액이 채권액을 넘는 경우에는 가등기담보권자는 그 차액을 청산금으로서 채무자 등에게 지급하여야 하고, 여기의 채권액을 계산함에는 선순위담보권이 있는 때에는 그것에 의하여 담보된 채권액도 합산하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2022_28-24-1","t":"공사대금채권에 기하여 유치권을 행사하는 자가 스스로 유치물인 주택에 거주하며 사용하는 것은 유치물인 주택의 보존에 도움이 되는 행위로서 유치물의 보존에 필요한 사용에 해당하므로, 차임 상당의 이득을 소유자에게 반환할 의무가 없다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2022_28-24-2","t":"유치권의 성립요건인 유치권자의 점유는 간접점유도 포함한다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2022_28-24-3","t":"유치권 배제 특약이 있는 경우 다른 법정요건이 모두 충족되더라도 유치권은 발생하지 않는데, 특약에 따른 효력은 특약의 상대방뿐 아니라 그 밖의 사람도 주장할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2022_28-24-4","t":"근저당권자는 유치권 신고를 한 사람을 상대로 유치권 전부의 부존재뿐만 아니라 경매절차에서 유치권을 내세워 대항할 수 있는 범위를 초과하는 유치권의 부존재 확인을 구할 법률상 이익이 있다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2022_28-24-5","t":"甲이 건물 신축공사 수급인인 乙 주식회사와 체결한 약정에 따라 공사현장에 시멘트와 모래 등의 건축자재를 공급한 경우, 甲의 건축자재대금채권은 매매계약에 따른 매매대금채권에 불과할 뿐 건물 자체에 관하여 생긴 채권이라고 할 수 없으므로 건물에 관한 유치권의 피담보채권이 되지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2022_28-29-1","t":"질권의 목적인 채권의 양도행위는 민법 제352조 소정의 질권자의 이익을 해하는 변경에 해당하므로 질권자의 동의를 요한다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2022_28-29-2","t":"근질권이 설정된 금전채권에 대하여 제3자의 압류로 강제집행절차가 개시된 경우 근질권의 피담보채권은 근질권자가 위와 같은 강제집행이 개시된 사실을 알게 된 때에 확정된다고 봄이 타당하다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2022_28-29-3","t":"질권은 원본, 이자, 위약금, 질권실행의 비용, 질물보존의 비용 및 채무불이행 또는 질물의 하자로 인한 손해배상의 채권을 담보한다. 그러나 다른 약정이 있는 때에는 그 약정에 의한다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2022_28-29-4","t":"민법 제347조는 채권을 질권의 목적으로 하는 경우에 채권증서가 있는 때에는 질권의 설정은 그 증서를 질권자에게 교부함으로써 효력이 생긴다고 규정하고 있는데, 임대차계약서와 같이 계약 당사자 쌍방의 권리의무관계의 내용을 정한 서면은 그 계약에 의한 권리의 존속을 표상하기 위한 것이라고 할 수는 없으므로 위 채권증서에 해당하지 않는다고 할 것이다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2022_28-29-5","t":"보험금청구권의 양도 또는 질권설정에 대한 채무자의 승낙은 별도로 면책사유가 있으면 보험금을 지급하지 않겠다는 취지를 명시하지 않아도 당연히 그것을 전제로 하고 있다고 보아야 하고 그 양수인 또는 질권자도 그러한 사실을 알고 있었다고 보아야 할 것이다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2022_28-35-1","t":"근저당권에 있어서 채권의 총액이 채권최고액을 초과하는 경우, 적어도 근저당권자와 채무자 겸 근저당권설정자와의 관계에서는 위 채권 전액의 변제가 있을 때까지 근저당권의 효력은 채권최고액과는 관계없이 잔존채무에 여전히 미치는 것이므로 채무자 겸 근저당권설정자는 채무의 일부인 채권최고액과 지연손해금, 집행비용만의 변제공탁으로는 근저당권설정등기의 말소를 청구할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2022_28-35-2","t":"공동근저당권자가 목적 부동산 중 일부 부동산에 대하여 제3자가 신청한 경매절차에 소극적으로 참가하여 우선배당을 받은 경우에, 해당 부동산에 관한 근저당권의 피담보채권은 그 근저당권이 소멸하는 시기, 즉 매수인이 매각대금을 지급한 때에 확정되지만, 나머지 목적 부동산에 관한 근저당권의 피담보채권은 기본거래가 종료하거나 채무자나 물상보증인에 대하여 파산이 선고되는 등의 다른 확정사유가 발생하지 아니하는 한 확정되지 아니한다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2022_28-35-3","t":"근저당권에 의하여 담보되는 피담보채무는 근저당권설정계약에서 근저당권의 존속기간을 정하거나 근저당권으로 담보되는 기본적인 거래계약에서 결산기를 정한 경우에는 원칙적으로 존속기간이나 결산기가 도래한 때에 확정되지만, 이 경우에도 근저당권에 의하여 담보되는 채권이 전부 소멸하고 채무자가 채권자로부터 새로이 금원을 차용하는 등 거래를 계속할 의사가 없는 경우에는, 그 존속기간 또는 결산기가 경과하기 전이라 하더라도 근저당권설정자는 계약을 해제하고 근저당권설정등기의 말소를 구할 수 있고, 존속기간이나 결산기의 정함이 없는 때에는 근저당권설정자가 근저당권자를 상대로 언제든지 해지의 의사표시를 함으로써 피담보채무를 확정시킬 수 있으나, 이러한 계약의 해제 또는 해지에 관한 권한은 계약당사자의 권능이라고 할 것이어서 근저당부동산의 소유권을 취득한 제3자는 원용할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2022_28-35-4","t":"민사집행법 제148조에 따라 배당받을 채권자나 제3취득자가 없는 한 근저당권자의 채권액이 근저당권의 채권최고액을 초과하는 경우에 매각대금 중 그 최고액을 초과하는 금액이 있더라도 이는 근저당권설정자에게 반환할 것은 아니고 근저당권자의 채권최고액을 초과하는 채무의 변제에 충당하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2022_28-35-5","t":"근저당권의 피담보채권이 확정되기 전에 그 채권의 일부를 양도하거나 대위변제한 경우 근저당권이 양수인이나 대위변제자에게 이전할 여지는 없으나, 그 근저당권에 의하여 담보되는 피담보채권이 확정되게 되면, 그 피담보채권액이 그 근저당권의 채권최고액을 초과하지 않는 한 그 근저당권 내지 그 실행으로 인한 경락대금에 대한 권리 중 그 피담보채권액을 담보하고 남는 부분은 저당권의 일부이전의 부기등기의 경료 여부와 관계없이 대위변제자에게 법률상 당연히 이전된다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2023_29-11-1","t":"물상보증인이 담보부동산을 제3취득자에게 매도하고 제3취득자가 담보부동산에 설정된 근저당권의 피담보채무의 이행을 인수한 경우, 이후 담보부동산에 대한 담보권이 실행되면 제3취득자가 채무자에 대하여 구상권을 취득한다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2023_29-11-2","t":"공동저당에 제공된 채무자 소유의 부동산과 물상보증인 소유의 부동산 가운데 물상보증인 소유의 부동산이 먼저 경매되어 매각대금에서 선순위공동저당권자가 변제를 받은 때에는 물상보증인은 채무자에 대하여 구상권을 취득함과 동시에 변제자대위에 의하여 채무자 소유의 부동산에 대한 선순위공동저당권을 대위취득한다. 이 경우 물상보증인 소유의 부동산에 대한 후순위저당권자는 물상보증인이 대위취득한 채무자 소유의 부동산에 대한 선순위공동저당권에 대하여 물상대위를 할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2023_29-11-3","t":"공동저당이 설정된 복수의 부동산이 같은 물상보증인의 소유에 속하고 그 중 하나의 부동산에 후순위저당권이 설정되어 있는데 그 부동산의 대가만 배당되는 경우, 후순위저당권자는 선순위 공동저당권자가 민법 제368조 제1항에 따라 공동저당이 설정된 다른 부동산으로부터 변제를 받을 수 있었던 금액에 이르기까지 공동저당이 설정된 다른 부동산에 대한 선순위 공동저당권자의 저당권을 대위 행사할 수 있고, 공동저당이 설정된 부동산이 제3자에게 양도되어 소유자가 다르게 되더라도 마찬가지이다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2023_29-11-4","t":"물상보증인의 채무자에 대한 구상권은 그들 사이의 물상보증위탁계약의 법적 성질과 관계없이 민법에 의하여 인정된 별개의 독립한 권리이고, 그 소멸시효에 있어서는 민법상 일반채권에 관한 규정이 적용된다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2023_29-11-5","t":"물상보증인이 담보권의 실행으로 타인의 채무를 담보하기 위하여 제공한 부동산의 소유권을 잃은 경우 물상보증인이 채무자에게 구상할 수 있는 범위는 특별한 사정이 없는 한 담보권의 실행으로 부동산의 소유권을 잃게 된 때(매수인이 매각대금을 다 낸 때)의 부동산 시가를 기준으로 하여야 하고, 매각대금을 기준으로 할 것이 아니다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2023_29-29-1","t":"근저당권자의 경매신청 등의 사유로 인하여 근저당권의 피담보채권이 확정되었을 경우, 확정 이후에 새로운 거래관계에서 발생한 원본채권은 그 근저당권에 의하여 담보되지 않지만, 확정 전에 발생한 원본채권에 관하여 확정 후에 발생하는 이자나 지연손해금 채권은 채권최고액의 범위 내에서 근저당권에 의하여 여전히 담보된다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2023_29-29-2","t":"근저당권은 그 담보할 채무의 최고액만을 정하고, 채무의 확정을 장래에 보류하여 설정하는 저당권으로서, 계속적인 거래관계로부터 발생하는 다수의 불특정채권을 장래의 결산기에서 일정한 한도까지 담보하기 위한 목적으로 설정되는 담보권이므로, 근저당권설정행위와는 별도로 근저당권의 피담보채권을 성립시키는 법률행위가 있어야 한다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2023_29-29-3","t":"저당권은 원본, 이자, 위약금, 채무불이행으로 인한 손해배상 및 저당권의 실행비용을 담보하는 것이며, 채권최고액의 정함이 있는 근저당권에 있어서 이러한 채권의 총액이 그 채권최고액을 초과하는 경우, 적어도 근저당권자와 채무자 겸 근저당권설정자와의 관계에 있어서는 위 채권 전액의 변제가 있을 때까지 근저당권의 효력은 채권최고액과는 관계없이 잔존채무에 여전히 미친다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2023_29-29-4","t":"구분건물의 전유부분만에 관하여 설정된 저당권의 효력은 특별한 사정이 없는 한 그 전유부분의 소유자가 사후에 취득한 대지사용권에까지 미친다고 할 수 없다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2023_29-29-5","t":"공장건물이나 토지에 대하여 공장저당법에 의한 공장저당이 아니라 민법상의 일반저당권이 설정된 경우에 그 저당권의 효력은 민법 제358조에 의하여 당연히 그 공장건물이나 토지의 종물 또는 부합물에까지 미친다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2024_30-21-1","t":"乙의 점유침탈로 甲이 해당 상가에 대한 점유를 상실한 이상 甲의 유치권은 소멸하고, 甲이 점유회수의 소를 제기하여 승소판결을 받아 점유를 회복하면 점유를 상실하지 않았던 것으로 되어 유치권이 되살아나지만, 위와 같은 방법으로 점유를 회복하기 전에는 유치권이 되살아나는 것이 아니므로, 점유회수의 소를 제기하여 점유를 회복할 수 있다는 사정만으로 甲의 유치권이 소멸하지 않았다고 판단하여서는 아니 된다.","ox":"O","m":"①","c":"A","tp":"점유와 유치권"},{"y":2024,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2024_30-21-2","t":"민법 제321조는 “유치권자는 채권 전부의 변제를 받을 때까지 유치물 전부에 대하여 그 권리를 행사할 수 있다.”라고 규정하고 있으므로, 유치물은 그 각 부분으로써 피담보채권의 전부를 담보하며, 이와 같은 유치권의 불가분성은 그 목적물이 분할 가능하거나 수개의 물건인 경우에도 적용된다.","ox":"O","m":"②","c":"A","tp":"점유와 유치권"},{"y":2024,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2024_30-21-3","t":"“점유물이 침탈되었을 경우에 부동산일 때에는 점유자는 침탈 후 직시 가해자를 배제하여 이를 탈환할 수 있다”고 정한 민법 제209조 제2항에서의 점유자의 자력탈환권은 점유가 침탈되었을 때 시간적으로 좁게 제한된 범위 내에서 자력으로 점유를 회복할 수 있다는 것으로서, 위 규정에서 말하는 “직시”란 ‘객관적으로 가능한 한 신속히’ 또는 ‘사회관념상 가해자를 배제하여 점유를 회복하는 데 필요하다고 인정되는 범위 안에서 되도록 속히’라는 뜻으로 해석할 것이므로, 점유자가 침탈사실을 알고 모르고와는 관계없이 침탈을 당한 후 상당한 시간이 흘렀다면 자력탈환권을 행사할 수 없다.","ox":"O","m":"③","c":"A","tp":"점유와 유치권"},{"y":2024,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2024_30-21-4","t":"민법 제320조 제1항에서 ‘그 물건에 관하여 생긴 채권’은 유치권 제도 본래의 취지인 공평의 원칙에 특별히 반하지 않는 한 채권이 목적물 자체로부터 발생한 경우는 물론이고 채권이 목적물의 반환청구권과 동일한 법률관계나 사실관계로부터 발생한 경우도 포함하므로, 이른바 계약명의신탁에서 명의신탁자의 명의수탁자에 대하여 가지는 부동산 매수자금액 상당의 부당이득반환청구권은 부동산 자체로부터 발생한 채권은 아니더라도 소유권 등에 기한 부동산의 반환청구권과 동일한 법률관계나 사실관계로부터 발생한 채권이라고 볼 수는 있으므로, 위 부당이득반환청구권은 민법 제320조 제1항의 ‘그 물건에 관하여 생긴 채권’이라고 볼 것이다.","ox":"X","m":"④","c":"A","tp":"점유와 유치권"},{"y":2024,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2024_30-21-5","t":"유치권은 타물권인 점에 비추어 볼 때 수급인의 재료와 노력으로 건축되었고 독립한 건물에 해당되는 기성부분은 수급인의 소유라 할 것이므로 수급인은 공사대금을 지급받을 때까지 이에 대하여 유치권을 가질 수 없다.","ox":"O","m":"⑤","c":"A","tp":"점유와 유치권"},{"y":2024,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2024_30-39-1","t":"민법 제365조에 기한 일괄경매청구권은 토지의 저당권자가 토지에 대하여 경매를 신청한 후에도 그 토지상의 건물에 대하여 토지에 관한 경매기일 공고 시까지는 일괄경매의 추가신청을 할 수 있고, 이 경우에 집행법원은 두 개의 경매사건을 병합하여 일괄경매절차를 진행함이 상당하다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2024_30-39-2","t":"공동근저당의 목적 부동산 중 일부에 대한 경매절차에서, 공동근저당권자가 선순위근저당권자로서의 자신의 채권 전액을 청구하였다면 선순위근저당권자가 경매대가로부터 우선하여 변제받고, 후순위근저당권자는 잔액으로부터 변제를 받는 것이며, 이는 선순위근저당권자와 후순위근저당권자가 동일인이라고 하여 달라지는 것은 아니다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2024_30-39-3","t":"근저당권설정등기상 근저당권자가 다른 사람과 함께 채무자로부터 유효하게 채권을 변제받을 수 있고 채무자도 그들 중 누구에게든 채무를 유효하게 변제할 수 있는 관계, 가령 채권자와 근저당권자가 불가분적 채권자의 관계에 있다고 볼 수 있는 경우에는 그러한 근저당권설정등기도 유효하다고 볼 것이다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2024_30-39-4","t":"건물에 대한 저당권의 효력은 그 건물에 종된 권리인 건물의 소유를 목적으로 하는 지상권에도 미치게 되므로, 건물에 대한 저당권이 실행되어 경락인이 그 건물의 소유권을 취득하였다면 특별한 사정이 없는 한 경락인은 건물 소유를 위한 지상권도 민법 제187조의 규정에 따라 등기 없이 당연히 취득하게 되나, 이 경우에 경락인이 건물을 제3자에게 양도한 때에는, 별도의 합의가 없는 한 지상권도 양도하기로 한 것으로 볼 수는 없다.","ox":"X","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2024_30-39-5","t":"공동저당권이 설정되어 있는 수개의 부동산 중 일부는 채무자 소유이고 일부는 물상보증인 소유인 경우 각 부동산의 경매대가를 동시에 배당하는 때에는 민법 제368조 제1항은 적용되지 아니한다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2025_31-28","t":"양도담보에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"양도담보에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","d":"ㄱ.양도담보설정자에게 목적물에 대한 소유권이나 처분권 등 양도담보를 설정할 권한이 없어도 양도담보를 설정할 수 있다.\nㄴ.동산 양도담보권자는 양도담보 목적물이 소실되어 양도담보설정자가 보험회사에 대하여 화재보험계약에 따른 보험금청구권을 취득한 경우에도 담보물 가치의 변형물인 위 화재보험금청구권에 대하여 양도담보권에 기한 물상대위권을 행사할 수 있다.\nㄷ.동산 양도담보설정자는 여전히 그 물건에 대한 사용․수익권을 가지고, 변제기에 이르러서는 채무 전액을 변제하고 소유권을 되돌려 받을 수 있다.\nㄹ.동산 양도담보권자는 양도담보권설정자를 제외한 제3자에 대한 관계에 있어서 자신이 그 동산의 소유자임을 주장하여 권리를 행사할 수는 없다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄱ, ㄹ","ㄴ, ㄷ","ㄷ, ㄹ"],"a":3}},{"y":2025,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2025_31-32-1","t":"근저당권은 계속되는 거래관계로부터 발생하고 소멸하는 불특정 다수의 장래 채권을 결산기에 계산하여 잔존하는 채무를 일정한 한도액의 범위 내에서 담보하는 저당권이어서 그 거래가 종료하기까지 채권은 계속적으로 증감 변동하나, 근저당권자가 피담보채무의 불이행을 이유로 스스로 담보권의 실행을 위한 경매를 신청한 때에는 그때까지 발생되어 있는 채권으로 피담보채권액이 확정된다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2025_31-32-2","t":"이미 소멸한 근저당권에 기하여 제2차 경매를 신청하여 경매가 개시되고 부동산이 매각되어 매수인이 매각대금을 지급하였더라도 경매가 무효이므로 매수인은 소유권을 취득할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2025_31-32-3","t":"근저당권을 설정한 후에 근저당권설정자와 근저당권자의 합의로 채무의 범위 또는 채무자를 추가하거나 교체하는 등으로 피담보채무를 변경할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2025_31-32-4","t":"근저당권의 피담보채권 중 지연손해금도 근저당권의 채권최고액 한도에서 전액 담보된다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2025_31-32-5","t":"근저당권은 채권담보를 위한 것이므로 채권자와 근저당권자는 동일인이어야 한다. 따라서 근저당권설정등기상 근저당권자가 다른 사람과 함께 채무자로부터 유효하게 채권을 변제받을 수 있고 채무자도 그들 중 누구에게든 채무를 유효하게 변제할 수 있는 관계, 가령 채권자와 근저당권자가 불가분적 채권자의 관계에 있다고 볼 수 있는 경우라도 그러한 근저당권설정등기는 유효하다고 볼 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2026_32-31-1","t":"유치권의 성립요건이자 존속요건인 유치권자의 점유는 직접점유이든 간접점유이든 관계가 없으나, 다만 유치권은 목적물을 유치함으로써 채무자의 변제를 간접적으로 강제하는 것을 본체적 효력으로 하는 권리인 점 등에 비추어, 그 직접점유자가 채무자인 경우에는 유치권의 요건으로서의 점유에 해당하지 않는다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2026_32-31-2","t":"부동산 매도인이 매매대금을 다 지급받지 아니한 상태에서 매수인에게 소유권이전등기를 마쳐주어 목적물의 소유권을 매수인에게 이전한 경우, 매도인이 부동산을 점유하고 있고 소유권을 이전받은 매수인에게서 매매대금 일부를 지급받지 못하고 있다고 하여 매매대금채권을 피담보채권으로 매수인이나 그에게서 부동산 소유권을 취득한 제3자를 상대로 유치권을 주장할 수는 없다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2026_32-31-3","t":"제한물권은 이해관계인의 이익을 부당하게 침해하지 않는 한 자유로이 포기할 수 있는 것이 원칙이고, 유치권은 채권자의 이익을 보호하기 위한 법정담보물권인 점을 고려할 때 당사자는 미리 유치권의 발생을 막는 특약을 할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2026_32-31-4","t":"경매로 인한 압류의 효력이 발생하기 전에 유치권을 취득한 경우에는 유치권 취득시기가 근저당권 설정 이후라거나 유치권 취득 전에 설정된 근저당권에 기하여 경매절차가 개시되었다고 하더라도 점유자는 유치권으로 경매절차의 매수인에게 대항할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2026_32-31-5","t":"건물의 신축공사를 도급받은 수급인이 사회통념상 독립한 건물이라고 볼 수 없는 정착물을 토지에 설치한 상태에서 공사가 중단된 경우, 그 정착물에 대하여 유치권을 행사할 수 있는 것이고, 또한 공사중단 시까지 발생한 공사금 채권을 피담보채권으로 하여 토지에 대하여 유치권을 행사할 수도 있는 것이다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2026_32-34-1","t":"질권의 목적인 채권에 대하여 질권설정자의 일반채권자의 신청으로 압류⋅전부명령이 내려진 경우에도 그 명령이 송달된 날보다 먼저 질권자가 확정일자 있는 문서에 의해 민법 제349조 제1항에서 정한 대항요건을 갖추었다면, 전부채권자는 질권이 설정된 채권을 이전받을 뿐이고 제3채무자는 전부채권자에게 변제했음을 들어 질권자에게 대항할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2026_32-34-2","t":"제3채무자가 질권설정 사실을 승낙한 후 질권설정계약이 합의해지된 경우 질권설정자가 해지를 이유로 제3채무자에게 원래의 채권으로 대항하려면 질권자가 제3채무자에게 해지 사실을 통지하여야 하고, 만일 질권자가 제3채무자에게 질권설정계약의 해지 사실을 통지하였다면, 설사 아직 해지가 되지 아니하였다고 하더라도 선의인 제3채무자는 질권설정자에게 대항할 수 있는 사유로 질권자에게 대항할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2026_32-34-3","t":"임대인이 별도로 갱신거절을 하지 아니함에 따라 임대차계약이 묵시적으로 갱신되는 결과가 발생하는 것은, 질권의 목적인 임대차보증금반환채권 자체가 아니라 이를 발생시키는 기본적 계약관계에 관한 사유에 속할 뿐만 아니라 질권설정자인 임차인이 위 채권 자체의 소멸을 목적으로 하거나 질권자의 이익을 해하는 변경을 한 것으로도 볼 수 없으므로, 이 경우에는 질권설정자는 질권자의 동의 없이 질권의 목적된 권리를 소멸하게 하거나 질권자의 이익을 해하는 변경을 할 수 없다는 민법 제352조의 제한을 받지 아니한다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2026_32-34-4","t":"질권설정자의 채무자에 대한 근저당권부채권 범위를 초과하여 질권자의 질권설정자에 대한 피담보채권 범위 내에서 질권자에게 배당금이 직접 지급됨으로써 질권자가 피담보채권의 만족을 얻은 경우, 근저당권부채권 범위를 초과하여 배당금을 수령한 질권자는 법률상 원인 없이 이득을 얻은 사람에 해당하므로 부당이득의 반환책임을 부담한다.","ox":"X","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2026_32-34-5","t":"저당권부 채권에 대한 질권의 등기를 할 때 부동산등기법이 ‘채권액 또는 채권최고액, 채무자의 성명 또는 명칭과 주소 또는 사무소 소재지, 변제기와 이자의 약정이 있는 경우에는 그 내용’을 기록하여야 한다고 정하고 있어 채권의 지연손해금을 등기사항으로 정하고 있지 않고 있다는 사정 등에 비추어 보면, 채권의 지연손해금을 별도로 등기부에 기재하지 않았더라도 근저당권부 질권의 피담보채권의 범위가 등기부에 기재된 약정이자에 한정된다고 볼 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2026_32-37-1","t":"가등기담보 등에 관한 법률(이하 ‘가등기담보법’이라고 한다)은 재산권 이전의 예약에 의한 가등기담보에 있어서 재산의 예약 당시의 가액이 차용액 및 이에 붙인 이자의 합산액을 초과하는 경우에 적용되는바, 재산권 이전의 예약 당시 재산에 대하여 선순위 근저당권이 설정되어 있는 경우에는 재산의 가액에서 피담보채무액을 공제한 나머지 가액이 차용액 및 이에 붙인 이자의 합산액을 초과하는 경우에만 적용된다.","ox":"O","m":"①","c":"A","tp":"가등기담보권"},{"y":2026,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2026_32-37-2","t":"가등기담보법 제3조, 제4조의 청산절차를 위반하여 이루어진 담보가등기에 기한 본등기가 무효라고 하더라도 선의의 제3자가 그 본등기에 터 잡아 소유권이전등기를 마치는 등으로 담보목적부동산의 소유권을 취득하면, 가등기담보법 제2조 제2호에서 정한 채무자 등은 더 이상 가등기담보법 제11조 본문에 따라 채권자를 상대로 그 본등기의 말소를 청구할 수 없게 된다. 이 경우 그 반사적 효과로서 무효인 채권자 명의의 본등기는 그 등기를 마친 시점으로 소급하여 확정적으로 유효하게 되고, 이에 따라 담보목적부동산에 관한 채권자의 가등기담보권은 소멸하며, 청산절차를 거치지 않아 무효였던 채권자의 위 본등기에 터 잡아 이루어진 등기 역시 소급하여 유효하게 된다고 보아야 한다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2026_32-37-3","t":"가등기담보법은 차용물의 반환에 관하여 다른 재산권을 이전할 것을 예약한 경우에 적용되므로 매매대금채권을 담보하기 위하여 가등기를 한 경우에는 위 법률은 적용되지 아니한다.","ox":"O","m":"③","c":"A","tp":"가등기담보권"},{"y":2026,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2026_32-37-4","t":"채권담보를 목적으로 가등기를 하는 경우에는 원칙적으로 채권자와 가등기명의자가 동일인이 되어야 하지만, 채권자 아닌 제3자의 명의로 가등기를 하는 데 대하여 채권자와 채무자 및 제3자 사이에 합의가 있었고, 나아가 제3자에게 그 채권이 실질적으로 귀속되었다고 볼 수 있는 특별한 사정이 있거나 채권자와 제3자가 불가분적 채권자의 관계에 있다고 볼 수 있는 경우에는 그 제3자 명의의 가등기도 유효하다고 볼 것이고, 이를 부동산 실권리자명의 등기에 관한 법률이 금지하고 있는 실권리자 아닌 자 명의의 등기라고 할 수는 없다.","ox":"O","m":"④","c":"A","tp":"가등기담보권"},{"y":2026,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2026_32-37-5","t":"가등기담보권은 그 존재가 가등기에 의해 공시되어 후순위 권리자로 하여금 예측할 수 없는 위험에 빠지게 하는 것이 아니므로, 채권자와 채무자가 가등기담보권설정계약을 체결하면서 가등기 이후에 발생할 채권도 후순위권리자에 대하여 우선변제권을 가지는 가등기담보권의 피담보채권에 포함시키기로 약정할 수 있고, 가등기담보권 설정 후에 후순위권리자나 제3취득자 등 이해관계 있는 제3자가 생긴 경우라도 새로운 약정으로 기존 가등기담보권에 피담보채권을 추가할 수 있다.","ox":"X","m":"⑤","c":"A"}],"2":[{"y":2016,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2016_22-06-1","t":"혼인이나 입양과 같은 신분행위에는 조건이나 기한을 붙일 수 없으나, 유언에는 조건을 붙일 수 있다.","ox":"O","m":"①","c":"A","tp":"조건과 기한"},{"y":2016,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2016_22-06-2","t":"원고 甲과 피고 乙은 금전지급청구 소송 중 ‘원고는 피고로부터 합의금 1억 원을 지급받은 후 본 소를 취하한다.’는 조건부 소취하 합의를 하였으나, 그 후 乙이 위 약정을 불이행하고 있다면, 甲으로서는 그 소송을 계속 유지할 법률상의 이익이 있다.","ox":"O","m":"②","c":"A","tp":"조건과 기한"},{"y":2016,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2016_22-06-3","t":"甲이 자신의 A토지를 乙에게 매도하면서 ‘乙은 A토지 중 공장부지 및 그 진입도로부지에 편입되지 아니할 부분토지를 매도인 甲에게 원가로 반환한다.’는 약정을 한 경우, 위 약정은 공장부지 및 진입도로로 사용되지 아니하기로 확정된 때에는 그 부분토지에 관한 매매는 해제되어 원상태로 돌아간다는 일종의 해제조건부 매매라고 봄이 상당하고, 그 환원에 당사자의 의사표시를 필요로 하는 조건부환매계약이라고 볼 수 없다.","ox":"O","m":"③","c":"A","tp":"조건과 기한"},{"y":2016,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2016_22-06-4","t":"甲은 2015. 3. 6. 자신 소유 A건물을 乙에게 매도하면서, ‘매매계약의 효력은 丙이 사망하면 발생하고, 그때 바로 매매대금을 지급함과 동시에 소유권이전등기를 해주기로 한다.’는 약정을 한 경우, 丙이 2016. 3. 6. 사망하였다면 매매계약은 매매계약체결시점인 2015. 3. 6.에 소급하여 효력이 발생한다.","ox":"X","m":"④","c":"A","tp":"조건과 기한"},{"y":2016,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2016_22-06-5","t":"어떠한 법률행위가 조건의 성취 시 법률행위의 효력이 발생하는 소위 정지조건부 법률행위에 해당한다는 사실은 그 법률행위로 인한 법률효과의 발생을 저지하는 사유로서 그 법률효과의 발생을 다투려는 자에게 주장입증책임이 있다.","ox":"O","m":"⑤","c":"A","tp":"조건과 기한"},{"y":2016,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2016_22-11-1","t":"선량한 풍속 기타 사회질서는 부단히 변천하는 가치관념으로서 어느 법률행위가 이에 위반되어 민법 제103조에 의하여 무효인지 여부는 그 법률행위가 이루어진 때를 기준으로 판단하여야 하고, 또한 그 법률행위가 유효로 인정될 경우의 부작용, 거래자유의 보장 및 규제의 필요성, 사회적 비난의 정도, 당사자 사이의 이익균형 등 제반 사정을 종합적으로 고려하여 사회통념에 따라 합리적으로 판단하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2016_22-11-2","t":"무효인 법률행위가 다른 법률행위의 요건을 구비하고 당사자가 그 무효를 알았더라면 다른 법률행위를 하는 것을 의욕하였으리라고 인정될 때에는 다른 법률행위로서 효력을 가진다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2016_22-11-3","t":"법률행위의 일부분이 무효인 때에는 그 전부를 무효로 하지만, 그 무효 부분이 없더라도 법률행위를 하였을 것이라고 인정될 때에는 나머지 부분은 무효가 되지 아니한다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2016_22-11-4","t":"불공정한 법률행위로서 무효인 경우에도 피해자가 그 무효임을 알고 추인한 경우에는 유효한 법률행위가 된다.","ox":"X","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2016_22-11-5","t":"위약벌의 약정은 채무의 이행을 확보하기 위하여 정해지는 것이나, 그 의무의 강제에 의하여 얻어지는 채권자의 이익에 비하여 약정된 벌이 과도하게 무거울 때에는 그 일부 또는 전부가 공서양속에 반하여 무효로 된다. 그런데 당사자가 약정한 위약벌의 액수가 과다하다는 이유로 법원이 계약의 구체적 내용에 개입하여 그 약정의 전부 또는 일부를 무효로 하는 것은, 사적 자치의 원칙에 대한 중대한 제약이 될 수 있고, 스스로가 한 약정을 이행하지 않겠다며 계약의 구속력으로부터 이탈하고자 하는 당사자를 보호하는 결과가 될 수 있으므로, 가급적 자제하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2016_22-15-1","t":"소멸시효는 법률행위에 의하여 이를 배제, 연장 또는 가중할 수 없고, 이를 단축 또는 경감할 수도 없다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2016_22-15-2","t":"하나의 금전채권의 원금 중 일부가 변제된 후 나머지 원금에 대하여 소멸시효가 완성된 경우, 소멸시효 완성의 효력은 소멸시효가 완성된 원금 부분으로부터 그 완성 전에 발생한 이자 또는 지연손해금 뿐만 아니라 변제로 소멸한 원금 부분으로부터 그 변제 전에 발생한 이자 또는 지연손해금에도 미친다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2016_22-15-3","t":"소멸시효 중단사유에 해당하는 민법 제170조 제1항 소정의 ‘재판상의 청구’라 함은 종국판결을 받기 위한 ‘소의 제기’에 한정되기 때문에 지급명령의 신청은 이에 포함되지 아니한다.","ox":"X","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2016_22-15-4","t":"일정한 채권의 소멸시효기간에 관하여 이를 특별히 1년의 단기로 정하는 민법 제164조는 그 각 호에서 개별적으로 정하여진 채권의 채권자가 그 채권의 발생원인이 된 계약에 기하여 상대방에 대하여 부담하는 반대채무에 대하여는 적용되지 않는다. 따라서 그 채권의 상대방이 그 계약에 기하여 가지는 반대채권은 원칙으로 돌아가, 다른 특별한 사정이 없는 한 민법 제162조 제1항에서 정하는 10년의 일반소멸시효기간의 적용을 받는다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2016_22-15-5","t":"부동산에 관한 경매절차에서 매각대금이 납부되고 매각을 원인으로 가압류등기가 말소되었다고 하더라도, 가압류등기 말소 후의 배당절차에서 가압류채권자의 채권에 대한 배당이 이루어지고 배당액이 공탁되었다면 가압류채권자가 그 공탁금에 대하여 채권자로서 권리행사를 계속하고 있다고 볼 수 있으므로 가압류에 의한 시효중단의 효력은 계속된다.","ox":"X","m":"⑤","c":"A","tp":"소멸시효"},{"y":2017,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2017_23-05-1","t":"불공정한 법률행위로서 무효인 경우에는 추인에 의하여 그 무효인 법률행위가 유효로 될 수 없고, 무효행위의 전환에 관한 민법 제138조가 적용될 수도 없다.","ox":"X","m":"①","c":"A","tp":"법률행위의 무효"},{"y":2017,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2017_23-05-2","t":"매매계약이 민법 제104조에서 정하는 ‘불공정한 법률행위’에 해당하여 무효라고 한다면, 그 계약으로 인하여 불이익을 입는 당사자로 하여금 위와 같은 불공정성을 소송 등 사법적 구제수단을 통하여 주장하지 못하도록 하는 부제소합의 역시 다른 특별한 사정이 없는 한 무효라고 할 것이다.","ox":"O","m":"②","c":"A","tp":"법률행위의 무효"},{"y":2017,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2017_23-05-3","t":"복수의 당사자 사이에 어떠한 합의를 한 경우 그 합의는 전체로서 일체성을 가지는 것이므로, 그 중 한 당사자의 의사표시가 무효인 것으로 판명된 경우 나머지 당사자 사이의 합의가 유효한지의 여부는 민법 제137조에 정한 바에 따라 당사자가 그 무효 부분이 없더라도 법률행위를 하였을 것이라고 인정되는지의 여부에 의하여 판정되어야 한다.","ox":"O","m":"③","c":"A","tp":"법률행위의 무효"},{"y":2017,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2017_23-05-4","t":"무효인 법률행위는 추인하여도 그 효력이 생기지 아니한다. 그러나 당사자가 그 무효임을 알고 추인한 때에는 새로운 법률행위로 본다.","ox":"O","m":"④","c":"A","tp":"법률행위의 무효"},{"y":2017,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2017_23-05-5","t":"무효인 법률행위는 그 법률행위가 성립한 당초부터 당연히 효력이 발생하지 않는 것이므로, 무효인 법률행위에 따른 법률효과를 침해하는 것처럼 보이는 위법행위나 채무불이행이 있다고 하여도 법률효과의 침해에 따른 손해는 없는 것이므로 그 손해배상을 청구할 수는 없다고 보아야 한다.","ox":"O","m":"⑤","c":"A","tp":"법률행위의 무효"},{"y":2017,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2017_23-06-1","t":"지급명령은 채권자가 법정기간 내에 가집행신청을 하지 아니함으로 인하여 그 효력을 잃은 때에는 시효중단의 효력이 없다.","ox":"O","m":"①","c":"A","tp":"소멸시효"},{"y":2017,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2017_23-06-2","t":"하나의 금전채권의 원금 중 일부가 변제된 후 나머지 원금에 대하여 소멸시효가 완성된 경우, 소멸시효 완성의 효력은 소멸시효가 완성된 원금 부분으로부터 그 완성 전에 발생한 이자 또는 지연손해금에는 미치나 변제로 소멸한 원금 부분으로부터 그 변제 전에 발생한 이자 또는 지연손해금에는 미치지 않는다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2017_23-06-3","t":"임대차 존속 중 차임채권의 소멸시효가 완성된 경우, 특별한 사정이 없는 한 임대인이 소멸시효가 완성된 차임채권을 자동채권으로 삼아 임대차보증금 반환채무와 상계할 수는 없으나 민법 제495조의 유추적용에 의하여 연체차임을 임대차보증금에서 공제할 수는 있다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2017_23-06-4","t":"도급받은 공사의 공사대금채권은 민법 제163조 제3호에 따라 3년의 단기소멸시효가 적용된다. 나아가 민법 제666조에 따라 수급인이 공사대금채권을 담보하기 위하여 도급인에 대해 갖는 저당권설정청구권은 공사에 부수되는 채권으로서 그 소멸시효기간 역시 3년이다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2017_23-06-5","t":"채권자와 주채무자 사이의 확정판결에 의하여 주채무가 확정되어 그 소멸시효기간이 10년으로 연장되면, 그 보증채무 역시 당연히 단기소멸시효의 적용이 배제되어 10년의 소멸시효기간이 적용된다.","ox":"X","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2018_24-26-1","t":"민법 제999조 제2항은 “상속회복청구권은 그 침해를 안 날부터 3년, 상속권의 침해행위가 있은 날부터 10년을 경과하면 소멸된다.”라고 규정하고 있는데, 그중 10년의 장기 제척기간은 상속권 침해행위로 인하여 상속회복청구권이 발생한 때부터 바로 진행한다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2018_24-26-2","t":"채권양도의 통지는 그 양도인이 채권이 양도되었다는 사실을 채무자에게 알리는 것에 그치는 행위이므로, 그것만으로 제척기간의 준수에 필요한 권리의 재판외 행사에 해당한다고 할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2018_24-26-3","t":"완성된 목적물에 하자가 있는 때에는 도급인은 수급인에 대하여 상당한 기간을 정하여 그 하자의 보수를 청구할 수 있고(민법 제667조 제1항), 그와 같은 하자 보수 청구는 목적물을 인도받은 날로부터 1년내에 하여야 한다(민법 제670조 제1항). 이때 민법 제670조 제1항에 정한 수급인의 하자담보책임에 관한 기간은 제척기간으로서 재판상 또는 재판외의 권리행사기간이며 재판상 청구를 위한 출소기간이 아니다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2018_24-26-4","t":"민법 제205조에 의하면, 점유자가 점유의 방해를 받은 때에는 방해의 제거 및 손해의 배상을 청구할 수 있고(제1항), 제1항의 청구권은 방해가 종료한 날로부터 1년내에 행사하여야 하는데(제2항), 민법 제205조 제2항이 정한 ‘1년의 제척기간’은 재판 외에서 권리행사하는 것으로 족한 기간이 아니라 반드시 그 기간 내에 소를 제기하여야 하는 출소기간이다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2018_24-26-5","t":"민법 제555조는 “증여의 의사가 서면으로 표시되지 아니한 경우에는 각 당사자는 이를 해제할 수 있다.”라고 규정하고 있다. 그에 기한 해제권은 특별한 존속기한의 정함이 없는 형성권에 해당하므로, 형성권의 제척기간인 10년을 경과한 후에는 이를 행사할 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2018_24-27","t":"취소에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"취소에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["근로계약은 근로자가 사용자에게 근로를 제공하고 사용자는 이에 대하여 임금을 지급하는 것을 목적으로 체결된 계약으로서 계약 체결에 관한 당사자들의 의사표시에 무효 또는 취소의 사유가 있으면, 상대방은 이를 이유로 근로계약의 무효 또는 취소를 주장하여 그에 따른 법률효과의 발생을 부정하거나 소멸시킬 수 있고, 민법 제141조가 적용되어 취소된 근로계약은 처음부터 무효인 것으로 된다.","법률행위가 사기에 의한 것으로서 취소되는 경우에 그 법률행위가 동시에 불법행위를 구성하는 때에는 취소의 효과로 생기는 부당이득반환청구권과 불법행위로 인한 손해배상청구권은 경합하여 병존하는 것이므로, 채권자는 어느 것이라도 선택하여 행사할 수 있지만 중첩적으로 행사할 수는 없다.","취소권은 추인할 수 있는 날로부터 3년내에 법률행위를 한 날로부터 10년내에 행사하여야 한다.","취소한 법률행위는 처음부터 무효인 것으로 간주되므로 취소할 수 있는 법률행위가 일단 취소된 이상 그 후에는 취소할 수 있는 법률행위의 추인이 아니라 무효인 법률행위의 추인의 요건과 효력으로서 추인할 수 있다.","법률행위의 취소는 상대방에 대한 의사표시로 하여야 하나 그 취소의 의사표시는 특별히 재판상 행하여짐이 요구되는 경우 이외에는 특정한 방식이 요구되는 것이 아니다. 23-18"],"a":1}},{"y":2018,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2018_24-36-1","t":"시효완성 후 소멸시효 중단사유에 해당하는 채무의 승인이 있었다 하더라도 그것만으로는 곧바로 소멸시효 이익의 포기라는 의사표시가 있었다고 단정할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2018_24-36-2","t":"시효중단 사유 중 하나인 가압류가 이루어진 경우, 소멸시효 중단의 효력은 가압류신청을 한 때로 소급한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2018_24-36-3","t":"채무자가 계약상 채무를 이행하지 않았다고 하더라도 채권자는 여전히 해당 계약에서 정한 채권을 보유하고 있다. 그러므로 특별한 사정이 없는 한 채무자가 그 채무를 이행하지 않고 있다고 하여 채무자가 법률상 원인 없이 이득을 얻었다고 할 수는 없다. 이는 그 채권이 시효로 소멸하였다 하더라도 마찬가지이다.","ox":"O","m":"③","c":"A","tp":"소멸시효"},{"y":2018,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2018_24-36-4","t":"민법 제176조는 ‘압류, 가압류 및 가처분은 시효의 이익을 받은 자에 대하여 하지 아니한 때에는 이를 그에게 통지한 후가 아니면 시효중단의 효력이 없다’고 규정하고 있다. 하지만 채권자의 신청에 따라 연대보증채무자 겸 물상보증인 A 소유 담보부동산에 대한 임의경매개시결정이 내려져 그 결정이 A에게 송달되고 압류의 효력이 생겼다면, 채권자는 그 압류 사실을 주채무자에게 통지하지 않더라도 주채무의 시효 중단을 주장할 수 있다.","ox":"X","m":"④","c":"A","tp":"소멸시효"},{"y":2018,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2018_24-36-5","t":"원금채무에 관하여는 소멸시효가 완성되지 아니하였으나 이자채무에 관하여는 소멸시효가 완성된 상태에서 채무자가 채무를 일부 변제한 때에는 그 액수에 관하여 다툼이 없는 한 그 원금채무에 관하여 묵시적으로 승인하는 한편 그 이자채무에 관하여 시효완성의 사실을 알고 그 이익을 포기한 것으로 추정된다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2018_24-37-1","t":"장래에 발생할 특정 조건부 채권을 담보하기 위하여도 저당권을 설정할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2018_24-37-2","t":"경개계약에도 조건을 붙일 수 있고, 조건부 경개의 경우에는 구채무의 소멸과 신채무의 성립 자체가 그 조건의 성취 여부에 걸려 있게 된다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2018_24-37-3","t":"채무자의 재산처분행위가 사해행위가 되는지는 처분행위 당시를 기준으로 판단하여야 하며, 설령 재산처분행위가 정지조건부인 경우라 하더라도 특별한 사정이 없는 한 마찬가지이다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2018_24-37-4","t":"지명채권 양도의 대항요건인 채무자의 승낙은 관념의 통지에 불과하므로, 채무자는 채권양도를 승낙하면서 조건을 붙일 수 없다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2018_24-37-5","t":"해제조건부증여로 인한 부동산소유권이전등기를 마쳤다 하더라도 그 해제조건이 성취되면 그 소유권은 증여자에게 복귀한다. 이 경우 당사자 사이에 다른 의사표시가 없는 한 그 조건성취의 효과는 소급하지 아니하나, 조건성취 전에 수증자가 한 처분행위는 조건성취의 효과를 제한하는 한도 내에서는 무효이고, 다만 그 조건이 등기되어 있지 않는 한 그 처분행위로 인하여 권리를 취득한 제3자에게 위 무효를 대항할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2018_24-40","t":"일부무효 및 무효행위의 전환에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"일부무효 및 무효행위의 전환에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["사용자가 근로자의 임금 지급에 갈음하여 사용자가 제3자에 대하여 가지는 채권을 근로자에게 양도하기로 하는 약정은 그 전부가 무효임이 원칙이나, 당사자 쌍방이 위와 같은 무효를 알았더라면 임금의 지급에 갈음하는 것이 아니라 그 지급을 위하여 채권을 양도하는 것을 의욕하였으리라고 인정될 때에는 무효행위 전환의 법리에 따라 그 채권양도 약정은 임금의 지급을 위하여 한 것으로서 효력을 가질 수 있다.","매매계약이 약정된 매매대금의 과다로 말미암아 민법 제104조에서 정하는 ‘불공정한 법률행위’에 해당하여 무효인 경우에도 무효행위의 전환에 관한 민법 제138조가 적용될 수 있다.","甲과 乙 보험회사가 피보험자를 만 7세인 甲의 아들 丙으로 하고 보험수익자를 甲으로 하여, 丙이 재해로 사망하였을 때는 사망보험금을 지급하고 재해로 장해를 입었을 때는 소득상실보조금 등을 지급하는 내용의 보험계약을 체결하였는데, 丙이 교통사고로 보험약관에서 정한 후유장해진단을 받은 사안에서, 甲이 보험계약을 체결한 목적 등에 비추어 甲과 乙 회사는 보험계약 중 재해로 인한 사망을 보험금 지급사유로 하는 부분이 상법 제732조에 의하여 무효라는 사실을 알았더라도 나머지 보험금 지급사유 부분에 관한 보험계약을 체결하였을 것으로 볼 수 있으면, 그 부분에 관한 보험계약은 여전히 유효하다.","복수의 당사자 사이에 어떠한 합의를 한 경우 그 합의는 전체로서 일체성을 가지는 것이므로, 그 중 한 당사자의 의사표시가 무효인 것으로 판명된 경우 나머지 당사자 사이의 합의가 유효한지의 여부도 민법 제137조에 정한 바에 따라 당사자가 그 무효 부분이 없더라도 법률행위를 하였을 것이라고 인정되는지의 여부에 의하여 판정되어야 한다.","민법 제137조는 임의규정으로서 의사자치의 원칙이 지배하는 영역에서 적용된다고 할 것이므로, 법률행위의 일부가 강행법규인 효력규정에 위반되어 무효가 되는 경우에는 언제나 적용되지 않는다."],"a":5}},{"y":2019,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2019_25-02-1","t":"무효인 법률행위가 다른 법률행위의 요건을 구비하고 당사자가 그 무효를 알았더라면 다른 법률행위를 하는 것을 의욕하였으리라고 인정될 때에는 다른 법률행위로서 효력을 가진다.","ox":"O","m":"①","c":"A","tp":"법률행위의 무효"},{"y":2019,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2019_25-02-2","t":"당사자가 이전의 법률행위가 존재함을 알고 그 유효함을 전제로 하여 이에 터 잡은 후속행위를 하였다고 해서 그것만으로 이전의 법률행위를 묵시적으로 추인하였다고 단정할 수 없다.","ox":"O","m":"②","c":"A","tp":"법률행위의 무효"},{"y":2019,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2019_25-02-3","t":"유동적 무효의 상태에 있는 거래계약의 당사자라도 상대방이 그 거래계약의 효력이 완성되도록 협력할 의무를 이행하지 아니하였음을 들어 일방적으로 유동적 무효의 상태에 있는 거래계약 자체를 해제할 수는 없다.","ox":"O","m":"③","c":"A","tp":"법률행위의 무효"},{"y":2019,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2019_25-02-4","t":"상속재산 전부를 공동상속인 중 1인에게 상속시킬 방편으로 나머지 상속인들이 법원에 한 상속포기신고가 그 법정기간 경과 후에 한 것으로서 재산상속 포기로서의 효력이 생기지 아니하더라도, 그에 따라 위 공동상속인들 사이에는 위 1인이 고유의 법정상속분을 초과하여 상속재산 전부를 취득하고 위 잔여 상속인들은 이를 전혀 취득하지 않기로 하는 내용의 상속재산에 관한 협의분할이 이루어진 것으로 볼 수 있다.","ox":"O","m":"④","c":"A","tp":"법률행위의 무효"},{"y":2019,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2019_25-02-5","t":"재건축사업부지에 포함된 토지에 대하여 재건축조합과 토지의 소유자가 체결한 매매계약이 매매대금의 과다로 말미암아 불공정한 법률행위에 해당한다면, 해당 매매계약은 전부 무효가 되는 것이고, 적정한 매매대금으로 감액된 내용으로 유효하다고 볼 여지는 없다.","ox":"X","m":"⑤","c":"A","tp":"법률행위의 무효"},{"y":2019,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2019_25-33-1","t":"당사자의 궁박, 경솔 또는 무경험으로 인하여 현저하게 공정을 잃은 법률행위는 무효로 한다.","ox":"O","m":"①","c":"A","tp":"민법 제104조의 불공정한 법률행위"},{"y":2019,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2019_25-33-2","t":"피해 당사자가 궁박, 경솔 또는 무경험의 상태에 있었다면, 그 상대방 당사자에게 폭리행위의 악의가 없었다 하더라도 불공정한 법률행위가 성립한다.","ox":"X","m":"②","c":"A","tp":"민법 제104조의 불공정한 법률행위"},{"y":2019,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2019_25-33-3","t":"증여계약과 같이 아무런 대가관계 없이 당사자 일방이 상대방에게 일방적인 급부를 하는 법률행위에는 민법 제104조가 적용되지 않는다.","ox":"O","m":"③","c":"A","tp":"민법 제104조의 불공정한 법률행위"},{"y":2019,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2019_25-33-4","t":"단체협약이 노동조합의 쟁의행위 끝에 체결되었고 사용자 측의 경영상태에 비추어 그 내용이 다소 합리성을 결하였다고 하더라도 그러한 사정만으로 이를 궁박한 상태에서 이루어진 불공정한 법률행위에 해당한다고 할 수 없다.","ox":"O","m":"④","c":"A","tp":"민법 제104조의 불공정한 법률행위"},{"y":2019,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2019_25-33-5","t":"대리인에 의하여 법률행위가 이루어진 경우, 그 법률행위가 민법 제104조의 불공정한 법률행위에 해당하는지 여부를 판단함에 있어서 경솔과 무경험은 대리인을 기준으로 하여 판단하고, 궁박은 본인을 기준으로 판단하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2019_25-36-1","t":"부관이 붙은 법률행위에서, 부관에 표시된 사실이 발생하지 않으면 채무를 이행하지 않아도 된다고 보는 것이 상당한 경우에는 조건으로 보아야 하고, 표시된 사실이 발생한 때에는 물론이고 발생하지 않는 것으로 확정된 때에도 그 채무를 이행하여야 한다고 보는 것이 상당한 경우에는 불확정기한으로 보아야 한다.","ox":"O","m":"①","c":"A","tp":"법률행위의 부관"},{"y":2019,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2019_25-36-2","t":"조건을 붙이고자 하는 의사는 법률행위의 내용으로 외부에 표시되어야 하고, 조건을 붙이고자 하는 의사의 표시는 그 방법에 관하여 일정한 방식이 요구되지 않으므로 묵시적 의사표시나 묵시적 약정으로도 할 수 있다.","ox":"O","m":"②","c":"A","tp":"법률행위의 부관"},{"y":2019,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2019_25-36-3","t":"제작물공급계약의 당사자들이 보수의 지급시기에 관하여 “수급인이 공급한 목적물을 도급인이 검사하여 합격하면, 도급인은 수급인에게 그 보수를 지급한다”는 내용의 약정은 도급인의 수급인에 대한 보수지급의무와 동시이행관계에 있는 수급인의 목적물 인도의무를 확인한 것에 불과하며, 법률행위의 부관인 조건에 해당하지 아니한다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2019_25-36-4","t":"유언에 정지조건이 있는 경우에 그 조건이 유언자의 사망후에 성취한 때에는 그 조건이 성취한 때로부터 유언의 효력이 생긴다.","ox":"O","m":"④","c":"A","tp":"법률행위의 부관"},{"y":2019,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2019_25-36-5","t":"甲에게 정지조건부 금전채무를 부담하고 있던 乙이 정지조건이 성취되기 전에 자신의 채권자 丙에게 그의 유일한 재산인 아파트에 관하여 근저당권설정계약을 체결하고 근저당권설정등기를 마쳐준 경우, 위 근저당권설정계약은 甲의 乙에 대한 채권의 정지조건이 성취되기 전에 이루어진 것이므로 甲에 대한 관계에서 사해행위가 될 수 없다.","ox":"X","m":"⑤","c":"A","tp":"법률행위의 부관"},{"y":2019,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2019_25-37-1","t":"상대방에게 알려진 법률행위의 동기가 반사회질서적인 경우도 민법 제103조에 의하여 무효로 되는 반사회질서의 법률행위에 포함된다.","ox":"O","m":"①","c":"A","tp":"민법 제103조 소정의 반사회질서 법률행위"},{"y":2019,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2019_25-37-2","t":"행정기관에 진정서를 제출하여 상대방을 궁지에 빠뜨린 다음 이를 취하하는 것을 조건으로 거액의 급부를 제공받기로 한 약정은 민법 제103조의 반사회질서 행위에 해당하여 무효이다.","ox":"O","m":"②","c":"A","tp":"민법 제103조 소정의 반사회질서 법률행위"},{"y":2019,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2019_25-37-3","t":"강제집행을 면할 목적으로 부동산에 허위의 근저당권설정등기를 경료하는 행위는 민법 제103조의 선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위로 볼 수 없다.","ox":"O","m":"③","c":"A","tp":"민법 제103조 소정의 반사회질서 법률행위"},{"y":2019,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2019_25-37-4","t":"소득세법령의 규정에 의하여 당해 자산의 양도 당시의 기준시가가 아닌 양도자와 양수자 간에 실제로 거래한 가액을 양도가액으로 하는 경우, 양도소득세의 일부를 회피할 목적으로 매매계약서에 실제로 거래한 가액보다 낮은 금액을 매매대금으로 기재하였다면, 그 매매계약은 사회질서에 반하는 법률행위로서 무효가 된다.","ox":"X","m":"④","c":"A","tp":"민법 제103조 소정의 반사회질서 법률행위"},{"y":2019,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2019_25-37-5","t":"영리를 목적으로 윤락행위를 하도록 권유·유인·알선 또는 강요하거나 이에 협력하는 것은 선량한 풍속 기타 사회질서에 위반되므로 그러한 행위를 하는 자가 영업상 관계있는 윤락행위를 하는 자에 대하여 가지는 채권은 계약의 형식에 관계없이 무효이다.","ox":"O","m":"⑤","c":"A","tp":"민법 제103조 소정의 반사회질서 법률행위"},{"y":2020,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2020_26-06-1","t":"시효중단을 위한 후소로서 이행소송 외에 전소 판결로 확정된 채권의 시효를 중단시키기 위한 조치, 즉 ‘재판상의 청구’가 있다는 점에 대하여만 확인을 구하는 형태의 ‘새로운 방식의 확인소송’이 허용되고, 채권자는 두 가지 형태의 소송 중 자신의 상황과 필요에보다 적합한 것을 선택하여 제기할 수 있다.","ox":"O","m":"①","c":"A","tp":"소멸시효"},{"y":2020,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2020_26-06-2","t":"소유권이전등기의무의 이행불능으로 인한 전보배상청구권의 소멸시효는 이전등기의무가 이행불능 상태인 때부터 진행되므로, 그 부동산에 대하여 제3자의 처분금지가처분등기가 기입되고 이후 그 제3자 명의로 소유권이전등기까지 마쳐진 경우, 처분금지가처분등기가 기입된 때부터 이행불능으로 인한 전보배상청구권의 소멸시효가 진행한다.","ox":"X","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2020_26-06-3","t":"기한이 있는 채권의 소멸시효는 이행기가 도래한 때부터 진행하지만, 이행기가 도래한 후 채권자와 채무자가 기한을 유예하기로 합의한 경우에는 유예된 때로 이행기가 변경되어 소멸시효는 변경된 이행기가 도래한 때부터 다시 진행한다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2020_26-06-4","t":"민법 제163조 제2호 소정의 의사의 치료에 관한 채권에 있어서는, 특약이 없는 한 그 개개의 진료가 종료될 때마다 각각의 당해 진료에 필요한 비용의 이행기가 도래하여 그에 대한 소멸시효가 진행된다고 해석함이 상당하고, 장기간 입원 치료를 받는 경우라 하더라도 다른 특약이 없는 한 입원 치료 중에 환자에 대하여 치료비를 청구함에 아무런 장애가 없으므로 퇴원시부터 소멸시효가 진행된다고 볼 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2020_26-06-5","t":"권리자인 피고가 응소하여 권리를 주장하였으나 그 소가 취하되어 본안에서 그 권리주장에 관한 판단 없이 소송이 종료된 경우 민법 제170조 제2항을 유추적용하여 그때부터 6월 이내에 재판상의 청구를 하면 응소시에 소급하여 시효중단의 효력이 있다.","ox":"O","m":"⑤","c":"A","tp":"소멸시효"},{"y":2020,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2020_26-16-1","t":"공유자의 한 사람이 공유물의 보존행위로서 소를 제기한 경우에 그로 인한 시효중단의 효력은 재판상의 청구를 한 그 공유자에 한하여 발생한다.","ox":"O","m":"①","c":"A","tp":"소멸시효의 중단"},{"y":2020,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2020_26-16-2","t":"형사고소는 시효중단사유로서의 재판상 청구라고 볼 수 없으나, 정식 기소가 이루어지면 고소를 한 때로 소급하여 시효가 중단된 것으로 본다.","ox":"X","m":"②","c":"A","tp":"소멸시효의 중단"},{"y":2020,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2020_26-16-3","t":"검사 작성의 피의자신문조서의 진술기재 가운데 채무의 일부를 승인하는 의사가 표시되어 있다면 소멸시효 중단사유로서 승인의 의사표시가 있는 것으로는 볼 수 있다.","ox":"X","m":"③","c":"A","tp":"소멸시효의 중단"},{"y":2020,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2020_26-16-4","t":"채권자가 피고로서 응소하여 권리를 주장하였으나 소가 각하되어 본안에서 피고의 주장에 관한 판단 없이 소송이 종료되고, 그로부터 6월 내에 채권자가 원고로서 소를 제기한 경우 소 제기시에 채권의 소멸시효는 중단된다.","ox":"X","m":"④","c":"A","tp":"소멸시효의 중단"},{"y":2020,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2020_26-16-5","t":"변론주의 원칙상 채권자인 피고가 응소행위를 하였다고 하여 바로 시효중단의 효과가 발생하는 것은 아니고 시효중단의 주장을 하여야 그 효력이 생기는 것이며, 시효중단의 주장은 반드시 응소시에 할 필요는 없고 사실심 변론종결 전에만 하면 족하나, 시효중단의 주장을 한 시점이 소멸시효기간이 만료된 후라면 이미 소멸시효가 완성된 것이어서 시효중단의 효력이 생길 여지가 없다.","ox":"X","m":"⑤","c":"A","tp":"소멸시효의 중단"},{"y":2020,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2020_26-23-1","t":"관련 법령에서 정한 한도를 초과하는 부동산 중개수수료 약정은 그 한도를 초과하는 범위 내에서 무효이다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2020_26-23-2","t":"증여계약과 같이 아무런 대가관계 없이 당사자 일방이 상대방에게 일방적인 급부를 하는 법률행위는 민법 제104조 소정의 공정성 여부를 논의할 수 있는 성질의 법률행위가 아니지만, 반사회질서적인 조건이 결부됨으로써 반사회질서적 성질을 띠게 될 여지는 있다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2020_26-23-3","t":"행정기관에 진정서를 제출하여 상대방을 궁지에 빠뜨린 다음 이를 취하하는 조건으로 거액의 급부를 제공받기로 약정한 것은 민법 제103조 소정의 반사회질서의 법률행위에 해당하여 무효이다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2020_26-23-4","t":"주택매매계약에 있어서 매도인으로 하여금 양도소득세를 면탈케 할 목적으로 소유권이전등기는 3년 후에 넘겨 받기로 한 특약은 사회질서에 반하는 것으로서 무효이다.","ox":"X","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2020_26-23-5","t":"어떠한 법률행위가 불공정한 법률행위에 해당하는지는 법률행위 시를 기준으로 판단하여야 하므로 계약 체결 당시를 기준으로 불공정한 것이 아니라면, 사후에 외부적 환경의 급격한 변화에 따라 계약당사자 일방에게 큰 손실이 발생하고 상대방에게는 그에 상응하는 큰 이익이 발생할 수 있는 구조라고 하여 그 계약이 당연히 불공정한 계약에 해당한다고 할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2020_26-33-1","t":"매매계약이 약정된 매매대금의 과다로 말미암아 민법 제104조에서 정하는 ‘불공정한 법률행위’에 해당하여 무효인 경우에도 무효행위의 전환에 관한 민법 제138조가 적용될 수 있다.","ox":"O","m":"①","c":"A","tp":"법률행위의 무효와 취소"},{"y":2020,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2020_26-33-2","t":"강박에 의한 의사표시에 대한 취소권은 형성권의 일종으로서 그 행사기간을 제척기간으로 보아야 하고, 취소권자가 취소의 의사표시를 담은 소장 부본을 피고에게 송달함으로써 취소권을 재판상 행사하는 경우에는 소장 부본이 피고에게 도달한 때에 비로소 취소권 행사의 효력이 발생하므로, 취소의 의사표시가 담긴 소장 부본이 제척기간 내에 송달되어야만 취소권자가 제척기간 내에 적법하게 취소권을 행사하였다고 할 것이다.","ox":"O","m":"②","c":"A","tp":"법률행위의 무효와 취소"},{"y":2020,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2020_26-33-3","t":"채권자와 연대보증인 사이의 연대보증계약이 주채무자의 기망에 의하여 체결되어 적법하게 취소되었으나, 그 보증책임이 금전채무로서 채무의 성격상 가분적이고 연대보증인에게 보증한도를 일정 금액으로 하는 보증의사가 있는 경우 연대보증인의 연대보증계약의 취소는 그 일정 금액을 초과하는 범위 내에서만 효력이 생긴다.","ox":"O","m":"③","c":"A","tp":"법률행위의 무효와 취소"},{"y":2020,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2020_26-33-4","t":"파산자가 상대방과 통정한 허위의 의사표시를 통하여 가장채권을 보유하고 있다가 파산이 선고된 경우 총파산채권자를 기준으로 하여 파산채권자 모두가 악의로 되지 않는 한 파산관재인은 선의의 제3자라고 할 수밖에 없다.","ox":"O","m":"④","c":"A","tp":"법률행위의 무효와 취소"},{"y":2020,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2020_26-33-5","t":"조건부 법률행위에 있어 조건의 내용 자체가 불법적인 것이어서 무효일 경우 또는 조건을 붙이는 것이 허용되지 아니하는 법률행위에 조건을 붙인 경우 그 조건만을 분리하여 무효로 할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"법률행위의 무효와 취소"},{"y":2021,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2021_27-18-1","t":"법률행위의 해석에 있어 당사자가 표시한 문언에 의하여 객관적인 의미가 명확하게 드러나지 않는 경우에는 문언의 형식과 내용, 법률행위가 이루어진 동기 및 경위, 당사자가 법률행위에 의하여 달성하려는 목적과 진정한 의사, 거래의 관행 등을 종합적으로 고려하여 사회정의와 형평의 이념에 맞도록 논리와 경험의 법칙, 그리고 사회일반의 상식과 거래의 통념에 따라 합리적으로 해석하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2021_27-18-2","t":"조건은 법률행위 효력의 발생 또는 소멸을 장래 불확실한 사실의 발생 여부에 따라 좌우되게 하는 법률행위의 부관이고, 법률행위에서 효과의사와 일체적인 내용을 이루는 의사표시 그 자체이다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2021_27-18-3","t":"조건을 붙이고자 하는 의사는 법률행위의 내용으로 외부에 표시될 필요가 없고, 조건을 붙이고자 하는 의사가 있는지는 의사표시에 관한 법리에 따라 판단하여야 한다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2021_27-18-4","t":"조건을 붙이고자 하는 의사가 외부에 표시되었다고 인정하려면, 그 법률행위가 이루어진 동기와 경위, 그 법률행위에 의하여 달성하려는 목적, 거래의 관행 등을 종합적으로 고려하여 그 법률행위 효력의 발생 또는 소멸을 장래의 불확실한 사실의 발생 여부에 따라 좌우되게 하려는 의사가 인정되어야 한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2021_27-18-5","t":"법률행위에 붙은 부관이 조건인지 기한인지가 명확하지 않은 경우 법률행위의 해석을 통해서 이를 결정해야 한다. 부관에 표시된 사실이 발생하지 않으면 채무를 이행하지 않아도 된다고 보는 것이 합리적인 경우에는 조건으로 보아야 한다. 그러나 부관에 표시된 사실이 발생한 때에는 물론이고 반대로 발생하지 않는 것이 확정된 때에도 그 채무를 이행하여야 한다고 보는 것이 합리적인 경우에는 표시된 사실의 발생 여부가 확정되는 것을 불확정기한으로 정한 것으로 보아야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2021_27-31-1","t":"소멸시효 중단사유로서의 채무승인은 시효의 이익을 받는 이가 상대방의 권리 등의 존재를 인정하는 일방적 행위로서, 그 권리의 원인·내용이나 범위 등에 관한 구체적 사항을 확인하여야 하는 것은 아니고, 그에 있어서 채무자가 권리 등의 법적 성질까지 알고 있거나 권리 등의 발생원인을 특정하여야 할 필요는 없다고 할 것이다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2021_27-31-2","t":"타인의 채무를 담보하기 위하여 자기의 물건에 담보권을 설정한 물상보증인은 채권자에 대하여 물적 유한책임을 지고 있어 그 피담보채권의 소멸에 의하여 직접 이익을 받는 관계에 있으므로 소멸시효의 완성을 주장할 수 있다. 또한 물상보증인이 그 피담보채무의 부존재 또는 소멸을 이유로 제기한 저당권설정등기 말소등기절차이행청구소송에서 채권자 겸 저당권자가 청구기각의 판결을 구하고 피담보채권의 존재를 주장하였다면 민법 제168조 제1호 소정의 소멸시효 중단사유인 '청구'에 해당한다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2021_27-31-3","t":"형사소송은 피고인에 대한 국가형벌권의 행사를 그 목적으로 하는 것이므로, 피해자가 형사소송에서 소송촉진 등에 관한 특례법에서 정한 배상명령을 신청한 경우를 제외하고는 단지 피해자가 가해자를 상대로 고소하거나 그 고소에 기하여 형사재판이 개시되어도 이를 가지고 소멸시효의 중단사유인 재판상의 청구로 볼 수는 없다. 또한 검사 작성의 피의자신문조서에서 피의자의 진술은 어디까지나 검사를 상대로 이루어지는 것이어서 그 진술기재 가운데 채무의 일부를 승인하는 의사가 표시되어 있다고 하더라도, 그 기재 부분만으로 곧바로 소멸시효 중단사유로서 승인의 의사표시가 있는 것으로 볼 수도 없다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2021_27-31-4","t":"이행인수는 채무자와 인수인 사이의 계약에 따라 인수인이 채권자에 대한 채무를 변제하기로 약정하는 것을 말한다. 이 경우 인수인은 채무자의 채무를 변제하는 등으로 면책시킬 의무를 부담하지만 채권자에 대한 관계에서 직접 이행의무를 부담하게 되는 것은 아니다. 한편 소멸시효 중단사유인 채무의 승인은 시효이익을 받을 당사자나 대리인만 할 수 있으므로 이행인수인이 채권자에 대하여 채무자의 채무를 승인하더라도 다른 특별한 사정이 없는 한 시효중단 사유가 되는 채무승인의 효력은 발생하지 않는다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2021_27-31-5","t":"소멸시효의 중단사유로서의 승인은 소멸시효의 진행이 개시된 이후에만 가능하고 그 이전에 승인을 하더라도 시효가 중단되지는 않는다고 할 것이고, 또한 현존하지 아니하는 장래의 채권을 미리 승인하는 것은 채무자가 그 권리의 존재를 인식하고서 한 것이라고 볼 수 없어 허용되지 않는다고 할 것이다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2021_27-33-1","t":"통정한 허위의 의사표시는 허위표시의 당사자와 포괄승계인 이외의 자로서 그 허위표시에 의하여 외형상 형성된 법률관계를 토대로 실질적으로 새로운 법률상 이해관계를 맺은 선의의 제3자를 제외한 누구에 대하여서나 무효이고, 또한 누구든지 그 무효를 주장할 수 있다. 그러나 비록 무효인 법률행위가 그 법률행위가 성립한 당초부터 당연히 효력이 발생하지 않는 것이라 하더라도, 무효인 법률행위에 따른 법률효과를 침해하는 것처럼 보이는 위법행위나 채무불이행이 있다면 그 손해가 없다고 할 수 없으므로 손해배상을 청구할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2021_27-33-2","t":"매매계약이 약정된 매매대금의 과다로 말미암아 민법 제104조에서 정하는 ‘불공정한 법률행위’에 해당하여 무효인 경우에도 무효행위의 전환에 관한 민법 제138조가 적용될 수 있다. 따라서 당사자 쌍방이 위와 같은 무효를 알았더라면 대금을 다른 액으로 정하여 매매계약에 합의하였을 것이라고 예외적으로 인정되는 경우에는, 그 대금액을 내용으로 하는 매매계약이 유효하게 성립한다고 할 것이다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2021_27-33-3","t":"무권리자가 타인의 권리를 자기의 이름으로 또는 자기의 권리로 처분한 경우에, 권리자는 후일 이를 추인함으로써 그 처분행위를 인정할 수 있고, 특별한 사정이 없는 한 이로써 권리자 본인에게 위 처분행위의 효력이 발생함은 사적 자치의 원칙에 비추어 당연하고, 이 경우 추인은 명시적으로뿐만 아니라 묵시적인 방법으로도 가능하며 그 의사표시는 무권대리인이나 그 상대방 어느 쪽에 하여도 무방하다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2021_27-33-4","t":"취소의 의사표시란 반드시 명시적이어야 하는 것은 아니고, 취소자가 그 착오를 이유로 자신의 법률행위의 효력을 처음부터 배제하려고 한다는 의사가 드러나면 족한 것이며, 취소원인의 진술 없이도 취소의 의사표시는 유효한 것이다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2021_27-33-5","t":"당사자가 이전의 법률행위가 존재함을 알고 그 유효함을 전제로 하여 이에 터 잡은 후속행위를 하였다고 해서 그것만으로 이전의 법률행위를 묵시적으로 추인하였다고 단정할 수는 없고, 묵시적 추인을 인정하기 위해서는 이전의 법률행위가 무효임을 알거나 적어도 무효임을 의심하면서도 그 행위의 효과를 자기에게 귀속시키도록 하는 의사로 후속행위를 하였음이 인정되어야 할 것이다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2022_28-05-1","t":"건물에 관한 소유권이전등기청구권에 있어서 그 목적물인 건물이 완공되지 아니하여 이를 행사할 수 없었다는 사유는 사실상의 장애사유에 불과하다.","ox":"X","m":"①","c":"A","tp":"소멸시효의 중단"},{"y":2022,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2022_28-05-2","t":"체납처분에 의한 채권압류로 인하여 채권자의 채무자에 대한 채권의 시효가 중단된 경우에 압류에 의한 체납처분 절차가 채권추심 등으로 종료된 때뿐만 아니라, 피압류채권이 기본계약관계의 해지·실효 또는 소멸시효 완성 등으로 인하여 소멸함으로써 압류의 대상이 존재하지 않게 되어 압류 자체가 실효된 경우에도 체납처분 절차는 더 이상 진행될 수 없으므로 시효중단사유가 종료한 것으로 보아야 하고, 그때부터 시효가 새로이 진행한다.","ox":"O","m":"②","c":"A","tp":"소멸시효의 중단"},{"y":2022,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2022_28-05-3","t":"소멸시효 중단사유로서의 채무승인은 시효이익을 받는 당사자인 채무자가 소멸시효의 완성으로 채권을 상실하게 될 자에 대하여 상대방의 권리 또는 자신의 채무가 있음을 알고 있다는 뜻을 표시함으로써 성립하는 이른바 관념의 통지로 여기에 어떠한 효과의사가 필요하지 않지만, 이에 반하여 시효완성 후 시효이익의 포기가 인정되려면 시효이익을 받는 채무자가 시효의 완성으로 인한 법적인 이익을 받지 않겠다는 효과의사가 필요하다.","ox":"O","m":"③","c":"A","tp":"소멸시효의 중단"},{"y":2022,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2022_28-05-4","t":"소멸시효의 기간만료 전 6개월 내에 제한능력자에게 법정대리인이 없는 경우에는 그가 능력자가 되거나 법정대리인이 취임한 때부터 6개월 내에는 시효가 완성되지 아니한다.","ox":"O","m":"④","c":"A","tp":"소멸시효의 중단"},{"y":2022,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2022_28-05-5","t":"진료계약을 체결하면서 “입원료 기타 제요금이 체납될 시는 병원의 법적 조치에 대하여 아무런 이의를 하지 않겠다.”고 약정하였다 하더라도, 이로써 그 당시 아직 발생하지도 않은 치료비 채무의 존재를 미리 승인하였다고 볼 수는 없다.","ox":"O","m":"⑤","c":"A","tp":"소멸시효의 중단"},{"y":2022,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2022_28-38-1","t":"토지거래계약 허가구역 내의 토지에 관하여 관할관청의 허가를 받을 것을 전제로 한 매매계약에 기한 소유권이전등기청구권 또는 토지거래계약에 관한 허가를 받을 것을 조건으로 한 소유권이전등기청구권을 피보전권리로 한 부동산처분금지가처분신청은 허용되지 않는다.","ox":"O","m":"①","c":"A","tp":"법률행위의 유동적 무효"},{"y":2022,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2022_28-38-2","t":"매매 당사자 일방이 계약 당시 상대방에게 계약금을 교부한 경우 당사자 사이에 다른 약정이 없는 한 당사자 일방이 계약 이행에 착수할 때까지 계약금 교부자는 이를 포기하고 계약을 해제할 수 있고, 그 상대방은 계약금의 배액을 상환하고 계약을 해제할 수 있음이 계약 일반의 법리인 이상, 특별한 사정이 없는 한 토지거래계약허가를 받지 않아 유동적 무효 상태인 매매계약에 있어서도 당사자 사이의 매매계약은 매도인이 계약금의 배액을 상환하고 계약을 해제함으로써 적법하게 해제된다.","ox":"O","m":"②","c":"A","tp":"법률행위의 유동적 무효"},{"y":2022,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2022_28-38-3","t":"토지거래계약허가를 받지 않아 유동적 무효의 상태에 있는 계약을 체결한 당사자는 쌍방이 그 계약이 효력이 있는 것으로 완성될 수 있도록 서로 협력할 의무가 있다고 할 것이므로, 이러한 매매계약을 체결할 당시 당사자 사이에 그 일방이 토지거래계약허가를 받기 위한 협력 자체를 이행하지 아니하거나 허가신청에 이르기 전에 매매계약을 철회하는 경우 상대방에게 일정한 손해액을 배상하기로 하는 약정을 유효하게 할 수 있다.","ox":"O","m":"③","c":"A","tp":"법률행위의 유동적 무효"},{"y":2022,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2022_28-38-4","t":"매도인의 토지거래계약허가 신청절차에 협력할 의무와 토지거래계약허가를 받으면 매매계약 내용에 따라 매수인이 이행하여야 할 매매대금 지급의무나 이에 부수하여 매수인이 부담하기로 특약한 양도소득세 상당 금원의 지급의무는 상호 이행상의 견련성이 있으므로 동시이행관계에 있다.","ox":"X","m":"④","c":"A","tp":"법률행위의 유동적 무효"},{"y":2022,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2022_28-38-5","t":"유동적 무효의 상태에 있는 거래계약의 당사자는 상대방이 그 거래계약의 효력이 완성되도록 협력할 의무를 이행하지 아니하였음을 들어 일방적으로 유동적 무효의 상태에 있는 거래계약 자체를 해제할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"법률행위의 유동적 무효"},{"y":2023,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2023_29-10-1","t":"부진정연대채무에서 채무자 1인에 대한 재판상 청구 또는 채무자 1인이 행한 채무의 승인 등 소멸시효의 중단사유나 시효이익의 포기는 다른 채무자에게 효력을 미치지 않는다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2023_29-10-2","t":"후순위 담보권자는 선순위 담보권의 피담보채권이 소멸하면 담보권의 순위가 상승하고 이에 따라 피담보채권에 대한 배당액이 증가할 수 있으므로, 선순위 담보권의 피담보채권에 관한 소멸시효가 완성되었다고 주장할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2023_29-10-3","t":"보증채무에 대한 소멸시효가 중단되는 등의 사유로 완성되지 아니하였다고 하더라도 주채무에 대한 소멸시효가 완성된 경우에는 시효완성 사실로써 주채무가 당연히 소멸되므로 보증채무의 부종성에 따라 보증채무 역시 당연히 소멸된다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2023_29-10-4","t":"특별한 사정이 없는 한 임치물 반환청구권의 소멸시효는 임치계약이 성립하여 임치물이 수치인에게 인도된 때부터 진행하는 것이지, 임치인이 임치계약을 해지한 때부터 진행한다고 볼 수 없다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2023_29-10-5","t":"주택임대차보호법에 따른 임대차에서 임차인이 임대차 종료 후 동시이행항변권을 근거로 임차목적물을 계속 점유하고 있는 경우에는 보증금반환채권에 대한 소멸시효가 진행하지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2023_29-20-1","t":"제척기간에 있어서는 소멸시효와 같이 기간의 중단이 있을 수 없다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2023_29-20-2","t":"제척기간이 도과하였는지 여부는 직권조사사항으로서 이에 대한 당사자의 주장이 없더라도 법원이 당연히 직권으로 조사하여 재판에 고려하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2023_29-20-3","t":"소멸시효가 일정한 기간의 경과와 권리의 불행사라는 사정에 의하여 권리소멸의 효과를 가져오는 것과는 달리 제척기간은 그 기간의 경과 자체만으로 곧 권리소멸의 효과를 가져온다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2023_29-20-4","t":"제척기간 진행의 기산점은 특별한 사정이 없는 한 원칙적으로 권리가 발생한 때이나, 당사자 사이에 매매예약 완결권을 행사할 수 있는 시기를 특별히 약정한 경우에는 그 제척기간은 그 약정에 따라 권리를 행사할 수 있는 때로부터 10년이 되는 날까지이다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2023_29-20-5","t":"채권양도의 통지는 양도인이 채권이 양도되었다는 사실을 채무자에게 알리는 것에 그치는 행위이므로, 그것만으로 제척기간의 준수에 필요한 권리의 재판외 행사에 해당한다고 할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2023_29-30-1","t":"부관이 붙은 법률행위에 있어서 부관에 표시된 사실이 발생하지 아니하면 채무를 이행하지 아니하여도 된다고 보는 것이 상당한 경우에는 정지조건으로 보아야 하고, 표시된 사실이 발생한 때에는 물론이고 반대로 발생하지 아니하는 것이 확정된 때에도 그 채무를 이행하여야 한다고 보는 것이 상당한 경우에는 표시된 사실의 발생 여부가 확정되는 것을 불확정기한으로 정한 것으로 보아야 한다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2023_29-30-2","t":"부부가 협의이혼을 전제로 재산분할의 약정을 한 경우, 특별한 사정이 없는 한 그 후 협의상 이혼이 이루어지지 아니하고 혼인관계가 존속하게 되거나 재판상 이혼이 이루어진 경우에는 그 재산분할 약정은 조건의 불성취로 인하여 효력이 발생하지 않는다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2023_29-30-3","t":"조건의 성취로 인하여 불이익을 받을 당사자가 신의성실에 반하여 조건의 성취를 방해한 경우, 조건이 성취된 것으로 의제되는 시점은 이러한 신의성실에 반하는 행위가 있었던 시점이다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2023_29-30-4","t":"조건부 법률행위에 있어 조건의 내용 자체가 불법적인 것이어서 무효일 경우 또는 조건을 붙이는 것이 허용되지 아니하는 법률행위에 조건을 붙인 경우 그 조건만을 분리하여 무효로 할 수는 없고 그 법률행위 전부가 무효로 된다고 보아야 한다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2023_29-30-5","t":"이미 부담하고 있는 채무의 변제에 관하여 일정한 사실이 부관으로 붙여진 경우에는 특별한 사정이 없는 한 그것은 변제기를 유예한 것으로서 그 사실이 발생한 때 또는 발생하지 아니하는 것으로 확정된 때에 기한이 도래한다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2024_30-07","t":"소멸시효에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"소멸시효에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","d":"ㄱ.연예인의 임금 채권은 1년간 행사하지 아니하면 소멸시효가 완성한다.\nㄴ.채권자가 영업양도가 이루어진 뒤 영업양도인을 상대로 소를 제기하여 확정판결을 받아 영업양도인에 대한 관계에서 소멸시효가 중단되거나 소멸시효 기간이 연장되었다면 그와 같은 소멸시효 중단이나 소멸시효 연장의 효과는 상호를 속용하는 영업양수인에게도 미친다.\nㄷ.부동산경매절차에서 채무자에게 교부할 잉여금이 공탁된 경우, 채무자의 공탁금지급청구권은 공탁일부터 소멸시효가 진행하고, 부동산경매절차에서 채무자에 대한 송달이 공시송달의 방법으로 이루어짐으로써 채무자가 경매진행 사실 및 잉여금의 존재에 관하여 사실상 알지 못하였다고 하더라도 소멸시효기간이 진행한다.\nㄹ.채무불이행에 따른 해제의 의사표시 당시에 이미 채무불이행의 대상이 되는 본래 채권이 시효가 완성되어 소멸하였다고 하더라도, 특별한 사정이 없는 한 채권자는 채무불이행 시점이 본래 채권의 시효 완성 전이라면 그 채무불이행을 이유로 한 해제권 및 이에 기한 원상회복청구권을 행사할 수 있다.\nㅁ.채무자가 제3채무자를 상대로 금전채권의 이행을 구하는 소를 제기한 후 채권자가 위 금전채권에 대하여 압류 및 추심명령을 받아 제3채무자를 상대로 추심의 소를 제기한 경우, 채무자가 권리주체의 지위에서 한 시효중단의 효력은 추심채권자에게도 미친다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄱ, ㄹ","ㄴ, ㄹ","ㄴ, ㅁ"],"a":4}},{"y":2024,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2024_30-10-1","t":"기한은 채권자의 이익을 위한 것으로 추정한다.","ox":"X","m":"①","c":"A","tp":"조건, 기한 및 기간"},{"y":2024,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2024_30-10-2","t":"조건이 법률행위의 당시 이미 성취한 것인 경우에는 그 조건이 정지조건이면 조건없는 법률행위로 하고 해제조건이면 그 법률행위는 무효로 한다.","ox":"O","m":"②","c":"A","tp":"조건, 기한 및 기간"},{"y":2024,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2024_30-10-3","t":"조건이 선량한 풍속 기타 사회질서에 위반한 것인 때에는 그 조건만 무효가 될 뿐 법률행위는 무효로 되지 않는다.","ox":"X","m":"③","c":"A","tp":"조건, 기한 및 기간"},{"y":2024,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2024_30-10-4","t":"연령계산에서 출생일은 산입하지 아니한다.","ox":"X","m":"④","c":"A","tp":"조건, 기한 및 기간"},{"y":2024,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2024_30-10-5","t":"제척기간에도 소멸시효 중단의 규정이 준용된다.","ox":"X","m":"⑤","c":"A","tp":"조건, 기한 및 기간"},{"y":2024,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2024_30-15-1","t":"대물변제예약이 불공정한 법률행위가 되는 요건의 하나인 대차의 목적물가격과 대물변제의 목적물가격에 있어서의 불균형이 있느냐 여부를 결정할 시점은 대물변제예약시가 아니라 대물변제의 효력이 발생할 변제기 당시를 표준으로 하여야 할 것임이 원칙이므로, 채권액수도 역시 변제기까지의 원리액을 기준으로 하여야 할 것이다.","ox":"O","m":"①","c":"A","tp":"반사회질서 내지 불공정한 법률행위"},{"y":2024,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2024_30-15-2","t":"도박채무의 변제를 위하여 채무자로부터 부동산의 처분을 위임받은 채권자가 그 부동산을 제3자에게 매도한 경우, 도박채무 부담행위 및 그 변제약정이 민법 제103조의 선량한 풍속 기타 사회질서에 위반되어 무효이므로, 그 무효는 변제약정의 이행행위에 해당하는 위 부동산을 제3자에게 처분한 대금으로 도박채무의 변제에 충당한 부분뿐만 아니라 위 변제약정의 이행행위에 직접 해당하지 아니하는 부동산 처분에 관한 대리권을 도박 채권자에게 수여한 행위 부분까지 무효이다.","ox":"X","m":"②","c":"A","tp":"반사회질서 내지 불공정한 법률행위"},{"y":2024,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2024_30-15-3","t":"소송사건에서 일방 당사자를 위하여 증인으로 출석하여 증언하였거나 증언할 것을 조건으로 어떤 대가를 받을 것을 약정한 경우, 증인은 법률에 의하여 증언거부권이 인정되지 않은 한 진실을 진술할 의무가 있는 것이므로 그 대가의 내용이 통상적으로 용인될 수 있는 수준(예컨대 증인에게 일당과 여비가 지급되기는 하지만 증인이 법원에 출석함으로써 입게 되는 손해에는 미치지 못하는 경우 그러한 손해를 전보해 주는 정도)을 초과하는 경우에는 그와 같은 약정은 금전적 대가가 결부됨으로써 선량한 풍속 기타 사회질서에 반하는 법률행위가 되어 민법 제103조에 따라 효력이 없다.","ox":"O","m":"③","c":"A","tp":"반사회질서 내지 불공정한 법률행위"},{"y":2024,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2024_30-15-4","t":"금전 소비대차계약과 함께 이자의 약정을 하는 경우, 양쪽 당사자 사이의 경제력의 차이로 인하여 그 이율이 당시의 경제적·사회적 여건에 비추어 사회통념상 허용되는 한도를 초과하여 현저하게 고율로 정하여졌다면, 그와 같이 허용할 수 있는 한도를 초과하는 부분의 이자 약정은 대주가 그의 우월한 지위를 이용하여 부당한 이득을 얻고 차주에게는 과도한 반대급부 또는 기타의 부당한 부담을 지우는 것이므로 선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위로서 무효이다.","ox":"O","m":"④","c":"A","tp":"반사회질서 내지 불공정한 법률행위"},{"y":2024,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2024_30-15-5","t":"제3자가 피상속인으로부터 토지를 전전매수하였다는 사실을 알면서도 그 정을 모르는 상속인을 기망하여 결과적으로 그로 하여금 토지를 이중매도하게 하였다면, 그 매수인의 적극적인 기망행위에 의하여 이루어진 상속인과 사이의 토지에 관한 양도계약은 반사회적 법률행위로서 무효이다.","ox":"O","m":"⑤","c":"A","tp":"반사회질서 내지 불공정한 법률행위"},{"y":2024,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2024_30-25","t":"법률행위 취소에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"법률행위 취소에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","d":"ㄱ.민법 제109조 제1항 단서는 의사표시의 착오가 표의자의 중대한 과실로 인한 때에는 그 의사표시를 취소하지 못한다고 규정하고 있는데, 위 단서 규정은 표의자의 상대방의 이익을 보호하기 위한 것이므로, 상대방이 표의자의 착오를 알고 이를 이용한 경우에도 착오가 표의자의 중대한 과실로 인한 것이라면 표의자는 의사표시를 취소할 수 없다.\nㄴ.동기의 착오가 법률행위의 내용의 중요부분의 착오에 해당함을 이유로 표의자가 법률행위를 취소하려면 그 동기를 당해 의사표시의 내용으로 삼을 것을 상대방에게 표시하고 의사표시의 해석상 법률행위의 내용으로 되어 있다고 인정되면 충분하고 당사자들 사이에 별도로 그 동기를 의사표시의 내용으로 삼기로 하는 합의까지 이루어질 필요는 없지만, 그 법률행위의 내용의 착오는 보통 일반인이 표의자의 입장에 섰더라면 그와 같은 의사표시를 하지 아니하였으리라고 여겨질 정도로 그 착오가 중요한 부분에 관한 것이어야 한다.\nㄷ.제한능력자의 법률행위는 취소할 수 있고, 취소된 법률행위는 처음부터 무효인 것으로 보므로 제한능력자가 취소된 법률행위로 수령한 급부는 상대방에게 부당이득으로 전부 반환되어야 한다.\nㄹ.임대차 계약에서 임차목적물이 임대인의 소유라는 사실은 중요한 필요조건이므로 목적물이 반드시 임대인의 소유일 것을 특히 계약의 내용으로 삼지 않은 경우라도 타인소유의 부동산을 임대한 것이라면 임대차계약을 해지할 사유뿐 아니라 착오를 이유로 임차인이 임대차계약을 취소할 수도 있다.\nㅁ.상품의 선전, 광고에 있어 다소의 과장이나 허위가 수반되는 것은 그것이 일반 상거래의 관행과 신의칙에 비추어 시인될 수 있는 한 기망성이 결여된다고 하겠으나, 거래에 있어서 중요한 사항에 관하여 구체적 사실을 신의성실의 의무에 비추어 비난받을 정도의 방법으로 허위로 고지한 경우에는 기망행위에 해당한다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄱ, ㄷ, ㄹ","ㄴ, ㄷ, ㄹ","ㄴ, ㄹ, ㅁ"],"a":3}},{"y":2025,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2025_31-11-1","t":"부동산 소유자가 취득시효 완성 사실을 알고서 그 부동산을 제3자에게 처분하여 소유권이전등기를 마쳐주었는데, 그 부동산을 취득한 제3자가 부동산 소유자의 이와 같은 불법행위에 적극 가담하여 위 처분행위 및 제3자 명의의 등기가 무효인 경우, 시효완성 당시의 소유자가 그 무효행위를 추인하여도 그 제3자 명의의 등기는 무효이다.","ox":"O","m":"①","c":"A","tp":"무효행위의 추인"},{"y":2025,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2025_31-11-2","t":"무효행위를 추인한 때에는 달리 소급효를 인정하는 법률규정이 없는 한 새로운 법률행위를 한 것으로 보아야 하지만, 주식회사의 이사회결의와 같이 단체법적 법률효과를 가지는 법률행위의 사후 추인의 경우에는 소급효를 가진다.","ox":"X","m":"②","c":"A","tp":"무효행위의 추인"},{"y":2025,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2025_31-11-3","t":"무권대리행위의 추인은 무권대리인 또는 상대방의 동의나 승낙을 요하지 않는 단독행위로서 추인은 의사표시의 전부에 대하여 행하여져야 하고, 그 일부에 대하여 추인을 하거나 그 내용을 변경하여 추인을 하였을 경우에는 상대방의 동의를 얻지 못하는 한 무효이다.","ox":"O","m":"③","c":"A","tp":"무효행위의 추인"},{"y":2025,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2025_31-11-4","t":"법인의 대표자가 한 매매계약이 법인에 대한 배임행위에 해당하고 그 매매계약 상대방이 배임행위를 유인·교사하거나 배임행위의 전 과정에 관여하는 등 배임행위에 적극 가담한 경우에는 그 매매계약이 반사회적 법률행위에 해당하여 무효로 될 수 있지만, 이때 매매계약을 무효로 한 이유는 본인인 법인의 이익을 보호하기 위한 데에 있는 것이어서, 무효의 원인이 소멸된 후 본인인 법인의 진정한 의사로 무효임을 알고 추인한 때에는 새로운 법률행위로 그 효력이 생길 수 있다.","ox":"O","m":"④","c":"A","tp":"무효행위의 추인"},{"y":2025,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2025_31-11-5","t":"무권리자에 의한 처분행위를 권리자가 추인한 경우에 권리자는 무권리자에 대하여 무권리자가 처분행위로 인하여 얻은 이득의 반환을 청구할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"무효행위의 추인"},{"y":2025,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2025_31-26-1","t":"소멸시효의 기산일은 변론주의의 적용 대상이고, 따라서 본래의 소멸시효 기산일과 당사자가 주장하는 기산일이 서로 다른 경우에는 변론주의의 원칙상 법원은 당사자가 주장하는 기산일을 기준으로 소멸시효를 계산하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2025_31-26-2","t":"민법 제163조 제2호 소정의 ‘의사의 치료에 관한 채권’에 있어서는, 특약이 없는 한 그 개개의 진료가 종료될 때마다 각각의 당해 진료에 필요한 비용의 이행기가 도래하여 그에 대한 소멸시효가 진행된다고 해석함이 상당하고, 장기간 입원 치료를 받는 경우라 하더라도 다른 특약이 없는 한 입원 치료 중에 환자에 대하여 치료비를 청구함에 아무런 장애가 없으므로 퇴원시부터 소멸시효가 진행된다고 볼 수는 없다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2025_31-26-3","t":"특별한 사정이 없는 한 임치계약 해지에 따른 임치물 반환청구권의 소멸시효는 임치인이 임치계약을 해지한 때부터 진행하는 것이지, 임치계약이 성립하여 임치물이 수치인에게 인도된 때부터 진행한다고 볼 수 없다.","ox":"X","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2025_31-26-4","t":"매도인에 대한 하자담보에 기한 매수인의 손해배상청구권은 권리의 내용·성질 및 취지에 비추어 민법 제162조 제1항의 채권 소멸시효의 규정이 적용되고, 다른 특별한 사정이 없는 한 매수인이 매매 목적물을 인도받은 때부터 소멸시효가 진행한다고 해석함이 타당하다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2025_31-26-5","t":"부당이득반환청구권은 그 발생과 동시에 행사할 수 있으므로, 부당이득채권이 발생한 때부터 소멸시효가 진행한다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2025_31-27-1","t":"형사사건에서의 성공보수약정은 수사·재판의 결과를 금전적인 대가와 결부시킴으로써, 기본적 인권의 옹호와 사회정의의 실현을 사명으로 하는 변호사 직무의 공공성을 저해하고, 의뢰인과 일반 국민의 사법제도에 대한 신뢰를 현저히 떨어뜨릴 위험이 있으므로, 선량한 풍속 기타 사회질서에 위배되는 것으로 평가할 수 있다.","ox":"O","m":"①","c":"A","tp":"법률행위의 목적"},{"y":2025,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2025_31-27-2","t":"매매계약체결 당시에 정당한 대가를 지급하고 목적물을 매수하는 계약을 체결하였더라도, 그 후 목적물이 범죄행위로 취득된 것을 알게 되었다면 위 계약의 이행을 구하는 것은 선량한 풍속 기타 사회질서에 위반하는 것이 되므로 당초의 매매계약에 기하여 목적물에 대한 소유권이전등기를 구할 수 없다.","ox":"X","m":"②","c":"A","tp":"법률행위의 목적"},{"y":2025,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2025_31-27-3","t":"영리를 목적으로 윤락행위를 하도록 권유·유인·알선 또는 강요하거나 이에 협력하는 것은 선량한 풍속 기타 사회질서에 위반되므로 그러한 행위를 하는 자가 영업상 관계 있는 윤락행위를 하는 자에 대하여 가지는 채권은 계약의 형식에 관계없이 무효라고 보아야 한다.","ox":"O","m":"③","c":"A","tp":"법률행위의 목적"},{"y":2025,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2025_31-27-4","t":"불공정 법률행위에 해당하는지는 법률행위가 이루어진 시점을 기준으로 약속된 급부와 반대급부 사이의 객관적 가치를 비교 평가하여 판단하여야 할 문제이고, 당초의 약정대로 계약이 이행되지 아니할 경우에 발생할 수 있는 문제는 달리 특별한 사정이 없는 한 채무의 불이행에 따른 효과로서 다루어지는 것이 원칙이다.","ox":"O","m":"④","c":"A","tp":"법률행위의 목적"},{"y":2025,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2025_31-27-5","t":"‘궁박’이라 함은 ‘급박한 곤궁’을 의미하는 것으로서 경제적 원인에 기인할 수도 있고 정신적 또는 심리적 원인에 기인할 수도 있으며, 당사자가 궁박한 상태에 있었는지 여부는 그의 나이와 직업, 교육 및 사회경험의 정도, 재산 상태 및 그가 처한 상황의 절박성의 정도 등 여러 사정을 종합하여 구체적으로 판단하여야 한다. 한편 당사자가 계약을 지키지 않는 경우 얻을 이익이 이로 인해 입을 불이익보다 크다고 판단하여, 그 불이익의 발생을 예측하면서도 이를 감수할 생각으로 계약에 반하는 행위를 함으로써 계약 상대방과의 관계에서 그가 주장하는 급박한 곤궁 상태에 이르렀다면, 이와 같이 그가 자초한 상태를 민법 제104조의 궁박이라고 인정하는 것은 엄격하고 신중하게 이루어져야 한다.","ox":"O","m":"⑤","c":"A","tp":"법률행위의 목적"},{"y":2025,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2025_31-29-1","t":"조건은 법률행위 효력의 발생 또는 소멸을 장래의 불확실한 사실의 성부에 의존하게 하는 법률행위의 부관이다. 반면 장래의 사실이더라도 그것이 장래 반드시 실현되는 사실이면 실현되는 시기가 비록 확정되지 않더라도 이는 기한으로 보아야 한다.","ox":"O","m":"①","c":"A","tp":"조건과 기한"},{"y":2025,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2025_31-29-2","t":"법률행위에 붙은 부관이 조건인지 기한인지가 명확하지 않은 경우 법률행위의 해석을 통해서 이를 결정해야 한다. 부관에 표시된 사실이 발생하지 않으면 채무를 이행하지 않아도 된다고 보는 것이 합리적인 경우에는 조건으로 보아야 하나, 부관에 표시된 사실이 발생한 때에는 물론이고 반대로 발생하지 않는 것이 확정된 때에도 채무를 이행하여야 한다고 보는 것이 합리적인 경우에는 표시된 사실의 발생 여부가 확정되는 것을 불확정기한으로 정한 것으로 보아야 한다.","ox":"O","m":"②","c":"A","tp":"조건과 기한"},{"y":2025,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2025_31-29-3","t":"기한이익 상실의 특약이 정지조건부 기한이익 상실의 특약과 형성권적 기한이익 상실의 특약 중 어느 것에 해당하느냐는 당사자의 의사해석의 문제이지만 일반적으로 기한이익 상실의 특약이 채권자를 위하여 둔 것인 점에 비추어 명백히 형성권적 기한이익 상실의 특약이라고 볼 만한 특별한 사정이 없는 이상 정지조건부 기한이익 상실의 특약으로 추정하는 것이 타당하다.","ox":"X","m":"③","c":"A","tp":"조건과 기한"},{"y":2025,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2025_31-29-4","t":"기한의 이익은 상대방의 이익을 해하지 않는 한 이를 포기할 수 있으므로, 가령 이자부 소비대차의 채무자는 이행기까지의 이자를 지급하여 기한 전에 변제를 할 수 있다.","ox":"O","m":"④","c":"A","tp":"조건과 기한"},{"y":2025,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2025_31-29-5","t":"기한의 이익 포기의 효과는 상대적이기 때문에 주채무자가 기한의 이익을 포기하더라도 그것은 보증인에게 효력이 없다.","ox":"O","m":"⑤","c":"A","tp":"조건과 기한"},{"y":2026,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2026_32-11-1","t":"부동산의 이중매매가 반사회적 법률행위로서 무효가 되기 위하여는 매도인의 배임행위와 매수인이 매도인의 배임행위에 적극 가담한 행위로 이루어진 매매로서, 그 적극 가담하는 행위는 매수인이 다른 사람에게 매매목적물이 매도된 것을 안다는 것만으로는 부족하고 적어도 그 매도사실을 알고도 매도를 요청하여 매매계약에 이르는 정도가 되어야 한다.","ox":"O","m":"①","c":"A","tp":"부동산의 이중양도"},{"y":2026,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2026_32-11-2","t":"특정물에 대한 소유권이전등기청구권을 보전하기 위하여 채권자취소권을 행사하는 것은 허용되지 않으나, 제1매수인이 부동산을 이중으로 매도하여 소유권이전등기를 마쳐준 매도인에 대하여 취득하는 부동산 가액 상당의 손해배상채권은 금전채권이고, 사해행위 이전에 이미 채권 성립의 기초가 되는 법률관계가 발생되어 있었다고 할 것이므로 사해행위취소권을 행사할 수 있는 피보전채권에 해당한다고 볼 것이다.","ox":"X","m":"②","c":"A","tp":"부동산의 이중양도"},{"y":2026,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2026_32-11-3","t":"부동산의 이중매매가 반사회적 법률행위에 해당하는 경우에는 이중매매계약은 절대적으로 무효이므로, 당해 부동산을 제2매수인으로부터 다시 취득한 제3자는 설사 제2매수인이 당해 부동산의 소유권을 유효하게 취득한 것으로 믿었더라도 이중매매계약이 유효하다고 주장할 수 없다.","ox":"O","m":"③","c":"A","tp":"부동산의 이중양도"},{"y":2026,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2026_32-11-4","t":"무효인 제2매매계약을 원인으로 하는 제2매수인 앞으로의 소유권이전등기가 확정판결에 따라 마쳐진 것이라면 그 확정판결이 당연무효이거나 재심의 소에 의하여 취소되지 않는 한 제1매수인이 매도인을 대위하여 소유권이전등기의 말소청구를 하는 것은 위 확정판결의 기판력에 저촉되는 것으로 허용되지 않는다.","ox":"O","m":"④","c":"A","tp":"부동산의 이중양도"},{"y":2026,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2026_32-11-5","t":"매수인에게 부동산의 소유권이전등기를 해줄 의무를 지는 매도인이 그 부동산에 관하여 다른 사람에게 이전등기를 마쳐 준 때에는 매도인이 그 부동산의 소유권에 관한 등기를 회복하여 매수인에게 이전등기해 줄 수 있는 특별한 사정이 없어야 비로소 매수인에 대한 소유권이전등기의무가 이행불능의 상태에 이르렀다고 할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"부동산의 이중양도"},{"y":2026,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2026_32-20-1","t":"법률행위에 붙은 부관이 조건인지 기한인지가 명확하지 않은 경우 법률행위의 해석을 통해서 이를 결정해야 하는바, 부관에 표시된 사실이 발생하지 않으면 채무를 이행하지 않아도 된다고 보는 것이 합리적인 경우에는 조건으로 보아야 하고, 부관에 표시된 사실이 발생한 때에는 물론이고 반대로 발생하지 않는 것이 확정된 때에도 그 채무를 이행하여야 한다고 보는 것이 합리적인 경우에는 표시된 사실의 발생 여부가 확정되는 것을 불확정기한으로 정한 것으로 보아야 한다.","ox":"O","m":"①","c":"A","tp":"조건과 기한"},{"y":2026,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2026_32-20-2","t":"민법은 조건 성취의 효과가 조건이 성취된 때로부터 발생하고 소급하지 아니하는 것을 원칙으로 규정하면서, 예외적으로 조건부 법률행위의 당사자가 조건 성취의 효과를 그 성취 전에 소급하게 할 의사를 표시한 때에는 소급효가 인정된다고 규정하고 있다.","ox":"O","m":"②","c":"A","tp":"조건과 기한"},{"y":2026,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2026_32-20-3","t":"토지 매수인은 토지를 담보로 한 금융기관에 대한 대출금상환채무를 인수하는 한편 그 채무액을 매매대금에서 공제하기로 약정하고, 토지 매수인과 그 토지상의 건물 신축공사도급계약을 체결한 수급인은 그 인수 대출금상환채무를 보증하면서 도급계약 등이 해약될 경우 보증은 무효화하기로 약정하였는데, 그 후 도급계약이 해약된 경우, 그 보증계약은 도급계약이 해약됨으로써 해제조건이 성취되었다 하여 당연히 소급적으로 실효되는 것은 아니다.","ox":"O","m":"③","c":"A","tp":"조건과 기한"},{"y":2026,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2026_32-20-4","t":"취소채권자의 채권이 정지조건부채권이라 하더라도, 장래에 그 정지조건이 성취되기 어려울 것으로 보이는 등의 특별한 사정이 없는 한, 이를 피보전채권으로 하여 채권자취소권을 행사할 수 있다.","ox":"O","m":"④","c":"A","tp":"조건과 기한"},{"y":2026,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2026_32-20-5","t":"조건의 성취로 인하여 불이익을 받을 당사자가 신의성실에 반하여 조건의 성취를 방해한 경우 상대방은 그 조건이 성취된 것으로 주장할 수 있고, 이 때 조건이 성취된 것으로 의제되는 시점은 신의성실에 반하여 조건의 성취를 방해하는 행위가 있었던 시점이다.","ox":"X","m":"⑤","c":"A","tp":"조건과 기한"},{"y":2026,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2026_32-25-1","t":"하나의 채권 중 일부에 관하여만 판결을 구한다는 취지를 명백히 하여 소송을 제기한 경우에는 소제기에 의한 소멸시효중단의 효력이 그 일부에 관하여만 발생하고, 나머지 부분에는 발생하지 아니하나, 소장에서 청구의 대상으로 삼은 채권 중 일부만을 청구하면서 소송의 진행경과에 따라 장차 청구금액을 확장할 뜻을 표시하고 당해 소송이 종료될 때까지 실제로 청구취지변경을 통하여 청구금액을 확장하였다면, 확장된 청구금액에 대하여는 청구취지변경신청서가 법원에 제출된 때부터 재판상 청구로 인한 시효중단의 효력이 발생한다.","ox":"X","m":"①","c":"A","tp":"소멸시효의 중단"},{"y":2026,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2026_32-25-2","t":"동일한 채권자와 채무자 사이에 다수의 채권이 존재하는 경우 채무자가 변제를 충당하여야 할 채무를 지정하지 않고 모든 채무를 변제하기에 부족한 금액을 변제한 때에는 특별한 사정이 없는 한 그 변제는 모든 채무에 대한 승인으로서 소멸시효를 중단하는 효력을 가진다.","ox":"O","m":"②","c":"A","tp":"소멸시효의 중단"},{"y":2026,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2026_32-25-3","t":"소멸시효와 달리 제척기간에 있어서는 기간의 중단이 없다.","ox":"O","m":"③","c":"A","tp":"소멸시효의 중단"},{"y":2026,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2026_32-25-4","t":"시효를 주장하는 자가 원고가 되어 소를 제기한 데 대하여 피고로서 응소하여 소송에서 적극적으로 권리를 주장하고 그것이 받아들여진 경우 시효중단사유 중 하나인 재판상의 청구에 해당한다.","ox":"O","m":"④","c":"A","tp":"소멸시효의 중단"},{"y":2026,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2026_32-25-5","t":"민법 제174조 소정의 시효중단사유로서의 최고에 있어서 채무이행을 최고받은 채무자가 그 이행의무의 존부 등에 대하여 조사를 해 볼 필요가 있다는 이유로 채권자에 대하여 그 이행의 유예를 구한 경우에는 채권자가 그 회답을 받을 때까지는 최고의 효력이 계속된다고 보아야 하므로, 민법 제174조에 규정된 6월의 기간은 채권자가 채무자로부터 회답을 받은 때로부터 기산되는 것이라고 해석하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"소멸시효의 중단"},{"y":2026,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2026_32-26-1","t":"민법 제137조는 법률행위의 일부분이 무효인 때에는 그 전부를 무효로 하나, 그 무효 부분이 없더라도 법률행위를 하였을 것이라고 인정될 때에는 나머지 부분은 무효가 되지 아니한다고 규정하고 있는데, 여기서 당사자의 의사는 법률행위의 일부가 무효임을 법률행위 당시에 알았다면 의욕하였을 가정적 효과의사를 가리키는 것이다.","ox":"O","m":"①","c":"A","tp":"법률행위의 무효"},{"y":2026,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2026_32-26-2","t":"법률행위의 일부무효 법리는 하나의 법률행위 중 일부분이 무효인 경우를 전제로 하므로, 여러 개의 계약이 체결된 경우에는 비록 그 계약 전부가 경제적, 사실적으로 일체로서 행하여져서 하나의 계약인 것과 같은 관계에 있더라도 일부무효 법리가 적용된다고 볼 수 없다.","ox":"X","m":"②","c":"A","tp":"법률행위의 무효"},{"y":2026,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2026_32-26-3","t":"매매계약이 약정된 매매대금의 과다로 말미암아 민법 제104조에서 정하는 ‘불공정한 법률행위’에 해당하여 무효인 경우에도 무효행위의 전환에 관한 민법 제138조가 적용될 수 있으므로, 당사자 쌍방이 위와 같은 무효를 알았더라면 대금을 다른 액으로 정하여 매매계약에 합의하였을 것이라고 예외적으로 인정되는 경우에는, 그 대금액을 내용으로 하는 매매계약이 유효하게 성립한다.","ox":"O","m":"③","c":"A","tp":"법률행위의 무효"},{"y":2026,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2026_32-26-4","t":"무효행위의 추인은 무효행위가 있음을 알고 그 행위의 효과를 자기에게 귀속시키도록 하는 단독행위로서 묵시적인 방법으로도 할 수 있으므로, 본인이 그 행위로 처하게 된 법적 지위를 충분히 이해하고 그럼에도 진의에 기하여 그 행위의 결과가 자기에게 귀속된다는 것을 승인한 것으로 볼 만한 사정이 있는 경우에는 묵시적으로 추인한 것으로 볼 수 있다.","ox":"O","m":"④","c":"A","tp":"법률행위의 무효"},{"y":2026,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2026_32-26-5","t":"유동적 무효인 경우 착오로 인한 의사표시의 취소를 주장하여 계약을 확정적으로 무효화할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"법률행위의 무효"}],"12":[{"y":2016,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2016_22-08-1","t":"과실로 피상속인에게 상해를 가하여 사망에 이르게 한 자는 상속인이 될 수 있다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2016_22-08-2","t":"금전채무와 같이 급부의 내용이 가분인 채무가 공동상속된 경우 상속재산 분할의 대상이 될 여지가 없고, 공동상속인들 사이의 분할의 협의에 따라 공동상속인 중의 1인이 법정상속분을 초과하여 채무를 부담하기로 하는 약정은 면책적 채무인수의 실질을 가진다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2016_22-08-3","t":"상속결격사유가 발생한 이후에 결격된 자가 피상속인으로부터 직접 증여를 받은 경우, 비록 그 수익은 상속인의 지위에서 받은 것이라고 할 수는 없지만 상속분의 선급으로서의 성격을 갖고 있으므로 민법 제1008조의 특별수익에 해당한다고 볼 것이다.","ox":"X","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2016_22-08-4","t":"공동상속인 중 1인이 협의분할에 의한 상속을 원인으로 하여 상속부동산에 관한 소유권이전등기를 마친 경우에 그 협의분할이 다른 공동상속인의 동의 없이 이루어진 것으로 무효라는 이유로 다른 공동상속인이 그 등기의 말소를 청구하는 소는 상속회복청구의 소에 해당한다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2016_22-08-5","t":"상속재산의 분할협의는 사해행위취소권 행사의 대상이 될 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2016_22-13-1","t":"상속인은 상속개시 있음을 안 날로부터 3월 내에 상속의 포기를 할 수 있는데, 여기서 상속개시 있음을 안 날이라 함은 상속개시의 원인이 되는 사실의 발생을 알고 이로써 자기가 상속인이 되었음을 안 날을 말한다.","ox":"O","m":"①","c":"A","tp":"상속포기"},{"y":2016,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2016_22-13-2","t":"상속의 포기는 상속개시된 때에 소급하여 그 효력이 있으므로, 상속을 포기한 자는 상속개시된 때부터 상속인이 아니었던 것과 같은 지위에 놓이게 된다.","ox":"O","m":"②","c":"A","tp":"상속포기"},{"y":2016,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2016_22-13-3","t":"상속인이 수인인 경우에 어느 상속인이 상속을 포기한 때에는 그 상속분은 다른 상속인의 상속분의 비율로 그 상속인에게 귀속된다.","ox":"O","m":"③","c":"A","tp":"상속포기"},{"y":2016,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2016_22-13-4","t":"피상속인의 배우자와 자녀 중 자녀 전부가 상속을 포기한 경우에는 배우자와 피상속인의 손자녀 또는 직계존속이 공동으로 상속인이 되고, 피상속인의 손자녀와 직계존속이 존재하지 아니하면 배우자가 단독으로 상속인이 된다.","ox":"O","m":"④","c":"A","tp":"상속포기"},{"y":2016,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2016_22-13-5","t":"상속의 포기는 공동상속인 사이에 잠정적 공유가 된 상속재산의 귀속을 확정시키는 것으로 그 성질상 재산권을 목적으로 하는 법률행위이므로 사해행위 취소의 대상이 된다.","ox":"X","m":"⑤","c":"A","tp":"상속포기"},{"y":2016,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2016_22-21-1","t":"공동상속인의 협의 또는 가정법원의 심판으로 기여분이 결정되지 않은 이상 유류분반환청구소송에서 기여분을 주장할 수 없지만, 공동상속인의 협의 또는 가정법원의 심판으로 기여분이 결정된 경우 유류분을 산정함에 있어 기여분을 공제할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2016_22-21-2","t":"증여 이후 수증자나 수증자로부터 증여재산을 양수받은 자가 자기의 비용으로 증여재산의 성상 등을 변경하여 상속개시 당시 그 가액이 증가되어 있는 경우, 위와 같이 변경된 성상 등을 기준으로 상속개시 당시의 가액을 산정하면 유류분권리자에게 부당한 이익을 주게 되므로, 이러한 경우에는 그와 같은 변경을 고려하지 않고 증여 당시의 성상 등을 기준으로 상속개시 당시의 가액을 산정하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2016_22-21-3","t":"유류분반환청구권의 행사는 재판상 또는 재판 외에서 상대방에 대한 의사표시의 방법으로 할 수 있고, 이 경우 그 의사표시는 침해를 받은 유증 또는 증여행위를 지정하여 이에 대한 반환청구의 의사를 표시하면 그것으로 족하며, 그로 인하여 생긴 목적물의 이전등기청구권이나 인도청구권 등을 행사하는 것과는 달리 그 목적물을 구체적으로 특정하여야 하는 것은 아니다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2016_22-21-4","t":"유류분반환청구권의 행사에 의하여 반환하여야 할 유증 또는 증여의 목적이 된 재산이 타인에게 양도된 경우 그 양수인이 양도 당시 유류분권리자를 해함을 안 때에는 양수인에 대하여도 그 재산의 반환을 청구할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2016_22-21-5","t":"유류분을 포함한 상속의 포기는 상속이 개시된 후 일정한 기간 내에만 가능하고 가정법원에 신고하는 등 일정한 절차와 방식을 따라야만 그 효력이 있다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2017_23-31-1","t":"상속재산 일부에 대해서만 제소하여 제척기간을 준수한 경우 특별한 사정이 없는 한 청구의 목적물로 하지 않은 나머지 상속재산에 대해서는 제척기간을 준수한 것으로 볼 수 없다.","ox":"O","m":"①","c":"A","tp":"상속회복청구권"},{"y":2017,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2017_23-31-2","t":"상속개시 후의 인지 또는 재판의 확정에 의하여 공동상속인이 된 자가 분할을 청구할 경우에 다른 공동상속인이 이미 분할 기타 처분을 한 때에는 그 상속분에 상당한 가액의 지급을 청구할 권리가 있는바, 이 가액청구권은 상속회복청구권의 일종이다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2017_23-31-3","t":"상속회복청구권이 제척기간의 경과로 소멸하게 되면 진정상속인은 상속에 따라 승계한 개개의 권리의무를 상실하게 되고, 그 반사적 효과로 인하여 참칭상속인의 지위는 확정되어 상속재산은 그 때부터 참칭상속인의 소유로 된다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2017_23-31-4","t":"진정상속인이 참칭상속인을 상대로 상속재산인 부동산에 관한 등기의 말소 등을 구하는 경우에 그 소유권 또는 지분권 등의 귀속원인을 상속으로 주장하고 있는 이상 청구원인 여하에 불구하고 상속회복청구의 소라고 해석하여야 한다.","ox":"O","m":"④","c":"A","tp":"상속회복청구권"},{"y":2017,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2017_23-31-5","t":"상속인의 상속회복청구권 및 그 제척기간에 관한 민법 규정은 포괄적 유증의 경우에도 유추 적용된다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2017_23-32-1","t":"공동상속인 중에 특별수익자가 있는 경우 구체적인 상속분의 산정의 기초가 되는 ‘피상속인이 상속개시 당시에 가지고 있던 재산의 가액’이란 상속재산 가운데 적극재산에서 소극재산을 제외한 순재산을 뜻한다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2017_23-32-2","t":"공동상속인들 중 일부가 한정승인을 한 경우, 그 한정승인에 따른 청산절차가 종료되지 않아도 상속재산분할청구가 가능하다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2017_23-32-3","t":"상속인이 피상속인의 제3자에 대한 손해배상채권을 추심하여 변제받았다면 이후에 한 상속포기는 효력이 없다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2017_23-32-4","t":"상속을 포기한 자는 상속개시된 때부터 상속인이 아니었던 것과 같은 지위에 놓이게 되므로, 피상속인의 배우자와 자녀 중 자녀 전부가 상속을 포기한 경우에는 배우자와 피상속인의 손자녀 또는 직계존속이 공동으로 상속인이 되고, 피상속인의 손자녀와 직계존속이 존재하지 아니하면 배우자가 단독으로 상속인이 된다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2017_23-32-5","t":"금전채권과 같이 급부의 내용이 가분인 채권은 공동상속되는 경우 상속개시와 동시에 당연히 법정상속분에 따라 공동상속인들에게 분할되어 귀속되므로 상속재산분할의 대상이 될 수 없는 것이 원칙이나, 상속재산분할을 통하여 공동상속인들 사이에 형평을 기할 필요가 있을 경우에는 가분채권도 예외적으로 상속재산분할의 대상이 될 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2018_24-01-1","t":"상속인이 한정승인의 신고를 하게 되면 피상속인의 채무에 대한 한정승인자의 책임은 상속재산으로 한정되고, 그 결과 상속채권자는 특별한 사정이 없는 한 상속인의 고유재산에 대하여 강제집행을 할 수 없으며 상속재산으로부터만 채권의 만족을 받을 수 있다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2018_24-01-2","t":"상속인이 한정승인을 함에는 상속개시 있음을 안 날로부터 3월내 또는 위 기간내에 상속채무가 상속재산을 초과하는 사실을 중대한 과실 없이 알지 못하고 단순승인을 한 경우에는 그 사실을 안 날부터 3월내에 한정승인을 할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2018_24-01-3","t":"상속채권자가 한정승인자의 고유재산에 대하여 강제집행을 할 수 없고 상속재산으로부터만 채권의 만족을 얻을 수 있으므로, 상속채권자는 한정승인자로부터 상속재산에 관하여 저당권 등의 담보권을 취득한 사람과의 사이에서 우선적 지위를 주장할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2018_24-01-4","t":"상속인이 한정승인을 한 때에는 피상속인에 대한 상속인의 재산상 권리의무는 소멸하지 아니한다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2018_24-01-5","t":"한정승인자는 조건 있는 채권이나 존속기간의 불확정한 채권은 법원의 선임한 감정인의 평가에 의하여 변제하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2019_25-06-1","t":"민법 제1113조 제1항에서 정하는 유류분 산정의 기초가 되는 ‘증여재산’이란 상속개시 전에 이미 증여계약이 이행되어 소유권이 수증자에게 이전된 재산을 가리키는 것이므로, 아직 증여계약이 이행되지 아니하여 소유권이 피상속인에게 남아 있는 상태로 상속이 개시된 재산은 유류분 산정의 기초가 되는 재산에 포함되지 아니한다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2019_25-06-2","t":"유류분권리자가 반환의무자를 상대로 유류분반환청구권을 행사하는 경우, 그의 유류분을 침해하는 증여는 소급적으로 효력을 상실하고 반환의무자는 상속개시 시점으로 소급하여 증여의 목적물을 사용·수익할 권리를 상실하게 되므로, 반환의무자는 선의의 점유자라 하더라도 유류분권리자에게 목적물의 사용이익을 부당이득으로 반환하여야 한다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2019_25-06-3","t":"유류분반환청구권은 유류분권리자에게 그 권리행사의 확정적 의사가 있다고 인정되는 경우라도 채권자대위권의 목적이 될 수 없다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2019_25-06-4","t":"유류분반환청구권의 행사는 재판상 또는 재판 외에서 상대방에 대한 의사표시의 방법으로 할 수 있고, 그 의사표시는 침해를 받은 유증 또는 증여행위를 지정하여 이에 대한 반환청구의 의사를 표시하면 족하나, 민법 제1117조에서 정한 유류분반환청구권의 소멸시효의 진행을 중단시키기 위해서는 그 목적물을 구체적으로 특정하여야 한다.","ox":"X","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2019_25-06-5","t":"유류분반환청구자가 유류분 제도 시행 전에 피상속인으로부터 재산을 증여받아 이행이 완료된 경우, 그 재산은 유류분산정을 위한 기초재산에는 포함되지 않으나 유류분반환청구자의 유류분 부족액 산정시 특별수익으로는 공제되어야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2019_25-19-1","t":"진정상속인이 참칭상속인을 상대로 상속재산인 부동산에 관한 등기의 말소 등을 구하는 경우에 그 소유권·지분권 등의 귀속원인을 상속으로 주장하고 있는 이상 그러한 청구는 모두 상속회복청구의 소에 해당하고, 민법 제999조 제2항의 제척기간이 적용된다.","ox":"O","m":"①","c":"A","tp":"상속회복청구권"},{"y":2019,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2019_25-19-2","t":"공동상속인 중 1인이 상속등기에 갈음하여 구 부동산소유권 이전등기 등에 관한 특별조치법에 따라 그 명의의 소유권이전등기를 경료한 경우, 다른 공동상속인이 그 등기의 말소를 청구하는 소는 상속회복청구의 소에 해당한다.","ox":"O","m":"②","c":"A","tp":"상속회복청구권"},{"y":2019,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2019_25-19-3","t":"상속인으로 오인될 만한 외관을 갖추고 있지 않거나 상속재산을 점유하고 있지도 않은 자가 스스로 상속인이라고 주장만을 하였다고 하여 이를 상속회복청구의 소에서 말하는 참칭상속인이라고 할 수 없다.","ox":"O","m":"③","c":"A","tp":"상속회복청구권"},{"y":2019,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2019_25-19-4","t":"상속회복청구권의 경우 상속재산의 일부에 대해서만 제소하여 제척기간을 준수하였을 때에는 청구의 목적물로 하지 않은 나머지 상속재산에 대해서는 제척기간을 준수한 것으로 볼 수 없다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2019_25-19-5","t":"상속회복청구권이 제척기간의 경과로 소멸된 경우 참칭상속인은 그 제척기간 만료일에 상속인으로서의 지위를 취득하고 상속재산은 그때부터 참칭상속인의 소유로 된다.","ox":"X","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2020_26-02-1","t":"기여분은 상속이 개시된 때의 피상속인의 재산가액에서 유증의 가액을 공제한 액을 넘지 못한다.","ox":"O","m":"①","c":"A","tp":"유류분 및 기여분"},{"y":2020,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2020_26-02-2","t":"유류분반환의 범위는 상속개시 당시 피상속인의 순재산과 문제된 증여재산을 합한 재산을 평가하여 그 재산액에 유류분청구권자의 유류분비율을 곱하여 얻은 유류분액을 기준으로 산정하는데, 증여받은 재산의 시가는 상속개시 당시를 기준으로 하여 산정하여야 한다.","ox":"O","m":"②","c":"A","tp":"유류분 및 기여분"},{"y":2020,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2020_26-02-3","t":"공동상속인 중에 피상속인으로부터 재산의 생전 증여에 의하여 특별수익을 한 자가 있는 경우에는 민법 제1114조의 규정은 그 적용이 배제되고, 그 증여는 수증자가 손해를 가할 것을 알고서 한 경우에 한하여 상속개시 1년 이전의 것인지 여부에 관계없이 유류분 산정을 위한 기초재산에 산입된다.","ox":"X","m":"③","c":"A","tp":"유류분 및 기여분"},{"y":2020,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2020_26-02-4","t":"상속개시 후에 인지판결이 확정되어 공동상속인이 된 자가 있더라도 그 인지판결 확정 전에 상속재산을 분할한 다른 공동상속인들이 그 분할받은 상속재산으로부터 발생한 과실을 취득하는 것은 피인지자에 대한 관계에서 부당이득이 되지 않는다.","ox":"O","m":"④","c":"A","tp":"유류분 및 기여분"},{"y":2020,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2020_26-02-5","t":"유류분반환청구권의 행사에 의하여 반환되어야 할 유증 또는 증여의 목적이 된 재산이 타인에게 양도된 경우 그 양수인이 양도 당시 유류분권리자를 해함을 안 때에는 양수인에 대하여도 그 재산의 반환을 청구할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"유류분 및 기여분"},{"y":2020,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2020_26-29-1","t":"상속포기의 신고가 아직 행하여지지 아니하거나 법원에 의하여 아직 수리되지 아니하고 있는 동안에 포기자를 제외한 나머지 공동상속인들 사이에 이루어진 상속재산분할협의는 후에 상속포기의 신고가 적법하게 수리되어 상속포기의 효력이 발생하게 됨으로써 공동상속인의 자격을 가지는 사람들 전원이 행한 것이 되어 소급적으로 유효하게 된다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2020_26-29-2","t":"피상속인은 유언으로 상속재산의 분할방법을 정할 수는 있지만, 생전행위에 의한 분할방법의 지정도 그 효력이 있어 상속인들이 피상속인의 의사에 구속된다.","ox":"X","m":"②","c":"A","tp":"상속재산분할"},{"y":2020,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2020_26-29-3","t":"공동상속인인 친권자와 미성년인 수인의 자 사이에 상속재산 분할협의를 하게 되는 경우에는 미성년자 각자마다 특별대리인을 선임하여 그 각 특별대리인이 각 미성년자인 자를 대리하여 상속재산분할의 협의를 하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2020_26-29-4","t":"상속재산을 공동상속인 1인에게 상속시킬 방편으로 나머지 상속인들이 한 상속포기 신고가 신고기간을 경과한 후에 신고된 것이어서 상속포기로서의 효력이 없다고 하더라도, 공동상속인들 사이에서는 1인이 고유의 상속분을 초과하여 상속재산 전부를 취득하고 나머지 상속인들은 이를 전혀 취득하지 않기로 하는 내용의 상속재산에 관한 협의분할이 이루어진 것으로 보아야 한다.","ox":"O","m":"④","c":"A","tp":"상속재산분할"},{"y":2020,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2020_26-29-5","t":"상속재산의 분할협의는 상속이 개시되어 공동상속인 사이에 잠정적 공유가 된 상속재산에 대하여 그 전부 또는 일부를 각 상속인의 단독소유로 하거나 새로운 공유관계로 이행시킴으로써 상속재산의 귀속을 확정시키는 것으로 그 성질상 재산권을 목적으로 하는 법률행위이므로 사해행위취소권 행사의 대상이 될 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상속재산분할"},{"y":2020,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2020_26-35-1","t":"공동상속인 중 1인이 협의분할에 의한 상속을 원인으로 하여 상속부동산에 관한 소유권이전등기를 마친 경우에, 협의분할이 다른 공동상속인의 동의 없이 이루어진 것이어서 무효라는 이유로 다른 공동상속인이 위 등기의 말소를 청구하는 소는 상속회복청구의 소에 해당한다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2020_26-35-2","t":"진정상속인이 참칭상속인으로부터 상속재산을 양수한 제3자를 상대로 상속재산인 부동산에 관한 등기의 말소 등을 청구하는 경우에도 상속회복청구권의 단기의 제척기간이 적용된다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2020_26-35-3","t":"상속회복청구권이 제척기간의 경과로 소멸하게 되면 상속인은 상속인으로서의 지위 즉 상속에 따라 승계한 개개의 권리의무 또한 총괄적으로 상실하게 되고, 그 반사적 효과로서 참칭상속인의 지위는 확정되어 참칭상속인이 상속개시의 시로부터 소급하여 상속인으로서의 지위를 취득한 것으로 봄이 상당하므로, 상속재산은 상속 개시일로 소급하여 참칭상속인의 소유로 된다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2020_26-35-4","t":"피상속인이 부담하던 금전채무가 공동상속인들에게 상속된 경우 공동상속인들은 그와 같은 채무를 상속재산 분할의 대상으로 삼을 수 있고 이때 상속재산 분할의 효력은 상속 개시 시점으로 소급한다.","ox":"X","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2020_26-35-5","t":"상속의 포기는 비록 포기자의 재산에 영향을 미치는 바가 없지 아니하나, 상속인으로서의 지위 자체를 소멸하게 하는 행위로서 순전한 재산법적 행위와 같이 볼 것이 아니다. 상속의 포기는 민법 제406조 제1항에서 정하는 재산권에 관한 법률행위에 해당하지 아니하여 사해행위취소의 대상이 되지 못한다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2021_27-11-1","t":"태아는 상속순위에 관하여 이미 출생한 것으로 보므로 대습상속 및 유류분권이 인정된다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2021_27-11-2","t":"상속포기의 효력은 피상속인의 사망으로 개시된 상속에 미칠 뿐만 아니라, 그 후 피상속인을 피대습자로 하여 개시된 대습상속에까지 미친다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2021_27-11-3","t":"공동상속인 중에 상당한 기간 동거·간호 그 밖의 방법으로 피상속인을 특별히 부양하거나 피상속인의 재산의 유지 또는 증가에 특별히 기여한 사람이 있을지라도 공동상속인의 협의 또는 가정법원의 심판으로 기여분이 결정되지 않은 이상 유류분반환청구소송에서 기여분을 주장할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2021_27-11-4","t":"공동상속인의 협의 또는 가정법원의 심판으로 기여분이 결정되었다고 하더라도 유류분을 산정함에 있어 기여분을 공제할 수 없고, 기여분으로 유류분에 부족이 생겼다고 하여 기여분에 대하여 반환을 청구할 수도 없다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2021_27-11-5","t":"유류분반환청구권은 그 행사 여부가 유류분권리자의 인격적 이익을 위하여 그의 자유로운 의사결정에 전적으로 맡겨진 권리로서 행사상의 일신전속성을 가진다고 보아야 하므로, 유류분권리자에게 그 권리행사의 확정적 의사가 있다고 인정되는 경우가 아니라면 채권자대위권의 목적이 될 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2021_27-13-1","t":"피상속인으로부터 상속받은 금전채무에 관하여 상속인 중 1인이 법정상속분을 초과하여 채무를 부담하기로 하는 상속재산에 대한 분할협의가 이루어진 경우 이는 상속이 개시된 때에 소급하여 그 효력이 있다.","ox":"X","m":"①","c":"A","tp":"상속재산의 분할"},{"y":2021,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2021_27-13-2","t":"상속재산의 분할협의는 공동상속인 사이에 잠정적 공유가 된 상속재산의 귀속을 확정시키는 것이므로, 그 협의를 통하여 공동상속인 중 무자력인 자가 자신의 상속에 관한 권리를 포기하는 내용으로 분할협의를 하였다고 하더라도 이러한 분할협의가 사해행위취소권 행사의 대상이 될 수는 없다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2021_27-13-3","t":"상속재산의 분할에 관하여 공동상속인 사이에 협의가 성립되지 아니하거나 협의할 수 없는 경우에는 상속재산에 속하는 개별 재산에 관하여 가정법원에 민법 제268조의 규정에 의한 공유물분할청구의 소를 제기할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2021_27-13-4","t":"상속재산 분할협의는 공동상속인들 사이에 이루어지는 일종의 계약으로서, 공동상속인들은 이미 이루어진 상속재산 분할협의의 전부 또는 일부를 전원의 합의에 의하여 해제한 다음 다시 새로운 분할협의를 할 수 있고, 이는 이미 상속등기를 마친 경우에도 마찬가지이다.","ox":"O","m":"④","c":"A","tp":"상속재산의 분할"},{"y":2021,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2021_27-13-5","t":"공동상속인 중 1인이 신청한 한정승인에 따른 청산절차가 종료되지 않은 경우 다른 상속인들은 상속재산분할청구를 할 수 없다.","ox":"X","m":"⑤","c":"A","tp":"상속재산의 분할"},{"y":2021,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2021_27-20-1","t":"재산상속에 관하여 진정한 상속인임을 전제로 상속으로 인한 재산권의 귀속을 주장하며 참칭상속인 또는 자기들만이 재산상속을 하였다는 일부 공동상속인들을 상대로 상속재산인 부동산에 관한 등기의 말소 등을 청구하는 것이라면 그 청구원인 여하에 불구하고 민법 제999조 소정의 상속회복청구의 소에 해당하여 10년의 제척기간의 적용을 받는다.","ox":"O","m":"①","c":"A","tp":"민법 제999조의 상속회복청구권"},{"y":2021,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2021_27-20-2","t":"동일한 부동산에 관하여 등기명의인을 달리하여 중복된 소유권보존등기가 마쳐져, 선행 보존등기로부터 소유권이전등기를 한 소유자의 상속인이 후행 보존등기나 그에 기하여 순차로 이루어진 소유권이전등기 등 후속등기가 모두 무효라는 이유로 등기의 말소를 구하는 경우 이는 무효인 후행 보존등기로부터 이루어진 소유권이전등기가 참칭상속인에 의한 것이어서 무효이고 따라서 후속등기도 무효임을 이유로 하는 것이 아니라 후행 보존등기 자체가 무효임을 이유로 하는 것이므로 상속회복청구의 소에 해당하지 않는다.","ox":"O","m":"②","c":"A","tp":"민법 제999조의 상속회복청구권"},{"y":2021,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2021_27-20-3","t":"甲의 사망 후 乙이 단독상속인이 되었으나 참칭상속인 丙이 乙의 상속권을 침해한 경우, 상속회복청구권의 행사기간이 경과한 때에는 그 행사기간이 만료한 때로 소급하여 乙은 상속인으로서의 지위를 상실하게 되는 반면, 丙은 상속인으로서 지위를 취득하게 된다.","ox":"X","m":"③","c":"A","tp":"민법 제999조의 상속회복청구권"},{"y":2021,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2021_27-20-4","t":"상속회복청구권은 그 침해를 안 날부터 3년, 상속권의 침해행위가 있은 날부터 10년을 경과하면 소멸하는데, 피상속인의 사망 후 인지되어 공동상속인이 된 혼외자가 ‘상속권의 침해를 안 날’이라 함은 그 인지판결이 확정된 날을 말한다.","ox":"O","m":"④","c":"A","tp":"민법 제999조의 상속회복청구권"},{"y":2021,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2021_27-20-5","t":"제3자가 특정한 공동상속인의 의사와 아무런 상관 없이 서류를 위조하여 그 특정 상속인의 명의로 상속등기를 마쳤다고 하더라도 그 등기명의인이 참칭상속인이 되는 것은 아니다.","ox":"O","m":"⑤","c":"A","tp":"민법 제999조의 상속회복청구권"},{"y":2022,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2022_28-15-1","t":"유류분반환의 범위는 상속개시 당시 피상속인의 순재산과 문제된 증여재산을 합한 재산을 평가하여 그 재산액에 유류분청구권자의 유류분비율을 곱하여 얻은 유류분액을 기준으로 산정하는데, 그 유류분액을 산정함에 있어 반환의무자가 증여받은 재산의 시가는 상속개시 당시가 아닌 유류분반환청구권 행사 당시를 기준으로 산정한다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2022_28-15-2","t":"유류분권리자가 유류분반환청구권을 행사한 경우 그의 유류분을 침해하는 범위 내에서 유증 또는 증여는 소급적으로 효력을 상실하고, 상대방은 그와 같이 실효된 범위 내에서 유증 또는 증여의 목적물을 반환할 의무를 부담한다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2022_28-15-3","t":"유류분반환청구권의 단기소멸시효기간의 기산점인 ‘유류분권리자가 상속의 개시와 반환하여야 할 증여 또는 유증을 한 사실을 안 때’는 유류분권리자가 상속이 개시되었다는 사실과 증여 또는 유증이 있었다는 사실 및 그것이 반환하여야 할 것임을 안 때를 뜻한다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2022_28-15-4","t":"유류분 제도가 생기기 전에 피상속인이 상속인이나 제3자에게 재산을 증여하고 그 이행을 완료하여 소유권이 수증자에게 이전된 때에는 피상속인이 1977. 12. 31. 법률 제3051호로 개정된 민법 시행 이후에 사망하여 상속이 개시되더라도 소급하여 그 증여재산이 유류분 제도에 의한 반환청구의 대상이 되지는 않는다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2022_28-15-5","t":"유류분반환청구권의 행사는 재판상 또는 재판 외에서 상대방에 대한 의사표시의 방법으로 할 수 있고, 이 경우 그 의사표시는 침해를 받은 유증 또는 증여행위를 지정하여 이에 대한 반환청구의 의사를 표시하면 그것으로 족하며, 그 반환목적물을 구체적으로 특정하여야 하는 것은 아니다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2022_28-19-1","t":"상속인은 상속개시 있음을 안 날로부터 3월내에 단순승인이나 한정승인 또는 포기를 할 수 있는데, 그 기간은 이해관계인 또는 검사의 청구에 의하여 가정법원이 이를 연장할 수 있다.","ox":"O","m":"①","c":"A","tp":"상속인의 한정승인 및 단순승인"},{"y":2022,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2022_28-19-2","t":"상속인이 미성년인 경우 특별한정승인에 관한 민법 제1019조 제3항이나 그 소급 적용에 관한 민법 부칙(2002. 1. 14. 개정 법률 부칙 중 2005. 12. 29. 법률 제7765호로 개정된 것) 제3항, 제4항에서 정한 ‘상속채무 초과사실을 중대한 과실 없이 제1019조 제1항의 기간 내에 알지 못하였는지’와 ‘상속채무 초과사실을 안 날이 언제인지’를 판단할 때에는 법정대리인의 인식을 기준으로 삼아야 한다.","ox":"O","m":"②","c":"A","tp":"상속인의 한정승인 및 단순승인"},{"y":2022,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2022_28-19-3","t":"특별한정승인에 관한 민법 제1019조 제3항이 규정한 ‘상속인이 상속채무가 상속재산을 초과하는 사실을 중대한 과실 없이 민법 제1019조 제1항의 기간 내에 알지 못하였다는 점’에 대한 증명책임은 상속인에게 있다.","ox":"O","m":"③","c":"A","tp":"상속인의 한정승인 및 단순승인"},{"y":2022,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2022_28-19-4","t":"민법은 한정승인자가 상속재산으로 상속채권자 등에게 변제하는 절차를 규정하고 있으므로, 한정승인에 의하여 상속채권자는 상속재산에 관하여 한정승인자로부터 물권을 취득한 제3자에 대하여 우선적 지위를 부여받는다.","ox":"X","m":"④","c":"A","tp":"상속인의 한정승인 및 단순승인"},{"y":2022,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2022_28-19-5","t":"‘상속인이 상속재산에 대한 처분행위를 한 때’ 단순승인으로 의제하는 규정인 민법 제1026조 제1호는 상속인이 한정승인 또는 포기를 하기 이전에 상속재산을 처분한 때에만 적용되는 것이고, 상속인이 한정승인 또는 포기를 한 후에 상속재산을 처분한 때에는 그것이 같은 조 제3호에 정한 상속재산의 부정소비에 해당되는 경우에만 상속인이 단순승인을 한 것으로 보아야 하는 것이지, 같은 조 제1호에 의한 단순승인 의제가 되는 것이 아니다.","ox":"O","m":"⑤","c":"A","tp":"상속인의 한정승인 및 단순승인"},{"y":2023,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2023_29-18-1","t":"피상속인의 배우자는 피상속인에게 직계비속이 있는 경우 직계비속과 공동상속인이 되고, 직계비속인 손자녀가 있는 경우 자녀 모두가 상속을 포기하더라도 상속포기의 소급효에 따라 자녀는 처음부터 상속인이 아니었던 것이 되어 피상속인의 배우자는 손자녀와 공동상속인이 된다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2023_29-18-2","t":"상속재산의 협의분할은 공동상속인 간의 일종의 계약으로서 공동상속인 전원이 참여하여야 하고 일부 상속인만으로 한 협의분할은 무효이나, 반드시 한 자리에서 이루어질 필요는 없고 순차적으로 이루어질 수도 있으며, 상속인 중 한 사람이 만든 분할 원안을 다른 상속인이 후에 돌아가며 승인하여도 무방하다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2023_29-18-3","t":"상속개시 당시에는 상속재산을 구성하던 재산이 그 후 처분되거나 멸실·훼손되는 등으로 상속재산분할 당시 상속재산을 구성하지 아니하게 되었다면 그 재산은 상속재산분할의 대상이 될 수 없다. 다만 상속인이 그 대가로 대상재산을 취득하게 된 경우, 그 대상재산이 상속재산분할의 대상이 될 수 있다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2023_29-18-4","t":"상속의 포기는 사해행위취소의 대상이 될 수 없으나, 상속재산의 분할협의는 사해행위취소의 대상이 될 수 있다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2023_29-18-5","t":"상속에 관한 비용은 상속재산 중에서 지급하는 것으로 상속재산의 관리 및 청산에 필요한 비용을 의미하므로, 장례비용도 피상속인이나 상속인의 사회적 지위와 그 지역의 풍속 등에 비추어 합리적인 금액 범위 내라면 이를 상속비용으로 보아야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2024_30-16-1","t":"포괄적 유증을 받은 자도 상속회복청구를 할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2024_30-16-2","t":"상속회복청구의 소에 있어 상대방이 되는 참칭상속인이라 함은, 재산상속인인 것을 신뢰케 하는 외관을 갖추고 있는 자나 상속인이라고 참칭하여 상속재산의 전부 또는 일부를 점유하는 자 등을 가리키는 것이므로 상속인으로 오인될 만한 외관을 갖추고 있지 않거나 상속재산을 점유하고 있지도 않은 자가 스스로 상속인이라는 주장만을 하였다 하여 이를 상속회복청구의 소에서 말하는 참칭상속인이라고는 할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2024_30-16-3","t":"진정상속인이 참칭상속인으로부터 상속재산을 양수한 제3자를 상대로 등기말소청구를 하는 경우에는 상속회복청구권의 단기의 제척기간이 적용되지 않는다.","ox":"X","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2024_30-16-4","t":"상속회복청구의 소는 진정상속인과 참칭상속인이 주장하는 피상속인이 동일인임을 전제로 하는 것이므로 진정상속인이 주장하는 피상속인과 참칭상속인이 주장하는 피상속인이 다른 사람인 경우에는 진정상속인의 청구원인이 상속에 의하여 소유권을 취득하였음을 전제로 한다고 하더라도 이를 상속회복청구의 소라고 할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2024_30-16-5","t":"상속회복청구권이 제척기간의 경과로 소멸하게 되면 상속인은 상속인으로서의 지위 즉 상속에 따라 승계한 개개의 권리의무 또한 총괄적으로 상실하게 되고, 그 반사적 효과로서 참칭상속인의 지위는 확정되어 참칭상속인이 상속개시 시로 소급하여 상속인으로서의 지위를 취득한 것으로 봄이 상당하므로, 상속재산은 상속 개시일로 소급하여 참칭상속인의 소유로 된다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2025_31-02","t":"상속회복청구의 행사기간에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"상속회복청구의 행사기간에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["상속회복청구권은 그 침해를 안 날부터 3년, 상속권의 침해행위가 있은 날부터 10년을 경과하면 소멸된다.","위 ①의 기간은 제소기간이 아니므로, 재판 외에서도 위 기간 내에 상속회복청구를 하였다면 상속회복청구권은 소멸하지 않는다.","상속회복청구권의 제척기간 기산점이 되는 ‘상속권의 침해를 안 날’이라 함은 자기가 진정한 상속인임을 알고 또 자기가 상속에서 제외된 사실을 안 때를 가리키는 것으로서, 단순히 상속권 침해의 추정이나 의문만으로는 충분하지 않다.","상속회복청구권의 제척기간의 기산점이 되는 ‘상속권의 침해행위가 있은 날’이라 함은 참칭상속인이 상속재산의 전부 또는 일부를 점유하거나 상속재산인 부동산에 관하여 소유권이전등기를 마치는 등의 방법에 의하여 진정한 상속인의 상속권을 침해하는 행위를 한 날을 의미한다.","상속재산의 일부에 대한 상속회복청구의 제소기간을 준수하였다고 하여 그로써 다른 상속재산에 대한 소송에 그 기간준수의 효력이 생기지 아니한다."],"a":2}},{"y":2026,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2026_32-01-1","t":"수증자가 증여받은 재산을 상속개시 전에 처분하거나 수용된 경우, 유류분 산정에서 증여재산 가액은 처분 당시의 현실 가치를 기준으로 상속개시까지의 물가변동률을 반영하여 산정한다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2026_32-01-2","t":"유류분반환청구권 단기소멸시효의 기산점인 ‘반환하여야 할 증여 또는 유증을 한 사실을 안 때’란 증여⋅유증이 있었다는 사실 및 그것이 반환하여야 할 것임을 안 때를 의미한다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2026_32-01-3","t":"유류분권리자가 반환청구할 수 있는 유류분 부족액은 유류분액에서 유류분권리자가 받은 특별수익액과 순상속분액을 공제하는 방법으로 산정한다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2026_32-01-4","t":"피상속인이 공동상속인 아닌 제3자를 보험수익자로 지정한 생명보험계약을 체결하여 그 제3자가 생명보험금을 수령한 경우, 그 보험금은 유류분 산정의 기초재산에 포함되는 증여에 해당하지 않는다.","ox":"X","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2026_32-01-5","t":"피상속인의 직계존속의 유류분은 그 법정상속분의 3분의 1이다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2026_32-03-1","t":"민법 제1007조에서 정한 ‘상속분’은 법정상속분을 의미하므로, 상속재산분할이 마쳐지지 않은 상태에서 특정 공동상속인에게 구체적 상속분이 없다는 이유로 그 공동상속인에게 법정상속분에 따른 권리승계가 이루어지지 않았다고 주장하는 것은 허용되지 않는다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2026_32-03-2","t":"민법 제1026조 제1호의 ‘상속재산에 대한 처분행위’에는 재산의 현상이나 성질을 변경하는 사실적⋅법률적 행위뿐만 아니라 상속재산의 보존⋅관리행위도 포함된다.","ox":"X","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2026_32-03-3","t":"금전채권과 같은 가분채권이 공동상속되는 경우, 특별수익이나 기여분이 인정되더라도 가분채권은 상속재산분할의 대상이 될 수 없다.","ox":"X","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2026_32-03-4","t":"주식이 공동상속되는 경우에도 금전채권과 마찬가지로 상속개시와 동시에 법정상속분에 따라 당연히 분할되어 각 공동상속인에게 귀속된다.","ox":"X","m":"④","c":"A","tp":"상속재산"},{"y":2026,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2026_32-03-5","t":"기여분은 상속이 개시된 때의 피상속인의 재산가액에서 유증의 가액을 공제한 액을 초과할 수도 있다.","ox":"X","m":"⑤","c":"A","tp":"상속재산"},{"y":2026,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2026_32-19-1","t":"특별한 사정이 없는 한 유증의 철회에 관한 민법 제1108조 제1항은 사인증여에 준용된다.","ox":"O","m":"①","c":"A","tp":"유언, 유증 등"},{"y":2026,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2026_32-19-2","t":"유언증서가 성립한 후 멸실되거나 분실되었다는 사유만으로 유언이 실효되는 것은 아니고, 이해관계인은 유언증서의 내용을 증명하여 유언의 유효를 주장할 수 있다.","ox":"O","m":"②","c":"A","tp":"유언, 유증 등"},{"y":2026,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2026_32-19-3","t":"민법이 유언의 방식을 엄격하게 규정한 취지에 비추어, 법정된 요건과 방식에 어긋난 유언이라도 그것이 유언자의 진정한 의사에 합치한다면 유효하다.","ox":"X","m":"③","c":"A","tp":"유언, 유증 등"},{"y":2026,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2026_32-19-4","t":"‘유언취지의 구수’라 함은 말로써 유언의 내용을 상대방에게 전달하는 것을 뜻하므로, 증인이 제3자에 의하여 미리 작성된, 유언의 취지가 적혀 있는 서면에 따라 유언자에게 질문을 하고 유언자가 동작이나 간략한 답변으로 긍정하는 방식은, 특별한 사정이 없는 한 민법 제1070조의 ‘유언취지의 구수’에 해당한다고 볼 수 없다.","ox":"O","m":"④","c":"A","tp":"유언, 유증 등"},{"y":2026,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2026_32-19-5","t":"유증을 받을 자는 유언자의 사망 후에 언제든지 유증을 승인 또는 포기할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"유언, 유증 등"}],"3":[{"y":2016,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2016_22-09-1","t":"甲 소유의 A부동산에 관하여 甲과 乙 사이에 ‘甲이 乙에게 소유권을 이전한다.’는 내용의 재판상 화해가 성립하여 그와 같은 내용의 화해조서가 작성된 경우라도, 乙은 자신 명의로 소유권이전등기를 경료하여야만 그 부동산의 소유권을 취득한다.","ox":"O","m":"①","c":"A","tp":"등기의 효력"},{"y":2016,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2016_22-09-2","t":"환매기간을 제한하는 환매특약이 등기부에 기재되어 있는 때에는 반증이 없는 한 등기부 기재와 같은 환매특약이 진정하게 성립된 것으로 추정함이 상당하다.","ox":"O","m":"②","c":"A","tp":"등기의 효력"},{"y":2016,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2016_22-09-3","t":"A부동산에 관하여 甲에서 乙, 丙으로 순차적으로 소유권이전등기가 경료된 경우, 丙이 乙로부터 부동산을 취득함에 있어 등기부상 기재된 등기원인인 증여에 의하지 않고 다른 원인인 매매에 의하여 적법하게 취득하였다고 주장하더라도 그 등기의 추정력은 유지된다.","ox":"O","m":"③","c":"A","tp":"등기의 효력"},{"y":2016,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2016_22-09-4","t":"A부동산에 관한 전(前) 등기명의인이 미성년자 乙이고 당해 부동산을 친권자 甲에게 증여하는 행위가 이해상반행위라면, 일단 甲에게 이전등기가 마쳐졌더라도 그 이전등기에 관하여 필요한 절차를 적법하게 거친 것으로 추정되기는 어렵다.","ox":"X","m":"④","c":"A","tp":"등기의 효력"},{"y":2016,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2016_22-09-5","t":"甲 소유의 A토지에 乙 명의로 소유권이전청구권 보전을 위한 가등기가 설정되어 있었는데, 丙이 A토지의 소유권을 양도받은 후 乙 명의의 가등기가 불법으로 말소된 경우, 乙은 丙을 상대로 가등기의 회복등기청구를 하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"등기의 효력"},{"y":2017,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2017_23-07-1","t":"최초 매도인과 중간 매수인, 중간 매수인과 최종 매수인 사이에 순차로 매매계약이 체결되고 이들 간에 중간생략등기의 합의가 있는 후에 최초 매도인과 중간 매수인 간에 매매대금을 인상하는 약정이 체결된 경우, 최초 매도인은 인상된 매매대금이 지급되지 않았음을 이유로 최종 매수인 명의로의 소유권이전등기의무의 이행을 거절할 수 있다.","ox":"O","m":"①","c":"A","tp":"부동산등기"},{"y":2017,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2017_23-07-2","t":"기존건물이 멸실된 후 그곳에 새로이 건축한 건물의 물권변동에 관한 등기를 멸실한 건물의 등기부에 한 경우 양 건물의 재료, 위치, 구조가 동일하더라도 그로써 신축된 건물이 멸실된 건물과 동일하다고 볼 수 없으므로 위 등기는 실체에 부합하는 등기로 볼 수 없다.","ox":"O","m":"②","c":"A","tp":"부동산등기"},{"y":2017,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2017_23-07-3","t":"순차 경료된 소유권이전등기의 각 말소 청구소송은 통상공동소송이므로 그 중의 어느 한 등기명의자만을 상대로 말소를 구할 수 있고, 최종 등기명의자에 대하여 등기말소를 구할 수 있는지에 관계없이 중간의 등기명의자에 대하여 등기말소를 구할 소의 이익이 있다.","ox":"O","m":"③","c":"A","tp":"부동산등기"},{"y":2017,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2017_23-07-4","t":"등기명의자가 전소유자로부터 부동산을 취득함에 있어 등기부상 기재된 등기원인에 의하지 아니하고 다른 원인으로 적법하게 취득하였다고 하면서 등기원인행위의 태양이나 과정을 다소 다르게 주장한다고 하여 이러한 주장만으로 그 등기의 추정력이 깨어진다고 볼 수 없고, 이는 전소유자가 사망한 이후에 그 명의의 신청에 의하여 이루어진 이전등기의 경우도 마찬가지이다.","ox":"X","m":"④","c":"A","tp":"부동산등기"},{"y":2017,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2017_23-07-5","t":"선 등기명의자의 소유권이전등기가 원인무효라 하더라도 그 이후의 최종 등기명의자가 등기부 시효취득의 항변을 제출하여 법원에서 받아들여졌다면, 그 전의 등기명의자들은 최종 등기명의자의 시효취득 사실을 원용하여 원소유자의 소유권 상실을 주장할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"부동산등기"},{"y":2017,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2017_23-10-1","t":"A토지는 甲이 선대로부터 사정받은 토지인데, 乙 명의로 원인무효의 소유권보존등기가 경료된 후 丙 앞으로 소유권이전등기가 경료되었다. 甲은 乙과 丙을 상대로 乙과 丙 명의의 등기의 말소를 구하는 소를 제기하였는데, 법원은 乙에 대한 청구는 인용하였으나 丙에 대한 청구는 등기부취득시효가 완성되었다는 이유로 기각하였고 이 판결은 확정되었다. 이 경우 A토지의 진정한 소유자였던 甲은 乙을 상대로 물권적 청구권인 소유권보존등기 말소등기청구권의 이행불능으로 인한 민법 제390조상의 손해배상청구권을 가진다고 말할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2017_23-10-2","t":"점유자가 유익비를 지출할 당시 계약관계 등 적법한 점유의 권원을 가진 경우 점유자는 그 계약관계 등의 상대방에 대하여 계약관계를 규율하는 법조항이나 법리에 따른 비용상환청구권을 행사하는 외에도 계약관계 등의 상대방이 아닌 점유회복 당시의 소유자에 대하여 민법 제203조 제2항에 따른 지출비용의 상환을 구할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2017_23-10-3","t":"점유자가 점유의 침탈을 당한 때에는 그 물건의 반환 및 손해의 배상을 청구할 수 있는데, 침탈자의 특별승계인이 악의인 경우에는 그자에 대하여도 위의 청구를 할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2017_23-10-4","t":"토지 소유자가 그 지상에 건축된 건물의 소유자에게 부지의 불법점유를 이유로 건물에서 퇴거할 것을 청구할 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2017_23-10-5","t":"타인 소유물을 권원 없이 점유함으로써 얻은 사용이익을 반환하는 경우 악의 수익자는 받은 이익에 이자를 붙여 반환하여야 하고, 위 이자의 이행지체로 인한 지연손해금도 지급하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2018_24-17-1","t":"양도인이 소유자로부터 보관을 위탁받은 동산을 제3자에게 보관시킨 경우에 양도인이 그 제3자에 대한 반환청구권을 양수인에게 양도하고 지명채권 양도의 대항요건을 갖추었을 때에는 동산 선의취득에 필요한 점유의 취득 요건을 충족한다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2018_24-17-2","t":"민법 제251조는 “양수인이 도품 또는 유실물을 경매나 공개시장에서 또는 동종류의 물건을 판매하는 상인에게서 선의로 매수한 때에는 피해자 또는 유실자는 양수인이 지급한 대가를 변상하고 그 물건의 반환을 청구할 수 있다.”라고 규정하고 있으므로 위 규정이 적용되기 위하여 양수인이 무과실일 필요는 없으나, 양수인에게 중과실이 있어서는 아니된다.","ox":"X","m":"②","c":"A","tp":"선의취득"},{"y":2018,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2018_24-17-3","t":"채무자 이외의 자 소유에 속하는 동산을 경매한 경우에도, 경매절차에서 그 동산을 매수하여 매각대금을 납부하고 이를 인도받은 매수인이 선의취득 요건을 갖추었다면 특별한 사정이 없는 한 그 소유권을 선의취득한다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2018_24-17-4","t":"위탁물 횡령에 있어 그 객체가 된 물건은 물론, 형법상으로는 절도죄가 성립하는 점유보조자의 횡령의 객체가 된 물건도 민법 제250조에 정한 도품, 유실물에는 포함되지 않는다.","ox":"O","m":"④","c":"A","tp":"선의취득"},{"y":2018,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2018_24-17-5","t":"자동차관리법이 적용되는 자동차의 소유권 취득에 관해서는 민법 제249조의 선의취득 규정은 적용되지 않는 것이 원칙이다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2018_24-29-1","t":"자동차손해배상 보장법에 의한 피해자의 보험자에 대한 직접청구권이 수반되는 경우에 그 직접청구권의 전제가 되는 자동차손해배상 보장법 제3조에 의한 피해자의 운행자에 대한 손해배상청구권은 비록 위 손해배상청구권과 손해배상의무가 상속에 의하여 동일인에게 귀속되더라도 혼동에 의하여 소멸되지 않고, 이러한 법리는 가해자가 피해자의 상속인이 되더라도 동일하다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2018_24-29-2","t":"임차주택의 양수인에게 대항할 수 있는 주택임차인이 당해 임차주택을 경락받아 그 대금을 납부함으로써 임차주택의 소유권을 취득한 때에는 그 주택임차인은 임대인의 지위를 승계하는 결과, 특별한 사정이 없는 한 임대차계약에 기한 채권이 혼동으로 인하여 소멸하게 되므로 그 임대차는 종료된 상태가 된다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2018_24-29-3","t":"명의신탁자가 장차 소유권이전등기청구권 보전을 위한 가등기를 경료한 후 가등기와는 상관없이 소유권이전등기를 넘겨받았다는 사정만으로는 가등기에 기한 본등기청구권이 혼동으로 소멸하지 않는다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2018_24-29-4","t":"어떠한 물건에 대한 소유권과 다른 물권이 동일한 사람에게 귀속한 경우 그 제한물권은 혼동에 의하여 소멸하는 것이 원칙이지만, 본인 또는 제3자의 이익을 위하여 그 제한물권을 존속시킬 필요가 있다고 인정되는 경우에는 혼동으로 소멸하지 않는다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2018_24-29-5","t":"부동산에 대한 소유권과 임차권이 동일인에게 귀속하게 되는 경우 그 임차권이 대항요건을 갖추고 있고 또한 그 대항요건을 갖춘 후에 저당권이 설정된 때에는 임차권은 혼동으로 소멸하지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2019_25-17-1","t":"근저당권 이전의 부기등기가 경료되었으나 근저당권설정등기가 당초부터 원인무효인 경우, 근저당권설정자는 근저당권의 현재 명의인인 양수인을 상대로 주등기인 근저당권설정등기의 말소를 구할 수 있을 뿐만 아니라, 근저당권자로부터 양수인 앞으로의 근저당권 이전이 무효임을 이유로 양수인을 상대로 근저당권설정등기의 말소를 구할 수도 있다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2019_25-17-2","t":"전(前) 등기명의인이 미성년자이고 당해 부동산을 친권자에게 증여하는 행위가 이해상반행위라 하더라도 일단 친권자에게 이전등기가 경료된 이상, 특별한 사정이 없는 한 그 이전등기에 관하여 필요한 절차를 적법하게 거친 것으로 추정된다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2019_25-17-3","t":"부동산의 공유자 중 한 사람은 공유물에 경료된 원인무효의 등기에 관하여 각 공유자에게 해당 지분별로 진정명의회복을 원인으로 한 소유권이전등기를 이행할 것을 단독으로 청구할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2019_25-17-4","t":"채권자가 무효인 소유권이전등기청구권의 보전을 위한 가등기의 유용 합의에 따라 부동산 소유자인 채무자로부터 그 가등기 이전의 부기등기를 마친 제3채무자를 상대로 채무자를 대위하여 가등기의 말소를 구하는 경우, 채권자가 그 부기등기 전에 부동산을 가압류한 사실을 주장하는 것은 채무자가 아닌 채권자 자신이 제3채무자에 대하여 가지는 사유에 관한 것이어서 허용되지 않는다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2019_25-17-5","t":"명의신탁 부동산을 명의수탁자가 임의로 처분할 경우에 대비하여 명의신탁자가 명의수탁자와 합의하여 자신의 명의로 소유권이전등기청구권 보전의 가등기를 경료한 경우, 비록 그 가등기의 등기원인이 매매예약이며 명의신탁자와 명의수탁자 사이에 그와 같은 매매예약이 체결된 바 없다 하더라도 위와 같은 가등기를 하기로 하는 명의신탁자와 명의수탁자의 합의를 통정허위표시라 할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2019_25-20","t":"물권적청구권과 관련한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"물권적청구권과 관련한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","d":"ㄱ.소유권에 기한 방해배제청구권에 있어서 ‘방해’란 현재에도 지속되고 있는 침해를 의미하므로, 소유권에 기한 방해배제청구권은 방해결과의 제거를 내용으로 할 수는 없다.\nㄴ.소유권을 양도하면서 소유권에 의하여 발생되는 물권적청구권을 소유권과 분리하여 소유권이 없는 전(前) 소유자에게 유보하여 제3자에게 대하여 이를 행사케 하는 것은 허용될 수 없다.\nㄷ.민법 제214조에 의하면 소유자는 소유권을 방해하는 자에 대하여 그 방해제거 행위를 청구할 수 있으므로, 소유자는 위 규정에 기하여 침해자에게 방해제거에 드는 비용 또한 청구할 수 있다.\nㄹ.등기명의인의 표시변경의 부기등기가 등기명의인의 동일성을 해치는 방법으로 행하여져서 부동산 등기부상의 표시가 실제 소유관계를 표상하고 있는 것이 아니라면, 진실한 소유자는 그 표시상의 소유명의자를 상대로 부기등기인 표시변경등기의 말소를 구할 수 있다.\nㅁ.토지소유자가 그 소유 토지에 대한 일반 공중의 통행을 용인하여 자신의 토지에 대한 독점적․배타적 사용․수익권이 인정되지 않는 경우라면, 이후 그 사용․수익권을 배제하는 기초가 된 객관적인 사정이 현저하게 변경되었다고 하더라도, 토지소유자가 다시 사용․수익권능을 포함한 완전한 소유권을 주장하는 것은 신의칙에 반하여 허용될 수 없다.","o":["ㄱ, ㄴ, ㄷ, ㅁ","ㄷ, ㅁ","ㄷ","ㄹ, ㅁ","ㄷ, ㄹ, ㅁ"],"a":2}},{"y":2019,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2019_25-26","t":"점유에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"점유에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["토지의 점유자가 소유자를 상대로 토지에 관한 소유자 명의의 소유권이전등기의 말소등기청구 소송을 제기하여 그 소송사건이 점유자의 패소로 확정된 경우, 점유자의 점유는 타주점유로 전환된다고 할 수 없다.","부동산을 매수하여 이를 점유하게 된 자는 그 매매가 무효가 된다는 사정이 있음을 알았다는 등의 사정이 없는 한 점유개시시에 소유의 의사로 점유한 것이며, 나중에 매도자에게 처분권이 없었다는 등의 사유로 그 매매가 무효인 것이 밝혀졌다 하더라도 타주점유로 전환되지 않는다.","건물의 부지가 된 토지는 그 건물의 소유자가 점유하는 것이고, 건물의 소유권이 양도된 경우에는 건물의 종전의 소유자는 그 부지의 점유를 계속할 별도의 독립된 권원이 있는 등의 사정이 없는 한 그 부지에 대한 점유도 함께 상실한다.","토지의 소유자가 점유자를 상대로 토지에 관한 점유자 명의의 소유권이전등기의 말소등기청구소송을 제기하여 그 소송사건이 점유자의 패소로 확정된 경우, 점유자의 점유는 그 소유권이전등기말소등기청구소송의 제기시부터 타주점유로 전환된다.","미등기건물을 양수하여 건물에 관한 사실상의 처분권을 보유하게 됨으로써 그 양수인이 건물부지 역시 아울러 점유하고 있다고 볼 수 있는 등의 사정이 없는 한 건물의 소유명의자가 아닌 자는 실제로 그 건물을 점유하고 있다고 하더라도 그 건물의 부지를 점유하는 자로 볼 수 없다. 22-18"],"a":4}},{"y":2019,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2019_25-35","t":"甲은 乙 소유의 A 토지를 매수하여 매매대금을 전부 지급하고, A 토지를 인도받아 현재까지 사용․수익하고 있으나, 아직 그 명의로 소유권이전등기를 마치지 못한 상태이다. 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"甲은 乙 소유의 A 토지를 매수하여 매매대금을 전부 지급하고, A 토지를 인도받아 현재까지 사용․수익하고 있으나, 아직 그 명의로 소유권이전등기를 마치지 못한 상태이다. 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["甲은 A 토지의 소유권을 취득하지 못하였으므로, 소유권에 기한 물권적 청구권을 행사할 수 없다.","乙은 甲을 상대로 A 토지에 대하여 소유권에 기한 반환청구를 할 수 없다.","乙은 甲을 상대로 등기를 인수받아 갈 것을 구하고 그 판결을 받아 甲 명의의 소유권이전등기를 강제로 실현할 수 있다.","甲이 丙에게 A 토지를 전매하였다고 하더라도, 乙은 丙에 대하여 소유권에 기한 물권적 청구권을 행사하거나 丙의 점유․사용을 법률상 원인이 없는 이익이라고 하여 부당이득반환청구를 할 수는 없다.","甲이 丙에게 A 토지를 처분하여 점유를 승계하여 주었다면, 甲의 소유권이전등기청구권은 점유 상실 시점부터 소멸시효가 진행된다. 22-20"],"a":5}},{"y":2020,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2020_26-19-1","t":"토지의 점유자가 이전에 토지 소유자를 상대로 그 토지에 관하여 매매를 원인으로 한 소유권이전등기청구소송을 제기하였다가 패소하고 그 판결이 확정되었다 하더라도 그 사정만을 들어서는 토지 점유자의 자주점유의 추정이 번복되어 타주점유로 전환된다고 할 수 없다.","ox":"O","m":"①","c":"A","tp":"점유권"},{"y":2020,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2020_26-19-2","t":"점유자가 유익비를 지출할 당시 계약관계 등 적법한 점유의 권원을 가진 경우에 그 지출비용의 상환에 관하여는 그 계약관계를 규율하는 법조항이나 법리 등이 적용되는 것이어서 점유자는 그 계약관계 등의 상대방에 대하여 해당 법조항이나 법리에 따른 비용상환청구권을 행사할 수 있을 뿐 계약관계 등의 상대방이 아닌 점유회복 당시의 소유자에 대하여 민법 제203조 제2항에 따른 지출비용의 상환을 구할 수는 없다.","ox":"O","m":"②","c":"A","tp":"점유권"},{"y":2020,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2020_26-19-3","t":"민법 제203조 제2항에서 유익비의 상환범위는 점유자가 유익비로 지출한 금액과 현존하는 증가액 중에서 회복자가 선택하는 것이며, 그 실제 지출금액 및 현존 증가액에 관한 증명책임도 회복자에게 있다고 보아야 한다.","ox":"X","m":"③","c":"A","tp":"점유권"},{"y":2020,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2020_26-19-4","t":"유효한 도급계약에 기하여 수급인이 도급인으로부터 제3자 소유 물건의 점유를 이전받아 이를 수리한 결과 그 물건의 가치가 증가한 경우, 도급인이 그 물건을 간접점유하면서 궁극적으로 자신의 계산으로 비용지출과정을 관리한 것이므로, 도급인만이 소유자에 대한 관계에 있어서 민법 제203조에 의한 비용상환청구권을 행사할 수 있는 비용지출자라고 할 것이고, 수급인은 그러한 비용지출자에 해당하지 않는다고 보아야 한다.","ox":"O","m":"④","c":"A","tp":"점유권"},{"y":2020,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2020_26-19-5","t":"민법 제201조 제1항은 선의의 점유자는 점유물의 과실을 취득한다고 규정하고 있는바, 여기서 선의의 점유자라 함은 과실수취권을 포함하는 권원이 있다고 오신한 점유자를 말하고, 다만 그와 같은 오신을 함에는 오신할 만한 정당한 근거가 있어야 한다.","ox":"O","m":"⑤","c":"A","tp":"점유권"},{"y":2020,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2020_26-28-1","t":"구 임야소유권이전등기에관한특별조치법에 따라 경료된 소유권보존등기는 그 등기명의자가 임야대장의 명의변경을 함에 있어 첨부한 원인증서인 위 특별조치법 소정의 보증서와 확인서가 허위임이 입증되었다면 그 추정력은 깨어진다.","ox":"O","m":"①","c":"A","tp":"등기의 추정력"},{"y":2020,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2020_26-28-2","t":"소유권이전등기의 원인으로 주장된 계약서가 진정하지 않은 것으로 증명되었다면 그 소유권이전등기의 적법추정은 깨어진다.","ox":"O","m":"②","c":"A","tp":"등기의 추정력"},{"y":2020,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2020_26-28-3","t":"신축된 건물의 소유권은 이를 건축한 사람이 원시취득하는 것이므로, 건물 소유권보존등기의 명의자가 이를 신축한 것이 아니라면 그 등기의 권리 추정력은 깨어지고, 등기 명의자가 스스로 적법하게 그 소유권을 취득한 사실을 입증하여야 한다.","ox":"O","m":"③","c":"A","tp":"등기의 추정력"},{"y":2020,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2020_26-28-4","t":"등기공무원이 관할지방법원의 명령에 의하여 소유권이전등기를 직권으로 말소하였으나 그 후 위 명령이 취소확정된 경우에는 위 말소등기는 결국 원인없이 경료된 등기와 같이 되어 말소된 소유권이전등기는 회복되어야 하고, 회복등기를 마치기 전이라도 등기명의인으로서의 권리를 그대로 보유하고 있다고 할 것이므로 그는 말소된 소유권이전등기의 최종명의인으로서 적법한 권리자로 추정된다.","ox":"O","m":"④","c":"A","tp":"등기의 추정력"},{"y":2020,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2020_26-28-5","t":"전 등기명의인이 미성년자이고 당해 부동산을 친권자에게 증여하는 행위가 이해상반행위라면 친권자에게 마쳐진 소유권이전등기에 관하여 필요한 절차를 적법하게 거친 것으로 추정되지 않는다.","ox":"X","m":"⑤","c":"A","tp":"등기의 추정력"},{"y":2020,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2020_26-32-1","t":"공유물분할의 소송절차 또는 조정절차에서 공유자 사이에 공유토지에 관한 현물분할의 협의가 성립하여 그 합의사항을 조서에 기재함으로써 조정이 성립하였다면, 재판에 의한 공유물분할의 경우와 마찬가지로 그 즉시 공유관계가 소멸하고 각 공유자에게 그 협의에 따른 새로운 법률관계가 창설된다.","ox":"X","m":"①","c":"A","tp":"물권변동"},{"y":2020,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2020_26-32-2","t":"건물신축도급계약에 있어서는 수급인이 자기의 노력과 재료를 들여 건물을 완성하더라도 도급인과 수급인 사이에 도급인 명의로 건축허가를 받아 소유권보존등기를 하기로 하는 등 완성된 건물의 소유권을 도급인에게 귀속시키기로 합의한 경우에는 그 건물의 소유권은 도급인에게 원시적으로 귀속된다.","ox":"O","m":"②","c":"A","tp":"물권변동"},{"y":2020,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2020_26-32-3","t":"유언으로 재단법인을 설립하는 경우 재단법인이 출연재산인 부동산에 관하여 소유권이전등기를 마치지 아니하였다면 유언자의 상속인의 한 사람으로부터 부동산의 지분을 취득하여 이전등기를 마친 선의의 제3자에 대하여 대항할 수 없다.","ox":"O","m":"③","c":"A","tp":"물권변동"},{"y":2020,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2020_26-32-4","t":"신축건물의 보존등기를 건물 완성 전에 하였더라도 그 후 건물이 완성되었다면 그 등기는 유효하다.","ox":"O","m":"④","c":"A","tp":"물권변동"},{"y":2020,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2020_26-32-5","t":"채무자 이외의 자의 소유에 속하는 동산을 경매한 경우에도 경매절차에서 그 동산을 경락받아 경락대금을 납부하고 이를 인도받은 경락인은 특별한 사정이 없는 한 소유권을 선의취득 한다.","ox":"O","m":"⑤","c":"A","tp":"물권변동"},{"y":2021,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2021_27-09-1","t":"등기는 물권의 효력발생 요건이고 존속요건은 아니므로 물권에 관한 등기가 원인 없이 말소된 경우에는 그 물권의 효력에 아무런 변동이 없다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2021_27-09-2","t":"근저당권 설정 후 부동산 소유권이 제3자에게 이전된 경우 근저당권을 설정한 종전의 소유자는 근저당권자에게 피담보채무의 소멸을 이유로 하여 그 근저당권설정등기의 말소를 청구할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2021_27-09-3","t":"가등기는 그 성질상 본등기의 순위보전의 효력만이 있고 후일 본등기가 마쳐지면 본등기의 순위가 가등기한 때로 소급함으로써 가등기 후 본등기 전에 이루어진 중간처분이 본등기보다 후순위로 되어 실효될 뿐이고 본등기에 의한 물권변동의 효력이 가등기한 때로 소급하여 발생하는 것은 아니다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2021_27-09-4","t":"가등기에 기하여 본등기가 마쳐진 경우 가등기의 원인인 법률행위와 본등기의 원인인 법률행위가 명백히 다른 것이 아니면 사해행위 요건의 구비 여부는 가등기의 원인된 법률 행위 당시를 기준으로 판단하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2021_27-09-5","t":"매수인 甲이 매도인 乙에 대한 소유권이전등기청구권을 丙에게 양도한 경우 甲이 乙에게 이러한 사실을 통지하였다면 丙은 乙에 대하여 대항력을 취득한다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2021_27-40-1","t":"민법 제187조에 따라 ‘판결’에 의한 부동산에 관한 물권의 취득은 등기를 요하지 아니하는 바, ‘피고는 원고에게 X토지에 관하여 2015. 4. 2. 매매를 원인으로 한 소유권이전등기절차를 이행하라.’는 판결이 확정되었다면, 원고는 X토지에 관하여 소유권이전등기를 마치지 않고도 소유권을 취득한다.","ox":"X","m":"①","c":"A","tp":"부동산등기"},{"y":2021,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2021_27-40-2","t":"甲 소유의 토지에 관하여 乙이 서류를 위조하여 자신의 이름으로 소유권이전등기를 마치고 이를 丙에게 매도한 경우 丙이 乙의 소유권등기를 진실한 것으로 믿었고 믿은데에 과실이 없었다면 丙은 乙로부터 소유권이전등기를 마침으로써 소유권을 취득한다.","ox":"X","m":"②","c":"A","tp":"부동산등기"},{"y":2021,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2021_27-40-3","t":"선행보존등기로부터 경료된 원고 명의의 소유권이전등기가 원인무효의 등기인 이상 특단의 사정이 없는 한 원고로서는 피고 명의의 후행보존등기에 대하여 그 말소를 청구할 권원이 없다고 할 것이므로, 아무리 후행보존등기가 무효라고 하여도 아무런 권원이 없는 원고의 말소등기청구를 받아들여 그 말소를 명할 수는 없다.","ox":"O","m":"③","c":"A","tp":"부동산등기"},{"y":2021,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2021_27-40-4","t":"무효인 소유권이전등기에 터 잡아 가압류등기를 마친 채권자가 존재하는 경우 진정한 소유자는 소유명의인에 대하여 소유권이전등기의 말소등기절차만을 구하면 족하고, 그 소유권이전등기를 말소하기 위하여 가압류 채권자에 대한 승낙의 의사표시를 구할 필요는 없다.","ox":"X","m":"④","c":"A","tp":"부동산등기"},{"y":2021,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2021_27-40-5","t":"공유물분할의 소에서 공유부동산의 특정한 일부씩을 각각의 공유자에게 귀속시키는 것으로 현물분할하는 내용의 조정이 성립하였다면, 그 조정조서는 공유물분할판결과 동일한 효력을 가지는 것으로서 민법 제187조 소정의 ‘판결’에 해당하는 것이므로 조정이 성립한 때 물권변동의 효력이 발생한다.","ox":"X","m":"⑤","c":"A","tp":"부동산등기"},{"y":2022,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2022_28-08-1","t":"부동산에 관하여 소유권이전등기가 마쳐져 있는 경우에는 그 등기명의자는 제3자에 대하여뿐 아니라 그 전소유자에 대하여서도 적법한 등기원인에 의하여 소유권을 취득한 것으로 추정되는 것이므로 이를 다투는 측에서 그 무효사유를 주장·입증하여야 한다.","ox":"O","m":"①","c":"A","tp":"등기의 추정력"},{"y":2022,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2022_28-08-2","t":"등기명의자가 전소유자로부터 부동산을 취득함에 있어 등기기록상 기재된 등기원인에 의하지 아니하고 다른 원인으로 적법하게 취득하였다고 하면서 등기원인행위의 태양이나 과정을 다소 다르게 주장한다면, 그 등기의 추정력은 깨어진다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2022_28-08-3","t":"소유권보존등기의 추정력은 그 보존등기 명의인 이외의 자가 당해 토지를 사정받은 것으로 밝혀지면 깨어지는 것이어서, 등기명의인이 그 구체적인 승계취득 사실을 주장·입증하지 못하는 한 그 등기는 원인무효로 된다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2022_28-08-4","t":"등기는 물권의 효력 발생 요건이고 존속 요건은 아니어서 등기가 원인 없이 말소된 경우에는 그 물권의 효력에 아무런 영향이 없고, 그 회복등기가 마쳐지기 전이라도 말소된 등기의 등기명의인은 적법한 권리자로 추정되므로 원인 없이 말소된 등기의 효력을 다투는 쪽에서 그 무효 사유를 주장·입증하여야 한다.","ox":"O","m":"④","c":"A","tp":"등기의 추정력"},{"y":2022,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2022_28-08-5","t":"부동산등기부에 소유권이전등기를 하면 그 절차와 원인이 정당한 것이라고 추정되고 절차와 원인이 부당하다고 주장하는 당사자에게 이를 증명할 책임이 있다. 그러나 등기 절차나 원인이 부당한 것으로 볼 만한 의심스러운 사정이 있음이 증명되면 그 추정력은 깨어진다.","ox":"O","m":"⑤","c":"A","tp":"등기의 추정력"},{"y":2022,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2022_28-37-1","t":"부동산 명의신탁자가 명의신탁약정을 해지한 다음 제3자에게 ‘명의신탁 해지를 원인으로 한 소유권이전등기청구권’을 양도하였으나 명의수탁자가 양도에 대하여 동의하거나 승낙하지 않은 경우, 양수인은 명의수탁자에 대하여 직접 소유권이전등기청구를 할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2022_28-37-2","t":"최초 매도인과 중간 매수인, 중간 매수인과 최종 매수인 사이에 순차로 매매계약이 체결되고 이들 간에 중간생략등기의 합의가 있은 후에 최초 매도인과 중간 매수인 간에 매매대금을 인상하는 약정이 체결된 경우, 최초 매도인은 인상된 매매대금이 지급되지 않았음을 이유로 최종 매수인 명의로의 소유권이전등기의무의 이행을 거절할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2022_28-37-3","t":"이미 자기 앞으로 소유권을 표상하는 등기가 되어 있었거나 법률에 의하여 소유권을 취득한 자가 진정한 등기명의를 회복하기 위한 방법으로는 현재의 등기명의인을 상대로 그 등기의 말소를 구하는 외에 “진정한 등기명의의 회복”을 원인으로 한 소유권이전등기절차의 이행을 직접 구하는 것도 허용된다. 이때 현재의 등기명의인을 상대로 하여야 하고 현재의 등기명의인이 아닌 자는 피고적격이 없다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2022_28-37-4","t":"미등기건물을 등기할 때에는 소유권을 원시취득한 자 앞으로 소유권보존등기를 한 다음 이를 양수한 자 앞으로 이전등기를 함이 원칙이라 할 것이나, 원시취득자와 승계취득자 사이의 합치된 의사에 따라 미등기건물에 관하여 승계취득자 앞으로 직접 소유권보존등기를 경료하게 되었다면, 그 소유권보존등기는 실체적 권리관계에 부합되어 적법한 등기로서의 효력을 가진다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2022_28-37-5","t":"부동산의 매매예약에 기하여 소유권이전등기청구권의 보전을 위한 가등기가 마쳐진 경우에 그 매매예약완결권이 소멸하였다면 그 가등기 또한 효력을 상실하여 말소되어야 할 것이나, 그 부동산의 소유자가 제3자와 사이에 새로운 매매예약을 체결하고 그에 기한 소유권이전등기청구권의 보전을 위하여 이미 효력이 상실된 가등기를 유용하기로 합의하고 실제로 그 가등기 이전의 부기등기를 마쳤다면, 그 가등기 이전의 부기등기를 마친 제3자로서는 언제든지 부동산의 소유자에 대하여 위 가등기 유용의 합의를 주장하여 가등기의 말소청구에 대항할 수 있고, 다만 그 가등기 이전의 부기등기 전에 등기부상 이해관계를 가지게 된 자에 대하여는 위 가등기 유용의 합의 사실을 들어 그 가등기의 유효를 주장할 수는 없다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2023_29-03-1","t":"특별한 사정이 없는 한 소유의 의사 유무는 점유개시시를 기준으로 판단하며, 나중에 매도자에게 처분권이 없었다는 등의 사유로 그 매매가 무효인 것이 밝혀지더라도 원칙적으로 점유의 성질은 변하지 않는다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2023_29-03-2","t":"점유자의 점유가 소유의 의사 있는 자주점유인지 아니면 소유의 의사 없는 타주점유인지의 여부는 점유자의 내심의 의사에 의하여 결정되는 것이 아니라 점유 취득의 원인이 된 권원의 성질이나 점유와 관계가 있는 모든 사정에 의하여 외형적·객관적으로 결정된다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2023_29-03-3","t":"점유란 물건이 사회통념상 그 사람의 사실적 지배에 속한다고 보이는 객관적 관계에 있는 것을 말하고 사실상의 지배가 있다고 하기 위해서는 반드시 물건을 물리적·현실적으로 지배하는 것만을 의미하는 것이 아니고 물건과 사람과의 시간적·공간적 관계와 본권관계, 타인지배의 배제가능성 등을 고려하여 사회관념에 따라 합목적적으로 판단하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2023_29-03-4","t":"점유자가 스스로 매매 또는 증여와 같이 자주점유의 권원을 주장하였으나 이것이 인정되지 않는 경우에는 점유권원의 성질상 타주점유라고 볼 수 있다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2023_29-03-5","t":"선대의 점유가 타주점유인 경우 선대로부터 상속에 의하여 점유를 승계한 자의 점유도 특단의 사정이 없는 한 자주점유로는 될 수 없고, 그 점유가 자주점유가 되기 위해서는 점유자가 소유자에 대하여 소유의 의사가 있는 것을 표시하거나 새로운 권원에 의하여 다시 소유의 의사로써 점유를 시작하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2023_29-08-1","t":"동일인 명의로 보존등기가 중복된 경우에 언제나 후(後)등기기록이 무효이다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2023_29-08-2","t":"자기 앞으로 소유권의 등기가 되어 있지 않았고 법률에 의하여 소유권을 취득하지도 않은 사람이 소유권자를 대위하여 현재의 등기명의인을 상대로 그 등기의 말소를 청구할 수 있을 뿐인 경우에는 진정한 등기명의의 회복을 위한 소유권이전등기청구를 할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2023_29-08-3","t":"멸실된 건물의 보존등기를 신축한 건물의 보존등기로 유용하는 것은 허용되지 않는다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2023_29-08-4","t":"멸실회복등기에 있어 전 등기의 접수연월일, 접수번호 및 원인일자가 각 불명이라고 기재되었다 하여도 별다른 사정이 없는 한 등기관에 의하여 적법하게 수리되고 처리된 것이라고 추정된다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2023_29-08-5","t":"근저당설정등기가 불법말소된 경우 그 회복등기를 구하는 본안소송에서 승소판결을 받으면 후순위 근저당권자가 있더라도 바로 회복등기를 할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2023_29-35-1","t":"소유자가 제3자에 대하여 목적물의 소유권을 이전하기로 하는 매매·증여·교환 기타의 채권계약을 체결하는 것만에 의하여서는 자신의 소유권에 어떠한 물권적 제한을 받지 아니하여서, 그는 다른 특별한 사정이 없는 한 자신의 소유물을 여전히 유효하게 달리 처분할 수 있고, 또한 소유권에 기하여 소유물에 대한 방해 등을 배제할 수 있는 민법 제213조, 제214조의 물권적 청구권을 가진다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2023_29-35-2","t":"자신의 토지에 폐기물을 매립하거나 토양을 오염시켜 토지를 유통시킨 경우는 물론 타인의 토지에 그러한 행위를 하여 토지가 유통된 경우라 하더라도, 행위자가 폐기물을 매립한 자 또는 토양오염을 유발시킨 자라는 이유만으로 자신과 직접적인 거래관계가 없는 토지의 전전 매수인에 대한 관계에서 폐기물 처리비용이나 오염정화비용 상당의 손해에 관한 불법행위책임을 부담한다고 볼 수는 없다.","ox":"X","m":"②","c":"A","tp":"물권적 청구권"},{"y":2023,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2023_29-35-3","t":"소유자가 자신의 소유권에 기하여 실체관계에 부합하지 아니하는 등기의 명의인을 상대로 그 등기말소나 진정명의회복 등을 청구하는 경우에, 그 권리는 물권적 청구권으로서의 방해배제청구권(민법 제214조)의 성질을 가진다. 그러므로 소유자가 그 후에 소유권을 상실하면 이제 그 발생의 기반이 아예 없게 되어 더 이상 그 존재 자체가 인정되지 아니하므로, 등기말소 등 의무자에 대하여 그 권리의 이행불능을 이유로 민법 제390조의 손해배상청구권을 가진다고 말할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2023_29-35-4","t":"토지소유권에 기한 물권적 청구권을 원인으로 하는 토지인도소송의 소송물은 토지소유권이 아니라 그 물권적 청구권인 토지인도청구권이므로, 그 소송에서 청구기각된 확정판결의 기판력은 토지인도청구권의 존부 그 자체에만 미치는 것이고 소송물이 되지 아니한 토지소유권의 존부에 관하여는 미치지 않는다. 그러므로 그 토지인도소송의 사실심변론종결 후에 그 패소자인 토지소유자로부터 토지를 매수하고 소유권이전등기를 마침으로써 그 소유권을 승계한 제3자의 토지소유권의 존부에 관하여는 위 확정판결의 기판력이 미치지 않는다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2023_29-35-5","t":"상속인은 피상속인의 일신에 전속한 것이 아닌 한 상속이 개시된 때로부터 피상속인의 재산에 관한 포괄적 권리·의무를 승계하므로(민법 제1005조), 피상속인이 사망 전에 그 소유 토지를 일반 공중의 이용에 제공하여 독점적·배타적인 사용·수익권을 포기한 것으로 볼 수 있고 그 토지가 상속재산에 해당하는 경우에는, 피상속인의 사망 후 그 토지에 대한 상속인의 독점적·배타적인 사용·수익권의 행사 역시 제한된다고 보아야 한다.","ox":"O","m":"⑤","c":"A","tp":"물권적 청구권"},{"y":2023,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2023_29-37-1","t":"부동산의 진정한 소유자가 원인무효등기의 말소를 청구하는 것은 소유권 그 자체에 터잡아서 방해의 배제나 소유물의 반환을 청구하는 것으로서 소유권이 있는 한 항상 행사할 수 있는 것이므로, 그 소유권을 취득하게 된 원인이 상속이고 그 상대방이 상속인을 참칭하여 등기를 한 사람이라고 하더라도 상속회복의 소라는 이름을 붙이고 그 권리의 행사를 제한하여야 할 이유가 없어, 이러한 경우 상속회복청구에 관한 민법규정은 적용되지 않는다.","ox":"X","m":"①","c":"A","tp":"말소등기청구"},{"y":2023,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2023_29-37-2","t":"피고로부터 매매 등의 방법으로 부동산에 대한 권리가 순차적으로 이전되어 최종적으로 소유권이전등기를 마친 제3자가 시효취득을 원인으로 부동산에 대한 소유권을 취득함에 따라 당초 부동산의 소유자인 원고가 소유권을 상실하게 되면, 비록 피고 명의의 소유권이전등기가 원인무효라고 하더라도 원고에게 피고 명의의 소유권이전등기의 말소를 청구할 수 있는 권원이 없으므로, 원고는 피고에 대하여 소유권에 기한 등기말소청구를 할 수 없다.","ox":"O","m":"②","c":"A","tp":"말소등기청구"},{"y":2023,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2023_29-37-3","t":"1필지의 토지의 특정된 일부에 대하여 소유권이전등기의 말소를 명하는 판결을 받은 등기권자는 그 판결에 따로 토지의 분할을 명하는 주문기재가 없더라도 그 판결에 기하여 등기의무자를 대위하여 그 특정된 일부에 대한 분필등기절차를 마친 후 소유권이전등기를 말소할 수 있으므로, 토지의 분할을 명함이 없이 1필지의 토지의 일부에 관하여 소유권이전등기의 말소를 명한 판결을 집행불능의 판결이라 할 수 없다.","ox":"O","m":"③","c":"A","tp":"말소등기청구"},{"y":2023,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2023_29-37-4","t":"채무자와 수익자 사이의 소송절차에서 확정판결 등을 통해 마쳐진 소유권이전등기가 사해행위취소로 인한 원상회복으로써 말소된다고 하더라도, 그것이 확정판결 등의 효력에 반하거나 모순되는 것이라고는 할 수 없다.","ox":"O","m":"④","c":"A","tp":"말소등기청구"},{"y":2023,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2023_29-37-5","t":"실체관계상 공유인 부동산에 관하여 단독소유로 소유권보존등기가 마쳐졌거나 단독소유인 부동산에 관하여 공유로 소유권보존등기가 마쳐진 경우에 소유권보존등기 중 진정한 권리자의 소유부분에 해당하는 일부 지분에 관한 등기명의인의 소유권보존등기는 무효이므로 이를 말소하고 그 부분에 관한 진정한 권리자의 소유권보존등기를 하여야 한다. 이 경우 진정한 권리자는 소유권보존등기의 일부말소를 소로써 구하고 법원은 그 지분에 한하여만 말소를 명할 수 있으나, 그 판결의 집행은 단독소유를 공유로 또는 공유를 단독소유로 하는 경정등기의 방식으로 이루어진다.","ox":"O","m":"⑤","c":"A","tp":"말소등기청구"},{"y":2024,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2024_30-18-1","t":"토지의 매수인이 아직 소유권이전등기를 경료받지 아니하였다 하여도 매매계약의 이행으로 그 토지를 인도받은 때에는 매매계약의 효력으로서 이를 점유·사용할 권리가 생기게 된 것으로 보아야 하고, 또 매수인으로부터 위 토지를 다시 매수한 자는 위와 같은 토지의 점유사용권을 취득한 것으로 봄이 상당하므로 매도인은 매수인으로부터 다시 위 토지를 매수한 자에 대하여 토지 소유권에 기한 물권적 청구권을 행사하거나 그 점유·사용을 법률상 원인이 없는 이익이라고 하여 부당이득반환청구를 할 수는 없다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2024_30-18-2","t":"소유권을 양도함에 있어 소유권에 의하여 발생되는 물상청구권을 소유권과 분리, 소유권 없는 전소유자에게 유보하여 제3자에게 대하여 이를 행사케 한다는 것은 소유권의 절대적 권리인 점에 비추어 허용될 수 없는 것이라 할 것으로서, 이는 양도인인 전소유자가 그 목적물을 양수인에게 인도할 의무있고 그 의무이행이 매매대금 잔액의 지급과 동시이행관계에 있다거나 그 소유권의 양도가 소송계속중에 있었다 하여 다를 리 없고, 일단 소유권을 상실한 전소유자는 제3자인 불법점유자에 대하여 물권적청구권에 의한 방해배제를 청구할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2024_30-18-3","t":"부동산의 양도담보권설정자는 그 부동산의 등기명의가 양도담보권자 앞으로 되어있다 할지라도 그 부동산의 불법점유자인 제3자에 대하여는 그 실질적 소유자임을 주장하여 불법점유의 상태의 배제권을 행사할 수 있다.","ox":"O","m":"③","c":"A","tp":"물권적 청구권"},{"y":2024,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2024_30-18-4","t":"건물이 그 존립을 위한 토지사용권을 갖추지 못하여 토지의 소유자가 건물의 소유자에 대하여 당해 건물의 철거 및 그 대지의 인도를 청구할 수 있는 경우에 건물소유자가 아닌 사람이 건물을 점유하고 있다면 토지소유자는 자신의 소유권에 기한 방해배제로서 건물점유자에 대하여 건물로부터의 퇴거를 청구할 수 있다. 다만 그 건물점유자가 건물소유자로부터의 임차인으로서 그 건물임차권이 이른바 대항력을 가지고 있다면 위 퇴거청구에 대항할 수 있게 된다.","ox":"X","m":"④","c":"A","tp":"물권적 청구권"},{"y":2024,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2024_30-18-5","t":"말소등기에 갈음하여 허용되는 진정명의회복을 원인으로 한 소유권이전등기청구권과 무효등기의 말소청구권은 어느 것이나 진정한 소유자의 등기명의를 회복하기 위한 것으로서 실질적으로 그 목적이 동일하고, 두 청구권 모두 소유권에 기한 방해배제청구권으로서 그 법적 근거와 성질이 동일하다.","ox":"O","m":"⑤","c":"A","tp":"물권적 청구권"},{"y":2025,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2025_31-33-1","t":"점유자가 점유물을 보존하거나 개량하기 위하여 지출한 필요비나 유익비에 관하여 민법 제203조 제1항, 제2항은 점유자가 ‘점유물을 반환할 때’에 상환을 청구할 수 있도록 규정하고 있으므로, 그 상환청구권은 점유자가 회복자로부터 점유물 반환을 청구받거나 회복자에게 점유물을 반환한 때에 비로소 발생하여 점유자가 이를 행사할 수 있는 상태가 되고 이행기가 도래한다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2025_31-33-2","t":"민법 제203조는 정당한 법률관계가 없는 물건 점유자와 회복자 사이에서 점유물을 반환하는 경우 점유자가 지출한 필요비 또는 유익비의 상환청구 범위와 상환시기에 관하여 규정한 특별규정이다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2025_31-33-3","t":"민법 제758조 제1항 소정의 공작물 점유자란 공작물을 사실상 지배하면서 그 설치 또는 보존상의 하자로 인하여 발생할 수 있는 각종 사고를 방지하기 위하여 공작물을 보수·관리할 권한 및 책임이 있는 자를 말한다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2025_31-33-4","t":"물건에 대한 점유란 사회관념상 어떤 사람의 사실적 지배에 있다고 보이는 객관적 관계를 말하는 것으로서, 사실상의 지배가 있다고 하기 위하여는 반드시 물건을 물리적, 현실적으로 지배하여야만 하는 것이 아니고, 물건과 사람 사이의 시간적, 공간적 관계와 본권관계, 타인지배의 배제 가능성 등을 고려하여 사회통념에 따라 합목적적으로 판단하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2025_31-33-5","t":"물건의 소유자가 적법한 점유 권원 없는 점유자를 상대로 민법 제213조에 따른 물권적 청구권을 행사하여 물건의 반환을 구할 수 있는 경우, 점유자는 물건의 소유자를 상대로 민법 제741조에 따라 해당 비용의 반환을 구할 수 있다.","ox":"X","m":"⑤","c":"A"}],"10":[{"y":2016,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2016_22-16-1","t":"사무관리가 성립하기 위하여는 타인을 위하여 사무를 처리하는 의사, 즉 관리의 사실상의 이익을 타인에게 귀속시키려는 의사가 있어야 하는데, 여기에서 ‘타인을 위하여 사무를 처리하는 의사’는 관리자 자신의 이익을 위한 의사와 병존할 수 있고, 반드시 외부적으로 표시될 필요가 없으며, 사무를 관리할 당시에 확정되어 있을 필요도 없다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2016_22-16-2","t":"제3자와의 약정에 따라 타인의 사무를 처리한 경우에는 의무 없이 타인의 사무를 처리한 것이 아니므로 원칙적으로 그 타인과의 관계에서는 사무관리가 된다고 볼 수 없다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2016_22-16-3","t":"관리자가 사무관리를 함에 있어서 과실 없이 손해를 받은 때에는 본인의 현존이익의 한도에서 그 손해의 보상을 청구할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2016_22-16-4","t":"관리자가 타인의 생명, 신체, 명예 또는 재산에 대한 급박한 위해를 면하게 하기 위하여 그 사무를 관리한 때에는 고의가 없는 경우에 한하여 그로 인한 손해를 배상할 책임이 없다.","ox":"X","m":"④","c":"A","tp":"사무관리"},{"y":2016,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2016_22-16-5","t":"사무관리라 함은 의무 없이 타인을 위하여 그의 사무를 처리하는 행위를 말하는 것이므로, 만약 그 사무가 타인의 사무가 아니라거나 또는 사무를 처리한 자에게 타인을 위하여 처리한다는 관리의사가 없는 경우에는 사무관리가 성립할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2016_22-31-1","t":"수익자가 법률상 원인 없이 이득한 재산을 처분함으로 인하여 원물반환이 불가능한 경우에 반환하여야 할 가액을 산정할 때에는 법률상 원인 없는 이득을 얻기 위하여 지출한 비용을 공제하여야 하므로, 무권리자가 타인 소유의 부동산을 제3자에게 처분하였다가 선의의 제3자 보호규정에 의하여 부동산을 반환하지 못하고 처분의 대가로 수령한 매각대금을 반환하여야 하는 경우, 자신의 처분행위로 인하여 발생한 양도소득세 기타 비용은 반환하여야 할 이득에서 공제할 수 있다.","ox":"X","m":"①","c":"A","tp":"부당이득 반환범위"},{"y":2016,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2016_22-31-2","t":"법률상 원인 없이 타인의 재산 또는 노무로 인하여 이익을 얻고 그로 인하여 타인에게 손해를 가한 경우, 그 취득한 것이 금전상의 이득인 때에는 그 금전은 이를 취득한 자가 소비하였는가의 여부를 불문하고 현존하는 것으로 추정된다.","ox":"O","m":"②","c":"A","tp":"부당이득 반환범위"},{"y":2016,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2016_22-31-3","t":"쌍무계약이 취소된 경우, 선의의 매수인에게 선의의 점유자의 과실수취권에 관한 민법 제201조가 적용되어 과실취득권이 인정되는 이상 선의의 매도인에게도 인도하지 아니한 목적물로부터 생긴 과실수취권에 관한 민법 제587조를 유추적용하여 대금의 운용이익 내지 법정이자의 반환을 부정함이 형평에 맞다.","ox":"O","m":"③","c":"A","tp":"부당이득 반환범위"},{"y":2016,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2016_22-31-4","t":"부당이득반환의무자가 악의의 수익자라는 점에 대하여는 이를 주장하는 측에서 입증책임을 진다. 또한 여기서 ‘악의’라고 함은, 민법 제749조 제2항에서 악의로 의제되는 경우 등은 별론으로 하고, 자신의 이익 보유가 법률상 원인 없는 것임을 인식하는 것을 말하고, 그 이익의 보유를 법률상 원인이 없는 것이 되도록 하는 사정, 즉 부당이득반환의무의 발생요건에 해당하는 사실이 있음을 인식하는 것만으로는 부족하다.","ox":"O","m":"④","c":"A","tp":"부당이득 반환범위"},{"y":2016,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2016_22-31-5","t":"채무자의 부동산에 관한 매매계약 등의 유상행위가 사해행위라는 이유로 취소되고 그 원상회복이 이루어짐으로써 수익자에 대하여 부당이득반환채무를 부담하게 된 채무자가 그 부당이득반환채무의 변제를 위하여 수익자와 소비대차계약을 체결하고 강제집행을 승낙하는 취지가 기재된 공정증서를 작성하여 준 경우, 그와 같은 행위로 인해 자신의 책임재산을 그 수익자에게 실질적으로 양도한 것과 다를 바 없는 것으로 볼 수 있는 특별한 사정이 있는 경우에 해당하지 않는 한, 다른 채권자를 해하는 새로운 사해행위가 된다고 볼 수 없다.","ox":"O","m":"⑤","c":"A","tp":"부당이득 반환범위"},{"y":2017,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2017_23-30-1","t":"부동산 실권리자명의 등기에 관한 법률 시행 후에 ‘계약명의신탁’이 이루어진 경우, 명의수탁자 甲이 명의신탁자 乙에게 반환하여야 할 부당이득의 대상은 당해 부동산 자체이다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2017_23-30-2","t":"甲 회사의 화물차량 운전자가 甲 회사 소유의 화물차량을 운전하면서 甲 회사의 지정주유소가 아닌 乙이 경영하는 주유소에서 대금을 지급할 의사나 능력이 없음에도 불구하고 상당량의 유류를 공급받아 편취한 다음 甲 회사의 화물운송사업에 사용하고 그 유류대금을 변제하지 않은 경우, 乙은 甲 회사에 대하여 부당이득 반환을 청구할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2017_23-30-3","t":"X 토지를 시효취득한 甲에게로 소유권이전등기가 있기 전에 원소유자 乙이 X 토지에 설정한 근저당권의 피담보채무를 甲이 변제한 경우, 乙에게 변제액 상당의 부당이득반환청구를 할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2017_23-30-4","t":"甲이 乙로부터 횡령한 금전을 그대로 丙에 대한 채무변제에 사용한 경우 丙이 그 변제를 수령함에 있어 악의 또는 중대한 과실이 있는 경우에는 丙의 금전 취득은 乙에 대한 관계에 있어서 법률상 원인을 결여한 것으로 봄이 상당하다.","ox":"O","m":"④","c":"A","tp":"부당이득"},{"y":2017,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2017_23-30-5","t":"甲과 乙 사이에 상계계약이 체결된 경우, 甲의 채권이 불성립되어 乙의 채무면제가 무효가 되었음에도 甲이 乙에 대한 채무를 이행하지 않고 있는 것은 법률상 원인 없이 이득을 얻은 것이 된다.","ox":"X","m":"⑤","c":"A","tp":"부당이득"},{"y":2017,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2017_23-33-1","t":"공동불법행위자 1인에 대한 이행의 청구는 다른 공동불법행위자에 대하여 시효중단의 효력이 있다.","ox":"X","m":"①","c":"A","tp":"불법행위책임"},{"y":2017,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2017_23-33-2","t":"공동불법행위자 중 1인의 손해배상채무가 시효로 소멸한 후에 다른 공동불법행위자 1인이 피해자에게 자기의 부담부분을 넘는 손해를 배상하였을 경우, 그 공동불법행위자는 다른 공동불법행위자에게 구상권을 행사할 수 있다.","ox":"O","m":"②","c":"A","tp":"불법행위책임"},{"y":2017,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2017_23-33-3","t":"손해발생으로 인하여 피해자에게 이득이 생기고 한편 그 손해발생에 피해자의 과실이 경합하는 경우, 그 손해배상액을 산정할 때에는 손익상계를 한 다음 과실상계를 하여야 한다.","ox":"X","m":"③","c":"A","tp":"불법행위책임"},{"y":2017,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2017_23-33-4","t":"공동불법행위자 중 1인에 대하여 구상의무를 부담하는 다른 공동불법행위자가 수인인 경우에는 특별한 사정이 없는 이상 그들의 구상권자에 대한 채무는 각자의 부담부분에 따른 분할채무가 되고, 이는 구상권자인 공동불법행위자 측에 과실이 없는 경우에도 마찬가지이다.","ox":"X","m":"④","c":"A","tp":"불법행위책임"},{"y":2017,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2017_23-33-5","t":"타인의 불법행위로 인하여 사망한 자를 매장하기 위하여 묘지를 구입한 경우, 그 묘지구입비는 손해배상의 대상이 되는 장례비에 포함되지 않는다.","ox":"X","m":"⑤","c":"A","tp":"불법행위책임"},{"y":2018,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2018_24-05-1","t":"민법 제758조에 따라 공작물 설치 또는 보존의 하자로 인하여 타인에게 가한 손해를 배상할 책임은 1차적으로 공작물 점유자에게 있다. 공작물 점유자가 손해의 방지에 필요한 주의를 해태하지 아니하였음을 입증함으로써 면책될 때에 2차적으로 공작물 소유자가 손해를 배상할 책임을 지게 된다.","ox":"O","m":"①","c":"A","tp":"공작물 등의 점유자, 소유자 책임"},{"y":2018,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2018_24-05-2","t":"공작물 설치·보존상 하자로 인한 사고는 공작물 설치·보존상 하자만 손해발생 원인이 되는 경우만을 말하는 것이 아니다. 공작물의 설치·보존상 하자가 사고의 공동원인 중 하나가 되는 이상 사고로 인한 손해는 공작물의 설치·보존상 하자로 생긴 것이라고 보아야 한다. 그리고 화재가 공작물 설치 또는 보존상 하자가 아닌 다른 원인으로 발생하였거나 화재 발생원인이 밝혀지지 않은 경우에도, 공작물 설치 또는 보존상 하자로 인하여 화재가 확산되어 손해가 발생하였다면 공작물 설치 또는 보존상 하자는 화재사고의 공동원인의 하나가 되었다고 볼 수 있다.","ox":"O","m":"②","c":"A","tp":"공작물 등의 점유자, 소유자 책임"},{"y":2018,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2018_24-05-3","t":"공작물 설치 또는 보존의 하자는 해당 공작물이 그 용도에 따라 갖추어야 할 안전성을 갖추지 못한 상태에 있다는 것을 의미한다. 여기에서 안전성을 갖추지 못한 상태, 즉 타인에게 위해를 끼칠 위험성이 있는 상태라 함은 해당 공작물을 구성하는 물적 시설 그 자체에 물리적·외형적 결함이 있거나 필요한 물적 시설이 갖추어져 있지 않아 이용자에게 위해를 끼칠 위험성이 있는 경우를 뜻할 뿐, 그 공작물을 본래의 목적 등으로 이용하는 과정에서 일정한 한도를 초과하여 제3자에게 사회통념상 일반적으로 참아내야 할 정도를 넘는 피해를 입히는 경우까지 포함하는 것은 아니다.","ox":"X","m":"③","c":"A","tp":"공작물 등의 점유자, 소유자 책임"},{"y":2018,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2018_24-05-4","t":"민법 제758조는 공작물 설치·보존의 하자로 인하여 타인에게 손해를 가한 경우 그 점유자 또는 소유자에게 일반 불법행위와 달리 이른바 위험책임의 법리에 따라 책임을 가중시킨 규정일 뿐이고, 그 공작물 시공자가 그 시공상 고의·과실로 인하여 피해자에게 손해를 가한 경우 민법 제750조에 따라 손해배상책임을 부담하는 것을 배제하는 규정은 아니다.","ox":"O","m":"④","c":"A","tp":"공작물 등의 점유자, 소유자 책임"},{"y":2018,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2018_24-05-5","t":"2009. 5. 8. 법률 제9648호로 전부 개정된 실화책임에 관한 법률은 손해배상액 경감에 관한 특례 규정만을 두었을 뿐 손해배상의무 성립을 제한하는 규정을 두고 있지 않다. 그러므로 공작물 설치·보존상 하자에 의하여 직접 발생한 화재로 인한 손해배상책임뿐만 아니라 그 화재로부터 연소한 부분에 대한 손해배상책임에 관하여도 공작물 설치·보존상 하자와 그 손해 사이에 상당인과관계가 있는 경우에는 민법 제758조 제1항이 적용된다.","ox":"O","m":"⑤","c":"A","tp":"공작물 등의 점유자, 소유자 책임"},{"y":2018,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2018_24-32-1","t":"법인의 사회적 명성, 신용을 훼손하는 행위도 불법행위가 될 수 있다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2018_24-32-2","t":"불법행위에 있어 위법행위 시점과 손해발생 시점 사이에 시간적 간격이 있는 경우에 불법행위로 인한 손해배상청구권의 지연손해금은 손해발생 시점을 기산일로 하여 발생한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2018_24-32-3","t":"민법 제496조는 “채무가 고의의 불법행위로 인한 것인 때에는 그 채무자는 상계로 채권자에게 대항하지 못한다.”라고 정하고 있다. 고의에 의한 행위가 불법행위를 구성함과 동시에 채무불이행을 구성하여 불법행위로 인한 손해배상채권과 채무불이행으로 인한 손해배상채권이 경합하는 경우, 고의의 채무불이행으로 인한 손해배상채권을 수동채권으로 하는 상계를 한 경우에도 채무자가 상계로 채권자에게 대항할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2018_24-32-4","t":"불법행위로 인한 손해배상채무에 대하여는 원칙적으로 별도의 이행 최고가 없더라도 공평의 관념에 비추어 불법행위로 그 채무가 성립함과 동시에 지연손해금이 발생하는 것이 원칙이다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2018_24-32-5","t":"남녀고용평등과 일·가정 양립 지원에 관한 법률(2017. 11. 28. 법률 제15109호로 개정되기 전의 것) 제14조 제2항은 사업주가 직장 내 성희롱과 관련하여 피해를 입은 근로자 또는 성희롱 피해 발생을 주장하는 근로자(이하 ‘피해근로자 등’이라 한다)에게 해고나 그 밖의 불리한 조치를 하여서는 안 된다고 규정하고 있을 뿐이다. 따라서 사업주가 피해근로자 등인 A가 아니라 그에게 도움을 준 동료 근로자 B에게 불리한 조치를 한 경우, 그 불리한 조치의 상대방(B)도 아닌 A가 직접 사업주에게 민법 제750조에 따라 불법행위책임을 물을 수는 없다.","ox":"X","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2019_25-05-1","t":"민법 제749조 제1항(수익자의 악의인정)에서 규정하는 ‘악의’란 자신의 이익 보유가 법률상 원인 없는 것임을 인식하는 것을 말하고, 그 이익의 보유를 법률상 원인이 없는 것이 되도록 하는 사정, 즉 부당이득반환의무의 발생요건에 해당하는 사실이 있음을 인식하는 것만으로는 부족하다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2019_25-05-2","t":"배당요구가 필요한 배당요구채권자가 경락기일까지 배당요구하지 아니한 채권을 경락기일 이후에 추가하여 배당요구를 하였으나 그 부분이 배당에서 제외된 경우, 위 채권자는 배당받은 후순위 채권자를 상대로 부당이득반환을 청구할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2019_25-05-3","t":"어떤 물건에 대하여 직접점유자와 간접점유자가 있는 경우, 그 물건에 대한 점유·사용으로 인한 위 점유자들의 부당이득반환의무 중 서로 중첩되는 부분에 관하여는 부진정연대채무의 관계가 성립한다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2019_25-05-4","t":"유효한 도급계약에 기하여 수급인 甲이 도급인 乙로부터 제3자 丙 소유의 물건을 점유이전 받아 이를 수리한 결과 그 물건의 가치가 증가한 경우, 甲은 丙에 대해 부당이득의 반환을 청구할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2019_25-05-5","t":"계약명의신탁에서 명의수탁자가 수령한 매수자금이 명의신탁약정에 기하여 지급되었다는 사실을 알았다고 하여도 그 명의신탁약정이 부동산 실권리자명의 등기에 관한 법률 제4조 제1항에 의하여 무효임을 알았다는 등의 사정이 부가되지 아니하는 한, 명의수탁자가 위 금전의 보유에 관하여 법률상 원인 없음을 알았다고 단정할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"부당이득"},{"y":2019,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2019_25-27-1","t":"부작위로 인한 불법행위가 성립하려면 작위의무가 전제되어야 하나, 의무자가 작위의무의 존재를 인식하지 못하였더라도 불법행위의 성립에는 영향이 없다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2019_25-27-2","t":"토지의 소유자라 하더라도 토양오염물질을 토양에 누출ㆍ유출하거나 투기ㆍ방치함으로써 토양오염을 유발하였음에도 오염토양을 정화하지 않은 상태에서 그 오염토양이 포함된 토지를 거래에 제공함으로써 유통되게 하거나, 토지에 폐기물을 불법으로 매립하였음에도 이를 처리하지 않은 상태에서 그 해당 토지를 거래에 제공하는 등으로 유통되게 하였다면, 다른 특별한 사정이 없는 한 이는 거래 상대방 및 위 토지를 전전 취득한 현재의 토지 소유자에 대한 위법행위로서 불법행위가 성립할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2019_25-27-3","t":"책임능력이 없는 미성년자가 불법행위를 저지른 경우와 달리 미성년자가 책임능력이 있다고 인정될 경우에는, 설령 그 미성년자의 불법행위로 인해 발생한 손해가 감독의무자의 의무위반과 상당인과관계가 있더라도 감독의무자는 손해배상의무를 지지 않는다.","ox":"X","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2019_25-27-4","t":"택시회사의 운전기사가 택시의 승객을 태우고 운행 중 차속에서 승객을 상대로 성범죄를 저지른 경우, 택시회사는 사용자로서 위 운전기사가 한 행위에 대한 손해배상책임이 있다고 보아야 한다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2019_25-27-5","t":"민법 제751조 제1항은 불법행위로 인한 재산 이외의 손해에 대한 배상책임을 규정하고 있고, 재산 이외의 손해는 정신상 고통만을 의미하는 것이 아니라 그 외에 수량적으로 산정할 수는 없으나 사회통념상 금전평가가 가능한 무형의 손해도 포함하므로, 법인의 명예나 신용을 훼손한 자는 그 법인에게 재산 이외의 손해에 대하여도 배상할 책임이 있다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2020_26-24-1","t":"본인의 의사나 이익에 적합하지 아니한 사무관리를 한 경우에는 과실이 없는 때에도 이로 인한 손해를 배상해야 하나 그 관리행위가 공공의 이익에 적합한 때에는 중대한 과실이 없으면 배상할 책임이 없다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2020_26-24-2","t":"사무관리가 성립하기 위하여는 우선 그 사무가 타인의 사무이고 타인을 위하여 사무를 처리하는 의사, 즉 관리의 사실상의 이익을 타인에게 귀속시키려는 의사가 있어야 하며, 나아가 그 사무의 처리가 본인에게 불리하거나 본인의 의사에 반한다는 것이 명백하지 아니할 것을 요한다. 여기에서 타인을 위하여 사무를 처리하는 의사는 관리자 자신의 이익을 위한 의사와 병존할 수 있고, 반드시 외부적으로 표시될 필요가 없으며, 사무를 관리할 당시에 확정되어 있을 필요가 없다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2020_26-24-3","t":"관리자가 타인의 생명, 신체, 명예 또는 재산에 대한 급박한 위해를 면하게 하기 위하여 그 사무를 관리한 때라 하더라도 경과실로 인하여 본인에게 손해가 발생한 때에는 이를 배상하여야 한다.","ox":"X","m":"③","c":"A","tp":"사무관리"},{"y":2020,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2020_26-24-4","t":"의무 없이 타인을 위하여 사무를 관리한 자는 타인에 대하여 민법상 사무관리 규정에 따라 비용상환 등을 청구할 수 있는 외에 사무관리에 의하여 결과적으로 사실상 이익을 얻은 다른 제3자에 대하여 직접 부당이득반환을 청구할 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2020_26-24-5","t":"의무 없이 타인의 사무를 처리한 자는 그 타인에 대하여 민법상 사무관리 규정에 따라 비용상환 등을 청구할 수 있으나, 제3자와의 약정에 따라 타인의 사무를 처리한 경우에는 의무 없이 타인의 사무를 처리한 것이 아니므로 이는 원칙적으로 그 타인과의 관계에서는 사무관리가 된다고 볼 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2020_26-31-1","t":"약사는 의약품을 조제할 수 있다 하여도 진단행위나 치료행위 등은 할 수 없으므로 의사가 아닌 약사가 환자의 증세에 대하여 문진을 한 후 감기로 진단하고 각종 의약품을 혼합하여 조제하는 등의 행위를 한 일련의 행위는 무면허 의료행위에 해당한다.","ox":"O","m":"①","c":"A","tp":"불법행위"},{"y":2020,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2020_26-31-2","t":"무면허 의료행위를 하였다면 그 자체만으로도 불법행위책임을 부담한다.","ox":"X","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2020_26-31-3","t":"법령에 대한 해석이 복잡, 미묘하여 워낙 어렵고, 이에 대한 학설, 판례조차 귀일되어 있지 않는 등의 특별한 사정이 없는 한 일반적으로 공무원이 관계 법규를 알지 못하거나 필요한 지식을 갖추지 못하고 법규의 해석을 그르쳐 행정처분을 하였다면 그가 법률전문가가 아닌 행정직 공무원이라고 하여 과실이 없다고는 할 수 없다.","ox":"O","m":"③","c":"A","tp":"불법행위"},{"y":2020,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2020_26-31-4","t":"일반적으로 도급인과 수급인 사이에는 지휘·감독의 관계가 없으므로 도급인은 수급인이나 수급인의 피용자의 불법행위에 대하여 사용자로서의 배상책임이 없는 것이지만, 도급인이 수급인에 대하여 특정한 행위를 지휘하거나 특정한 사업을 도급시키는 경우와 같은 이른바 노무도급의 경우에는 비록 도급인이라고 하더라도 사용자로서의 배상책임이 있다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2020_26-31-5","t":"합동법무사사무소의 구성원인 법무사들이 등기사무를 처리함에 있어서 내부 방침에 따라 구성원인 법무사 중 1인이 등기신청 대행 업무를 처리하면서 다른 법무사를 서류상 작성명의인으로 기재한 경우, 서류상 작성명의인인 법무사는 합동사무소에 위촉되어 동업관계에 있는 법무사와 공동으로 처리하여야 할 업무를 위임하여 처리하도록 한 셈이므로 그 업무처리에 있어 실제 업무를 처리한 법무사를 지휘·감독하여야 할 사용자관계에 있다.","ox":"O","m":"⑤","c":"A","tp":"불법행위"},{"y":2021,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2021_27-38-1","t":"부동산에 관하여 과반수 공유지분을 가진 자는 공유자 사이에 공유물의 관리방법에 관하여 협의가 미리 없었다 하더라도 공유물의 관리에 관한 사항을 단독으로 결정할 수 있으므로 공유토지에 관하여 과반수지분권을 가진 자가 그 공유토지의 특정된 한 부분을 배타적으로 사용수익하더라도 다른 공유자와의 관계에서 부당이득이 성립하지 않는다.","ox":"X","m":"①","c":"A","tp":"부당이득반환청구"},{"y":2021,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2021_27-38-2","t":"토지의 매수인이 아직 소유권이전등기를 마치지 않았더라도 매매계약의 이행으로 토지를 인도받은 때에는 매매계약의 효력으로서 이를 점유·사용할 권리가 있으므로, 매도인이 매수인에 대하여 그 점유·사용을 법률상 원인이 없는 이익이라고 하여 부당이득반환청구를 할 수는 없다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2021_27-38-3","t":"부동산에 대한 취득시효가 완성되면 점유자는 소유명의자에 대하여 취득시효완성을 원인으로 한 소유권이전등기절차의 이행을 청구할 수 있고 소유명의자는 이에 응할 의무가 있으므로 점유자가 그 명의로 소유권이전등기를 경료하지 아니하여 아직 소유권을 취득하지 못하였다고 하더라도 소유명의자는 점유자에 대하여 점유로 인한 부당이득반환청구를 할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2021_27-38-4","t":"법률상 원인 없이 타인의 재산 또는 노무로 인하여 이익을 얻고 그로 인하여 타인에게 손해를 가한 경우, 그 취득한 것이 금전상의 이득인 때에는 그 금전은 이를 취득한 자가 소비하였는가의 여부를 불문하고 현존하는 것으로 추정된다.","ox":"O","m":"④","c":"A","tp":"부당이득반환청구"},{"y":2021,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2021_27-38-5","t":"타인 소유의 토지 위에 권한 없이 건물을 소유하는 자는 그 자체로써 건물 부지가 된 토지를 점유하고 있는 것이므로 특별한 사정이 없는 한 법률상 원인 없이 타인의 재산으로 인하여 토지의 차임에 상당하는 이익을 얻고 이로 인하여 타인에게 동액 상당의 손해를 주고 있는 것이다.","ox":"O","m":"⑤","c":"A","tp":"부당이득반환청구"},{"y":2022,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2022_28-34-1","t":"채무자 아닌 자가 착오로 인하여 타인의 채무를 변제한 경우에 채권자가 선의로 증서를 훼멸하거나 담보를 포기하거나 시효로 인하여 그 채권을 잃은 때에는 변제자는 그 반환을 청구하지 못한다.","ox":"O","m":"①","c":"A","tp":"부당이득"},{"y":2022,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2022_28-34-2","t":"불법행위로 인한 인신손해에 대한 손해배상청구소송에서 판결이 확정된 후 피해자가 그 판결에서 손해배상액 산정의 기초로 인정된 기대여명보다 일찍 사망한 경우라도 그 판결이 재심의 소등으로 취소되지 않는 한 그 판결에 기하여 지급받은 손해배상금 중 일부를 법률상 원인 없는 이득이라 하여 반환을 구하는 것은 그 판결의 기판력에 저촉되어 허용될 수 없다.","ox":"O","m":"②","c":"A","tp":"부당이득"},{"y":2022,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2022_28-34-3","t":"불법원인급여 후 급부를 이행받은 자가 급부의 원인행위와 별도의 약정으로 급부 그 자체 또는 그에 갈음한 대가물의 반환을 특약하는 것은 불법원인급여를 한 자가 그 부당이득의 반환을 청구하는 경우와는 달리 그 반환약정 자체가 사회질서에 반하여 무효가 되지 않는 한 유효하다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2022_28-34-4","t":"토지의 매수인이 매매계약의 이행으로 그 토지를 인도받았으나 아직 소유권이전등기를 경료받지 아니하였다면 그 매수인으로부터 위 토지를 다시 매수한 자에 대하여 매도인은 그 점유·사용을 법률상 원인이 없는 이익이라고 하여 부당이득반환청구를 할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2022_28-34-5","t":"무권한자의 변제수령을 채권자가 추인한 경우에 채권자는 무권한자에게 부당이득으로서 그 변제받은 것의 반환을 청구할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2023_29-28-1","t":"교통사고의 피해자가 사고로 상해를 입은 후에도 계속하여 종전과 같이 직장에 근무하여 종전과 같은 보수를 지급받고 있다 하더라도 이를 손해배상액에서 공제할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2023_29-28-2","t":"아파트 건축으로 인근 토지 소유자의 일조권을 침해하여 불법행위로 인한 손해배상책임이 성립한 경우 아파트 건축으로 인하여 그 토지의 지가가 상승하였다고 하더라도 그 이익을 손해배상액에서 공제할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2023_29-28-3","t":"교통사고를 일으켜 개인택시를 운전하는 사람을 사망하게 한 경우 그 망인의 가족들이 망인의 가동연한이 도래하기 전에 미리 개인택시운송사업면허를 다른 사람에게 처분하고 받은 돈에 대한 망인의 가동연한까지의 법정이자 상당 이익을 망인에 대한 손해배상액에서 공제할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2023_29-28-4","t":"공무원연금법상의 퇴직연금을 받던 사람이 다른 사람의 불법행위로 인하여 사망한 경우에 그 유족이 퇴직연금 상당의 손해배상청구권을 상속함과 동시에 유족연금을 지급받게 되었다면, 유족에게 지급할 손해배상액을 산정함에 있어서는 위 망인의 일실퇴직연금액에서 유족연금액을 공제하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2023_29-28-5","t":"피해자가 수령한 산업재해보상보험법에 따른 휴업급여금이나 장해급여금이 법원에서 인정된 소극적 손해액을 초과하더라도 그 초과부분을 기간과 성질을 달리하는 손해배상액에서 공제할 것은 아니며, 휴업급여는 휴업기간 중의 일실수입에 대응하는 것이므로 그것이 지급된 휴업기간 중의 일실수입 상당의 손해액에서만 공제되어야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2023_29-38-1","t":"위법행위가 있었다 하더라도 그로 인한 재산상태와 그 위법행위가 없었더라면 존재하였을 재산상태 사이에 차이가 없다면 다른 특별한 사정이 없는 한 위법행위로 인한 손해가 발생하였다고 할 수 없다.","ox":"O","m":"①","c":"A","tp":"불법행위"},{"y":2023,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2023_29-38-2","t":"배우자 있는 부녀와 간통행위를 하고, 이로 인하여 그 부녀가 배우자와 별거하거나 이혼하는 등으로 혼인관계를 파탄에 이르게 한 경우 그 부녀와 간통행위를 한 제3자(상간자)는 그 부녀의 자녀에 대한 관계에서 불법행위책임을 부담하므로 그가 입은 정신상의 고통을 위자할 의무가 있다고 할 것이다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2023_29-38-3","t":"손해배상의무자는 그 손해가 고의 또는 중대한 과실에 의한 것이 아니고 그 배상으로 인하여 배상자의 생계에 중대한 영향을 미치게 될 경우에는 법원에 그 배상액의 경감을 청구할 수 있다.","ox":"O","m":"③","c":"A","tp":"불법행위"},{"y":2023,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2023_29-38-4","t":"불법행위로 상해를 입었지만 후유증 등으로 인하여 불법행위 당시에는 전혀 예상할 수 없었던 후발손해가 새로이 발생한 경우와 같이, 사회통념상 후발손해가 판명된 때에 현실적으로 손해가 발생한 것으로 볼 수 있는 경우에는 후발손해 판명 시점에 불법행위로 인한 손해배상채권이 성립하고, 지연손해금 역시 그때부터 발생한다고 봄이 상당하다. 이 경우 후발손해가 판명된 때가 불법행위 시이자 그로부터 장래의 구체적인 소극적·적극적 손해에 대한 중간이자를 공제하는 현가산정의 원칙적인 기준시기가 된다고 보아야 하고, 그보다 앞선 시점이 현가산정의 기준시기나 지연손해금의 기산일이 될 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2023_29-38-5","t":"환자가 병원에 입원하여 치료를 받는 경우에 있어서, 병원은 진료뿐만 아니라 환자에 대한 숙식의 제공을 비롯하여 간호, 보호 등 입원에 따른 포괄적 채무를 지므로, 병원은 병실에의 출입자를 통제·감독하든가 그것이 불가능하다면 최소한 입원환자에게 휴대품을 안전하게 보관할 수 있는 시정장치가 있는 사물함을 제공하는 등으로 입원환자의 휴대품 등의 도난을 방지함에 필요한 적절한 조치를 강구하여 줄 신의칙상의 보호의무가 있다고 할 것이다.","ox":"O","m":"⑤","c":"A","tp":"불법행위"},{"y":2024,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2024_30-34-1","t":"임차인이 임대차계약관계가 소멸한 다음에도 임대차 목적물을 계속 점유하기는 하였지만 이를 본래의 임대차계약상 목적에 따라 사용·수익하지 않아 이익을 얻은 적이 없는 경우에는 그로 말미암아 임대인에게 손해가 발생하였더라도 임차인의 부당이득반환의무는 성립하지 않는다.","ox":"O","m":"①","c":"A","tp":"사무관리, 부당이득"},{"y":2024,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2024_30-34-2","t":"부당이득제도는 이득자의 재산상 이득이 법률상 원인을 갖지 못한 경우에 공평·정의의 이념에 근거하여 이득자에게 반환의무를 부담시키는 것이므로, 이득자에게 실질적으로 이득이 귀속된 바 없다면 반환의무를 부담시킬 수 없다.","ox":"O","m":"②","c":"A","tp":"사무관리, 부당이득"},{"y":2024,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2024_30-34-3","t":"사무관리가 성립하기 위하여는 우선 그 사무가 타인의 사무이고 타인을 위하여 사무를 처리하는 의사, 즉 관리의 사실상의 이익을 타인에게 귀속시키려는 의사가 있어야 하며, 나아가 그 사무의 처리가 본인에게 불리하거나 본인의 의사에 반한다는 것이 명백하지 아니할 것을 요한다. 여기에서 ‘타인을 위하여 사무를 처리하는 의사’는 관리자 자신의 이익을 위한 의사와 병존할 수 있으나, 외부적으로 표시되어야 하며 사무를 관리할 당시에 확정되어 있어야 한다.","ox":"X","m":"③","c":"A","tp":"사무관리, 부당이득"},{"y":2024,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2024_30-34-4","t":"의무 없이 타인의 사무를 처리한 자는 그 타인에 대하여 민법상 사무관리 규정에 따라 비용상환 등을 청구할 수 있으나, 제3자와의 약정에 따라 타인의 사무를 처리한 경우에는 의무 없이 타인의 사무를 처리한 것이 아니므로 이는 원칙적으로 그 타인과의 관계에서는 사무관리가 된다고 볼 수 없다.","ox":"O","m":"④","c":"A","tp":"사무관리, 부당이득"},{"y":2024,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2024_30-34-5","t":"민법 제742조 소정의 비채변제에 관한 규정은 변제자가 채무 없음을 알면서도 변제를 한 경우에 적용되는 것이고, 채무 없음을 알지 못한 경우에는 그 과실 유무를 불문하고 적용되지 아니하며, 변제자가 채무 없음을 알았다는 점에 대한 입증책임은 반환청구권을 부인하는 측에 있다고 할 것이다.","ox":"O","m":"⑤","c":"A","tp":"사무관리, 부당이득"},{"y":2025,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2025_31-04-1","t":"공동불법행위자 중의 1인과 보험계약을 체결한 보험자가 피해자에게 손해배상금을 보험금으로 모두 지급한 경우 다른 공동불법행위자들의 보험자들에 대하여 직접 구상권을 가짐과 동시에 상법 제682조에 따라 피보험자의 다른 공동불법행위자들의 보험자들에 대한 구상권을 대위 취득하게 되나, 이러한 ‘구상권’과 ‘보험자대위권’은 내용이 전혀 다른 별개의 권리이다.","ox":"O","m":"①","c":"A","tp":"공동불법행위책임"},{"y":2025,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2025_31-04-2","t":"제3자가 부부의 일방과 부정행위를 함으로써 그 배우자에게 부담하는 불법행위책임은 부정행위를 한 부부의 일방이 배우자에 대하여 부담하는 불법행위책임과 공동불법행위책임으로서 부진정연대채무 관계에 있지만, 부정행위를 한 부부의 일방이 이혼과정에서 배우자에게 금원을 지급하였으나 그 금원에 위자료뿐만 아니라 재산분할금이나 양육비 등 다른 성격의 금원이 포함되어 있어 공동불법행위로 인한 위자료를 구분·특정하기 어려운 특별한 경우에는, 그러한 금원 지급으로 인한 변제의 효과가 부진정연대채무자인 제3자에게 미치지 아니한다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2025_31-04-3","t":"공동불법행위책임은 가해자 각 개인의 행위에 대하여 개별적으로 그로 인한 손해를 구하는 것이 아니라 가해자들이 공동으로 가한 불법행위에 대하여 그 책임을 추궁하는 것이므로, 법원이 피해자의 과실을 들어 과실상계를 함에 있어서는 피해자의 공동불법행위자 각인에 대한 과실비율이 서로 다르더라도 피해자의 과실을 공동불법행위자 각인에 대한 과실로 개별적으로 평가할 것이 아니고 그들 전원에 대한 과실로 전체적으로 평가하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2025_31-04-4","t":"공동불법행위자 중 1인이 피해자에게 전부 변제하여 면책된 경우 그 공동불법행위자에게 과실이 없다면, 그에 대한 다른 공동불법행위자들의 구상의무는 부진정연대관계에 있다.","ox":"O","m":"④","c":"A","tp":"공동불법행위책임"},{"y":2025,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2025_31-04-5","t":"환자가 수혈로 인하여 에이즈에 감염된 경우, 에이즈에 감염된 혈액을 수혈한 대한적십자사의 과실과 수혈로 인한 에이즈 바이러스 감염 위험 등의 설명의무를 다하지 아니한 의사들의 과실은 공동불법행위를 구성하지 아니한다.","ox":"O","m":"⑤","c":"A","tp":"공동불법행위책임"},{"y":2025,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2025_31-07-1","t":"계약의 일방당사자가 상대방의 지시 등으로 상대방과 또 다른 계약관계를 맺고 있는 제3자에게 직접 급부한 경우(이른바 삼각관계에서의 급부가 이루어진 경우), 계약의 일방당사자는 제3자를 상대로 법률상 원인 없이 급부를 수령하였다는 이유로 부당이득반환청구를 할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2025_31-07-2","t":"이른바 삼각관계에서의 급부가 이루어진 경우, 제3자가 급부를 수령함에 있어 계약의 일방당사자가 상대방에 대하여 급부를 한 원인관계인 법률관계에 무효 등의 흠이 있었다는 사실을 알고 있었다면 계약의 일방당사자는 제3자를 상대로 법률상 원인 없이 급부를 수령하였다는 이유로 부당이득반환청구를 할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2025_31-07-3","t":"계약상 금전채무를 지는 이가 채권자 甲의 지시에 좇아 甲에 대한 채권자에게 직접 금전을 지급하였는데 계약의 효력이 불발생하였으면, 그와 같이 적법한 이행을 한 계약당사자는 다른 특별한 사정이 없는 한 그 제3자가 아니라 계약의 상대방당사자에 대하여 계약의 효력불발생으로 인한 부당이득을 이유로 자신의 급부 또는 그 가액의 반환을 청구하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2025_31-07-4","t":"제3자를 위한 계약관계에서 낙약자와 요약자 사이의 법률관계(이른바 기본관계)를 이루는 계약이 해제된 경우 그 계약관계의 청산은 계약의 당사자인 낙약자와 요약자 사이에 이루어져야 하므로, 특별한 사정이 없는 한 낙약자가 이미 제3자에게 급부한 것이 있더라도 낙약자는 계약해제에 기한 원상회복 또는 부당이득을 원인으로 제3자를 상대로 그 반환을 구할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2025_31-07-5","t":"회사가 임원이나 근로자를 피보험자 및 수익자로 하여 퇴직보험에 가입한 경우, 임원이나 근로자가 퇴직보험에 의하여 수령한 금원 중에서 위 퇴직금을 초과하는 금원은 회사가 출연한 보험료를 기초로 하여 법률상 원인 없이 이득을 얻은 것이 되어 회사에게 반환할 의무가 있다.","ox":"O","m":"⑤","c":"A","tp":"부당이득"},{"y":2025,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2025_31-14","t":"불법원인급여에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"불법원인급여에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","d":"ㄱ.급여자와 수익자의 불법성을 비교하여 수익자의 불법성이 급여자의 그것에 비하여 현저히 큰 경우에는 급여자는 수익자에 대하여 이익의 반환을 청구할 수 있다.\nㄴ.불법원인급여가 성립한 경우, 수익자가 그 불법의 원인에 가공하였다면 특별한 사정이 없는 한 급여자는 수익자의 불법행위를 이유로 그 재산의 급여로 말미암아 발생한 자신의 손해의 배상을 구할 수 있다.\nㄷ.구 수산업법 제33조에서 정한 어업권 임대차 금지를 위반하는 행위는 그 금지의 취지 등에 비추어 선량한 풍속 기타 사회질서에 반하는 행위에 해당하므로, 어업권을 임대한 어업권자로서는 임차인이 양식어장을 점유․사용함으로써 얻은 이익을 부당이득으로 반환을 구할 수 없다.\nㄹ.불법의 원인으로 소유권을 이전한 경우에 급여자는 부당이득을 이유로 하여 그 반환을 청구할 수는 없으나 특별한 사정이 없는 한 소유권에 기한 반환청구는 가능하다.\nㅁ.부동산 실권리자명의 등기에 관한 법률을 위반하여 무효인 명의신탁약정에 따라 명의수탁자 명의로 등기를 한 경우, 명의신탁자가 명의수탁자를 상대로 그 등기의 말소를 구하는 것이 불법원인급여를 이유로 금지된다고 할 수 없고, 이는 해당 명의신탁약정이 농지법에 따른 제한을 회피하고자 체결된 경우에도 마찬가지이다.","o":["ㄱ, ㄷ, ㄹ","ㄱ, ㄷ, ㅁ","ㄴ, ㄷ, ㅁ","ㄴ, ㄷ, ㄹ","ㄴ, ㄹ, ㅁ"],"a":4}},{"y":2025,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2025_31-40-1","t":"제3자가 채권자를 해한다는 사정을 알면서도 법규에 위반하거나 선량한 풍속 또는 사회질서에 위반하는 등 위법한 행위를 함으로써 채권자의 이익을 침해하였다면 이로써 불법행위가 성립한다고 하지 않을 수 없다.","ox":"O","m":"①","c":"A","tp":"제3자의 채권침해"},{"y":2025,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2025_31-40-2","t":"제3자가 위법한 행위를 함으로써 다른 사람 사이의 계약체결을 방해하거나 유효하게 존속하던 계약의 갱신을 하지 못하게 하여 그 다른 사람의 정당한 법률상 이익이 침해되기에 이른 경우에도 제3자의 채권침해에 의한 불법행위가 성립한다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2025_31-40-3","t":"채권침해의 위법성은 침해되는 채권의 내용, 침해행위의 태양, 침해자의 고의 내지 해의의 유무 등을 참작하여 구체적, 개별적으로 판단하되, 거래자유 보장의 필요성, 경제·사회정책적 요인을 포함한 공공의 이익, 당사자 사이의 이익균형 등을 종합적으로 고려하여야 한다.","ox":"O","m":"③","c":"A","tp":"제3자의 채권침해"},{"y":2025,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2025_31-40-4","t":"채무자가 다른 채권자들에게 채무를 변제한 행위가 정당한 법률행위인 이상 이를 요청한 행위 또한 위법성이 없어서 제3자의 채권침해에 의한 불법행위가 될 수 없다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2025_31-40-5","t":"일반적으로 채권에 대하여는 배타적 효력이 부인되고 채권자 상호간 및 채권자와 제3자 사이에 자유경쟁이 허용되는 것이지만 제3자에 의하여 채권이 침해되었으면 그 자체로 곧바로 불법행위가 성립한다고 볼 것이다.","ox":"X","m":"⑤","c":"A","tp":"제3자의 채권침해"},{"y":2026,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2026_32-10-1","t":"민법상 불법행위가 되는 명예훼손은 공연히 사실을 적시하여 사람의 인격적 가치에 대한 사회적 평가를 침해하는 행위를 말하고, 순수하게 의견만을 표명하는 경우에는 타인의 인격권을 침해하는 등으로 다른 유형의 불법행위를 구성할 수 있음은 별론으로 하더라도 그 의견표명 자체만으로 명예훼손이 성립하지는 않는다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2026_32-10-2","t":"어떠한 표현이 사실의 적시인지 의견의 진술인지는 어휘의 통상적인 의미나 전후 문맥 등 전체적인 흐름, 사회평균인의 지식이나 경험 등을 고려하여 그 표현의 진위를 결정하는 것이 가능한지 여부에 따라 판단되어야 한다.","ox":"O","m":"②","c":"A","tp":"명예훼손"},{"y":2026,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2026_32-10-3","t":"언론보도의 진실성이란 보도내용 전체의 취지에서 중요한 부분이 객관적 사실과 합치되는 것을 의미하고, 세부적으로 진실과 약간 차이가 나거나 다소 과장된 표현이 있다는 사정만으로 그 보도가 진실하지 않다고 볼 것은 아니다.","ox":"O","m":"③","c":"A","tp":"명예훼손"},{"y":2026,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2026_32-10-4","t":"언론⋅출판을 통해 사실을 적시하여 타인의 명예를 훼손하더라도, 그것이 진실한 사실로서 오로지 공공의 이익에 관한 때에는 그 행위에 위법성이 없다.","ox":"O","m":"④","c":"A","tp":"명예훼손"},{"y":2026,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2026_32-10-5","t":"법원은 명예훼손으로 인한 손해배상을 청구받은 경우, 피해자의 청구에 의하여 손해배상에 갈음하거나 손해배상과 함께 명예회복에 적당한 처분을 명할 수 있는바, 사죄광고의 형태로 명예회복에 적당한 처분을 명하는 것도 허용된다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2026_32-28-1","t":"대기오염이나 수질오염 등에 의한 공해로 인한 손해배상을 청구하는 소송에서는 가해자가 어떤 유해한 원인물질을 배출하고 그것이 피해물건에 도달하여 손해가 발생하였다면 가해자 측에서 그것이 무해하다는 것을 증명하지 못하는 한 가해행위와 피해자의 손해발생 사이의 인과관계를 인정할 수 있지만, 적어도 가해자가 어떤 유해한 원인물질을 배출한 사실, 그 유해의 정도가 사회통념상 일반적으로 참아내야 할 정도를 넘는다는 사실, 그것이 피해물건에 도달한 사실, 그 후 피해자에게 손해가 발생한 사실에 관한 증명책임은 피해자가 여전히 부담한다.","ox":"O","m":"①","c":"A","tp":"불법행위"},{"y":2026,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2026_32-28-2","t":"불법행위 시와 결과발생 시 사이에 시간적 간격이 있는 경우에는 결과가 발생한 때에 불법행위가 완성된다고 보아 불법행위가 완성된 시점, 즉 손해발생 시가 손해액 산정의 기준 시점이 된다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2026_32-28-3","t":"제3자의 채권침해 당시 채무자가 가지고 있던 다액의 채무로 인하여 제3자의 채권침해가 없었더라도 채권자가 채무자로부터 일정액 이상으로 채권을 회수할 가능성이 없었다고 인정될 경우에는 위 일정액을 초과하는 손해와 제3자의 채권침해로 인한 불법행위 사이에는 상당인과관계를 인정할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2026_32-28-4","t":"변호인의 접견교통권은 피의자 등이 변호인의 조력을 받을 권리를 실현하기 위한 것이므로, 설령 변호인의 접견교통권이 수사기관에 의하여 위법하게 침해되었더라도 변호인으로서 정신적 고통을 입었다고 볼 수 없어 국가가 변호인에게 위자료를 배상할 책임은 없다.","ox":"X","m":"④","c":"A","tp":"불법행위"},{"y":2026,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2026_32-28-5","t":"민법 제758조 제1항의 ‘공작물의 설치 또는 보존상의 하자’란 공작물이 그 용도에 따라 통상 갖추어야 할 안전성을 갖추지 못한 상태에 있음을 말한다.","ox":"O","m":"⑤","c":"A","tp":"불법행위"},{"y":2026,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2026_32-36","t":"의료과실에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"의료과실에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","d":"ㄱ.의사가 진료를 할 때 요구되는 주의의무는 의료행위 당시 임상의학 분야에서 실천되고 있는 의료행위의 수준을 기준으로 판단하여야 한다.\nㄴ.수술 도중이나 수술 후 환자에게 중한 결과의 원인이 된 증상이 발생한 경우, 그 증상발생에 관하여 의료상 과실 이외의 다른 원인이 있다고 보기 어려운 간접사실들을 증명하더라도 그 증상이 의료상 과실에 기한 것으로 추정할 수는 없다.\nㄷ.의사 등이 진료상 과실 또는 설명의무 위반으로 손해배상책임이 있는 경우, 의사 측 과실의 내용⋅정도 등을 참작하여 손해배상액을 제한할 수 있고, 그 책임감경사유에 관한 사실인정이나 비율을 정하는 것은 원칙적으로 사실심의 전권사항이다.\nㄹ.의료진의 주의의무 위반 정도가 일반인의 처지에서 수인한도를 넘어설 만큼 현저하게 불성실한 진료로 평가될 정도에 이르렀다면, 그 자체로 불법행위를 구성하여 위자료 배상을 명할 수 있으나, 이러한 사정에 대한 증명책임은 불법행위의 성립을 주장하는 피해자가 부담한다.\nㅁ.의사는 환자에게 위험성이 있는 의료행위를 하는 경우 진료계약상의 의무 내지 침습에 대한 승낙을 얻기 위한 전제로서 질병의 증상, 치료방법의 내용 및 필요성, 발생이 예상되는 위험 등에 관하여 환자가 스스로 결정할 수 있도록 사전에 설명할 의무가 있다.","o":["ㄱ, ㄹ","ㄴ, ㄹ, ㅁ","ㄱ, ㄷ, ㅁ","ㄴ, ㅁ","ㄱ, ㄷ, ㄹ, ㅁ"],"a":5}},{"y":2026,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2026_32-39-1","t":"사용자의 배상책임을 지우기 위한 사용자와 피용자의 관계는 반드시 유효한 고용관계가 있는 경우에 한하는 것이 아니고, 사실상 어떤 사람이 다른 사람을 위하여 그 지휘⋅감독 아래 그 의사에 따라 사무를 집행하는 관계가 있으면 인정되고, 지휘⋅감독 관계는 실제로 지휘⋅감독하고 있느냐의 여부에 의하여 결정되는 것이 아니라 객관적으로 지휘⋅감독을 하여야 할 관계에 있느냐의 여부에 따라 결정된다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2026_32-39-2","t":"타인에게 어떤 사업에 관하여 자기의 명의를 사용할 것을 허용한 경우에는 외부에 대한 관계에 있어서는 그 사업이 명의자의 사업이고 또 그 타인은 명의자의 종업원임을 표명한 것과 다름이 없으므로, 명의사용을 허용받은 사람이 업무수행을 함에 있어 고의 또는 과실로 다른 사람에게 손해를 끼쳤다면 명의사용을 허용한 사람은 사용자로서 그 손해를 배상할 책임이 있다.","ox":"O","m":"②","c":"A","tp":"사용자의 배상책임"},{"y":2026,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2026_32-39-3","t":"피용자의 행위가 사용자나 사용자에 갈음하여 그 사무를 감독하는 자의 사무집행 행위에 해당하지 않음을 피해자 자신이 알았거나 또는 중대한 과실로 알지 못한 경우에는 사용자 혹은 사용자에 갈음하여 그 사무를 감독하는 자에 대하여 사용자책임을 물을 수 없다.","ox":"O","m":"③","c":"A","tp":"사용자의 배상책임"},{"y":2026,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2026_32-39-4","t":"사용관계가 있느냐 여부는 객관적⋅규범적으로 보아 사용자가 그 불법행위자를 지휘⋅감독해야 할 지위에 있었느냐의 여부에 따라 결정하여야 할 것이므로 동업관계에 있는 자들이 공동으로 처리하여야 할 업무를 동업자 중 1인에게 맡겨 그로 하여금 처리하도록 한 경우 다른 동업자는 업무집행과정에서 발생한 사고에 대하여 사용자로서 손해배상책임을 지지 않는다.","ox":"X","m":"④","c":"A","tp":"사용자의 배상책임"},{"y":2026,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2026_32-39-5","t":"사용자책임의 성립요건인 ‘사무집행에 관하여’란 피용자의 불법행위가 객관적으로 사용자의 사업활동, 사무집행행위 또는 그와 관련된 것이라고 보일 때에는 행위자의 주관적 사정을 고려하지 않고 사무집행에 관하여 한 행위로 본다는 것으로, 피용자가 다른 사람에게 가해행위를 한 경우 그 행위가 피용자의 사무집행 그 자체는 아니더라도 사용자의 사업과 시간적ㆍ장소적으로 근접하고 피용자의 사무 전부 또는 일부를 수행하는 과정에서 이루어지거나 가해행위의 동기가 업무처리와 관련된 것이라면 사용자의 사무집행행위와 관련된 것으로 볼 수 있다.","ox":"O","m":"⑤","c":"A","tp":"사용자의 배상책임"}],"5":[{"y":2016,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2016_22-17-1","t":"주위토지통행권자는 필요한 경우에는 통행지상에 통로를 개설할 수 있으나, 통행지 소유자의 이익을 해하지 않는 경우라 할지라도 통로를 포장하는 것은 주위토지통행권의 성질상 허용되지 않고, 주위토지통행권자가 통로를 개설한 이상 그 통로에 대하여 통행지 소유자의 점유를 배제할 정도의 배타적인 점유를 하고 있지 않더라도 통행지 소유자는 주위토지통행권자에 대하여 주위토지통행권이 미치는 범위 내의 통로 부분의 인도를 구하거나 그 통로에 설치된 시설물의 철거를 구할 수 있다.","ox":"X","m":"①","c":"A","tp":"주위토지통행권 및 지역권"},{"y":2016,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2016_22-17-2","t":"지역권은 요역지 소유권에 부종하여 이전하며 또는 요역지에 대한 소유권 이외의 권리의 목적이 된다. 그러나 다른 약정이 있는 때에는 그 약정에 의한다.","ox":"O","m":"②","c":"A","tp":"주위토지통행권 및 지역권"},{"y":2016,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2016_22-17-3","t":"토지공유자의 1인은 지분에 관하여 그 토지를 위한 지역권 또는 그 토지가 부담한 지역권을 소멸하게 하지 못한다.","ox":"O","m":"③","c":"A","tp":"주위토지통행권 및 지역권"},{"y":2016,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2016_22-17-4","t":"지역권은 계속되고 표현된 것에 한하여 민법 제245조의 부동산점유취득시효에 관한 규정을 준용한다.","ox":"O","m":"④","c":"A","tp":"주위토지통행권 및 지역권"},{"y":2016,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2016_22-17-5","t":"점유로 인한 지역권 취득기간의 중단은 지역권을 행사하는 모든 공유자에 대한 사유가 아니면 그 효력이 없다.","ox":"O","m":"⑤","c":"A","tp":"주위토지통행권 및 지역권"},{"y":2016,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2016_22-34-1","t":"관습상의 법정지상권은 법률행위로 인한 물권의 취득이 아니므로 등기를 필요로 하지 아니하고 이를 취득할 당시의 토지소유자나 이로부터 소유권을 전득한 제3자에게도 등기 없이 관습상의 법정지상권을 주장할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2016_22-34-2","t":"법정지상권을 가진 건물소유자로부터 건물을 양수하면서 법정지상권까지 양도받기로 한 자는 채권자대위의 법리에 따라 전건물소유자 및 대지소유자에 대하여 차례로 지상권의 설정등기 및 이전등기절차이행을 구할 수 있다 할 것이므로, 이러한 법정지상권을 취득할 지위에 있는 자에 대하여 대지소유자가 소유권에 기하여 건물철거를 구함은 지상권의 부담을 용인하고 그 설정등기절차를 이행할 의무있는 자가 그 권리자를 상대로 한 청구라 할 것이어서 신의성실의 원칙상 허용될 수 없다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2016_22-34-3","t":"법정지상권자가 건물을 제3자에게 양도하는 경우에는 특별한 사정이 없는 한 건물과 함께 법정지상권도 양도하기로 하는 채권적 계약이 있었다고 할 것이며, 양수인은 양도인을 순차 대위하여 토지소유자 및 건물의 전소유자에 대하여 법정지상권의 설정등기 및 이전등기절차이행을 구할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2016_22-34-4","t":"토지와 지상 건물이 함께 양도되었다가 채권자취소권의 행사에 따라 그중 건물에 관하여만 양도가 취소되고 수익자와 전득자 명의의 소유권이전등기가 말소되었다고 하더라도, 이는 관습상 법정지상권의 성립요건인 ‘동일인의 소유에 속하고 있던 토지와 지상 건물이 매매 등으로 인하여 소유자가 다르게 된 경우’에 해당한다고 할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2016_22-34-5","t":"건물 소유를 위하여 법정지상권을 취득한 자로부터 경매에 의하여 그 건물의 소유권을 이전받은 경락인은 경락 후 건물을 철거한다는 등의 매각조건하에서 경매되는 경우 등 특별한 사정이 없는 한 건물의 경락취득과 함께 위 지상권도 당연히 취득하는데, 다만 이러한 법리는 압류, 가압류나 체납처분압류 등 처분제한의 등기가 된 건물에 관하여 그에 저촉되는 소유권이전등기를 마친 사람이 건물의 소유자로서 관습상의 법정지상권을 취득한 후 경매 또는 공매절차에서 건물이 매각되는 경우에는 적용되지 않는다.","ox":"X","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2017_23-19-1","t":"지상권자는 토지사용의 대가로서 지료를 지급하는 것이 보통이지만, 지료의 지급은 지상권의 성립요건이 아니므로 지료에 관한 약정이 없으면 무상의 지상권을 설정한 것으로 인정된다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2017_23-19-2","t":"지상권의 존속기간을 영구(永久)로 약정하는 것은 토지 소유권자의 권리를 지나치게 제한하므로 허용되지 않는다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2017_23-19-3","t":"토지의 근저당권자가 주로 목적물의 담보가치가 감소하는 것을 막기 위하여 지상권을 취득하였다면 그 피담보채권이 변제 등으로 만족을 얻어 소멸한 경우에는 그 지상권은 피담보채권에 부종하여 소멸하나, 그 피담보채권이 시효소멸한 경우에는 그 지상권은 소멸하지 않는다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2017_23-19-4","t":"지상권자가 토지소유권의 양도 전후에 걸쳐서 지료지급을 지체한 경우, 양도인과 양수인에 대하여 연체된 지료의 합이 2년분에 이르면 양수인은 지상권의 소멸을 청구할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2017_23-19-5","t":"법정지상권의 경우 지료가 결정되지 않았다 하더라도 지료에 관하여 무상으로 하는 합의가 없는 한 지상권자가 지료를 지급하지 않았다면 지료지급의 지체가 된다.","ox":"X","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2018_24-06-1","t":"미등기 무허가건물의 양수인이라도 소유권이전등기를 마치지 않는 한 건물의 소유권을 취득할 수 없고, 소유권에 준하는 관습상의 물권이 있다고도 할 수 없으므로, 미등기 무허가건물의 양수인은 소유권에 기한 방해제거청구를 할 수 없다.","ox":"O","m":"①","c":"A","tp":"미등기건물"},{"y":2018,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2018_24-06-2","t":"소액임차인의 우선변제권에 관한 주택임대차보호법 제8조 제1항 후문이 ‘이 경우 임차인은 주택에 대한 경매신청의 등기 전에’ 대항요건을 갖추어야 한다고 규정하고 있으므로, 미등기 주택의 소액임차인이 그 대지의 매각대금에 대해 우선변제권을 행사하기 위해서는, 그 임대차의 목적물인 주택에 관하여 소유권등기가 이루어져 경매신청의 등기가 되는 경우이어야 한다.","ox":"X","m":"②","c":"A","tp":"미등기건물"},{"y":2018,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2018_24-06-3","t":"동일인의 소유에 속하였던 토지와 건물이 매매, 증여, 강제경매, 국세징수법에 의한 공매 등으로 그 소유권자를 달리하게 된 경우에 그 건물을 철거한다는 특약이 없는 한 건물소유자는 그 건물의 소유를 위하여 그 부지에 관하여 관습상의 법정지상권을 취득하는 것이고, 그 건물은 건물로서의 요건을 갖추고 있는 이상 무허가건물이거나 미등기건물이거나를 가리지 않는다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2018_24-06-4","t":"미등기건물을 그 대지와 함께 매도하였다면 비록 매수인에게 그 대지에 관하여만 소유권이전등기가 경료되고 건물에 관하여는 등기가 경료되지 아니하여 형식적으로 대지와 건물이 그 소유 명의자를 달리하게 되었다 하더라도 매도인에게 관습상의 법정지상권을 인정할 이유가 없다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2018_24-06-5","t":"건물철거는 그 소유권의 종국적 처분에 해당하는 사실행위이므로 원칙으로는 그 소유자에게만 그 철거처분권이 있으나 미등기건물을 그 소유권의 원시취득자로부터 양도받아 점유중에 있는 자는 비록 소유권취득등기를 하지 못하였다고 하더라도 그 권리의 범위내에서는 점유중인 건물을 법률상 또는 사실상 처분할 수 있는 지위에 있으므로, 그 건물의 존재로 불법점유를 당하고 있는 토지소유자는 위와 같은 건물점유자에게 그 철거를 구할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2019_25-23-1","t":"전세권을 목적으로 한 저당권이 설정된 경우, 저당권이 설정된 때에 이미 전세권설정자가 전세권자에 대하여 반대채권을 가지고 있고 반대채권의 변제기가 장래 발생할 전세금반환채권의 변제기와 동시에 또는 그보다 먼저 도래하는 경우라도 전세권설정자는 반대채권을 자동채권으로 하여 전세금반환채권과 상계함으로써 전세권저당권자에게 대항할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2019_25-23-2","t":"토지와 건물을 함께 소유하던 자가 건물에 대하여 전세권을 설정하여 주었는데 그 후 토지가 제3자에게 매각되어 건물소유자가 법정지상권을 취득한 후 건물을 다시 타인에게 양도한 경우, 건물 양수인이 토지 소유자와의 관계에서 전세권자의 동의 없이 법정지상권을 취득할 지위를 소멸시켰다고 하더라도, 건물 양수인은 그 사유를 들어 전세권자에게 대항할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2019_25-23-3","t":"전세금은 민법 제315조에 정한 전세권설정자의 전세권자에 대한 손해배상채권 외 다른 채권까지 담보한다고 볼 수 없으므로, 전세권설정자가 전세권자에 대하여 위 손해배상채권 외 다른 채권을 가지고 있더라도 다른 특별한 사정이 없는 한 이를 가지고 전세금반환채권에 대하여 물상대위권을 행사한 전세권저당권자에게 상계로 대항할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2019_25-23-4","t":"전세권이 존속하는 동안은 전세권을 존속시키기로 하면서 전세금반환채권만을 전세권과 분리하여 확정적으로 양도하는 것은 허용되지 않으며, 다만 전세권 존속 중에는 장래에 그 전세권이 소멸하는 경우에 전세금반환채권이 발생하는 것을 조건으로 그 장래의 조건부 채권을 양도할 수 있을 뿐이다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2019_25-23-5","t":"당사자가 주로 채권담보의 목적으로 전세권을 설정하였고, 그 설정과 동시에 목적물을 인도하지 아니한 경우라 하더라도, 장차 전세권자가 목적물을 사용·수익하는 것을 완전히 배제하는 것이 아니라면, 그 전세권의 효력을 부인할 수는 없다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2020_26-17-1","t":"전세권의 존속기간이 경과한 후 전세권과 그 피담보채권인 전세금반환채권을 제3자에게 양도하여 전세권 이전의 부기등기까지 마쳤더라도 확정일자 있는 증서에 의한 채권양도절차를 거치지 않으면 전세금반환채권에 대한 압류채권자, 전부채권자 등 제3자에게 전세금반환채권의 양도사실로써 대항할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2020_26-17-2","t":"전세권이 성립한 후 전세목적물의 소유권이 이전된 경우 전세권이 소멸하면 전세권자는 전 소유자에 대해서도 전세금반환을 청구할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2020_26-17-3","t":"전세권설정계약이 합의해지된 경우 전세권자는 전세권과 분리하여 전세금반환채권만을 확정적으로 양도할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2020_26-17-4","t":"전세권이 부동산의 일부에 설정된 경우 전세권자는 건물 전부에 대하여 후순위권리자 기타 채권자보다 전세금의 우선변제를 받을 권리가 있으므로, 전세목적물이 아닌 나머지 건물부분에 대하여 경매를 청구할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2020_26-17-5","t":"甲 소유의 주택에 관한 乙의 전세권에 대하여 丙 명의의 저당권이 설정되었음에도 전세기간이 종료하였음을 이유로 甲이 乙에게 전세금을 반환한 경우 전세금반환채권에 대하여 丙의 압류가 없었다고 하더라도 甲은 전세금 반환으로써 丙에게 대항할 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2020_26-21-1","t":"전세권이 그 존속기간의 만료로 인하여 소멸한 때에는 전세권자는 그 목적물을 원상에 회복하여야 하며 그 목적물에 부속시킨 물건은 수거할 수 있다. 그러나 전세권설정자가 그 부속물건의 매수를 청구한 때에는 전세권자는 정당한 이유 없이 거절하지 못한다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2020_26-21-2","t":"전세금의 지급은 전세권 성립의 요소가 되는 것이지만 그렇다고 하여 전세금의 지급이 반드시 현실적으로 수수되어야만 하는 것은 아니고 기존의 채권으로 전세금의 지급에 갈음할 수도 있다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2020_26-21-3","t":"전세권이 소멸한 때에는 전세권설정자는 전세권자로부터 그 목적물의 인도 및 전세권설정등기의 말소등기에 필요한 서류의 교부를 받는 동시에 전세금을 반환하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2020_26-21-4","t":"전세권이 존속기간의 만료 등으로 종료한 경우라면 최선순위 전세권자의 채권자는 전세권이 설정된 부동산에 대한 경매절차에서 전세금반환채권에 대하여 압류 및 추심명령을 받은 다음 추심권한에 기하여 전세권에 대한 배당요구를 할 수 있을 뿐이지, 채권자대위권에 기하여 자기 이름으로 배당요구를 할 수는 없다.","ox":"X","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2020_26-21-5","t":"타인의 토지에 있는 건물에 전세권을 설정한 때에는 전세권의 효력은 그 건물의 소유를 목적으로 한 지상권 또는 임차권에 미친다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2020_26-30-1","t":"건물이 있는 토지에 저당권을 설정하고 나서 그 건물을 헐고 다시 건물을 지은 때에도 저당권의 실행으로 토지와 건물의 소유자가 달라지게 되면 법정지상권이 발생한다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2020_26-30-2","t":"동일인의 소유에 속하는 토지와 그 지상건물에 관하여 공동저당이 설정된 후 그 지상건물이 철거되고 새로 건물이 신축된 경우 특별한 사정이 없는 한 그 신축건물을 위한 법정지상권이 성립한다.","ox":"X","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2020_26-30-3","t":"나대지에 저당권이 설정된 후 저당권설정자가 그 위에 건물을 건축하였다가 임의경매로 인하여 대지와 그 지상건물의 소유자가 달라졌다 할지라도 건물소유자는 민법 제366조의 법정지상권이나 관습법상의 법정지상권을 취득할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2020_26-30-4","t":"미등기건물을 그 대지와 함께 매수한 사람이 그 대지에 관하여만 소유권이전등기를 넘겨받고 건물에 대하여는 그 등기를 이전 받지 못하고 있다가, 대지에 대하여 저당권을 설정하고 그 저당권의 실행으로 대지가 경매되어 다른 사람의 소유로 된 경우에는, 그 저당권의 설정 당시에 이미 대지와 건물이 각각 다른 사람의 소유에 속하고 있었으므로 법정지상권이 성립될 여지가 없다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2020_26-30-5","t":"건물 소유를 위하여 법정지상권을 취득한 자로부터 경매를 통해 건물의 소유권을 이전받았다면 경락 후 건물을 철거한다는 등의 매각조건하에서 경매되는 등 특별한 사정이 없는 한 매각대금을 완납하여 건물의 소유권을 취득할 때 지상권 이전등기 없이도 법정지상권을 취득한다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2021_27-27-1","t":"일반적으로 자기의 노력과 재료를 들여 건물을 건축한 사람이 그 건물의 소유권을 원시취득하는 것이지만, 도급계약에 있어서는 수급인이 자기의 노력과 재료를 들여 건물을 완성하더라도 도급인과 수급인 사이에 도급인 명의로 건축허가를 받아 소유권보존등기를 하기로 하는 등 완성된 건물의 소유권을 도급인에게 귀속시키기로 합의한 것으로 보일 경우에는 그 건물의 소유권은 도급인에게 원시적으로 귀속된다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2021_27-27-2","t":"동일한 소유자에 속하는 대지와 그 지상건물이 매매에 의하여 각기 소유자가 달라지게 된 경우에는 특히 건물을 철거한다는 조건이 없는 한 건물소유자는 대지 위에 건물을 위한 관습상의 법정지상권을 취득하는 것이고, 한편 건물 소유를 위하여 법정지상권을 취득한 자로부터 경매에 의하여 건물의 소유권을 이전받은 경락인은 경락 후 건물을 철거한다는 등의 매각조건하에서 경매되는 경우 등 특별한 사정이 없는 한 건물의 경락취득과 함께 위 지상권도 당연히 취득한다. 이러한 법리는 압류, 가압류나 체납처분압류 등 처분제한의 등기가 된 건물에 관하여 그에 저촉되는 소유권이전등기를 마친 사람이 건물의 소유자로서 관습상의 법정지상권을 취득한 후 경매 또는 공매절차에서 건물이 매각되는 경우에도 마찬가지로 적용된다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2021_27-27-3","t":"동일인의 소유에 속하고 있던 토지와 지상 건물이 매매 등으로 인하여 소유자가 다르게 된 경우에 건물을 철거한다는 특약이 없는 한 건물소유자는 건물의 소유를 위한 관습상 법정지상권을 취득한다. 나아가 토지와 지상 건물이 함께 양도되었다가 채권자취소권의 행사에 따라 그 중 건물에 관하여만 양도가 취소되고 수익자와 전득자 명의의 소유권이전등기가 말소되었다면, 이는 관습상 법정지상권의 성립요건인 ‘동일인의 소유에 속하고 있던 토지와 지상 건물이 매매 등으로 인하여 소유자가 다르게 된 경우’에 해당한다고 봄이 상당하다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2021_27-27-4","t":"법정지상권을 취득한 건물소유자가 법정지상권의 설정등기를 경료함이 없이 건물을 양도하는 경우에는 특별한 사정이 없는 한 건물과 함께 지상권도 양도하기로 하는 채권적 계약이 있었다고 할 것이므로 법정지상권자는 지상권설정등기를 한 후에 건물양수인에게 이의 양도등기절차를 이행하여 줄 의무가 있는 것이고 따라서 건물양수인은 건물양도인을 순차대위하여 토지소유자에 대하여 건물소유자였던 최초의 법정지상권자에의 법정지상권설정등기절차 이행을 청구할 수 있다. 그리고 법정지상권을 가진 건물소유자로부터 건물을 양수하면서 지상권까지 양도받기로 한 사람에 대하여 대지소유자가 소유권에 기하여 건물철거 및 대지의 인도를 구하는 것은 지상권의 부담을 용인하고 그 설정등기절차를 이행할 의무있는 자가 그 권리자를 상대로 한 청구라 할 것이어서 신의성실의 원칙상 허용될 수 없다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2021_27-27-5","t":"동일인의 소유에 속하는 토지 및 그 지상 건물에 관하여 공동저당권이 설정된 후 그 지상 건물이 철거되고 새로 건물이 신축된 경우에는 그 신축건물의 소유자가 토지의 소유자와 동일하고 토지의 저당권자에게 신축건물에 관하여 토지의 저당권과 동일한 순위의 공동저당권을 설정해 주는 등 특별한 사정이 없는 한 저당물의 경매로 인하여 토지와 그 신축건물이 다른 소유자에 속하게 되더라도 그 신축건물을 위한 법정지상권은 성립하지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2022_28-39-1","t":"분묘의 기지인 토지가 분묘소유권자 아닌 다른 사람의 소유인 경우에 그 토지 소유자가 분묘소유자에 대하여 분묘의 설치를 승낙한 때에는 그 분묘의 기지에 대하여 분묘소유자를 위한 지상권 유사의 물권(분묘기지권)을 설정한 것으로 보아야 한다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2022_28-39-2","t":"토지 소유자의 승낙이 없음에도 20년간 평온, 공연한 점유가 있었다는 사실만으로 사실상 영구적이고 무상인 분묘기지권의 시효취득을 인정하는 종전의 관습은 적어도 2001. 1. 13. 장사 등에 관한 법률이 시행될 무렵에는 법적 규범으로서 효력을 상실하였다고 할 것이므로, 2001. 1. 13. 당시 아직 20년의 시효기간이 경과하지 아니한 분묘의 경우에는 법적 규범의 효력을 상실한 분묘기지권의 시효취득에 관한 종전의 관습을 가지고 분묘기지권의 시효취득을 주장할 수 없다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2022_28-39-3","t":"분묘의 부속시설인 비석 등 제구를 설치·관리할 권한은 분묘의 수호·관리권에 포함되어 원칙적으로 제사를 주재하는 자에게 있고, 만약 제사주재자 아닌 다른 후손들이 비석 등 시설물을 설치하였고 그것이 제사주재자의 의사에 반하는 것이라 하더라도, 그 시설물의 규모나 범위가 분묘기지권의 허용범위를 넘지 아니하는 한, 분묘가 위치한 토지의 소유권자가 토지소유권에 기하여 방해배제청구로서 그 철거를 구할 수는 없다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2022_28-39-4","t":"자기 소유 토지에 분묘를 설치한 사람이 그 토지를 양도하면서 분묘를 이장하겠다는 특약을 하지 않음으로써 분묘기지권을 취득한 경우, 특별한 사정이 없는 한 분묘기지권자는 분묘기지권이 성립한 때부터 토지 소유자에게 그 분묘의 기지에 대한 토지사용의 대가로서 지료를 지급할 의무가 있다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2022_28-39-5","t":"甲이 乙과, 乙 소유의 분묘지 중 일부분에 관하여 분묘기지사용계약을 체결하였고 이에 따라 토지를 인도받아 수기의 분묘를 설치하고 20년이 넘도록 평온·공연하게 점유함으로써 분묘기지 중 계약면적을 초과하는 부분의 토지에 관하여 지상권 유사의 관습상 물권인 분묘기지권을 시효취득한 경우, 甲이 초과 토지에 관한 관리비 상당의 이익을 얻은 부분은 부당이득으로서 乙에게 반환되어야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2023_29-12-1","t":"전세권 소멸 시 목적부동산의 인도 및 전세권설정등기의 말소등기에 필요한 서류의 교부의무와 전세금반환의무는 동시이행의 관계에 있다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2023_29-12-2","t":"전세권자에게 책임 있는 사유로 전세권의 목적인 부동산이 일부 멸실된 경우 전세권설정자는 멸실된 부분만이 아니라 전세권 전부의 소멸을 청구할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2023_29-12-3","t":"건물의 일부에 대하여 전세권이 설정되어 있는 경우 그 전세권자는 전세권의 목적이 아닌 나머지 건물부분에 대하여는 경매신청을 할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2023_29-12-4","t":"전세기간 만료 이후 전세권양도계약 및 전세권이전의 부기등기가 이루어진 경우 전세권이 담보물권적 성격도 가지는 이상 부종성과 수반성이 있는 것이므로 이로써 당연히 전세금반환채권 또한 이전되었다고 할 것이어서 확정일자 있는 증서에 의한 채권양도절차를 거치지 않더라도 전세금반환채권의 압류·전부채권자 등 제3자에게 대항할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2023_29-12-5","t":"당사자가 주로 채권담보의 목적으로 전세권을 설정하였고, 그 설정과 동시에 목적물을 인도하지 아니한 경우라 하더라도, 장차 전세권자가 목적물을 사용·수익하는 것을 완전히 배제하는 것이 아니라면 그 전세권의 효력을 부인할 수는 없다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2023_29-26-1","t":"대지 소유자가 그 지상 건물을 다른 사람과 공유하면서 대지만을 타인에게 매도한 경우 건물 공유자들은 대지에 관하여 관습법상 법정지상권을 취득한다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2023_29-26-2","t":"관습법상 법정지상권이 성립된 토지에 대하여는 법정지상권자가 지상건물의 유지 및 사용에 필요한 범위를 벗어나지 않은 한 그 토지를 자유로이 사용할 수 있는 것이므로, 지상건물이 증축되었다 하더라도 관습법상 법정지상권자가 점유·사용할 권한이 있는 토지 위에 있는 이상 이를 철거할 의무는 없다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2023_29-26-3","t":"원소유자로부터 대지와 건물이 한 사람에게 매도되었으나 대지에 관하여만 그 소유권이전등기가 경료되고 건물의 소유 명의가 매도인 명의로 남아 있게 되어 형식적으로 대지와 건물이 그 소유 명의자를 달리하게 된 경우에 있어서는, 그 대지의 점유·사용 문제는 매매계약 당사자 사이의 계약에 따라 해결할 수 있는 것이므로 양자 사이에 관습법상 법정지상권을 인정할 필요는 없다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2023_29-26-4","t":"토지와 건물이 동일한 소유자에게 속하였다가 건물 또는 토지가 매매 기타 원인으로 인하여 양자의 소유자가 다르게 되었더라도, 당사자 사이에 그 건물을 철거하기로 하는 합의가 있었던 경우에는 건물 소유자는 토지 소유자에 대하여 그 건물을 위한 관습법상의 법정지상권을 취득할 수 없다.","ox":"O","m":"④","c":"A","tp":"관습법상 법정지상권"},{"y":2023,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2023_29-26-5","t":"토지공유자의 한 사람이 다른 공유자의 지분 과반수의 동의를 얻어 건물을 건축한 후 토지와 건물의 소유자가 달라진 경우 그와 같은 건물은 공유물인 토지의 관리방법으로서 적법한 사용·수익권에 기초하여 건축된 것이므로, 토지에 관하여 관습법상 법정지상권이 성립한다.","ox":"X","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2024_30-08-1","t":"요역지가 분필되어 그 부분의 소유권이 타인에게 이전되었다 하여도 요역지의 소유자가 아직 지역권설정등기를 이행받지 못하고 있는 이상, 타인소유로 된 대지부분까지를 요역지로 하여 지역권설정등기의 이행을 청구할 수 있다.","ox":"O","m":"①","c":"A","tp":"지역권, 주위토지통행권"},{"y":2024,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2024_30-08-2","t":"주위토지통행권은 통행을 위한 지역권과는 달리 그 통행로가 항상 특정한 장소로 고정되어 있는 것은 아니고, 주위토지통행권확인청구는 변론종결 시에 있어서의 민법 제219조에 정해진 요건에 해당하는 토지가 어느 토지인가를 확정하는 것이므로, 주위토지 소유자가 그 용법에 따라 기존 통행로로 이용되던 토지의 사용방법을 바꾸었을 때에는 대지 소유자는 그 주위토지 소유자를 위하여 보다 손해가 적은 다른 장소로 옮겨 통행할 수밖에 없는 경우도 있다.","ox":"O","m":"②","c":"A","tp":"지역권, 주위토지통행권"},{"y":2024,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2024_30-08-3","t":"주위토지통행권의 범위는 현재의 토지의 용법에 따른 이용의 범위뿐만 아니라 장래의 이용상황까지 미리 대비하여 정하여야 한다.","ox":"X","m":"③","c":"A","tp":"지역권, 주위토지통행권"},{"y":2024,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2024_30-08-4","t":"지역권은 계속되고 표현된 것에 한하여 민법 제245조의 규정을 준용하도록 되어 있으므로, 통행지역권은 요역지의 소유자가 승역지 위에 도로를 설치하여 승역지를 사용하는 객관적 상태가 민법 제245조에 규정된 기간 계속된 경우에 한하여 그 시효취득을 인정할 수 있다.","ox":"O","m":"④","c":"A","tp":"지역권, 주위토지통행권"},{"y":2024,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2024_30-08-5","t":"지역권은 일정한 목적을 위하여 타인의 토지를 자기의 토지의 편익에 이용하는 용익물권으로서 요역지와 승역지 사이의 권리관계에 터 잡은 것이므로, 어느 토지에 대하여 통행지역권을 주장하려면 그 토지의 통행으로 편익을 얻는 요역지가 있음을 주장·증명하여야 한다.","ox":"O","m":"⑤","c":"A","tp":"지역권, 주위토지통행권"},{"y":2025,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2025_31-13-1","t":"지상권의 존속기간과 관련하여 민법 제280조에서 석조, 석회조, 연와조 또는 이와 유사한 견고한 건물이나 수목의 소유를 목적으로 하는 때에는 최장 30년의 제한규정을 두고 있다.","ox":"X","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2025_31-13-2","t":"토지의 공유자 중의 1인이 공유토지 위에 건물을 소유하고 있다가 토지지분만을 전매한 경우 당해 토지에 관하여 건물의 소유를 위한 관습법상의 법정지상권이 성립될 수 있다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2025_31-13-3","t":"동일인의 소유에 속하고 있던 토지와 지상 건물이 함께 양도되었다가 채권자취소권의 행사에 따라 그중 건물에 관하여만 양도가 취소되고 수익자와 전득자 명의의 소유권이전등기가 말소된 경우, 관습법상 법정지상권의 성립요건인 ‘동일인의 소유에 속하고 있던 토지와 지상 건물이 매매 등으로 인하여 소유자가 다르게 된 경우’에 해당한다.","ox":"X","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2025_31-13-4","t":"동일인의 소유에 속하는 토지 및 그 지상 건물에 관하여 공동저당권이 설정된 후 그 지상 건물이 철거되고 새로 건물이 신축된 경우에는 그 신축건물의 소유자가 토지의 소유자와 동일하고 토지의 저당권자에게 신축건물에 관하여 토지의 저당권과 동일한 순위의 공동저당권을 설정해 주는 등 특별한 사정이 없는 한 저당물의 경매로 인하여 토지와 그 신축건물이 다른 소유자에 속하게 되더라도 그 신축건물을 위한 법정지상권은 성립하지 않는다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2025_31-13-5","t":"수목의 소유를 목적으로 하는 지상권은 수목이 멸실되면 소멸한다.","ox":"X","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2025_31-23-1","t":"전세권이 소멸한 때에는 전세권설정자는 전세권자로부터 그 목적물의 인도 및 전세권설정등기의 말소등기에 필요한 서류의 교부를 받는 동시에 전세금을 반환하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2025_31-23-2","t":"대지와 건물이 동일한 소유자에 속한 경우에 건물에 전세권을 설정한 때에는 그 대지소유권의 특별승계인은 전세권자에 대하여 지상권을 설정한 것으로 본다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2025_31-23-3","t":"전세권이 담보물권적 성격도 가지는 이상 부종성과 수반성이 있는 것이므로 전세권을 그 담보하는 전세금반환채권과 분리하여 양도하는 것은 허용되지 않는다고 할 것이나, 전세권이 존속기간의 만료로 소멸한 경우이거나 전세계약의 합의해지 또는 당사자 간의 특약에 의하여 전세권반환채권의 처분에도 불구하고, 전세권의 처분이 따르지 않는 경우 등의 특별한 사정이 있는 때에는 채권양수인은 담보물권이 없는 무담보의 채권을 양수한 것이 된다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2025_31-23-4","t":"건물의 일부에 대하여 전세권이 설정되어 있는 경우 그 전세권자는 민법 제303조 제1항, 제318조의 규정에 의하여 그 건물 전부에 대하여 후순위 권리자 기타 채권자보다 전세금의 우선변제를 받을 권리가 있고, 전세권설정자가 전세금의 반환을 지체한 때에는 전세권의 목적물의 경매를 청구할 수 있다 할 것이나, 전세권의 목적물이 아닌 나머지 건물부분에 대하여는 우선변제권은 별론으로 하고 경매신청권은 없다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2025_31-23-5","t":"전세권의 존속기간은 10년을 넘지 못한다. 당사자의 약정기간이 10년을 넘는 때에는 이를 10년으로 단축한다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2026_32-02-1","t":"근저당권 등 담보권 설정의 당사자들이 건물 또는 공작물이 축조⋅설치되는 등으로 토지의 담보가치가 줄어드는 것을 막기 위하여 담보권과 아울러 설정하는 이른바 담보지상권은 당사자의 약정에 따라 담보권의 존속과 지상권의 존속이 서로 연계되어 있을 뿐이고 피담보채무가 존재하는 것은 아니므로, 지상권설정등기에 관한 피담보채무의 범위 확인을 구하는 청구는 원고의 권리 또는 법률상의 지위에 관한 청구라고 보기 어려우므로 확인의 이익이 없어 부적법하다.","ox":"O","m":"①","c":"A","tp":"담보목적의 지상권"},{"y":2026,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2026_32-02-2","t":"금융기관이 대출금 채권의 담보를 위하여 토지에 저당권과 함께 지료 없는 지상권을 설정하면서 채무자 등으로 하여금 그 토지를 계속하여 점유, 사용토록 하는 경우라 할지라도 그 토지 위에 도로개설⋅옹벽축조 등의 행위를 한 무단점유자에 대하여는 지상권 자체의 침해를 이유로 임료 상당의 손해배상을 구할 수 있다.","ox":"X","m":"②","c":"A","tp":"담보목적의 지상권"},{"y":2026,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2026_32-02-3","t":"저당권과 함께 담보지상권이 설정된 토지 위에 제3자가 건물을 신축하는 경우에는 그 제3자가 지상권자에게 대항할 수 있는 권원을 가지고 있다는 등의 특별한 사정이 없는 한, 지상권자는 그 방해배제청구로서 신축 중인 건물의 철거와 대지의 인도 등을 구할 수 있다.","ox":"O","m":"③","c":"A","tp":"담보목적의 지상권"},{"y":2026,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2026_32-02-4","t":"토지에 관하여 저당권이 설정될 당시 저당권자를 위하여 동시에 지상권이 설정되었다고 하더라도 저당권 설정 당시 토지 위에 건물의 규모, 종류가 외형상 예상할 수 있는 정도까지 건축 중인 건물이 있었고, 그 후 경매절차에서 매수인이 매각대금을 다 낸 때까지 최소한의 기둥과 지붕 그리고 주벽이 이루어지는 등 독립된 부동산으로서 건물의 요건을 갖추었고, 그 건물을 철거하기로 하는 등 특별한 사유가 없으며 저당권의 실행으로 그 지상권도 소멸하였다면 그 건물을 위한 법정지상권이 성립할 수 있다.","ox":"O","m":"④","c":"A","tp":"담보목적의 지상권"},{"y":2026,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2026_32-02-5","t":"근저당권 등 담보권 설정의 당사자들이 동시에 이른바 담보지상권을 설정하였다면, 그 피담보채권이 변제 등으로 만족을 얻어 소멸한 경우는 물론이고 시효소멸한 경우에도 그 지상권은 피담보채권에 부종하여 소멸한다.","ox":"O","m":"⑤","c":"A","tp":"담보목적의 지상권"},{"y":2026,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2026_32-18","t":"용익물권에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"용익물권에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","d":"ㄱ.전세권자가 유익비상환청구권을 행사하기 위해서는 민법 제310조의 요건 및 부당이득에 관한 민법 제741조가 정하는 요건까지 모두 충족하여야 한다.\nㄴ.해안에 인접한 어장과 토지의 공로 사이에 통로가 없는 경우, 어업권의 대상인 공유수면과 인접한 토지 사이에도 주위토지통행권에 관한 민법 제219조가 준용될 수 있다.\nㄷ.지상권의 존속기간 만료 후 지상권자가 지체 없이 지상권갱신청구권을 행사하지 않아 그 권리가 소멸한 경우에도, 민법 제283조 제2항의 지상물매수청구권은 여전히 발생한다.\nㄹ.전세권이 성립한 후 전세목적물의 소유권 중 일부 지분이 이전된 경우, 그 지분을 이전받은 새로운 공유자는 전세권자에 대하여 공동 전세권설정자의 지위에서 전세금 반환의무를 부담한다.\nㅁ.대지와 건물이 동일한 소유자에게 속하는 경우에 건물에 전세권을 설정한 때에는, 그 대지소유권의 특별승계인은 전세권설정자에 대하여 지상권을 설정한 것으로 본다.","o":["ㄴ, ㄹ","ㄴ, ㄹ, ㅁ","ㄱ, ㄷ","ㄱ, ㅁ","ㄹ, ㅁ"],"a":2}},{"y":2026,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2026_32-22","t":"법정지상권에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"법정지상권에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","d":"ㄱ.토지에 관하여 저당권이 설정될 당시 토지 소유자에 의하여 그 지상에 건물이 건축 중이었던 경우 그것이 사회관념상 독립된 건물로 볼 수 있는 정도에 이르지 않았다 하더라도 건물의 규모, 종류가 외형상 예상할 수 있는 정도까지 건축이 진전되어 있었고, 그 후 경매절차에서 매수인이 매각대금을 다 낸 때까지 최소한의 기둥과 지붕 그리고 주벽이 이루어지는 등 독립된 부동산으로서 건물의 요건을 갖춘 경우에는 민법 제366조의 법정지상권이 성립한다.\nㄴ.건물공유자의 1인이 그 건물의 부지인 토지를 단독으로 소유하면서 그 토지에 관하여만 저당권을 설정하였다가 위 저당권에 의한 경매로 인하여 토지의 소유자가 달라진 경우 위 건물공유자들은 민법 제366조에 의하여 토지 전부에 관하여 건물의 존속을 위한 법정지상권을 취득한다.\nㄷ.강제경매의 목적이 된 토지 또는 그 지상 건물의 소유권이 강제경매로 인하여 그 절차상의 매수인에게 이전된 경우에 건물의 소유를 위한 관습상 법정지상권이 성립하기 위해서는 압류의 효력이 발생하는 때가 아니라 매수인이 소유권을 취득하는 매각대금의 완납 시에 토지와 그 지상 건물이 동일인에 속하여야 한다.\nㄹ.구분소유적 공유관계에 있는 토지의 공유자들이 그 토지 위에 각자 독자적으로 별개의 건물을 소유하면서 그 토지 전체에 대하여 저당권을 설정하였다가 그 저당권의 실행으로 토지와 건물의 소유자가 달라지게 된 경우 민법 제366조 소정의 법정지상권이 성립한다.\nㅁ.토지공유자의 한 사람이 다른 공유자의 지분 과반수의 동의를 얻어 건물을 건축한 후 토지와 건물의 소유자가 달라진 경우 토지에 관하여 관습법상의 법정지상권이 성립한다.","o":["ㄷ, ㅁ","ㄴ, ㅁ","ㄱ, ㄷ","ㄹ, ㅁ","ㄷ, ㄹ"],"a":1}}],"4":[{"y":2016,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2016_22-18-1","t":"재판에 의하여 공유물을 분할하는 경우에는 법원은 현물로 분할하는 것이 원칙이고, 현물로 분할할 수 없거나 현물로 분할을 하게 되면 현저히 그 가액이 감손될 염려가 있는 때에 비로소 물건의 경매를 명하여 대금분할을 할 수 있는 것이다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2016_22-18-2","t":"여러 사람이 공유하는 물건을 분할하는 경우에는 원칙적으로는 각 공유자가 취득하는 토지의 면적이 그 공유지분의 비율과 같도록 하여야 할 것이나, 반드시 그런 방법으로만 분할하여야 하는 것은 아니고, 제반 사정을 고려하여 경제적 가치가 지분 비율에 상응되도록 분할하는 것도 허용되며 일정한 요건이 갖추어진 경우에는 공유자 상호간에 금전으로 경제적 가치의 과부족을 조정하게 하여 분할을 하는 것도 현물분할의 한 방법으로 허용된다.","ox":"O","m":"②","c":"A","tp":"공유물"},{"y":2016,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2016_22-18-3","t":"부동산의 일부 공유지분에 관하여 저당권이 설정된 후 그 부동산이 분할된 경우, 그 저당권은 분할된 각 부동산 위에 종전의 지분비율대로 존속하고, 분할된 각 부동산은 그 저당권의 공동담보가 된다.","ox":"O","m":"③","c":"A","tp":"공유물"},{"y":2016,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2016_22-18-4","t":"공동상속인은 상속재산의 분할에 관하여 공동상속인 사이에 협의가 성립되지 아니하거나 협의할 수 없는 경우에 가사소송법이 정하는 바에 따라 가정법원에 상속재산분할심판을 청구할 수 있을 뿐이고, 그 상속재산에 속하는 개별 재산에 관하여 민법 제268조의 규정에 의한 공유물분할청구의 소를 제기하는 것은 허용되지 않는다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2016_22-18-5","t":"공유물분할청구의 소는 형성의 소로서 법원은 공유물분할을 청구하는 원고가 구하는 방법에 구애받지 않고 재량에 따라 합리적 방법으로 분할을 명할 수 있으므로, 분할청구자들이 그들 사이의 공유관계의 유지를 원하고 있지 아니한 경우에도 분할청구자들과 상대방 사이의 공유관계만 해소한 채 분할청구자들을 여전히 공유로 남기는 방식으로 현물분할을 하는 것도 허용될 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2016_22-19-1","t":"토지의 매수인이 매매계약에 의하여 목적 토지의 점유를 취득한 경우 설사 그것이 타인의 토지의 매매에 해당하여 그에 의하여 곧바로 소유권을 취득할 수 없다고 하더라도 그것만으로 매수인이 점유권원의 성질상 소유의 의사가 없는 것으로 보이는 권원에 바탕을 두고 점유를 취득한 사실이 증명되었다고 단정할 수 없다.","ox":"O","m":"①","c":"A","tp":"취득시효"},{"y":2016,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2016_22-19-2","t":"양도담보권설정자가 양도담보부동산을 20년간 소유의 의사로 평온, 공연하게 점유한 경우, 양도담보권자를 상대로 점유취득시효를 원인으로 하여 담보 목적으로 경료된 소유권이전등기의 말소를 구할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2016_22-19-3","t":"취득시효완성 사실을 알면서도 소유자로부터 그 부동산을 매수하여 소유권이전등기를 마친 자라고 하더라도 특별한 사정이 없는 한 소유자의 소유권이전등기의무를 승계한다고 볼 수 없다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2016_22-19-4","t":"점유자는 취득시효완성 전에 이미 설정되어 있던 가등기에 기하여 시효완성 후 소유권이전의 본등기를 경료한 제3자에 대하여 그 가등기나 본등기를 무효로 볼 수 있는 경우와 같은 특별한 사정이 없는 한 시효취득을 주장할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2016_22-19-5","t":"취득시효기간 중 계속해서 등기명의자가 동일한 경우에는, 전 점유자의 점유를 승계하여 자신의 점유기간을 통산하여 20년이 경과한 경우에 있어서도 전 점유자가 점유를 개시한 이후의 임의의 시점을 그 기산점으로 삼을 수 있다고 할 것이다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2016_22-22-1","t":"주물의 상용에 이바지한다 함은 주물 그 자체의 경제적 효용을 다하게 하는 것을 말하는 것으로서, 주물의 소유자나 이용자의 사용에 공여되고 있더라도 주물 그 자체의 효용과 직접 관계가 없는 물건은 종물이 아니라고 할 것이다.","ox":"O","m":"①","c":"A","tp":"종물 또는 부합물"},{"y":2016,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2016_22-22-2","t":"동일인의 소유에 속하는 전유부분과 대지지분 중 전유부분만에 관하여 설정된 저당권의 효력은 규약이나 공정증서로써 달리 정하는 등의 특별한 사정이 없는 한 종물 내지 종된 권리인 대지지분에까지 미친다.","ox":"O","m":"②","c":"A","tp":"종물 또는 부합물"},{"y":2016,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2016_22-22-3","t":"부동산에 부합된 물건이 사실상 분리복구가 불가능하여 거래상 독립한 권리의 객체성을 상실하고 그 부동산과 일체를 이루는 부동산의 구성 부분이 된 경우라도 타인이 권원에 의하여 이를 부합시켰으면 민법 제256조 단서에 따라 그 물건의 소유권은 부동산의 소유자에게 귀속되지 않는다.","ox":"X","m":"③","c":"A","tp":"종물 또는 부합물"},{"y":2016,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2016_22-22-4","t":"종물은 주물의 처분에 수반된다는 민법 제100조 제2항은 임의규정이므로, 당사자는 주물을 처분할 때에 특약으로 종물을 제외할 수 있고, 종물만을 별도로 처분할 수도 있다고 보아야 한다.","ox":"O","m":"④","c":"A","tp":"종물 또는 부합물"},{"y":2016,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2016_22-22-5","t":"종물은 물건의 소유자가 그 물건의 상용에 공하기 위하여 자기 소유인 다른 물건을 이에 부속하게 한 것을 말하므로, 주물과 다른 사람의 소유에 속하는 물건은 종물이 될 수 없다.","ox":"O","m":"⑤","c":"A","tp":"종물 또는 부합물"},{"y":2016,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2016_22-29-1","t":"부동산의 점유권원의 성질이 분명하지 않을 때에는 민법 제197조 제1항에 의하여 점유자는 소유의 의사로 선의, 평온 및 공연하게 점유한 것으로 추정되는 것이며, 이러한 추정은 지적공부 등의 관리주체인 국가나 지방자치단체가 점유하는 경우에도 마찬가지로 적용된다.","ox":"O","m":"①","c":"A","tp":"취득시효"},{"y":2016,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2016_22-29-2","t":"점유자가 점유 개시 당시에 소유권 취득의 원인이 될 수 있는 법률행위 기타 법률요건이 없이 그와 같은 법률요건이 없다는 사실을 잘 알면서 타인 소유의 부동산을 무단점유한 것임이 입증된 경우에는, 특별한 사정이 없는 한 점유자는 타인의 소유권을 배척하고 점유할 의사를 갖고 있지 않다고 보아야 할 것이므로 이로써 소유의 의사가 있는 점유라는 추정은 깨어진다고 할 것이다.","ox":"O","m":"②","c":"A","tp":"취득시효"},{"y":2016,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2016_22-29-3","t":"부동산점유취득시효의 원시취득으로서의 성격에 비추어 볼 때, 진정한 권리자가 아니었던 채무자 또는 물상보증인이 채무담보의 목적으로 채권자에게 부동산에 관하여 저당권설정등기를 경료해 준 후 그 부동산을 시효취득하는 경우에는 저당목적물의 시효취득으로 저당권자의 권리는 소멸한다.","ox":"X","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2016_22-29-4","t":"부동산에 대한 점유취득시효 완성을 원인으로 하는 소유권이전등기청구권은 채권적 청구권으로서, 취득시효가 완성된 점유자가 그 부동산에 대한 점유를 상실한 때로부터 10년간 이를 행사하지 아니하면 소멸시효가 완성한다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2016_22-29-5","t":"토지에 대한 취득시효완성으로 인한 소유권이전등기청구권은 그 토지에 대한 점유가 계속되는 한 시효로 소멸하지 아니하고, 여기서 말하는 점유에는 직접점유뿐만 아니라 간접점유도 포함한다고 해석하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2016_22-32-1","t":"부동산 실권리자명의 등기에 관한 법률(이하 ‘부동산실명법’이라 함)에서 정한 예외에 해당하는 등 부동산 명의신탁약정이 유효한 경우라도, 소유권이 대외적으로 수탁자에게 귀속하므로 명의신탁자는 신탁을 이유로 제3자에 대하여 그 소유권을 주장할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2016_22-32-2","t":"부동산경매절차에서 부동산을 매수하려는 사람이 매수대금을 자신이 부담하면서 다른 사람의 명의로 매각허가결정을 받기로 그 다른 사람과 약정함에 따라 매각허가가 이루어진 경우 그 경매절차에서 매수인의 지위에 서게 되는 사람은 어디까지나 그 명의인이므로 경매 목적 부동산의 소유권은 매수대금을 실질적으로 부담한 사람이 누구인가와 상관없이 그 명의인이 취득한다고 할 것이고, 이 경우 매수대금을 부담한 사람과 이름을 빌려 준 사람 사이에는 명의신탁관계가 성립한다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2016_22-32-3","t":"명의신탁자와 명의수탁자가 무효인 명의신탁약정을 함과 아울러 그 약정을 전제로 하여 이에 기한 명의신탁자의 명의수탁자에 대한 소유권이전등기청구권을 확보하기 위하여 명의신탁 부동산에 명의신탁자 명의의 가등기를 마치고 향후 명의신탁자가 요구하는 경우 본등기를 마쳐 주기로 약정하였더라도, 이러한 약정 또한 부동산실명법에 의하여 무효인 명의신탁약정을 전제로 한 것이어서 무효이고, 위 약정에 의하여 마쳐진 가등기는 원인무효라 할 것이다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2016_22-32-4","t":"이른바 3자간 등기명의신탁의 경우 부동산실명법에서 정한 유예기간 경과에 의하여 기존 명의신탁약정과 그에 의한 등기가 무효로 되고, 매도인과 명의신탁자 사이의 매매계약도 역시 무효로 된다.","ox":"X","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2016_22-32-5","t":"아파트의 수분양자가 타인과의 사이에 대내적으로는 자신이 수분양권을 계속 보유하기로 하되 수분양자 명의만을 그 타인의 명의로 하는 내용의 명의신탁약정을 맺으면서 분양계약의 수분양자로서의 지위를 포괄적으로 이전하는 내용의 계약인수약정을 체결하고 이에 대하여 위 명의신탁약정의 존재를 모르는 분양자가 동의 내지 승낙을 한 경우, 이는 이른바 계약명의신탁 관계에서 명의수탁자가 당초 명의신탁약정의 존재를 모르는 분양자와 사이에 분양계약을 체결한 경우와 다를 바 없으므로, 위 분양계약인수약정은 유효하다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2017_23-11-1","t":"공유자가 그 지분을 포기하거나 상속인 없이 사망한 때에는 그 지분은 다른 공유자에게 각 지분의 비율로 귀속한다.","ox":"O","m":"①","c":"A","tp":"공동소유"},{"y":2017,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2017_23-11-2","t":"공유자는 그 지분을 처분할 수 있으나, 합유자는 전원의 동의 없이 합유물에 대한 지분을 처분하지 못한다.","ox":"O","m":"②","c":"A","tp":"공동소유"},{"y":2017,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2017_23-11-3","t":"1필지의 토지 중 일부를 특정하여 매수하고 다만 그 소유권이전등기는 그 필지 전체에 관하여 공유지분권이전등기를 한 경우에는 그 특정부분 이외의 부분에 관한 등기는 상호명의신탁을 하고 있는 것으로서, 그 지분권자는 내부관계에 있어서는 특정부분에 한하여 소유권을 취득하고 이를 배타적으로 사용, 수익할 수 있는 것이지만, 제3자의 방해행위가 있는 경우에는 자기의 구분소유 부분뿐 아니라 전체 토지에 대하여 공유물의 보존행위로서 그 배제를 구할 수 있다.","ox":"O","m":"③","c":"A","tp":"공동소유"},{"y":2017,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2017_23-11-4","t":"채무부담행위는 총유물 자체의 관리ㆍ처분이 따르지 않더라도 민법 제275조 등에 따라 정관ㆍ규약 또는 총회결의에 의하여야 하는 총유물의 관리ㆍ처분에 해당한다.","ox":"X","m":"④","c":"A","tp":"공동소유"},{"y":2017,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2017_23-11-5","t":"공유물에 관한 보존행위는 공유자 각자가 할 수 있고, 이는 합유물도 마찬가지이다. 그러나 총유물에 관한 보존행위로서 소송을 하는 경우에는 총회의 결의를 거치거나 정관이 정하는 바에 따른 절차를 거쳐야만 한다.","ox":"O","m":"⑤","c":"A","tp":"공동소유"},{"y":2017,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2017_23-13-1","t":"동산과 동산이 부합하여 훼손하지 아니하면 분리할 수 없거나 그 분리에 과다한 비용을 요할 경우에는 그 합성물의 소유권은 주된 동산의 소유자에게 속한다. 부합한 동산의 주종을 구별할 수 없는 때에는 동산의 소유자는 부합당시의 가액의 비율로 합성물을 공유한다.","ox":"O","m":"①","c":"A","tp":"소유권의 취득"},{"y":2017,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2017_23-13-2","t":"매장물은 법률에 정한 바에 의하여 공고한 후 1년 내에 그 소유자가 권리를 주장하지 아니하면 발견자가 그 소유권을 취득하나, 타인의 토지 기타 물건으로부터 발견한 매장물은 그 토지 기타 물건의 소유자와 발견자가 절반하여 취득한다.","ox":"O","m":"②","c":"A","tp":"소유권의 취득"},{"y":2017,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2017_23-13-3","t":"유실물은 법률에 정한 바에 의하여 공고한 후 6개월 내에 그 소유자가 권리를 주장하지 아니하면 습득자가 그 소유권을 취득한다.","ox":"O","m":"③","c":"A","tp":"소유권의 취득"},{"y":2017,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2017_23-13-4","t":"무주의 부동산 및 동산은 국유로 한다.","ox":"X","m":"④","c":"A","tp":"소유권의 취득"},{"y":2017,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2017_23-13-5","t":"타인의 동산에 가공한 때에는 그 물건의 소유권은 원재료의 소유자에게 속한다. 그러나 가공으로 인한 가액의 증가가 원재료의 가액보다 현저히 다액인 때에는 가공자의 소유로 한다.","ox":"O","m":"⑤","c":"A","tp":"소유권의 취득"},{"y":2017,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2017_23-39-1","t":"부동산 실권리자명의 등기에 관한 법률(이하 ‘부동산실명법’이라 한다) 시행 전에 명의신탁이 있었으나 실명화 등의 조치 없이 부동산실명법에서 정한 유예기간이 경과한 경우, 명의신탁자가 명의수탁자에 대해 가지는 소유권이전등기청구권은 10년의 기간이 경과함으로써 시효로 소멸한다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2017_23-39-2","t":"부부간의 명의신탁약정은 특별한 사정이 없는 한 유효하고, 신탁자가 이러한 유효한 명의신탁약정을 해지함을 전제로 신탁된 부동산을 제3자에게 직접 처분하면서 수탁자 및 제3자와의 합의 아래 중간등기를 생략하고 수탁자에게서 곧바로 제3자 앞으로 소유권이전등기를 마쳐 준 경우 이로써 신탁자의 소극재산이 적극재산을 초과하게 되거나 채무초과상태가 더 나빠지게 되고 신탁자도 그러한 사실을 인식하고 있었다면, 이러한 신탁자의 법률행위는 신탁자의 일반채권자들을 해하는 행위로서 사해행위에 해당한다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2017_23-39-3","t":"신탁자와 수탁자가 명의신탁약정을 맺고, 그에 따라 수탁자가 당사자가 되어 명의신탁약정의 존재 사실을 알지 못하는 소유자와 부동산에 관한 매매계약을 체결한 계약명의신탁에서 신탁자와 수탁자 간의 명의신탁약정이 부동산 실권리자명의 등기에 관한 법률이 정한 유예기간의 경과로 무효가 되었다면, 특별한 사정이 없는 한 신탁자와 수탁자 간에 명의신탁약정과 함께 이루어진 부동산 매입의 위임 약정 역시 무효로 되고, 이 경우 신탁자와 수탁자 사이에 신탁자의 요구에 따라 부동산의 소유 명의를 이전하기로 한 약정도 명의신탁약정이 유효함을 전제로 명의신탁 부동산 자체의 반환을 구하는 범주에 속하는 것에 해당하여 역시 무효로 된다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2017_23-39-4","t":"출연자와 예금주인 명의인 사이에 예금주 명의신탁계약이 체결된 경우 그 명의인은 출연자의 요구가 있을 때에는 금융기관에 대한 예금반환채권을 출연자에게 양도할 의무가 있다고 보아야 할 것이므로, 예금주 명의신탁계약이 사해행위에 해당하여 취소될 경우 그 취소에 따른 원상회복은 명의인이 예금계좌에서 예금을 인출하여 사용하였거나 그 예금계좌를 해지하였다는 등의 특별한 사정이 없는 한 명의인에 대하여 금융기관에 대한 예금채권을 출연자에게 양도하고 아울러 금융기관에 대하여 양도통지를 할 것을 명하는 방법으로 이루어져야 할 것이다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2017_23-39-5","t":"명의신탁자가 명의신탁약정과는 별개의 적법한 원인에 기하여 명의수탁자에 대하여 소유권이전등기청구권을 가지게 된 경우, 이를 보전하기 위하여 자신의 명의가 아닌 제3자 명의로 가등기를 마쳤다면 위 가등기는 유효하다.","ox":"X","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2017_23-40-1","t":"타인의 토지에 관하여 공작물의 소유를 위한 지상권의 점유취득시효가 인정되려면 그 토지의 점유사실 외에도 그것이 임대차나 사용대차관계에 기한 것이 아니라 지상권자로서의 점유에 해당함이 객관적으로 표시되어 계속되어야 한다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2017_23-40-2","t":"부동산점유취득시효는 원시취득에 해당하므로 특별한 사정이 없는 한 원소유자의 소유권에 가하여진 각종 제한에 의하여 영향을 받지 아니하는 완전한 내용의 소유권을 취득한다. 따라서 양도담보권설정자가 양도담보부동산을 20년간 소유의 의사로 평온, 공연하게 점유하였다면 양도담보권자를 상대로 점유취득시효를 원인으로 하여 담보 목적으로 경료된 소유권이전등기의 말소를 구하거나 양도담보권설정자 명의로의 소유권이전등기를 구할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2017_23-40-3","t":"명의신탁에 의하여 부동산의 소유자로 등기된 자는 그 사실만으로 당연히 부동산을 점유하는 것으로 볼 수 없음은 물론이고 설사 그의 점유가 인정된다고 하더라도 그 점유권원의 성질상 자주점유라 할 수 없는 것이고, 한편 명의신탁자가 스스로 점유를 계속하면서 등기명의를 수탁자에게 이전한 경우에 수탁자의 등기명의를 신탁자의 등기명의와 동일한 것으로 볼 수는 없다.","ox":"O","m":"③","c":"A","tp":"취득시효"},{"y":2017,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2017_23-40-4","t":"점유로 인한 소유권취득시효가 완성된 점유자는 그 취득시효 완성 당시의 소유자에 대하여 시효취득을 원인으로 한 소유권이전등기청구권을 가지는 것이므로 이를 등기하지 아니하고 있는 사이에 먼저 소유권이전등기를 마쳐 그 부동산 소유권을 취득한 제3자에 대하여는 취득시효 완성으로 대항할 수 없다. 그러나 이로 인하여 점유자가 취득시효 완성 당시의 소유자에 대한 소유권이전등기청구권을 상실하는 것은 아니고 단지 소유자의 점유자에 대한 소유권이전등기의무가 이행불능이 되는 것뿐이므로, 그 후 어떠한 사유로 취득시효 완성 당시의 소유자에게로 소유권이 회복되었다면 원칙적으로 점유자는 소유자에게 취득시효 완성을 주장할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2017_23-40-5","t":"부동산에 관한 점유취득시효기간이 완성되었다고 하더라도 그것만으로 바로 소유권취득의 효력이 생기는 것이 아니라, 이를 원인으로 하여 소유권취득을 위한 등기청구권이 발생하는 것에 불과하고, 미등기 부동산의 경우라 하여 취득시효기간의 완성만으로 등기 없이도 점유자가 소유권을 취득한다고 볼 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2018_24-19","t":"상린관계에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"상린관계에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["민법 제218조 제1항 본문은 “토지 소유자는 타인의 토지를 통과하지 아니하면 필요한 수도, 소수관, 까스관, 전선 등을 시설할 수 없거나 과다한 비용을 요하는 경우에는 타인의 토지를 통과하여 이를 시설할 수 있다.”라고 규정하고 있다. 이와 같은 수도 등 시설권은 법정의 요건을 갖추면 당연히 인정되는 것이므로, 토지 소유자의 동의나 승낙은 민법 제218조에 기초한 수도 등 시설권의 성립이나 효력 등에 어떠한 영향을 미치는 법률행위나 준법률행위라고 볼 수 없다.","포위된 토지가 사정변경에 의하여 공로에 접하게 되거나 포위된 토지 소유자가 주위의 토지를 취득함으로써 주위토지통행권을 인정할 필요성이 없어지게 된 경우에는 통행권은 당연히 소멸한다.","어느 토지가 타인 소유의 토지에 둘러싸여 공로에 통할 수 없는 경우뿐만 아니라, 별도의 진입로가 이미 있다고 하더라도 그 진입로로 통로를 개설하는 데 과다한 비용을 요하는 때에는 민법 제219조에 의한 주위토지통행권이 인정될 수 있다.","분할로 인하여 공로에 통하지 못하는 토지가 있는 때에는 그 토지소유자는 공로에 출입하기 위하여 다른 분할자의 토지를 통행할 수 있고, 이 경우에는 보상의 의무가 없다(민법 제220조 제1항). 그러나 위 규정은 포위된 토지 또는 피통행지의 특정승계인에게는 적용되지 않고, 이는 분할자 또는 일부 양도의 당사자가 무상주위통행권에 기하여 이미 통로를 개설해 놓은 다음 특정승계가 이루어진 경우라 하더라도 마찬가지이다.","민법 제221조 제1항은 “토지소유자는 이웃 토지로부터 자연히 흘러오는 물을 막지 못한다.”라고 규정하고 있으나, 낮은 곳의 토지 소유자가 자신의 토지에 성토하여 지반고를 높여 단지 우수(빗물)의 흐름을 막게 된 것에 불과하다면 위 조항에 정한 승수의무를 위반하였다고 할 수 없다. 23-16"],"a":5}},{"y":2018,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2018_24-23","t":"주물과 종물 등에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"주물과 종물 등에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["경매대상 건물이 인접한 다른 건물과 합동됨으로써 건물로서 독립성을 상실하게 되었다면, 경매대상 건물만을 독립하여 양도하거나 경매의 대상으로 삼을 수는 없다. 이러한 경우 경매대상 건물에 설정되어 있던 저당권은 원칙적으로 소멸한다.","종물은 주물의 처분에 수반된다는 민법 제100조 제2항은 임의규정이므로, 당사자는 주물을 처분할 때에 특약으로 종물을 제외할 수 있고 종물만을 별도로 처분할 수도 있다.","주물과 다른 사람의 소유에 속하는 물건은 종물이 될 수 없다.","구분건물의 전유부분에 대한 소유권보존등기만 경료되고 대지지분에 대한 등기가 경료되기 전에 전유부분만에 대해 내려진 가압류결정의 효력은 특별한 사정이 없는 한 종물 내지 종된 권리인 그 대지권에까지 미친다.","부동산의 종물은 주물의 처분에 따르고, 저당권은 그 목적 부동산의 종물에 대하여도 그 효력이 미친다. 따라서 저당권 실행으로 개시된 경매절차에서 부동산을 매수한 자와 그 승계인은 종물의 소유권을 취득하고, 그 저당권이 설정된 이후에 종물에 대하여 강제집행을 한 자는 위와 같은 매수인과 그 승계인에게 강제집행의 효력을 주장할 수 없다. 23-17"],"a":1}},{"y":2018,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2018_24-28-1","t":"민법 제267조는 “공유자가 그 지분을 포기하거나 상속인 없이 사망한 때에는 그 지분은 다른 공유자에게 각 지분의 비율로 귀속한다.”라고 규정하므로, 부동산 공유자가 그 지분을 포기한 경우 다른 공유자들은 민법 제187조에 따라 등기 없이 부동산 물권을 취득한다.","ox":"X","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2018_24-28-2","t":"실체관계상 공유인 부동산에 관하여 단독소유로 소유권보존등기가 마쳐진 경우 소유권보존등기 중 진정한 권리자의 소유 부분에 해당하는 일부 지분에 관한 등기명의인의 소유권보존등기는 무효이므로, 이 경우 진정한 권리자는 소유권보존등기의 일부 말소를 소로써 구하고 법원은 그 지분에 한하여만 말소를 명할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2018_24-28-3","t":"합유의 경우와 달리, 건물 공유자가 공동으로 건물을 임대하고 임차보증금을 수령한 경우 특별한 사정이 없는 한 그 임차보증금 반환채무는 분할채무에 해당한다.","ox":"X","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2018_24-28-4","t":"과반수의 지분을 가진 공유자라고 하더라도, 다른 공유자와 공유물 관리방법에 관한 협의를 하지 않고 그 공유물을 자신이 배타적으로 사용·수익하기로 정할 수는 없다.","ox":"X","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2018_24-28-5","t":"공유물분할 소송에서 법원이 공유물을 현물분할하는 경우 분할청구자의 지분한도 안에서 현물분할을 하고 분할을 원하지 않는 나머지 공유자는 공유로 남는 방법도 허용되므로, 분할청구자들이 그들 사이의 공유관계의 유지를 원하지 않는 경우에도 분할청구자들과 상대방 사이의 공유관계만 해소하고 분할청구자들을 여전히 공유로 남기는 방식으로 현물분할을 할 수도 있다.","ox":"X","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2018_24-30-1","t":"3자간 등기명의신탁에 있어서, 부동산 실권리자명의 등기에 관한 법률(이하 ‘부동산실명법’이라 함) 소정의 유예기간이 경과하여 명의신탁약정과 그에 의한 등기가 무효로 된 경우에도, 매도인과 명의신탁자 사이의 매매계약은 여전히 유효하다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2018_24-30-2","t":"계약의 상대방인 매도인이 명의신탁자와 명의수탁자 사이의 명의신탁관계를 알고 있었다면, 계약명의자인 명의수탁자가 아니라 명의신탁자에게 계약에 따른 법률효과를 직접 귀속시킬 의도로 계약을 체결하였다는 등의 특별한 사정이 인정되지 아니하더라도, 그 명의신탁관계는 3자간 등기명의신탁에 해당한다고 보아야 한다.","ox":"X","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2018_24-30-3","t":"3자간 등기명의신탁에 있어서, 명의수탁자가 부동산실명법에서 정한 유예기간 경과 후에 자의로 명의신탁자에게 바로 소유권이전등기를 경료해 준 경우, 명의신탁자 명의의 소유권이전등기는 부동산실명법에 따라 무효이지만 결국 실체관계에 부합하는 등기로서 유효할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2018,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2018_24-30-4","t":"3자간 등기명의신탁에 있어서, 명의수탁자가 신탁부동산을 임의로 매각처분한 경우, 매도인으로서는 명의수탁자로부터 그 소유명의를 회복하기 전까지는 명의신탁자에 대하여 매매대금 반환채무의 이행을 거절할 수 있고, 명의신탁자의 소유권이전등기청구도 허용되지 아니하므로, 매도인으로서는 명의수탁자의 처분행위로 인하여 손해를 입은 바가 없다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2018_24-30-5","t":"계약명의신탁에 있어서, 매도인이 명의신탁약정이 있다는 사실을 알지 못하였고, 명의신탁약정이 부동산실명법 시행 후인 경우에는 명의신탁자는 명의수탁자에 대하여 부동산 매수자금 상당의 부당이득반환청구권을 가진다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2018_24-34-1","t":"민법 제256조는 “부동산의 소유자는 그 부동산에 부합한 물건의 소유권을 취득한다. 그러나 타인의 권원에 의하여 부속된 것은 그러하지 아니하다.”라고 규정하고 있다. 지상권을 설정한 토지 소유자로부터 토지를 이용할 수 있는 권리를 취득하였다고 하더라도, 지상권이 존속하는 한 위와 같이 토지 소유자로부터 취득한 권리는 원칙적으로는 민법 제256조 단서가 정한 ‘권원’에 해당하지 않는다.","ox":"O","m":"①","c":"A","tp":"첨부"},{"y":2018,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2018_24-34-2","t":"부합, 혼화, 가공으로 동산 소유권이 소멸한 때에는 그 동산을 목적으로 한 다른 권리도 소멸한다.","ox":"O","m":"②","c":"A","tp":"첨부"},{"y":2018,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2018_24-34-3","t":"타인의 동산에 가공한 때에는 그 물건의 소유권은 원재료의 소유자에게 속한다. 그러나 가공으로 인한 가액의 증가가 원재료의 가액보다 현저히 다액인 때에는 원재료 소유자와 가공자가 그 가액 비율로 공유한다.","ox":"X","m":"③","c":"A","tp":"첨부"},{"y":2018,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2018_24-34-4","t":"부합, 혼화, 가공으로 손해를 받은 자는 민법 제261조에 의해 부당이득에 관한 규정에 의하여 보상을 청구할 수 있다. 하지만 이러한 보상청구가 인정되기 위해서는 민법 제261조 자체의 요건뿐만 아니라, 부당이득 법리에 따른 판단에 의하여 부당이득의 요건이 모두 충족되었다고 인정되어야 한다.","ox":"O","m":"④","c":"A","tp":"첨부"},{"y":2018,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2018_24-34-5","t":"양도담보권의 목적인 주된 동산에 다른 동산이 부합되어 부합된 동산의 소유권자 A가 그 소유권을 상실하는 손해를 입은 경우, 특별한 사정이 없는 한 A는 양도담보권설정자를 상대로 민법 제261조에 따라 보상을 청구할 수 있을 뿐 양도담보권자를 상대로 보상을 청구할 수는 없다.","ox":"O","m":"⑤","c":"A","tp":"첨부"},{"y":2019,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2019_25-12","t":"다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"다음 설명 중 가장 옳지 않은 것은?","d":"","o":["일제시의 임야조사령이나 토지조사령에 의하여 사정을 받은 사람은 소유권을 원시적, 창설적으로 취득하고, 종중이 그 소유였던 부동산을 종중원에게 명의신탁하여 사정받았더라도 사정명의인이 그 소유권을 취득하고, 명의신탁자인 종중은 명의신탁계약에 의한 신탁자의 지위에서 명의신탁을 해지하고 그 소유권이전등기를 청구할 수 있을 뿐이며, 종중이 명의신탁계약을 해지하였더라도 그 명의로 소유권이전등기를 마치지 않은 이상 그 소유권을 취득할 수는 없다.","부동산 실권리자명의 등기에 관한 법률에 의하면, 명의신탁자와 명의수탁자가 이른바 계약명의신탁약정을 맺고 명의수탁자가 당사자가 되어 명의신탁약정이 있다는 사실에 대하여 선의인 소유자와 사이에 부동산에 관한 매매계약을 체결한 후 그 매매계약에 따라 해당 부동산의 소유권이전등기를 수탁자 명의로 마친 경우에는 명의수탁자가 해당 부동산의 완전한 소유권을 취득하게 되고, 다만 명의수탁자는 명의신탁자에 대하여 명의신탁약정 위반에 따른 채무불이행책임을 부담하게 될 뿐이다.","부동산 실권리자명의 등기에 관한 법률에 따라 부부간 명의신탁이 일단 유효한 것으로 인정되었다면 그 후 배우자 일방의 사망으로 부부관계가 해소되었더라도 그 명의신탁은 사망한 배우자의 다른 상속인과의 관계에서도 여전히 유효하게 존속한다고 보아야 한다.","부동산 실권리자명의 등기에 관한 법률 제4조 제3항의 입법취지 등을 고려할 때, 명의신탁자와 부동산에 관한 물권을 취득하기 위한 계약을 맺고 단지 등기명의만을 명의수탁자로부터 경료받은 것 같은 외관을 갖춘 자는 위 법률조항의 제3자에 해당하지 않는다.","계약명의신탁의 당사자들이 명의신탁약정의 유효한 것, 즉 명의신탁자가 이른바 내부적 소유권을 가지는 것을 전제로 하여 장차 명의신탁자 앞으로 목적 부동산에 관한 소유권등기를 이전하거나 부동산의 처분대가를 명의신탁자에게 지급하는 것 등을 내용으로 하는 약정을 하였다면 이는 무효이다. 22-14"],"a":2}},{"y":2019,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2019_25-25-1","t":"乙이 丙에게 X토지를 매도하고 1999. 4. 1. 소유권이전등기를 마쳐준 경우, 甲은 1999. 4. 1.을 기산점으로 하여 丙에게 취득시효완성을 주장할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2019_25-25-2","t":"乙이 丙에게 X토지를 매도하고 2005. 4. 1. 소유권이전등기를 마쳐주었는데, 丙이 2010. 4. 1. X토지를 다시 乙에게 매도하여 현재 乙 명의로 등기가 되어 있는 경우, 甲은 乙에게 취득시효완성을 이유로 한 소유권이전등기청구를 할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2019_25-25-3","t":"甲이 2019. 4. 1. 乙에게 X토지에 관하여 취득시효완성을 원인으로 한 소유권이전등기청구소송을 제기하고 그 소장부본이 2019. 4. 15. 乙에게 송달되었는데, 乙이 2019. 5. 1. 丙에게 X토지를 매도하고 소유권이전등기를 마쳐준 경우, 乙은 甲이 입은 손해를 배상하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2019_25-25-4","t":"2019. 6. 1. 현재 乙의 등기부상 소유명의가 원인무효이고 X토지의 진정한 소유자가 丙임이 밝혀진 경우, 乙은 시효취득을 원인으로 한 소유권이전등기청구의 상대방이 될 수 없고, 甲은 丙을 대위하여 乙 명의의 등기말소를 구하고 다시 丙을 상대로 취득시효완성을 이유로 한 소유권이전등기를 구하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2019_25-25-5","t":"乙이 2015. 2. 1. 丙으로부터 1천만 원을 빌리면서 그 담보로 X토지에 관하여 丙 앞으로 근저당권설정등기를 마쳐주었는데, 乙이 위 돈을 갚지 못하여 丙이 X토지에 대해 경매신청을 하자 甲이 丙에게 위 돈을 변제한 경우, 甲은 乙에게 1천만 원 상당의 부당이득반환을 구할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2020_26-01-1","t":"공유물분할청구의 소는 형성의 소로서 법원은 공유물분할을 청구하는 원고가 구하는 방법에 구애받지 않고 재량에 따라 합리적 방법으로 분할을 명할 수 있으나, 분할청구자들이 그들 사이의 공유관계의 유지를 원하고 있지 아니한데도 분할청구자들과 상대방 사이의 공유관계만 해소한 채 분할청구자들을 여전히 공유로 남기는 방식으로 현물분할을 하는 것은 허용될 수 없다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2020_26-01-2","t":"합유물을 처분 또는 변경함에는 합유자 전원의 동의가 있어야 하지만, 보존행위는 각자가 단독으로 할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2020_26-01-3","t":"지분을 포기한 합유지분권자로부터 잔존 합유지분권자들에게 합유지분권 이전등기가 이루어지지 아니하는 한 지분을 포기한 지분권자는 제3자에 대하여 여전히 합유지분권자로서의 지위를 가지고 있다고 보아야 하며, 그는 합유물을 점유하는 제3자에게 합유물의 반환을 구할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2020_26-01-4","t":"총유물의 관리 및 처분이라 함은 총유물 그 자체에 관한 이용·개량행위나 법률적·사실적 처분행위를 의미하는 것이므로, 비법인사단이 타인 간의 금전채무를 보증하는 행위는 총유물 그 자체의 관리·처분이 따르지 아니하는 단순한 채무부담행위에 불과하여 이를 총유물의 관리·처분행위라고 볼 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2020_26-01-5","t":"공유자가 공유물을 타인에게 임대하는 행위 및 그 임대차계약을 해지하는 행위는 공유물의 관리행위에 해당하나, 상가건물 임대차보호법이 적용되는 상가건물의 공유자인 임대인이 임차인에게 갱신 거절의 통지를 하는 행위까지 관리행위로 볼 것은 아니다.","ox":"X","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2020_26-07-1","t":"다세대주택의 지하층은 구분소유자들이 공동으로 사용하는 경우가 적지 않은데, 다세대주택인 1동의 건물을 신축하면서 건축허가를 받지 않고 위법하게 지하층을 건축하였다면 처분권자의 구분의사가 명확하게 표시되지 않은 이상 공용부분으로 추정하는 것이 사회관념이나 거래관행에 부합한다.","ox":"O","m":"①","c":"A","tp":"구분건물"},{"y":2020,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2020_26-07-2","t":"1동 건물의 구분소유자들이 당초 건물을 분양받을 당시 대지 공유지분 비율대로 건물의 대지를 공유하고 있는 경우 특별한 사정이 없는 한 구분소유자들 사이에서는 대지 공유지분 비율의 차이를 이유로 부당이득반환을 구할 수 없다.","ox":"O","m":"②","c":"A","tp":"구분건물"},{"y":2020,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2020_26-07-3","t":"구분소유권은 원칙적으로 건물 전체가 완성되어 당해 건물에 관한 건축물대장에 구분건물로 등록된 시점에 성립하고, 예외적으로 건축물대장에 등록되기 전에 등기관이 집행법원의 등기촉탁에 의하여 미등기건물에 관하여 소유권 처분제한의 등기를 하면서 구분건물의 표시에 관한 등기를 하는 경우에는 등기된 시점에 구분소유권이 성립한다.","ox":"X","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2020_26-07-4","t":"집합건물에 있어 전유부분에 대한 대지사용권을 분리처분할 수 있도록 정한 규약이 존재한다는 등의 특별한 사정이 없는 한, 집합건물을 신축하였으나 그 대지 소유권을 취득하지 못한 상태에서 전유부분의 소유권을 경매로 상실한 자는 장래 취득할 대지지분을 전유부분의 소유권을 취득한 경락인이 아닌 제3자에게 분리처분하지 못하고, 이를 위반한 대지지분의 처분행위는 무효이다.","ox":"O","m":"④","c":"A","tp":"구분건물"},{"y":2020,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2020_26-07-5","t":"1동 건물의 일부분이 구분소유권의 객체로서 적합한 구조상 독립성을 갖추지 못한 상태에서 구분소유권의 목적으로 등기되고 이에 기초하여 근저당권설정등기나 소유권이전등기 등이 순차로 마쳐진 다음 구분소유권의 객체가 된 경우 그 등기는 유효하다.","ox":"O","m":"⑤","c":"A","tp":"구분건물"},{"y":2020,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2020_26-39-1","t":"진정한 권리자가 아니었던 채무자 또는 물상보증인이 채무담보의 목적으로 채권자에게 부동산에 관하여 저당권설정등기를 경료해 준 후 그 부동산을 시효취득하는 경우 채무자 또는 물상보증인은 피담보채권의 변제의무 내지 책임이 있는 사람으로서 이미 저당권의 존재를 용인하고 점유하여 온 것이므로, 저당목적물의 시효취득으로 저당권자의 권리는 소멸하지 않는다.","ox":"O","m":"①","c":"A","tp":"취득시효"},{"y":2020,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2020_26-39-2","t":"취득시효 완성 당시 그 부동산의 등기부상 소유자의 등기가 원인 무효의 흠결이 있더라도 등기부상 소유자가 진정한 소유자를 상대로 제기한 소유권이전등기 청구소송의 기판력 있는 확정판결에 의하여 위 등기가 경료된 경우, 위 확정판결의 기판력에 따라 진정한 소유자를 대위하여 등기부상 소유자를 상대로 위 등기의 말소를 구할 수 없고, 직접 현재 등기부상 소유자를 상대로 취득시효를 원인으로 한 소유권이전등기를 청구할 수도 없다.","ox":"X","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2020_26-39-3","t":"명의신탁된 부동산에 관하여 그 점유자의 점유취득시효 완성 후 그 소유권이전등기를 경료하기 전에 위 명의신탁이 해지되고 새로운 명의신탁이 이루어져 그 소유 명의가 점유취득시효 완성 당시의 명의수탁자로부터 새로운 명의수탁자에게로 이전된 경우, 위 소유 명의의 이전이 무효가 아닌 이상 새로운 명의수탁자는 위 점유취득시효 완성 후에 소유권을 취득한 자에 해당하므로, 위 점유자는 그에 대하여 시효취득을 주장할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2020_26-39-4","t":"점유자가 점유 개시 당시에 소유권 취득의 원인이 될 수 있는 법률요건이 없다는 사실을 잘 알면서 타인 소유의 부동산을 무단점유한 것임이 밝혀진 경우 원칙적으로 자주점유의 추정은 깨어진다.","ox":"O","m":"④","c":"A","tp":"취득시효"},{"y":2020,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2020_26-39-5","t":"부동산을 20년간 소유의 의사로 평온·공연하게 점유한 자는 민법 제245조 제1항에 의하여 점유부동산에 관하여 소유자에 대한 소유권이전등기청구권을 취득하고, 점유자가 취득시효기간의 만료로 일단 소유권이전등기청구권을 취득한 이상, 그 후 점유를 상실하였다고 하더라도 이를 시효이익의 포기로 볼 수 있는 경우가 아닌 한, 이미 취득한 소유권이전등기청구권은 소멸하지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2020_26-40-1","t":"건물의 소유자가 그 건물의 소유를 통하여 토지를 불법점유하고 있는 경우 그 토지 소유자로서는 그 건물의 철거와 그 대지 부분의 인도를 청구할 수 있을 뿐, 자기 소유의 건물을 점유하고 있는 자에 대하여 그 건물에서 퇴거할 것을 청구할 수는 없다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2020_26-40-2","t":"건물이 그 존립을 위한 토지사용권을 갖추지 못하여 토지소유자가 건물소유자에 대하여 당해 건물의 철거 및 그 대지의 인도를 청구할 수 있는 상황에서 건물소유자가 아닌 사람이 건물을 점유하고 있는 경우, 토지소유자는 건물점유자에 대하여 퇴거청구를 할 수 있고, 이는 건물 점유자가 건물 소유자로부터의 임차인으로서 그 건물임차권이 이른바 대항력을 가지는 경우에도 마찬가지이다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2020_26-40-3","t":"과반수 지분의 공유자가 그 공유물의 특정 부분을 배타적으로 사용·수익하는 것은 공유물의 관리방법으로서 적법하므로, 소수 지분의 공유자는 과반수 지분의 공유자로부터 사용·수익을 허락받은 점유자에 대하여 건물의 철거나 퇴거 등 점유배제를 구할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2020_26-40-4","t":"건물의 공유자들이 부담하는 철거의무는 성질상 불가분채무라 할 것이어서 각 공유자가 건물 전체에 대한 철거의무를 부담하는 것이므로 공유자 전원을 피고로 삼지 않고 그 중 일부만을 피고로 하여서는 건물 전체의 철거를 구할 수 없다.","ox":"X","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2020_26-40-5","t":"불법점유자에 대한 인도청구는 현실로 불법점유를 하고 있는 자만을 상대로 하여야 하는 반면, 인도 약정에 따른 이행청구의 경우에는 간접점유자에 대하여도 인도를 구할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2021_27-10-1","t":"부동산에 부합된 물건이 사실상 분리복구가 불가능하여 거래상 독립된 권리의 객체성을 상실하고 그 부동산과 일체를 이루는 부동산의 구성부분이 된 경우에는 타인의 권원에 의하여 이를 부합시킨 경우에도 그 물건의 소유권은 부동산의 소유자에게 귀속된다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2021_27-10-2","t":"토지의 지상에 별개의 부동산인 건축물이 건축된 경우, 토지의 지하에 시공된 시설이 토지에 부합되었는지 아니면 지상 건축물의 기초 등을 구성하여 건축물의 일부분이 되었는지 여부는, 그 시설과 토지 및 건축물 사이의 각 결합 정도나 그 물리적 구조뿐만 아니라 당해 시설의 객관적, 사회경제적인 기능과 용도, 일반 거래관념, 토지의 당초 조성상태, 건축물의 종류와 규모 등 제반 사정을 종합하여 합리적으로 판단하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2021_27-10-3","t":"종물은 물건의 소유자가 그 물건의 상용에 공하기 위하여 자기 소유인 다른 물건을 이에 부속하게 한 것을 말하므로 주물과 다른 사람의 소유에 속하는 물건은 종물이 될 수 없다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2021_27-10-4","t":"종물은 주물의 처분에 수반된다는 민법 제100조 제2항은 임의규정이므로, 당사자는 주물을 처분할 때에 특약으로 종물을 제외할 수 있고 종물만을 별도로 처분할 수도 있다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2021_27-10-5","t":"부동산에 부합된 물건이 사실상 분리복구가 불가능하여 거래상 독립한 권리의 객체성을 상실하고 그 부동산과 일체를 이루는 부동산의 구성부분이 된 경우에는 타인이 권원에 의하여 이를 부합시켰더라도 그 물건의 소유권은 부동산의 소유자에게 귀속되어 부동산의 소유자는 방해배제청구권에 기하여 부합물의 철거를 청구할 수 없고, 부합물이 위와 같은 요건을 충족하지 못해 그 물건의 소유권이 부동산의 소유자에게 귀속되었다고 볼 수 없는 경우에도 부동산의 소유자는 방해배제청구권에 기하여 부합물의 철거를 청구할 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2021_27-19","t":"X토지에 대하여 甲은 4/6 지분을, 乙, 丙은 1/6 지분씩을 각 공유하고 있는데, 乙이 다른 공유자들과 협의 없이 X토지의 일부에 소나무를 식재하고 이를 독점적으로 점유하고 있다. 이에 대한 다음 설명 중 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"X토지에 대하여 甲은 4/6 지분을, 乙, 丙은 1/6 지분씩을 각 공유하고 있는데, 乙이 다른 공유자들과 협의 없이 X토지의 일부에 소나무를 식재하고 이를 독점적으로 점유하고 있다. 이에 대한 다음 설명 중 옳은 것을 모두 고른 것은?","d":"ㄱ.丙은 공유물의 보존행위로서 乙을 상대로 乙이 점유하는 부분에 대한 인도를 청구할 수 있다.\nㄴ.丙은 자신의 공유지분권에 기하여 乙을 상대로 공유물에 대한 방해상태를 제거하거나 방해하는 행위의 금지를 청구할 수 있다.\nㄷ.만일 乙이 아닌 甲이 소나무를 식재하고 독점적으로 점유하는 경우라면 다른 공유자들은 보존행위로서 甲을 상대로 공유물의 인도를 청구할 수 있다.\nㄹ. 만일 乙이 아닌 甲이 소나무를 식재하고 독점적으로 점유하는 경우라면 다른 공유자들은 甲에 대하여 방해상태를 제거하거나 방해하는 행위의 금지를 청구할 수 있다.","o":["ㄴ","ㄱ, ㄴ","ㄴ, ㄹ","ㄱ, ㄴ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":1}},{"y":2021,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2021_27-22-1","t":"민법 제211조는 “소유자는 법률의 범위 내에서 그 소유물을 사용, 수익, 처분할 권리가 있다.”고 규정하고 있으므로, 소유자가 채권적으로 상대방에 대하여 사용·수익의 권능을 포기하거나 사용·수익권 행사에 제한을 설정하는 것 외에 소유권의 핵심적 권능에 속하는 배타적인 사용·수익 권능이 소유자에게 존재하지 아니한다고 하는 것은 물권법정주의에 반하여 특별한 사정이 없는 한 허용될 수 없다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2021_27-22-2","t":"토지 소유자가 그 소유의 토지를 도로, 수도시설의 매설 부지 등 일반 공중을 위한 용도로 제공한 경우에, 소유자가 토지를 소유하게 된 경위와 보유기간, 소유자가 토지를 공공의 사용에 제공한 경위와 그 규모, 토지의 제공에 따른 소유자의 이익 또는 편익의 유무, 해당 토지 부분의 위치나 형태, 인근의 다른 토지들과의 관계, 주위 환경 등 여러 사정을 종합적으로 고찰하고, 토지 소유자의 소유권 보장과 공공의 이익 사이의 비교형량을 한 결과, 소유자가 그 토지에 대한 독점적·배타적인 사용·수익권을 포기한 것으로 볼 수 있는 경우에, 타인[사인(私人)뿐만 아니라 국가, 지방자치단체도 이에 해당할 수 있다]이 그 토지를 점유·사용하고 있다면 특별한 사정이 없는 한 토지소유자에게 어떠한 손해가 생긴다고 볼 수 없어 손해배상청구를 할 수는 없으나, 토지 소유자는 그 타인을 상대로 부당이득반환을 청구할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2021_27-22-3","t":"점유권에 기인한 소와 본권에 기인한 소는 서로 영향을 미치지 아니하고, 점유권에 기인한 소는 본권에 관한 이유로 재판하지 못하므로 점유회수의 청구에 대하여 점유침탈자가 점유물에 대한 본권이 있다는 주장으로 점유회수를 배척할 수 없다(민법 제208조). 그러므로 점유권에 기한 본소에 대하여 본권자가 본소청구 인용에 대비하여 본권에 기한 예비적 반소를 제기하고 양 청구가 모두 이유 있는 경우, 법원은 점유권에 기한 본소와 본권에 기한 예비적 반소를 모두 인용해야 하고 점유권에 기한 본소를 본권에 관한 이유로 배척할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2021_27-22-4","t":"타인 소유의 토지에 분묘를 설치한 경우에 20년간 평온, 공연하게 분묘의 기지를 점유하면 지상권과 유사한 관습상의 물권인 분묘기지권을 시효로 취득한다는 점은 오랜 세월 동안 지속되어 온 관습 또는 관행으로서 법적 규범으로 승인되어 왔고, 이러한 법적 규범이 장사 등에 관한 법률(법률 제6158호) 시행일인 2001. 1. 13. 이전에 설치된 분묘에 관하여 현재까지 유지되고 있다고 보아야 한다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2021_27-22-5","t":"미등기 무허가건물의 양수인이라도 소유권이전등기를 마치지 않는 한 건물의 소유권을 취득할 수 없고, 소유권에 준하는 관습상의 물권이 있다고도 할 수 없으므로, 미등기 무허가건물의 양수인은 소유권에 기한 방해제거청구를 할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2021_27-28-1","t":"부동산 실권리자명의 등기에 관한 법률(이하 ‘부동산실명법’이라 한다)은 부동산에 관한 소유권과 그 밖의 물권을 실체적 권리관계와 일치하도록 실권리자 명의로 등기하게 함으로써 부동산등기제도를 악용한 투기ㆍ탈세ㆍ탈법행위 등 반사회적 행위를 방지하고 부동산 거래의 정상화와 부동산 가격의 안정을 도모하여 국민경제의 건전한 발전에 이바지함을 목적으로 하고 있다(제1조). 부동산실명법에 의하면, 누구든지 부동산에 관한 물권을 명의신탁약정에 따라 명의수탁자의 명의로 등기하여서는 아니 되고(제3조 제1항), 명의신탁약정과 그에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효가 되며(제4조 제1항, 제2항 본문), 명의신탁약정에 따른 명의수탁자 명의의 등기를 금지하도록 규정한 부동산실명법 제3조 제1항을 위반한 경우 명의신탁자와 명의수탁자 쌍방은 형사처벌된다(제7조).","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2021_27-28-2","t":"부동산실명법에 의해 양자간 등기명의신탁의 경우 목적 부동산에 관한 명의수탁자 명의의 소유권이전등기에도 불구하고 그 소유권은 처음부터 이전되지 아니하는 것이어서 원래 그 부동산의 소유권을 취득하였던 명의신탁자가 그 소유권을 여전히 보유하는 것이 되는 이상, 침해부당이득의 성립 여부와 관련하여 명의수탁자 명의로의 소유권이전등기로 인하여 명의신탁자가 어떠한 ‘손해’를 입게 되거나 명의수탁자가 어떠한 이익을 얻게 된다고 할 수 없다. 결국 양자간 등기명의신탁에 있어서 그 명의신탁자로서는 명의수탁자를 상대로 소유권에 기하여 원인무효인 소유권이전등기의 말소를 구하거나 진정한 등기명의의 회복을 원인으로 한 소유권이전등기절차의 이행을 구할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2021_27-28-3","t":"甲이 乙과 직접 부동산에 관한 매매계약을 체결하고 그 대금을 모두 지급하였으나 丙에게 명의를 신탁하여 그 앞으로 소유권이전등기를 경료한 경우, 부동산에 관하여 乙로부터 丙 앞으로 이루어진 소유권이전등기의 원인이 된 명의신탁약정은 명의신탁자인 甲이 매매계약의 당사자로 되었으나 등기명의만을 명의수탁자인 丙에게 신탁한 것으로서 명의수탁자가 계약당사자가 된 경우가 아니어서 부동산실명법 제4조 제2항 단서의 규정을 적용할 여지 없이 무효라고 봄이 상당하고, 甲으로서는 여전히 乙에 대하여 부동산에 관한 소유권이전등기절차의 이행을 구할 수 있다고 할 것이므로, 乙을 대위하여 丙에게 말소등기절차의 이행을 구할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2021_27-28-4","t":"명의신탁자와 명의수탁자가 이른바 계약명의신탁 약정을 맺고 매매계약을 체결한 소유자도 명의신탁자와 명의수탁자 사이의 명의신탁약정을 알면서 그 매매계약에 따라 명의수탁자 앞으로 당해 부동산의 소유권이전등기를 마친 경우 부동산실명법 제4조 제2항 본문에 의하여 명의수탁자 명의의 소유권이전등기는 무효이므로, 당해 부동산의 소유권은 매매계약을 체결한 소유자에게 그대로 남아 있게 된다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2021_27-28-5","t":"부동산실명법 규정의 문언, 내용, 체계와 입법 목적 등을 종합하면, 부동산실명법을 위반하여 무효인 명의신탁약정에 따라 명의수탁자 명의로 등기를 하였다면 이는 불법원인급여에 해당한다. 이는 농지법에 따른 제한을 회피하고자 명의신탁을 한 경우에도 마찬가지이다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2021_27-34-1","t":"하천에 인접한 토지가 홍수로 인한 하천류수의 범람으로 침수되어 토지가 황폐화되거나 물밑에 잠기거나 항시 물이 흐르고 있는 상태가 계속되고 원상복구가 사회통념상 불가능하게 되면 소위 포락으로 인하여 소유권은 영구히 소멸되는 것이고, 이와 같은 사정은 사권의 소멸을 주장하는 자가 입증하여야한다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2021_27-34-2","t":"일단의 증감 변동하는 동산을 하나의 물건으로 보아 이를 채권담보의 목적으로 삼으려는 이른바 집합물에 대한 양도담보설정계약체결은 허용되지 않는다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2021_27-34-3","t":"1동의 건물에 대하여 구분소유가 성립하기 위해서는 객관적·물리적인 측면에서 1동의 건물이 존재하고, 구분된 건물부분이 구조상·이용상 독립성을 갖추어야 할 뿐 아니라, 1동의 건물 중 물리적으로 구획된 건물부분을 각각 구분소유권의 객체로 하려는 구분행위가 있어야 한다. 여기서 구분행위는 건물의 물리적 형질에 변경을 가함이 없이 법률관념상 건물의 특정 부분을 구분하여 별개의 소유권의 객체로 하려는 일종의 법률행위로서, 그 시기나 방식에 특별한 제한이 있는 것은 아니고 처분권자의 구분의사가 객관적으로 외부에 표시되면 인정된다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2021_27-34-4","t":"독립된 부동산으로서의 건물이라고 하기 위하여는 최소한의 기둥과 지붕 그리고 주벽이 이루어지면 된다. 신축건물의 경락대금 납부 당시 이미 지하 1층부터 지하 3층까지 기둥, 주벽 및 천장 슬라브공사가 완료된 상태였을 뿐만 아니라 지하 1층의 일부 점포가 일반에 분양되기까지 하였다면, 비록 토지가 경락될 당시 신축건물의 지상층 부분이 골조공사만 이루어진 채 벽이나 지붕 등이 설치된 바가 없다 하더라도, 지하층 부분만으로도 구분소유권의 대상이 될 수 있는 구조라는 점에서 신축건물은 경락 당시 미완성 상태이기는 하지만 독립된 건물로서의 요건을 갖추었다고 봄이 상당하다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2021_27-34-5","t":"건축주의 사정으로 건축공사가 중단되었던 미완성의 건물을 인도받아 나머지 공사를 마치고 완공한 경우, 그 건물이 공사가 중단된 시점에서 이미 사회통념상 독립한 건물이라고 볼 수 있는 형태와 구조를 갖추고 있었다면 원래의 건축주가 그 건물의 소유권을 원시취득한다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2021_27-36-1","t":"부동산에 대한 점유취득시효가 완성된 후 취득시효 완성을 원인으로 한 소유권이전등기를 하지 않고 있는 사이에 그 부동산에 관하여 제3자 명의의 소유권이전등기가 경료된 경우라 하더라도 당초의 점유자가 계속 점유하고 있고 소유자가 변동된 시점을 기산점으로 삼아도 다시 취득시효의 점유기간이 경과한 경우에는 점유자로서는 제3자 앞으로의 소유권 변동시를 새로운 점유취득시효의 기산점으로 삼아 2차의 취득시효의 완성을 주장할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2021_27-36-2","t":"부동산에 관하여 적법·유효한 등기를 마치고 그 소유권을 취득한 사람이 자기 소유의 부동산을 점유하는 경우 특별한 사정이 없는 한 그 점유는 취득시효의 기초가 되는 점유라고 할 수 없다.","ox":"O","m":"②","c":"A","tp":"점유취득시효"},{"y":2021,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2021_27-36-3","t":"토지 소유자가 토지의 특정한 일부분을 타인에게 매도하면서 등기부상으로는 전체 토지의 일부 지분에 관한 소유권이전등기를 경료해 준 경우에 매도 대상에서 제외된 나머지 특정 부분을 계속 점유한다고 하더라도 이는 자기 소유의 토지를 점유하는 것이어서 취득시효의 기초가 되는 점유라고 할 수 없다.","ox":"O","m":"③","c":"A","tp":"점유취득시효"},{"y":2021,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2021_27-36-4","t":"취득시효기간이 완성되었다고 하더라도 바로 소유권취득의 효력이 생기는 것이 아니라 이를 원인으로 하여 소유권취득을 위한 등기청구권이 발생하는 것에 불과하지만, 미등기 부동산이라는 특별한 사정이 있는 경우에는 등기 없이도 소유권을 취득한다.","ox":"X","m":"④","c":"A","tp":"점유취득시효"},{"y":2021,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2021_27-36-5","t":"취득시효가 완성된 점유자는 소유권이전등기를 마치기 전이라도 점유권에 기하여 등기부상의 명의인을 상대로 점유방해의 배제를 청구할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"점유취득시효"},{"y":2022,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2022_28-01-1","t":"종물이 타인의 소유라고 하더라도 그 타인의 권리를 해하지 아니하는 범위에서 민법 제100조가 적용된다고 할 것이고, 따라서 주물이 처분된 경우에 종물의 소유자가 동의 또는 추인하거나, 종물이 동산인 경우에 상대방이 선의취득의 요건을 갖추면 종물의 소유권을 취득하게 되는 것이며, 또한 동산의 선의취득을 주장하는 자는 점유취득시에 무과실이었다는 점을 주장·입증하여야 한다.","ox":"O","m":"①","c":"A","tp":"물건"},{"y":2022,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2022_28-01-2","t":"토지의 개수는 지적법에 의한 지적공부상의 토지의 필수를 표준으로 하여 결정되는 것으로 1필지의 토지를 수필의 토지로 분할하여 등기하려면 먼저 위와 같이 지적법이 정하는 바에 따라 분할의 절차를 밟아 지적공부에 각 필지마다 등록이 되어야 하고 지적법상의 분할절차를 거치지 아니하는 한 1개의 토지로서 등기의 목적이 될 수 없는 것이며, 설사 등기기록에만 분필의 등기가 실행되었다 하여도 이러한 분필등기는 1부동산1등기기록의 원칙에 반하는 등기로서 무효라 할 것이다.","ox":"O","m":"②","c":"A","tp":"물건"},{"y":2022,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2022_28-01-3","t":"민법 제201조 제1항에 의하면 선의의 점유자는 점유물의 과실을 취득한다고 규정하고 있고, 한편 건물을 사용함으로써 얻는 이득은 그 건물의 과실에 준하는 것이므로, 선의의 점유자는 비록 법률상 원인 없이 타인의 건물을 점유·사용하고 이로 말미암아 그에게 손해를 입혔다고 하더라도 그 점유·사용으로 인한 이득을 반환할 의무는 없다.","ox":"O","m":"③","c":"A","tp":"물건"},{"y":2022,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2022_28-01-4","t":"구분건물의 전유부분에 대한 소유권보존등기만 경료되고 대지지분에 대한 등기가 경료되기 전에 전유부분만에 대해 내려진 가압류결정의 효력은, 대지사용권의 분리처분이 가능하도록 규약으로 정하였다는 등의 특별한 사정이 없는 한, 종물 내지 종된 권리인 그 대지권에까지 미친다.","ox":"O","m":"④","c":"A","tp":"물건"},{"y":2022,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2022_28-01-5","t":"매매당사자가 토지의 실제 경계가 지적공부상의 경계와 상이한 것을 모르는 상태에서 실제의 경계를 대지의 경계로 알고 매매하였다면 매매당사자들이 지적공부상의 경계를 떠나 현실의 경계에 따라 매매목적물을 특정하여 매매한 것이라고 볼 수 있다.","ox":"X","m":"⑤","c":"A","tp":"물건"},{"y":2022,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2022_28-20-1","t":"공유지분의 포기는 법률행위로서 상대방 있는 단독행위에 해당하므로, 부동산 공유자의 공유지분 포기의 의사표시가 다른 공유자에게 도달하더라도 이로써 곧바로 공유지분 포기에 따른 물권변동의 효력이 발생하는 것은 아니고, 다른 공유자는 자신에게 귀속될 공유지분에 관하여 소유권이전등기청구권을 취득하며, 이후 민법 제186조에 의하여 등기를 하여야 공유지분 포기에 따른 물권변동의 효력이 발생한다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2022_28-20-2","t":"수인이 공동으로 소유하는 부동산에 관한 멸실회복등기는 공유자 중 1인이 공유자 전원의 이름으로 그 회복등기신청을 할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2022_28-20-3","t":"공유자 사이에 이미 분할에 관한 협의가 성립되었더라도 일부 공유자가 분할에 따른 이전등기에 협조하지 않거나 분할에 관하여 다툼이 있다면 다시 소로써 그 분할을 청구하거나 이미 제기한 공유물분할의 소를 유지함이 허용된다.","ox":"X","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2022_28-20-4","t":"공유자는 다른 공유자가 분할로 인하여 취득한 물건에 대하여 그 지분의 비율로 매도인과 동일한 담보책임이 있다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2022_28-20-5","t":"공유자 중 1인이 다른 공유자의 동의 없이 그 공유 토지의 특정부분을 매도하여 타인 명의로 소유권이전등기가 마쳐졌다면, 그 매도 부분 토지에 관한 소유권이전등기는 처분공유자의 공유지분 범위 내에서는 실체관계에 부합하는 유효한 등기라고 보아야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2022_28-21-1","t":"주위토지통행권자가 민법 제219조 제1항 본문에 따라 통로를 개설하는 경우 통행지 소유자는 원칙적으로 통행권자의 통행을 수인할 소극적 의무를 부담할 뿐 통로개설 등 적극적인 작위의무를 부담하는 것은 아니고, 다만 통행지 소유자가 주위토지통행권에 기한 통행에 방해가 되는 담장 등 축조물을 설치한 경우에는 주위토지통행권의 본래적 기능발휘를 위하여 통행지 소유자가 그 철거의무를 부담한다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2022_28-21-2","t":"포위된 토지가 사정변경에 의하여 공로에 접하게 되거나 포위된 토지의 소유자가 주위의 토지를 취득함으로써 주위토지통행권을 인정할 필요성이 없어지게 되었더라도, 통행지 소유자가 주위토지통행권자에게 그와 같은 사실을 통지하고 통지한 때로부터 상당한 기간이 경과한 뒤에야 주위토지통행권은 소멸한다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2022_28-21-3","t":"주위토지통행권은 그 소유 토지와 공로 사이에 그 토지의 용도에 필요한 통로가 없는 경우에 한하여 인정되는 것이므로, 이미 그 소유 토지의 용도에 필요한 통로가 있는 경우에는 그 통로를 사용하는 것보다 더 편리하다는 이유만으로 다른 장소로 통행할 권리를 인정할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2022_28-21-4","t":"주위토지통행권이 인정된다고 하더라도 통로를 상시적으로 개방하여 제한 없이 이용할 수 있도록 하거나 통행지 소유자의 관리권이 배제되어야만 하는 것은 아니므로, 쌍방 토지의 용도 및 이용 상황, 통행로 이용의 목적 등에 비추어 토지의 용도에 적합한 범위에서 통행 시기나 횟수, 통행방법 등을 제한하여 인정할 수도 있다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2022_28-21-5","t":"통행지의 소유자 이외의 제3자가 일정한 지위나 이해관계에서 통행권을 부인하고 그 행사를 방해할 때에는 그 제3자를 상대로 통행권의 확인 및 방해금지 청구를 하는 것이 통행권자의 지위나 권리를 보전하는 데에 유효·적절한 수단이 될 수 있다.","ox":"O","m":"⑤","c":"A","tp":"주위토지통행권"},{"y":2022,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2022_28-27-1","t":"부동산 실권리자명의 등기에 관한 법률(이하 ‘부동산실명법’이라 한다)을 위반하여 무효인 양자간 명의신탁약정에 따라 명의수탁자 명의로 등기를 한 경우 명의신탁자는 부동산 소유자로서 명의수탁자를 상대로 등기말소를 청구할 수 있다.","ox":"O","m":"①","c":"A","tp":"부동산 명의신탁"},{"y":2022,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2022_28-27-2","t":"부동산실명법이 시행되기 전에 명의신탁자와 명의수탁자가 명의신탁 약정을 맺고 이에 따라 명의수탁자가 당사자가 되어 명의신탁 약정이 있다는 사실을 알지 못하는 소유자와 부동산에 관한 매매계약을 체결한 후 그 매매계약에 기하여 당해 부동산의 소유권이전등기를 자신의 명의로 마치는 한편, 장차 위 부동산의 처분대가를 명의신탁자에게 지급하기로 하는 정산약정을 한 경우, 그러한 약정 이후에 부동산실명법이 시행되었거나 그 부동산의 처분이 부동산실명법 시행 이후에 이루어졌다면 위 정산약정도 당연히 무효가 된다.","ox":"X","m":"②","c":"A","tp":"부동산 명의신탁"},{"y":2022,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2022_28-27-3","t":"명의신탁자와 명의수탁자의 명의신탁약정에 기하여 명의수탁자 앞으로 부동산소유권이전등기가 마쳐진 후 명의수탁자가 이를 새로운 이해관계를 가진 제3자에게 처분한 경우에는 그 제3자에 대하여 명의신탁약정의 무효를 이유로 대항하지 못한다.","ox":"O","m":"③","c":"A","tp":"부동산 명의신탁"},{"y":2022,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2022_28-27-4","t":"부동산실명법 시행 이후 부동산을 매수하면서 매수대금의 실질적 부담자와 명의인 간에 명의신탁관계가 성립한 경우, 그들 사이에 매수대금의 실질적 부담자의 요구에 따라 부동산의 소유 명의를 이전하기로 하는 등의 약정을 하였다고 하더라도, 이는 무효인 명의신탁약정을 전제로 명의신탁 부동산 자체 또는 처분대금의 반환을 구하는 범주에 속하는 것이어서 역시 무효이다.","ox":"O","m":"④","c":"A","tp":"부동산 명의신탁"},{"y":2022,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2022_28-27-5","t":"계약명의자가 명의수탁자로 되어 있다 하더라도 계약당사자를 명의신탁자로 볼 수 있다면 이는 3자간 등기명의신탁이 되므로, 계약명의자인 명의수탁자가 아니라 명의신탁자에게 계약에 따른 법률효과를 직접 귀속시킬 의도로 매매계약을 체결한 사정이 인정되는 경우, 그 명의신탁관계는 3자간 등기명의신탁으로 보아야 한다.","ox":"O","m":"⑤","c":"A","tp":"부동산 명의신탁"},{"y":2023,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2023_29-09-1","t":"구분소유적 공유관계에 있는 토지 중 공유자 1인의 특정 구분소유 부분에 관한 점유취득시효가 완성된 경우라면, 다른 공유자의 특정 구분소유 부분이 타에 양도되고 그에 따라 토지 전체에 대한 공유지분에 관한 지분이전등기가 경료되었다 하더라도, 점유자는 취득시효의 기산점을 임의로 선택하여 주장할 수 있다.","ox":"X","m":"①","c":"A","tp":"부동산 점유취득시효"},{"y":2023,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2023_29-09-2","t":"시효완성 당시의 소유권보존등기 또는 이전등기가 무효라면 원칙적으로 그 등기명의인은 시효취득을 원인으로 한 소유권이전등기청구의 상대방이 될 수 없고, 이 경우 시효취득자는 소유자를 대위하여 위 무효등기의 말소를 구하고 다시 위 소유자를 상대로 취득시효완성을 이유로 한 소유권이전등기를 구하여야 한다.","ox":"O","m":"②","c":"A","tp":"부동산 점유취득시효"},{"y":2023,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2023_29-09-3","t":"점유로 인한 소유권취득시효 완성 당시 미등기로 남아 있던 토지에 관하여 소유권을 가지고 있던 자가 취득시효 완성 후에 그 명의로 소유권보존등기를 마쳤다 하더라도 이는 소유권의 변경에 관한 등기가 아니므로 그러한 자를 그 취득시효 완성 후의 새로운 이해관계인으로 볼 수 없다.","ox":"O","m":"③","c":"A","tp":"부동산 점유취득시효"},{"y":2023,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2023_29-09-4","t":"타인 소유의 토지에 분묘를 설치한 경우에 20년간 평온, 공연하게 분묘의 기지를 점유하면 지상권과 유사한 관습상의 물권인 분묘기지권을 시효로 취득한다는 점은 오랜 세월 동안 지속되어 온 관습 또는 관행으로서 법적 규범으로 승인되어 왔고, 이러한 법적 규범이 장사 등에 관한 법률(법률 제6158호) 시행일인 2001. 1. 13. 이전에 설치된 분묘에 관하여 현재까지 유지되고 있다고 보아야 한다.","ox":"O","m":"④","c":"A","tp":"부동산 점유취득시효"},{"y":2023,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2023_29-09-5","t":"점유자가 소유자를 상대로 소유권이전등기 청구소송을 제기하면서 그 청구원인으로 ‘취득시효 완성’이 아닌 ‘매매’를 주장함에 대하여, 소유자가 이에 응소하여 원고 청구기각의 판결을 구하면서 원고의 주장 사실을 부인하는 경우에는, 시효중단사유의 하나인 재판상의 청구에 해당한다고 할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"부동산 점유취득시효"},{"y":2023,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2023_29-19-1","t":"양도담보권의 목적인 주된 동산에 다른 동산이 부합되어 부합된 동산에 관한 권리자가 권리를 상실하는 손해를 입은 경우 주된 동산이 담보물로서 가치가 증가된 데 따른 실질적 이익은 주된 동산에 관한 양도담보권설정자뿐만 아니라 양도담보권자에게도 귀속되는 것이므로, 이 경우 부합으로 인하여 권리를 상실하는 자는 양도담보권자를 상대로 민법 제261조에 따라 보상을 청구할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2023_29-19-2","t":"건물의 증축 부분이 기존건물에 부합하여 기존건물과 분리하여서는 별개의 독립물로서의 효용을 갖지 못하는 이상 기존건물에 대한 근저당권은 민법 제358조에 의하여 부합된 증축 부분에도 효력이 미치는 것이므로 기존건물에 대한 경매절차에서 경매목적물로 평가되지 아니하였다고 할지라도 경락인은 부합된 증축 부분의 소유권을 취득한다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2023_29-19-3","t":"부동산에 부합된 물건이 사실상 분리복구가 불가능하여 거래상 독립된 권리의 객체성을 상실하고 그 부동산과 일체를 이루는 부동산의 구성부분이 된 경우에는 타인의 권원에 의하여 이를 부합시킨 경우에도 그 물건의 소유권은 부동산의 소유자에게 귀속된다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2023_29-19-4","t":"매도인에게 소유권이 유보된 자재가 제3자와 매수인 사이에 이루어진 도급계약의 이행으로 제3자 소유 건물의 건축에 사용되어 부합된 경우 보상청구를 거부할 법률상 원인이 있다고 할 수 없지만, 제3자가 도급계약에 의하여 제공된 자재의 소유권이 유보된 사실에 관하여 과실 없이 알지 못한 경우라면 선의취득의 경우와 마찬가지로 제3자가 그 자재의 귀속으로 인한 이익을 보유할 수 있는 법률상 원인이 있다고 봄이 상당하므로, 매도인으로서는 그에 관한 보상청구를 할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":19,"lv":3,"i":"법무사2023_29-19-5","t":"토지 위에 식재된 입목은 토지의 구성부분으로 토지의 일부일 뿐 독립한 물건으로 볼 수 없으므로 특별한 사정이 없는 한 토지에 부합하고, 토지의 소유자는 식재된 입목의 소유권을 취득한다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2023_29-24-1","t":"동업을 목적으로 한 조합이 조합체로서 또는 조합재산으로서 부동산의 소유권을 취득하였다면 당연히 그 조합체의 합유물이 되고, 다만 그 조합체가 합유등기를 하지 아니하고 그 대신 조합원들 명의로 각 지분에 관하여 공유등기를 하였다면 이는 그 조합체가 조합원들에게 각 지분에 관하여 명의신탁한 것으로 보아야 한다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2023_29-24-2","t":"부동산의 합유자 중 일부가 사망한 경우 합유자 사이에 특별한 약정이 없는 한 사망한 합유자의 상속인이 그 지분을 승계한다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2023_29-24-3","t":"은행에 공동명의로 예금을 하고 은행에 대하여 그 권리를 함께 행사하기로 한 경우에 만일 동업 자금을 공동명의로 예금한 경우라면 채권의 준합유관계에 있다고 볼 것이다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2023_29-24-4","t":"민법상 조합인 공동수급체가 경쟁입찰에 참가하였다가 다른 경쟁업체가 낙찰자로 선정된 경우, 그 공동수급체의 구성원 중 1인이 그 낙찰자 선정이 무효임을 주장하며 무효확인의 소를 제기하는 것은 합유재산의 보존행위에 해당한다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2023_29-24-5","t":"합유재산을 합유자 1인의 단독소유로 소유권보존등기를 한 경우에는 소유권보존등기가 실질관계에 부합하지 않는 원인무효의 등기이므로, 다른 합유자는 등기명의인인 합유자를 상대로 소유권보존등기 말소청구의 소를 제기하는 등의 방법으로 원인무효의 등기를 말소시킨 다음 새로이 합유의 소유권보존등기를 신청할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2023_29-36","t":"다음 설명 중 옳은 것(○)과 옳지 않은 것(×)을 올바르게 조합한 것은?","c":"A","mc":{"s":"다음 설명 중 옳은 것(○)과 옳지 않은 것(×)을 올바르게 조합한 것은?","d":"ㄱ.어떤 토지가 개설경위를 불문하고 일반 공중의 통행에 공용되는 도로, 즉 공로가 되면 그 부지의 소유권 행사는 제약을 받게 되며, 이는 소유자가 수인하여야 하는 재산권의 사회적 제약에 해당한다. 따라서 공로 부지의 소유자가 이를 점유ㆍ관리하는 지방자치단체를 상대로 공로로 제공된 도로의 철거, 점유 이전 또는 통행금지를 청구하는 것은 법질서상 원칙적으로 허용될 수 없는 ‘권리남용’이라고 보아야 한다.\nㄴ.매수인이 매도인 등의 기망행위로 인하여 부동산을 고가에 매수하게 됨으로써 입게 된 손해는 그 부동산의 매수 당시 시가와 매수가격과의 차액이지만, 그 후 매수인이 그 부동산 중 일부에 대하여 보상금을 수령하였다거나 부동산 시가가 상승하여 매수가격을 상회하게 되었다면 매수인에게 손해가 발생하지 않았다고 볼 수 있다.\nㄷ.채무불이행으로 인한 손해배상을 규정하고 있는 민법 제394조는 다른 의사표시가 없는 한 금전으로 배상하여야 한다고 규정하고 있는바, 위 법조 소정의 금전이라 함은 우리나라의 통화를 가리키는 것이어서, 채무불이행으로 인한 손해배상을 구하는 채권은 당사자가 외국통화로 지급하기로 약정하였다는 등의 특별한 사정이 없는 한 채권액이 외국통화로 지정된 외화채권이라고 할 수 없다.\nㄹ. 판결이 확정되면 기판력에 의하여 그 대상이 된 청구권의 존재가 확정되고 그 내용에 따라 집행력이 발생하는 것이므로, 확정판결의 내용이 실체적 권리관계에 배치되어 부당하고 또한 그 확정판결에 기한 집행채권자가 이를 알고 있었다면 그 집행행위에 대하여 불법행위가 성립한다고 할 수 있다.\nㅁ.어떠한 건물 신축이 건축 당시의 건축법 등 관계 법령의 일조방해에 관한 직접적인 단속법규에 위반하지 않는다면 현실적인 일조방해의 정도가 현저하게 커 사회통념상 수인한도를 넘은 경우라도 위법행위로 평가될 수는 없다.","o":["ㄱ(O), ㄴ(X), ㄷ(O), ㄹ(X), ㅁ(X)","ㄱ(O), ㄴ(O), ㄷ(O), ㄹ(X), ㅁ(X)","ㄱ(O), ㄴ(X), ㄷ(X), ㄹ(O), ㅁ(O)","ㄱ(X), ㄴ(O), ㄷ(X), ㄹ(X), ㅁ(O)","ㄱ(X), ㄴ(X), ㄷ(O), ㄹ(O), ㅁ(X)"],"a":1}},{"y":2024,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2024_30-11","t":"공유물의 소수지분권자인 피고가 다른 공유자와 협의하지 않고 공유물의 전부 또는 일부를 독점적으로 점유하는 경우, 다른 소수지분권자인 원고가 피고를 상대로 공유물의 인도를 청구하는 사안과 관련하여 다음 설명 중 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"공유물의 소수지분권자인 피고가 다른 공유자와 협의하지 않고 공유물의 전부 또는 일부를 독점적으로 점유하는 경우, 다른 소수지분권자인 원고가 피고를 상대로 공유물의 인도를 청구하는 사안과 관련하여 다음 설명 중 옳은 것을 모두 고른 것은?","d":"ㄱ.공유물의 소수지분권자인 피고가 다른 공유자와 협의하지 않고 공유물의 전부 또는 일부를 독점적으로 점유하는 경우 다른 소수지분권자인 원고가 피고를 상대로 공유물의 보존행위로서 공유물의 인도를 청구할 수는 없다.\nㄴ.원고도 피고와 마찬가지로 소수지분권자에 지나지 않으므로 원고가 공유자인 피고를 전면적으로 배제하고 자신만이 단독으로 공유물을 점유하도록 인도해 달라고 청구할 권원은 없다.\nㄷ.피고가 다른 공유자를 배제하고 단독 소유자인 것처럼 공유물을 독점하는 것은 위법하므로, 피고의 점유는 지분비율과 무관하게 공유물 전체의 범위에서 위법하다.\nㄹ.원고는 위와 같이 공유물의 보존행위로서 그 인도를 청구할 수는 없을 뿐만 아니라 자신의 지분권에 기초하여 공유물에 대한 방해 상태를 제거하거나 공동 점유를 방해하는 행위의 금지 등을 청구할 수도 없다.","o":["ㄱ","ㄱ, ㄴ","ㄱ, ㄴ, ㄷ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㄹ"],"a":2}},{"y":2024,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2024_30-20","t":"부동산 실권리자명의 등기에 관한 법률(이하 ‘부동산실명법’이라 한다)의 시행 후에 이루어진 명의신탁에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"부동산 실권리자명의 등기에 관한 법률(이하 ‘부동산실명법’이라 한다)의 시행 후에 이루어진 명의신탁에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","d":"㉠부동산실명법은 부동산등기제도를 악용한 투기․탈세․탈법행위 등 반사회적 행위를 방지하는 것 등을 목적으로 제정되었으므로 위 법률에 위반되어 무효인 명의신탁약정에 기하여 타인 명의의 등기가 마쳐졌다면 그것은 불법원인급여에 해당한다.\n㉡ 이른바 3자간 등기명의신탁의 경우 명의신탁약정과 그에 의한 등기가 무효로 되고 그 결과 명의신탁된 부동산은 여전히 매도인의 소유이므로, 매도인은 명의수탁자에게 무효인 그 명의 등기의 말소를 구할 수 있게 되고, 한편 매도인과 명의신탁자 사이의 매매계약은 여전히 유효하므로, 명의신탁자는 매도인에 대하여 매매계약에 기한 소유권이전등기를 청구할 수 있고, 그 소유권이전등기청구권을 보전하기 위하여 매도인을 대위하여 명의수탁자에게 무효인 그 명의 등기의 말소를 구할 수도 있다.\n㉢양자간 등기명의신탁에서 명의수탁자가 신탁부동산을 처분하여 제3취득자가 유효하게 소유권을 취득하고 이로써 명의신탁자가 신탁부동산에 대한 소유권을 상실하였다면, 명의신탁자의 소유권에 기한 물권적 청구권, 즉 소유권말소등기청구권이나 진정명의회복을 원인으로 한 소유권이전등기청구권도 더 이상 그 존재 자체가 인정되지 않지만, 그 후 명의수탁자가 우연히 신탁부동산의 소유권을 다시 취득하였다면 물권적 청구권도 인정되게 된다.\n㉣이른바 계약명의신탁약정을 맺고 명의수탁자가 당사자가 되어 명의신탁약정을 알지 못하는 소유자와 부동산에 관한 매매계약을 체결한 뒤 수탁자 명의로 소유권이전등기를 마친 경우, 명의수탁자는 명의신탁자에 대하여 부당이득반의무를 부담하게 되는데 이 때 명의수탁자는 당해 부동산 자체를 부당이득으로 반환해야 한다.\n㉤위 ㉡의 경우, 명의신탁약정의 목적물인 부동산을 인도받아 점유하고 있는 명의신탁자의 매도인에 대한 소유권이전등기청구권은 소멸시효가 진행되지 않는다.","o":["㉠, ㉢, ㉣","㉡, ㉢, ㉣","㉠, ㉤","㉡, ㉣, ㉤","㉢, ㉣, ㉤"],"a":1}},{"y":2024,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2024_30-24-1","t":"민법 제265조 단서가 공유물의 보존행위를 각 공유자가 단독으로 할 수 있도록 한 취지는 그 보존행위가 긴급을 요하는 경우가 많고 다른 공유자에게도 이익이 되는 것이 보통이기 때문이므로, 어느 공유자가 보존권을 행사하는 때에 그 행사의 결과가 다른 공유자의 이해와 충돌될 때에는 그 행사는 보존행위로 될 수 없다고 보아야 한다.","ox":"O","m":"①","c":"A","tp":"공동소유"},{"y":2024,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2024_30-24-2","t":"집합건물의 대지를 집합건물의 구분소유자인 공유자와 구분소유자가 아닌 공유자가 공유하고 있고, 당해 대지를 집합건물의 구분소유자인 공유자에게 취득시키고 구분소유자가 아닌 다른 공유자에게는 그 지분의 가격을 취득시키는 것이 공유자 간의 실질적인 공평을 해치지 않는다고 인정되는 특별한 사정이 있어 그와 같이 공유물을 분할하는 것이 허용되는 경우에는, 그러한 공유물에 대한 분할청구는 집합건물의 소유 및 관리에 관한 법률 제8조의 입법 취지에 비추어 허용된다고 보는 것이 타당하다.","ox":"O","m":"②","c":"A","tp":"공동소유"},{"y":2024,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2024_30-24-3","t":"합유물 가운데서도 조합재산의 경우 그 처분·변경에 관한 행위는 조합의 특별사무에 해당하는 업무집행으로서, 이에 대하여는 특별한 사정이 없는 한 민법 제706조 제2항이 민법 제272조에 우선하여 적용되므로, 조합재산의 처분·변경은 업무집행자가 없는 경우에는 조합원의 과반수로 결정하고, 업무집행자가 수인 있는 경우에는 그 업무집행자의 과반수로써 결정하며, 업무집행자가 1인만 있는 경우에는 그 업무집행자가 단독으로 결정한다.","ox":"O","m":"③","c":"A","tp":"공동소유"},{"y":2024,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2024_30-24-4","t":"여러 채권자가 같은 기회에 어느 부동산에 관하여 하나의 근저당권을 설정받아 이를 준공유하는 경우 피담보채권이 확정되기 전에는 근저당권에 대한 준공유비율을 정할 수 없으나 피담보채권액이 확정되면 각자 그 확정된 채권액의 비율에 따라 근저당권을 준공유하는 것이 되므로, 준공유자는 각기 그 채권액의 비율에 따라 변제받는 것이 원칙이고, 설령 준공유자 전원의 합의로 피담보채권의 확정 전에 위와 다른 비율을 정하거나 준공유자 중 일부가 먼저 변제받기로 약정하더라도 이는 외관을 신뢰한 제3자의 이익을 해할 수 있으므로, 준공유자들은 위와 같은 약정에 구속되지 않는다.","ox":"X","m":"④","c":"A","tp":"공동소유"},{"y":2024,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2024_30-24-5","t":"총유물의 보존에 있어서는 공유물의 보존에 관한 민법 제265조의 규정이 적용될 수 없고, 민법 제276조 제1항의 규정에 따른 사원총회의 결의를 거치거나 정관이 정하는 바에 따른 절차를 거쳐야 하므로, 법인 아닌 사단인 교회가 그 총유재산에 대한 보존행위로서 소송을 하는 경우에도 교인 총회의 결의를 거치거나 그 정관이 정하는 바에 따른 절차를 거쳐야 한다.","ox":"O","m":"⑤","c":"A","tp":"공동소유"},{"y":2024,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2024_30-31-1","t":"취득시효완성 당시 그 부동산의 등기부상 소유명의자는 취득시효완성으로 인한 권리변동의 당사자이나 그 등기가 실체관계와 부합하지 않는 무효의 등기인 때에는 권리변동의 당사자가 될 수 없는 것이므로, 소유권이전등기가 그 경료 당시에는 실체관계와 부합하지 아니하여 무효의 등기였다가 취득시효완성 후에 적법한 권리자로부터 권리를 양수하여 실체관계에 부합하게 된 것이라면, 그 등기명의자는 취득시효완성 후에 소유권을 취득한 자에 해당하지는 않으므로 그에 대하여 취득시효완성을 주장할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2024_30-31-2","t":"진정한 권리자가 아니었던 채무자 또는 물상보증인이 채무담보의 목적으로 채권자에게 부동산에 관하여 저당권설정등기를 경료해 준 후 그 부동산을 시효취득하는 경우에는, 채무자 또는 물상보증인은 피담보채권의 변제의무 내지 책임이 있는 사람으로서 이미 저당권의 존재를 용인하고 점유하여 온 것이므로, 저당목적물의 시효취득으로 저당권자의 권리는 소멸하지 않는다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2024_30-31-3","t":"양도담보권설정자가 양도담보부동산을 20년간 소유의 의사로 평온, 공연하게 점유하였다고 하더라도, 점유취득시효를 원인으로 하여 담보 목적으로 경료된 소유권이전등기의 말소를 구할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2024_30-31-4","t":"점유자의 취득시효 완성 후 소유자가 토지에 대한 권리를 주장하는 소를 제기하여 승소판결을 받은 사실이 있다고 하더라도 그 판결에 의하여 시효중단의 효력이 발생할 여지는 없고, 점유자가 그 소송에서 그 토지에 대한 시효취득을 주장하지 않았다고 하여 시효이익을 포기한 것이라고도 볼 수 없다.","ox":"O","m":"④","c":"A","tp":"부동산"},{"y":2024,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2024_30-31-5","t":"등기부취득시효의 요건으로서의 소유자로 등기한 자라 함은 적법·유효한 등기를 마친 자일 필요는 없고 무효의 등기를 마친 자라도 상관없으며, 등기부취득시효에서의 선의·무과실은 등기에 관한 것이 아니고 점유 취득에 관한 것이다.","ox":"O","m":"⑤","c":"A","tp":"부동산"},{"y":2025,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2025_31-12-1","t":"부동산의 공유자의 1인은 당해 부동산에 관하여 제3자 명의로 원인무효의 소유권이전등기가 마쳐져 있는 경우 공유물에 관한 보존행위로서 제3자에 대하여 그 등기 전부의 말소를 구할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2025_31-12-2","t":"공유자가 다른 공유자의 지분권을 대외적으로 주장하는 것을 공유물의 멸실·훼손을 방지하고 공유물의 현상을 유지하는 사실적·법률적 행위인 공유물의 보존행위에 속한다고 할 수는 없으므로, 자신의 소유지분 범위를 초과하는 부분에 관하여 마쳐진 등기에 대하여 공유물에 관한 보존행위로서 무효라고 주장하면서 말소를 구할 수는 없다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2025_31-12-3","t":"공유물에 관한 원인무효의 등기에 대하여 모든 공유자가 항상 공유물의 보존행위로서 말소를 구할 수 있는 것은 아니고, 원인무효의 등기로 인하여 자신의 지분이 침해된 공유자에 한하여 공유물의 보존행위로서 그 등기의 말소를 구할 수 있을 뿐이다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2025_31-12-4","t":"과반수 지분의 공유자는 다른 공유자와 사이에 미리 공유물의 관리방법에 관한 협의가 없었다면, 공유물의 관리에 관한 사항을 단독으로 결정할 수는 없다.","ox":"X","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2025_31-12-5","t":"과반수 지분의 공유자가 그 공유물의 특정 부분을 배타적으로 사용·수익하기로 정하는 것은 공유물의 관리방법으로서 적법하다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2025_31-25-1","t":"민법 제247조 제2항은 “소멸시효의 중단에 관한 규정은 점유로 인한 부동산소유권의 시효취득기간에 준용한다.”고 규정하고, 민법 제168조 제2호는 소멸시효 중단사유로 ‘압류 또는 가압류, 가처분’을 규정하고 있으므로, 취득시효기간의 완성 전에 부동산에 압류 또는 가압류 조치가 이루어지면 취득시효의 진행이 중단된다.","ox":"X","m":"①","c":"A","tp":"부동산 점유취득시효"},{"y":2025,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2025_31-25-2","t":"토지 매수인이 매매계약에 의하여 목적 토지의 점유를 취득한 경우 설사 그것이 타인의 토지의 매매에 해당하여 그에 의하여 곧바로 소유권을 취득할 수 없다고 하더라도, 그 사실만으로 바로 그 매수인의 점유가 소유의 의사가 있는 점유라는 추정이 깨어진다고 할 수 없다.","ox":"O","m":"②","c":"A","tp":"부동산 점유취득시효"},{"y":2025,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2025_31-25-3","t":"부동산점유취득시효는 원시취득에 해당하므로, 양도담보권설정자가 양도담보부동산을 20년간 소유의 의사로 평온, 공연하게 점유한 경우, 양도담보권자를 상대로 점유취득시효를 원인으로 하여 담보 목적으로 경료된 소유권이전등기의 말소를 구하거나 또는 이와 같은 효과가 있는 양도담보권설정자 명의로의 소유권이전등기를 구할 수도 있다.","ox":"X","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2025_31-25-4","t":"부동산 점유권원의 성질이 분명하지 않을 때에는 민법 제197조 제1항에 따라 점유자는 소유의 의사로 선의, 평온 및 공연하게 점유한 것으로 추정되는데, 이러한 추정은 지적공부 등의 관리주체인 국가나 지방자치단체가 점유하는 경우에는 적용되지 아니한다.","ox":"X","m":"④","c":"A","tp":"부동산 점유취득시효"},{"y":2025,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2025_31-25-5","t":"취득시효의 대상이 미등기 부동산인 경우, 취득시효 기간이 완성되면 점유자는 등기 없이도 그 부동산의 소유권을 취득한다.","ox":"X","m":"⑤","c":"A","tp":"부동산 점유취득시효"},{"y":2025,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2025_31-30-1","t":"미등기 무허가건물에 관한 매매계약이 해제되기 전에 매수인으로부터 해당 무허가건물을 다시 매수하고 무허가건물관리대장에 소유자로 등재되었다고 하더라도 건물에 관하여 완전한 권리를 취득한 것으로 볼 수 없으므로 민법 제548조 제1항 단서에서 규정하는 제3자에 해당한다고 할 수 없다.","ox":"O","m":"①","c":"A","tp":"미등기 건물"},{"y":2025,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2025_31-30-2","t":"건물 소유를 목적으로 하는 토지 임대차에서 종전 임차인으로부터 미등기 무허가건물을 매수하여 점유하고 있는 임차인은 특별한 사정이 없는 한 비록 소유자로서의 등기명의가 없어 소유권을 취득하지 못하였다 하더라도 임대인에 대하여 지상물매수청구권을 행사할 수 있는 지위에 있다.","ox":"O","m":"②","c":"A","tp":"미등기 건물"},{"y":2025,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2025_31-30-3","t":"소액임차인의 우선변제권에 관한 주택임대차보호법 제8조 제1항은 그 후문에서 ‘임차인은 주택에 대한 경매신청의 등기 전에’ 대항요건을 갖추어야 한다고 규정하고 있으므로, 위 규정에 의해 건물이나 토지의 매각대금에서 우선변제를 받기 위해서는 그 임대차의 목적물인 주택에 관하여 임대차 후에라도 소유권등기가 거쳐져 경매신청의 등기가 되는 경우이어야 한다.","ox":"X","m":"③","c":"A","tp":"미등기 건물"},{"y":2025,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2025_31-30-4","t":"미등기 무허가건물의 양수인이라 할지라도 그 소유권이전등기를 경료받지 않는 한 건물에 대한 소유권을 취득할 수 없고, 그러한 건물의 취득자에게 소유권에 준하는 관습상의 물권이 있다고 볼 수 없다.","ox":"O","m":"④","c":"A","tp":"미등기 건물"},{"y":2025,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2025_31-30-5","t":"건축허가나 신고 없이 건축된 미등기 건물에 대하여는 경매에 의한 공유물분할이 허용되지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2025_31-37","t":"부동산 실권리자명의 등기에 관한 법률(이하 ‘부동산실명법’이라 한다) 제4조 제3항에 의하면 명의신탁약정 및 이에 따른 등기로 이루어진 부동산에 관한 물권변동의 무효는 제3자에게 대항하지 못한다. 위 조항에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"부동산 실권리자명의 등기에 관한 법률(이하 ‘부동산실명법’이라 한다) 제4조 제3항에 의하면 명의신탁약정 및 이에 따른 등기로 이루어진 부동산에 관한 물권변동의 무효는 제3자에게 대항하지 못한다. 위 조항에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["명의수탁자가 신탁부동산을 임의로 처분하거나 강제수용이나 공공용지 협의취득 등을 원인으로 제3취득자 명의로 이전등기가 마쳐진 경우, 특별한 사정이 없는 한 제3취득자는 유효하게 소유권을 취득하고 이 경우 명의신탁관계는 당사자의 의사표시 등을 기다릴 필요 없이 당연히 종료되었다고 볼 것이다.","여기서 ‘제3자’는 명의신탁약정의 당사자 및 포괄승계인 이외의 자로서 명의수탁자가 물권자임을 기초로 그와 사이에 직접 새로운 이해관계를 맺은 사람으로서 소유권이나 저당권 등 물권을 취득한 자뿐만 아니라 압류 또는 가압류채권자도 포함하고 그의 선의․악의를 묻지 않는다.","위 ②의 법리는 특별한 사정이 없는 한 명의신탁약정에 따라 형성된 외관을 토대로 다시 명의신탁이 이루어지는 등 연속된 명의신탁관계에서 최후의 명의수탁자가 물권자임을 기초로 그와 사이에 직접 새로운 이해관계를 맺은 사람에게도 적용된다.","사립학교법 제28조 제1항은 학교법인이 기본재산에 대한 처분행위를 하고자 할 때에는 관할청의 허가를 받아야 한다고 규정하고 있다. 부동산실명법 소정의 유예기간 내에 실명등기 등을 하지 아니함으로써 종전의 명의신탁약정 및 그에 따른 등기에 의한 부동산의 물권변동이 무효가 되는 경우 명의신탁자는 명의수탁자를 상대로 원인무효를 이유로 직접 또는 대위하여 등기 말소를 구할 수 있고, 명의신탁자 명의로 소유권을 표상하는 등기가 되어 있었거나 명의신탁자가 법률에 의하여 소유권을 취득한 진정한 소유자라는 사정이 있다면 등기명의를 회복하기 위한 방법으로 진정명의회복을 원인으로 한 소유권이전등기절차이행을 구할 수도 있는바, 명의신탁자가 학교법인의 기본재산으로 등기되어 있는 부동산에 관하여 그와 같은 이유로 등기 말소 또는 진정명의회복을 원인으로 한 소유권이전등기절차이행을 구하는 경우에 이는 사립학교법 제28조 제1항에 근거하여 관할청 허가가 필요하다고 보아야 한다.","오로지 명의신탁자와 부동산에 관한 물권을 취득하기 위한 계약을 맺고 단지 등기명의만을 명의수탁자로부터 경료받은 것 같은 외관을 갖춘 자는 위 법률조항의 제3자에 해당되지 아니한다고 할 것이므로 이러한 자로서는 자신의 등기가 실체관계에 부합하여 유효라고 주장하는 것은 별론으로 하더라도 부동산실명법 제4조 제3항의 규정을 들어 무효인 명의신탁등기에 터 잡아 경료된 자신의 등기의 유효를 주장할 수는 없다."],"a":4}},{"y":2026,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2026_32-06-1","t":"甲 소유 토지 위에 乙 등이 건물을 공유하며 그 건물의 소유를 통해 위 토지를 점유하고 있는 경우, 甲은 건물의 철거를 구할 수 있음은 별론으로 하고 건물 공유자인 乙 등을 상대로 건물에서 퇴거할 것을 청구할 수는 없다.","ox":"O","m":"①","c":"A","tp":"물권"},{"y":2026,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2026_32-06-2","t":"소유권에 기초하여 부동산을 점유하는 경우 이는 자기 소유 부동산에 대한 점유이므로 취득시효의 기초가 되는 점유로 인정될 수 없다.","ox":"X","m":"②","c":"A","tp":"물권"},{"y":2026,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2026_32-06-3","t":"공유물분할판결에서 가격배상의 방법에 의할 때 기준이 되는 지분가격은, 시가 변동 사정을 고려할 필요 없이 감정평가액에만 의존하여 산정하면 충분하다.","ox":"X","m":"③","c":"A","tp":"물권"},{"y":2026,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2026_32-06-4","t":"건축허가상 공동건축주 중 1인이 자신의 지분을 타인에게 양도하기로 약정하였다면, 별도의 법령이나 약정상 근거가 없더라도 나머지 공동건축주는 당연히 건축주 명의변경에 동의할 의무를 부담한다.","ox":"X","m":"④","c":"A","tp":"물권"},{"y":2026,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2026_32-06-5","t":"토지 소유자가 스스로 토지를 도로로 제공하여 독점적⋅배타적인 사용⋅수익권을 포기하였다면, 이후 그 토지를 둘러싼 사정에 중대한 변경이 생기더라도 소유자는 완전한 소유권에 기한 권리를 다시 주장할 수 없다.","ox":"X","m":"⑤","c":"A","tp":"물권"},{"y":2026,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2026_32-08-1","t":"상호명의신탁관계 내지 구분소유적 공유관계에서 건물의 특정 부분을 구분소유하는 자는 그 부분에 대하여 신탁적으로 지분등기를 가지고 있는 자를 상대로 하여 그 특정 부분에 대한 명의신탁 해지를 원인으로 한 지분이전등기절차의 이행을 구할 수 있을 뿐 그 건물 전체에 대한 공유물분할을 구할 수는 없다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2026_32-08-2","t":"과세관청이 3자간 등기명의신탁에 따라 해당 부동산의 공부상 소유자가 된 명의수탁자에게 재산세 부과처분을 하고 이에 따라 명의수탁자가 재산세를 납부하였더라도 명의수탁자가 명의신탁자 또는 그 상속인을 상대로 재산세 상당의 금액에 대한 부당이득반환청구권을 가진다고 보기는 어렵다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2026_32-08-3","t":"3자간 등기명의신탁에서 명의수탁자가 제3자에게 부동산을 매도하거나 부동산에 관하여 근저당권을 설정하는 등으로 처분행위를 하여 제3자가 부동산 실권리자명의 등기에 관한 법률 제4조 제3항에 따라 부동산에 관한 권리를 취득하게 되는 경우, 처분대금과 같이 처분과정에서 명의수탁자가 얻은 이익에 관하여 명의신탁자는 명의수탁자를 상대로 직접 부당이득반환을 청구할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2026_32-08-4","t":"명의신탁자와 명의수탁자가 명의신탁약정을 맺고 그에 따라 명의수탁자가 당사자가 되어 소유자와 부동산 매매계약을 체결하는 계약명의신탁의 경우, 명의신탁자가 명의신탁약정에 따라 부동산을 점유하더라도 명의신탁자에게 점유할 다른 권원이 인정되는 등의 특별한 사정이 없는 한 명의신탁자는 소유권 취득의 원인이 되는 법률요건이 없이 그와 같은 사실을 잘 알면서 타인의 부동산을 점유한 것이므로, 소유의 의사로 점유한다는 추정은 깨어진다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2026_32-08-5","t":"명의신탁자와 명의수탁자가 계약명의신탁약정을 맺고 명의수탁자가 당사자가 되어 매도인과 부동산에 관한 매매계약을 체결하는 경우 그 계약과 등기의 효력은 매매계약을 체결할 당시 매도인의 인식뿐만 아니라 그 이후의 사정까지 종합적으로 고려하여 판단해야 하므로, 매도인이 매매계약을 체결할 당시에는 명의신탁약정 사실을 인식하지 못하였더라도 계약 체결 이후 명의신탁약정 사실을 알게 되었다면, 매매계약은 소급적으로 무효가 된다고 보아야 한다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2026_32-16-1","t":"집합건물의 소유 및 관리에 관한 법률 제8조는 집합건물의 존립 기초 확보를 위해 대지공유자의 분할청구를 원칙적으로 금지하지만, 집합건물의 구분소유자인 공유자에게 대지를 취득시키고 구분소유자 아닌 다른 공유자에게는 그 지분의 가격을 취득시키는 것이 실질적 공평을 해치지 않는다고 인정되는 특별한 사정이 있는 경우에는 예외적으로 공유물분할 청구가 허용될 수 있다.","ox":"O","m":"①","c":"A","tp":"집합건물과 공유"},{"y":2026,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2026_32-16-2","t":"집합건물의 구분소유자들이 건물의 대지 중 일부 지분만 가지고 있고 구분소유자 아닌 대지공유자가 나머지 지분을 가진 경우, 구분소유자 중 자신의 전유부분 면적 비율에 상응하는 적정 대지지분보다 부족한 대지지분을 가진 구분소유자는 특별한 사정이 없는 한 부당이득반환의무를 부담하지 않는다.","ox":"X","m":"②","c":"A","tp":"집합건물과 공유"},{"y":2026,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2026_32-16-3","t":"공유물분할의 소에서 법원은 청구인이 구하는 방법에 구속되며, 재량으로 그와 다른 방법을 선택할 수 없다.","ox":"X","m":"③","c":"A","tp":"집합건물과 공유"},{"y":2026,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2026_32-16-4","t":"대지공유자 중 일부가 대지에 적법하게 건축된 건물을 철거하게 하는 행위는 공유물의 이용⋅개량행위에 해당할 뿐, 공유물인 대지의 변경에는 해당하지 않는다.","ox":"X","m":"④","c":"A","tp":"집합건물과 공유"},{"y":2026,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2026_32-16-5","t":"민법 제268조에 따라 공유자는 언제든지 공유물의 분할을 청구할 수 있는 것이 원칙이나, 공유자들이 10년 내의 기간으로 분할하지 아니할 것을 약정할 수 있다.","ox":"X","m":"⑤","c":"A","tp":"집합건물과 공유"},{"y":2026,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2026_32-17-1","t":"‘배타적 사용·수익권의 포기’ 법리는 대법원이 오랜 시간에 걸쳐 발전시켜 온 것으로서, 현재에도 여전히 그 타당성을 인정할 수 있지만, 토지 소유자의 독점적이고 배타적인 사용·수익권 행사의 제한 여부를 판단하기 위해서는 토지 소유자의 소유권 보장과 공공의 이익 사이의 비교형량을 하여야 하고, 원소유자의 독점적·배타적인 사용·수익권 행사가 제한되는 경우에도 특별한 사정이 있다면 특정승계인의 독점적·배타적인 사용·수익권 행사가 허용될 수 있다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2026_32-17-2","t":"미등기 무허가건물의 양수인은 그 소유권이전등기를 경료받지 않는 한 그 건물에 대한 소유권을 취득할 수 없지만, 건물을 신축하여 그 소유권을 원시취득한 자로부터 그 건물을 매수하였으나 아직 소유권이전등기를 갖추지 못한 경우에는 그 건물의 불법점거자에 대하여 직접 자신의 소유권 등에 기하여 명도를 청구할 수는 있다.","ox":"X","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2026_32-17-3","t":"민법 제249조에 따른 선의취득에 있어서 평온, 공연하게 선의로 점유한 것으로 추정되지만, 무과실은 추정되지 않는다.","ox":"O","m":"③","c":"A","tp":"소유권"},{"y":2026,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2026_32-17-4","t":"부동산점유취득시효는 20년의 시효기간이 완성한 것만으로 점유자가 곧바로 소유권을 취득하는 것은 아니고 점유자 명의로 등기를 함으로써 소유권을 취득하게 되고, 이는 원시취득에 해당한다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":17,"lv":3,"i":"법무사2026_32-17-5","t":"어떠한 동산이 민법 제256조에 의하여 부동산에 부합된 것으로 인정되기 위해서는 그 동산을 훼손하거나 과다한 비용을 지출하지 않고서는 분리할 수 없을 정도로 부착·합체되었는지 여부 및 그 물리적 구조, 용도와 기능면에서 기존 부동산과는 독립한 경제적 효용을 가지고 거래상 별개의 소유권의 객체가 될 수 있는지 여부 등을 종합하여 판단하여야 할 것이고, 이러한 부동산에의 부합에 관한 법리는 건물의 증축의 경우는 물론 건물의 신축의 경우에도 그대로 적용될 수 있다.","ox":"O","m":"⑤","c":"A"}],"7":[{"y":2016,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2016_22-20-1","t":"채무초과 상태의 채무자가 그의 유일한 재산을 우선변제권 있는 채권자에게 대물변제로 제공한 행위는 특별한 사정이 없는 한 다른 채권자들의 이익을 해한다고 볼 수 없어 사해행위가 되지 않는다.","ox":"O","m":"①","c":"A","tp":"채권자취소권"},{"y":2016,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2016_22-20-2","t":"사해행위가 채권자에 의하여 취소되기 전에 이미 수익자가 배당금을 현실로 지급받은 경우, 채권자는 원상회복방법으로 수익자를 상대로 배당 금원 중 자신의 채권액 상당의 지급을 가액배상의 방법으로 청구할 수 있다.","ox":"O","m":"②","c":"A","tp":"채권자취소권"},{"y":2016,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2016_22-20-3","t":"가등기에 기하여 본등기가 경료된 경우 가등기의 원인인 법률행위와 본등기의 원인인 법률행위가 명백히 다른 것이 아닌 한 사해행위 요건의 구비 여부는 가등기의 원인된 법률행위 당시를 기준으로 하여 판단하여야 한다.","ox":"O","m":"③","c":"A","tp":"채권자취소권"},{"y":2016,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2016_22-20-4","t":"채무자가 채권자와 신용카드가입계약을 체결하고 신용카드를 발급받았으나 자신의 유일한 부동산을 매도한 후에 비로소 신용카드를 사용하기 시작하여 신용카드대금을 연체하게 된 경우, 그 신용카드대금채권은 사해행위 이후에 발생한 채권이지만, 위 신용카드가입계약을 ‘채권성립의 기초가 되는 법률관계’로 볼 수 있는 이상 사해행위의 피보전채권이 될 수 있다.","ox":"X","m":"④","c":"A","tp":"채권자취소권"},{"y":2016,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2016_22-20-5","t":"채권자가 가등기의 원인행위가 사해행위임을 안 때부터 1년 내에 가등기의 원인행위에 대하여 취소의 소를 제기하였다면 본등기의 원인행위에 대한 취소 청구는 그 원인행위에 대한 제척기간이 경과한 후 제기하더라도 적법하다.","ox":"O","m":"⑤","c":"A","tp":"채권자취소권"},{"y":2016,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2016_22-26-1","t":"이행기의 정함이 없는 지명채권을 양수한 채권양수인이 채무자를 상대로 그 이행을 구하는 소를 제기하고 그 소송 계속 중 채무자에 대한 채권양도통지가 이루어진 경우에는 특별한 사정이 없는 한 채무자는 그 채권양도통지가 도달된 다음 날부터 이행지체의 책임을 진다.","ox":"O","m":"①","c":"A","tp":"이행기 또는 이행지체"},{"y":2016,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2016_22-26-2","t":"반환시기의 약정이 없는 소비대차의 경우 대주가 상당한 기간을 정하여 반환을 최고한 후 그 기간을 경과하여야 지체책임이 발생한다.","ox":"O","m":"②","c":"A","tp":"이행기 또는 이행지체"},{"y":2016,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2016_22-26-3","t":"지시채권이나 무기명채권의 채무자는 증서에 변제기한이 있는 경우에도 그 기한이 도래한 후에 소지인이 증서를 제시하여 이행을 청구한 때로부터 지체책임이 있다.","ox":"O","m":"③","c":"A","tp":"이행기 또는 이행지체"},{"y":2016,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2016_22-26-4","t":"제3채무자가 압류채권자에게 압류된 채권액 상당에 관하여 지체책임을 지는 것은 집행법원으로부터 추심명령을 송달받은 때부터가 아니라, 추심명령이 발령된 후 압류채권자로부터 추심금 청구를 받은 다음날부터라고 할 것이다.","ox":"O","m":"④","c":"A","tp":"이행기 또는 이행지체"},{"y":2016,"e":"법무사 1차","qn":26,"lv":3,"i":"법무사2016_22-26-5","t":"채권의 가압류는 제3채무자에 대하여 채무자에게 지급하는 것을 금지시키므로, 가압류가 있는 경우 그 채권의 이행기가 도래하더라도 제3채무자는 지체책임을 지지 않는다.","ox":"X","m":"⑤","c":"A","tp":"이행기 또는 이행지체"},{"y":2016,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2016_22-35-1","t":"민법 제398조 제2항의 적용에 따라 손해배상의 예정액이 부당하게 과다한지의 여부 내지 그에 대한 적당한 감액의 범위를 판단하는 데 있어서는, 손해배상액을 예정할 당시의 사정만을 기준으로 판단하는 것이 원칙이고, 특별한 사정이 있는 경우에 한하여 사실심의 변론종결 당시를 기준으로 하여 판단한다.","ox":"X","m":"①","c":"A","tp":"손해배상액의 예정"},{"y":2016,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2016_22-35-2","t":"채무불이행으로 인한 손해배상액의 예정이 있는 경우에는 채권자는 채무불이행 사실만 증명하면 손해의 발생 및 그 액을 증명하지 않고 예정배상액을 청구할 수 있고, 채무자는 채권자와 채무불이행에 있어 채무자의 귀책사유를 묻지 않는다는 약정을 하지 않은 이상 자신의 귀책사유가 없음을 주장ㆍ증명함으로써 위 예정배상액의 지급책임을 면할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2016_22-35-3","t":"민법 제398조가 규정하는 손해배상의 예정은 채무불이행의 경우에 채무자가 지급하여야 할 손해배상액을 미리 정해두는 것으로서 그 목적은 손해의 발생사실과 손해액에 대한 입증곤란을 배제하고 분쟁을 사전에 방지하여 법률관계를 간이하게 해결하는 것 외에 채무자에게 심리적으로 경고를 줌으로써 채무이행을 확보하려는 데에 있으므로, 채무자가 실제로 손해발생이 없다거나 손해액이 예정액보다 적다는 것을 입증하더라도 채무자는 그 예정액의 지급을 면하거나 감액을 청구하지 못한다.","ox":"O","m":"③","c":"A","tp":"손해배상액의 예정"},{"y":2016,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2016_22-35-4","t":"위약벌의 약정은 채무의 이행을 확보하기 위하여 정해지는 것으로서 손해배상의 예정과는 그 내용이 다르므로 손해배상의 예정에 관한 민법 제398조 제2항을 유추적용하여 그 액을 감액할 수는 없다.","ox":"O","m":"④","c":"A","tp":"손해배상액의 예정"},{"y":2016,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2016_22-35-5","t":"법원이 손해배상의 예정액을 부당히 과다하다고 하여 감액하려면 채권자와 채무자의 경제적 지위, 계약의 목적과 내용, 손해배상액을 예정한 경위와 동기, 채무액에 대한 예정액의 비율, 예상 손해액의 크기, 당시의 거래 관행과 경제상태 등을 참작한 결과 손해배상 예정액의 지급이 경제적 약자의 지위에 있는 채무자에게 부당한 압박을 가하여 공정을 잃는 결과를 초래한다고 인정되는 경우라야 하고, 단지 예정액 자체가 크다든가 계약 체결 시부터 계약 해제 시까지의 시간적 간격이 짧다든가 하는 사유만으로는 부족하다.","ox":"O","m":"⑤","c":"A","tp":"손해배상액의 예정"},{"y":2016,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2016_22-38-1","t":"채권자가 자기채권을 보전하기 위하여 채무자의 권리를 행사하려면 채무자의 무자력을 요건으로 하는 것이 통상이고, 임대차보증금반환채권을 양수한 채권자가 그 이행을 청구하기 위하여 임차인의 가옥명도가 선 이행되어야 할 필요가 있어서 그 명도를 구하는 경우에도 채무자의 무자력을 요건으로 한다.","ox":"X","m":"①","c":"A","tp":"채권자대위권"},{"y":2016,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2016_22-38-2","t":"채권자는 채무자에 대한 채권을 보전하기 위하여 채무자를 대위해서 채무자의 권리를 행사할 수 있는데, 채권자가 보전하려는 권리와 대위하여 행사하려는 채무자의 권리가 밀접하게 관련되어 있고 채권자가 채무자의 권리를 대위하여 행사하지 않으면 자기 채권의 완전한 만족을 얻을 수 없게 될 위험이 있어 채무자의 권리를 대위하여 행사하는 것이 자기 채권의 현실적 이행을 유효ㆍ적절하게 확보하기 위하여 필요한 경우에는 채권자대위권의 행사가 채무자의 자유로운 재산관리행위에 대한 부당한 간섭이 된다는 등의 특별한 사정이 없는 한 채권자는 채무자의 권리를 대위하여 행사할 수 있어야 한다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2016_22-38-3","t":"채권자대위권은 채무자가 제3채무자에 대한 권리를 행사하지 아니하는 경우에 한하여 채권자가 자기의 채권을 보전하기 위하여 행사할 수 있는 것이어서, 채권자가 대위권을 행사할 당시에 이미 채무자가 그 권리를 재판상 행사하였을 때에는 채권자는 채무자를 대위하여 채무자의 권리를 행사할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2016_22-38-4","t":"채권자대위권을 행사함에 있어서 채권자가 제3채무자에 대하여 자기에게 직접 급부를 요구하여도 상관없는 것이고 자기에게 급부를 요구하여도 어차피 그 효과는 채무자에게 귀속되는 것이므로, 채권자대위권을 행사하여 채권자가 제3채무자에게 그 명의의 소유권보존등기나 소유권이전등기의 말소절차를 직접 자기에게 이행할 것을 청구하여 승소하였다고 하여도 그 효과는 원래의 소유자인 채무자에게 귀속되는 것이니, 법원이 채권자대위권을 행사하는 채권자에게 직접 말소등기 절차를 이행할 것을 명하였다고 하여 무슨 위법이 있다고 할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2016_22-38-5","t":"채권자는 자기의 채권을 보전하기 위하여 채무자의 권리를 행사할 수 있다. 그러나 일신에 전속한 권리는 그러하지 아니하다.","ox":"O","m":"⑤","c":"A","tp":"채권자대위권"},{"y":2017,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2017_23-27-1","t":"확정기한이 있는 금전채권에 관하여 가압류가 있다 하여도 그 채권의 이행기가 도래한 때에는 제3채무자는 그 지체책임을 면할 수 없다.","ox":"O","m":"①","c":"A","tp":"이행지체"},{"y":2017,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2017_23-27-2","t":"불법행위로 인한 손해배상채무에 대하여는 별도의 이행 최고가 없더라도 채무성립과 동시에 지연손해금이 발생하는 것이 원칙이다.","ox":"O","m":"②","c":"A","tp":"이행지체"},{"y":2017,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2017_23-27-3","t":"쌍무계약의 당사자 일방이 먼저 일시적으로 현실의 제공을 하고 상대방을 수령지체에 빠지게 하였더라도, 그 이행 제공이 계속되지 않는 한 동시이행항변권은 부활하게 되므로 그 이후로는 상대방의 의무가 이행지체 상태에 빠진 것으로 볼 수 없고, 따라서 이행지체를 전제로 하는 손해배상청구도 할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2017_23-27-4","t":"매수인이 선이행하여야 할 중도금지급을 하지 아니한 채 잔대금지급일을 경과한 경우, 매수인의 중도금 및 잔대금 지급채무와 매도인의 소유권이전등기의무는 특별한 사정이 없는 한 서로 동시이행관계에 있게 되나, 매수인의 중도금 지급 다음날부터 잔대금 지급일까지의 지연손해금 채권은 여전히 이행지체 상태로 유지된다.","ox":"X","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2017_23-27-5","t":"매수인이 매도인으로부터 물품을 공급받은 다음 그들 사이의 물품대금 지급방법에 관한 약정에 따라 그 대금의 지급을 위하여 매도인에게 지급기일이 물품 공급일자 이후로 된 약속어음을 발행ㆍ교부한 경우 물품대금 지급채무의 이행기는 그 약속어음의 지급기일이 되고, 이는 그 약속어음이 그 지급기일 이전에 지급거절된 경우도 마찬가지이다.","ox":"O","m":"⑤","c":"A","tp":"이행지체"},{"y":2017,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2017_23-28-1","t":"상소의 제기와 마찬가지로 종전 재심대상판결에 대하여 불복하여 종전 소송절차의 재개, 속행 및 재심판을 구하는 재심의 소제기는 채권자대위권의 목적이 될 수 없다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2017_23-28-2","t":"매수인이 매도인에 대하여 가지는 토지거래허가신청 절차의 협력의무의 이행청구권도 채권자대위권의 행사에 의하여 보전될 수 있는 채권에 해당한다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2017_23-28-3","t":"채권자가 양수한 임차보증금의 이행을 청구하기 위하여 임차인의 가옥명도가 선이행되어야 할 필요가 있어서 그 명도를 구하는 경우에는 그 채권의 보전과 채무자인 임대인의 자력유무는 관계가 없는 일이므로 무자력을 요건으로 한다고 할 수 없다.","ox":"O","m":"③","c":"A","tp":"채권자대위권"},{"y":2017,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2017_23-28-4","t":"채권자대위소송을 제기한 경우, 제3채무자는 채권자의 채무자에 대한 권리의 발생원인이 된 법률행위가 무효라거나 위 권리가 변제 등으로 소멸하였다는 등의 사실을 주장하여 채권자의 채무자에 대한 권리가 인정되는지 여부를 다툴 수 있다.","ox":"O","m":"④","c":"A","tp":"채권자대위권"},{"y":2017,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2017_23-28-5","t":"유류분반환청구권은 그 재산권적 성격에 의하여 원칙적으로 채권자대위권의 목적이 될 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2017_23-29-1","t":"사해행위취소소송에 있어서 수익자가 사해행위임을 몰랐다는 사실은 그 수익자 자신에게 증명책임이 있고, 이때 수익자의 선의를 인정함에 있어서는 객관적이고 납득할 만한 증거자료 등에 의하여야 한다.","ox":"O","m":"①","c":"A","tp":"채권자취소권"},{"y":2017,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2017_23-29-2","t":"협의 또는 심판에 의하여 구체화되지 않은 재산분할청구권은 채무자의 책임재산에 해당하지 아니하고 이를 포기하는 행위 또한 채권자취소권의 대상이 될 수 없다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2017_23-29-3","t":"채무자가 연속하여 수개의 재산행위를 한 경우에는 채권자취소권에 관하여 각 행위별로 그로 인하여 무자력이 초래되었는지 여부에 따라 사해성을 판단하는 것이 원칙이다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2017_23-29-4","t":"부동산을 양도받아 소유권이전등기청구권을 가지고 있는 자가 양도인이 제3자에게 이를 이중으로 양도하여 소유권이전등기를 경료하여 줌으로써 취득하는 부동산 가액 상당의 손해배상채권은 이중양도행위에 대한 사해행위취소권을 행사할 수 있는 피보전권리에 해당하지 않는다.","ox":"O","m":"④","c":"A","tp":"채권자취소권"},{"y":2017,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2017_23-29-5","t":"가등기에 기하여 본등기가 경료된 경우 가등기의 원인인 법률행위와 본등기의 원인인 법률행위가 명백히 다른 것이 아닌 한 사해행위 요건의 구비 여부는 본등기가 마쳐진 당시를 기준으로 하여 판단하여야 한다.","ox":"X","m":"⑤","c":"A","tp":"채권자취소권"},{"y":2018,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2018_24-02-1","t":"채무의 이행이 불능이라는 것은 단순히 절대적⋅물리적으로 불능인 경우가 아니라 사회생활에 있어서의 경험법칙 또는 거래상의 관념에 비추어 볼 때 채권자가 채무자의 이행의 실현을 기대할 수 없는 경우를 말한다.","ox":"O","m":"①","c":"A","tp":"이행불능"},{"y":2018,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2018_24-02-2","t":"매매목적물에 관하여 이중으로 제3자와 매매계약을 체결하였다는 사실만 가지고는 매매계약이 법률상 이행불능이라고 할 수 없으나, 부동산을 이중매도하고 매도인이 그 중 1인에게 먼저 소유권명의를 이전하여 준 경우에는 특별한 사정이 없는 한 다른 1인에 대한 소유권이전등기의무는 이행불능상태가 된다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2018_24-02-3","t":"채무자가 채무의 발생원인 내지 존재에 관한 법률적인 판단을 통하여 자신의 채무가 없다고 믿고 채무의 이행을 거부한 채 소송을 통하여 이를 다투었다면, 채무자의 그러한 법률적 판단이 잘못된 것이라도 특별한 사정이 없는 한 채무불이행에 관하여 채무자에게 고의나 과실이 있다고는 할 수 없다.","ox":"X","m":"③","c":"A","tp":"이행불능"},{"y":2018,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2018_24-02-4","t":"매도인의 매매목적물에 관한 소유권이전등기 의무가 이행불능이 됨으로 말미암아 매수인이 입는 손해액은 원칙적으로 그 이행불능이 될 당시의 목적물의 시가상당액이다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2018_24-02-5","t":"매도인이 매매목적물의 원소유자에 대하여 갖는 소유권이전등기청구권에 대하여 가압류 또는 처분금지가처분 집행이 되어 있다고 하여 그 자체로 매매에 기한 소유권이전등기의무가 이행불능이라 할 수는 없다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2018_24-07","t":"채권자대위권에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"채권자대위권에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["계약의 승낙은 일신전속권에 해당하지 아니하므로, 특별한 사정이 없는 한 특정채권 보전을 위한 채권자대위권의 목적이 될 수 있다.","채권자는 그 채권의 기한이 도래하기 전에는 법원 허가 없이 채권자대위권을 행사하지 못하나, 보전행위는 할 수 있다.","채권자대위권을 행사함에 있어서 채권자가 채무자를 상대로 하여 그 보전되는 청구권에 기한 이행청구의 소를 제기하여 승소판결을 선고받고 그 판결이 확정되면, 제3채무자는 그 청구권의 존재를 다툴 수 없는 것이 원칙이다.","채권자대위권 행사가 채무자의 자유로운 재산관리행위에 대한 부당한 간섭이 된다는 등의 특별한 사정이 있는 경우에는 보전의 필요성이 부정될 수 있다.","채권자대위소송이 제기되고 채무자가 이를 알게 되면, 채무자가 피대위권리를 처분하여도 이로써 채권자에게 대항하지 못한다. 23-13"],"a":1}},{"y":2018,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2018_24-18","t":"甲은 자신의 소유인 X토지를 乙에게 매도하고 대금 전부를 지급받았다. 이후 甲은 X토지를 다시 丙에게 매도한 후 丙에게 소유권이전등기를 마쳐주었다. 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"甲은 자신의 소유인 X토지를 乙에게 매도하고 대금 전부를 지급받았다. 이후 甲은 X토지를 다시 丙에게 매도한 후 丙에게 소유권이전등기를 마쳐주었다. 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["甲이 X토지를 먼저 乙에게 매도하였다는 사실을 丙이 알고 있었다고 하더라도 다른 특별한 사정이 없었다면 X토지의 소유권은 丙에게 있다.","위 ①의 경우, 乙은 甲을 상대로 이행불능을 이유로 한 전보배상을 청구하거나 대상청구권을 행사할 수 있다.","위 ①의 경우, 乙이 甲에 대한 소유권이전등기청구권의 보전을 위하여 甲과 丙 사이의 매매계약에 대하여 채권자취소권을 행사하는 것은 허용되지 않는다.","丙이 甲의 이중매매에 적극 가담한 것으로 인정되는 경우, 乙은 甲을 대위함이 없이 직접 丙을 상대로 소유권이전등기의 말소를 청구할 수 있다.","丙이 甲의 이중매매에 적극 가담한 것으로 인정되는 경우, 만약 丁이 丙 명의의 소유권이전등기를 신뢰하여 丙으로부터 X토지를 매수하여 소유권이전등기를 마쳤더라도, 丁은 X토지의 소유권을 주장하지 못한다."],"a":4}},{"y":2018,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2018_24-20-1","t":"사해행위취소의 소는 채권자가 취소원인을 안 날로부터 1년, 법률행위 있은 날로부터 5년내에 제기하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2018_24-20-2","t":"채권자가 채권자취소권을 행사하려면 사해행위로 인하여 이익을 받은 자나 전득한 자를 상대로 그 법률행위의 취소를 청구하는 소송을 제기하여야 되는 것으로서 채무자를 상대로 그 소송을 제기할 수는 없다.","ox":"O","m":"②","c":"A","tp":"사해행위취소"},{"y":2018,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2018_24-20-3","t":"사해행위라고 볼 수 있는 행위가 행하여지기 전에 발생한 채권은 원칙적으로 채권자취소권에 의하여 보호될 수 있는 채권이 될 수 있고, 채권자의 채권이 사해행위 이전에 성립한 이상 사해행위 이후에 양도되었다고 하더라도 양수인은 채권자취소권을 행사할 수 있다.","ox":"O","m":"③","c":"A","tp":"사해행위취소"},{"y":2018,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2018_24-20-4","t":"무자력상태의 채무자가 소송절차를 통해 수익자에게 자신의 책임재산을 이전하기로 하여 수익자가 제기한 소송에서 자백하는 등의 방법으로 패소판결을 받아 확정시키고, 이에 따라 수익자 앞으로 책임재산에 대한 소유권이전등기가 마쳐진 경우 채무자와 수익자 사이의 이전합의가 사해행위가 되더라도 확정판결의 효력에 의하여 채권자는 확정판결을 통해 마쳐진 소유권이전등기의 말소를 구할 수 없으므로 가액배상만을 구할 수 있다.","ox":"X","m":"④","c":"A","tp":"사해행위취소"},{"y":2018,"e":"법무사 1차","qn":20,"lv":3,"i":"법무사2018_24-20-5","t":"재산분할청구권의 보전을 위해서도 사해행위취소권을 행사할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2018_24-33-1","t":"채권의 목적을 종류로만 지정한 경우에 채무자가 이행에 필요한 행위를 완료하거나 채권자의 동의를 얻어 이행할 물건을 지정한 때에는 그때로부터 그 물건을 채권의 목적물로 한다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2018_24-33-2","t":"제한종류채권에서 당사자 사이에 지정권 부여 및 지정 방법에 관한 합의가 없고 채무자가 이행에 필요한 행위를 하지 아니하거나 지정권자로 된 채무자가 이행할 물건을 지정하지 아니하는 경우에는, 선택채권의 선택권 이전에 관한 민법 제381조를 준용하여, 채권의 기한이 도래한 후 채권자가 상당한 기간을 정하여 지정권이 있는 채무자에게 그 지정을 최고하여도 채무자가 이행할 물건을 지정하지 않으면 지정권이 채권자에게 이전한다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2018_24-33-3","t":"금전채무의 지연손해금채무 이행을 지체한다고 하여, 채무자가 지연손해금채무 그 자체에 대한 지연손해금을 지급할 의무를 부담하는 것은 아니다.","ox":"X","m":"③","c":"A","tp":"채권"},{"y":2018,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2018_24-33-4","t":"채권액이 외국통화로 지정된 금전채권인 외화채권을 채무자가 우리나라 통화로 변제할 경우, 그 환산 기준시는 원칙적으로 이행기가 아니라 현실로 이행하는 때이다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2018_24-33-5","t":"채권의 목적이 수개의 행위 중에서 선택에 좇아 확정될 경우에 다른 법률의 규정이나 당사자의 약정이 없으면 선택권은 채무자에게 있다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2018_24-35","t":"채무의 이행기 등에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"채무의 이행기 등에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["부당이득반환의무는 이행기한의 정함이 없는 채무이므로 특별한 사정이 없는 한 그 채무자는 이행청구를 받은 때에 비로소 지체책임을 진다.","임대인이 민법 제628조에 의하여 장래에 대한 차임의 증액을 청구하였을 때에 당사자 사이에 협의가 성립되지 아니하여 법원이 결정해 주는 차임과 관련하여, 특별한 사정이 없는 한 증액된 차임에 대하여는 법원의 차임증액결정시를 이행기로 보아야 한다.","채권자가 기존 채무 지급을 위하여 그 채무의 이행기가 도래하기 전에 미리 그 채무의 변제기보다 후의 일자가 만기로 된 어음의 교부를 받은 때에는 묵시적으로 기존 채무의 지급을 유예하는 의사가 있었다고 볼 경우가 있을 수 있다. 이때 기존 채무의 변제기는 어음에 기재된 만기일로 변경된다고 볼 것이나, 특별한 사정이 없는 한 채무자가 기존 채무의 이행기에 채무를 변제하지 아니하여 채무불이행 상태에 빠진 다음에 기존 채무의 지급을 위하여 어음이 발행된 경우까지 그와 동일하게 볼 수는 없다.","이행기의 정함이 없는 채권을 양수한 채권양수인이 채무자를 상대로 그 이행을 구하는 소를 제기하고 소송 계속 중에 비로소 채무자에 대한 채권양도통지가 이루어진 경우에는, 특별한 사정이 없는 한 채무자는 채권양도통지가 도달된 다음 날부터 이행지체의 책임을 진다.","채무가 특정된 확정채무에 대하여 보증한 보증인으로서는 자신의 동의 없이 피보증채무의 이행기를 연장해 주었는지에 상관없이 보증채무를 부담하는 것이 원칙이다. 23-20"],"a":2}},{"y":2018,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2018_24-38-1","t":"과실에 의한 불법행위자인 중개보조원이 고의에 의한 불법행위자와 공동불법행위책임을 부담하는 경우, 중개보조원의 손해배상액을 정할 때에는 피해자의 과실을 참작하여 과실상계를 할 수 있다. 그리고 중개보조원을 고용한 개업공인중개사의 손해배상금액을 정할 때에는 개업공인중개사가 중개보조원의 사용자일 뿐 불법행위에 관여하지는 않았다는 등의 개별적인 사정까지 고려하여 중개보조원보다 가볍게 책임을 제한할 수도 있다.","ox":"O","m":"①","c":"A"},{"y":2018,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2018_24-38-2","t":"도급인이 민법 제673조(수급인이 일을 완성하기 전에는 도급인은 손해를 배상하고 계약을 해제할 수 있다)에 의하여 도급계약을 해제한 이상, 특별한 사정이 없는 한 도급인은 수급인에 대한 손해배상에 있어서 과실상계나 손해배상예정액 감액을 주장할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2018,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2018_24-38-3","t":"특별한 사정이 없는 한 손해배상 청구소송에서 피해자에게 과실이 인정되면 법원은 손해배상의 책임 및 그 금액을 정함에 있어서 이를 참작하여야 한다. 배상의무자가 피해자의 과실에 관하여 주장하지 않는 경우에도 소송자료에 의하여 과실이 인정되는 경우에는 이를 법원이 직권으로 심리·판단하여야 한다.","ox":"O","m":"③","c":"A","tp":"과실상계"},{"y":2018,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2018_24-38-4","t":"피해자가 공동불법행위자들을 모두 피고로 삼아 한꺼번에 손해배상청구소송을 제기한 경우와 달리, 공동불법행위자 별로 별개의 소를 제기하여 소송을 진행하는 경우에는 과실상계비율과 손해액도 서로 달리 인정될 수 있다.","ox":"O","m":"④","c":"A"},{"y":2018,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2018_24-38-5","t":"당사자 사이의 계약에서 채무자의 채무불이행으로 인한 손해배상액이 예정되어 있는 경우에도, 채권자에게 과실이 있다면 과실상계를 할 수 있다.","ox":"X","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2019_25-13-1","t":"A가 B에게 부동산을 양도하기로 매매계약을 체결한 후 위 부동산을 다시 C에게 이중으로 양도하고 C 명의로 소유권이전등기를 마쳐주었다. 이 경우 B는 소유권이전등기청구권은 물론이고, 이행불능에 따른 손해배상청구권을 피보전채권으로 하여서도, A와 C 사이의 매매계약을 사해행위로 취소할 수 없다.","ox":"O","m":"①","c":"A","tp":"채권자취소권"},{"y":2019,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2019_25-13-2","t":"甲에 대하여 억대에 이르는 채무를 부담하는 등 거액의 채무초과 상태에서 별다른 재산이 없던 채무자 乙은 그 어머니인 丙으로부터 상속을 받게 되자, 다른 공동상속인들인 A, B, C, D와 사이에 상속재산분할협의를 하면서 망인 丙의 상속재산으로 시가 3억 9,000만 원 상당의 부동산과 丙 명의의 7,000만 원 상당의 예금이 있었음에도, 위 부동산에 대한 자신의 상속지분 2/13를 포기하고 대신 현금으로만 8,000만 원을 지급받기로 합의하였다. 이 경우 위 상속재산분할협의는 사해행위취소의 대상이 될 수 있다.","ox":"O","m":"②","c":"A","tp":"채권자취소권"},{"y":2019,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2019_25-13-3","t":"甲 주식회사가 乙에게 채무를 변제하지 못하는 것을 정지조건으로 甲 회사의 丙에 대한 채권을 양도하고 乙로부터 금전을 차용하였는데, 그 후 甲 회사가 부도를 내고 사업을 폐지한 다음 乙과 위 채권에 관한 채권양도증서를 작성하여 채권양도 사실을 丙에게 통지하였다. 이 경우 甲 회사와 乙이 체결한 채권양도계약이 사해행위에 해당하는지는 양도증서가 작성된 시점이 아니라 당초 채권양도계약이 체결된 시점을 기준으로 판단하여야 한다.","ox":"O","m":"③","c":"A","tp":"채권자취소권"},{"y":2019,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2019_25-13-4","t":"채무자 乙은 수익자 丙에게 그 소유의 부동산을 매도하고 그 명의로 소유권이전등기를 마쳐주었는데, 그 후 위 매매계약이 사해행위라는 이유로 취소되고 그 원상회복으로 丙 명의의 소유권이전등기가 말소되자, 乙은 같은 날 丁에게 위 부동산을 다시 매도하고 소유권이전등기를 마쳐주었다. 이 경우 위 사해행위 이전에 乙에 대한 채권을 취득한 甲은 위 부동산에 대한 강제집행을 위하여 직접 丁을 상대로 소유권이전등기의 말소를 청구할 수 있다.","ox":"O","m":"④","c":"A","tp":"채권자취소권"},{"y":2019,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2019_25-13-5","t":"부부인 乙과 丙은 부동산을 1/2 지분씩 공유하고 있었는데, A 은행에 위 부동산 전부에 관하여 채무자를 乙, 채권최고액을 1억 3,000만 원으로 하는 근저당권을 설정하여 주었다. 그 후 乙은 채무초과 상태에서 자신의 유일한 재산인 위 부동산 중 1/2 지분을 丙에게 증여하는 계약을 체결하고, 丙 명의로 소유권이전등기를 마쳐주었다. 丙은 위 부동산에 관하여 B 은행에 채권최고액 1억 800만 원으로 하는 근저당권을 설정하여 주고 B 은행으로부터 9,000만 원을 대출받아 이를 이용하여 A은행 명의의 근저당권설정등기를 말소하였다. 이 경우 乙과 丙의 위 증여계약이 사해행위인지 여부를 판단할 때 채무자 乙 소유의 부동산 지분이 부담하는 피담보채권액은 원칙적으로 공유지분의 비율에 따라 분담된 금액이다.","ox":"X","m":"⑤","c":"A","tp":"채권자취소권"},{"y":2019,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2019_25-24-1","t":"채권자 甲의 채무자 乙에 대한 채권이 변제기가 도래하지 아니한 경우, 甲은 자기의 채권을 보전하기 위하여 법원의 허가를 얻어 乙의 丙에 대한 채권을 대위행사할 수 있다.","ox":"O","m":"①","c":"A","tp":"채권자대위권"},{"y":2019,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2019_25-24-2","t":"X주택의 임대인 乙에 대한 임차인 丙의 보증금반환채권을 양수한 甲이 그 이행을 청구하기 위하여 丙의 X주택 인도가 선이행되어야 할 필요가 있어서 乙을 대위하여 그 인도를 청구하는 경우, 乙의 무자력은 요구되지 않는다.","ox":"O","m":"②","c":"A","tp":"채권자대위권"},{"y":2019,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2019_25-24-3","t":"채무자 乙이 채권자 甲의 채권자대위권 행사를 통지받은 후에 乙의 채무불이행을 이유로 제3채무자 丙이 乙과 丙 사이의 매매계약을 해제한 경우, 丙은 위 계약의 해제로써 대위권을 행사하는 甲에게 대항할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2019_25-24-4","t":"채권자 甲이 채무자 乙을 대위하여 제3채무자 丙에 대한 채권을 행사하는 경우, 丙은 甲의 乙에 대한 채권이 소멸시효가 완성되었음을 항변할 수 없다.","ox":"O","m":"④","c":"A","tp":"채권자대위권"},{"y":2019,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2019_25-24-5","t":"채무자인 비법인사단 乙이 그 명의로 제3채무자 丙을 상대로 소를 제기하였으나 사원총회의 결의 없이 총유재산에 관한 소가 제기되었다는 이유로 각하판결이 선고·확정된 경우, 乙은 스스로 丙에 대한 자신의 권리를 행사한 것이므로 이후 채권자 甲의 채권자대위의 소는 부적법하다.","ox":"X","m":"⑤","c":"A","tp":"채권자대위권"},{"y":2019,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2019_25-29-1","t":"계약 당시 손해배상액을 예정한 경우 다른 특약이 없는 한 채무불이행으로 인하여 입은 통상손해 외에 특별손해까지도 예정액에 포함된다고 할 수는 없고, 채권자의 손해가 예정액을 초과한다면 이를 주장·입증하여 초과부분을 따로 청구할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2019_25-29-2","t":"계약 당시 당사자 사이에 손해배상액을 예정하는 내용의 약정이 있는 경우에는 그것은 계약상의 채무불이행으로 인한 손해액에 관한 것이고 이를 그 계약과 관련된 불법행위상의 손해까지 예정한 것이라고는 볼 수 없다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2019_25-29-3","t":"채무불이행으로 인한 손해배상 예정액의 청구와 채무불이행으로 인한 손해배상액의 청구는 그 청구원인을 달리 하는 별개의 청구이므로 손해배상 예정액의 청구 가운데 채무불이행으로 인한 손해배상액의 청구가 포함되어 있다고 볼 수 없다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2019_25-29-4","t":"토지에 대한 부당한 가압류의 집행으로 그 지상에 건물을 신축하는 내용의 공사도급계약이 해제됨으로 인한 손해는 특별손해이므로, 가압류채권자가 토지에 대한 가압류집행이 그 지상 건물 공사도급계약의 해제사유가 된다는 특별한 사정을 알았거나 알 수 있었을 때에 한하여 배상의 책임이 있다.","ox":"O","m":"④","c":"A","tp":"손해배상"},{"y":2019,"e":"법무사 1차","qn":29,"lv":3,"i":"법무사2019_25-29-5","t":"일반육체노동을 하는 사람 또는 육체노동을 주로 생계활동으로 하는 사람의 일실수입 산정에 있어서 그 산정의 기초가 되는 가동연한은 특별한 사정이 없는 한 경험칙상만 65세까지로 보아야 한다.","ox":"O","m":"⑤","c":"A","tp":"손해배상"},{"y":2019,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2019_25-34-1","t":"甲이 乙에게 갖고 있는 금전채권에 관하여 甲의 채권자인 丙에 의하여 가압류되었을 때에는, 乙은 甲에 대하여 이행기에 채무를 이행하지 않더라도 가압류의 지급금지효에 의하여 지체책임을 부담하지 않는다.","ox":"X","m":"①","c":"A","tp":"금전채무 불이행"},{"y":2019,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2019_25-34-2","t":"금전채무의 지연손해금채무는 금전채무의 이행지체로 인한 손해배상채무로서 이행기의 정함이 없는 채무에 해당하므로, 채무자는 확정된 지연손해금채무에 대하여 채권자로부터 이행청구를 받은 때로부터 지체책임을 부담하게 된다.","ox":"O","m":"②","c":"A","tp":"금전채무 불이행"},{"y":2019,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2019_25-34-3","t":"금전채무 불이행의 손해배상에 관하여는 채권자는 손해의 증명을 요하지 아니하고 채무자는 과실 없음을 항변하지 못한다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2019_25-34-4","t":"금전채무 불이행의 손해배상액의 약정이율이 법정이율보다 낮은 경우, 법정이율에 의하여 지연손해금을 정해야 한다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2019_25-34-5","t":"금전채무에 관하여 이행지체에 대비한 지연손해금 비율을 따로 약정한 경우에 이는 손해배상액의 예정으로서 감액의 대상이 된다.","ox":"O","m":"⑤","c":"A","tp":"금전채무 불이행"},{"y":2020,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2020_26-03-1","t":"채권자가 채권자취소권을 행사하려면 사해행위로 인하여 이익을 받은 자나 전득한 자를 상대로 그 법률행위의 취소를 청구하는 소송을 제기하여야 되는 것으로서 채무자를 상대로 그 소송을 제기할 수는 없다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2020_26-03-2","t":"이혼으로 인한 재산분할청구권은 이혼을 한 당사자의 일방이 다른 일방에 대하여 재산분할을 청구할 수 있는 권리로서 이혼이 성립한 때에 그 법적 효과로서 비로소 발생하는 것일 뿐만 아니라, 협의 또는 심판에 의하여 구체적 내용이 형성되기까지는 그 범위 및 내용이 불명확·불확정하기 때문에 구체적으로 권리가 발생하였다고 할 수 없으므로 협의 또는 심판에 의하여 구체화되지 않은 재산분할청구권은 채무자의 책임재산에 해당하지 아니하고, 이를 포기하는 행위 또한 채권자취소권의 대상이 될 수 없다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2020_26-03-3","t":"채무자가 사해행위 취소로 등기명의를 회복한 부동산을 제3자에게 처분하더라도 이는 무권리자의 처분에 불과하여 효력이 없으므로, 제3자에게 마쳐진 소유권이전등기나 이에 기초하여 순차로 마쳐진 소유권이전등기 등은 모두 원인무효의 등기로서 말소되어야 한다. 이 경우 취소채권자나 민법 제407조에 따라 사해행위 취소와 원상회복의 효력을 받는 채권자는 채무자의 책임재산으로 취급되는 부동산에 대한 강제집행을 위하여 원인무효 등기의 명의인을 상대로 등기의 말소를 청구할 수 있다.","ox":"O","m":"③","c":"A","tp":"채권자취소권"},{"y":2020,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2020_26-03-4","t":"건축 중인 건물 외에 별다른 재산이 없는 채무자가 건축 중인 건물을 양도하기 위해 수익자 앞으로 건축주명의를 변경해주기로 약정한 때에 이러한 건축주명의변경 약정은 민법 제406조 제1항의 재산권을 목적으로 한 법률행위에 해당한다고 볼 수 없으므로 다른 일반채권자의 이익을 해하는 사해행위가 된다고 할 수 없다.","ox":"X","m":"④","c":"A","tp":"채권자취소권"},{"y":2020,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2020_26-03-5","t":"채권자취소권의 요건을 갖춘 각 채권자는 고유의 권리로서 채무자의 재산처분행위를 취소하고 그 원상회복을 구할 수 있는 것이지만, 어느 한 채권자가 동일한 사해행위에 관하여 채권자취소 및 원상회복청구를 하여 승소판결을 받아 그 판결이 확정되고 그에 기하여 재산이나 가액의 회복을 마친 경우에는, 다른 채권자의 채권자취소 및 원상회복청구는 그와 중첩되는 범위 내에서 권리보호의 이익이 없게 된다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2020_26-09-1","t":"민법이 타인의 권리의 매매를 인정하고 있는 것처럼 타인의 권리의 증여도 가능하며, 이 경우 채무자는 권리를 취득하여 채권자에게 이전하여야 하고, 이 같은 사정은 계약 당시부터 예정되어 있으므로, 매매나 증여의 대상인 권리가 타인에게 귀속되어 있다는 이유만으로 채무자의 계약에 따른 이행이 불능이라고 할 수는 없다.","ox":"O","m":"①","c":"A","tp":"채무불이행"},{"y":2020,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2020_26-09-2","t":"매수인에게 부동산의 소유권이전등기를 해줄 의무를 지는 매도인이 그 부동산에 관하여 다른 사람에게 이전등기를 마쳐 준 때에는 매도인이 그 부동산의 소유권에 관한 등기를 회복하여 매수인에게 이전등기해 줄 수 있는 특별한 사정이 없어야 비로소 매수인에 대한 소유권이전등기의무가 이행불능의 상태에 이르렀다고 할 수 있다.","ox":"O","m":"②","c":"A","tp":"채무불이행"},{"y":2020,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2020_26-09-3","t":"금전채무의 지연손해금채무는 금전채무의 이행지체로 인한 손해배상채무로서 이행기의 정함이 없는 채무에 해당하므로, 채무자는 확정된 지연손해금채무에 대하여 채권자로부터 이행청구를 받은 때부터 지체책임을 부담하게 된다.","ox":"O","m":"③","c":"A","tp":"채무불이행"},{"y":2020,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2020_26-09-4","t":"쌍무계약에 있어서 계약당사자의 일방은 상대방이 채무를 이행하지 아니할 의사를 명백히 표시한 경우에는 최고나 자기 채무의 이행제공 없이 그 계약을 적법하게 해제할 수 있고, 이후 그 이행거절의 의사표시가 적법하게 철회되었다고 하더라도, 상대방이 채무불이행을 이유로 계약을 해제하기 위하여 자기 채무의 이행을 제공하고 상당한 기간을 정하여 이행을 최고하여야 한다고 볼 수 없다.","ox":"X","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2020_26-09-5","t":"소송비용액확정결정에 따른 소송비용액상환의무는 소송비용액확정결정이 확정됨으로써 비로소 이행기가 도래하고, 채무자가 그 이행기가 도래하였음을 안 때로부터 지체책임을 진다.","ox":"O","m":"⑤","c":"A","tp":"채무불이행"},{"y":2020,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2020_26-11-1","t":"특정물에 대한 소유권이전등기청구권을 보전하기 위하여 채권자취소권을 행사하는 것은 허용되지 않으므로, 부동산의 제1양수인은 자신의 소유권이전등기청구권 보전을 위하여 양도인과 제3자 사이에서 이루어진 이중양도행위에 대하여 채권자취소권을 행사할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2020_26-11-2","t":"부동산을 매수하여 소유권이전등기청구권을 가지고 있는 자가 매도인이 제3자에게 이를 이중으로 양도하여 소유권이전등기를 경료하여 줌으로써 취득하게 되는 부동산 가액 상당의 손해배상채권은 금전채권이므로 이중양도행위에 대하여 사해행위취소권을 행사할 수 있는 피보전채권에 해당한다.","ox":"X","m":"②","c":"A","tp":"채권자취소권"},{"y":2020,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2020_26-11-3","t":"채권자취소권에 의하여 보호될 수 있는 채권은 원칙적으로 사해행위라고 볼 수 있는 행위가 행하여지기 전에 발생된 것임을 요하지만, 그 사해행위 당시에 이미 채권 성립의 기초가 되는 법률관계가 발생되어 있고, 가까운 장래에 그 법률관계에 터잡아 채권이 성립되리라는 점에 대한 고도의 개연성이 있으며, 실제로 가까운 장래에 그 개연성이 현실화되어 채권이 성립된 경우에는, 그 채권도 채권자취소권의 피보전채권이 될 수 있다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2020_26-11-4","t":"신용카드가입계약은 신용카드의 발행 및 관리, 신용카드의 이용과 관련된 대금의 결제에 관한 기본적 사항을 포함하고 있기는 하나 그에 기하여 신용카드업자의 채권이 바로 성립되는 것은 아니고, 신용카드를 발행받은 신용카드회원이 신용카드를 사용하여 신용카드가맹점으로부터 물품을 구매하거나 용역을 제공받음으로써 성립하는 신용카드매출채권을 신용카드가맹점이 신용카드업자에게 양도하거나, 신용카드업자로부터 자금의 융통을 받는 별개의 법률관계에 의하여 비로소 채권이 성립하는 것이므로, 단순히 신용카드가입계약만을 가리켜 채권성립의 기초가 되는 법률관계에 해당한다고 할 수는 없다.","ox":"O","m":"④","c":"A","tp":"채권자취소권"},{"y":2020,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2020_26-11-5","t":"채무자가 채권자와 신용카드가입계약을 체결하고 신용카드를 발급받았으나 유일한 재산인 아파트를 매도한 이후에 비로소 신용카드를 사용하기 시작하여 카드대금을 연체하게 되었다면 그 신용카드대금채권은 사해행위의 피보전채권이 될 수 없다.","ox":"O","m":"⑤","c":"A","tp":"채권자취소권"},{"y":2020,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2020_26-18-1","t":"형사보상금지급청구권은 국가에 대한 일반 금전채권과 유사하므로, 민법의 이행지체 규정, 그중에서도 민법 제397조의 금전채무불이행에 대한 특칙이 그대로 적용된다고 보아야 한다. 형사보상금지급청구권은 형사보상법이나 보상결정에서 이행의 기한을 정하지 않고 있으므로, 국가는 미지급 형사보상금에 대하여 지급 청구일 다음 날부터 민사법정이율로 계산한 지연손해금을 가산하여 지급하여야 한다고 봄이 타당하다.","ox":"O","m":"①","c":"A","tp":"채무불이행으로 인한 손해배상청구"},{"y":2020,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2020_26-18-2","t":"채무자는 이행지체 중에 생긴 손해를 배상하여야 한다. 그러나 채무자가 이행기에 이행하여도 손해를 면할 수 없는 경우 또는 채무자에게 과실이 없는 경우에는 그러하지 아니하다.","ox":"X","m":"②","c":"A","tp":"채무불이행으로 인한 손해배상청구"},{"y":2020,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2020_26-18-3","t":"보증채무는 주채무와는 별개의 채무이기 때문에 보증채무 자체의 이행지체로 인한 지연손해금은 보증한도액과는 별도인바, 이 경우 보증채무의 연체이율에 관하여 특별한 약정이 있으면 그에 따르고 특별한 약정이 없으면 그 거래행위의 성질에 따라 상법 또는 민법에서 정한 법정이율에 따르는 것이지, 주채무에 관하여 약정된 연체이율이 당연히 여기에 적용되는 것은 아니다.","ox":"O","m":"③","c":"A","tp":"채무불이행으로 인한 손해배상청구"},{"y":2020,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2020_26-18-4","t":"계약당사자 일방이 자신이 부담하는 계약상 채무를 이행하는 데 장애가 될 수 있는 사유를 계약을 체결할 당시에 알았거나 예견할 수 있었음에도 이를 상대방에게 고지하지 아니한 경우에는, 비록 그 사유로 말미암아 후에 채무불이행이 되는 것 자체에 대하여는 그에게 어떠한 잘못이 없다고 하더라도, 상대방이 그 장애사유를 인식하고 이에 관한 위험을 인수하여 계약을 체결하였다거나 채무불이행이 상대방의 책임 있는 사유로 인한 것으로 평가되어야 하는 등의 특별한 사정이 없는 한, 그 채무가 불이행된 것에 대하여 귀책사유가 없다고 할 수 없다.","ox":"O","m":"④","c":"A","tp":"채무불이행으로 인한 손해배상청구"},{"y":2020,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2020_26-18-5","t":"채권의 가압류가 있다 하여도 그 채권의 이행기가 도래한 때에는 제3채무자는 그 지체책임을 면할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"채무불이행으로 인한 손해배상청구"},{"y":2020,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2020_26-34-1","t":"유류분반환청구권의 행사로 인하여 생기는 원물반환의무 또는 가액반환의무는 이행기한의 정함이 없는 채무이므로, 반환의무자는 그 의무에 대한 이행청구를 받은 때에 비로소 지체책임을 진다.","ox":"O","m":"①","c":"A","tp":"이행지체"},{"y":2020,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2020_26-34-2","t":"추심명령은 압류채권자에게 채무자의 제3채무자에 대한 채권을 추심할 권능을 수여함에 그치고, 제3채무자로 하여금 압류채권자에게 압류된 채권액 상당을 지급할 것을 명하거나 그 지급 기한을 정하는 것이 아니므로, 제3채무자가 압류채권자에게 압류된 채권액 상당에 관하여 지체책임을 지는 것은 집행법원으로부터 추심명령을 송달받은 때부터가 아니라 추심명령이 발령된 후 압류채권자로부터 추심금 청구를 받은 다음날부터라고 하여야 한다.","ox":"O","m":"②","c":"A","tp":"이행지체"},{"y":2020,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2020_26-34-3","t":"부당이득반환의무는 이행기한의 정함이 없는 채무이므로 그 채무자는 이행청구를 받은 때에 비로소 지체책임을 진다.","ox":"O","m":"③","c":"A","tp":"이행지체"},{"y":2020,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2020_26-34-4","t":"금전채무의 이행지체로 인하여 발생하는 지연손해금은 그 성질이 손해배상금이지 이자가 아니며, 민법 제163조 제1호가 규정한 1년 이내의 기간으로 정한 채권도 아니므로 3년간의 단기소멸시효의 대상이 되지 아니한다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2020_26-34-5","t":"이행지체에 빠져 원본과 지연이자를 지급할 의무가 있는 금전채무자가 원본과 지연이자를 합한 전액에 부족한 이행제공을 하면서 이를 원본에 대한 변제로 지정하였다면 그 지정은 변제충당의 법리에 따라서 채권자에 대한 효력이 있으므로 채권자는 그 수령을 거절할 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2021_27-04-1","t":"이행기를 정하지 않은 채권의 양수인이 2021. 1. 3. 채무자에게 이행을 청구한 후에 2021. 1. 13. 채권양도사실의 통지가 채무자에게 도달하였다면 채무자는 2021. 1. 14.부터 이행지체의 책임을 진다.","ox":"O","m":"①","c":"A","tp":"금전채무의 이행지체"},{"y":2021,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2021_27-04-2","t":"불법행위로 인한 손해배상채무는 기한의 정함이 없는 채무이므로 가해자는 피해자의 이행청구를 받은 때로부터 이행지체의 책임을 진다.","ox":"X","m":"②","c":"A","tp":"금전채무의 이행지체"},{"y":2021,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2021_27-04-3","t":"甲이 乙에게 변제기를 정하지 않고 1억원을 대여한 후 2021. 5. 15. 대여금의 반환을 청구하였다면 乙은 2021. 5. 16.부터 이행지체의 책임을 진다.","ox":"X","m":"③","c":"A","tp":"금전채무의 이행지체"},{"y":2021,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2021_27-04-4","t":"부당이득반환채무의 경우 부당이득한 날부터 지체책임을 부담한다.","ox":"X","m":"④","c":"A","tp":"금전채무의 이행지체"},{"y":2021,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2021_27-04-5","t":"甲이 乙에게 공사대금채무의 지급을 확보하기 위한 수단으로 약속어음을 발행한 경우 공사대금채무의 변제기가 도래하더라도 乙이 위 약속어음을 반환하지 않는 이상 지체책임을 부담하지 않는다.","ox":"X","m":"⑤","c":"A","tp":"금전채무의 이행지체"},{"y":2021,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2021_27-23-1","t":"채권자가 사해행위의 취소로서 수익자를 상대로 채무자와의 법률행위의 취소를 구함과 아울러 전득자를 상대로도 전득행위의 취소를 구함에 있어서, 전득자의 악의는 전득행위 당시 채무자와 수익자 사이의 법률행위가 채권자를 해한다는 사실, 즉 사해행위의 객관적 요건을 구비하였다는 것에 대한 인식을 의미한다. 한편 사해행위취소소송에서 채무자의 악의의 점에 대하여는 취소를 주장하는 채권자에게 증명책임이 있으나 수익자 또는 전득자가 악의라는 점에 관하여는 증명책임이 채권자에게 있는 것이 아니고 수익자 또는 전득자 자신에게 선의라는 사실을 증명할 책임이 있으며, 채무자의 재산처분행위가 사해행위에 해당할 경우에 사해행위 또는 전득행위 당시 수익자 또는 전득자가 선의였음을 인정함에 있어서는 객관적이고도 납득할 만한 증거자료 등에 의하여야 하고, 채무자나 수익자의 일방적인 진술이나 제3자의 추측에 불과한 진술 등에만 터 잡아 사해행위 또는 전득행위 당시 수익자 또는 전득자가 선의였다고 선뜻 단정하여서는 아니 된다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2021_27-23-2","t":"상속재산의 분할협의는 상속이 개시되어 공동상속인 사이에 잠정적 공유가 된 상속재산에 대하여 그 전부 또는 일부를 각 상속인의 단독소유로 하거나 새로운 공유관계로 이행시킴으로써 상속재산의 귀속을 확정시키는 것에 불과하므로 사해행위취소권 행사의 대상이 될 수 없다. 따라서 채무자가 자기의 유일한 재산인 부동산을 매각하여 소비하기 쉬운 금전으로 바꾸거나 타인에게 무상으로 이전하여 주는 행위가 채권자에 대하여 사해행위가 되는 것과 달리, 이미 채무초과 상태에 있는 채무자가 상속재산의 분할협의를 하면서 자신의 상속분에 관한 권리를 포기하였다고 하더라도 채권자에 대한 사해행위에 해당한다고 할 수는 없다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2021_27-23-3","t":"근저당권이 설정되어 있는 부동산에 관하여 사해행위가 이루어진 후 근저당권이 말소되어 그 부동산의 가액에서 근저당권 피담보채무액을 공제한 나머지 금액의 한도에서 사해행위를 취소하고 가액의 배상을 명하는 경우 그 가액의 산정은 사실심 변론종결시를 기준으로 하여야 하고, 이 경우 사해행위가 있은 후 그 부동산에 관한 권리를 취득한 전득자에 대하여는 사실심 변론종결시의 부동산 가액에서 말소된 근저당권 피담보채무액을 공제한 금액과 사실심 변론종결시를 기준으로 한 취소채권자의 채권액 중 적은 금액의 한도 내에서 그가 취득한 이익에 대해서만 가액배상을 명할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2021_27-23-4","t":"부동산에 관한 법률행위가 사해행위에 해당하는 경우에는 채무자의 책임재산을 보전하기 위하여 사해행위를 취소하고 원상회복을 명하여야 한다. 수익자는 채무자로부터 받은 재산을 반환하는 것이 원칙이지만, 그 반환이 불가능하거나 곤란한 사정이 있는 때에는 그 가액을 반환하여야 한다. 사해행위를 취소하여 부동산 자체의 회복을 명하게 되면 당초 일반 채권자들의 공동담보로 되어 있지 않던 부분까지 회복을 명하는 것이 되어 공평에 반하는 결과가 되는 경우에는 그 부동산의 가액에서 공동담보로 되어 있지 않던 부분의 가액을 뺀 나머지 금액 한도에서 가액반환을 명할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":23,"lv":3,"i":"법무사2021_27-23-5","t":"채권자취소의 소는 채권자가 취소원인을 안 날로부터 1년 내에 제기하여야 한다(민법 제406조 제2항). 여기에서 취소 원인을 안다는 것은 단순히 채무자의 법률행위가 있었다는 사실을 아는 것만으로는 부족하고, 그 법률행위가 채권자를 불리하게 하는 행위라는 것, 즉 그 행위에 의하여 채권의 공동담보에 부족이 생기거나 이미 부족상태에 있는 공동담보가 한층 더 부족하게 되어 채권을 완전하게 만족시킬 수 없게 된다는 것까지 알아야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2021_27-30-1","t":"乙이 甲을 강박하여 그에 따른 하자 있는 의사표시에 의하여 부동산에 관한 소유권이전등기를 마친 다음 타인에게 매도하여 소유권이전등기까지 마친 경우, 그 소유권이전등기는 소송 기타 방법에 따라 말소 환원 여부가 결정될 특별한 사정이 있으므로 乙의 甲에 대한 소유권이전등기의 말소등기의무는 아직 이행불능이 되었다고 할 수 없으나, 甲이 그 부동산의 전득자들을 상대로 제기한 소유권이전등기 말소등기청구소송에서 패소로 확정되면 그 때에 乙의 소유권이전등기 말소등기의무가 이행불능상태에 이른다고 할 것이다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2021_27-30-2","t":"계약당사자 일방이 자신이 부담하는 계약상 채무를 이행하는 데 장애가 될 수 있는 사유를 계약을 체결할 당시에 알았거나 예견할 수 있었음에도 이를 상대방에게 고지하지 아니한 경우에는, 비록 그 사유로 말미암아 후에 채무불이행이 되는 것 자체에 대하여는 그에게 어떠한 잘못이 없다고 하더라도, 상대방이 그 장애사유를 인식하고 이에 관한 위험을 인수하여 계약을 체결하였다거나 채무불이행이 상대방의 책임 있는 사유로 인한 것으로 평가되어야 하는 등의 특별한 사정이 없는 한, 그 채무가 불이행된 것에 대하여 귀책사유가 없다고 할 수 없다. 그것이 계약의 원만한 실현과 관련하여 각각의 당사자가 부담하여야 할 위험을 적절하게 분배한다는 계약법의 기본적 요구에 부합한다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2021_27-30-3","t":"채무의 이행이 불능이라는 것은 단순히 절대적·물리적으로 불능인 경우가 아니라 사회생활에 있어서의 경험법칙 또는 거래상의 관념에 비추어 볼 때 채권자가 채무자의 이행의 실현을 기대할 수 없는 경우를 말하는 것인 바, 매매목적물에 대하여 가압류 또는 처분금지가처분 집행이 되어 있다고 하여 매매에 따른 소유권이전등기가 불가능한 것은 아니며, 이러한 법리는 가압류 또는 가처분집행의 대상이 매매목적물 자체가 아니라 매도인이 매매목적물의 원소유자에 대하여 가지는 소유권이전등기청구권 또는 분양권인 경우에도 마찬가지이다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2021_27-30-4","t":"계약의 이행불능 여부는 사회통념에 의하여 이를 판정하여야 할 것인 바, 임대차계약상의 임대인의 의무는 목적물을 사용수익케 할 의무로서, 목적물에 대한 소유권 있음을 성립요건으로 하고 있지 아니하여 임대인이 소유권을 상실하였다는 이유만으로 그 의무가 불능하게 된 것이라고 단정할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2021_27-30-5","t":"부동산소유권이전등기 의무자가 그 부동산에 관하여 채무담보를 위하여 제3자 앞으로 소유권이전등기를 마친 것이라면, 그 의무자가 채무를 변제할 자력이 없다는 사정이 있다고 하더라도 그 소유권이전등기의무가 이행불능이 되었다고 볼 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2022_28-10-1","t":"채무자의 적극재산인 부동산에 이미 제3자 명의로 소유권이전청구권보전의 가등기가 경료되어 있는 경우에는 위 가등기가 가등기담보 등에 관한 법률에 정한 담보가등기로서 강제집행을 통한 매각이 가능하다는 등의 특별한 사정이 없는 한 위 부동산은 실질적으로 재산적 가치가 없어 적극재산을 산정함에 있어서 이를 제외하여야 할 것이다.","ox":"O","m":"①","c":"A","tp":"채권자대위권"},{"y":2022,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2022_28-10-2","t":"임대인의 동의없는 임차권의 양도는 당사자 사이에서는 유효하다 하더라도 다른 특약이 없는 한 임대인에게는 대항할 수 없는 것이고, 임대인에 대항할 수 없는 임차권의 양수인으로서는 임대인의 권한을 대위행사할 수 없다.","ox":"O","m":"②","c":"A","tp":"채권자대위권"},{"y":2022,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2022_28-10-3","t":"민사집행법 제301조에 의하여 가처분절차에도 준용되는 같은 법제287조 제1항에 따라 가압류·가처분결정에 대한 본안의 제소명령을 신청할 수 있는 권리나 같은 조 제2항 및 제3항에 따라 제소기간의 도과에 의한 가압류·가처분의 취소를 신청할 수 있는 권리는 채권자대위권의 목적이 될 수 있는 권리로 볼 수 없다.","ox":"X","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2022_28-10-4","t":"피대위자인 채무자가 실존인물이 아니거나 사망한 사람인 경우 피보전채권인 채권자의 채무자에 대한 권리를 인정할 수 없는 경우에 해당하므로 그러한 채권자대위소송은 당사자적격이 없어 부적법하다.","ox":"O","m":"④","c":"A","tp":"채권자대위권"},{"y":2022,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2022_28-10-5","t":"채권자대위권에 기해 청구를 하다가 당해 피대위채권 자체를 양수하여 양수금청구로 소를 변경하더라도 당초의 채권자대위소송으로 인한 시효중단의 효력은 소멸하지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2022_28-13-1","t":"이행보조자의 행위가 채무자에 의하여 그에게 맡겨진 이행업무와 객관적, 외형적으로 관련을 가지는 경우에는 채무자는 그 행위에 대하여 책임을 져야 하고, 채무의 이행에 관련된 행위이면 가사 이행보조자의 행위가 채권자에 대한 불법행위가 된다고 하더라도 채무자가 면책될 수는 없다.","ox":"O","m":"①","c":"A","tp":"채무불이행"},{"y":2022,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2022_28-13-2","t":"매매나 증여의 대상인 권리가 타인에게 귀속되어 있다는 이유만으로는 채무자의 계약에 따른 이행이 불능이라고 할 수 없고, 매매목적물에 관하여 이중으로 제3자와 매매계약을 체결하였다는 사실만으로 매매계약이 이행불능으로 되었다고 할 수 없다.","ox":"O","m":"②","c":"A","tp":"채무불이행"},{"y":2022,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2022_28-13-3","t":"소유권이전등기의무의 목적 부동산이 수용되어 그 소유권이전등기의무가 이행불능이 된 경우, 등기청구권자는 대상청구권의 행사로써 등기의무자가 지급받은 수용보상금의 반환을 구하거나 또는 등기의무자가 취득한 수용보상금청구권의 양도를 구할 수 있을 뿐 그 수용보상금청구권 자체가 등기청구권자에게 귀속되는 것은 아니다.","ox":"O","m":"③","c":"A","tp":"채무불이행"},{"y":2022,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2022_28-13-4","t":"채무불이행에 따른 손해배상청구권의 소멸시효의 기산점은 채무불이행이 생긴 때로부터 진행하고, 소멸시효 기간은 불법행위에 관한 민법 제766조가 준용된다.","ox":"X","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2022_28-13-5","t":"일반적으로 계약상 채무불이행으로 인하여 재산적 손해가 발생한 경우, 그로 인하여 계약 당사자가 받은 정신적인 고통은 재산적 손해에 대한 배상이 이루어짐으로써 회복된다고 보아야 할 것이므로, 재산적 손해의 배상만으로는 회복될 수 없는 정신적 고통을 입었다는 특별한 사정이 있고, 상대방이 이와 같은 사정을 알았거나 알 수 있었을 경우에 한하여 정신적 고통에 대한 위자료를 인정할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2022_28-33-1","t":"계약 해제의 효과로서 원상회복의무를 규정하는 민법 제548조 제1항 본문은 부당이득에 관한 특별규정의 성격을 가지는 것으로서, 그 이익 반환의 범위는 이익의 현존 여부나 청구인의 선의·악의를 불문하고 특단의 사유가 없는 한 받은 이익의 전부이다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2022_28-33-2","t":"과실상계는 본래 채무불이행 또는 불법행위로 인한 손해배상책임에 대하여 인정되는 것이고, 매매계약이 해제되어 소급적으로 효력을 잃은 결과 매매당사자에게 당해 계약에 기한 급부가 없었던 것과 동일한 재산상태를 회복시키기 위한 원상회복의무의 이행으로서 이미 지급한 매매대금 기타의 급부의 반환을 구하는 경우에는 적용되지 아니한다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2022_28-33-3","t":"계약의 해제로 인한 원상회복청구권에 대하여 해제자가 해제의 원인이 된 채무불이행에 관하여 ‘원인’의 일부를 제공하였다는 등의 사유를 내세워 신의칙 또는 공평의 원칙에 기하여 일반적으로 손해배상에 있어서의 과실상계에 준하여 권리의 내용이 제한될 수 있다고 하는 것은 허용되어서는 아니 된다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2022_28-33-4","t":"사용자가 피용자의 과실에 의한 불법행위로 인한 사용자책임을 부담하는 경우, 피해자에게 그 손해의 발생과 확대에 기여한 과실이 있다 하더라도 사용자책임의 범위를 정함에 있어서 이러한 피해자의 과실을 고려하여 그 책임을 제한할 수는 없다.","ox":"X","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2022_28-33-5","t":"불법행위로 인하여 건물이 훼손된 경우 그 손해는 수리가 가능하다면 그 수리비, 수리가 불가능하다면 그 교환가치(시가)가 통상의 손해이고, 사용 및 수리가 불가능한 경우 통상 불법행위로 인한 손해배상액의 기준이 되는 건물의 시가에는 건물의 철거비용은 포함되지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2023_29-04","t":"손해배상에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"손해배상에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","d":"ㄱ.손해배상액의 예정과 위약벌은 그 기능이 유사하므로, 약정의 형식이나 해석 결과에 따라 감액 여부를 달리 취급할 것이 아니라, 위약벌도 손해배상액의 예정과 함께 위약금의 일종으로서 손해배상액의 예정에 관한 민법 제398조 제2항을 유추하여 감액할 수 있다고 해석하는 것이 공평의 관념에 부합한다.\nㄴ.금전채무 불이행에 관한 특칙을 규정한 민법 제397조는 그 이행지체가 있으면 지연이자 부분만큼의 손해가 있는 것으로 의제하려는 데에 그 취지가 있는 것이므로 지연이자를 청구하는 채권자는 그 만큼의 손해가 있었다는 것을 주장 및 증명할 필요가 없다.\nㄷ.계약 당시 당사자 사이에 손해배상액을 예정하는 내용의 약정이 있는 경우에는 그것은 계약상의 채무불이행으로 인한 손해액에 관한 것이고 이를 그 계약과 관련된 불법행위상의 손해까지 예정한 것이라고는 볼 수 없다.\nㄹ.채무불이행자 또는 불법행위자는 특별한 사정의 존재를 알았거나 알 수 있었으면 그러한 특별사정으로 인한 손해를 배상하여야 할 의무가 있는 것이고, 그러한 특별한 사정에 의하여 발생한 손해의 액수까지 알았거나 알 수 있었어야 하는 것은 아니다.\nㅁ.도급인이 그가 분양한 아파트의 하자와 관련하여 구분소유자들로부터 손해배상청구를 당하여 그 하자에 대한 손해배상금 및 이에 대한 지연손해금을 지급한 경우, 그 지연손해금은 수급인의 도급계약상의 채무불이행과 상당인과관계가 있는 손해라고 볼 수 있으므로, 도급인으로서는 수급인을 상대로 위 하자에 대한 손해배상금 및 이에 대한 지연손해금의 지급을 청구할 수 있다.","o":["ㄱ,ㄴ,ㄷ","ㄴ,ㄷ,ㄹ","ㄷ,ㄹ,ㅁ","ㄱ,ㄴ,ㄹ","ㄱ,ㄴ,ㅁ"],"a":5}},{"y":2023,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2023_29-39","t":"채권자취소권에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"채권자취소권에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","d":"ㄱ.채권자취소권의 요건을 갖춘 각 채권자는 고유의 권리로서 채무자의 재산처분 행위를 취소하고 그 원상회복을 구할 수 있는 것이므로 각 채권자가 동시 또는 이시에 채권자취소 및 원상회복소송을 제기한 경우 이들 소송은 중복제소에 해당하지 않는다.\nㄴ.사해행위 당시에 이미 채권 성립의 기초가 되는 법률관계가 발생되어 있고 가까운 장래에 그 법률관계에 기하여 채권이 성립될 고도의 개연성이 있으며 실제로 가까운 장래에 그 개연성이 현실화되어 채권이 성립된 경우에는 그 채권도 채권자취소권의 피보전채권이 될 수 있으므로, 사해행위 당시 계속적인 물품거래관계가 존재하였다는 사정만으로도 채권 성립의 기초가 되는 법률관계가 발생하여 있었다고 할 수 있다.\nㄷ.채권자취소소송에서 피보전채권의 존재가 인정되어 사해행위 취소 및 원상회복을 명하는 판결이 확정되었다고 하더라도, 그에 기하여 재산이나 가액의 회복을 마치기 전에 피보전채권이 소멸하여 채권자가 더 이상 채무자의 책임재산에 대하여 강제집행을 할 수 없게 되었다면, 이는 위 판결의 집행력을 배제하는 적법한 청구이의 이유가 된다.\nㄹ.채권자가 채무자 소유의 부동산에 대한 가압류신청 시 첨부한 등기부등본에 수익자 명의의 근저당권설정등기가 경료되어 있었다면 채권자가 가압류신청 당시 사해행위 취소원인을 알았다고 인정할 수 있다.\nㅁ.수익자가 채권자취소에 따른 원상회복으로서 가액배상을 할 경우, 수익자 자신도 채무자에 대한 채권자라는 이유로 채무자에 대하여 가지는 자기의 채권과의 상계를 주장할 수는 없다.","o":["ㄱ, ㄴ, ㄹ","ㄱ, ㄴ, ㅁ","ㄱ, ㄷ, ㅁ","ㄴ, ㄷ, ㅁ","ㄷ, ㄹ, ㅁ"],"a":3}},{"y":2023,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2023_29-40","t":"다음 설명 중 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"다음 설명 중 옳지 않은 것을 모두 고른 것은?","d":"ㄱ.민법 제400조 소정의 채권자지체가 성립하기 위해서는 민법 제460조 소정의 채무자의 변제 제공이 있어야 하고, 변제 제공은 원칙적으로 현실 제공으로 하여야 하며, 다만 구두의 제공으로 하더라도 무방한 경우 또는 구두의 제공조차 필요하지 않은 경우도 있지만, 민법 제538조 제1항 제2문 소정의 ‘채권자의 수령지체 중에 당사자 쌍방의 책임 없는 사유로 이행할 수 없게 된 때’에 해당하기 위해서는 현실 제공이나 구두 제공이 필요하다.\nㄴ.채무불이행으로 인한 손해배상 예정액의 청구와 채무불이행으로 인한 손해배상액의 청구는 그 청구원인을 달리 하는 별개의 청구이므로 손해배상 예정액의 청구 가운데 채무불이행으로 인한 손해배상액의 청구가 포함되어 있다고 볼 수 없다. 따라서, 채무불이행으로 인한 손해배상액의 청구에 있어서 채권자가 손해배상책임의 발생 원인 사실에 관하여는 주장․입증을 하였더라도 손해의 발생 사실에 관한 주장․입증을 하지 아니하였다면 변론주의의 원칙상 법원은 당사자가 주장하지 아니한 손해의 발생 사실을 기초로 하여 손해액을 산정할 수는 없다.\nㄷ.매수인의 잔금지급 지체로 인하여 계약을 해제하지 아니한 매도인이 지체된 기간 동안 입은 손해 중 그 미지급 잔금에 대한 법정이율에 따른 이자 상당의 금액은 통상손해라고 할 것이고, 그 사이에 매매대상 토지의 개별공시지가가 급등하여 매도인의 양도소득세 부담이 늘었다면 그 손해 또한 사회일반의 관념상 매매계약에서의 잔금지급의 이행지체의 경우 통상 발생하는 것으로 생각되는 범위의 통상손해라고 할 수 있다.\nㄹ.공동불법행위로 인한 손해배상책임의 범위는 피해자에 대한 관계에서 가해자들 전원의 행위를 전체적으로 함께 평가하여 정하여야 하나, 이는 과실상계를 위한 피해자의 과실을 평가함에 있어서 공동불법행위자 전원에 대한 과실을 전체적으로 평가하여야 한다는 것이지, 공동불법행위자 중에 고의로 불법행위를 행한 자가 있는 경우에는 피해자에게 과실이 없는 것으로 보아야 한다거나 모든 불법행위자가 과실상계의 주장을 할 수 없게 된다는 의미는 아니다.\nㅁ.실화가 중과실로 인한 것이 아닌 경우 배상의무자는 법원에 손해배상액의 경감을 청구할 수 있고, 이러한 청구가 있을 경우 법원은 배상의무자 및 피해자의 경제 상태 등을 고려하여 그 손해배상액을 경감하여야 한다.","o":["ㄱ, ㄴ","ㄷ, ㄹ","ㄱ, ㅁ","ㄴ, ㄹ","ㄷ, ㅁ"],"a":5}},{"y":2024,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2024_30-04-1","t":"특정물의 인도가 채권의 목적인 때에는 채무자는 그 물건을 인도하기까지 선량한 관리자의 주의로 보존하여야 하므로, 보수없이 임치를 받은 자의 경우에도 선량한 관리자의 주의로 임치물을 보관해야 한다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2024_30-04-2","t":"원본채권의 소멸시효가 지분적 이자채권의 소멸시효에 앞서 완성되면 지분적 이자채권은 그 자체의 소멸시효가 완성되지 않더라도 소멸한다.","ox":"O","m":"②","c":"A","tp":"채권의 목적"},{"y":2024,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2024_30-04-3","t":"채권액이 외국통화로 지정된 금전채권인 외화채권을 채무자가 우리나라 통화로 변제함에 있어서 현실이행시의 외국환시세에 의하여 환산한 우리나라 통화로 변제하여야 하므로, 채권자가 위와 같은 외화채권을 대용급부의 권리를 행사하여 우리나라 통화로 환산하여 청구하는 경우에도 법원이 채무자에게 그 이행을 명함에 있어서는 채무자가 현실로 이행할 때에 가장 가까운 사실심 변론종결 당시의 외국환 시세를 우리나라 통화로 환산하는 기준시로 삼아야 한다.","ox":"O","m":"③","c":"A","tp":"채권의 목적"},{"y":2024,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2024_30-04-4","t":"금전채무의 지연손해금채무는 금전채무의 이행지체로 인한 손해배상채무로서 이행기의 정함이 없는 채무에 해당하므로, 채무자는 확정된 지연손해금채무에 대하여 채권자로부터 이행청구를 받은 때로부터 지체책임을 부담하게 된다.","ox":"O","m":"④","c":"A","tp":"채권의 목적"},{"y":2024,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2024_30-04-5","t":"금전으로 가액을 산정할 수 없는 것이라도 채권의 목적으로 할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2024_30-09-1","t":"채권자의 채권이 사해행위 이전에 성립되어 있는 이상 그 채권이 양도된 경우에도 그 양수인이 채권자취소권을 행사할 수 있으나, 이 경우 채권양도의 대항요건을 사해행위 이후에 갖추었다면, 채권양수인으로서는 채무자에게 채권양도로 대항할 수 없는 만큼 채권자취소권을 행사할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2024_30-09-2","t":"채권자취소권 행사는 채무 이행을 구하는 것이 아니라 총채권자를 위하여 채무자의 자력 감소를 방지하고, 일탈된 채무자의 책임재산을 회수하여 채권의 실효성을 확보하는 데 목적이 있으나, 채무자의 법률행위를 취소하는 법률효과를 부여하는 채권자취소권의 내용에 비추어 볼 때 피보전채권이 사해행위 이전에 이미 성립되어 있다면, 그 액수나 범위가 구체적으로 확정되어야 할 것이다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2024_30-09-3","t":"어느 부동산에 관한 법률행위가 사해행위에 해당하는 경우에 그 부동산에 관하여 주택임대차보호법 제3조 제1항이 정한 대항력을 갖추고 임대차계약서에 확정일자를 받아 임대차보증금 우선변제권을 가진 임차인 또는 같은 법제8조에 의하여 임대차보증금 중 일정액을 우선하여 변제받을 수 있는 소액임차인이 있는 때에는 수익자가 배상하여야 할 부동산의 가액에서 그 우선변제권 있는 임차보증금 반환채권 금액을 공제하여서는 아니된다.","ox":"X","m":"③","c":"A","tp":"채권자취소권"},{"y":2024,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2024_30-09-4","t":"저당권이 이미 설정되어 있는 부동산에 관하여 사해행위가 이루어진 경우에 그 사해행위는 부동산의 가액에서 저당권의 피담보채권액을 공제한 잔액의 범위 내에서만 성립한다고 보아야 하므로, 사해행위 후 변제 등에 의하여 저당권설정등기가 말소된 경우, 사해행위를 취소하여 그 부동산 자체의 회복을 명하는 것은 당초 일반 채권자들의 공동담보로 되어 있지 아니하던 부분까지 회복을 명하는 것이 되어 공평에 반하는 결과가 되므로, 그 부동산의 가액에서 저당권의 피담보채무액을 공제한 잔액의 한도에서 사해행위를 취소하고 그 가액의 배상을 구할 수 있을 뿐이고, 그와 같은 가액 산정은 변제 등에 의하여 저당권설정등기가 말소될 당시를 기준으로 하여야 한다.","ox":"X","m":"④","c":"A","tp":"채권자취소권"},{"y":2024,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2024_30-09-5","t":"처분행위 당시에는 채권자를 해하는 것이었다고 하더라도 그 후 채무자가 자력을 회복하여 사해행위취소권을 행사하는 사실심의 변론종결시에는 채권자를 해하지 않게 된 경우에는 책임재산 보전의 필요성이 없어지게 되어 채권자취소권이 소멸하는 것으로 보아야 할 것인바, 그러한 사정변경이 있다는 사실은 채권자취소소송의 상대방이 증명하여야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2024_30-33","t":"채무불이행에 관한 다음 설명 중 가장 옳은 것은?","c":"A","mc":{"s":"채무불이행에 관한 다음 설명 중 가장 옳은 것은?","d":"","o":["금전채무의 이행지체로 인하여 발생하는 지연이자는 단기소멸시효에 관한 민법 제163조 제1호가 규정한 ‘1년 이내의 기간으로 정한 채권’에 해당하여 3년의 단기소멸시효의 대상이 된다.","매도인이 매수인으로부터 중도금을 지급받아 원매도인에게 매매잔대금을 지급하지 아니하고서는 토지의 소유권이전등기서류를 갖추어 매수인에게 제공하기 어려운 특별한 사정이 있었고, 매수인도 그러한 사정을 알고 매매계약을 체결하였던 경우라도 매수인의 중도금 지급의무는 당초 계약상의 잔금지급기일을 도과하였다면 매도인의 소유권이전등기서류의 제공과 동시이행의 관계에 있게 된다.","이행기의 정함이 없는 채권을 양수한 채권양수인이 채무자를 상대로 그 이행을 구하는 소를 제기하고 소송 계속 중 채무자에 대한 채권양도통지가 이루어진 경우 특별한 사정이 없는 한 채무자는 소장 부본을 송달받은 다음 날부터 이행지체의 책임을 진다.","소유자가 자신의 소유권에 기하여 실체관계에 부합하지 아니하는 등기의 명의인을 상대로 그 등기말소를 청구하는 경우 그 권리는 물권적 청구권으로서의 방해배제청구권의 성질을 가지므로 소유자가 그 후에 소유권을 상실함으로써 등기말소를 청구할 수 없게 되었다면, 소유자는 등기말소 의무자에 대하여 그 권리의 이행불능을 이유로 한 민법 제390조상의 손해배상청구권을 가진다.","채무불이행으로 인한 손해배상청구소송에서 재산적 손해의 발생사실이 인정되나 구체적인 손해의 액수를 증명하는 것이 사안의 성질상 곤란한 경우, 법원은 증거조사의 결과와 변론 전체의 취지에 의하여 밝혀진 당사자들 사이의 관계, 채무불이행과 그로 인한 재산적 손해가 발생하게 된 경위, 손해의 성격, 손해가 발생한 이후의 제반 정황 등의 관련된 모든 간접사실들을 종합하여 적당하다고 인정되는 금액을 손해의 액수로 정할 수 있다."],"a":5}},{"y":2024,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2024_30-40-1","t":"채권자대위권은 채무자의 제3채무자에 대한 권리를 행사하는 것이므로, 제3채무자는 채무자에 대해 가지는 모든 항변사유로 채권자에게 대항할 수 있고, 공평의 원칙상 채권자도 채무자 자신이 주장할 수 있는 사유의 범위뿐만 아니라 채권자 자신과 제3채무자 사이의 독자적인 사정에 기한 사유도 함께 주장할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2024_30-40-2","t":"채권자대위권은 채무자가 제3채무자에 대한 권리를 행사하지 아니하는 경우에 한하여 채권자가 자기의 채권을 보전하기 위하여 행사할 수 있는 것이기는 하나, 채권자가 대위권을 행사할 당시 이미 채무자가 그 권리를 재판상 행사하였으나 이후 불성실한 소송수행 등으로 패소의 확정판결을 받은 경우라면, 채권자는 채무자를 대위하여 채무자의 권리를 행사할 당사자적격이 있다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2024_30-40-3","t":"임대인의 임대차계약 해지권은 오로지 임대인의 의사에 행사의 자유가 맡겨져 있어 민법 제404조 제1항 후단에서 정하는 채권자대위권의 소극적 요건 중 하나인 ‘행사상의 일신전속권’에 해당하는 것으로 볼 수 있으므로, 채권자대위권의 대상이 되지 아니한다.","ox":"X","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2024_30-40-4","t":"부동산의 소유자에 대하여 소유권이전등기를 청구할 지위에 있기는 하지만 아직 그 소유권이전등기를 경료하지 않은 상태에서, 제3자가 부동산의 소유자를 상대로 그 부동산에 관한 소유권이전등기절차 이행의 확정판결을 받아 소유권이전등기를 경료한 경우, 그 확정판결이 당연무효이거나 재심의 소에 의하여 취소되지 않았더라도, 종전의 소유권이전등기청구권을 가지는 자가 부동산의 소유자에 대한 소유권이전등기청구권을 보전하기 위하여 부동산의 소유자를 대위하여 제3자 명의의 소유권이전등기가 원인무효임을 내세워 그 등기의 말소를 구할 수 있다.","ox":"X","m":"④","c":"A","tp":"채권자대위"},{"y":2024,"e":"법무사 1차","qn":40,"lv":3,"i":"법무사2024_30-40-5","t":"채무자 소유의 부동산을 시효취득한 채권자의 공동상속인이 채무자에 대한 소유권이전등기청구권을 피보전채권으로 하여 제3채무자를 상대로 채무자의 제3채무자에 대한 소유권이전등기의 말소등기청구권을 대위행사하는 경우, 공동상속인은 자신의 지분 범위 내에서만 채무자의 제3채무자에 대한 소유권이전등기의 말소등기청구권을 대위행사할 수 있고, 지분을 초과하는 부분에 관하여는 채무자를 대위할 보전의 필요성이 없다.","ox":"O","m":"⑤","c":"A","tp":"채권자대위"},{"y":2025,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2025_31-01","t":"채권자취소권에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"채권자취소권에 관한 다음 설명 중 옳은 것을 모두 고른 것은?","d":"ㄱ.사해행위가 채권자에 의하여 취소되기 전에 이미 수익자 또는 전득자가 배당금을 현실로 지급받은 경우, 채권자는 원상회복방법으로 수익자 또는 전득자를 상대로 배당으로 수령한 금원 중 자신의 채권액 상당의 지급을 가액배상의 방법으로 청구할 수 있다.\nㄴ.수익자가 채무초과 상태에 있는 채무자의 부동산에 관하여 설정된 선순위 근저당권의 피담보채무를 변제하여 근저당권설정등기를 말소하는 대신 동일한 금액을 피담보채무로 하는 새로운 근저당권설정등기를 설정하면 사해행위가 성립한다.\nㄷ.채권자가 전득자를 상대로 하여 사해행위취소의 소를 제기하는 경우, 취소의 대상이 되는 사해행위는 채무자와 수익자 사이에서 행하여진 법률행위에 국한될 뿐 수익자와 전득자 사이의 법률행위는 그 대상이 되지 않는다.\nㄹ.원고의 피고에 대한 청구의 원인행위가 사해행위라는 이유로 원고에 대하여 사해행위취소를 청구하면서 독립당사자참가신청을 하는 경우, 독립당사자참가인의 청구가 그대로 받아들여진다 하더라도 원고와 피고 사이의 법률관계에는 아무런 영향이 없고, 따라서 그러한 참가신청은 사해방지참가의 목적을 달성할 수 없으므로 부적법하다.\nㅁ.가등기에 기하여 본등기가 경료된 경우 가등기의 원인인 법률행위와 본등기의 원인인 법률행위가 명백히 다른 경우가 아닌 한 사해행위 요건의 구비 여부는 본등기 경료 당시를 기준으로 하여 판단하여야 한다.","o":["ㄱ, ㄷ, ㄹ","ㄱ, ㄷ, ㅁ","ㄱ, ㄹ, ㅁ","ㄴ, ㄷ, ㅁ","ㄴ, ㄷ, ㄹ"],"a":1}},{"y":2025,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2025_31-10-1","t":"채권자가 채무자를 대위하여 제3채무자에 대하여 보전행위 이외의 권리를 행사한 때에는 채무자에게 통지하여야 하고, 채무자가 그 통지를 받은 후에는 그 권리를 처분하여도 이로써 채권자에게 대항하지 못한다.","ox":"O","m":"①","c":"A","tp":"채권자대위권"},{"y":2025,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2025_31-10-2","t":"민법상 조합원의 조합탈퇴권은 그 성질상 조합계약의 해지권으로서 그의 일반재산을 구성하는 재산권의 일종이라 할 것이고 채권자대위가 허용되지 않는 일신전속적 권리라고는 할 수 없다.","ox":"O","m":"②","c":"A","tp":"채권자대위권"},{"y":2025,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2025_31-10-3","t":"이혼으로 인한 재산분할청구권은 이혼을 한 당사자의 일방이 다른 일방에 대하여 재산분할을 청구할 수 있는 권리로서 청구인의 재산에 영향을 미치는 재산법적 행위이므로 채권자대위권의 목적이 될 수 있다.","ox":"X","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2025_31-10-4","t":"채권자대위소송에서 피대위자인 채무자가 실존인물이 아니거나 사망한 사람인 경우 피보전채권인 채권자의 채무자에 대한 권리를 인정할 수 없는 경우에 해당하므로 그러한 채권자대위소송은 당사자적격이 없어 부적법하다.","ox":"O","m":"④","c":"A","tp":"채권자대위권"},{"y":2025,"e":"법무사 1차","qn":10,"lv":3,"i":"법무사2025_31-10-5","t":"피보전채권이 특정채권이라 하여 반드시 순차매도 또는 임대차에 있어 소유권이전등기청구권이나 인도청구권 등의 보전을 위한 경우에만 한하여 채권자대위권이 인정되는 것은 아니며, 물권적 청구권에 대하여도 채권자대위권에 관한 규정과 법리가 적용될 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2025_31-21-1","t":"불법행위로 인한 손해배상채무는 손해발생과 동시에 이행기에 있는 것으로, 공평의 관념상 별도의 이행최고가 없더라도 불법행위 당시부터 지연손해금이 발생하는 것이 원칙이다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2025_31-21-2","t":"매매계약이 해제되면 그 효력이 소급적으로 소멸함에 따라 각 당사자는 상대방에 대하여 원상회복의무가 있으므로 이미 그 계약상 의무에 기하여 이행된 급부는 원상회복을 위하여 부당이득으로 반환되어야 하고, 그 원상회복의 대상에는 매매대금은 물론 이와 관련하여 그 매매계약의 존속을 전제로 수령한 지연손해금도 포함된다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2025_31-21-3","t":"금전채무의 지연손해금채무는 금전채무의 이행지체로 인한 손해배상채무로서 이행기의 정함이 없는 채무에 해당하므로, 채무자는 확정된 지연손해금채무에 대하여 채권자로부터 이행청구를 받은 때부터 지체책임을 부담하게 된다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2025_31-21-4","t":"금전채무에 관하여 이행지체에 대비한 지연손해금 비율을 따로 약정한 경우에 이는 일종의 손해배상액의 예정으로서 민법 제398조 제2항에 의한 감액의 대상이 된다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2025_31-21-5","t":"상계적상 시점 이전에 수동채권에 대하여 이자나 지연손해금이 발생한 경우 상계적상 시점까지 수동채권의 이자나 지연손해금을 계산한 다음 자동채권으로써 먼저 수동채권의 원본을 소각하고 잔액을 가지고 이자나 지연손해금을 소각하여야 한다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2026_32-12-1","t":"소장에서 채권 일부만을 청구하면서 장차 청구금액을 확장할 뜻을 표시했다가 그 후 채권의 특정 부분을 청구범위에서 명시적으로 제외한 경우, 그 제외된 부분에 대하여는 애초부터 소가 제기되지 않은 것과 마찬가지이므로 재판상 청구로 인한 시효중단의 효력이 발생하지 않는다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2026_32-12-2","t":"불법행위로 인한 손해배상청구권의 단기소멸시효 기산점인 ‘손해 및 가해자를 안 날’이란 위법한 가해행위의 존재, 손해의 발생, 상당인과관계 등 불법행위의 요건사실을 현실적⋅구체적으로 인식한 때를 의미한다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2026_32-12-3","t":"송금의뢰인이 착오송금임을 이유로 반환을 요청하고 수취인도 이를 인정하여 반환을 승낙하고 있는 경우, 수취은행이 수취인에 대한 대출채권을 자동채권으로 하여 착오로 입금된 금원 상당의 예금채권과 상계하는 것은 특별한 사정이 없는 한 신의칙에 반하거나 상계권 남용에 해당한다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2026_32-12-4","t":"조합원 중 1인이 자기의 출재로 조합채무를 면책시킨 경우 그 조합원은 다른 조합원에 대하여 구상권을 행사할 수 있고, 이러한 구상권은 반드시 조합의 잔여재산분배 절차에서 행사해야 하는 것은 아니다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":12,"lv":3,"i":"법무사2026_32-12-5","t":"부동산의 매매로 인한 소유권이전등기청구권은 특별한 사정이 없는 이상 그 권리의 성질상 양도가 가능하므로, 양도인이 채무자에 대한 양도통지를 하면 채무자에 대한 대항력이 생긴다.","ox":"X","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2026_32-30","t":"손해배상액의 예정에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"손해배상액의 예정에 관한 다음 설명 중 옳지 않은 것을 모두 고른 것은?","d":"ㄱ.위약벌은 손해배상액의 예정과 함께 위약금의 일종으로서 손해배상액의 예정에 관한 민법 제398조 제2항을 유추하여 감액할 수 있다.\nㄴ.법원은 손해배상 예정액이 부당히 과다한지를 판단할 때 사실심의 변론종결 당시를 기준으로 그 사이에 발생한 사정을 종합적으로 고려하여야 한다.\nㄷ.감액사유에 대한 사실인정이나 그 비율을 정하는 것은 사실심의 전권에 속하는 사항이므로, 손해배상액 예정이 없더라도 채무자가 당연히 지급의무를 부담하여 채권자가 받을 수 있던 금액보다 적은 금액으로 감액하는 것도 가능하다.\nㄹ.위약금은 손해배상액의 예정으로 추정되므로, 위약금을 위약벌로 해석하기 위해서는 이를 위약벌로 인정할 만한 특별한 사정이 있어야 한다.\nㅁ.위약금 약정이 손해배상액의 예정과 위약벌의 성격을 함께 가지는 경우 특별한 사정이 없는 한 법원은 당사자의 주장이 없더라도 직권으로 민법 제398조 제2항에 따라 위약금 전체 금액을 기준으로 감액할 수 있다.","o":["ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄷ","ㄷ, ㅁ","ㄱ, ㅁ"],"a":2}},{"y":2026,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2026_32-35-1","t":"채무자가 유일한 재산인 그 소유의 부동산에 관한 매매예약에 따른 예약완결권이 제척기간 경과가 임박하여 소멸할 예정인 상태에서 제척기간을 연장하기 위하여 새로 매매예약을 하는 행위는 채무자가 부담하지 않아도 될 채무를 새롭게 부담하게 되는 결과가 되므로 채권자취소권의 대상인 사해행위가 될 수 있다.","ox":"O","m":"①","c":"A","tp":"사해행위취소"},{"y":2026,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2026_32-35-2","t":"사해행위취소에 따른 원물반환이 불가능하거나 현저히 곤란한 경우 원상회복의무의 이행으로서 사해행위 목적물의 가액 상당을 배상하여야 하는데, 여기서 원물반환이 불가능하거나 현저히 곤란한 경우는 원물반환이 사회생활상의 경험법칙 또는 거래상의 관념에 비추어 채권자가 수익자나 전득자로부터 이행의 실현을 기대할 수 없는 경우를 말한다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2026_32-35-3","t":"사해행위의 취소와 원상회복은 모든 채권자의 이익을 위하여 그 효력이 있으므로, 채권자취소권의 행사로 채무자에게 회복된 재산에 대하여 취소채권자가 우선변제권을 가지는 것이 아니라 다른 채권자도 총채권액 중 자기의 채권에 해당하는 안분액을 변제받을 수 있으므로, 다른 채권자는 취소채권자를 상대로 직접 자기의 채권액에 해당하는 안분액의 지급을 청구할 권리를 가진다.","ox":"X","m":"③","c":"A","tp":"사해행위취소"},{"y":2026,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2026_32-35-4","t":"채권자취소권은 모든 채권자를 위하여 채무자의 책임재산을 보전하는 권리이지만, 사해행위 이후에 채권을 취득한 채권자는 채권의 취득 당시에 사해행위취소에 의하여 회복되는 재산을 채권자의 공동담보로 파악하지 아니한 자로서 민법 제407조 소정의 사해행위취소와 원상회복의 효력을 받는 채권자에 포함되지 아니 한다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":35,"lv":3,"i":"법무사2026_32-35-5","t":"사해행위취소소송에서 수익자가 사해행위임을 몰랐다는 사실은 수익자 자신이 증명하여야 한다.","ox":"O","m":"⑤","c":"A"}],"8":[{"y":2016,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2016_22-24-1","t":"채무자의 채권양도인에 대한 자동채권이 발생하는 기초가 되는 원인이 양도 전에 이미 성립하여 존재하고 그 자동채권이 수동채권인 양도채권과 동시이행의 관계에 있는 경우에는, 양도통지가 채무자에게 도달하여 채권양도의 대항요건이 갖추어진 후에 자동채권이 발생하였다고 하더라도 채무자는 동시이행의 항변권을 주장할 수 있고, 따라서 그 채권에 의한 상계로 양수인에게 대항할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2016,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2016_22-24-2","t":"가분적인 금전채권의 일부에 대한 전부명령이 확정된 경우 그 채권에 대하여 압류채무자에 대한 반대채권으로 상계하고자 하는 제3채무자로서는 전부채권자 혹은 압류채무자 중 어느 누구도 상계의 상대방으로 지정하여 상계하거나 상계로 대항할 수 있고, 그러한 제3채무자의 상계 의사표시를 수령한 전부채권자는 압류채무자에 잔존한 채권 부분이 먼저 상계되어야 한다거나 각 분할채권액의 채권 총액에 대한 비율에 따라 상계되어야 한다는 이의를 할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2016,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2016_22-24-3","t":"고의의 불법행위 채권을 자동채권으로 하여 상계할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2016,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2016_22-24-4","t":"불법행위 또는 채무불이행에 따른 채무자의 손해배상액을 산정할 때에 손해부담의 공평을 기하기 위하여 채무자의 책임을 제한할 필요가 있고, 채무자가 채권자에 대하여 가지는 반대채권으로 상계항변을 하는 경우에는 먼저 상계한 후 책임제한을 하여야 한다.","ox":"X","m":"④","c":"A"},{"y":2016,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2016_22-24-5","t":"수탁보증인이 주채무자에 대하여 가지는 사전구상권을 자동채권으로 하는 상계는 허용될 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2016,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2016_22-27-1","t":"매매로 인한 소유권이전등기청구권은 특별한 사정이 없는 이상 그 권리의 성질상 양도가 제한되고 그 양도에 채무자의 승낙이나 동의를 요한다고 할 것이므로 통상의 채권양도와 달리 양도인의 채무자에 대한 통지만으로는 채무자에 대한 대항력이 생기지 않으며 반드시 채무자의 동의나 승낙을 받아야 대항력이 생긴다.","ox":"O","m":"①","c":"A","tp":"지명채권 양도"},{"y":2016,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2016_22-27-2","t":"당사자의 의사표시에 의한 채권양도 금지는 제3자가 악의의 경우는 물론 제3자가 채권양도 금지를 알지 못한 데에 중대한 과실이 있는 경우 그 채권양도 금지로써 대항할 수 있다.","ox":"O","m":"②","c":"A","tp":"지명채권 양도"},{"y":2016,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2016_22-27-3","t":"종전의 채권자가 채권의 추심 기타 행사를 위임하여 채권을 양도하였으나 양도의 ‘원인’이 되는 그 위임이 해지 등으로 효력이 소멸한 경우에 이로써 채권은 양도인에게 복귀하게 되고, 나아가 양수인은 그 양도의무계약의 해지로 인하여 양도인에 대하여 부담하는 원상회복의무의 한 내용으로 채무자에게 이를 통지할 의무를 부담한다고 봄이 상당하다.","ox":"O","m":"③","c":"A","tp":"지명채권 양도"},{"y":2016,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2016_22-27-4","t":"당사자 사이에 양도금지의 특약이 있는 채권이더라도 전부명령에 의하여 전부되는 데에는 지장이 없고, 양도금지의 특약이 있는 사실에 관하여 집행채권자가 선의인가 악의인가는 전부명령의 효력에 영향을 미치지 못하는 것이지만, 그 전부채권자로부터 다시 그 채권을 양수한 자가 그 특약의 존재를 알았거나 중대한 과실로 알지 못한 경우 채무자는 위 특약을 근거로 삼아 채권양도의 무효를 주장할 수 있다.","ox":"X","m":"④","c":"A","tp":"지명채권 양도"},{"y":2016,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2016_22-27-5","t":"채무자가 양도되는 채권의 성립이나 소멸에 영향을 미치는 사정에 관하여 양수인에게 알려야 할 신의칙상 주의의무가 있다고 볼 만한 특별한 사정이 없는 한 채무자가 그러한 사정을 알리지 아니하였다고 하여 불법행위가 성립한다고 볼 수 없다.","ox":"O","m":"⑤","c":"A","tp":"지명채권 양도"},{"y":2016,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2016_22-28-1","t":"변제는 채무내용에 좇은 현실제공으로 이를 하여야 한다. 그러나 채권자가 미리 변제받기를 거절하거나 채무의 이행에 채권자의 행위를 요하는 경우에는 변제준비의 완료를 통지하고 그 수령을 최고하면 된다.","ox":"O","m":"①","c":"A","tp":"변제 또는 변제충당"},{"y":2016,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2016_22-28-2","t":"채무자는 물론 채권자라고 할지라도 비용, 이자, 원본의 순서와 다르게 일방적으로 충당의 순서를 지정할 수는 없으므로, 당사자의 일방적인 지정에 대하여 상대방이 지체 없이 이의를 제기하지 아니함으로써 묵시적 합의가 되었다고 보여지는 경우라도 위 법정충당의 순서와는 달리 충당의 순서를 인정할 수는 없다.","ox":"X","m":"②","c":"A","tp":"변제 또는 변제충당"},{"y":2016,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2016_22-28-3","t":"변제자가 주채무자인 경우 보증인이 있는 채무와 보증인이 없는 채무 사이에 변제이익의 점에서 차이가 없다.","ox":"O","m":"③","c":"A","tp":"변제 또는 변제충당"},{"y":2016,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2016_22-28-4","t":"변제자가 채무자인 경우 물상보증인이 제공한 물적 담보가 있는 채무와 그러한 담보가 없는 채무 사이에 변제이익의 점에서 차이가 없다.","ox":"O","m":"④","c":"A","tp":"변제 또는 변제충당"},{"y":2016,"e":"법무사 1차","qn":28,"lv":3,"i":"법무사2016_22-28-5","t":"채권자의 태도로 보아 채무자가 설사 채무의 이행제공을 하였더라도 그 수령을 거절하였을 것이 명백한 경우에는 채무자는 이행의 제공을 하지 않고 바로 변제공탁할 수 있는 것이다.","ox":"O","m":"⑤","c":"A","tp":"변제 또는 변제충당"},{"y":2017,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2017_23-04-1","t":"채무자가 이의를 보류하지 아니하고 채권양도에 관하여 승낙을 한 때에는 양도인에게 대항할 수 있는 사유로써 양수인에게 대항하지 못한다. 따라서 보험자가 보험금청구권 양도 승낙시에 면책사유에 대한 이의를 보류하지 않았다면 보험계약상의 면책사유를 양수인에게 주장할 수 없다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2017_23-04-2","t":"채권의 양도는 양도인이 채무자에게 통지하거나 채무자가 승낙하지 아니하면 채무자 기타 제3자에게 대항하지 못한다. 그러나 대항요건을 갖추지 못하여 채무자에게 대항하지 못한다고 하더라도 채권의 양수인이 채무자를 상대로 재판상의 청구를 하였다면 이는 소멸시효 중단사유인 재판상의 청구에 해당한다.","ox":"O","m":"②","c":"A","tp":"채권양도"},{"y":2017,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2017_23-04-3","t":"가압류된 채권도 양도가 가능하고, 가압류된 금전채권의 양수인은 제3채무자를 상대로 양수금의 이행을 구하는 소송을 제기할 수도 있다.","ox":"O","m":"③","c":"A","tp":"채권양도"},{"y":2017,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2017_23-04-4","t":"채권양도가 다른 채무의 담보조로 이루어졌으며 또한 그 다른 채무가 변제되었다고 하더라도 양도채권의 채무자로서는 그와 관계없이 채권양수인에게 양도된 채무를 변제하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2017_23-04-5","t":"채권양도의 통지는 민사소송법상의 송달에 관한 규정에서 송달장소로 정하는 채무자의 주소ㆍ거소ㆍ영업소 또는 사무소 등에 해당하지 아니하는 장소에서라도 채무자가 사회통념상 그 통지의 내용을 알 수 있는 객관적 상태에 놓여졌다고 인정됨으로써 족하다고 할 것이다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2017_23-24-1","t":"공탁금출급청구권은 피공탁자가 공탁소에 대하여 공탁금의 지급, 인도를 구하는 청구권으로서 위 청구권이 시효로 소멸한 경우 공탁자에게 공탁금회수청구권이 인정되지 않는 한 그 공탁금은 국고에 귀속하게 된다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2017_23-24-2","t":"변제공탁이 적법한 경우에는 채권자가 공탁물 출급청구를 하였는지 여부와는 관계없이 공탁을 한 때에 변제의 효력이 발생하나, 변제공탁자가 공탁물 회수권의 행사에 의하여 공탁물을 회수한 경우에는 공탁하지 아니한 것으로 보아 채권소멸의 효력은 소급하여 없어진다. 이와 같이 채권소멸의 효력을 소급적으로 소멸시키는 공탁물의 회수에는 공탁자에 의하여 이루어진 경우뿐만 아니라 제3자가 공탁자에 대하여 가지는 별도 채권의 집행권원으로써 공탁자의 공탁물 회수청구권에 대하여 압류 및 추심명령을 받아 그 집행으로 공탁물을 회수한 경우도 포함된다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2017_23-24-3","t":"어음발행인이 지급기일에 피사취신고 등 사고신고를 하면서 어음액면금 상당의 사고신고담보금을 지급은행에 예치하였다면, 이는 어음소지인에 대한 변제공탁으로서 효력을 갖고, 따라서 지급기일부터의 이자나 지연손해금의 발생이 저지되는 효력이 생긴다.","ox":"X","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2017_23-24-4","t":"건물명도와 동시이행관계에 있는 임차보증금의 변제공탁을 함에 있어서 건물을 명도하였다는 확인서를 첨부할 것을 반대급부조건으로 붙였다면 위 변제공탁은 명도의 선이행을 조건으로 한 것이라고 볼 수밖에 없으므로 변제의 효력이 없다고 보아야 할 것이다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":24,"lv":3,"i":"법무사2017_23-24-5","t":"변제의 목적물이 공탁에 적당하지 아니하거나 멸실 또는 훼손될 염려가 있거나 공탁에 과다한 비용을 요하는 경우에는 변제자는 법원의 허가를 얻어 그 물건을 경매하거나 시가로 방매하여 대금을 공탁할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2017_23-34-1","t":"변제자가 주채무자인 경우, 보증인이 있는 채무와 보증인이 없는 채무 사이에 전자가 후자에 비하여 변제이익이 더 많다고 볼 근거는 전혀 없으므로 양자는 변제이익의 점에서 차이가 없다고 보아야 하나, 물상보증인이 제공한 물적 담보가 있는 채무와 그러한 담보가 없는 채무 사이에는 변제이익의 점에서 차이가 있다.","ox":"X","m":"①","c":"A","tp":"변제 또는 변제충당"},{"y":2017,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2017_23-34-2","t":"채무자는 물론 채권자라고 할지라도 비용, 이자, 원본의 순서와 다르게 일방적으로 충당의 순서를 지정할 수는 없으나, 당사자의 일방적인 지정에 대하여 상대방이 지체 없이 이의를 제기하지 아니함으로써 묵시적 합의가 되었다고 보여지는 경우 위 법정충당의 순서와는 달리 충당의 순서를 인정할 수 있다.","ox":"O","m":"②","c":"A","tp":"변제 또는 변제충당"},{"y":2017,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2017_23-34-3","t":"민법 제472조는 불필요한 연쇄적 부당이득반환의 법률관계가 형성되는 것을 피하기 위하여 변제받을 권한 없는 자에 대한 변제의 경우에도 그로 인하여 채권자가 이익을 받은 한도에서 효력이 있다고 규정하고 있다. 그런데 변제수령자가 변제로 받은 급부를 가지고 자신이나 제3자의 채권자에 대한 채무를 변제함으로써 채권자의 기존 채권을 소멸시킨 경우에는 채권자에게 실질적인 이익이 생겼다고 할 수 없으므로 위 규정에 의한 변제의 효력을 인정할 수 없다.","ox":"O","m":"③","c":"A","tp":"변제 또는 변제충당"},{"y":2017,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2017_23-34-4","t":"채권의 일부에 대하여 대위변제가 있는 때에는 대위자는 그 변제한 가액에 비례하여 채권자와 함께 그 권리를 행사하나, 채무불이행을 원인으로 하는 계약의 해지 또는 해제는 채권자만이 할 수 있다.","ox":"O","m":"④","c":"A","tp":"변제 또는 변제충당"},{"y":2017,"e":"법무사 1차","qn":34,"lv":3,"i":"법무사2017_23-34-5","t":"채권의 준점유자에 대한 변제는 변제자가 선의이며 과실 없는 때에 한하여 효력이 있다.","ox":"O","m":"⑤","c":"A","tp":"변제 또는 변제충당"},{"y":2017,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2017_23-36-1","t":"면책적채무인수가 있은 경우, 인수채무의 소멸시효기간은 채무인수와 동시에 이루어진 소멸시효중단사유, 즉 채무승인에 따라 채무인수일로부터 새로이 진행된다.","ox":"O","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2017_23-36-2","t":"인수채무가 원래 5년의 상사시효의 적용을 받던 채무라면 그 후 면책적채무인수에 따라 그 채무자의 지위가 인수인으로 교체되었다고 하더라도 그 소멸시효의 기간은 여전히 5년의 상사시효의 적용을 받는다 할 것이고, 이는 채무인수행위가 상행위나 보조적 상행위에 해당하지 아니한다고 하여 달리 볼 것이 아니다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2017_23-36-3","t":"부동산의 매수인이 매매목적물에 관한 채무를 인수하는 한편 그 채무액을 매매대금에서 공제하기로 약정한 경우, 그 인수는 특별한 사정이 없는 한 매도인을 면책시키는 채무인수가 아니라 이행인수로 보아야 하므로, 설령 매수인이 위 채무를 현실적으로 변제하지 아니하였다 하더라도 그와 같은 사정만으로는 매도인은 매매계약을 해제할 수 없다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2017_23-36-4","t":"제3자가 채무자와의 계약으로 채무를 인수한 경우에는 채권자의 승낙에 의하여 그 효력이 생긴다. 이때 채권자의 승낙 또는 거절의 상대방은 제3자이다.","ox":"X","m":"④","c":"A","tp":"채무인수"},{"y":2017,"e":"법무사 1차","qn":36,"lv":3,"i":"법무사2017_23-36-5","t":"채무자와 인수인의 합의에 의한 중첩적 채무인수는 일종의 제3자를 위한 계약이라고 할 것이므로, 채권자는 인수인에 대하여 채무이행을 청구하거나 기타 채권자로서의 권리를 행사하는 방법으로 수익의 의사표시를 함으로써 인수인에 대하여 직접 청구할 권리를 갖게 된다.","ox":"O","m":"⑤","c":"A"},{"y":2017,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2017_23-37-1","t":"여러 사람이 공동으로 법률상 원인 없이 타인의 재산을 사용한 경우의 부당이득 반환채무는 특별한 사정이 없는 한 불가분적 이득의 반환으로서 불가분채무로 보아야 한다.","ox":"O","m":"①","c":"A","tp":"다수당사자의 채권관계"},{"y":2017,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2017_23-37-2","t":"연대채무자는 자신의 부담부분 이상을 변제하여 공동의 면책을 얻게 하였을 때에 다른 연대채무자에 대하여 구상권을 행사할 수 있으나, 공동불법행위자는 자신의 부담부분 이상을 변제하지 않더라도 다른 공동불법행위자에 대하여 구상권을 행사할 수 있다.","ox":"X","m":"②","c":"A","tp":"다수당사자의 채권관계"},{"y":2017,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2017_23-37-3","t":"어떤 물건에 대하여 직접점유자와 간접점유자가 있는 경우, 그에 대한 점유사용으로 인한 부당이득의 반환의무는 이른바 부진정연대채무의 관계에 있다.","ox":"O","m":"③","c":"A","tp":"다수당사자의 채권관계"},{"y":2017,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2017_23-37-4","t":"부진정연대채무자 중 1인을 위하여 보증인이 된 자가 피보증인을 위하여 그 채무를 변제한 경우에는 그 보증인은 다른 부진정연대채무자들에 대하여 그 부담 부분에 한하여 구상권을 행사할 수 있다.","ox":"O","m":"④","c":"A","tp":"다수당사자의 채권관계"},{"y":2017,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2017_23-37-5","t":"보증채무는 주채무와는 별개의 채무이므로 보증채무 자체의 이행지체로 인한 지연손해금은 보증한도액과는 별도로 보아야 하고, 주채무에 관하여 약정된 연체이율 역시 당연히 보증채무의 연체이율에 적용되는 것은 아니다.","ox":"O","m":"⑤","c":"A","tp":"다수당사자의 채권관계"},{"y":2017,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2017_23-38-1","t":"甲에 대한 乙의 금전채무를 담보하기 위하여 丙이 자신의 부동산에 저당권을 설정해 주었는데, 이 때 乙의 부탁으로 물상보증인이 된 丙은 乙에 대하여 사전구상권을 행사할 수 있다.","ox":"X","m":"①","c":"A"},{"y":2017,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2017_23-38-2","t":"甲에 대한 乙의 금전채무에 대하여 丙과 丁이 연대보증인이 된 경우, 甲의 丁에 대한 채권포기는 乙에게는 그 효력이 미치지 않는다.","ox":"O","m":"②","c":"A"},{"y":2017,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2017_23-38-3","t":"甲에 대한 乙의 금전채무에 대한 보증인 丙은 甲에 대한 자신의 채권으로 채권자의 보증채권과 상계할 수 있을 뿐만 아니라, 乙의 甲에 대한 채권으로도 상계할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2017,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2017_23-38-4","t":"주채무자 甲이 면책행위를 하고도 수탁보증인 乙에게 그 사실을 통지하지 않고 있던 중, 乙이 사전통지를 하지 않고 甲의 면책행위가 있었음을 모르고 이중의 면책행위를 한 경우, 乙은 甲에 대하여 자기의 면책행위가 유효하다고 주장할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2017,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2017_23-38-5","t":"부진정연대채무자 甲이 채권자 乙에 대한 자신의 반대채권으로 상계를 한 경우, 그 상계로 인한 채무소멸의 효력은 소멸한 채무 전액에 관하여 다른 부진정연대채무자 丙에 대하여도 미치고, 위 상계 당시 乙이 丙의 존재를 알지 못하여도 마찬가지이다.","ox":"O","m":"⑤","c":"A"},{"y":2018,"e":"법무사 1차","qn":11,"lv":3,"i":"법무사2018_24-11","t":"경개에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"경개에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["당사자가 채무의 중요한 부분을 변경하는 계약을 한 때에는 구채무는 경개로 인하여 소멸한다.","경개나 준소비대차는 모두 기존채무를 소멸하게 하고 신채무를 성립시키는 계약인 점에 있어서는 동일하지만 경개의 경우에는 기존채무와 신채무 사이에 동일성이 없는 반면, 준소비대차의 경우에는 원칙적으로 동일성이 인정된다는 점에 차이가 있다.","경개계약은 신채권을 성립시키고 구채권을 소멸시키는 처분행위로서 신채권이 성립되면 그 효과는 완결되고 경개계약 자체의 이행의 문제는 발생할 여지가 없으므로 경개에 의하여 성립된 신채무의 불이행을 이유로 경개계약을 해제할 수 없고, 당사자들 사이에서도 그 계약을 합의해제하여 구채권을 부활시킬 수 없다.","경개로 인한 신채무가 원인의 불법 또는 당사자가 알지 못한 사유로 인하여 성립하지 아니하거나 취소된 때에는 구채무는 소멸하지 않는다.","경개의 당사자는 구채무의 담보를 그 목적의 한도에서 신채무의 담보로 할 수 있다. 그러나 제3자가 제공한 담보는 그 승낙을 얻어야 한다. 23-14"],"a":3}},{"y":2018,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2018_24-15","t":"연대 또는 부진정연대채무에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"연대 또는 부진정연대채무에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["민법 제426조 제2항은 “어느 연대채무자가 변제 기타 자기의 출재로 공동면책되었음을 다른 연대채무자에게 통지하지 아니한 경우에 다른 연대채무자가 선의로 채권자에게 변제 기타 유상의 면책행위를 한 때에는 그 연대채무자는 자기의 면책행위의 유효를 주장할 수 있다.”라고 규정하고 있다. 부진정연대채무에 해당하는 공동불법행위로 인한 손해배상채무에 있어서도 연대채무의 경우와 마찬가지로 과실 없는 변제자를 보호할 필요가 있으므로, 위 규정이 유추적용된다.","상계할 채권이 있는 연대채무자가 상계하지 아니한 때에는 그 채무자의 부담부분에 한하여 다른 연대채무자가 상계할 수 있다.","금액이 다른 채무가 서로 부진정연대 관계에 있을 때, 다액채무자가 일부 변제를 하는 경우 변제로 인하여 먼저 소멸하는 부분은 다액채무자가 단독으로 채무를 부담하는 부분이다.","부진정연대채무에서 채무자 1인에 대한 재판상 청구 또는 채무자 1인이 행한 채무의 승인 등 소멸시효 중단사유나 시효이익 포기는 다른 채무자에게 효력을 미치지 않는다.","부진정연대채무자 중 1인이 자신의 채권자에 대한 반대채권으로 상계를 한 경우에 그 상계로 인한 채무소멸의 효력은 소멸한 채무 전액에 관하여 다른 부진정연대채무자에 대하여도 미친다. 이는 부진정연대채무자 중 1인이 채권자와 상계계약을 체결한 경우에도 마찬가지이다. 23-15"],"a":1}},{"y":2019,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2019_25-01-1","t":"보증인의 채권자에 대한 출연행위 당시에는 주채무가 유효하게 존속하고 있었으나 그 후 주계약이 해제된 경우, 보증인은 변제를 수령한 채권자를 상대로 이미 이행한 급부를 부당이득으로 반환청구할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2019_25-01-2","t":"보증인은 주채무자의 채권자에 대한 채권으로 상계할 수 있으며 채권자가 주채무자에 대하여 상계적상에 있는 자동채권을 상계하지 않는 경우에는 이를 이유로 보증채무의 이행을 거부할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2019_25-01-3","t":"보증인이 주채무자의 기망행위에 의하여 주채무가 있는 것으로 믿고 주채무자와 보증계약을 체결한 후 그에 따라 보증채무자로서 그 채무까지 이행한 경우, 그 보증인은 주채무자의 채권자에 대한 채무부담행위라는 허위표시에 기초하여 구상권 취득에 관한 법률상 이해관계를 가지게 되었으므로 민법 제108조 제2항의 제3자에 해당한다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2019_25-01-4","t":"손해담보계약상 담보의무자의 책임은 손해배상책임이 아니라 이행의 책임이므로, 민법 제396조의 과실상계 규정이 준용될 수 없고, 과실상계의 법리를 유추적용하여 그 담보책임을 감경할 수도 없다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2019_25-01-5","t":"보증기간과 보증한도액의 정함이 없는 계속적 보증계약의 경우, 보증인이 사망하면 상속인은 보증인의 지위를 상속하지 않고 이미 발생한 보증채무만을 상속한다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2019_25-21-1","t":"비용, 이자, 원본에 대한 변제충당의 순서는 민법 제479조에 법정되어 있으므로 당사자 사이에 그와 다른 특별한 합의가 있었다는 등의 특단의 사정이 없는 한 위의 법정순서에 의하여 변제충당이 이루어져야 한다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2019_25-21-2","t":"수인이 시기를 달리하여 채권의 일부씩을 대위변제하고 근저당권 일부이전의 부기등기를 각 경료한 경우 그들은 각 일부대위자로서 그 변제한 가액에 비례하여 근저당권을 준공유하고 있다고 보아야 하고, 그 근저당권을 실행하여 배당함에 있어서는 다른 특별한 사정이 없는 한 각 변제채권액에 비례하여 안분배당하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2019_25-21-3","t":"변제자가 주채무자인 경우 보증인이 있는 채무와 보증인이 없는 채무 사이에 전자가 후자에 비하여 변제이익이 더 많다고 볼 근거는 전혀 없으므로 양자는 변제이익의 점에서 차이가 없다고 보아야 한다. 마찬가지로 변제자가 채무자인 경우 물상보증인이 제공한 물적 담보가 있는 채무와 그러한 담보가 없는 채무 사이에도 변제이익의 점에서 차이가 없다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2019_25-21-4","t":"이해관계 없는 제3자는 채무자의 의사에 반하여 변제하지 못하는데, 부동산의 매수인은 그 권리실현에 장애가 되는 그 부동산에 대한 담보권 등의 권리를 소멸시키기 위하여 매도인의 채무를 대신 변제할 법률상 이해관계 있는 제3자라고 볼 것이다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":21,"lv":3,"i":"법무사2019_25-21-5","t":"본래의 청구권에 선이행청구 또는 동시이행의 항변권이 붙은 경우 채권자는 자기의 상대의무 이행을 하지 아니하면 공탁물을 수령하지 못하고, 반대로 채권자가 어떤 반대급부 기타의 조건이행을 필요로 하지 않고 곧바로 수령할 수 있는 권리를 갖는 경우에 채무자가 채권자의 어떤 행위의 이행을 조건으로 공탁하였다면 이러한 조건만 무효로 될 뿐이어서 결과적으로 공탁 자체는 유효하게 된다.","ox":"X","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2019_25-31-1","t":"채권양도금지의 특약에 위반해서 채권을 제3자에게 양도한 경우에 악의 또는 중과실의 채권양수인에 대하여는 채권 이전의 효과가 생기지 아니하나, 채무자가 그 양도에 대하여 사후승낙을 한 때에는 무효인 채권양도행위가 추인되어 유효하게 되며, 이 경우 채권양도의 효과는 다른 특별한 사정이 없는 한 채권양도시로 소급하여 발생한다.","ox":"X","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2019_25-31-2","t":"채권에 대한 압류 및 추심명령이 있으면 제3채무자에 대한 이행의 소는 추심채권자만이 제기할 수 있고 채무자는 피압류채권에 대한 이행소송을 제기할 당사자적격을 상실한다.","ox":"O","m":"②","c":"A","tp":"채권양도"},{"y":2019,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2019_25-31-3","t":"매매로 인한 소유권이전등기청구권은 특별한 사정이 없는 한, 그 권리의 성질상 양도가 제한되고 그 양도에 채무자의 승낙이나 동의를 요한다고 할 것이므로, 통상의 채권양도와 달리 양도인의 채무자에 대한 통지만으로는 채무자에 대한 대항력이 생기지 않으며 반드시 채무자의 동의나 승낙을 받아야 대항력이 생긴다.","ox":"O","m":"③","c":"A"},{"y":2019,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2019_25-31-4","t":"취득시효완성으로 인한 소유권이전등기청구권은 채권자와 채무자 사이에 계약관계나 신뢰관계가 없고, 채권자가 채무자에게 반대급부로 부담하여야 하는 의무도 없으므로, 취득시효완성으로 인한 소유권이전등기청구권의 양도의 경우에는 매매로 인한 소유권이전등기청구권에 관한 양도제한의 법리가 적용되지 않는다.","ox":"O","m":"④","c":"A","tp":"채권양도"},{"y":2019,"e":"법무사 1차","qn":31,"lv":3,"i":"법무사2019_25-31-5","t":"채권양도 당시 양도 목적 채권의 채권액이 확정되어 있지 아니하였다 하더라도, 채무의 이행기까지 이를 확정할 수 있는 기준이 설정되어 있다면 그 채권의 양도는 유효한 것으로 보아야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2019,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2019_25-38-1","t":"유치권이 인정되는 아파트를 경매로 취득한 자가 유치권자에 대한 임료 상당의 부당이득금반환채권을 자동채권으로 하고, 유치권자의 종전 소유자에 대한 유익비상환채권을 수동채권으로 하여 상계하는 것은 허용되지 않는다.","ox":"O","m":"①","c":"A"},{"y":2019,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2019_25-38-2","t":"부당이득의 원인이 고의의 불법행위에 기인함으로써 불법행위로 인한 손해배상채권과 부당이득반환채권이 모두 성립하여 양 채권이 경합하는 경우 피해자가 부당이득반환채권만을 청구하고 불법행위로 인한 손해배상채권을 청구하지 아니하였다면, 가해자는 피해자에 대한 채권으로 상계할 수 있다.","ox":"X","m":"②","c":"A"},{"y":2019,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2019_25-38-3","t":"공법상의 확정된 벌금채권도 자동채권으로 될 수 있다.","ox":"O","m":"③","c":"A","tp":"상계"},{"y":2019,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2019_25-38-4","t":"부진정연대채무자 중 1인이 자신의 채권자에 대한 반대채권으로 상계를 한 경우, 그 상계로 인한 채무소멸의 효력은 소멸한 채무 전액에 관하여 다른 부진정연대채무자에 대하여도 미친다.","ox":"O","m":"④","c":"A"},{"y":2019,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2019_25-38-5","t":"공동명의 예금채권자 중 1인에 대한 별개의 대출금채권을 가지는 은행은 그 대출금채권을 자동채권으로 하고, 위 공동명의 예금채권자 중 1인의 지분에 상응하는 예금반환채권을 수동채권으로 하여 상계할 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2020_26-08-1","t":"중과실로 인한 불법행위를 저지른 가해자는 현실적으로 손해배상을 지급할 필요가 있으므로 중과실로 인한 불법행위 손해배상채권을 수동채권으로 하여 가해자가 상계를 하는 것은 금지된다.","ox":"X","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2020_26-08-2","t":"벌금형이 확정되었다면 벌금채권의 변제기는 도래한 것이므로 달리 이를 금하는 특별한 법률상 근거가 없는 이상 벌금채권은 상계의 자동채권이 될 수 있다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2020_26-08-3","t":"소멸시효가 완성된 채권이 그 완성 전에 상계적상에 있었다면 소멸시효가 완성된 채권을 자동채권으로 하여 상계할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2020_26-08-4","t":"고의의 불법행위로 인한 피해자는 가해자에 대한 손해배상채권과 가해자의 자신에 대한 대여금 채권을 상계할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2020_26-08-5","t":"금전채권에 대한 압류 및 전부명령이 있는 때에는 압류된 채권은 동일성을 유지한 채로 압류채무자로부터 압류채권자에게 이전되고, 제3채무자는 채권이 압류되기 전에 압류채무자에게 대항할 수 있는 사유로써 압류채권자에게 대항할 수 있는 것이므로 제3채무자의 압류채무자에 대한 자동채권이 수동채권인 피압류채권과 동시이행의 관계에 있는 경우에는, 압류명령이 제3채무자에게 송달되어 압류의 효력이 생긴 후에 자동채권이 발생하였다고 하더라도 제3채무자는 동시이행의 항변권을 주장할 수 있다.","ox":"O","m":"⑤","c":"A","tp":"상계"},{"y":2020,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2020_26-15-1","t":"변제는 채무내용에 좇은 현실제공으로 이를 하여야 하나, 채권자가 미리 변제받기를 거절하거나 채무의 이행에 채권자의 행위를 요하는 경우에는 변제준비의 완료를 통지하고 그 수령을 최고하면 된다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2020_26-15-2","t":"채무자가 채무 전부를 변제한 때에는 채권자에게 채권증서의 반환을 청구할 수 있으며, 제3자가 변제를 하는 경우에는 제3자도 채권증서의 반환을 구할 수 있으나, 이러한 채권증서 반환청구권은 채권 전부를 변제한 경우에 인정되는 것이고, 영수증 교부의무와는 달리 변제와 동시이행관계에 있지 않다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2020_26-15-3","t":"변제충당지정은 상대방에 대한 의사표시로써 하여야 하나, 채권자와 채무자 사이에 변제충당에 관한 약정이 있고, 그 약정내용이 변제가 채권자에 대한 모든 채무를 소멸시키기에 부족한 때에는 채권자가 적당하다고 인정하는 순서와 방법에 의하여 충당하기로 한 것이라면, 변제수령권자인 채권자가 위 약정에 터 잡아 스스로 적당하다고 인정하는 순서와 방법에 좇아 변제충당을 한 이상 변제자에 대한 의사표시와 관계없이 충당의 효력이 있다고 해석하는 것이 타당하다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2020_26-15-4","t":"담보권 실행을 위한 경매에서 배당된 배당금이 담보권자가 가지는 수개의 피담보채권 전부를 소멸시키기에 부족한 경우에는 민법 제476조에 의한 지정변제충당은 허용될 수 없고, 채권자와 채무자 사이에 변제충당에 관한 합의가 있었다고 하여 그 합의에 따른 변제충당도 허용될 수 없으며, 획일적으로 가장 공평타당한 충당방법인 민법 제477조 및 제479조의 규정에 의한 법정변제충당의 방법에 따라 충당하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":15,"lv":3,"i":"법무사2020_26-15-5","t":"채무의 성질 또는 당사자의 의사표시로 변제장소를 정하지 아니한 때에는 특정물의 인도는 이행기에 그 물건이 있던 장소에서 하여야 한다.","ox":"X","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2020_26-22-1","t":"다수당사자의 채권채무관계는 원칙적으로 분할채권채무관계이고 성질상 또는 당사자의 약정에 기하여 특히 불가분으로 하는 경우에 한하여 불가분채권채무관계로 되는 것이므로 불가분채권채무임을 주장하는 자가 불가분채권채무관계로 하는 의사표시나 특별한 사정을 주장·입증하여야 한다.","ox":"O","m":"①","c":"A","tp":"다수당사자의 법률관계"},{"y":2020,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2020_26-22-2","t":"연대채무자 중 1인에 대하여 생긴 사유 중 채권의 만족을 가져 오는 변제 및 이와 동일시되는 대물변제, 공탁, 경개, 상계의 경우 그 전범위에서 면제, 혼동, 소멸시효 완성의 경우 그 부담부분에 한하여 채무 소멸의 절대적 효력이 인정되므로, 다른 연대채무자는 위 사유들을 채무 소멸의 유효한 항변으로 주장할 수 있다.","ox":"O","m":"②","c":"A","tp":"다수당사자의 법률관계"},{"y":2020,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2020_26-22-3","t":"부진정연대채무는 수인의 채무자가 동일한 내용의 급부에 대하여 각자 독립하여 전부를 급부할 의무를 부담하는 다수당사자의 법률관계로서 채무의 발생원인, 채무의 액수 등이 서로 동일할 것을 요한다.","ox":"X","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2020_26-22-4","t":"인화성 물질 등이 산재한 밀폐된 신축 중인 건물 내부에서 용접작업을 하던 중 화재가 발생하여 피용자가 사망한 사고에서 공사수급인은 건물의 점유자로서 그 보존상의 하자에 따른 불법행위로 인한 손해배상책임을, 사용자는 피용자의 안전에 대한 보호의무를 다하지 아니한 채무불이행으로 인한 손해배상책임을 각 부담하는 경우, 양 채무는 부진정연대채무의 관계에 있다.","ox":"O","m":"④","c":"A","tp":"다수당사자의 법률관계"},{"y":2020,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2020_26-22-5","t":"주택을 공동으로 소유하는 부부가 공동으로 주택을 임대하고 보증금을 수령한 경우 특별한 사정이 없는 한 그 임대는 각자 공유지분을 임대한 것이 아니고 임대목적물을 다수의 당사자로서 공동으로 임대한 것이므로 그 보증금 반환채무는 성질상 불가분채무에 해당된다.","ox":"O","m":"⑤","c":"A","tp":"다수당사자의 법률관계"},{"y":2020,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2020_26-37-1","t":"채권양도에 있어 사회통념상 양도 목적 채권을 다른 채권과 구별하여 그 동일성을 인식할 수 있을 정도이면 그 채권은 특정된 것으로 보아야 할 것이고, 채권양도 당시 양도 목적 채권의 채권액이 확정되어 있지 아니하였다 하더라도 채무의 이행기까지 이를 확정할 수 있는 기준이 설정되어 있다면 그 채권의 양도는 유효한 것으로 보아야 할 것이다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2020_26-37-2","t":"양도금지특약을 위반하여 채권을 제3자에게 양도한 경우에 채권양수인이 양도금지특약이 있음을 알았거나 중대한 과실로 알지 못하였다면 채권 이전의 효과가 생기지 아니한다. 반대로 양수인이 중대한 과실 없이 양도금지특약의 존재를 알지 못하였다면 채권양도는 유효하게 되어 채무자는 양수인에게 양도금지특약을 가지고 채무 이행을 거절할 수 없다. 채권양수인의 악의 내지 중과실은 양도금지특약으로 양수인에게 대항하려는 자가 주장·증명하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2020_26-37-3","t":"채권이 이중으로 양도된 경우 양수인들이 모두 제3자에 대한 대항요건을 갖추었다면 양수인 상호간 우열은 통지 또는 승낙에 붙여진 확정일자의 선후에 의하여 결정한다.","ox":"X","m":"③","c":"A","tp":"채권양도"},{"y":2020,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2020_26-37-4","t":"당사자 사이에 양도금지의 특약이 있는 채권이더라도 전부명령에 의하여 전부되는 데에는 지장이 없고, 양도금지의 특약이 있는 사실에 관하여 집행채권자가 선의인가 악의인가는 전부명령의 효력에 영향을 미치지 못한다.","ox":"O","m":"④","c":"A","tp":"채권양도"},{"y":2020,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2020_26-37-5","t":"채무자가 채권자에게 채무변제와 관련하여 다른 채권을 양도하는 것은 특단의 사정이 없는 한 채무변제를 위한 담보 또는 변제의 방법으로 양도되는 것으로 추정할 것이지 채무변제에 갈음한 것으로 볼 것은 아니어서, 그 경우 채권양도만 있으면 바로 원래의 채권이 소멸한다고 볼 수는 없고 채권자가 양도받은 채권을 변제받은 때에 비로소 그 범위 내에서 채무자가 면책된다.","ox":"O","m":"⑤","c":"A"},{"y":2020,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2020_26-38-1","t":"보증인의 출연행위 당시에는 주채무가 유효하게 존속하고 있었다 하더라도 그 후 주계약이 해제되어 소급적으로 소멸하는 경우에는 보증인은 변제를 수령한 채권자를 상대로 이미 이행한 급부를 부당이득으로 반환청구할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2020,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2020_26-38-2","t":"채무자의 채무불이행시의 손해배상의 범위에 관하여 채무자와 채권자 사이의 합의로 보증인의 관여 없이 그 손해배상 예정액이 결정되었다고 하더라도, 보증인으로서는 위 합의로 결정된 손해배상 예정액이 채무불이행으로 인하여 채무자가 부담할 손해배상 책임의 범위를 초과하지 아니한 한도 내에서만 보증책임이 있다.","ox":"O","m":"②","c":"A"},{"y":2020,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2020_26-38-3","t":"채권자와 주채무자 사이의 확정판결에 의하여 주채무가 확정되어 그 소멸시효기간이 10년으로 연장되었다 할지라도 그 보증채무까지 당연히 단기소멸시효의 적용이 배제되어 10년의 소멸시효기간이 적용되는 것은 아니다.","ox":"O","m":"③","c":"A"},{"y":2020,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2020_26-38-4","t":"확정채무에 대한 연대보증인이더라도 그 채무의 이행기가 연장된 데에 대해 그가 동의한 바 없다면 원래 이행기가 경과한 후 연대보증인으로서의 채무를 부담하지 아니한다.","ox":"X","m":"④","c":"A"},{"y":2020,"e":"법무사 1차","qn":38,"lv":3,"i":"법무사2020_26-38-5","t":"일반적으로 계속적 거래의 도중에 매수인을 위하여 보증의 범위와 기간의 정함이 없이 보증인이 된 자는 특별한 사정이 없는 한 계약일 이후에 발생되는 채무뿐 아니라 계약일 현재 이미 발생된 채무도 보증하는 것으로 보는 것이 상당하다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2021_27-02-1","t":"채권은 양도할 수 있는 것이 원칙이나, 채권의 성질이 양도를 허용하지 않는 경우 및 당사자가 양도 반대의 의사표시를 한 경우에는 양도할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2021_27-02-2","t":"당사자가 양도 반대의 의사표시를 한 경우에, 선의 및 중과실이 아닌 제3자에게는 대항하지 못한다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2021_27-02-3","t":"지명채권의 양도는 양도인이 채무자에게 통지하여야 하고, 채무자가 승낙하지 아니하면 채무자 기타 선의의 제3자에게 대항하지 못한다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2021_27-02-4","t":"채무자가 이의를 보류하고 승낙을 한 때에도 양도인에게 대항할 수 있는 사유로써 양수인에게 대항하지 못한다.","ox":"X","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2021_27-02-5","t":"채무자가 채무를 소멸하게 하기 위하여 양도인에게 급여한 것이 있으면 이를 회수할 수 있으나, 양도인에 대하여 부담한 채무가 있으면 그 성립되지 아니함을 주장할 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2021_27-05-1","t":"면책적 채무인수는 채무자와 인수인 사이의 계약으로도 할 수 있으며, 이 경우 채권자의 승낙이 있어야 그 효력이 발생한다.","ox":"O","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2021_27-05-2","t":"면책적 채무인수에서 채권자가 승낙을 거절하면 그 이후에는 채권자가 다시 승낙하여도 채무인수로서의 효력이 생기지 않는다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2021_27-05-3","t":"채무자와 인수인 사이의 면책적 채무인수약정에 대해 채권자의 승낙이 있는 경우 채무자가 자신의 채무를 담보하기 위해 설정하였던 저당권은 원칙적으로 소멸한다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2021_27-05-4","t":"부동산의 매수인이 매매목적물에 관한 임대차보증금 반환채무를 인수하는 한편 그 채무액을 매매대금에서 공제하기로 약정한 경우 이에 대해 채권자인 임차인의 승낙이 있다면 면책적 채무인수로 볼 수 있다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2021_27-05-5","t":"중첩적 채무인수에서 인수인이 채무자의 부탁 없이 채권자와의 계약으로 채무를 인수하는 것은 매우 드문 일이므로 채무자와 인수인은 원칙적으로 주관적 공동관계가 있는 연대채무관계에 있고, 인수인이 채무자의 부탁을 받지 아니하여 주관적 공동관계가 없는 경우에는 부진정연대관계에 있는 것으로 보아야 한다.","ox":"O","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2021_27-16-1","t":"보증은 그 의사가 보증인의 기명날인 또는 서명이 있는 서면으로 표시되어야 효력이 발생하므로 작성된 서면에 최소한 ‘보증인’ 또는 ‘보증한다’라는 문언의 기재가 있어야 한다.","ox":"X","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2021_27-16-2","t":"보증서의 보증금액은 보증인이 보증책임을 지게 될 주채무에 관한 한도액을 정한 것으로서 그 한도액에는 주채무의 원금 및 이에 대한 이자, 지연손해금과 보증채무 자체의 이행지체로 인한 지연손해금이 모두 포함되므로 그 합계액이 보증의 한도액을 초과해서는 안된다.","ox":"X","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2021_27-16-3","t":"채권자와 주채무자 사이의 확정판결에 의하여 상사채무인 주채무가 확정되어 그 소멸시효기간이 10년으로 연장되었다면 채권자와 연대보증인 사이에 있어서 연대보증채무의 소멸시효기간도 10년으로 연장된다.","ox":"X","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2021_27-16-4","t":"채권자가 보증인에게 채무의 이행을 청구한 때에는 보증인은 주채무자의 변제자력이 있다는 점 및 그 집행이 용이하다는 점을 증명하여 먼저 주채무자에게 청구할 것과 그 재산에 대하여 집행할 것을 항변할 수 있고, 단순히 주채무자에게 먼저 청구할 것을 항변할 수는 없다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":16,"lv":3,"i":"법무사2021_27-16-5","t":"보증채무의 연체이율에 관하여 특별한 약정이 없으면 주채무에 관하여 약정된 연체이율이 적용된다.","ox":"X","m":"⑤","c":"A"},{"y":2021,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2021_27-25-1","t":"상계는 당사자 쌍방이 서로 같은 종류를 목적으로 한 채무를 부담한 경우에 서로 같은 종류의 급부를 현실로 이행하는 대신 어느 일방 당사자의 의사표시로 그 대등액에 관하여 채권과 채무를 동시에 소멸시키는 것이고, 이러한 상계제도의 취지는 서로 대립하는 두 당사자 사이의 채권·채무를 간이한 방법으로 원활하고 공평하게 처리하려는 데 있다. 따라서 수동채권으로 될 수 있는 채권은 상대방이 상계자에 대하여 가지는 채권에 한정되지 않고, 상대방이 제3자에 대하여 가지는 채권과도 상계할 수 있다고 보아야 한다.","ox":"X","m":"①","c":"A"},{"y":2021,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2021_27-25-2","t":"타인의 채무를 담보하기 위하여 그 소유의 부동산에 저당권을 설정한 물상보증인이 타인의 채무를 변제하거나 저당권의 실행으로 저당물의 소유권을 잃은 때에는 채무자에 대하여 구상권을 취득한다(민법 제370조, 제341조). 그런데 구상권 취득의 요건인 ‘채무의 변제’라 함은 채무의 내용인 급부가 실현되고 이로써 채권이 그 목적을 달성하여 소멸하는 것을 의미하므로, 기존 채무가 동일성을 유지하면서 인수 당시의 상태로 종래의 채무자로부터 인수인에게 이전할 뿐 기존 채무를 소멸시키는 효력이 없는 면책적 채무인수는 설령 이로 인하여 기존 채무자가 채무를 면한다고 하더라도 이를 가리켜 채무가 변제된 경우에 해당한다고 할 수 없다. 따라서 채무인수의 대가로 기존 채무자가 물상보증인에게 어떤 급부를 하기로 약정하였다는 등의 사정이 없는 한 물상보증인이 기존 채무자의 채무를 면책적으로 인수하였다는 것만으로 물상보증인이 기존 채무자에 대하여 구상권 등의 권리를 가진다고 할 수 없다.","ox":"O","m":"②","c":"A"},{"y":2021,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2021_27-25-3","t":"일반적으로 당사자 사이에 상계적상이 있는 채권이 병존하고 있는 경우에는 이를 상계할 수 있는 것이 원칙이고, 이러한 상계의 대상이 되는 채권은 상대방과 사이에서 직접 발생한 채권에 한하는 것이 아니라 제3자로부터 양수 등을 원인으로 하여 취득한 채권도 포함한다. 또한 당사자가 상계의 대상이 되는 채권이나 채무를 취득하게 된 목적과 경위, 상계권을 행사함에 이른 구체적·개별적 사정에 비추어，그것이 상계 제도의 목적이나 기능을 일탈하고, 법적으로 보호받을 만한 가치가 없는 경우에는，그 상계권의 행사는 신의칙에 반하거나 상계에 관한 권리를 남용하는 것으로서 허용되지 않는다고 함이 상당하고, 상계권 행사를 제한하는 위와 같은 근거에 비추어 볼 때 일반적인 권리 남용의 경우에 요구되는 주관적 요건을 필요로 하는 것은 아니다.","ox":"O","m":"③","c":"A"},{"y":2021,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2021_27-25-4","t":"민법 제496조는 “채무가 고의의 불법행위로 인한 것인 때에는 그 채무자는 상계로 채권자에게 대항하지 못한다.”라고 정하고 있다. 고의에 의한 불법행위의 발생을 방지함과 아울러 고의의 불법행위로 인한 피해자에게 현실의 변제를 받게 하려는 데이 규정의 취지가 있다. 이 규정은 고의의 불법행위로 인한 손해배상채권을 수동채권으로 한 상계에 관한 것이고 고의의 채무불이행으로 인한 손해배상채권에는 적용되지 않는다. 다만 고의에 의한 행위가 불법행위를 구성함과 동시에 채무불이행을 구성하여 불법행위로 인한 손해배상채권과 채무불이행으로 인한 손해배상채권이 경합하는 경우에는 이 규정을 유추적용할 필요가 있다.","ox":"O","m":"④","c":"A"},{"y":2021,"e":"법무사 1차","qn":25,"lv":3,"i":"법무사2021_27-25-5","t":"당사자 쌍방의 채무가 서로 상계적상에 있다 하더라도, 별도의 의사표시 없이도 상계된 것으로 한다는 특약이 없는한, 그 자체만으로 상계로 인한 채무 소멸의 효력이 생기는 것은 아니고 상계의 의사표시를 기다려 비로소 상계로 인한 채무소멸의 효력이 생긴다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2022_28-02-2","t":"丙이 甲으로부터 청구를 받은 경우, 丙이 乙에게 변제자력이 있는 사실 및 그 집행이 용이할 것을 증명하면 甲은 우선 乙에게 청구하여야 한다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2022_28-02-3","t":"丙이 3,000만 원을 甲에게 변제한 경우 丙은 乙에 대하여는 구상할 수 있지만 丁에 대하여 구상할 수는 없다.","ox":"X","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2022_28-02-4","t":"甲이 丙에 대한 연대보증채권을 피보전권리로 하여 丙 소유의 부동산에 가압류를 하더라도 乙에 대한 채권의 소멸시효는 중단되지 않는다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":2,"lv":3,"i":"법무사2022_28-02-5","t":"丙은 乙이 甲에 대하여 가지는 채권에 의한 상계를 가지고 甲에게 대항할 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2022_28-03-1","t":"보증인은 피보증인의 채무를 변제할 정당한 이익이 있는 자로서 그 변제로 인하여 당연히 채권자를 대위할 법정대위권이 있는 것이므로 다른 특단의 사정이 없는 한 채권자가 고의나 과실로 담보를 상실하게 하거나 감소되게 한 때에는 보증인의 대위권을 침해한 것이 되어 보증인은 민법 제485조에 의하여 그 상실 또는 감소로 인하여 상환을 받을 수 없는 한도에서 그 면책주장을 할 수 있다.","ox":"O","m":"①","c":"A","tp":"대위변제"},{"y":2022,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2022_28-03-2","t":"변제할 정당한 이익이 있는 사람이 채무자를 위하여 채권의 일부를 대위변제할 경우에 대위변제자는 변제한 가액의 범위 내에서 종래 채권자가 가지고 있던 채권 및 담보에 관한 권리를 취득하므로, 채권자가 부동산에 대하여 저당권을 가지고 있는 경우에는 채권자는 대위변제자에게 일부 대위변제에 따른 저당권 일부 이전의 부기등기를 할 의무를 진다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2022_28-03-3","t":"제3자가 유효하게 채무자가 부담하는 채무를 변제한 경우에 채무자와 계약관계가 있으면 그에 따라 구상권을 취득하고, 그러한 계약관계가 없으면 특별한 사정이 없는 한 민법 제734조 제1항에서 정한 사무관리가 성립하여 민법 제739조에 정한 사무관리비용의 상환청구권에 따라 구상권을 취득한다.","ox":"O","m":"③","c":"A","tp":"대위변제"},{"y":2022,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2022_28-03-4","t":"변제할 정당한 이익이 있는 수인이 시기를 달리하여 근저당권의 피담보채권의 일부씩을 대위변제한 경우 그들은 각 일부 대위변제자로서 그 변제한 가액에 비례하여 근저당권을 준공유하고 있다고 보아야 하고, 그 근저당권을 실행하여 배당함에 있어서는 다른 특별한 사정이 없는 한 먼저 대위변제한 순서대로 배당하여야 한다.","ox":"X","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2022_28-03-5","t":"근저당권은 계속적인 거래관계로부터 발생·소멸하는 불특정다수의 채권 중 그 결산기에 잔존하는 채권을 일정한 한도액의 범위 내에서 담보하는 것으로서 그 거래가 종료하기까지 그 피담보채권은 계속적으로 증감·변동하는 것이므로, 근저당 거래관계가 계속되는 관계로 근저당권의 피담보채권이 확정되지 아니하는 동안에는 그 채권의 일부가 대위변제되었다 하더라도 그 근저당권이 대위변제자에게 이전될 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2022_28-04-1","t":"채권의 일부에 대한 대위변제가 있는 때에는 채권자는 채권증서에 그 대위를 기입한 후 그 채권증서 및 점유한 담보물을 대위자에게 교부하여야 한다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2022_28-04-2","t":"변제공탁은 제3자를 위한 계약의 일종이므로, 채권자의 수익의 의사표시가 있는 때에 공탁의 효력이 발생한다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2022_28-04-3","t":"경개로 인한 신채무가 원인의 불법 또는 당사자가 알지 못한 사유로 인하여 성립되지 아니하거나 취소된 때에는 구채무는 소멸되지 아니한다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2022_28-04-4","t":"경개계약은 신채권을 성립시키고 구채권을 소멸시키는 처분행위로서 신채권이 성립되면 그 효과는 완결되고 경개계약 자체의 이행의 문제는 발생할 여지가 없으므로 경개에 의하여 성립된 신채무의 불이행을 이유로 경개계약을 해제할 수는 없고, 경개계약의 성립 후에 그 계약을 합의해제하여 구채권을 부활시키는 것은 당사자 사이에서도 불가능하다.","ox":"X","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":4,"lv":3,"i":"법무사2022_28-04-5","t":"부적법한 변제공탁으로 변제의 효력이 발생하지 않았다면 피공탁자는 이를 수락하여 공탁물 출급청구를 할 수도 없고, 공탁자에 대한 다른 채권에 기하여 공탁자의 공탁물 회수청구권에 대하여 압류 및 추심명령을 받아 그 집행으로 공탁물을 회수할 수도 없다.","ox":"X","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2022_28-07-1","t":"상계에 따른 양 채권의 차액 계산 또는 상계 충당은 상계적상의 시점을 기준으로 하므로, 그 시점 이전에 수동채권에 대하여 이자나 지연손해금이 발생한 경우 상계적상 시점까지 수동채권의 이자나 지연손해금을 계산한 다음 자동채권으로써 먼저 수동채권의 이자나 지연손해금을 소각하고 잔액을 가지고 원본을 소각하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2022_28-07-2","t":"채권압류명령을 받은 제3채무자가 압류채무자에 대한 반대채권을 가지고 있는 경우에 상계로써 압류채권자에게 대항하기 위하여는, 압류의 효력 발생 당시에 대립하는 양 채권이 상계적상에 있거나, 그 당시 반대채권(자동채권)의 변제기가 도래하지 아니한 경우에는 그것이 피압류채권(수동채권)의 변제기와 동시에 또는 그보다 먼저 도래하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2022_28-07-3","t":"채무자가 채권양도 통지를 받은 경우 채무자는 그때까지 양도인에 대하여 생긴 사유로써 양수인에게 대항할 수 있고, 당시 이미 상계할 수 있는 원인이 있었던 경우에는 아직 상계적상에 있지 않더라도 그 후에 상계적상에 이르면 채무자는 양수인에 대하여 상계로 대항할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2022_28-07-4","t":"채권자가 주채무자에 대하여 상계적상에 있는 자동채권을 상계하지 않았다고 하여 이를 이유로 보증채무자가 보증한 채무의 이행을 거부할 수 없으며 나아가 보증채무자의 책임이 면책되는 것도 아니다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"법무사 1차","qn":7,"lv":3,"i":"법무사2022_28-07-5","t":"소멸시효가 완성된 채권이 그 완성 전에 상계할 수 있었던 것이면 그 채권자는 상계할 수 있으나, 매도인이나 수급인의 담보책임을 기초로 한 매수인이나 도급인의 손해배상채권의 제척기간이 지난 경우에는 위 법리가 적용되지 않으므로 매수인이나 도급인은 위 손해배상채권을 자동채권으로 하여 상대방의 채권과 상계할 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2022_28-22-1","t":"지명채권의 양도통지를 한 후 그 양도계약이 해제된 경우에, 양도인이 그 해제를 이유로 다시 원래의 채무자에 대하여 양도채권으로 대항하려면 양도인이 채무자에게 위와 같은 해제사실을 통지하여야 한다.","ox":"X","m":"①","c":"A","tp":"채권양도"},{"y":2022,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2022_28-22-2","t":"채권양도에 관한 채무자의 승낙이라 함은 채무자가 채권양도 사실에 관한 인식을 표명하는 것으로서 이른바 관념의 통지에 해당하고, 대리인에 의하여도 위와 같은 승낙을 할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2022_28-22-3","t":"채권가압류의 처분금지의 효력은 본안소송에서 가압류채권자가 승소하여 집행권원을 얻는 등으로 피보전권리의 존재가 확정되는 것을 조건으로 하여 발생하는 것이므로 채권가압류결정의 채권자가 본안소송에서 승소하는 등으로 집행권원을 취득하는 경우에는 가압류에 의하여 권리가 제한된 상태의 채권을 양수받는 양수인에 대한 채권양도는 무효가 된다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2022_28-22-4","t":"집합채권의 양도가 양도금지특약에 위반해서 무효인 경우 채무자는 일부 개별 채권을 특정하여 추인하는 것이 가능하고, 이 경우 다른 약정이 없는 한 소급효가 인정되지 않고 양도의 효과는 추인시부터 발생한다고 할 것이다.","ox":"O","m":"④","c":"A","tp":"채권양도"},{"y":2022,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2022_28-22-5","t":"소송행위를 하게 하는 것을 주된 목적으로 채권양도가 이루어진 경우 그 채권양도가 신탁법상의 신탁에 해당하지 않는다고 하여도 신탁법 제6조가 유추적용되므로 이는 무효이다.","ox":"O","m":"⑤","c":"A"},{"y":2022,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2022_28-30-1","t":"공동불법행위자 중 1인에 대하여 구상의무를 부담하는 다른 공동불법행위자가 수인인 경우, 구상권자인 공동불법행위자측에 과실이 있든 없든 그에 대한 수인의 구상의무 사이의 관계를 부진정연대관계로 봄이 상당하다.","ox":"X","m":"①","c":"A","tp":"다수당사자의 채권관계"},{"y":2022,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2022_28-30-2","t":"채권자의 신청에 의한 경매개시결정에 따라 연대채무자 1인의 소유 부동산이 압류된 경우, 이로써 위 채무자에 대한 채권의 소멸시효는 중단되지만, 압류에 의한 시효중단의 효력은 다른 연대채무자에게 미치지 않는다.","ox":"O","m":"②","c":"A","tp":"다수당사자의 채권관계"},{"y":2022,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2022_28-30-3","t":"금융기관이 회사 임직원의 대규모 분식회계로 인하여 회사의 재무구조를 잘못 파악하고 회사에 대출을 해 준 경우, 회사의 금융기관에 대한 대출금채무와 회사 임직원의 분식회계 행위로 인한 금융기관에 대한 손해배상채무는 부진정연대의 관계에 있다.","ox":"O","m":"③","c":"A","tp":"다수당사자의 채권관계"},{"y":2022,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2022_28-30-4","t":"부진정연대채무의 관계에 있는 채무자들을 공동피고로 하여 이행의 소가 제기된 경우 공동피고에 대한 각 청구는 법률상 양립할 수 없는 것이 아니므로 그 소송은 민사소송법 제70조 제1항에 규정한 본래 의미의 예비적·선택적 공동소송이라고 할 수 없다.","ox":"O","m":"④","c":"A","tp":"다수당사자의 채권관계"},{"y":2022,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2022_28-30-5","t":"4인의 매도인이 4인의 매수인에게 임야를 매도하기로 하는 계약을 체결한 후 매매계약의 무효를 원인으로 부당이득으로서 계약금의 반환을 구하는 경우, 특별한 사정이 없으면 매도인 중의 1인이 매수인 중의 1인에게 위 계약금 전액을 반환할 의무가 있다고 할 수 없다.","ox":"O","m":"⑤","c":"A","tp":"다수당사자의 채권관계"},{"y":2023,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2023_29-01-1","t":"경개계약은 신채권을 성립시키고 구채권을 소멸시키는 처분행위로서 신채권이 성립되면 그 효과는 완결되고 경개계약 자체의 이행의 문제는 발생할 여지가 없으므로 경개에 의하여 성립된 신채무의 불이행을 이유로 경개계약을 해제할 수는 없다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2023_29-01-2","t":"기존의 채권이 제3자에게 이전된 경우 이를 채권의 양도로 볼 것인가 또는 경개로 볼 것인가는 일차적으로 당사자의 의사에 의하여 결정되고, 만약 당사자의 의사가 명백하지 아니할 때에는 일반적으로 채권의 양도로 볼 것이다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2023_29-01-3","t":"기존채무와 관련하여 새로운 약정을 체결한 경우에 그러한 약정이 경개에 해당하는 것인지 아니면 단순히 기존채무의 변제기나 변제방법 등을 변경한 것인지는 당사자의 의사에 의하여 결정되고, 만약 당사자의 의사가 명백하지 아니할 때에는 의사해석의 문제로 귀착되는 것으로서, 이러한 당사자의 의사를 해석함에 있어서는 새로운 약정이 이루어지게 된 동기 및 경위, 당사자가 그 약정에 의하여 달성하려고 하는 목적과 진정한 의사 등을 종합적으로 고찰하여 사회정의와 형평의 이념에 맞도록 논리와 경험의 법칙, 그리고 사회일반의 상식과 거래의 통념에 따라 합리적으로 해석하여야 한다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2023_29-01-4","t":"채무자가 부담한 구채무의 일부가 이자제한법 위반으로 무효라고 하더라도 경개계약을 체결한 경우 그 부분에 관하여 효력이 발생하지 않는다고 할 수 없다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":1,"lv":3,"i":"법무사2023_29-01-5","t":"현실적인 자금의 수수 없이 형식적으로만 신규대출을 하여 기존채무를 변제하는 이른바 대환은 특별한 사정이 없는 한 형식적으로는 별도의 대출에 해당하나 실질적으로는 기존채무의 변제기의 연장에 불과하여 경개라고 할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2023_29-13-1","t":"민법 제666조에서 정한 수급인의 저당권설정청구권은 공사대금채권을 담보하기 위하여 인정되는 채권적 청구권으로서 공사대금채권에 부수하여 인정되는 권리이므로, 당사자 사이에 공사대금채권만을 양도하고 저당권설정청구권은 이와 함께 양도하지 않기로 약정하였다는 등의 특별한 사정이 없는 한, 공사대금채권이 양도되는 경우 저당권설정청구권도 이에 수반하여 함께 이전된다고 봄이 타당하다.","ox":"O","m":"①","c":"A","tp":"채권양도"},{"y":2023,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2023_29-13-2","t":"채무자가 양도되는 채권의 성립이나 소멸에 영향을 미치는 사정에 관하여 양수인에게 알려야 할 신의칙상 주의의무가 있다고 볼 만한 특별한 사정이 없는 한, 채무자가 그러한 사정을 알리지 아니하였다고 하여 불법행위가 성립한다고 볼 수 없다.","ox":"O","m":"②","c":"A","tp":"채권양도"},{"y":2023,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2023_29-13-3","t":"제3채무자가 질권설정 사실을 승낙한 후 질권설정계약이 합의해지된 경우에, 만일 질권자가 제3채무자에게 질권설정계약의 해지 사실을 통지하였다면, 설사 아직 해지가 되지 아니하였다고 하더라도 선의인 제3채무자는 질권설정자에게 대항할 수 있는 사유로 질권자에게 대항할 수 있다고 봄이 타당하다.","ox":"O","m":"③","c":"A","tp":"채권양도"},{"y":2023,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2023_29-13-4","t":"채무자의 채권양도인에 대한 자동채권이 발생하는 기초가 되는 원인이 양도 전에 이미 성립하여 존재하고 그 자동채권이 수동채권인 양도채권과 동시이행의 관계에 있다 하더라도, 양도통지가 채무자에게 도달하여 채권양도의 대항요건이 갖추어진 후에 자동채권이 발생하였다면, 채무자는 동시이행의 항변권을 주장할 수 없고, 따라서 그 채권에 의한 상계로 양수인에게 대항할 수도 없다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":13,"lv":3,"i":"법무사2023_29-13-5","t":"양도금지특약부 채권에 대한 전부명령이 유효한 이상, 그 전부채권자로부터 다시 그 채권을 양수한 자가 그 특약의 존재를 알았거나 중대한 과실로 알지 못하였다 하더라도 채무자는 위 특약을 근거로 삼아 채권양도의 무효를 주장할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2023_29-22-1","t":"변제공탁의 목적인 채무는 현존하는 확정채무여야 하지만, 그 의미는 장래의 채무나 불확정채무는 원칙적으로 변제공탁의 목적이 되지 못한다는 것일 뿐, 채무자에 대한 각 채권자의 채권이 동일한 채권이어야 한다는 의미는 아니다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2023_29-22-2","t":"변제공탁이 적법한 경우에는 채권자가 공탁물 출급청구를 하였는지 여부와는 관계없이 공탁을 한 때에 변제의 효력이 발생하나, 피공탁자를 포함한 제3자가 공탁자에 대하여 가지는 별도 채권의 집행권원으로써 공탁자의 공탁물 회수청구권에 대하여 압류 및 추심명령을 받아 그 집행으로 공탁물을 회수한 경우 채권소멸의 효력은 소급하여 없어진다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2023_29-22-3","t":"채권자에게 반대급부 기타 조건의 이행의무가 없음에도 불구하고 채무자가 그와 같은 조건으로 변제공탁을 한 때에는 채권자가 이를 수락하였다고 하더라도 그 변제공탁은 무효이다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2023_29-22-4","t":"채권자의 태도로 보아 채무자가 설령 채무의 이행제공을 하였더라도 그 수령을 거절하였을 것이 명백한 경우에는 채무자는 이행의 제공을 하지 않고 바로 변제공탁할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":22,"lv":3,"i":"법무사2023_29-22-5","t":"채무자가 채무액의 일부만을 변제공탁하였으나 그 후 부족분을 추가로 공탁하였다면 그 때부터는 전 채무액에 대하여 유효한 공탁이 이루어진 것으로 볼 수 있고, 이 경우 채권자가 공탁물수령의 의사표시를 하기 전이라면 추가공탁을 하면서 제1차 공탁시에 지정된 공탁의 목적인 채무의 내용을 변경하는 것도 허용될 수 있다.","ox":"O","m":"⑤","c":"A"},{"y":2023,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2023_29-33-1","t":"채무담보 목적의 가등기가 경료되어 있는 부동산을 시효취득하여 소유권이전등기청구권을 취득한 자가 그 등기를 경료하지 못하던 중에 채권자가 청산절차를 거치지 아니하고 위 가등기에 기하여 본등기를 경료하였다면 그는 부동산 소유자에 대한 소유권이전등기청구권을 보전하기 위하여 위 소유자를 대위하여 그의 채권자에게 위 채무를 변제할 법률상의 권한이 있어 이해관계 있는 제3자에 해당한다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2023_29-33-2","t":"확정판결에 대한 청구이의 사유는 그 확정판결의 변론 종결 후에 생긴 것이어야 하므로, 확정판결의 변론 종결 전에 이루어진 일부이행을 채권자가 변론 종결 후 수령함으로써 변제의 효력이 발생한 경우 그 한도 내에서도 청구이의 사유가 될 수는 없다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2023_29-33-3","t":"효력규정인 강행법규에 위반되는 계약을 체결한 자가 그 약정의 효력이 부인된다는 사실을 알지 못한 탓에 그 약정에 따라 변제수령권을 갖는 것처럼 외관을 갖게 된 자에게 변제를 한 경우에는, 특별한 사정이 없는 한 과실에 기인한 변제이므로 채권의 준점유자에 대한 변제로서 유효하다고 볼 수 없다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2023_29-33-4","t":"채무자(乙)가 제3채무자(丙)에 대하여 가지고 있던 채권에 관하여 제3자(丁) 앞으로 대항력 있는 채권양도가 이루어진 후 乙이 丁의 승낙 없이 임의로 丙에게 채권양도철회의 통지를 한 상태에서 乙에 대한 채권자(甲)가 위 채권에 대하여 채권압류 및 전부명령을 받고 이어 甲이 제기한 전부금소송에서 丙이 패소판결을 받고 甲에게 그 금원을 지급한 경우, 법률전문가가 아닌 丙이 甲이 유효하게 채권을 전부받은 채권자인 것으로 오인한 데 대하여 과실이 있다고 볼 수 없으므로 丙의 甲에 대한 변제는 채권의 준점유자에 대한 변제로서 유효하다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"법무사 1차","qn":33,"lv":3,"i":"법무사2023_29-33-5","t":"채무자는 변제의 제공이 있는 때로부터 채무불이행의 책임을 면하지만, 금전채무의 경우 현실제공은 특별한 사정이 없는 한 채권자가 급부를 즉시 수령할 수 있는 상태에 있어야만 인정될 수 있다. 따라서 채무자가 채무내용에 좇은 급부를 제공하면서도 채권자가 그 급부를 즉시 수령하기 어려운 장애요인을 형성·유지한 경우에는 현실제공이 있다고 할 수 없다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2024_30-03-1","t":"상속채권자가 상속이 개시된 후 한정승인 이전에 피상속인에 대한 채권을 자동채권으로 하여 상속인에 대한 채무에 대하여 상계하였더라도, 그 이후 상속인이 한정승인을 하는 경우에는 민법 제1031조의 취지에 따라 상계가 소급하여 효력을 상실하고, 상계의 자동채권인 상속채권자의 피상속인에 대한 채권과 수동채권인 상속인에 대한 채무는 모두 부활한다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2024_30-03-2","t":"채권양도가 사해행위에 해당하는 경우 불법행위로 인한 손해배상채권의 채무자가 채권양도인에 대한 별도의 채권자 지위에서 채권양수인에게 채권자취소권을 행사하여 채권양도의 취소를 구함과 아울러 취소에 따른 원상회복 방법으로 직접 자신 앞으로 가액배상의 지급을 구하는 것 자체는 민법 제496조에 반하지 않으므로 허용된다.","ox":"O","m":"②","c":"A","tp":"상계"},{"y":2024,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2024_30-03-3","t":"수탁보증인이 주채무자에 대하여 가지는 민법 제442조의 사전구상권에는 민법 제443조의 담보제공청구권이 항변권으로 부착되어 있으므로 이를 자동채권으로 하는 상계는 원칙적으로 허용될 수 없다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2024_30-03-4","t":"대항요건을 갖춘 채권양수인이 양수채권을 자동채권으로 하여 그 채무자가 채권양수인에 대해 가지고 있던 기존 채권과 상계한 경우, 채권양도 전에 이미 양 채권의 변제기가 도래하였다면 상계의 효력은 변제기로 소급한다.","ox":"X","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":3,"lv":3,"i":"법무사2024_30-03-5","t":"민법 제492조 제1항에 따르면 쌍방이 서로 같은 종류를 목적으로 한 채무를 부담한 경우 쌍방 채무의 이행기가 도래한 때에는 각 채무자는 대등액에 관하여 상계할 수 있는데, 위 조항에서 정한 ‘채무의 이행기가 도래한 때’는 채권자가 채무자에게 이행의 청구를 할 수 있는 시기가 도래하였음을 의미하고 채무자가 이행지체에 빠지는 시기를 말하는 것이 아니다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2024_30-14-1","t":"양도인이 지명채권을 제1양수인에게 1차로 양도한 다음 제1양수인이 그에 따라 확정일자 있는 증서에 의한 대항요건을 적법하게 갖추었다면 이로써 채권이 제1양수인에게 이전하고 양도인은 채권에 대한 처분권한을 상실하므로, 그 후 양도인이 동일한 채권을 제2양수인에게 양도하였더라도 제2양수인은 채권을 취득할 수 없다. 다만, 제2차 양도계약 후 양도인과 제1양수인이 제1차 양도계약을 합의해지한 다음 제1양수인이 그 사실을 채무자에게 통지함으로써 채권이 다시 양도인에게 귀속하게 되었다면, 양도인이 처분권한 없이 한 제2차 양도계약이 채권양도로서 유효하게 될 수 있다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2024_30-14-2","t":"당사자의 의사표시에 의한 채권양도금지 특약은 제3자가 악의인 경우는 물론 제3자가 채권양도금지 특약을 알지 못한 데에 중대한 과실이 있는 경우에도 채권양도금지 특약으로써 대항할 수 있고, 제3자의 악의 내지 중과실은 채권양도금지 특약으로 양수인에게 대항하려는 자가 이를 주장·증명하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2024_30-14-3","t":"민법 제449조 제2항 단서는 채권양도금지 특약으로써 대항할 수 없는 자를 ‘선의의 제3자’라고만 규정하고 있어 채권자로부터 직접 양수한 자만을 가리키는 것으로 해석할 이유는 없으므로, 악의의 양수인으로부터 다시 선의로 양수한 전득자도 위 조항에서의 선의의 제3자에 해당한다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2024_30-14-4","t":"지명채권양도에 있어서 확정일자 있는 증서에 의한 통지나 승낙은 제3자에 대한 대항요건에 불과하고 채권양도의 유효요건은 아니며, 여기서 채무자 이외의 제3자라 함은 당해 채권에 관하여 양수인의 지위와 양립할 수 없는 법률상 지위를 취득한 자를 말하는 것이므로, 당해 채권을 양수한 양수인에게까지 확정일자 있는 증서에 의한 통지나 승낙이 대항요건으로 필요한 것은 아니라고 할 것이다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2024_30-14-5","t":"채권양도의 통지는 채무자에게 도달됨으로써 효력이 발생하는 것이고, 여기서 도달이라 함은 사회통념상 상대방이 통지의 내용을 알 수 있는 객관적 상태에 놓여졌다고 인정되는 상태를 가리킨다. 이와 같이 도달은 보다 탄력적인 개념으로서 송달장소나 수송달자 등의 면에서 민사소송법상의 송달에서와 같은 엄격함은 요구되지 아니하며, 이에 따라 송달장소 등에 관한 민사소송법의 규정을 유추적용할 것이 아니다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2024_30-30-1","t":"주채무에 대한 소멸시효가 완성되어 보증채무가 소멸된 상태에서 보증인이 보증채무를 이행하거나 승인하였다고 하더라도, 주채무자가 아닌 보증인의 행위에 의하여 주채무에 대한 소멸시효 이익의 포기 효과가 발생된다고 할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2024_30-30-2","t":"채권자와 주채무자 사이의 확정판결에 의하여 주채무가 확정되어 그 소멸시효기간이 10년으로 연장되었다면, 그 보증채무까지도 당연히 단기소멸시효의 적용이 배제되어 10년의 소멸시효기간이 적용된다고 보는 것이 보증채무의 성질에 부합한다.","ox":"X","m":"②","c":"A"},{"y":2024,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2024_30-30-3","t":"민법 제440조는 “주채무자에 대한 시효의 중단은 보증인에 대하여 그 효력이 있다.”라고 규정하고 있는바, 민법 제440조는 시효중단에 관한 민법 제169조의 예외 규정으로서 이는 채권자 보호 내지 채권담보의 확보를 위하여 주채무자에 대한 시효중단의 사유가 발생하였을 때는 그 보증인에 대한 별도의 중단조치가 이루어지지 아니하여도 동시에 시효중단의 효력이 생기도록 한 것이고, 그 시효중단사유가 압류, 가압류 및 가처분이라고 하더라도 이를 보증인에게 통지하여야 비로소 시효중단의 효력이 발생하는 것은 아니다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2024_30-30-4","t":"수탁보증인의 사전구상권과 사후구상권은 종국적 목적과 사회적 효용을 같이하는 공통성을 가지고 있으나, 그 발생원인을 달리하고 법적성질도 달리하는 별개의 독립된 권리이므로, 사후구상권이 발생한 이후에도 사전구상권은 소멸하지 아니하고 병존하며, 다만 목적달성으로 일방이 소멸하면 타방도 소멸하는 관계에 있을 뿐이다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"법무사 1차","qn":30,"lv":3,"i":"법무사2024_30-30-5","t":"어느 연대채무자나 어느 불가분채무자를 위하여 보증인이 된 자의 다른 연대채무자나 다른 불가분채무자에 대한 구상권에 관한 규정인 민법 제447조는 연대채무자 모두를 위하여 물상보증인이 된 자가 그 연대채무자의 1인에 대하여 구상권을 행사하는 경우에는 적용될 여지가 없다.","ox":"O","m":"⑤","c":"A"},{"y":2024,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2024_30-37-1","t":"공유물 무단 점유자에 대한 차임 상당 부당이득반환청구권은 특별한 사정이 없는 한 각 공유자에게 지분 비율만큼 귀속된다.","ox":"O","m":"①","c":"A","tp":"수인의 채권자 및 채무자"},{"y":2024,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2024_30-37-2","t":"민법 제428조의2 제1항 전문은 “보증은 그 의사가 보증인의 기명날인 또는 서명이 있는 서면으로 표시되어야 효력이 발생한다.”라고 규정하고 있는데, ‘보증인의 서명’은 원칙적으로 보증인이 직접 자신의 이름을 쓰는 것을 의미하므로 타인이 보증인의 이름을 대신 쓰는 것은 이에 해당하지 않지만, ‘보증인의 기명날인’은 타인이 이를 대행하는 방법으로 하여도 무방하다.","ox":"O","m":"②","c":"A","tp":"수인의 채권자 및 채무자"},{"y":2024,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2024_30-37-3","t":"부진정연대채무자 중 1인이 자신의 채권자에 대한 반대채권으로 상계를 한 경우, 채권자가 상계 내지 상계계약이 이루어질 당시 다른 부진정연대채무자의 존재를 알았던 경우에 한하여 그 상계로 인한 채무소멸의 효력이 소멸한 채무 전액에 관하여 다른 부진정연대채무자에 대하여도 미친다고 보아야 한다.","ox":"X","m":"③","c":"A","tp":"수인의 채권자 및 채무자"},{"y":2024,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2024_30-37-4","t":"여러 사람이 공동임대인으로서 임차인과 하나의 임대차계약을 체결한 경우에는 민법 제547조 제1항의 적용을 배제하는 특약이 있다는 등의 특별한 사정이 없는 한 공동임대인 전원의 해지의 의사표시에 따라 임대차계약 전부를 해지하여야 하고, 이러한 법리는 임대차계약의 체결 당시부터 공동임대인이었던 경우뿐만 아니라 임대차목적물 중 일부가 양도되어 그에 관한 임대인의 지위가 승계됨으로써 공동임대인으로 되는 경우에도 마찬가지로 적용된다.","ox":"O","m":"④","c":"A","tp":"수인의 채권자 및 채무자"},{"y":2024,"e":"법무사 1차","qn":37,"lv":3,"i":"법무사2024_30-37-5","t":"어느 연대채무자가 다른 연대채무자에게 통지하지 아니하고 변제 기타 자기의 출재로 공동면책이 된 경우에 다른 연대채무자가 채권자에게 대항할 수 있는 사유가 있었을 때에는 그 부담부분에 한하여 이 사유로 면책행위를 한 연대채무자에게 대항할 수 있고, 그 대항사유가 상계인 때에는 상계로 소멸할 채권은 그 연대채무자에게 이전된다.","ox":"O","m":"⑤","c":"A","tp":"수인의 채권자 및 채무자"},{"y":2025,"e":"법무사 1차","qn":5,"lv":3,"i":"법무사2025_31-05","t":"상계에 관한 다음 설명 중 가장 옳지 않은 것은?","c":"A","mc":{"s":"상계에 관한 다음 설명 중 가장 옳지 않은 것은?","d":"","o":["주채무자가 수탁보증인에 대해 사전에 민법 제443조의 담보제공청구권 등의 항변권을 포기한 경우, 그 수탁보증인은 주채무자에 대하여 가지는 민법 제442조의 사전구상권을 자동채권으로 하여 주채무자가 수탁보증인에 대하여 가지는 채권과 상계할 수 있다.","근로자가 일정 기간 동안의 미지급 법정수당을 청구하는 경우에 사용자가 같은 기간 동안 법정수당의 초과 지급 부분이 있음을 이유로 상계나 그 충당을 주장하는 것은 허용된다.","임대인인 甲이 임차인인 乙을 상대로 임대차계약 종료 후에도 임대목적물인 건물 부분을 불법점유하고 있다며 건물 부분의 인도와 함께 임대차계약에서 정한 손해배상 예정액의 지급을 구하자, 乙이 준비서면의 송달로 부속물매수청구권을 행사한다는 의사표시를 하고, 甲도 준비서면의 송달로 乙의 불법점유로 인한 甲의 손해배상채권을 자동채권으로 하여 乙의 부속물 매매대금 채권과 대등액에서 상계한다는 의사표시를 한 사안에서, 甲의 상계 의사표시로 그 의사표시 이전까지 존재하였던 甲의 부속물 매매대금 지급의무와 乙의 건물 부분 인도의무 사이의 동시이행관계는 상계적상이 있었던 시기로 소급하여 소멸하고 이로 인해 乙의 점유는 소급하여 불법점유가 된다.","유치권이 인정되는 아파트를 경매로 매수한 자가 아파트 일부를 점유․사용하고 있는 유치권자에 대한 임료 상당의 부당이득금 반환채권을 자동채권으로 하고 유치권자가 종전 소유자에 대하여 가지는 유익비상환채권을 수동채권으로 하여 상계할 수는 없다.","제3채무자의 압류채무자에 대한 자동채권이 수동채권인 피압류채권과 동시이행의 관계에 있는 경우에는, 압류명령이 제3채무자에게 송달되어 압류의 효력이 생긴 후에 자동채권이 발생하였다고 하더라도, 제3채무자는 그 채권에 의한 상계로 압류채권자에게 대항할 수 있다."],"a":3}},{"y":2025,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2025_31-06-1","t":"채권의 일부에 대하여 대위변제가 있는 때에는 대위자는 그 변제한 가액에 비례하여 채권자와 함께 그 권리를 행사한다.","ox":"O","m":"①","c":"A","tp":"변제자대위"},{"y":2025,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2025_31-06-2","t":"변제할 정당한 이익이 있는 사람이 채무자를 위하여 채권의 일부를 대위변제할 경우에 대위변제자는 변제한 가액의 범위 내에서 종래 채권자가 가지고 있던 채권 및 담보에 관한 권리를 취득하므로, 채권자가 부동산에 대하여 저당권을 가지고 있는 경우에는 채권자는 대위변제자에게 일부 대위변제에 따른 저당권 일부 이전의 부기등기를 할 의무를 진다.","ox":"O","m":"②","c":"A","tp":"변제자대위"},{"y":2025,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2025_31-06-3","t":"변제로 채권자를 대위하는 경우에 채권 및 그 담보에 관한 권리가 변제자에게 이전될 뿐 계약당사자의 지위가 이전되는 것은 아니다.","ox":"O","m":"③","c":"A","tp":"변제자대위"},{"y":2025,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2025_31-06-4","t":"대위변제자와 채무자 사이에 구상금에 관한 지연손해금 약정이 있으면 이 약정은 변제자대위권을 행사하는 경우에도 적용된다.","ox":"X","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":6,"lv":3,"i":"법무사2025_31-06-5","t":"채무자를 위하여 변제한 자는 변제와 동시에 채권자의 승낙을 얻어 채권자를 대위할 수 있는바(민법 제480조 제1항), 여기에서 채권자의 승낙은 반드시 명시적일 필요가 없고, 변제의 동기 내지 이유와 그 과정, 변제받음에 있어 채권자가 보인 태도, 변제 후의 사정 등 여러 사정을 두루 참작하여 그 승낙이 있은 것으로 추단될 수 있으면 된다.","ox":"O","m":"⑤","c":"A","tp":"변제자대위"},{"y":2025,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2025_31-08-1","t":"채권의 양수인이 채권양도의 대항요건을 갖추지 못하여 채무자에게 대항하지 못하는 상태에서 채무자를 상대로 재판상의 청구를 하였다면 이는 소멸시효 중단사유인 재판상의 청구에 해당한다고 볼 수 없다.","ox":"X","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2025_31-08-2","t":"주채무자에 대한 채권이 이전되면 당사자 사이에 별도의 특약이 없는 한 보증인에 대한 채권도 함께 이전하지만, 채권양도의 대항요건은 주채무자와 별도로 보증인에 대하여도 구비하여야 보증인에게 대항할 수 있게 된다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2025_31-08-3","t":"매매로 인한 소유권이전등기청구권 같은 지명채권의 양도는 양도인이 채무자에게 통지하거나 채무자가 승낙하지 아니하면 채무자 기타 제3자에게 대항하지 못한다.","ox":"X","m":"③","c":"A","tp":"채권양도"},{"y":2025,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2025_31-08-4","t":"양도금지의 특약이 붙은 채권이 양도된 경우에 양수인의 악의 또는 중과실에 관한 증명책임은 채무자가 부담하므로 채무자는 특별한 사정이 없는 한 민법 제487조 후단의 채권자 불확지를 원인으로 하여 변제공탁을 할 수 없다.","ox":"X","m":"④","c":"A","tp":"채권양도"},{"y":2025,"e":"법무사 1차","qn":8,"lv":3,"i":"법무사2025_31-08-5","t":"계약인수는 개별 채권·채무의 이전을 목적으로 하는 것이 아니라 다수의 채권·채무를 포함한 계약당사자로서의 지위의 포괄적 이전을 목적으로 하는 것으로서, 채무자 보호를 위해 개별 채권양도에서 요구되는 대항요건은 계약인수에서는 별도로 요구되지 않는다.","ox":"O","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2025_31-09-1","t":"부진정연대채무자 중 1인이 자신의 채권자에 대한 반대채권으로 상계를 한 경우 그 상계로 인한 채무소멸의 효력은 소멸한 채무 전액에 관하여 다른 부진정연대채무자에 대하여도 미친다.","ox":"O","m":"①","c":"A","tp":"채권의 소멸"},{"y":2025,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2025_31-09-2","t":"법정변제충당과 관련하여 특별한 사정이 없는 한 변제자가 타인의 채무에 대한 연대보증인으로서 부담하는 채무는 변제자 자신의 채무에 비하여 변제 이익이 적다.","ox":"O","m":"②","c":"A","tp":"채권의 소멸"},{"y":2025,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2025_31-09-3","t":"검사 작성의 피의자신문조서는 검사가 피의자를 신문하여 그 진술을 기재한 조서로서 당해 신문과정에서 다른 피의자나 참고인과 대질이 이루어진 경우라고 할지라도 피의자 진술은 어디까지나 검사를 상대로 이루어지는 것이므로 그 진술기재 가운데 채무면제의 의사가 표시되어 있다고 하더라도 그 부분이 곧바로 채무면제의 처분문서에 해당한다고 보기 어렵다.","ox":"O","m":"③","c":"A","tp":"채권의 소멸"},{"y":2025,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2025_31-09-4","t":"변제할 정당한 이익이 있는 자가 채무자를 위하여 채권의 일부를 대위변제할 경우에 대위변제자는 변제한 가액의 범위내에서 종래 채권자가 가지고 있던 채권 및 담보에 관한 권리를 취득하게 되고 따라서 채권자가 부동산에 대하여 저당권을 가지고 있는 경우에는 채권자는 대위변제자에게 일부 대위변제에 따른 저당권의 일부이전의 부기등기를 경료해 주어야 할 의무가 있으므로 일부 대위변제자는 채권자에 대하여 우선변제권을 가지게 된다.","ox":"X","m":"④","c":"A","tp":"채권의 소멸"},{"y":2025,"e":"법무사 1차","qn":9,"lv":3,"i":"법무사2025_31-09-5","t":"변제공탁이 유효하려면 채무 전부에 대한 변제의 제공 및 채무 전액에 대한 공탁이 있어야 하고, 채무 전액이 아닌 일부에 대한 공탁은 일부의 제공이 유효한 제공이라고 볼 수 있거나 변제자의 공탁금액이 채무의 총액에 비하여 아주 근소하게 부족하여 해당 변제공탁을 신의칙상 유효한 것이라고 볼 수 있는 등의 특별한 사정이 있는 경우를 제외하고는 채권자가 이를 수락하지 않는 한 그 공탁 부분에 관하여서도 채무소멸의 효과가 발생하지 않는다.","ox":"O","m":"⑤","c":"A","tp":"채권의 소멸"},{"y":2025,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2025_31-18-1","t":"담보권 실행을 위한 경매에서 배당된 배당금이 담보권자가 가지는 수개의 피담보채권 전부를 소멸시키기에 부족한 경우에는 민법 제477조의 규정에 의한 법정변제충당의 방법에 따라 충당하여야 하나, 채권자와 채무자 사이에 변제충당에 관한 합의가 있었다면 그 합의에 따른 변제충당은 허용된다.","ox":"X","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2025_31-18-2","t":"변제자가 주채무자인 경우 보증인이 있는 채무와 보증인이 없는 채무 사이에 전자가 후자에 비하여 변제이익이 더 많고, 물상보증인이 제공한 물적 담보가 있는 채무와 그러한 담보가 없는 채무 사이에는 전자가 후자에 비하여 변제이익이 더 많다.","ox":"X","m":"②","c":"A","tp":"변제충당"},{"y":2025,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2025_31-18-3","t":"변제자와 변제수령자는 변제로 소멸한 채무에 관한 보증인 등 이해관계 있는 제3자의 이익을 해하지 않는 이상 이미 급부를 마친 뒤에도 기존의 충당방법을 배제하고 제공된 급부를 어느 채무에 어떤 방법으로 다시 충당할 것인가를 약정할 수 있다.","ox":"O","m":"③","c":"A","tp":"변제충당"},{"y":2025,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2025_31-18-4","t":"가집행선고로 인한 강제집행을 면하기 위하여 채무자가 채권자에게 금원을 지급하였으나 그 가지급금의 액수가 채무자가 채권자에게 지급하여야 할 정당한 금원(최종적으로 확정된 금원)인 원본 및 지연손해금 합계액에 미치지 못하였다면, 그 가지급금으로는 특별한 사정이 없는 한, 민법 소정의 변제충당의 법리에 따라 채무자가 채권자에게 지급하여야 할 정당한 금원에 관하여 지연손해금, 원본의 순서로 변제에 충당되어야 하나, 이러한 법리는 가집행의 근거가 된 판결의 소송물이 복수의 금전청구가 객관적으로 병합된 경우에는 적용되지 아니한다.","ox":"X","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":18,"lv":3,"i":"법무사2025_31-18-5","t":"비용, 이자, 원본에 대한 변제충당에 있어서는 민법 제479조에 그 충당 순서가 법정되어 있고 지정 변제충당에 관한 민법 제476조는 준용되지 않으므로 원칙적으로 비용, 이자, 원본의 순서로 충당하여야 하고, 채무자는 물론 채권자라 할지라도 위 법정 순서와 다르게 일방적으로 충당의 순서를 지정할 수는 없으며, 당사자 간 합의로도 법정충당의 순서와 달리 충당의 순서를 정할 수 없다.","ox":"X","m":"⑤","c":"A"},{"y":2025,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2025_31-39-1","t":"상계의 의사표시에 의하여 각 채무는 상계할 수 있는 때에 대등액에 관하여 소멸한 것으로 보게 되지만, 이러한 상계의 소급효는 양 채권 및 이에 관한 이자나 지연손해금 등을 정산하는 기준시기를 소급하는 것일 뿐이고 특별한 사정이 없는 한 상계의 의사표시 전에 이미 발생한 사실을 복멸시키지는 아니한다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2025_31-39-2","t":"어느 연대채무자가 채권자에 대하여 채권이 있는 경우에 그 채무자가 상계한 때에는 채권은 모든 연대채무자의 이익을 위하여 소멸한다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2025_31-39-3","t":"상계는 상대방에 대한 의사표시로 한다. 이 의사표시에는 조건 또는 기한을 붙이지 못한다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2025_31-39-4","t":"부당이득반환채권은 이행기의 정함이 없는 채권으로서 그 이행 청구일에 상계적상에서 의미하는 이행기가 도래한 것으로 볼 수 있다.","ox":"X","m":"④","c":"A"},{"y":2025,"e":"법무사 1차","qn":39,"lv":3,"i":"법무사2025_31-39-5","t":"채권양수인이 양수채권을 자동채권으로 하여 그 채무자가 채권양수인에 대해 가지고 있던 기존 채권과 상계한 경우, 채권양수인은 채권양도의 대항요건이 갖추어진 때 비로소 자동채권을 행사할 수 있으므로 채권양도 전에 이미 양 채권의 변제기가 도래하였다고 하더라도 상계의 효력은 변제기로 소급하는 것이 아니라 채권양도의 대항요건이 갖추어진 시점으로 소급한다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2026_32-14-1","t":"채무자와 인수인의 합의에 의한 중첩적 채무인수의 경우 채권자의 수익의 의사표시는 채무인수계약의 성립요건이자 효력발생요건이다.","ox":"X","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2026_32-14-2","t":"제3자는 채권자와의 계약으로 채무를 인수하여 채무자의 채무를 면하게 할 수 있지만, 채무의 성질이 인수를 허용하지 아니하는 때에는 그러하지 아니하고, 이해관계 없는 제3자는 채무자의 의사에 반하여 채무를 인수하지 못한다.","ox":"O","m":"②","c":"A","tp":"채무인수"},{"y":2026,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2026_32-14-3","t":"중첩적 채무인수에서 인수인이 채무자의 부탁 없이 채권자와의 계약으로 채무를 인수하는 것은 매우 드문 일이므로 채무자와 인수인은 원칙적으로 주관적 공동관계가 있는 연대채무관계에 있고, 인수인이 채무자의 부탁을 받지 아니하여 주관적 공동관계가 없는 경우에는 부진정연대채무관계에 있는 것으로 보아야 한다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2026_32-14-4","t":"부동산의 매수인이 매매목적물에 관한 근저당권의 피담보채무를 인수하고 그 채무액을 매매대금에서 공제하기로 약정한 경우, 특별한 사정이 없는 한 매도인을 면책시키는 채무인수가 아니라 이행인수로 보아야 한다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":14,"lv":3,"i":"법무사2026_32-14-5","t":"채무인수에 있어서 면책적 인수인지, 중첩적 인수인지가 분명하지 아니한 때에는 이를 중첩적으로 인수한 것으로 볼 것이다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2026_32-27-1","t":"민법 제428조의2 제1항 전문은 “보증은 그 의사가 보증인의 기명날인 또는 서명이 있는 서면으로 표시되어야 효력이 발생한다.”라고 규정하고 있는데, 여기서 ‘보증인의 기명날인’은 타인이 이를 대행하는 방법으로 할 수 없다.","ox":"X","m":"①","c":"A","tp":"보증채무"},{"y":2026,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2026_32-27-2","t":"불확정한 다수의 채무에 대하여 보증하는 경우 보증채무의 최고액이 서면으로 특정되어 보증계약이 유효하다고 하기 위해서는, 보증인의 보증의사가 표시된 서면에 보증채무의 최고액이 명시적으로 기재되어 있어야 하고, 보증채무의 최고액이 명시적으로 기재되어 있지 않더라도 그 서면 자체로 보아 보증채무의 최고액이 얼마인지를 객관적으로 알 수 있는 등 보증채무의 최고액이 명시적으로 기재되어 있는 경우와 동일시할 수 있을 정도의 구체적인 기재가 필요하다고 봄이 타당하다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2026_32-27-3","t":"보증채무에 대한 소멸시효가 중단되는 등의 사유로 완성되지 아니하였다고 하더라도 주채무에 대한 소멸시효가 완성된 경우에는 시효완성의 사실로 주채무가 소멸되므로 보증채무의 부종성에 따라 보증채무 역시 당연히 소멸되는 것이 원칙이다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2026_32-27-4","t":"근보증의 대상인 주채무는 근보증계약을 체결할 당시에 이미 발생되어 있거나 구체적으로 내용이 특정되어 있을 필요는 없고, 장래의 채무, 조건부 채무는 물론 장래 증감⋅변동이 예정된 불특정의 채무라도 이를 특정할 수 있는 기준이 정해져 있으면 된다.","ox":"O","m":"④","c":"A","tp":"보증채무"},{"y":2026,"e":"법무사 1차","qn":27,"lv":3,"i":"법무사2026_32-27-5","t":"연대보증채무에 대한 소멸시효가 중단되었다고 하더라도 이로써 주채무에 대한 소멸시효가 중단되는 것은 아니고, 주채무가 소멸시효 완성으로 소멸된 경우에는 연대보증채무도 그 채무 자체의 시효중단에 불구하고 부종성에 따라 당연히 소멸한다.","ox":"O","m":"⑤","c":"A"},{"y":2026,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2026_32-32-1","t":"변제자가 주채무자인 경우 보증인이 있는 채무와 보증인이 없는 채무 사이에 변제이익에 있어 차이가 없다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2026_32-32-2","t":"채무자를 위하여 채무를 변제한 자는 채무자에 대한 구상권을 취득할 수 있고, 구상권의 발생 경위와 취지 등에 비추어 특별한 사정이 없는 한 구상권은 변제자가 민법 제480조 제1항에 따라 가지는 변제자대위권과 원본, 변제기, 이자, 지연손해금 유무 등에서 그 내용이 다른 별개의 권리라고 볼 수 없다.","ox":"X","m":"②","c":"A"},{"y":2026,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2026_32-32-3","t":"변제자(채무자)와 변제수령자(채권자)는 변제로 소멸한 채무에 관한 보증인 등 이해관계 있는 제3자의 이익을 해하지 않는 이상 이미 급부를 마친 뒤에도 기존의 충당방법을 배제하고 제공된 급부를 어느 채무에 어떤 방법으로 다시 충당할 것인가를 약정할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2026_32-32-4","t":"민법 제469조 제2항은 이해관계 없는 제3자는 채무자의 의사에 반하여 변제하지 못한다고 규정하고, 민법 제481조는 변제할 정당한 이익이 있는 자는 변제로 당연히 채권자를 대위한다고 규정하고 있는바, 위 조항에서 말하는 ‘이해관계’ 내지 ‘변제할 정당한 이익’이 있는 자는 변제를 하지 않으면 채권자로부터 집행을 받게 되거나 또는 채무자에 대한 자기의 권리를 잃게 되는 지위에 있기 때문에 변제함으로써 당연히 대위의 보호를 받아야 할 법률상 이익을 가지는 자를 말하고, 단지 사실상의 이해관계를 가진 자는 제외된다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"법무사 1차","qn":32,"lv":3,"i":"법무사2026_32-32-5","t":"가집행이 붙은 제1심판결 선고 이후 채무자가 제1심판결에 기한 강제집행을 피하기 위해 돈을 지급한 경우 그에 따라 확정적으로 변제의 효과가 발생하는 것이 아니므로 채무자가 항소심에서 위와 같이 돈을 지급한 사실을 주장하더라도 항소심법원은 그러한 사유를 참작하지 않고 청구의 당부를 판단해야 한다.","ox":"O","m":"⑤","c":"A"}]};
window.PAIRS=[{"n":14,"s":0.766,"o":{"i":"법무사2024_30-41-1","t":"혼인은 가족관계의 등록 등에 관한 법률에 정한 바에 의하여 신고함으로써 그 효력이 생기며, 그 신고는 당사자 쌍방과 성년자인 증인 2인의 연서한 서면으로 하여야 한다.","y":2024,"e":"법무사 1차"},"x":{"i":"법무사2024_30-41-3","t":"입양은 가족관계의 등록 등에 관한 법률에서 정한 바에 따라 신고함으로써 그 효력이 생기며, 그 신고는 당사자 쌍방과 성년자인 증인 2인의 연서한 서면으로 하여야 한다.","y":2024,"e":"법무사 1차"}},{"n":14,"s":0.423,"o":{"i":"법무사2019_25-41-4","t":"시ㆍ읍ㆍ면의 장이 신고서류 등을 수리한 때에는 그 신고사건에 무효사유가 없으면, 즉시 가족관계등록부에 기록을 하여야 한다.","y":2019,"e":"법무사 1차"},"x":{"i":"법무사2024_30-49-4","t":"시·읍·면의 장이 출생신고서류를 수리한 때에는 그 신고사건에 무효사유가 있더라도 즉시 등록부에 기록을 하여야 한다.","y":2024,"e":"법무사 1차"}},{"n":14,"s":0.421,"o":{"i":"법무사2016_22-41-4","t":"중혼은 취소원인이나 그 취소의 효력은 이전으로 소급하지 아니하므로, 중혼으로 취소할 수 있는 혼인당사자 사이에서의 출생한 자녀는 혼인 중의 자로 출생신고를 하여야 한다.","y":2016,"e":"법무사 1차"},"x":{"i":"법무사2022_28-47-4","t":"중혼으로 취소할 수 있는 혼인당사자 사이에서의 출생한 자녀는 혼인 외의 자로 출생신고해야 한다.","y":2022,"e":"법무사 1차"}},{"n":14,"s":0.421,"o":{"i":"법무사2025_31-44-3","t":"양육비부담조서의 집행문은 그 양육비부담조서가 작성된 협의이혼의사확인사건의 확인서에 따라 이혼신고를 하였음을 소명한 때에만 내어준다.","y":2025,"e":"법무사 1차"},"x":{"i":"법무사2020_26-42-2","t":"양육비부담조서는 협의이혼신고일부터 미성년인 자녀가 각 성년에 이르는 날까지의 기간에 해당하는 양육비에 한하여 작성하므로, 양육비부담조서의 집행문은 그 양육비부담조서가 작성된 협의이혼의사확인 사건의 확인서에 따라 이혼신고를 하였음이 소명된 경우 내어준다.","y":2020,"e":"법무사 1차"}},{"n":13,"s":0.459,"o":{"i":"법무사2019_25-49-5","t":"동일한 사건에 수개의 신고가 수리된 경우에는 먼저 수리된 신고에 따라 가족관계등록부에 기록하여야 한다.","y":2019,"e":"법무사 1차"},"x":{"i":"법무사2022_28-43-4","t":"시(구)·읍·면을 달리하여 동일한 사건에 수개의 신고가 수리된 경우에, 뒤에 수리된 신고에 따라 가족관계등록부에 기록한 때에는 먼저 수리한 시(구)·읍·면의 장이 먼저 수리된 신고에 맞추어 가족관계등록부의 기록을 정정하여야 한다.","y":2022,"e":"법무사 1차"}},{"n":13,"s":0.453,"o":{"i":"법무사2024_30-42-1","t":"인터넷에 의한 등록사항별 증명서의 발급은 본인 또는 배우자, 부모, 자녀가 신청할 수 있다. 다만, 친양자입양관계증명서의 발급은 친양자가 성년이 되어 신청하는 경우에 한한다.","y":2024,"e":"법무사 1차"},"x":{"i":"법무사2024_30-42-4","t":"무인증명서발급기에 의한 등록사항별 증명서의 발급은 본인 또는 배우자, 부모, 자녀가 신청할 수 있다.","y":2024,"e":"법무사 1차"}},{"n":13,"s":0.419,"o":{"i":"법무사2026_32-41-1","t":"인터넷에 의한 등록사항별 증명서의 발급은 법원행정처 전산정보중앙관리소 전산운영책임관 명의로 한다.","y":2026,"e":"법무사 1차"},"x":{"i":"법무사2026_32-41-5","t":"법원행정처와 외교부의 시스템 연계 방식을 이용한 재외공관에서 교부하는 등록사항별 증명서는 법원행정처 전산정보중앙관리소 전산운영책임관 명의로 한다.","y":2026,"e":"법무사 1차"}},{"n":13,"s":0.403,"o":{"i":"법무사2019_25-48-4","t":"대법원장은 재외국민에 관한 등록사무를 가족관계등록관으로 하여금 처리하게 할 수 있다.","y":2019,"e":"법무사 1차"},"x":{"i":"법무사2026_32-47-4","t":"대법원장은 외국에 거주하거나 체류하는 대한민국 국민에 관한 등록사무를 가족관계등록관에게 위임하여 처리하게 할 수 있다.","y":2026,"e":"법무사 1차"}},{"n":15,"s":0.495,"o":{"i":"법무사2017_23-41-1","t":"등록부의 기록이 법률상 무효인 것이거나 그 기록에 착오 또는 누락이 있음을 안 때에는 시ㆍ읍ㆍ면의 장은 지체 없이 신고인 또는 신고사건의 본인에게 그 사실을 통지하여야 한다. 다만, 그 착오 또는 누락이 시ㆍ읍ㆍ면의 장의 잘못으로 인한 것인 때에는 그러하지 아니하다.","y":2017,"e":"법무사 1차"},"x":{"i":"법무사2020_26-45-1","t":"등록부의 기록에 착오 또는 누락이 시(구)·읍·면의 장의 잘못으로 인한 것인 때에는 지체없이 신고인 또는 신고사건의 본인에게 그 사실을 통지하여야 한다.","y":2020,"e":"법무사 1차"}},{"n":15,"s":0.4,"o":{"i":"법무사2022_28-49-5","t":"가족관계등록부에 기록된 외국인인 가족이 외국에서 사망한 경우 이해관계인은 해당 가족관계등록부의 등록기준지와 무관하게 전국 시(구)·읍·면의 장에게 사망사실을 증명하는 서면을 제출하여 직권기록을 신청할 수 있고, 시(구)·읍·면의 장은 간이직권절차에 의하여 기록한다.","y":2022,"e":"법무사 1차"},"x":{"i":"법무사2022_28-49-4","t":"가족관계등록부에 기록된 외국인인 가족에 관한 기록사항 중 출생연월일, 외국인등록번호, 국적 또는 성별이 기록되지 않은 경우 이해관계인은 해당 가족관계등록부의 등록기준지의 시(구)·읍·면의 장에게 직권기록을 신청하여야 하고, 등록기준지의 시(구)·읍·면의 장은 간이직권절차에 의하여 기록한다.","y":2022,"e":"법무사 1차"}},{"n":11,"s":0.438,"o":{"i":"법무사2024_30-22-3","t":"협의이혼을 예정하고 미리 재산분할 협의를 한 경우 협의이혼에 따른 재산분할에 있어 분할의 대상이 되는 재산과 액수는 협의이혼이 성립한 날(이혼신고일)을 기준으로 정하여야 한다. 따라서 재산분할 협의를 한 후 협의이혼 성립일까지의 기간 동안 재산분할 대상인 채무의 일부가 변제된 경우 그 변제된 금액은 원칙적으로 채무액에서 공제되어야 한다.","y":2024,"e":"법무사 1차"},"x":{"i":"법무사2025_31-24-3","t":"협의이혼에 따른 재산분할에서 분할의 대상이 되는 재산과 액수는 협의이혼이 성립한 날(이혼신고일)을 기준으로 정하여야 하지만, 협의이혼을 예정하고 미리 재산분할 협의를 한 경우에는 해당 재산분할 협의 시점을 기준으로 정하여야 한다.","y":2025,"e":"법무사 1차"}},{"n":11,"s":0.358,"o":{"i":"법무사2026_32-23-1","t":"이혼위자료청구권은 원칙적으로 일신전속적 권리로서 양도나 상속 등 승계가 되지 아니하나 이는 행사상 일신전속권이고 귀속상 일신전속권은 아니라 할 것인바, 그 청구권자가 위자료의 지급을 구하는 소송을 제기함으로써 청구권을 행사할 의사가 외부적·객관적으로 명백하게 된 이상 양도나 상속 등 승계가 가능하다.","y":2026,"e":"법무사 1차"},"x":{"i":"법무사2020_26-05-1","t":"이혼에 따른 위자료청구권은 일신전속적 권리이므로 청구권자가 위자료의 지급을 구하는 소송을 제기함으로써 청구권을 행사할 의사가 외부적·객관적으로 명백하게 되었다고 하더라도 타인에게 양도하거나 상속 할 수 없다.","y":2020,"e":"법무사 1차"}},{"n":11,"s":0.336,"o":{"i":"법무사2024_30-22-5","t":"이혼하지 않은 당사자가 장차 협의상 이혼할 것을 합의하는 과정에서 이를 전제로 재산분할청구권을 포기하는 서면을 작성한 경우, 부부 쌍방의 협력으로 형성된 공동재산 전부를 청산·분배하려는 의도로 재산분할의 대상이 되는 재산액, 이에 대한 쌍방의 기여도와 재산분할 방법 등에 관하여 협의한 결과 부부 일방이 재산분할청구권을 포기하기에 이르렀다는 등의 사정이 없는 한 성질상 허용되지 아니하는 ‘재산분할청구권의 사전포기’에 불과할 뿐이므로 쉽사리 ‘재산분할에 관한 협의’로서의 ‘포기약정’이라고 보아서는 아니 된다.","y":2024,"e":"법무사 1차"},"x":{"i":"법무사2025_31-24-1","t":"아직 이혼하지 않은 당사자가 장차 협의상 이혼할 것을 합의하는 과정에서 이를 전제로 재산분할청구권을 포기하는 서면을 작성한 경우, 특별한 사정이 없는 한 ‘재산분할에 관한 협의’로서의 ‘포기약정’에 해당한다.","y":2025,"e":"법무사 1차"}},{"n":1,"s":0.787,"o":{"i":"법무사2016_22-12-5","t":"매매계약의 체결과 이행에 관하여 포괄적으로 대리권을 수여받은 대리인은 특별한 다른 사정이 없는 한 상대방에 대하여 약정된 매매대금 지급기일을 연기하여 줄 권한도 가진다.","y":2016,"e":"법무사 1차"},"x":{"i":"법무사2023_29-16-1","t":"매매계약의 체결과 이행에 관하여 포괄적으로 대리권을 수여받은 대리인이라도 특별한 다른 사정이 없는 한 상대방에 대하여 약정된 매매대금지급기일을 연기하여 줄 권한은 없다.","y":2023,"e":"법무사 1차"}},{"n":1,"s":0.687,"o":{"i":"법무사2019_25-28-5","t":"주채무자의 차용금반환채무를 보증할 의사로 공정증서에 연대보증인으로 서명날인하였으나 그 공정증서가 주채무자의 기존의 구상금채무 등에 관한 준소비대차계약의 공정증서였다 하더라도, 연대보증인의 위와 같은 착오는 연대보증계약의 중요 부분의 착오가 아니다.","y":2019,"e":"법무사 1차"},"x":{"i":"법무사2023_29-31-4","t":"주채무자의 차용금반환채무를 보증할 의사로 공정증서에 연대보증인으로 서명·날인하였으나 그 공정증서가 주채무자의 기존의 구상금채무 등에 관한 준소비대차계약의 공정증서이었던 경우, 위와 같은 착오는 연대보증계약의 중요 부분의 착오에 해당한다.","y":2023,"e":"법무사 1차"}},{"n":1,"s":0.667,"o":{"i":"법무사2016_22-12-4","t":"대리권이 법률행위에 의하여 부여된 경우에는 대리인은 본인의 승낙이 있거나 부득이한 사유있는 때가 아니면 복대리인을 선임하지 못한다.","y":2016,"e":"법무사 1차"},"x":{"i":"법무사2021_27-32-3","t":"대리권이 법률행위에 의하여 부여된 경우에는 대리인은 본인의 승낙이 있거나 부득이한 사유있는 때가 아니어도 필요에 따라 복대리인을 선임할 수 있다.","y":2021,"e":"법무사 1차"}},{"n":1,"s":0.426,"o":{"i":"법무사2023_29-31-3","t":"상대방이 표의자의 착오를 알고 이를 이용한 경우에는 착오가 표의자의 중대한 과실로 인한 것이라고 하더라도 표의자는 의사표시를 취소할 수 있다.","y":2023,"e":"법무사 1차"},"x":{"i":"법무사2020_26-14-2","t":"민법 제109조 제1항 단서는 의사표시의 착오가 표의자의 중대한 과실로 인한 때에는 그 의사표시를 취소하지 못한다고 규정하고 있으므로 상대방이 표의자의 착오를 알고 이를 이용한 경우에도 착오가 표의자의 중대한 과실로 인한 것이라면 표의자는 의사표시를 취소할 수 없다.","y":2020,"e":"법무사 1차"}},{"n":9,"s":0.671,"o":{"i":"법무사2023_29-32-4","t":"채무자와 인수인의 계약으로 체결되는 병존적 채무인수는 채권자로 하여금 인수인에 대하여 새로운 권리를 취득하게 하는 것으로 제3자를 위한 계약에 해당한다.","y":2023,"e":"법무사 1차"},"x":{"i":"법무사2019_25-10-3","t":"채무자와 인수인의 계약으로 체결되는 병존적 채무인수는 채권자로 하여금 인수인에 대하여 새로운 권리를 취득하게 하는 것으로, 그 성격은 제3자를 위한 계약이 아니라 이행인수로 보아야 한다.","y":2019,"e":"법무사 1차"}},{"n":9,"s":0.664,"o":{"i":"법무사2016_22-25-3","t":"위임계약의 일방 당사자가 타방 당사자의 채무불이행을 이유로 위임계약을 해지한다는 의사표시를 하였으나 실제로는 채무불이행을 이유로 한 계약 해지의 요건을 갖추지 못한 경우라도, 특별한 사정이 없는 한 위 의사표시에는 임의해지로서의 효력이 인정된다.","y":2016,"e":"법무사 1차"},"x":{"i":"법무사2021_27-15-3","t":"위임계약의 일방 당사자가 타방 당사자의 채무불이행을 이유로 위임계약을 해지한다는 의사표시를 하였으나 실제로는 채무불이행을 이유로 한 계약 해지의 요건을 갖추지 못한 경우에는, 특별한 사정이 없는 한 위 의사표시에는 민법 제689조 제1항에 기한 임의해지로서의 효력도 인정되지 아니한다.","y":2021,"e":"법무사 1차"}},{"n":9,"s":0.629,"o":{"i":"법무사2025_31-17-5","t":"민법 제548조 제2항은 계약해제로 인한 원상회복의무의 이행으로서 반환하는 금전에는 그 받은 날로부터 이자를 가산하여야 한다고 하고 있는바, 위 이자의 반환은 원상회복의무의 범위에 속하는 것으로 일종의 부당이득반환의 성질을 가지는 것이지 반환의무의 이행지체로 인한 손해배상은 아니라고 할 것이다.","y":2025,"e":"법무사 1차"},"x":{"i":"법무사2017_23-20-1","t":"민법 제548조 제2항은 계약해제로 인한 원상회복의무의 이행으로서 반환하는 금전에는 그 받은 날로부터 이자를 가산하여야 한다고 규정하고 있는바, 위 이자의 반환은 반환의무의 이행지체로 인한 손해배상의 성질을 가지는 것이지, 일반적인 부당이득반환의 성질을 갖는 것이 아니다.","y":2017,"e":"법무사 1차"}},{"n":9,"s":0.609,"o":{"i":"법무사2024_30-27-4","t":"동시이행의 항변권은 상대방의 채무이행이 있기까지 자신의 채무이행을 거절할 수 있는 권리이므로, 매수인이 매도인을 상대로 매매목적 부동산 중 일부에 대해서만 소유권이전등기의무의 이행을 구하고 있는 경우에도 매도인은 특별한 사정이 없는 한 그 매매잔대금 전부에 대하여 동시이행의 항변권을 행사할 수 있다고 할 것이다.","y":2024,"e":"법무사 1차"},"x":{"i":"법무사2022_28-14-3","t":"매수인이 매도인을 상대로 매매목적 부동산 중 일부에 대해서만 소유권이전등기의무의 이행을 구하고 있는 경우에는, 매도인은 특별한 사정이 없는 한 그 매매잔대금 일부에 대하여 동시이행의 항변권을 행사할 수 있다.","y":2022,"e":"법무사 1차"}},{"n":6,"s":0.748,"o":{"i":"법무사2023_29-29-1","t":"근저당권자의 경매신청 등의 사유로 인하여 근저당권의 피담보채권이 확정되었을 경우, 확정 이후에 새로운 거래관계에서 발생한 원본채권은 그 근저당권에 의하여 담보되지 않지만, 확정 전에 발생한 원본채권에 관하여 확정 후에 발생하는 이자나 지연손해금 채권은 채권최고액의 범위 내에서 근저당권에 의하여 여전히 담보된다.","y":2023,"e":"법무사 1차"},"x":{"i":"법무사2017_23-12-4","t":"근저당권자의 경매신청 등의 사유로 인하여 근저당권의 피담보채권이 확정되었을 경우, 확정 이후에 새로운 거래관계에서 발생한 원본채권과 확정 전에 발생한 원본채권에 관하여 확정 후에 발생하는 이자나 지연손해금 채권은 그 근저당권에 의하여 담보되지 않는다.","y":2017,"e":"법무사 1차"}},{"n":6,"s":0.653,"o":{"i":"법무사2024_30-39-3","t":"근저당권설정등기상 근저당권자가 다른 사람과 함께 채무자로부터 유효하게 채권을 변제받을 수 있고 채무자도 그들 중 누구에게든 채무를 유효하게 변제할 수 있는 관계, 가령 채권자와 근저당권자가 불가분적 채권자의 관계에 있다고 볼 수 있는 경우에는 그러한 근저당권설정등기도 유효하다고 볼 것이다.","y":2024,"e":"법무사 1차"},"x":{"i":"법무사2025_31-32-5","t":"근저당권은 채권담보를 위한 것이므로 채권자와 근저당권자는 동일인이어야 한다. 따라서 근저당권설정등기상 근저당권자가 다른 사람과 함께 채무자로부터 유효하게 채권을 변제받을 수 있고 채무자도 그들 중 누구에게든 채무를 유효하게 변제할 수 있는 관계, 가령 채권자와 근저당권자가 불가분적 채권자의 관계에 있다고 볼 수 있는 경우라도 그러한 근저당권설정등기는 유효하다고 볼 수 없다.","y":2025,"e":"법무사 1차"}},{"n":6,"s":0.545,"o":{"i":"법무사2022_28-29-4","t":"민법 제347조는 채권을 질권의 목적으로 하는 경우에 채권증서가 있는 때에는 질권의 설정은 그 증서를 질권자에게 교부함으로써 효력이 생긴다고 규정하고 있는데, 임대차계약서와 같이 계약 당사자 쌍방의 권리의무관계의 내용을 정한 서면은 그 계약에 의한 권리의 존속을 표상하기 위한 것이라고 할 수는 없으므로 위 채권증서에 해당하지 않는다고 할 것이다.","y":2022,"e":"법무사 1차"},"x":{"i":"법무사2018_24-12-4","t":"민법 제347조는 채권을 질권의 목적으로 하는 경우에 채권증서가 있는 때에는 질권의 설정은 그 증서를 질권자에게 교부함으로써 효력이 생긴다고 규정하고 있다. 임대차계약서와 같이 계약 당사자 쌍방의 권리의무관계의 내용을 기재한 서면은 여기에서 말하는 ‘채권증서’에 해당한다.","y":2018,"e":"법무사 1차"}},{"n":6,"s":0.512,"o":{"i":"법무사2026_32-37-1","t":"가등기담보 등에 관한 법률(이하 ‘가등기담보법’이라고 한다)은 재산권 이전의 예약에 의한 가등기담보에 있어서 재산의 예약 당시의 가액이 차용액 및 이에 붙인 이자의 합산액을 초과하는 경우에 적용되는바, 재산권 이전의 예약 당시 재산에 대하여 선순위 근저당권이 설정되어 있는 경우에는 재산의 가액에서 피담보채무액을 공제한 나머지 가액이 차용액 및 이에 붙인 이자의 합산액을 초과하는 경우에만 적용된다.","y":2026,"e":"법무사 1차"},"x":{"i":"법무사2016_22-33-4","t":"가등기담보법은 재산권 이전의 예약에 의한 가등기담보에 있어서 그 재산의 예약 당시의 가액이 차용액 및 이에 붙인 이자의 합산액을 초과하는 경우에 그 적용이 있는 것이므로, 재산권 이전의 예약 당시 그 재산에 대하여 선순위 근저당권이 설정되어 있다고 해서 그 재산의 가액에서 그 피담보채무액을 공제한 나머지 가액이 차용액 및 이에 붙인 이자의 합산액을 초과하는 경우에만 그 적용이 있다고 볼 것은 아니다.","y":2016,"e":"법무사 1차"}},{"n":2,"s":0.781,"o":{"i":"법무사2017_23-06-2","t":"하나의 금전채권의 원금 중 일부가 변제된 후 나머지 원금에 대하여 소멸시효가 완성된 경우, 소멸시효 완성의 효력은 소멸시효가 완성된 원금 부분으로부터 그 완성 전에 발생한 이자 또는 지연손해금에는 미치나 변제로 소멸한 원금 부분으로부터 그 변제 전에 발생한 이자 또는 지연손해금에는 미치지 않는다.","y":2017,"e":"법무사 1차"},"x":{"i":"법무사2016_22-15-2","t":"하나의 금전채권의 원금 중 일부가 변제된 후 나머지 원금에 대하여 소멸시효가 완성된 경우, 소멸시효 완성의 효력은 소멸시효가 완성된 원금 부분으로부터 그 완성 전에 발생한 이자 또는 지연손해금 뿐만 아니라 변제로 소멸한 원금 부분으로부터 그 변제 전에 발생한 이자 또는 지연손해금에도 미친다.","y":2016,"e":"법무사 1차"}},{"n":2,"s":0.747,"o":{"i":"법무사2023_29-30-4","t":"조건부 법률행위에 있어 조건의 내용 자체가 불법적인 것이어서 무효일 경우 또는 조건을 붙이는 것이 허용되지 아니하는 법률행위에 조건을 붙인 경우 그 조건만을 분리하여 무효로 할 수는 없고 그 법률행위 전부가 무효로 된다고 보아야 한다.","y":2023,"e":"법무사 1차"},"x":{"i":"법무사2020_26-33-5","t":"조건부 법률행위에 있어 조건의 내용 자체가 불법적인 것이어서 무효일 경우 또는 조건을 붙이는 것이 허용되지 아니하는 법률행위에 조건을 붙인 경우 그 조건만을 분리하여 무효로 할 수 있다.","y":2020,"e":"법무사 1차"}},{"n":12,"s":0.696,"o":{"i":"법무사2020_26-02-1","t":"기여분은 상속이 개시된 때의 피상속인의 재산가액에서 유증의 가액을 공제한 액을 넘지 못한다.","y":2020,"e":"법무사 1차"},"x":{"i":"법무사2026_32-03-5","t":"기여분은 상속이 개시된 때의 피상속인의 재산가액에서 유증의 가액을 공제한 액을 초과할 수도 있다.","y":2026,"e":"법무사 1차"}},{"n":12,"s":0.69,"o":{"i":"법무사2020_26-02-2","t":"유류분반환의 범위는 상속개시 당시 피상속인의 순재산과 문제된 증여재산을 합한 재산을 평가하여 그 재산액에 유류분청구권자의 유류분비율을 곱하여 얻은 유류분액을 기준으로 산정하는데, 증여받은 재산의 시가는 상속개시 당시를 기준으로 하여 산정하여야 한다.","y":2020,"e":"법무사 1차"},"x":{"i":"법무사2022_28-15-1","t":"유류분반환의 범위는 상속개시 당시 피상속인의 순재산과 문제된 증여재산을 합한 재산을 평가하여 그 재산액에 유류분청구권자의 유류분비율을 곱하여 얻은 유류분액을 기준으로 산정하는데, 그 유류분액을 산정함에 있어 반환의무자가 증여받은 재산의 시가는 상속개시 당시가 아닌 유류분반환청구권 행사 당시를 기준으로 산정한다.","y":2022,"e":"법무사 1차"}},{"n":12,"s":0.546,"o":{"i":"법무사2022_28-15-5","t":"유류분반환청구권의 행사는 재판상 또는 재판 외에서 상대방에 대한 의사표시의 방법으로 할 수 있고, 이 경우 그 의사표시는 침해를 받은 유증 또는 증여행위를 지정하여 이에 대한 반환청구의 의사를 표시하면 그것으로 족하며, 그 반환목적물을 구체적으로 특정하여야 하는 것은 아니다.","y":2022,"e":"법무사 1차"},"x":{"i":"법무사2019_25-06-4","t":"유류분반환청구권의 행사는 재판상 또는 재판 외에서 상대방에 대한 의사표시의 방법으로 할 수 있고, 그 의사표시는 침해를 받은 유증 또는 증여행위를 지정하여 이에 대한 반환청구의 의사를 표시하면 족하나, 민법 제1117조에서 정한 유류분반환청구권의 소멸시효의 진행을 중단시키기 위해서는 그 목적물을 구체적으로 특정하여야 한다.","y":2019,"e":"법무사 1차"}},{"n":12,"s":0.511,"o":{"i":"법무사2020_26-35-2","t":"진정상속인이 참칭상속인으로부터 상속재산을 양수한 제3자를 상대로 상속재산인 부동산에 관한 등기의 말소 등을 청구하는 경우에도 상속회복청구권의 단기의 제척기간이 적용된다.","y":2020,"e":"법무사 1차"},"x":{"i":"법무사2024_30-16-3","t":"진정상속인이 참칭상속인으로부터 상속재산을 양수한 제3자를 상대로 등기말소청구를 하는 경우에는 상속회복청구권의 단기의 제척기간이 적용되지 않는다.","y":2024,"e":"법무사 1차"}},{"n":3,"s":0.682,"o":{"i":"법무사2020_26-19-2","t":"점유자가 유익비를 지출할 당시 계약관계 등 적법한 점유의 권원을 가진 경우에 그 지출비용의 상환에 관하여는 그 계약관계를 규율하는 법조항이나 법리 등이 적용되는 것이어서 점유자는 그 계약관계 등의 상대방에 대하여 해당 법조항이나 법리에 따른 비용상환청구권을 행사할 수 있을 뿐 계약관계 등의 상대방이 아닌 점유회복 당시의 소유자에 대하여 민법 제203조 제2항에 따른 지출비용의 상환을 구할 수는 없다.","y":2020,"e":"법무사 1차"},"x":{"i":"법무사2017_23-10-2","t":"점유자가 유익비를 지출할 당시 계약관계 등 적법한 점유의 권원을 가진 경우 점유자는 그 계약관계 등의 상대방에 대하여 계약관계를 규율하는 법조항이나 법리에 따른 비용상환청구권을 행사하는 외에도 계약관계 등의 상대방이 아닌 점유회복 당시의 소유자에 대하여 민법 제203조 제2항에 따른 지출비용의 상환을 구할 수 있다.","y":2017,"e":"법무사 1차"}},{"n":3,"s":0.523,"o":{"i":"법무사2019_25-17-2","t":"전(前) 등기명의인이 미성년자이고 당해 부동산을 친권자에게 증여하는 행위가 이해상반행위라 하더라도 일단 친권자에게 이전등기가 경료된 이상, 특별한 사정이 없는 한 그 이전등기에 관하여 필요한 절차를 적법하게 거친 것으로 추정된다.","y":2019,"e":"법무사 1차"},"x":{"i":"법무사2020_26-28-5","t":"전 등기명의인이 미성년자이고 당해 부동산을 친권자에게 증여하는 행위가 이해상반행위라면 친권자에게 마쳐진 소유권이전등기에 관하여 필요한 절차를 적법하게 거친 것으로 추정되지 않는다.","y":2020,"e":"법무사 1차"}},{"n":10,"s":0.764,"o":{"i":"법무사2020_26-24-2","t":"사무관리가 성립하기 위하여는 우선 그 사무가 타인의 사무이고 타인을 위하여 사무를 처리하는 의사, 즉 관리의 사실상의 이익을 타인에게 귀속시키려는 의사가 있어야 하며, 나아가 그 사무의 처리가 본인에게 불리하거나 본인의 의사에 반한다는 것이 명백하지 아니할 것을 요한다. 여기에서 타인을 위하여 사무를 처리하는 의사는 관리자 자신의 이익을 위한 의사와 병존할 수 있고, 반드시 외부적으로 표시될 필요가 없으며, 사무를 관리할 당시에 확정되어 있을 필요가 없다.","y":2020,"e":"법무사 1차"},"x":{"i":"법무사2024_30-34-3","t":"사무관리가 성립하기 위하여는 우선 그 사무가 타인의 사무이고 타인을 위하여 사무를 처리하는 의사, 즉 관리의 사실상의 이익을 타인에게 귀속시키려는 의사가 있어야 하며, 나아가 그 사무의 처리가 본인에게 불리하거나 본인의 의사에 반한다는 것이 명백하지 아니할 것을 요한다. 여기에서 ‘타인을 위하여 사무를 처리하는 의사’는 관리자 자신의 이익을 위한 의사와 병존할 수 있으나, 외부적으로 표시되어야 하며 사무를 관리할 당시에 확정되어 있어야 한다.","y":2024,"e":"법무사 1차"}},{"n":10,"s":0.414,"o":{"i":"법무사2025_31-07-1","t":"계약의 일방당사자가 상대방의 지시 등으로 상대방과 또 다른 계약관계를 맺고 있는 제3자에게 직접 급부한 경우(이른바 삼각관계에서의 급부가 이루어진 경우), 계약의 일방당사자는 제3자를 상대로 법률상 원인 없이 급부를 수령하였다는 이유로 부당이득반환청구를 할 수 없다.","y":2025,"e":"법무사 1차"},"x":{"i":"법무사2025_31-07-2","t":"이른바 삼각관계에서의 급부가 이루어진 경우, 제3자가 급부를 수령함에 있어 계약의 일방당사자가 상대방에 대하여 급부를 한 원인관계인 법률관계에 무효 등의 흠이 있었다는 사실을 알고 있었다면 계약의 일방당사자는 제3자를 상대로 법률상 원인 없이 급부를 수령하였다는 이유로 부당이득반환청구를 할 수 있다.","y":2025,"e":"법무사 1차"}},{"n":10,"s":0.383,"o":{"i":"법무사2021_27-38-2","t":"토지의 매수인이 아직 소유권이전등기를 마치지 않았더라도 매매계약의 이행으로 토지를 인도받은 때에는 매매계약의 효력으로서 이를 점유·사용할 권리가 있으므로, 매도인이 매수인에 대하여 그 점유·사용을 법률상 원인이 없는 이익이라고 하여 부당이득반환청구를 할 수는 없다.","y":2021,"e":"법무사 1차"},"x":{"i":"법무사2022_28-34-4","t":"토지의 매수인이 매매계약의 이행으로 그 토지를 인도받았으나 아직 소유권이전등기를 경료받지 아니하였다면 그 매수인으로부터 위 토지를 다시 매수한 자에 대하여 매도인은 그 점유·사용을 법률상 원인이 없는 이익이라고 하여 부당이득반환청구를 할 수 있다.","y":2022,"e":"법무사 1차"}},{"n":5,"s":0.791,"o":{"i":"법무사2016_22-34-4","t":"토지와 지상 건물이 함께 양도되었다가 채권자취소권의 행사에 따라 그중 건물에 관하여만 양도가 취소되고 수익자와 전득자 명의의 소유권이전등기가 말소되었다고 하더라도, 이는 관습상 법정지상권의 성립요건인 ‘동일인의 소유에 속하고 있던 토지와 지상 건물이 매매 등으로 인하여 소유자가 다르게 된 경우’에 해당한다고 할 수 없다.","y":2016,"e":"법무사 1차"},"x":{"i":"법무사2025_31-13-3","t":"동일인의 소유에 속하고 있던 토지와 지상 건물이 함께 양도되었다가 채권자취소권의 행사에 따라 그중 건물에 관하여만 양도가 취소되고 수익자와 전득자 명의의 소유권이전등기가 말소된 경우, 관습법상 법정지상권의 성립요건인 ‘동일인의 소유에 속하고 있던 토지와 지상 건물이 매매 등으로 인하여 소유자가 다르게 된 경우’에 해당한다.","y":2025,"e":"법무사 1차"}},{"n":5,"s":0.665,"o":{"i":"법무사2021_27-27-2","t":"동일한 소유자에 속하는 대지와 그 지상건물이 매매에 의하여 각기 소유자가 달라지게 된 경우에는 특히 건물을 철거한다는 조건이 없는 한 건물소유자는 대지 위에 건물을 위한 관습상의 법정지상권을 취득하는 것이고, 한편 건물 소유를 위하여 법정지상권을 취득한 자로부터 경매에 의하여 건물의 소유권을 이전받은 경락인은 경락 후 건물을 철거한다는 등의 매각조건하에서 경매되는 경우 등 특별한 사정이 없는 한 건물의 경락취득과 함께 위 지상권도 당연히 취득한다. 이러한 법리는 압류, 가압류나 체납처분압류 등 처분제한의 등기가 된 건물에 관하여 그에 저촉되는 소유권이전등기를 마친 사람이 건물의 소유자로서 관습상의 법정지상권을 취득한 후 경매 또는 공매절차에서 건물이 매각되는 경우에도 마찬가지로 적용된다.","y":2021,"e":"법무사 1차"},"x":{"i":"법무사2016_22-34-5","t":"건물 소유를 위하여 법정지상권을 취득한 자로부터 경매에 의하여 그 건물의 소유권을 이전받은 경락인은 경락 후 건물을 철거한다는 등의 매각조건하에서 경매되는 경우 등 특별한 사정이 없는 한 건물의 경락취득과 함께 위 지상권도 당연히 취득하는데, 다만 이러한 법리는 압류, 가압류나 체납처분압류 등 처분제한의 등기가 된 건물에 관하여 그에 저촉되는 소유권이전등기를 마친 사람이 건물의 소유자로서 관습상의 법정지상권을 취득한 후 경매 또는 공매절차에서 건물이 매각되는 경우에는 적용되지 않는다.","y":2016,"e":"법무사 1차"}},{"n":5,"s":0.38,"o":{"i":"법무사2021_27-27-5","t":"동일인의 소유에 속하는 토지 및 그 지상 건물에 관하여 공동저당권이 설정된 후 그 지상 건물이 철거되고 새로 건물이 신축된 경우에는 그 신축건물의 소유자가 토지의 소유자와 동일하고 토지의 저당권자에게 신축건물에 관하여 토지의 저당권과 동일한 순위의 공동저당권을 설정해 주는 등 특별한 사정이 없는 한 저당물의 경매로 인하여 토지와 그 신축건물이 다른 소유자에 속하게 되더라도 그 신축건물을 위한 법정지상권은 성립하지 않는다.","y":2021,"e":"법무사 1차"},"x":{"i":"법무사2020_26-30-2","t":"동일인의 소유에 속하는 토지와 그 지상건물에 관하여 공동저당이 설정된 후 그 지상건물이 철거되고 새로 건물이 신축된 경우 특별한 사정이 없는 한 그 신축건물을 위한 법정지상권이 성립한다.","y":2020,"e":"법무사 1차"}},{"n":5,"s":0.343,"o":{"i":"법무사2025_31-23-4","t":"건물의 일부에 대하여 전세권이 설정되어 있는 경우 그 전세권자는 민법 제303조 제1항, 제318조의 규정에 의하여 그 건물 전부에 대하여 후순위 권리자 기타 채권자보다 전세금의 우선변제를 받을 권리가 있고, 전세권설정자가 전세금의 반환을 지체한 때에는 전세권의 목적물의 경매를 청구할 수 있다 할 것이나, 전세권의 목적물이 아닌 나머지 건물부분에 대하여는 우선변제권은 별론으로 하고 경매신청권은 없다.","y":2025,"e":"법무사 1차"},"x":{"i":"법무사2020_26-17-4","t":"전세권이 부동산의 일부에 설정된 경우 전세권자는 건물 전부에 대하여 후순위권리자 기타 채권자보다 전세금의 우선변제를 받을 권리가 있으므로, 전세목적물이 아닌 나머지 건물부분에 대하여 경매를 청구할 수 있다.","y":2020,"e":"법무사 1차"}},{"n":4,"s":0.814,"o":{"i":"법무사2020_26-01-1","t":"공유물분할청구의 소는 형성의 소로서 법원은 공유물분할을 청구하는 원고가 구하는 방법에 구애받지 않고 재량에 따라 합리적 방법으로 분할을 명할 수 있으나, 분할청구자들이 그들 사이의 공유관계의 유지를 원하고 있지 아니한데도 분할청구자들과 상대방 사이의 공유관계만 해소한 채 분할청구자들을 여전히 공유로 남기는 방식으로 현물분할을 하는 것은 허용될 수 없다.","y":2020,"e":"법무사 1차"},"x":{"i":"법무사2016_22-18-5","t":"공유물분할청구의 소는 형성의 소로서 법원은 공유물분할을 청구하는 원고가 구하는 방법에 구애받지 않고 재량에 따라 합리적 방법으로 분할을 명할 수 있으므로, 분할청구자들이 그들 사이의 공유관계의 유지를 원하고 있지 아니한 경우에도 분할청구자들과 상대방 사이의 공유관계만 해소한 채 분할청구자들을 여전히 공유로 남기는 방식으로 현물분할을 하는 것도 허용될 수 있다.","y":2016,"e":"법무사 1차"}},{"n":4,"s":0.706,"o":{"i":"법무사2017_23-13-5","t":"타인의 동산에 가공한 때에는 그 물건의 소유권은 원재료의 소유자에게 속한다. 그러나 가공으로 인한 가액의 증가가 원재료의 가액보다 현저히 다액인 때에는 가공자의 소유로 한다.","y":2017,"e":"법무사 1차"},"x":{"i":"법무사2018_24-34-3","t":"타인의 동산에 가공한 때에는 그 물건의 소유권은 원재료의 소유자에게 속한다. 그러나 가공으로 인한 가액의 증가가 원재료의 가액보다 현저히 다액인 때에는 원재료 소유자와 가공자가 그 가액 비율로 공유한다.","y":2018,"e":"법무사 1차"}},{"n":4,"s":0.688,"o":{"i":"법무사2024_30-31-3","t":"양도담보권설정자가 양도담보부동산을 20년간 소유의 의사로 평온, 공연하게 점유하였다고 하더라도, 점유취득시효를 원인으로 하여 담보 목적으로 경료된 소유권이전등기의 말소를 구할 수 없다.","y":2024,"e":"법무사 1차"},"x":{"i":"법무사2016_22-19-2","t":"양도담보권설정자가 양도담보부동산을 20년간 소유의 의사로 평온, 공연하게 점유한 경우, 양도담보권자를 상대로 점유취득시효를 원인으로 하여 담보 목적으로 경료된 소유권이전등기의 말소를 구할 수 있다.","y":2016,"e":"법무사 1차"}},{"n":4,"s":0.672,"o":{"i":"법무사2016_22-29-1","t":"부동산의 점유권원의 성질이 분명하지 않을 때에는 민법 제197조 제1항에 의하여 점유자는 소유의 의사로 선의, 평온 및 공연하게 점유한 것으로 추정되는 것이며, 이러한 추정은 지적공부 등의 관리주체인 국가나 지방자치단체가 점유하는 경우에도 마찬가지로 적용된다.","y":2016,"e":"법무사 1차"},"x":{"i":"법무사2025_31-25-4","t":"부동산 점유권원의 성질이 분명하지 않을 때에는 민법 제197조 제1항에 따라 점유자는 소유의 의사로 선의, 평온 및 공연하게 점유한 것으로 추정되는데, 이러한 추정은 지적공부 등의 관리주체인 국가나 지방자치단체가 점유하는 경우에는 적용되지 아니한다.","y":2025,"e":"법무사 1차"}},{"n":7,"s":0.823,"o":{"i":"법무사2016_22-20-3","t":"가등기에 기하여 본등기가 경료된 경우 가등기의 원인인 법률행위와 본등기의 원인인 법률행위가 명백히 다른 것이 아닌 한 사해행위 요건의 구비 여부는 가등기의 원인된 법률행위 당시를 기준으로 하여 판단하여야 한다.","y":2016,"e":"법무사 1차"},"x":{"i":"법무사2017_23-29-5","t":"가등기에 기하여 본등기가 경료된 경우 가등기의 원인인 법률행위와 본등기의 원인인 법률행위가 명백히 다른 것이 아닌 한 사해행위 요건의 구비 여부는 본등기가 마쳐진 당시를 기준으로 하여 판단하여야 한다.","y":2017,"e":"법무사 1차"}},{"n":7,"s":0.597,"o":{"i":"법무사2017_23-29-4","t":"부동산을 양도받아 소유권이전등기청구권을 가지고 있는 자가 양도인이 제3자에게 이를 이중으로 양도하여 소유권이전등기를 경료하여 줌으로써 취득하는 부동산 가액 상당의 손해배상채권은 이중양도행위에 대한 사해행위취소권을 행사할 수 있는 피보전권리에 해당하지 않는다.","y":2017,"e":"법무사 1차"},"x":{"i":"법무사2020_26-11-2","t":"부동산을 매수하여 소유권이전등기청구권을 가지고 있는 자가 매도인이 제3자에게 이를 이중으로 양도하여 소유권이전등기를 경료하여 줌으로써 취득하게 되는 부동산 가액 상당의 손해배상채권은 금전채권이므로 이중양도행위에 대하여 사해행위취소권을 행사할 수 있는 피보전채권에 해당한다.","y":2020,"e":"법무사 1차"}},{"n":7,"s":0.58,"o":{"i":"법무사2016_22-38-3","t":"채권자대위권은 채무자가 제3채무자에 대한 권리를 행사하지 아니하는 경우에 한하여 채권자가 자기의 채권을 보전하기 위하여 행사할 수 있는 것이어서, 채권자가 대위권을 행사할 당시에 이미 채무자가 그 권리를 재판상 행사하였을 때에는 채권자는 채무자를 대위하여 채무자의 권리를 행사할 수 없다.","y":2016,"e":"법무사 1차"},"x":{"i":"법무사2024_30-40-2","t":"채권자대위권은 채무자가 제3채무자에 대한 권리를 행사하지 아니하는 경우에 한하여 채권자가 자기의 채권을 보전하기 위하여 행사할 수 있는 것이기는 하나, 채권자가 대위권을 행사할 당시 이미 채무자가 그 권리를 재판상 행사하였으나 이후 불성실한 소송수행 등으로 패소의 확정판결을 받은 경우라면, 채권자는 채무자를 대위하여 채무자의 권리를 행사할 당사자적격이 있다.","y":2024,"e":"법무사 1차"}},{"n":7,"s":0.442,"o":{"i":"법무사2020_26-11-5","t":"채무자가 채권자와 신용카드가입계약을 체결하고 신용카드를 발급받았으나 유일한 재산인 아파트를 매도한 이후에 비로소 신용카드를 사용하기 시작하여 카드대금을 연체하게 되었다면 그 신용카드대금채권은 사해행위의 피보전채권이 될 수 없다.","y":2020,"e":"법무사 1차"},"x":{"i":"법무사2016_22-20-4","t":"채무자가 채권자와 신용카드가입계약을 체결하고 신용카드를 발급받았으나 자신의 유일한 부동산을 매도한 후에 비로소 신용카드를 사용하기 시작하여 신용카드대금을 연체하게 된 경우, 그 신용카드대금채권은 사해행위 이후에 발생한 채권이지만, 위 신용카드가입계약을 ‘채권성립의 기초가 되는 법률관계’로 볼 수 있는 이상 사해행위의 피보전채권이 될 수 있다.","y":2016,"e":"법무사 1차"}},{"n":8,"s":0.854,"o":{"i":"법무사2017_23-34-2","t":"채무자는 물론 채권자라고 할지라도 비용, 이자, 원본의 순서와 다르게 일방적으로 충당의 순서를 지정할 수는 없으나, 당사자의 일방적인 지정에 대하여 상대방이 지체 없이 이의를 제기하지 아니함으로써 묵시적 합의가 되었다고 보여지는 경우 위 법정충당의 순서와는 달리 충당의 순서를 인정할 수 있다.","y":2017,"e":"법무사 1차"},"x":{"i":"법무사2016_22-28-2","t":"채무자는 물론 채권자라고 할지라도 비용, 이자, 원본의 순서와 다르게 일방적으로 충당의 순서를 지정할 수는 없으므로, 당사자의 일방적인 지정에 대하여 상대방이 지체 없이 이의를 제기하지 아니함으로써 묵시적 합의가 되었다고 보여지는 경우라도 위 법정충당의 순서와는 달리 충당의 순서를 인정할 수는 없다.","y":2016,"e":"법무사 1차"}},{"n":8,"s":0.792,"o":{"i":"법무사2016_22-24-1","t":"채무자의 채권양도인에 대한 자동채권이 발생하는 기초가 되는 원인이 양도 전에 이미 성립하여 존재하고 그 자동채권이 수동채권인 양도채권과 동시이행의 관계에 있는 경우에는, 양도통지가 채무자에게 도달하여 채권양도의 대항요건이 갖추어진 후에 자동채권이 발생하였다고 하더라도 채무자는 동시이행의 항변권을 주장할 수 있고, 따라서 그 채권에 의한 상계로 양수인에게 대항할 수 있다.","y":2016,"e":"법무사 1차"},"x":{"i":"법무사2023_29-13-4","t":"채무자의 채권양도인에 대한 자동채권이 발생하는 기초가 되는 원인이 양도 전에 이미 성립하여 존재하고 그 자동채권이 수동채권인 양도채권과 동시이행의 관계에 있다 하더라도, 양도통지가 채무자에게 도달하여 채권양도의 대항요건이 갖추어진 후에 자동채권이 발생하였다면, 채무자는 동시이행의 항변권을 주장할 수 없고, 따라서 그 채권에 의한 상계로 양수인에게 대항할 수도 없다.","y":2023,"e":"법무사 1차"}},{"n":8,"s":0.73,"o":{"i":"법무사2019_25-21-3","t":"변제자가 주채무자인 경우 보증인이 있는 채무와 보증인이 없는 채무 사이에 전자가 후자에 비하여 변제이익이 더 많다고 볼 근거는 전혀 없으므로 양자는 변제이익의 점에서 차이가 없다고 보아야 한다. 마찬가지로 변제자가 채무자인 경우 물상보증인이 제공한 물적 담보가 있는 채무와 그러한 담보가 없는 채무 사이에도 변제이익의 점에서 차이가 없다.","y":2019,"e":"법무사 1차"},"x":{"i":"법무사2017_23-34-1","t":"변제자가 주채무자인 경우, 보증인이 있는 채무와 보증인이 없는 채무 사이에 전자가 후자에 비하여 변제이익이 더 많다고 볼 근거는 전혀 없으므로 양자는 변제이익의 점에서 차이가 없다고 보아야 하나, 물상보증인이 제공한 물적 담보가 있는 채무와 그러한 담보가 없는 채무 사이에는 변제이익의 점에서 차이가 있다.","y":2017,"e":"법무사 1차"}},{"n":8,"s":0.682,"o":{"i":"법무사2023_29-01-1","t":"경개계약은 신채권을 성립시키고 구채권을 소멸시키는 처분행위로서 신채권이 성립되면 그 효과는 완결되고 경개계약 자체의 이행의 문제는 발생할 여지가 없으므로 경개에 의하여 성립된 신채무의 불이행을 이유로 경개계약을 해제할 수는 없다.","y":2023,"e":"법무사 1차"},"x":{"i":"법무사2022_28-04-4","t":"경개계약은 신채권을 성립시키고 구채권을 소멸시키는 처분행위로서 신채권이 성립되면 그 효과는 완결되고 경개계약 자체의 이행의 문제는 발생할 여지가 없으므로 경개에 의하여 성립된 신채무의 불이행을 이유로 경개계약을 해제할 수는 없고, 경개계약의 성립 후에 그 계약을 합의해제하여 구채권을 부활시키는 것은 당사자 사이에서도 불가능하다.","y":2022,"e":"법무사 1차"}}];
